--
-- Name: require_order_cancellation_execution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_order_cancellation_execution() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    order_matches BOOLEAN;
    active_hold_count BIGINT;
    active_reservation_count BIGINT;
    active_allocation_count BIGINT;
    released_hold_count BIGINT;
    released_reservation_count BIGINT;
    released_allocation_count BIGINT;
    released_quantity BIGINT;
    affected_facility_ids BIGINT[];
    task_count BIGINT;
    cancelled_task_count BIGINT;
    content_count BIGINT;
    cancelled_content_count BIGINT;
    release_count BIGINT;
    confirmation_count BIGINT;
    reversed_confirmation_count BIGINT;
    container_count BIGINT;
    released_container_count BIGINT;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM public.orders order_header
        WHERE order_header.tenant_id = NEW.tenant_id
          AND order_header.inventory_owner_id = NEW.inventory_owner_id
          AND order_header.id = NEW.order_id
          AND order_header.deleted IS NULL
          AND order_header.status = 'cancelled'
          AND order_header.revision = NEW.resulting_revision
    ) INTO order_matches;

    SELECT COUNT(*) FILTER (WHERE hold.released_at IS NULL),
           COUNT(*) FILTER (WHERE hold.released_at = NEW.occurred_at)
    INTO active_hold_count, released_hold_count
    FROM public.order_holds hold
    WHERE hold.tenant_id = NEW.tenant_id
      AND hold.inventory_owner_id = NEW.inventory_owner_id
      AND hold.order_id = NEW.order_id;

    SELECT COUNT(*) FILTER (
               WHERE reservation.deleted IS NULL AND reservation.status = 'active'
           ),
           COUNT(*) FILTER (
               WHERE reservation.deleted = NEW.occurred_at
                 AND reservation.status = 'cancelled'
           ),
           COALESCE(
               array_agg(DISTINCT reservation.facility_id ORDER BY reservation.facility_id)
                   FILTER (
                       WHERE reservation.deleted = NEW.occurred_at
                         AND reservation.status = 'cancelled'
                   ),
               '{}'::BIGINT[]
           )
    INTO active_reservation_count, released_reservation_count, affected_facility_ids
    FROM public.inventory_reservations reservation
    WHERE reservation.tenant_id = NEW.tenant_id
      AND reservation.inventory_owner_id = NEW.inventory_owner_id
      AND reservation.order_id = NEW.order_id;

    SELECT COUNT(*) FILTER (
               WHERE allocation.deleted IS NULL AND allocation.status = 'allocated'
           ),
           COUNT(*) FILTER (
               WHERE allocation.deleted = NEW.occurred_at
                 AND allocation.status = 'released'
           ),
           COALESCE(SUM(allocation.qty) FILTER (
               WHERE allocation.deleted = NEW.occurred_at
                 AND allocation.status = 'released'
           ), 0)::BIGINT
    INTO active_allocation_count, released_allocation_count, released_quantity
    FROM public.inventory_allocations allocation
    INNER JOIN public.inventory_reservations reservation
      ON reservation.tenant_id = allocation.tenant_id
     AND reservation.inventory_owner_id = allocation.inventory_owner_id
     AND reservation.id = allocation.reservation_id
    WHERE allocation.tenant_id = NEW.tenant_id
      AND allocation.inventory_owner_id = NEW.inventory_owner_id
      AND reservation.order_id = NEW.order_id;

    SELECT COUNT(*),
           COUNT(*) FILTER (
               WHERE task.status = 'cancelled'
                 AND task.assigned_user_id IS NULL
                 AND task.claimed_at IS NULL
                 AND task.lease_expires_at IS NULL
                 AND task.completed_at = NEW.occurred_at
           )
    INTO task_count, cancelled_task_count
    FROM public.pick_tasks task
    WHERE task.tenant_id = NEW.tenant_id
      AND task.inventory_owner_id = NEW.inventory_owner_id
      AND task.order_id = NEW.order_id;

    SELECT COUNT(*),
           COUNT(*) FILTER (
               WHERE content.state = 'cancelled'
                 AND content.completed_at = NEW.occurred_at
           )
    INTO content_count, cancelled_content_count
    FROM public.pick_task_contents content
    WHERE content.tenant_id = NEW.tenant_id
      AND content.inventory_owner_id = NEW.inventory_owner_id
      AND content.order_id = NEW.order_id;

    SELECT COUNT(*) INTO release_count
    FROM public.order_releases release
    WHERE release.tenant_id = NEW.tenant_id
      AND release.inventory_owner_id = NEW.inventory_owner_id
      AND release.order_id = NEW.order_id;

    SELECT COUNT(*), COUNT(*) FILTER (
               WHERE EXISTS (
                   SELECT 1 FROM public.pick_reversals reversal
                   WHERE reversal.tenant_id = confirmation.tenant_id
                     AND reversal.inventory_owner_id = confirmation.inventory_owner_id
                     AND reversal.pick_confirmation_id = confirmation.id
               )
           )
    INTO confirmation_count, reversed_confirmation_count
    FROM public.pick_confirmations confirmation
    WHERE confirmation.tenant_id = NEW.tenant_id
      AND confirmation.inventory_owner_id = NEW.inventory_owner_id
      AND confirmation.order_id = NEW.order_id;

    SELECT COUNT(*), COUNT(*) FILTER (
               WHERE container.released_at = NEW.occurred_at
                 AND container.released_by_user_id = NEW.actor_user_id
                 AND container.release_order_cancellation_id = NEW.id
           )
    INTO container_count, released_container_count
    FROM public.outbound_order_containers container
    WHERE container.tenant_id = NEW.tenant_id
      AND container.inventory_owner_id = NEW.inventory_owner_id
      AND container.order_id = NEW.order_id;

    IF NOT order_matches
       OR active_hold_count <> 0
       OR active_reservation_count <> 0
       OR active_allocation_count <> 0
       OR released_hold_count <> NEW.released_hold_count
       OR released_reservation_count <> NEW.released_reservation_count
       OR released_allocation_count <> NEW.released_allocation_count
       OR released_quantity <> NEW.released_quantity
       OR affected_facility_ids IS DISTINCT FROM NEW.affected_facility_ids
    THEN
        RAISE EXCEPTION 'order cancellation does not match released order commitments'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.previous_status = 'processing' THEN
        IF release_count <> 1
           OR task_count = 0
           OR task_count <> NEW.cancelled_pick_task_count
           OR cancelled_task_count <> task_count
           OR content_count <> NEW.cancelled_pick_content_count
           OR cancelled_content_count <> content_count
           OR content_count <> task_count
           OR confirmation_count <> reversed_confirmation_count
           OR reversed_confirmation_count <> NEW.reversed_pick_confirmation_count
           OR container_count <> released_container_count
           OR released_container_count <> NEW.released_outbound_container_count
           OR EXISTS (
               SELECT 1 FROM public.pick_shortages shortage
               WHERE shortage.tenant_id = NEW.tenant_id
                 AND shortage.order_id = NEW.order_id
           )
           OR EXISTS (
               SELECT 1 FROM public.packing_sessions session
               WHERE session.tenant_id = NEW.tenant_id
                 AND session.order_id = NEW.order_id
                 AND session.state <> 'abandoned'
           )
        THEN
            RAISE EXCEPTION 'processing order cancellation requires untouched or restored terminal pick work'
                USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.cancelled_pick_task_count <> 0
          OR NEW.cancelled_pick_content_count <> 0
          OR NEW.reversed_pick_confirmation_count <> 0
          OR NEW.released_outbound_container_count <> 0
          OR task_count <> 0
          OR content_count <> 0
          OR release_count <> 0
    THEN
        RAISE EXCEPTION 'unreleased order cancellation cannot contain pick work'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


CREATE FUNCTION public.require_cancelled_order_evidence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF NEW.status = 'cancelled'
       AND OLD.status IS DISTINCT FROM 'cancelled'
       AND NOT EXISTS (
           SELECT 1
           FROM public.order_cancellations cancellation
           WHERE cancellation.tenant_id = NEW.tenant_id
             AND cancellation.inventory_owner_id = NEW.inventory_owner_id
             AND cancellation.order_id = NEW.id
             AND cancellation.previous_status = OLD.status
             AND cancellation.expected_revision = OLD.revision
             AND cancellation.resulting_revision = NEW.revision
       )
    THEN
        RAISE EXCEPTION 'cancelled order requires immutable cancellation evidence'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: reject_packing_ledger_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_packing_ledger_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION '% is immutable', TG_TABLE_NAME
        USING ERRCODE = '55000';
END;
$$;


--
-- Name: guard_outbound_order_container_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_outbound_order_container_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'outbound container assignments cannot be deleted'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM OLD.facility_id
       OR NEW.order_release_id IS DISTINCT FROM OLD.order_release_id
       OR NEW.order_id IS DISTINCT FROM OLD.order_id
       OR NEW.destination_location_id IS DISTINCT FROM OLD.destination_location_id
       OR NEW.license_plate_id IS DISTINCT FROM OLD.license_plate_id
       OR NEW.created_by_user_id IS DISTINCT FROM OLD.created_by_user_id
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR OLD.released_at IS NOT NULL
       OR NEW.released_at IS NULL
       OR NEW.released_by_user_id IS NULL
       OR NEW.release_order_cancellation_id IS NULL
       OR NOT EXISTS (
           SELECT 1 FROM public.order_cancellations cancellation
           WHERE cancellation.tenant_id = NEW.tenant_id
             AND cancellation.inventory_owner_id = NEW.inventory_owner_id
             AND cancellation.order_id = NEW.order_id
             AND cancellation.id = NEW.release_order_cancellation_id
             AND cancellation.actor_user_id = NEW.released_by_user_id
             AND cancellation.occurred_at = NEW.released_at
             AND cancellation.previous_status = 'processing'
       )
       OR EXISTS (
           SELECT 1 FROM public.pick_confirmations confirmation
           WHERE confirmation.tenant_id = NEW.tenant_id
             AND confirmation.inventory_owner_id = NEW.inventory_owner_id
             AND confirmation.facility_id = NEW.facility_id
             AND confirmation.order_release_id = NEW.order_release_id
             AND confirmation.order_id = NEW.order_id
             AND confirmation.destination_license_plate_id = NEW.license_plate_id
             AND NOT EXISTS (
                 SELECT 1 FROM public.pick_reversals reversal
                 WHERE reversal.tenant_id = confirmation.tenant_id
                   AND reversal.inventory_owner_id = confirmation.inventory_owner_id
                   AND reversal.pick_confirmation_id = confirmation.id
             )
       )
       OR EXISTS (
           SELECT 1 FROM public.inventory_balances balance
           WHERE balance.tenant_id = NEW.tenant_id
             AND balance.inventory_owner_id = NEW.inventory_owner_id
             AND balance.facility_id = NEW.facility_id
             AND balance.license_plate_id = NEW.license_plate_id
             AND balance.deleted IS NULL
             AND (balance.qty_on_hand <> 0 OR balance.qty_reserved <> 0
                  OR balance.qty_held <> 0)
       )
    THEN
        RAISE EXCEPTION 'outbound container release does not match a restored cancelled order'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_packing_session_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_packing_session_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM OLD.facility_id
       OR NEW.order_release_id IS DISTINCT FROM OLD.order_release_id
       OR NEW.order_id IS DISTINCT FROM OLD.order_id
       OR NEW.packing_location_id IS DISTINCT FROM OLD.packing_location_id
       OR NEW.expected_allocation_count IS DISTINCT FROM OLD.expected_allocation_count
       OR NEW.expected_qty IS DISTINCT FROM OLD.expected_qty
       OR NEW.started_by_user_id IS DISTINCT FROM OLD.started_by_user_id
       OR NEW.started_at IS DISTINCT FROM OLD.started_at
    THEN
        RAISE EXCEPTION 'packing session identity and plan are immutable'
            USING ERRCODE = '55000';
    END IF;

    IF OLD.state IN ('ready_to_manifest', 'abandoned') THEN
        RAISE EXCEPTION 'terminal packing sessions are immutable'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.state = 'open' THEN
        IF NEW.revision <> OLD.revision + 1
           OR NEW.ready_by_user_id IS NOT NULL
           OR NEW.ready_at IS NOT NULL
           OR NEW.abandonment_reason IS NOT NULL
           OR NEW.abandonment_note IS NOT NULL
           OR NEW.abandoned_by_user_id IS NOT NULL
           OR NEW.abandoned_at IS NOT NULL
        THEN
            RAISE EXCEPTION 'open packing session updates must advance revision once'
                USING ERRCODE = '55000';
        END IF;
    ELSIF NEW.state = 'ready_to_manifest' THEN
        IF OLD.state <> 'open'
           OR NEW.revision <> OLD.revision + 1
           OR NEW.ready_by_user_id IS NULL
           OR NEW.ready_at IS NULL
           OR NEW.abandonment_reason IS NOT NULL
           OR NEW.abandonment_note IS NOT NULL
           OR NEW.abandoned_by_user_id IS NOT NULL
           OR NEW.abandoned_at IS NOT NULL
        THEN
            RAISE EXCEPTION 'invalid packing session completion transition'
                USING ERRCODE = '55000';
        END IF;
    ELSIF NEW.state = 'abandoned' THEN
        IF OLD.state <> 'open'
           OR NEW.revision <> OLD.revision + 1
           OR NEW.ready_by_user_id IS NOT NULL
           OR NEW.ready_at IS NOT NULL
           OR NEW.abandonment_reason IS NULL
           OR NEW.abandoned_by_user_id IS NULL
           OR NEW.abandoned_at IS NULL
           OR NEW.abandoned_at < NEW.started_at
           OR NEW.packed_allocation_count <> 0
           OR NEW.packed_qty <> 0
           OR NEW.open_carton_count <> 0
           OR NEW.closed_carton_count <> 0
        THEN
            RAISE EXCEPTION 'invalid packing session abandonment transition'
                USING ERRCODE = '55000';
        END IF;
    ELSE
        RAISE EXCEPTION 'invalid packing session state'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_carton_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_carton_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM OLD.facility_id
       OR NEW.packing_session_id IS DISTINCT FROM OLD.packing_session_id
       OR NEW.order_release_id IS DISTINCT FROM OLD.order_release_id
       OR NEW.order_id IS DISTINCT FROM OLD.order_id
       OR NEW.packing_location_id IS DISTINCT FROM OLD.packing_location_id
       OR NEW.license_plate_id IS DISTINCT FROM OLD.license_plate_id
       OR NEW.created_by_user_id IS DISTINCT FROM OLD.created_by_user_id
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
    THEN
        RAISE EXCEPTION 'carton identity is immutable'
            USING ERRCODE = '55000';
    END IF;

    IF OLD.state <> 'open'
       OR NEW.state NOT IN ('closed', 'voided')
       OR (NEW.state = 'closed' AND (
            NEW.closed_by_user_id IS NULL
            OR NEW.closed_at IS NULL
            OR NEW.voided_by_user_id IS NOT NULL
            OR NEW.voided_at IS NOT NULL
       ))
       OR (NEW.state = 'voided' AND (
            NEW.voided_by_user_id IS NULL
            OR NEW.voided_at IS NULL
            OR NEW.closed_by_user_id IS NOT NULL
            OR NEW.closed_at IS NOT NULL
       ))
    THEN
        RAISE EXCEPTION 'cartons may only transition once from open to closed or voided'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_outbound_order_container(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_outbound_order_container() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.released_at IS NOT NULL
       OR NEW.released_by_user_id IS NOT NULL
       OR NEW.release_order_cancellation_id IS NOT NULL
    THEN
        RAISE EXCEPTION 'outbound container assignments must begin active'
            USING ERRCODE = '23514';
    END IF;

    PERFORM 1
    FROM public.license_plates plate
    WHERE plate.tenant_id = NEW.tenant_id
      AND plate.inventory_owner_id = NEW.inventory_owner_id
      AND plate.facility_id = NEW.facility_id
      AND plate.id = NEW.license_plate_id
    FOR UPDATE;

    IF NOT EXISTS (
        SELECT 1
        FROM public.order_releases release
        INNER JOIN public.orders order_header
          ON order_header.tenant_id = release.tenant_id
         AND order_header.inventory_owner_id = release.inventory_owner_id
         AND order_header.id = release.order_id
         AND order_header.deleted IS NULL
        INNER JOIN public.locations location
          ON location.tenant_id = release.tenant_id
         AND location.facility_id = release.facility_id
         AND location.id = release.destination_location_id
         AND location.deleted IS NULL
        INNER JOIN public.license_plates plate
          ON plate.tenant_id = release.tenant_id
         AND plate.inventory_owner_id = release.inventory_owner_id
         AND plate.facility_id = release.facility_id
         AND plate.id = NEW.license_plate_id
         AND plate.deleted IS NULL
        WHERE release.tenant_id = NEW.tenant_id
          AND release.inventory_owner_id = NEW.inventory_owner_id
          AND release.facility_id = NEW.facility_id
          AND release.id = NEW.order_release_id
          AND release.order_id = NEW.order_id
          AND release.destination_location_id = NEW.destination_location_id
          AND plate.location_id = NEW.destination_location_id
          AND plate.barcode IS NOT NULL
          AND btrim(plate.barcode) <> ''
          AND location.active
          AND NOT location.pickable
          AND location.barcode IS NOT NULL
          AND btrim(location.barcode) <> ''
          AND lower(location.type) IN ('staging', 'packing')
          AND order_header.status IN ('processing', 'awaiting packing')
    ) THEN
        RAISE EXCEPTION 'outbound container must match an active released order destination'
            USING ERRCODE = '23514';
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.cartons carton
        WHERE carton.tenant_id = NEW.tenant_id
          AND carton.inventory_owner_id = NEW.inventory_owner_id
          AND carton.facility_id = NEW.facility_id
          AND carton.license_plate_id = NEW.license_plate_id
    ) THEN
        RAISE EXCEPTION 'a picked outbound container cannot also be a carton'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_packing_session(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_packing_session() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.order_releases release
        INNER JOIN public.orders order_header
          ON order_header.tenant_id = release.tenant_id
         AND order_header.inventory_owner_id = release.inventory_owner_id
         AND order_header.id = release.order_id
         AND order_header.deleted IS NULL
        INNER JOIN public.locations location
          ON location.tenant_id = release.tenant_id
         AND location.facility_id = release.facility_id
         AND location.id = NEW.packing_location_id
         AND location.deleted IS NULL
        WHERE release.tenant_id = NEW.tenant_id
          AND release.inventory_owner_id = NEW.inventory_owner_id
          AND release.facility_id = NEW.facility_id
          AND release.id = NEW.order_release_id
          AND release.order_id = NEW.order_id
          AND location.active
          AND NOT location.pickable
          AND lower(location.type) = 'packing'
          AND location.barcode IS NOT NULL
          AND btrim(location.barcode) <> ''
    ) THEN
        RAISE EXCEPTION 'packing session must match a packing order and active packing location'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.state <> 'open'
       OR NEW.packed_allocation_count <> 0
       OR NEW.packed_qty <> 0
       OR NEW.open_carton_count <> 0
       OR NEW.closed_carton_count <> 0
       OR NEW.ready_by_user_id IS NOT NULL
       OR NEW.ready_at IS NOT NULL
       OR NEW.abandonment_reason IS NOT NULL
       OR NEW.abandonment_note IS NOT NULL
       OR NEW.abandoned_by_user_id IS NOT NULL
       OR NEW.abandoned_at IS NOT NULL
    THEN
        RAISE EXCEPTION 'packing sessions must begin open with empty execution counters'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: require_outbound_order_container_pick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_outbound_order_container_pick() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.pick_confirmations confirmation
        WHERE confirmation.tenant_id = NEW.tenant_id
          AND confirmation.inventory_owner_id = NEW.inventory_owner_id
          AND confirmation.facility_id = NEW.facility_id
          AND confirmation.order_release_id = NEW.order_release_id
          AND confirmation.order_id = NEW.order_id
          AND confirmation.destination_location_id = NEW.destination_location_id
          AND confirmation.destination_license_plate_id = NEW.license_plate_id
          AND confirmation.confirmed_by_user_id = NEW.created_by_user_id
          AND confirmation.confirmed_at >= NEW.created_at
          AND NOT EXISTS (
              SELECT 1 FROM public.pick_confirmations earlier
              WHERE earlier.tenant_id = confirmation.tenant_id
                AND earlier.inventory_owner_id = confirmation.inventory_owner_id
                AND earlier.facility_id = confirmation.facility_id
                AND earlier.order_release_id = confirmation.order_release_id
                AND earlier.order_id = confirmation.order_id
                AND earlier.destination_location_id = confirmation.destination_location_id
                AND earlier.destination_license_plate_id =
                    confirmation.destination_license_plate_id
                AND earlier.id < confirmation.id
          )
    ) THEN
        RAISE EXCEPTION 'outbound container must receive a confirmed pick in the same transaction'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: validate_packing_session_allocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_packing_session_allocation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.packing_sessions session
        INNER JOIN public.pick_confirmations confirmation
          ON confirmation.tenant_id = session.tenant_id
         AND confirmation.inventory_owner_id = session.inventory_owner_id
         AND confirmation.facility_id = session.facility_id
         AND confirmation.order_id = session.order_id
         AND confirmation.id = NEW.pick_confirmation_id
        INNER JOIN public.outbound_order_containers container
          ON container.tenant_id = confirmation.tenant_id
         AND container.inventory_owner_id = confirmation.inventory_owner_id
         AND container.facility_id = confirmation.facility_id
         AND container.order_release_id = confirmation.order_release_id
         AND container.order_id = confirmation.order_id
         AND container.destination_location_id = confirmation.destination_location_id
         AND container.license_plate_id = confirmation.destination_license_plate_id
         AND container.id = NEW.outbound_order_container_id
        INNER JOIN public.inventory_allocations allocation
          ON allocation.tenant_id = confirmation.tenant_id
         AND allocation.inventory_owner_id = confirmation.inventory_owner_id
         AND allocation.facility_id = confirmation.facility_id
         AND allocation.id = confirmation.destination_inventory_allocation_id
        INNER JOIN public.inventory_balances balance
          ON balance.tenant_id = allocation.tenant_id
         AND balance.inventory_owner_id = allocation.inventory_owner_id
         AND balance.facility_id = allocation.facility_id
         AND balance.id = allocation.inventory_balance_id
        WHERE session.tenant_id = NEW.tenant_id
          AND session.inventory_owner_id = NEW.inventory_owner_id
          AND session.facility_id = NEW.facility_id
          AND session.id = NEW.packing_session_id
          AND session.order_id = NEW.order_id
          AND session.state = 'open'
          AND confirmation.order_item_id = NEW.order_item_id
          AND confirmation.reservation_id = NEW.reservation_id
          AND confirmation.destination_inventory_allocation_id = NEW.source_inventory_allocation_id
          AND confirmation.destination_inventory_balance_id = NEW.source_inventory_balance_id
          AND confirmation.destination_location_id = NEW.source_location_id
          AND confirmation.destination_license_plate_id = NEW.source_license_plate_id
          AND confirmation.item_batch_id = NEW.item_batch_id
          AND confirmation.item_id = NEW.item_id
          AND confirmation.uom = NEW.uom
          AND confirmation.inventory_status = NEW.inventory_status
          AND confirmation.picked_qty = NEW.planned_qty
          AND allocation.reservation_id = NEW.reservation_id
          AND allocation.inventory_balance_id = NEW.source_inventory_balance_id
          AND allocation.location_id = NEW.source_location_id
          AND allocation.license_plate_id = NEW.source_license_plate_id
          AND allocation.item_batch_id = NEW.item_batch_id
          AND allocation.item_id = NEW.item_id
          AND allocation.uom = NEW.uom
          AND allocation.inventory_status = NEW.inventory_status
          AND allocation.qty = NEW.planned_qty
          AND allocation.status = 'allocated'
          AND allocation.execution_stage = 'staged'
          AND allocation.deleted IS NULL
          AND balance.location_id = NEW.source_location_id
          AND balance.license_plate_id = NEW.source_license_plate_id
          AND balance.item_batch_id = NEW.item_batch_id
          AND balance.item_id = NEW.item_id
          AND balance.uom = NEW.uom
          AND balance.status = NEW.inventory_status
          AND balance.qty_on_hand >= NEW.planned_qty
          AND balance.qty_reserved >= NEW.planned_qty
          AND balance.deleted IS NULL
    ) THEN
        RAISE EXCEPTION 'packing allocation snapshot does not match active confirmed pick stock'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_carton(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_carton() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM 1
    FROM public.license_plates plate
    WHERE plate.tenant_id = NEW.tenant_id
      AND plate.inventory_owner_id = NEW.inventory_owner_id
      AND plate.facility_id = NEW.facility_id
      AND plate.id = NEW.license_plate_id
    FOR UPDATE;

    IF NOT EXISTS (
        SELECT 1
        FROM public.packing_sessions session
        INNER JOIN public.locations location
          ON location.tenant_id = session.tenant_id
         AND location.facility_id = session.facility_id
         AND location.id = session.packing_location_id
         AND location.deleted IS NULL
        INNER JOIN public.license_plates plate
          ON plate.tenant_id = session.tenant_id
         AND plate.inventory_owner_id = session.inventory_owner_id
         AND plate.facility_id = session.facility_id
         AND plate.id = NEW.license_plate_id
         AND plate.deleted IS NULL
        WHERE session.tenant_id = NEW.tenant_id
          AND session.inventory_owner_id = NEW.inventory_owner_id
          AND session.facility_id = NEW.facility_id
          AND session.id = NEW.packing_session_id
          AND session.order_release_id = NEW.order_release_id
          AND session.order_id = NEW.order_id
          AND session.packing_location_id = NEW.packing_location_id
          AND session.state = 'open'
          AND plate.location_id = NEW.packing_location_id
          AND plate.barcode IS NOT NULL
          AND btrim(plate.barcode) <> ''
          AND location.active
          AND NOT location.pickable
          AND lower(location.type) = 'packing'
          AND location.barcode IS NOT NULL
          AND btrim(location.barcode) <> ''
    ) THEN
        RAISE EXCEPTION 'carton must use an empty plate at the active packing session location'
            USING ERRCODE = '23514';
    END IF;

    IF TG_OP = 'INSERT' AND (
        EXISTS (
            SELECT 1 FROM public.outbound_order_containers container
            WHERE container.tenant_id = NEW.tenant_id
              AND container.inventory_owner_id = NEW.inventory_owner_id
              AND container.facility_id = NEW.facility_id
              AND container.license_plate_id = NEW.license_plate_id
        )
        OR EXISTS (
            SELECT 1 FROM public.inventory_balances balance
            WHERE balance.tenant_id = NEW.tenant_id
              AND balance.inventory_owner_id = NEW.inventory_owner_id
              AND balance.facility_id = NEW.facility_id
              AND balance.license_plate_id = NEW.license_plate_id
              AND balance.deleted IS NULL
              AND balance.qty_on_hand > 0
        )
    ) THEN
        RAISE EXCEPTION 'carton license plate is not empty and unbound'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.state = 'closed' AND NOT EXISTS (
        SELECT 1 FROM public.carton_contents content
        INNER JOIN public.packing_allocation_positions position
          ON position.tenant_id = content.tenant_id
         AND position.inventory_owner_id = content.inventory_owner_id
         AND position.facility_id = content.facility_id
         AND position.packing_session_id = content.packing_session_id
         AND position.packing_session_allocation_id = content.packing_session_allocation_id
         AND position.current_carton_content_id = content.id
         AND position.state = 'packed'
        WHERE content.tenant_id = NEW.tenant_id
          AND content.inventory_owner_id = NEW.inventory_owner_id
          AND content.packing_session_id = NEW.packing_session_id
          AND content.carton_id = NEW.id
    ) THEN
        RAISE EXCEPTION 'an empty carton cannot be closed'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.state = 'voided' AND EXISTS (
        SELECT 1 FROM public.carton_contents content
        INNER JOIN public.packing_allocation_positions position
          ON position.tenant_id = content.tenant_id
         AND position.inventory_owner_id = content.inventory_owner_id
         AND position.facility_id = content.facility_id
         AND position.packing_session_id = content.packing_session_id
         AND position.packing_session_allocation_id = content.packing_session_allocation_id
         AND position.current_carton_content_id = content.id
         AND position.state = 'packed'
        WHERE content.tenant_id = NEW.tenant_id
          AND content.inventory_owner_id = NEW.inventory_owner_id
          AND content.packing_session_id = NEW.packing_session_id
          AND content.carton_id = NEW.id
    ) THEN
        RAISE EXCEPTION 'a nonempty carton cannot be voided'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_carton_content(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_carton_content() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.packing_session_allocations snapshot
        INNER JOIN public.packing_allocation_positions position
          ON position.tenant_id = snapshot.tenant_id
         AND position.inventory_owner_id = snapshot.inventory_owner_id
         AND position.facility_id = snapshot.facility_id
         AND position.packing_session_id = snapshot.packing_session_id
         AND position.packing_session_allocation_id = snapshot.id
        INNER JOIN public.packing_sessions session
          ON session.tenant_id = snapshot.tenant_id
         AND session.inventory_owner_id = snapshot.inventory_owner_id
         AND session.facility_id = snapshot.facility_id
         AND session.id = snapshot.packing_session_id
        INNER JOIN public.cartons carton
          ON carton.tenant_id = snapshot.tenant_id
         AND carton.inventory_owner_id = snapshot.inventory_owner_id
         AND carton.facility_id = snapshot.facility_id
         AND carton.packing_session_id = snapshot.packing_session_id
         AND carton.id = NEW.carton_id
        INNER JOIN public.inventory_allocations source_allocation
          ON source_allocation.tenant_id = snapshot.tenant_id
         AND source_allocation.inventory_owner_id = snapshot.inventory_owner_id
         AND source_allocation.id = NEW.source_inventory_allocation_id
        INNER JOIN public.inventory_allocations destination_allocation
          ON destination_allocation.tenant_id = snapshot.tenant_id
         AND destination_allocation.inventory_owner_id = snapshot.inventory_owner_id
         AND destination_allocation.id = NEW.destination_inventory_allocation_id
        INNER JOIN public.inventory_balances source_balance
          ON source_balance.tenant_id = snapshot.tenant_id
         AND source_balance.inventory_owner_id = snapshot.inventory_owner_id
         AND source_balance.id = NEW.source_inventory_balance_id
        INNER JOIN public.inventory_balances destination_balance
          ON destination_balance.tenant_id = snapshot.tenant_id
         AND destination_balance.inventory_owner_id = snapshot.inventory_owner_id
         AND destination_balance.id = NEW.destination_inventory_balance_id
        INNER JOIN public.inventory_transactions transaction
          ON transaction.tenant_id = snapshot.tenant_id
         AND transaction.inventory_owner_id = snapshot.inventory_owner_id
         AND transaction.id = NEW.inventory_transaction_id
        WHERE snapshot.tenant_id = NEW.tenant_id
          AND snapshot.inventory_owner_id = NEW.inventory_owner_id
          AND snapshot.facility_id = NEW.facility_id
          AND snapshot.id = NEW.packing_session_allocation_id
          AND snapshot.packing_session_id = NEW.packing_session_id
          AND snapshot.order_release_id = NEW.order_release_id
          AND snapshot.order_id = NEW.order_id
          AND snapshot.order_item_id = NEW.order_item_id
          AND snapshot.reservation_id = NEW.reservation_id
          AND snapshot.outbound_order_container_id = NEW.outbound_order_container_id
          AND snapshot.pick_confirmation_id = NEW.pick_confirmation_id
          AND snapshot.source_location_id = NEW.source_location_id
          AND snapshot.source_license_plate_id = NEW.source_license_plate_id
          AND snapshot.item_batch_id = NEW.item_batch_id
          AND snapshot.item_id = NEW.item_id
          AND snapshot.uom = NEW.uom
          AND snapshot.inventory_status = NEW.inventory_status
          AND snapshot.planned_qty = NEW.packed_qty
          AND position.state = 'available'
          AND position.current_carton_content_id IS NULL
          AND position.current_inventory_allocation_id = NEW.source_inventory_allocation_id
          AND position.current_inventory_balance_id = NEW.source_inventory_balance_id
          AND position.current_location_id = NEW.source_location_id
          AND position.current_license_plate_id = NEW.source_license_plate_id
          AND session.state = 'open'
          AND NEW.packed_at >= session.started_at
          AND carton.state = 'open'
          AND NEW.packed_at >= carton.created_at
          AND carton.order_release_id = NEW.order_release_id
          AND carton.order_id = NEW.order_id
          AND carton.packing_location_id = NEW.destination_location_id
          AND carton.license_plate_id = NEW.destination_license_plate_id
          AND source_allocation.reservation_id = NEW.reservation_id
          AND source_allocation.inventory_balance_id = NEW.source_inventory_balance_id
          AND source_allocation.location_id = NEW.source_location_id
          AND source_allocation.license_plate_id = NEW.source_license_plate_id
          AND source_allocation.item_batch_id = NEW.item_batch_id
          AND source_allocation.item_id = NEW.item_id
          AND source_allocation.uom = NEW.uom
          AND source_allocation.inventory_status = NEW.inventory_status
          AND source_allocation.qty = NEW.packed_qty
          AND source_allocation.status = 'fulfilled'
          AND source_allocation.execution_stage = 'staged'
          AND source_allocation.deleted = NEW.packed_at
          AND destination_allocation.reservation_id = NEW.reservation_id
          AND destination_allocation.inventory_balance_id = NEW.destination_inventory_balance_id
          AND destination_allocation.facility_id = NEW.facility_id
          AND destination_allocation.location_id = NEW.destination_location_id
          AND destination_allocation.license_plate_id = NEW.destination_license_plate_id
          AND destination_allocation.item_batch_id = NEW.item_batch_id
          AND destination_allocation.item_id = NEW.item_id
          AND destination_allocation.uom = NEW.uom
          AND destination_allocation.inventory_status = NEW.inventory_status
          AND destination_allocation.qty = NEW.packed_qty
          AND destination_allocation.status = 'allocated'
          AND destination_allocation.execution_stage = 'packed'
          AND destination_allocation.deleted IS NULL
          AND destination_allocation.created = NEW.packed_at
          AND destination_allocation.created_by = NEW.packed_by_user_id
          AND destination_allocation.allocation_run_id IS NOT DISTINCT FROM source_allocation.allocation_run_id
          AND source_balance.facility_id = NEW.facility_id
          AND source_balance.location_id = NEW.source_location_id
          AND source_balance.license_plate_id = NEW.source_license_plate_id
          AND source_balance.item_batch_id = NEW.item_batch_id
          AND source_balance.item_id = NEW.item_id
          AND source_balance.uom = NEW.uom
          AND source_balance.status = NEW.inventory_status
          AND destination_balance.facility_id = NEW.facility_id
          AND destination_balance.location_id = NEW.destination_location_id
          AND destination_balance.license_plate_id = NEW.destination_license_plate_id
          AND destination_balance.item_batch_id = NEW.item_batch_id
          AND destination_balance.item_id = NEW.item_id
          AND destination_balance.uom = NEW.uom
          AND destination_balance.status = NEW.inventory_status
          AND destination_balance.qty_on_hand >= NEW.packed_qty
          AND destination_balance.qty_reserved >= NEW.packed_qty
          AND transaction.actor_user_id = NEW.packed_by_user_id
          AND transaction.transaction_type = 'move'
          AND transaction.operation = 'packing.content.confirm.v1'
          AND transaction.reference_type = 'packing_session_allocation'
          AND transaction.reference_id = NEW.packing_session_allocation_id
    ) THEN
        RAISE EXCEPTION 'carton content does not match its snapshot and inventory movement'
            USING ERRCODE = '23514';
    END IF;

    IF (SELECT COUNT(*) FROM public.inventory_entries entry
        WHERE entry.tenant_id = NEW.tenant_id
          AND entry.inventory_owner_id = NEW.inventory_owner_id
          AND entry.transaction_id = NEW.inventory_transaction_id) <> 2
       OR NOT EXISTS (
        SELECT 1 FROM public.inventory_entries entry
        WHERE entry.tenant_id = NEW.tenant_id
          AND entry.inventory_owner_id = NEW.inventory_owner_id
          AND entry.transaction_id = NEW.inventory_transaction_id
          AND entry.facility_id = NEW.facility_id
          AND entry.location_id = NEW.source_location_id
          AND entry.license_plate_id = NEW.source_license_plate_id
          AND entry.item_batch_id = NEW.item_batch_id
          AND entry.item_id = NEW.item_id
          AND entry.uom = NEW.uom
          AND entry.status = NEW.inventory_status
          AND entry.quantity_delta = -NEW.packed_qty
       )
       OR NOT EXISTS (
        SELECT 1 FROM public.inventory_entries entry
        WHERE entry.tenant_id = NEW.tenant_id
          AND entry.inventory_owner_id = NEW.inventory_owner_id
          AND entry.transaction_id = NEW.inventory_transaction_id
          AND entry.facility_id = NEW.facility_id
          AND entry.location_id = NEW.destination_location_id
          AND entry.license_plate_id = NEW.destination_license_plate_id
          AND entry.item_batch_id = NEW.item_batch_id
          AND entry.item_id = NEW.item_id
          AND entry.uom = NEW.uom
          AND entry.status = NEW.inventory_status
          AND entry.quantity_delta = NEW.packed_qty
       )
    THEN
        RAISE EXCEPTION 'carton content inventory journal does not match the exact move'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_packing_session_consistency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_packing_session_consistency() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    session_id bigint;
    session_row public.packing_sessions%ROWTYPE;
    allocation_count bigint;
    allocation_qty bigint;
    packed_count bigint;
    packed_qty bigint;
    open_count bigint;
    closed_count bigint;
    order_status text;
    order_revision bigint;
BEGIN
    IF TG_TABLE_NAME = 'packing_sessions' THEN
        session_id := NEW.id;
    ELSE
        session_id := NEW.packing_session_id;
    END IF;

    SELECT * INTO session_row
    FROM public.packing_sessions session
    WHERE session.tenant_id = NEW.tenant_id AND session.id = session_id;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    SELECT COUNT(*), COALESCE(SUM(allocation.planned_qty), 0)::bigint
    INTO allocation_count, allocation_qty
    FROM public.packing_session_allocations allocation
    WHERE allocation.tenant_id = session_row.tenant_id
      AND allocation.packing_session_id = session_row.id;

    SELECT COUNT(*), COALESCE(SUM(allocation.planned_qty), 0)::bigint
    INTO packed_count, packed_qty
    FROM public.packing_allocation_positions position
    INNER JOIN public.packing_session_allocations allocation
      ON allocation.tenant_id = position.tenant_id
     AND allocation.inventory_owner_id = position.inventory_owner_id
     AND allocation.facility_id = position.facility_id
     AND allocation.packing_session_id = position.packing_session_id
     AND allocation.id = position.packing_session_allocation_id
    WHERE position.tenant_id = session_row.tenant_id
      AND position.packing_session_id = session_row.id
      AND position.state = 'packed';

    SELECT COUNT(*) FILTER (WHERE carton.state = 'open'),
           COUNT(*) FILTER (WHERE carton.state = 'closed')
    INTO open_count, closed_count
    FROM public.cartons carton
    WHERE carton.tenant_id = session_row.tenant_id
      AND carton.packing_session_id = session_row.id;

    SELECT status, revision INTO order_status, order_revision
    FROM public.orders order_header
    WHERE order_header.tenant_id = session_row.tenant_id
      AND order_header.inventory_owner_id = session_row.inventory_owner_id
      AND order_header.id = session_row.order_id;

    IF allocation_count <> session_row.expected_allocation_count
       OR allocation_qty <> session_row.expected_qty
       OR packed_count <> session_row.packed_allocation_count
       OR packed_qty <> session_row.packed_qty
       OR open_count <> session_row.open_carton_count
       OR closed_count <> session_row.closed_carton_count
       OR EXISTS (
           SELECT 1
           FROM public.outbound_effective_demand demand
           WHERE demand.tenant_id = session_row.tenant_id
             AND demand.inventory_owner_id = session_row.inventory_owner_id
             AND demand.order_id = session_row.order_id
             AND demand.effective_qty <> (
                 SELECT COALESCE(SUM(allocation.planned_qty), 0)::BIGINT
                 FROM public.packing_session_allocations allocation
                 WHERE allocation.tenant_id = session_row.tenant_id
                   AND allocation.inventory_owner_id = session_row.inventory_owner_id
                   AND allocation.facility_id = session_row.facility_id
                   AND allocation.packing_session_id = session_row.id
                   AND allocation.order_item_id = demand.order_item_id
             )
       )
       OR (session_row.state = 'open' AND (
            order_status IS DISTINCT FROM 'packing'
            OR order_revision IS DISTINCT FROM session_row.revision
       ))
       OR (session_row.state = 'ready_to_manifest' AND NOT (
            (order_status = 'awaiting shipment'
             AND order_revision = session_row.revision
             AND NOT EXISTS (
                 SELECT 1 FROM public.shipments shipment
                 WHERE shipment.tenant_id = session_row.tenant_id
                   AND shipment.inventory_owner_id = session_row.inventory_owner_id
                   AND shipment.facility_id = session_row.facility_id
                   AND shipment.packing_session_id = session_row.id
                   AND shipment.state <> 'cancelled'
             ))
            OR EXISTS (
                SELECT 1 FROM public.shipments shipment
                WHERE shipment.tenant_id = session_row.tenant_id
                  AND shipment.inventory_owner_id = session_row.inventory_owner_id
                  AND shipment.facility_id = session_row.facility_id
                  AND shipment.packing_session_id = session_row.id
                  AND shipment.order_release_id = session_row.order_release_id
                  AND shipment.order_id = session_row.order_id
                  AND shipment.creation_expected_order_revision = session_row.revision
                  AND shipment.creation_resulting_order_revision = session_row.revision + 1
                  AND ((shipment.state IN ('awaiting manifest', 'manifested')
                        AND order_status = 'awaiting shipment'
                        AND order_revision = shipment.creation_resulting_order_revision)
                       OR (shipment.state = 'partially departed'
                           AND order_status = 'awaiting shipment'
                           AND order_revision = shipment.creation_resulting_order_revision
                               + (shipment.revision - 2))
                       OR (shipment.state = 'departed'
                           AND order_status = 'shipped'
                           AND order_revision = shipment.creation_resulting_order_revision
                               + (shipment.revision - 2)))
            )
       ))
       OR (session_row.state = 'abandoned' AND (
            order_status IS DISTINCT FROM 'awaiting packing'
            OR order_revision IS DISTINCT FROM session_row.revision
            OR session_row.packed_allocation_count <> 0
            OR session_row.packed_qty <> 0
            OR session_row.open_carton_count <> 0
            OR session_row.closed_carton_count <> 0
            OR EXISTS (
                SELECT 1 FROM public.packing_allocation_positions position
                WHERE position.tenant_id = session_row.tenant_id
                  AND position.packing_session_id = session_row.id
                  AND position.state = 'packed'
            )
            OR EXISTS (
                SELECT 1 FROM public.cartons carton
                WHERE carton.tenant_id = session_row.tenant_id
                  AND carton.packing_session_id = session_row.id
                  AND carton.state <> 'voided'
            )
       ))
    THEN
        RAISE EXCEPTION 'packing session header, contents, cartons, and order state do not reconcile'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: reject_shipping_ledger_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_shipping_ledger_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION '% is immutable', TG_TABLE_NAME
        USING ERRCODE = '55000';
END;
$$;


--
-- Name: guard_shipment_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_shipment_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM OLD.facility_id
       OR NEW.packing_session_id IS DISTINCT FROM OLD.packing_session_id
       OR NEW.order_release_id IS DISTINCT FROM OLD.order_release_id
       OR NEW.order_id IS DISTINCT FROM OLD.order_id
       OR NEW.creation_expected_order_revision IS DISTINCT FROM OLD.creation_expected_order_revision
       OR NEW.creation_resulting_order_revision IS DISTINCT FROM OLD.creation_resulting_order_revision
       OR NEW.carton_count IS DISTINCT FROM OLD.carton_count
       OR NEW.content_count IS DISTINCT FROM OLD.content_count
       OR NEW.shipped_qty IS DISTINCT FROM OLD.shipped_qty
       OR NEW.created_by_user_id IS DISTINCT FROM OLD.created_by_user_id
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
    THEN
        RAISE EXCEPTION 'shipment identity and plan are immutable'
            USING ERRCODE = '55000';
    END IF;

    IF OLD.state = 'awaiting manifest'
       AND NEW.state = 'manifested'
       AND NEW.revision = OLD.revision + 1
       AND OLD.manifested_at IS NULL
       AND NEW.manifested_at IS NOT NULL
       AND NEW.manifested_at >= NEW.created_at
       AND NEW.departed_at IS NULL
       AND NEW.departed_carton_count = 0
       AND NEW.departed_qty = 0
       AND OLD.carrier IS NULL
       AND OLD.service IS NULL
       AND NEW.carrier IS NOT NULL
    THEN
        RETURN NEW;
    END IF;

    IF OLD.state IN ('manifested', 'partially departed')
       AND NEW.state IN ('partially departed', 'departed')
       AND NEW.revision = OLD.revision + 1
       AND NEW.carrier IS NOT DISTINCT FROM OLD.carrier
       AND NEW.service IS NOT DISTINCT FROM OLD.service
       AND NEW.manifested_at IS NOT DISTINCT FROM OLD.manifested_at
       AND NEW.departed_carton_count > OLD.departed_carton_count
       AND NEW.departed_qty > OLD.departed_qty
       AND ((NEW.state = 'partially departed'
             AND NEW.departed_at IS NULL
             AND NEW.departed_carton_count < NEW.carton_count
             AND NEW.departed_qty < NEW.shipped_qty)
            OR (NEW.state = 'departed'
                AND NEW.departed_at IS NOT NULL
                AND NEW.departed_at >= NEW.manifested_at
                AND NEW.departed_carton_count = NEW.carton_count
                AND NEW.departed_qty = NEW.shipped_qty))
    THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'invalid shipment state or revision transition'
        USING ERRCODE = '55000';
END;
$$;


--
-- Name: validate_shipment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_shipment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.state <> 'awaiting manifest'
       OR NEW.revision <> 1
       OR NEW.carrier IS NOT NULL
       OR NEW.service IS NOT NULL
       OR NEW.manifested_at IS NOT NULL
       OR NEW.departed_at IS NOT NULL
       OR NEW.departed_carton_count <> 0
       OR NEW.departed_qty <> 0
       OR NOT EXISTS (
            SELECT 1
            FROM public.packing_sessions session
            INNER JOIN public.orders order_header
              ON order_header.tenant_id = session.tenant_id
             AND order_header.inventory_owner_id = session.inventory_owner_id
             AND order_header.id = session.order_id
             AND order_header.deleted IS NULL
            WHERE session.tenant_id = NEW.tenant_id
              AND session.inventory_owner_id = NEW.inventory_owner_id
              AND session.facility_id = NEW.facility_id
              AND session.id = NEW.packing_session_id
              AND session.order_release_id = NEW.order_release_id
              AND session.order_id = NEW.order_id
              AND session.state = 'ready_to_manifest'
              AND session.closed_carton_count = NEW.carton_count
              AND session.packed_allocation_count = NEW.content_count
              AND session.packed_qty = NEW.shipped_qty
              AND NEW.creation_expected_order_revision = session.revision
              AND NEW.creation_resulting_order_revision = NEW.creation_expected_order_revision + 1
       )
    THEN
        RAISE EXCEPTION 'shipment must snapshot one ready full-order packing session'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_shipment_address_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_shipment_address_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (NEW.name IS NULL OR btrim(NEW.name) = '')
       AND (NEW.company IS NULL OR btrim(NEW.company) = '')
    THEN
        RAISE EXCEPTION 'shipping address requires a recipient or company name'
            USING ERRCODE = '23514';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.shipments shipment
        INNER JOIN public.addresses address
          ON address.tenant_id = shipment.tenant_id
         AND address.id = NEW.source_address_id
         AND address.deleted IS NULL
        LEFT JOIN public.facilities facility
          ON NEW.address_role = 'origin'
         AND facility.tenant_id = shipment.tenant_id
         AND facility.id = shipment.facility_id
         AND facility.deleted IS NULL
         AND facility.address_id = address.id
        LEFT JOIN public.orders order_header
          ON NEW.address_role = 'destination'
         AND order_header.tenant_id = shipment.tenant_id
         AND order_header.inventory_owner_id = shipment.inventory_owner_id
         AND order_header.id = shipment.order_id
         AND order_header.deleted IS NULL
         AND order_header.address_id = address.id
        WHERE shipment.tenant_id = NEW.tenant_id
          AND shipment.inventory_owner_id = NEW.inventory_owner_id
          AND shipment.facility_id = NEW.facility_id
          AND shipment.id = NEW.shipment_id
          AND ((NEW.address_role = 'origin' AND facility.id IS NOT NULL)
               OR (NEW.address_role = 'destination' AND order_header.id IS NOT NULL))
          AND NEW.name IS NOT DISTINCT FROM address.name
          AND NEW.company IS NOT DISTINCT FROM address.company
          AND NEW.line1 = address.line1
          AND NEW.line2 IS NOT DISTINCT FROM address.line2
          AND NEW.postal_code = address.postal_code
          AND NEW.country = address.country
          AND NEW.phone IS NOT DISTINCT FROM address.phone
          AND NEW.email IS NOT DISTINCT FROM address.email
          AND NEW.state IS NOT DISTINCT FROM address.state
          AND NEW.county IS NOT DISTINCT FROM address.county
          AND NEW.city = address.city
          AND NEW.territory IS NOT DISTINCT FROM address.territory
          AND NEW.district IS NOT DISTINCT FROM address.district
    ) THEN
        RAISE EXCEPTION 'shipment address snapshot must exactly copy its complete scoped source'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_shipment_carton(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_shipment_carton() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.shipments shipment
        INNER JOIN public.cartons carton
          ON carton.tenant_id = shipment.tenant_id
         AND carton.inventory_owner_id = shipment.inventory_owner_id
         AND carton.facility_id = shipment.facility_id
         AND carton.packing_session_id = shipment.packing_session_id
         AND carton.order_release_id = shipment.order_release_id
         AND carton.order_id = shipment.order_id
         AND carton.id = NEW.carton_id
        INNER JOIN public.license_plates plate
          ON plate.tenant_id = carton.tenant_id
         AND plate.inventory_owner_id = carton.inventory_owner_id
         AND plate.facility_id = carton.facility_id
         AND plate.id = carton.license_plate_id
         AND plate.deleted IS NULL
        WHERE shipment.tenant_id = NEW.tenant_id
          AND shipment.inventory_owner_id = NEW.inventory_owner_id
          AND shipment.facility_id = NEW.facility_id
          AND shipment.id = NEW.shipment_id
          AND shipment.packing_session_id = NEW.packing_session_id
          AND carton.state = 'closed'
          AND carton.license_plate_id = NEW.license_plate_id
          AND plate.location_id = carton.packing_location_id
          AND plate.barcode = NEW.carton_barcode
          AND carton.weight_g IS NOT DISTINCT FROM NEW.weight_g
          AND carton.length_mm IS NOT DISTINCT FROM NEW.length_mm
          AND carton.width_mm IS NOT DISTINCT FROM NEW.width_mm
          AND carton.height_mm IS NOT DISTINCT FROM NEW.height_mm
          AND NEW.content_count = (
              SELECT COUNT(*)
              FROM public.carton_contents content
              INNER JOIN public.packing_allocation_positions position
                ON position.tenant_id=content.tenant_id
               AND position.inventory_owner_id=content.inventory_owner_id
               AND position.facility_id=content.facility_id
               AND position.packing_session_id=content.packing_session_id
               AND position.packing_session_allocation_id=content.packing_session_allocation_id
               AND position.current_carton_content_id=content.id
               AND position.state='packed'
              WHERE content.tenant_id = carton.tenant_id
                AND content.inventory_owner_id = carton.inventory_owner_id
                AND content.packing_session_id = carton.packing_session_id
                AND content.carton_id = carton.id
          )
          AND NEW.packed_qty = (
              SELECT COALESCE(SUM(content.packed_qty), 0)::bigint
              FROM public.carton_contents content
              INNER JOIN public.packing_allocation_positions position
                ON position.tenant_id=content.tenant_id
               AND position.inventory_owner_id=content.inventory_owner_id
               AND position.facility_id=content.facility_id
               AND position.packing_session_id=content.packing_session_id
               AND position.packing_session_allocation_id=content.packing_session_allocation_id
               AND position.current_carton_content_id=content.id
               AND position.state='packed'
              WHERE content.tenant_id = carton.tenant_id
                AND content.inventory_owner_id = carton.inventory_owner_id
                AND content.packing_session_id = carton.packing_session_id
                AND content.carton_id = carton.id
          )
    ) THEN
        RAISE EXCEPTION 'shipment carton must exactly snapshot a closed carton'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_shipment_manifest(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_shipment_manifest() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.shipments shipment
        WHERE shipment.tenant_id = NEW.tenant_id
          AND shipment.inventory_owner_id = NEW.inventory_owner_id
          AND shipment.facility_id = NEW.facility_id
          AND shipment.id = NEW.shipment_id
          AND shipment.packing_session_id = NEW.packing_session_id
          AND shipment.order_release_id = NEW.order_release_id
          AND shipment.order_id = NEW.order_id
          AND shipment.state = 'manifested'
          AND shipment.revision = NEW.resulting_revision
          AND shipment.carrier = NEW.carrier
          AND shipment.service IS NOT DISTINCT FROM NEW.service
          AND shipment.carton_count = NEW.package_count
          AND shipment.manifested_at = NEW.manifested_at
          AND NEW.resulting_revision = NEW.expected_revision + 1
          AND NEW.manifested_at >= shipment.created_at
    ) THEN
        RAISE EXCEPTION 'manifest must match the shipment transition'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_shipment_manifest_package(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_shipment_manifest_package() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.shipment_manifests manifest
        INNER JOIN public.shipment_cartons shipment_carton
          ON shipment_carton.tenant_id = manifest.tenant_id
         AND shipment_carton.inventory_owner_id = manifest.inventory_owner_id
         AND shipment_carton.facility_id = manifest.facility_id
         AND shipment_carton.shipment_id = manifest.shipment_id
         AND shipment_carton.id = NEW.shipment_carton_id
        WHERE manifest.tenant_id = NEW.tenant_id
          AND manifest.inventory_owner_id = NEW.inventory_owner_id
          AND manifest.facility_id = NEW.facility_id
          AND manifest.id = NEW.manifest_id
          AND manifest.shipment_id = NEW.shipment_id
          AND manifest.carrier = NEW.carrier
          AND manifest.service IS NOT DISTINCT FROM NEW.service
          AND shipment_carton.carton_id = NEW.carton_id
          AND shipment_carton.license_plate_id = NEW.license_plate_id
          AND shipment_carton.weight_g IS NOT DISTINCT FROM NEW.weight_g
          AND shipment_carton.length_mm IS NOT DISTINCT FROM NEW.length_mm
          AND shipment_carton.width_mm IS NOT DISTINCT FROM NEW.width_mm
          AND shipment_carton.height_mm IS NOT DISTINCT FROM NEW.height_mm
          AND NEW.created_at = manifest.manifested_at
    ) THEN
        RAISE EXCEPTION 'manifest package must exactly snapshot a shipment carton'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_shipment_confirmation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_shipment_confirmation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.shipments shipment
        INNER JOIN public.shipment_manifests manifest
          ON manifest.tenant_id = shipment.tenant_id
         AND manifest.inventory_owner_id = shipment.inventory_owner_id
         AND manifest.facility_id = shipment.facility_id
         AND manifest.shipment_id = shipment.id
         AND manifest.id = NEW.manifest_id
        INNER JOIN public.orders order_header
          ON order_header.tenant_id = shipment.tenant_id
         AND order_header.inventory_owner_id = shipment.inventory_owner_id
         AND order_header.id = shipment.order_id
        INNER JOIN public.inventory_transactions transaction
          ON transaction.tenant_id = shipment.tenant_id
         AND transaction.inventory_owner_id = shipment.inventory_owner_id
         AND transaction.id = NEW.inventory_transaction_id
        WHERE shipment.tenant_id = NEW.tenant_id
          AND shipment.inventory_owner_id = NEW.inventory_owner_id
          AND shipment.facility_id = NEW.facility_id
          AND shipment.id = NEW.shipment_id
          AND shipment.packing_session_id = NEW.packing_session_id
          AND shipment.order_release_id = NEW.order_release_id
          AND shipment.order_id = NEW.order_id
          AND shipment.state = NEW.resulting_shipment_state
          AND shipment.revision = NEW.resulting_shipment_revision
          AND ((NEW.resulting_shipment_state = 'partially departed'
                AND shipment.departed_at IS NULL)
               OR (NEW.resulting_shipment_state = 'departed'
                   AND shipment.departed_at = NEW.confirmed_at))
          AND NEW.resulting_shipment_revision = NEW.expected_shipment_revision + 1
          AND order_header.status = CASE NEW.resulting_shipment_state
              WHEN 'departed' THEN 'shipped' ELSE 'awaiting shipment' END
          AND order_header.revision = NEW.resulting_order_revision
          AND NEW.resulting_order_revision = NEW.expected_order_revision + 1
          AND NEW.expected_order_revision = shipment.creation_resulting_order_revision
              + (NEW.expected_shipment_revision - 2)
          AND shipment.departed_carton_count >= NEW.carton_count
          AND shipment.departed_qty >= NEW.shipped_qty
          AND transaction.actor_user_id = NEW.confirmed_by_user_id
          AND transaction.created <= NEW.confirmed_at
          AND transaction.transaction_type = 'ship'
          AND transaction.operation = 'shipping.shipment.departure.confirm.v1'
          AND transaction.reference_type = 'shipment'
          AND transaction.reference_id = shipment.id
    ) THEN
        RAISE EXCEPTION 'shipment confirmation must match shipment, order, and journal transitions'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_shipment_confirmation_carton(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_shipment_confirmation_carton() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.shipment_confirmations confirmation
        INNER JOIN public.shipment_cartons shipment_carton
          ON shipment_carton.tenant_id = confirmation.tenant_id
         AND shipment_carton.inventory_owner_id = confirmation.inventory_owner_id
         AND shipment_carton.facility_id = confirmation.facility_id
         AND shipment_carton.shipment_id = confirmation.shipment_id
         AND shipment_carton.id = NEW.shipment_carton_id
        WHERE confirmation.tenant_id = NEW.tenant_id
          AND confirmation.inventory_owner_id = NEW.inventory_owner_id
          AND confirmation.facility_id = NEW.facility_id
          AND confirmation.shipment_id = NEW.shipment_id
          AND confirmation.id = NEW.confirmation_id
          AND confirmation.confirmed_at = NEW.departed_at
          AND shipment_carton.carton_id = NEW.carton_id
          AND shipment_carton.license_plate_id = NEW.license_plate_id
          AND shipment_carton.packed_qty = NEW.packed_qty
          AND EXISTS (
              SELECT 1
              FROM public.packed_inventory_positions position
              WHERE position.tenant_id = shipment_carton.tenant_id
                AND position.inventory_owner_id = shipment_carton.inventory_owner_id
                AND position.facility_id = shipment_carton.facility_id
                AND position.carton_id = shipment_carton.carton_id
                AND position.state = 'departed'
                AND position.departure_inventory_transaction_id = confirmation.inventory_transaction_id
                AND position.departed_at = confirmation.confirmed_at
          )
    ) THEN
        RAISE EXCEPTION 'shipment confirmation carton must exactly identify departed carton evidence'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: require_shipment_confirmation_consistency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_shipment_confirmation_consistency() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    target_confirmation_id bigint;
    confirmation_row public.shipment_confirmations%ROWTYPE;
    carton_count bigint;
    shipped_qty bigint;
BEGIN
    IF TG_TABLE_NAME = 'shipment_confirmations' THEN
        target_confirmation_id := NEW.id;
    ELSE
        target_confirmation_id := NEW.confirmation_id;
    END IF;

    SELECT * INTO confirmation_row
    FROM public.shipment_confirmations confirmation
    WHERE confirmation.tenant_id = NEW.tenant_id
      AND confirmation.id = target_confirmation_id;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    SELECT COUNT(*), COALESCE(SUM(carton.packed_qty), 0)::bigint
    INTO carton_count, shipped_qty
    FROM public.shipment_confirmation_cartons carton
    WHERE carton.tenant_id = confirmation_row.tenant_id
      AND carton.inventory_owner_id = confirmation_row.inventory_owner_id
      AND carton.facility_id = confirmation_row.facility_id
      AND carton.shipment_id = confirmation_row.shipment_id
      AND carton.confirmation_id = confirmation_row.id;

    IF carton_count <> confirmation_row.carton_count
       OR shipped_qty <> confirmation_row.shipped_qty
       OR EXISTS (
           SELECT 1
           FROM public.packed_inventory_positions position
           INNER JOIN public.shipment_confirmation_cartons carton
             ON carton.tenant_id = position.tenant_id
            AND carton.inventory_owner_id = position.inventory_owner_id
            AND carton.facility_id = position.facility_id
            AND carton.shipment_id = confirmation_row.shipment_id
            AND carton.confirmation_id = confirmation_row.id
            AND carton.carton_id = position.carton_id
           INNER JOIN public.carton_contents content
             ON content.tenant_id = position.tenant_id
            AND content.inventory_owner_id = position.inventory_owner_id
            AND content.id = position.carton_content_id
           LEFT JOIN LATERAL (
               SELECT detail.destination_inventory_allocation_id,
                      detail.destination_inventory_balance_id
               FROM public.packed_carton_move_details detail
               JOIN public.packed_carton_move_confirmations movement
                 ON movement.tenant_id = detail.tenant_id
                AND movement.inventory_owner_id = detail.inventory_owner_id
                AND movement.id = detail.move_confirmation_id
               WHERE detail.tenant_id = position.tenant_id
                 AND detail.inventory_owner_id = position.inventory_owner_id
                 AND detail.packed_position_id = position.id
               ORDER BY movement.moved_at DESC, movement.id DESC
               LIMIT 1
           ) move_detail ON TRUE
           INNER JOIN public.inventory_allocations allocation
             ON allocation.tenant_id = position.tenant_id
            AND allocation.inventory_owner_id = position.inventory_owner_id
            AND allocation.facility_id = position.facility_id
            AND allocation.id = COALESCE(
                move_detail.destination_inventory_allocation_id,
                content.destination_inventory_allocation_id)
           INNER JOIN public.inventory_balances balance
             ON balance.tenant_id = position.tenant_id
            AND balance.inventory_owner_id = position.inventory_owner_id
            AND balance.facility_id = position.facility_id
            AND balance.id = COALESCE(
                move_detail.destination_inventory_balance_id,
                content.destination_inventory_balance_id)
           INNER JOIN public.license_plates plate
             ON plate.tenant_id = carton.tenant_id
            AND plate.inventory_owner_id = carton.inventory_owner_id
            AND plate.facility_id = carton.facility_id
            AND plate.id = carton.license_plate_id
           WHERE position.state <> 'unpacked'
             AND (position.state <> 'departed'
              OR position.departure_inventory_transaction_id IS DISTINCT FROM confirmation_row.inventory_transaction_id
              OR position.departed_at IS DISTINCT FROM confirmation_row.confirmed_at
              OR allocation.status <> 'fulfilled'
              OR allocation.modified IS DISTINCT FROM confirmation_row.confirmed_at
              OR allocation.deleted IS DISTINCT FROM confirmation_row.confirmed_at
              OR balance.qty_on_hand <> 0
              OR balance.qty_reserved <> 0
              OR balance.deleted IS DISTINCT FROM confirmation_row.confirmed_at
              OR plate.location_id IS NOT NULL
              OR plate.deleted IS DISTINCT FROM confirmation_row.confirmed_at)
       )
       OR EXISTS (
           WITH expected AS (
               SELECT position.facility_id,
                      source_balance.location_id,
                      source_balance.license_plate_id,
                      position.item_batch_id, position.item_id, position.uom,
                      batch.lot, batch.expiration, batch.serial,
                      position.inventory_status AS status,
                      -SUM(position.packed_qty)::bigint AS quantity_delta
               FROM public.packed_inventory_positions position
               INNER JOIN public.shipment_confirmation_cartons carton
                 ON carton.tenant_id = position.tenant_id
                AND carton.inventory_owner_id = position.inventory_owner_id
                AND carton.facility_id = position.facility_id
                AND carton.shipment_id = confirmation_row.shipment_id
                AND carton.confirmation_id = confirmation_row.id
                AND carton.carton_id = position.carton_id
               INNER JOIN public.carton_contents content
                 ON content.tenant_id = position.tenant_id
                AND content.inventory_owner_id = position.inventory_owner_id
                AND content.id = position.carton_content_id
               LEFT JOIN LATERAL (
                   SELECT detail.destination_inventory_balance_id
                   FROM public.packed_carton_move_details detail
                   JOIN public.packed_carton_move_confirmations movement
                     ON movement.tenant_id = detail.tenant_id
                    AND movement.inventory_owner_id = detail.inventory_owner_id
                    AND movement.id = detail.move_confirmation_id
                   WHERE detail.tenant_id = position.tenant_id
                     AND detail.inventory_owner_id = position.inventory_owner_id
                     AND detail.packed_position_id = position.id
                   ORDER BY movement.moved_at DESC, movement.id DESC
                   LIMIT 1
               ) move_detail ON TRUE
               INNER JOIN public.inventory_balances source_balance
                 ON source_balance.tenant_id = position.tenant_id
                AND source_balance.inventory_owner_id = position.inventory_owner_id
                AND source_balance.facility_id = position.facility_id
                AND source_balance.id = COALESCE(
                    move_detail.destination_inventory_balance_id,
                    content.destination_inventory_balance_id)
               INNER JOIN public.item_batches batch
                 ON batch.tenant_id = position.tenant_id
                AND batch.inventory_owner_id = position.inventory_owner_id
                AND batch.id = position.item_batch_id
               WHERE position.state <> 'unpacked'
               GROUP BY position.facility_id, source_balance.location_id,
                        source_balance.license_plate_id,
                        position.item_batch_id, position.item_id, position.uom,
                        batch.lot, batch.expiration, batch.serial,
                        position.inventory_status
           ), actual AS (
               SELECT entry.facility_id, entry.location_id, entry.license_plate_id,
                      entry.item_batch_id, entry.item_id, entry.uom,
                      entry.lot, entry.expiration, entry.serial, entry.status,
                      SUM(entry.quantity_delta)::bigint AS quantity_delta
               FROM public.inventory_entries entry
               WHERE entry.tenant_id = confirmation_row.tenant_id
                 AND entry.inventory_owner_id = confirmation_row.inventory_owner_id
                 AND entry.transaction_id = confirmation_row.inventory_transaction_id
               GROUP BY entry.facility_id, entry.location_id, entry.license_plate_id,
                        entry.item_batch_id, entry.item_id, entry.uom,
                        entry.lot, entry.expiration, entry.serial, entry.status
           )
           SELECT 1
           FROM expected
           FULL OUTER JOIN actual
             ON actual.facility_id = expected.facility_id
            AND actual.location_id = expected.location_id
            AND actual.license_plate_id = expected.license_plate_id
            AND actual.item_batch_id = expected.item_batch_id
            AND actual.item_id = expected.item_id
            AND actual.uom = expected.uom
            AND actual.lot IS NOT DISTINCT FROM expected.lot
            AND actual.expiration IS NOT DISTINCT FROM expected.expiration
            AND actual.serial IS NOT DISTINCT FROM expected.serial
            AND actual.status = expected.status
           WHERE actual.quantity_delta IS DISTINCT FROM expected.quantity_delta
       )
    THEN
        RAISE EXCEPTION 'shipment confirmation does not reconcile with its carton set and journal'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: validate_shipment_consistency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_shipment_consistency() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    target_shipment_id bigint;
    shipment_row public.shipments%ROWTYPE;
    address_count bigint;
    carton_count bigint;
    content_count bigint;
    packed_qty bigint;
    closed_carton_count bigint;
    manifest_count bigint;
    package_count bigint;
    confirmation_count bigint;
    confirmation_carton_count bigint;
    confirmation_shipped_qty bigint;
    cancellation_count bigint;
    cancellation_previous_state text;
    cancellation_manifest_id bigint;
    order_status text;
    order_revision bigint;
BEGIN
    IF TG_TABLE_NAME = 'shipments' THEN
        target_shipment_id := NEW.id;
    ELSIF TG_TABLE_NAME = 'orders' THEN
        SELECT shipment.id INTO target_shipment_id
        FROM public.shipments shipment
        WHERE shipment.tenant_id = NEW.tenant_id
          AND shipment.inventory_owner_id = NEW.inventory_owner_id
          AND shipment.order_id = NEW.id
          AND shipment.state <> 'cancelled';
        IF NOT FOUND THEN
            RETURN NULL;
        END IF;
    ELSE
        target_shipment_id := NEW.shipment_id;
    END IF;

    SELECT * INTO shipment_row
    FROM public.shipments shipment
    WHERE shipment.tenant_id = NEW.tenant_id
      AND shipment.id = target_shipment_id;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    SELECT COUNT(*) INTO address_count
    FROM public.shipment_address_snapshots snapshot
    WHERE snapshot.tenant_id = shipment_row.tenant_id
      AND snapshot.inventory_owner_id = shipment_row.inventory_owner_id
      AND snapshot.facility_id = shipment_row.facility_id
      AND snapshot.shipment_id = shipment_row.id;

    SELECT COUNT(*), COALESCE(SUM(carton.content_count), 0)::bigint,
           COALESCE(SUM(carton.packed_qty), 0)::bigint
    INTO carton_count, content_count, packed_qty
    FROM public.shipment_cartons carton
    WHERE carton.tenant_id = shipment_row.tenant_id
      AND carton.inventory_owner_id = shipment_row.inventory_owner_id
      AND carton.facility_id = shipment_row.facility_id
      AND carton.shipment_id = shipment_row.id;

    SELECT COUNT(*) INTO closed_carton_count
    FROM public.cartons carton
    WHERE carton.tenant_id = shipment_row.tenant_id
      AND carton.inventory_owner_id = shipment_row.inventory_owner_id
      AND carton.facility_id = shipment_row.facility_id
      AND carton.packing_session_id = shipment_row.packing_session_id
      AND carton.state = 'closed';

    SELECT COUNT(*) INTO manifest_count
    FROM public.shipment_manifests manifest
    WHERE manifest.tenant_id = shipment_row.tenant_id
      AND manifest.inventory_owner_id = shipment_row.inventory_owner_id
      AND manifest.facility_id = shipment_row.facility_id
      AND manifest.shipment_id = shipment_row.id;

    SELECT COUNT(*) INTO package_count
    FROM public.shipment_manifest_packages package
    WHERE package.tenant_id = shipment_row.tenant_id
      AND package.inventory_owner_id = shipment_row.inventory_owner_id
      AND package.facility_id = shipment_row.facility_id
      AND package.shipment_id = shipment_row.id;

    SELECT COUNT(*) INTO confirmation_count
    FROM public.shipment_confirmations confirmation
    WHERE confirmation.tenant_id = shipment_row.tenant_id
      AND confirmation.inventory_owner_id = shipment_row.inventory_owner_id
      AND confirmation.facility_id = shipment_row.facility_id
      AND confirmation.shipment_id = shipment_row.id;

    SELECT COUNT(*), COALESCE(SUM(carton.packed_qty), 0)::bigint
    INTO confirmation_carton_count, confirmation_shipped_qty
    FROM public.shipment_confirmation_cartons carton
    WHERE carton.tenant_id = shipment_row.tenant_id
      AND carton.inventory_owner_id = shipment_row.inventory_owner_id
      AND carton.facility_id = shipment_row.facility_id
      AND carton.shipment_id = shipment_row.id;

    SELECT COUNT(*), MAX(cancellation.previous_shipment_state),
           MAX(cancellation.carrier_manifest_id)
    INTO cancellation_count, cancellation_previous_state, cancellation_manifest_id
    FROM public.shipment_cancellations cancellation
    WHERE cancellation.tenant_id = shipment_row.tenant_id
      AND cancellation.inventory_owner_id = shipment_row.inventory_owner_id
      AND cancellation.facility_id = shipment_row.facility_id
      AND cancellation.shipment_id = shipment_row.id;

    SELECT status, revision INTO order_status, order_revision
    FROM public.orders order_header
    WHERE order_header.tenant_id = shipment_row.tenant_id
      AND order_header.inventory_owner_id = shipment_row.inventory_owner_id
      AND order_header.id = shipment_row.order_id;

    IF shipment_row.state = 'cancelled' THEN
        IF address_count <> 2
           OR carton_count <> shipment_row.carton_count
           OR content_count <> shipment_row.content_count
           OR packed_qty <> shipment_row.shipped_qty
           OR confirmation_count <> 0
           OR confirmation_carton_count <> 0 OR confirmation_shipped_qty <> 0
           OR cancellation_count <> 1
           OR shipment_row.departed_carton_count <> 0 OR shipment_row.departed_qty <> 0
           OR cancellation_previous_state NOT IN ('awaiting manifest','manifested')
           OR (cancellation_previous_state = 'awaiting manifest' AND (
               cancellation_manifest_id IS NOT NULL
               OR manifest_count <> 0 OR package_count <> 0))
           OR (cancellation_previous_state = 'manifested' AND (
               cancellation_manifest_id IS NULL
               OR manifest_count <> 1
               OR package_count <> shipment_row.carton_count
               OR NOT EXISTS (
                   SELECT 1 FROM public.shipment_manifests manifest
                   WHERE manifest.tenant_id = shipment_row.tenant_id
                     AND manifest.inventory_owner_id = shipment_row.inventory_owner_id
                     AND manifest.facility_id = shipment_row.facility_id
                     AND manifest.shipment_id = shipment_row.id
                     AND manifest.id = cancellation_manifest_id)
               OR EXISTS (
                   SELECT 1 FROM public.shipment_cartons shipment_carton
                   WHERE shipment_carton.tenant_id = shipment_row.tenant_id
                     AND shipment_carton.inventory_owner_id = shipment_row.inventory_owner_id
                     AND shipment_carton.facility_id = shipment_row.facility_id
                     AND shipment_carton.shipment_id = shipment_row.id
                     AND NOT EXISTS (
                         SELECT 1 FROM public.shipment_manifest_packages package
                         WHERE package.tenant_id = shipment_carton.tenant_id
                           AND package.inventory_owner_id = shipment_carton.inventory_owner_id
                           AND package.facility_id = shipment_carton.facility_id
                           AND package.shipment_id = shipment_carton.shipment_id
                           AND package.manifest_id = cancellation_manifest_id
                           AND package.shipment_carton_id = shipment_carton.id))))
           OR NOT EXISTS (
               SELECT 1 FROM public.shipment_address_snapshots snapshot
               WHERE snapshot.tenant_id = shipment_row.tenant_id
                 AND snapshot.shipment_id = shipment_row.id
                 AND snapshot.address_role = 'origin')
           OR NOT EXISTS (
               SELECT 1 FROM public.shipment_address_snapshots snapshot
               WHERE snapshot.tenant_id = shipment_row.tenant_id
                 AND snapshot.shipment_id = shipment_row.id
                 AND snapshot.address_role = 'destination')
           OR NOT EXISTS (
               SELECT 1 FROM public.shipment_cancellations cancellation
               WHERE cancellation.tenant_id = shipment_row.tenant_id
                 AND cancellation.inventory_owner_id = shipment_row.inventory_owner_id
                 AND cancellation.facility_id = shipment_row.facility_id
                 AND cancellation.shipment_id = shipment_row.id
                 AND cancellation.attempt = shipment_row.attempt
                 AND cancellation.previous_shipment_state = cancellation_previous_state
                 AND cancellation.carrier_manifest_id IS NOT DISTINCT FROM cancellation_manifest_id
                 AND cancellation.resulting_shipment_revision = shipment_row.revision
                 AND cancellation.cancelled_by_user_id = shipment_row.cancelled_by_user_id
                 AND cancellation.cancelled_at = shipment_row.cancelled_at)
        THEN
            RAISE EXCEPTION 'cancelled shipment snapshot and evidence do not reconcile'
                USING ERRCODE = '23514';
        END IF;
        RETURN NULL;
    END IF;

    IF address_count <> 2
       OR NOT EXISTS (
           SELECT 1 FROM public.packing_sessions session
           WHERE session.tenant_id = shipment_row.tenant_id
             AND session.inventory_owner_id = shipment_row.inventory_owner_id
             AND session.facility_id = shipment_row.facility_id
             AND session.id = shipment_row.packing_session_id
             AND session.order_release_id = shipment_row.order_release_id
             AND session.order_id = shipment_row.order_id
             AND session.state = 'ready_to_manifest'
             AND session.revision = shipment_row.creation_expected_order_revision
             AND session.closed_carton_count = shipment_row.carton_count
             AND session.packed_allocation_count = shipment_row.content_count
             AND session.packed_qty = shipment_row.shipped_qty
       )
       OR NOT EXISTS (
           SELECT 1 FROM public.shipment_address_snapshots snapshot
           WHERE snapshot.tenant_id = shipment_row.tenant_id
             AND snapshot.shipment_id = shipment_row.id
             AND snapshot.address_role = 'origin'
       )
       OR NOT EXISTS (
           SELECT 1 FROM public.shipment_address_snapshots snapshot
           WHERE snapshot.tenant_id = shipment_row.tenant_id
             AND snapshot.shipment_id = shipment_row.id
             AND snapshot.address_role = 'destination'
       )
       OR carton_count <> shipment_row.carton_count
       OR content_count <> shipment_row.content_count
       OR packed_qty <> shipment_row.shipped_qty
       OR closed_carton_count <> shipment_row.carton_count
       OR EXISTS (
           SELECT 1
           FROM public.outbound_effective_demand demand
           WHERE demand.tenant_id = shipment_row.tenant_id
             AND demand.inventory_owner_id = shipment_row.inventory_owner_id
             AND demand.order_id = shipment_row.order_id
             AND demand.effective_qty <> (
                 SELECT COALESCE(SUM(content.packed_qty), 0)::BIGINT
                 FROM public.carton_contents content
                 INNER JOIN public.packing_allocation_positions position
                   ON position.tenant_id=content.tenant_id
                  AND position.inventory_owner_id=content.inventory_owner_id
                  AND position.facility_id=content.facility_id
                  AND position.packing_session_id=content.packing_session_id
                  AND position.packing_session_allocation_id=content.packing_session_allocation_id
                  AND position.current_carton_content_id=content.id
                  AND position.state='packed'
                 WHERE content.tenant_id = shipment_row.tenant_id
                   AND content.inventory_owner_id = shipment_row.inventory_owner_id
                   AND content.facility_id = shipment_row.facility_id
                   AND content.packing_session_id = shipment_row.packing_session_id
                   AND content.order_item_id = demand.order_item_id
             )
       )
       OR EXISTS (
           SELECT 1
           FROM public.inventory_reservations reservation
           WHERE reservation.tenant_id = shipment_row.tenant_id
             AND reservation.inventory_owner_id = shipment_row.inventory_owner_id
             AND reservation.facility_id = shipment_row.facility_id
             AND reservation.order_id = shipment_row.order_id
             AND reservation.qty <> (
                 SELECT COALESCE(SUM(content.packed_qty), 0)::BIGINT
                 FROM public.carton_contents content
                 INNER JOIN public.packing_allocation_positions position
                   ON position.tenant_id=content.tenant_id
                  AND position.inventory_owner_id=content.inventory_owner_id
                  AND position.facility_id=content.facility_id
                  AND position.packing_session_id=content.packing_session_id
                  AND position.packing_session_allocation_id=content.packing_session_allocation_id
                  AND position.current_carton_content_id=content.id
                  AND position.state='packed'
                 WHERE content.tenant_id = reservation.tenant_id
                   AND content.inventory_owner_id = reservation.inventory_owner_id
                   AND content.facility_id = reservation.facility_id
                   AND content.packing_session_id = shipment_row.packing_session_id
                   AND content.order_item_id = reservation.order_item_id
                   AND content.reservation_id = reservation.id
             ) + (
                 SELECT COALESCE(SUM(disposition.accepted_short_qty), 0)::BIGINT
                 FROM public.pick_short_ship_dispositions disposition
                 WHERE disposition.tenant_id = reservation.tenant_id
                   AND disposition.inventory_owner_id = reservation.inventory_owner_id
                   AND disposition.facility_id = reservation.facility_id
                   AND disposition.order_id = reservation.order_id
                   AND disposition.order_item_id = reservation.order_item_id
                   AND disposition.reservation_id = reservation.id
             ) + (
                 SELECT COALESCE(SUM(split_line.newly_backordered_qty), 0)::BIGINT
                 FROM public.order_backorder_split_lines split_line
                 WHERE split_line.tenant_id = reservation.tenant_id
                   AND split_line.inventory_owner_id = reservation.inventory_owner_id
                   AND split_line.facility_id = reservation.facility_id
                   AND split_line.parent_order_id = reservation.order_id
                   AND split_line.parent_order_item_id = reservation.order_item_id
             ) + (
                 SELECT COALESCE(SUM(substitution.accepted_source_qty), 0)::BIGINT
                 FROM public.pick_shortage_substitutions substitution
                 WHERE substitution.tenant_id = reservation.tenant_id
                   AND substitution.inventory_owner_id = reservation.inventory_owner_id
                   AND substitution.facility_id = reservation.facility_id
                   AND substitution.order_id = reservation.order_id
                   AND substitution.source_order_item_id = reservation.order_item_id
                   AND substitution.source_reservation_id = reservation.id
             )
       )
       OR EXISTS (
           SELECT 1 FROM public.cartons carton
           WHERE carton.tenant_id = shipment_row.tenant_id
             AND carton.inventory_owner_id = shipment_row.inventory_owner_id
             AND carton.facility_id = shipment_row.facility_id
             AND carton.packing_session_id = shipment_row.packing_session_id
             AND carton.state = 'closed'
             AND NOT EXISTS (
                 SELECT 1 FROM public.shipment_cartons shipment_carton
                 WHERE shipment_carton.tenant_id = carton.tenant_id
                   AND shipment_carton.inventory_owner_id = carton.inventory_owner_id
                   AND shipment_carton.facility_id = carton.facility_id
                   AND shipment_carton.shipment_id = shipment_row.id
                   AND shipment_carton.carton_id = carton.id
             )
       )
    THEN
        RAISE EXCEPTION 'shipment does not exactly snapshot its addresses and closed cartons'
            USING ERRCODE = '23514';
    END IF;

    IF shipment_row.state = 'awaiting manifest' THEN
        IF shipment_row.revision <> 1
           OR manifest_count <> 0 OR package_count <> 0 OR confirmation_count <> 0
           OR shipment_row.departed_carton_count <> 0 OR shipment_row.departed_qty <> 0
           OR order_status IS DISTINCT FROM 'awaiting shipment'
           OR order_revision IS DISTINCT FROM shipment_row.creation_resulting_order_revision
        THEN
            RAISE EXCEPTION 'awaiting-manifest shipment state does not reconcile'
                USING ERRCODE = '23514';
        END IF;
        RETURN NULL;
    END IF;

    IF manifest_count <> 1
       OR package_count <> shipment_row.carton_count
       OR EXISTS (
           SELECT 1 FROM public.shipment_cartons shipment_carton
           WHERE shipment_carton.tenant_id = shipment_row.tenant_id
             AND shipment_carton.inventory_owner_id = shipment_row.inventory_owner_id
             AND shipment_carton.facility_id = shipment_row.facility_id
             AND shipment_carton.shipment_id = shipment_row.id
             AND NOT EXISTS (
                 SELECT 1 FROM public.shipment_manifest_packages package
                 WHERE package.tenant_id = shipment_carton.tenant_id
                   AND package.inventory_owner_id = shipment_carton.inventory_owner_id
                   AND package.facility_id = shipment_carton.facility_id
                   AND package.shipment_id = shipment_carton.shipment_id
                   AND package.shipment_carton_id = shipment_carton.id
             )
       )
    THEN
        RAISE EXCEPTION 'shipment manifest does not contain the exact carton set'
            USING ERRCODE = '23514';
    END IF;

    IF shipment_row.state = 'manifested' THEN
        IF shipment_row.revision <> 2
           OR confirmation_count <> 0
           OR shipment_row.departed_carton_count <> 0 OR shipment_row.departed_qty <> 0
           OR order_status IS DISTINCT FROM 'awaiting shipment'
           OR order_revision IS DISTINCT FROM shipment_row.creation_resulting_order_revision
        THEN
            RAISE EXCEPTION 'manifested shipment state does not reconcile'
                USING ERRCODE = '23514';
        END IF;
        RETURN NULL;
    END IF;

    IF confirmation_count <> shipment_row.revision - 2
       OR confirmation_carton_count <> shipment_row.departed_carton_count
       OR confirmation_shipped_qty <> shipment_row.departed_qty
       OR EXISTS (
           SELECT 1
           FROM public.shipment_confirmations confirmation
           WHERE confirmation.tenant_id = shipment_row.tenant_id
             AND confirmation.inventory_owner_id = shipment_row.inventory_owner_id
             AND confirmation.facility_id = shipment_row.facility_id
             AND confirmation.shipment_id = shipment_row.id
             AND (confirmation.carton_count <> (
                     SELECT COUNT(*)
                     FROM public.shipment_confirmation_cartons carton
                     WHERE carton.tenant_id = confirmation.tenant_id
                       AND carton.inventory_owner_id = confirmation.inventory_owner_id
                       AND carton.facility_id = confirmation.facility_id
                       AND carton.shipment_id = confirmation.shipment_id
                       AND carton.confirmation_id = confirmation.id)
                  OR confirmation.shipped_qty <> (
                     SELECT COALESCE(SUM(carton.packed_qty), 0)::bigint
                     FROM public.shipment_confirmation_cartons carton
                     WHERE carton.tenant_id = confirmation.tenant_id
                       AND carton.inventory_owner_id = confirmation.inventory_owner_id
                       AND carton.facility_id = confirmation.facility_id
                       AND carton.shipment_id = confirmation.shipment_id
                       AND carton.confirmation_id = confirmation.id))
       )
    THEN
        RAISE EXCEPTION 'shipment departure confirmations do not reconcile with cumulative progress'
            USING ERRCODE = '23514';
    END IF;

    IF shipment_row.state = 'partially departed' THEN
        IF shipment_row.departed_carton_count <= 0
           OR shipment_row.departed_carton_count >= shipment_row.carton_count
           OR shipment_row.departed_qty <= 0
           OR shipment_row.departed_qty >= shipment_row.shipped_qty
           OR shipment_row.departed_at IS NOT NULL
           OR order_status IS DISTINCT FROM 'awaiting shipment'
           OR order_revision IS DISTINCT FROM shipment_row.creation_resulting_order_revision
                + confirmation_count
        THEN
            RAISE EXCEPTION 'partially-departed shipment state does not reconcile'
                USING ERRCODE = '23514';
        END IF;
        RETURN NULL;
    END IF;

    IF shipment_row.state <> 'departed'
       OR shipment_row.departed_carton_count <> shipment_row.carton_count
       OR shipment_row.departed_qty <> shipment_row.shipped_qty
       OR order_status IS DISTINCT FROM 'shipped'
       OR order_revision IS DISTINCT FROM shipment_row.creation_resulting_order_revision
            + confirmation_count
       OR EXISTS (
           SELECT 1
           FROM public.shipment_cartons shipment_carton
           INNER JOIN public.license_plates plate
             ON plate.tenant_id = shipment_carton.tenant_id
            AND plate.inventory_owner_id = shipment_carton.inventory_owner_id
            AND plate.facility_id = shipment_carton.facility_id
            AND plate.id = shipment_carton.license_plate_id
           INNER JOIN public.shipment_confirmation_cartons departed_carton
             ON departed_carton.tenant_id = shipment_carton.tenant_id
            AND departed_carton.inventory_owner_id = shipment_carton.inventory_owner_id
            AND departed_carton.facility_id = shipment_carton.facility_id
            AND departed_carton.shipment_id = shipment_carton.shipment_id
            AND departed_carton.shipment_carton_id = shipment_carton.id
           WHERE shipment_carton.tenant_id = shipment_row.tenant_id
             AND shipment_carton.inventory_owner_id = shipment_row.inventory_owner_id
             AND shipment_carton.facility_id = shipment_row.facility_id
             AND shipment_carton.shipment_id = shipment_row.id
             AND (plate.location_id IS NOT NULL
                  OR plate.deleted IS DISTINCT FROM departed_carton.departed_at)
       )
       OR EXISTS (
           SELECT 1
           FROM public.packed_inventory_positions position
           INNER JOIN public.carton_contents content
             ON content.tenant_id = position.tenant_id
            AND content.inventory_owner_id = position.inventory_owner_id
            AND content.id = position.carton_content_id
           INNER JOIN public.shipment_confirmation_cartons departed_carton
             ON departed_carton.tenant_id = position.tenant_id
            AND departed_carton.inventory_owner_id = position.inventory_owner_id
            AND departed_carton.facility_id = position.facility_id
            AND departed_carton.shipment_id = shipment_row.id
            AND departed_carton.carton_id = position.carton_id
           LEFT JOIN LATERAL (
               SELECT detail.destination_inventory_allocation_id,
                      detail.destination_inventory_balance_id
               FROM public.packed_carton_move_details detail
               JOIN public.packed_carton_move_confirmations movement
                 ON movement.tenant_id = detail.tenant_id
                AND movement.inventory_owner_id = detail.inventory_owner_id
                AND movement.id = detail.move_confirmation_id
               WHERE detail.tenant_id = position.tenant_id
                 AND detail.inventory_owner_id = position.inventory_owner_id
                 AND detail.packed_position_id = position.id
               ORDER BY movement.moved_at DESC, movement.id DESC
               LIMIT 1
           ) move_detail ON TRUE
           INNER JOIN public.inventory_allocations allocation
             ON allocation.tenant_id = position.tenant_id
            AND allocation.inventory_owner_id = position.inventory_owner_id
            AND allocation.facility_id = position.facility_id
            AND allocation.id = COALESCE(
                move_detail.destination_inventory_allocation_id,
                content.destination_inventory_allocation_id)
           INNER JOIN public.inventory_balances balance
             ON balance.tenant_id = position.tenant_id
            AND balance.inventory_owner_id = position.inventory_owner_id
            AND balance.facility_id = position.facility_id
            AND balance.id = COALESCE(
                move_detail.destination_inventory_balance_id,
                content.destination_inventory_balance_id)
           WHERE position.tenant_id = shipment_row.tenant_id
             AND position.inventory_owner_id = shipment_row.inventory_owner_id
             AND position.facility_id = shipment_row.facility_id
             AND position.state <> 'unpacked'
             AND position.carton_id IN (
                 SELECT shipment_carton.carton_id
                 FROM public.shipment_cartons shipment_carton
                 WHERE shipment_carton.tenant_id = shipment_row.tenant_id
                   AND shipment_carton.inventory_owner_id = shipment_row.inventory_owner_id
                   AND shipment_carton.shipment_id = shipment_row.id)
             AND content.packing_session_id = shipment_row.packing_session_id
             AND (allocation.status <> 'fulfilled'
                  OR allocation.modified IS DISTINCT FROM departed_carton.departed_at
                  OR allocation.deleted IS DISTINCT FROM departed_carton.departed_at
                  OR balance.qty_on_hand <> 0
                  OR balance.qty_reserved <> 0
                  OR balance.deleted IS DISTINCT FROM departed_carton.departed_at)
       )
       OR EXISTS (
           SELECT 1
           FROM public.inventory_reservations reservation
           WHERE reservation.tenant_id = shipment_row.tenant_id
             AND reservation.inventory_owner_id = shipment_row.inventory_owner_id
             AND reservation.order_id = shipment_row.order_id
             AND (reservation.status <> 'fulfilled'
                  OR reservation.modified IS DISTINCT FROM shipment_row.departed_at
                  OR reservation.deleted IS DISTINCT FROM shipment_row.departed_at)
       )
       OR EXISTS (
           WITH expected AS (
               SELECT position.facility_id,
                      source_balance.location_id,
                      source_balance.license_plate_id,
                      position.item_batch_id, position.item_id, position.uom,
                      batch.lot, batch.expiration, batch.serial,
                      position.inventory_status AS status,
                      -SUM(position.packed_qty)::bigint AS quantity_delta
               FROM public.packed_inventory_positions position
               INNER JOIN public.carton_contents content
                 ON content.tenant_id = position.tenant_id
                AND content.inventory_owner_id = position.inventory_owner_id
                AND content.id = position.carton_content_id
               LEFT JOIN LATERAL (
                   SELECT detail.destination_inventory_balance_id
                   FROM public.packed_carton_move_details detail
                   JOIN public.packed_carton_move_confirmations movement
                     ON movement.tenant_id = detail.tenant_id
                    AND movement.inventory_owner_id = detail.inventory_owner_id
                    AND movement.id = detail.move_confirmation_id
                   WHERE detail.tenant_id = position.tenant_id
                     AND detail.inventory_owner_id = position.inventory_owner_id
                     AND detail.packed_position_id = position.id
                   ORDER BY movement.moved_at DESC, movement.id DESC
                   LIMIT 1
               ) move_detail ON TRUE
               INNER JOIN public.inventory_balances source_balance
                 ON source_balance.tenant_id = position.tenant_id
                AND source_balance.inventory_owner_id = position.inventory_owner_id
                AND source_balance.facility_id = position.facility_id
                AND source_balance.id = COALESCE(
                    move_detail.destination_inventory_balance_id,
                    content.destination_inventory_balance_id)
               INNER JOIN public.item_batches batch
                 ON batch.tenant_id = position.tenant_id
                AND batch.inventory_owner_id = position.inventory_owner_id
                AND batch.id = position.item_batch_id
               WHERE position.tenant_id = shipment_row.tenant_id
                 AND position.inventory_owner_id = shipment_row.inventory_owner_id
                 AND position.facility_id = shipment_row.facility_id
                 AND position.state <> 'unpacked'
                 AND content.packing_session_id = shipment_row.packing_session_id
                 AND position.carton_id IN (
                     SELECT shipment_carton.carton_id
                     FROM public.shipment_cartons shipment_carton
                     WHERE shipment_carton.tenant_id = shipment_row.tenant_id
                       AND shipment_carton.inventory_owner_id = shipment_row.inventory_owner_id
                       AND shipment_carton.shipment_id = shipment_row.id)
               GROUP BY position.facility_id, source_balance.location_id,
                        source_balance.license_plate_id,
                        position.item_batch_id, position.item_id, position.uom,
                        batch.lot, batch.expiration, batch.serial,
                        position.inventory_status
           ), actual AS (
               SELECT entry.facility_id, entry.location_id, entry.license_plate_id,
                      entry.item_batch_id, entry.item_id, entry.uom,
                      entry.lot, entry.expiration, entry.serial, entry.status,
                      SUM(entry.quantity_delta)::bigint AS quantity_delta
               FROM public.inventory_entries entry
               INNER JOIN public.shipment_confirmations confirmation
                 ON confirmation.tenant_id = entry.tenant_id
                AND confirmation.inventory_owner_id = entry.inventory_owner_id
                AND confirmation.inventory_transaction_id = entry.transaction_id
               WHERE confirmation.tenant_id = shipment_row.tenant_id
                 AND confirmation.inventory_owner_id = shipment_row.inventory_owner_id
                 AND confirmation.facility_id = shipment_row.facility_id
                 AND confirmation.shipment_id = shipment_row.id
               GROUP BY entry.facility_id, entry.location_id, entry.license_plate_id,
                        entry.item_batch_id, entry.item_id, entry.uom,
                        entry.lot, entry.expiration, entry.serial, entry.status
           )
           SELECT 1
           FROM expected
           FULL OUTER JOIN actual
             ON actual.facility_id = expected.facility_id
            AND actual.location_id = expected.location_id
            AND actual.license_plate_id = expected.license_plate_id
            AND actual.item_batch_id = expected.item_batch_id
            AND actual.item_id = expected.item_id
            AND actual.uom = expected.uom
            AND actual.lot IS NOT DISTINCT FROM expected.lot
            AND actual.expiration IS NOT DISTINCT FROM expected.expiration
            AND actual.serial IS NOT DISTINCT FROM expected.serial
            AND actual.status = expected.status
           WHERE actual.quantity_delta IS DISTINCT FROM expected.quantity_delta
       )
    THEN
        RAISE EXCEPTION 'departed shipment does not reconcile with order, inventory, or carton departures'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: reject_order_release_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_order_release_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'order release records are immutable'
        USING ERRCODE = '55000';
END;
$$;


--
-- Name: guard_pick_task_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_pick_task_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'pick tasks are retained permanently'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM OLD.facility_id
       OR NEW.order_release_id IS DISTINCT FROM OLD.order_release_id
       OR NEW.order_id IS DISTINCT FROM OLD.order_id
       OR NEW.order_item_id IS DISTINCT FROM OLD.order_item_id
       OR NEW.reservation_id IS DISTINCT FROM OLD.reservation_id
       OR NEW.source_allocation_id IS DISTINCT FROM OLD.source_allocation_id
       OR NEW.destination_location_id IS DISTINCT FROM OLD.destination_location_id
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.priority IS DISTINCT FROM OLD.priority
       OR NEW.ship_by IS DISTINCT FROM OLD.ship_by
       OR NEW.task_timeout_seconds IS DISTINCT FROM OLD.task_timeout_seconds
    THEN
        RAISE EXCEPTION 'pick task planning dimensions are immutable'
            USING ERRCODE = '55000';
    END IF;

    IF OLD.status = 'completed' AND NEW.status = 'open' THEN
        IF NEW.assigned_user_id IS NOT NULL
           OR NEW.claimed_at IS NOT NULL
           OR NEW.lease_expires_at IS NOT NULL
           OR NEW.completed_at IS NOT NULL
           OR NEW.release_count IS DISTINCT FROM OLD.release_count
           OR NEW.last_released_at IS DISTINCT FROM OLD.last_released_at
           OR NEW.last_release_reason IS DISTINCT FROM OLD.last_release_reason
           OR NEW.last_release_note IS DISTINCT FROM OLD.last_release_note
           OR NOT EXISTS (
               SELECT 1 FROM public.pick_reversals reversal
               WHERE reversal.tenant_id = NEW.tenant_id
                 AND reversal.inventory_owner_id = NEW.inventory_owner_id
                 AND reversal.facility_id = NEW.facility_id
                 AND reversal.task_id = NEW.id
           )
        THEN
            RAISE EXCEPTION 'reopening completed pick work requires exact reversal evidence'
                USING ERRCODE = '55000';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.status IN ('completed', 'shorted', 'cancelled') THEN
        RAISE EXCEPTION 'terminal pick tasks are immutable'
            USING ERRCODE = '55000';
    END IF;

    IF OLD.status = 'open' AND NEW.status = 'in_progress' THEN
        IF NEW.release_count IS DISTINCT FROM OLD.release_count
           OR NEW.last_released_at IS DISTINCT FROM OLD.last_released_at
           OR NEW.last_release_reason IS DISTINCT FROM OLD.last_release_reason
           OR NEW.last_release_note IS DISTINCT FROM OLD.last_release_note
        THEN
            RAISE EXCEPTION 'claiming pick work cannot change release history'
                USING ERRCODE = '55000';
        END IF;
    ELSIF OLD.status = 'open' AND NEW.status = 'cancelled' THEN
        IF NEW.assigned_user_id IS NOT NULL
           OR NEW.claimed_at IS NOT NULL
           OR NEW.lease_expires_at IS NOT NULL
           OR NEW.completed_at IS NULL
           OR NEW.release_count IS DISTINCT FROM OLD.release_count
           OR NEW.last_released_at IS DISTINCT FROM OLD.last_released_at
           OR NEW.last_release_reason IS DISTINCT FROM OLD.last_release_reason
           OR NEW.last_release_note IS DISTINCT FROM OLD.last_release_note
        THEN
            RAISE EXCEPTION 'cancelling pick work requires an untouched open task'
                USING ERRCODE = '55000';
        END IF;
    ELSIF OLD.status = 'in_progress' AND NEW.status = 'open' THEN
        IF NEW.release_count <> OLD.release_count + 1
           OR NEW.last_released_at IS NULL
           OR NEW.last_release_reason IS NULL
        THEN
            RAISE EXCEPTION 'releasing pick work requires release attribution'
                USING ERRCODE = '55000';
        END IF;
    ELSIF OLD.status = 'in_progress' AND NEW.status IN ('completed', 'shorted') THEN
        IF NEW.assigned_user_id IS DISTINCT FROM OLD.assigned_user_id
           OR NEW.claimed_at IS DISTINCT FROM OLD.claimed_at
           OR NEW.release_count IS DISTINCT FROM OLD.release_count
           OR NEW.last_released_at IS DISTINCT FROM OLD.last_released_at
           OR NEW.last_release_reason IS DISTINCT FROM OLD.last_release_reason
           OR NEW.last_release_note IS DISTINCT FROM OLD.last_release_note
        THEN
            RAISE EXCEPTION 'pick terminalization cannot change claim attribution'
                USING ERRCODE = '55000';
        END IF;
    ELSIF OLD.status = 'in_progress' AND NEW.status = 'in_progress' THEN
        IF NEW.assigned_user_id IS DISTINCT FROM OLD.assigned_user_id
           OR NEW.claimed_at IS DISTINCT FROM OLD.claimed_at
           OR NEW.release_count IS DISTINCT FROM OLD.release_count
           OR NEW.last_released_at IS DISTINCT FROM OLD.last_released_at
           OR NEW.last_release_reason IS DISTINCT FROM OLD.last_release_reason
           OR NEW.last_release_note IS DISTINCT FROM OLD.last_release_note
           OR NEW.completed_at IS DISTINCT FROM OLD.completed_at
           OR NEW.lease_expires_at <= OLD.lease_expires_at
        THEN
            RAISE EXCEPTION 'pick heartbeat may only extend the active lease'
                USING ERRCODE = '55000';
        END IF;
    ELSE
        RAISE EXCEPTION 'invalid pick task lifecycle transition'
            USING ERRCODE = '55000';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: guard_pick_task_content_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_pick_task_content_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'pick task contents are retained permanently'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM OLD.facility_id
       OR NEW.task_id IS DISTINCT FROM OLD.task_id
       OR NEW.order_release_id IS DISTINCT FROM OLD.order_release_id
       OR NEW.order_id IS DISTINCT FROM OLD.order_id
       OR NEW.order_item_id IS DISTINCT FROM OLD.order_item_id
       OR NEW.reservation_id IS DISTINCT FROM OLD.reservation_id
       OR NEW.source_allocation_id IS DISTINCT FROM OLD.source_allocation_id
       OR NEW.source_inventory_balance_id IS DISTINCT FROM OLD.source_inventory_balance_id
       OR NEW.source_location_id IS DISTINCT FROM OLD.source_location_id
       OR NEW.source_license_plate_id IS DISTINCT FROM OLD.source_license_plate_id
       OR NEW.item_batch_id IS DISTINCT FROM OLD.item_batch_id
       OR NEW.item_id IS DISTINCT FROM OLD.item_id
       OR NEW.uom IS DISTINCT FROM OLD.uom
       OR NEW.inventory_status IS DISTINCT FROM OLD.inventory_status
       OR NEW.planned_qty IS DISTINCT FROM OLD.planned_qty
       OR NEW.travel_sequence IS DISTINCT FROM OLD.travel_sequence
    THEN
        RAISE EXCEPTION 'pick task content snapshot is immutable'
            USING ERRCODE = '55000';
    END IF;

    IF OLD.state = 'completed' AND NEW.state = 'pending' THEN
        IF OLD.completed_at IS NULL
           OR NEW.completed_at IS NOT NULL
           OR NOT EXISTS (
               SELECT 1 FROM public.pick_reversals reversal
               WHERE reversal.tenant_id = NEW.tenant_id
                 AND reversal.inventory_owner_id = NEW.inventory_owner_id
                 AND reversal.facility_id = NEW.facility_id
                 AND reversal.pick_task_content_id = NEW.id
                 AND reversal.task_id = NEW.task_id
           )
        THEN
            RAISE EXCEPTION 'reopening completed pick content requires exact reversal evidence'
                USING ERRCODE = '55000';
        END IF;
    ELSIF OLD.state <> 'pending'
          OR NEW.state NOT IN ('completed', 'shorted', 'cancelled')
          OR OLD.completed_at IS NOT NULL
          OR NEW.completed_at IS NULL
    THEN
        RAISE EXCEPTION 'invalid pick content lifecycle transition'
            USING ERRCODE = '55000';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: reject_pick_confirmation_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_pick_confirmation_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'pick confirmations are immutable'
        USING ERRCODE = '55000';
END;
$$;


--
-- Name: reject_pick_reversal_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_pick_reversal_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'pick reversals are immutable'
        USING ERRCODE = '55000';
END;
$$;


--
-- Name: validate_pick_reversal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_pick_reversal() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    target RECORD;
    transaction_row RECORD;
BEGIN
    SELECT confirmation.inventory_owner_id,
           confirmation.facility_id,
           confirmation.task_id,
           confirmation.pick_task_content_id,
           confirmation.order_release_id,
           confirmation.order_id,
           confirmation.order_item_id,
           confirmation.reservation_id,
           confirmation.source_inventory_allocation_id,
           staged_allocation.id AS destination_inventory_allocation_id,
           confirmation.source_inventory_balance_id,
           staged_balance.id AS destination_inventory_balance_id,
           confirmation.source_location_id,
           staged_allocation.location_id AS destination_location_id,
           confirmation.source_license_plate_id,
           staged_allocation.license_plate_id AS destination_license_plate_id,
           confirmation.item_batch_id,
           confirmation.item_id,
           confirmation.uom,
           confirmation.inventory_status,
           confirmation.picked_qty,
           confirmation.confirmed_at,
           content.planned_qty,
           content.state AS content_state,
           content.completed_at AS content_completed_at,
           task.status AS task_status,
           task.completed_at AS task_completed_at,
           order_header.status AS order_status,
           order_header.revision AS order_revision,
           source_allocation.status AS source_allocation_status,
           source_allocation.deleted AS source_allocation_deleted,
           source_allocation.execution_stage AS source_execution_stage,
           staged_allocation.status AS staged_allocation_status,
           staged_allocation.deleted AS staged_allocation_deleted,
           staged_allocation.execution_stage AS staged_execution_stage,
           source_balance.qty_on_hand AS source_on_hand,
           staged_balance.qty_on_hand AS staged_on_hand,
           staged_balance.qty_reserved AS staged_reserved
    INTO target
    FROM public.pick_confirmations confirmation
    INNER JOIN public.pick_task_contents content
      ON content.tenant_id = confirmation.tenant_id
     AND content.inventory_owner_id = confirmation.inventory_owner_id
     AND content.facility_id = confirmation.facility_id
     AND content.task_id = confirmation.task_id
     AND content.id = confirmation.pick_task_content_id
    INNER JOIN public.pick_tasks task
      ON task.tenant_id = confirmation.tenant_id
     AND task.inventory_owner_id = confirmation.inventory_owner_id
     AND task.facility_id = confirmation.facility_id
     AND task.id = confirmation.task_id
    INNER JOIN public.orders order_header
      ON order_header.tenant_id = confirmation.tenant_id
     AND order_header.inventory_owner_id = confirmation.inventory_owner_id
     AND order_header.id = confirmation.order_id
    INNER JOIN public.inventory_allocations source_allocation
      ON source_allocation.tenant_id = confirmation.tenant_id
     AND source_allocation.inventory_owner_id = confirmation.inventory_owner_id
     AND source_allocation.id = confirmation.source_inventory_allocation_id
    LEFT JOIN public.packing_session_allocations pack_snapshot
      ON pack_snapshot.tenant_id = confirmation.tenant_id
     AND pack_snapshot.inventory_owner_id = confirmation.inventory_owner_id
     AND pack_snapshot.facility_id = confirmation.facility_id
     AND pack_snapshot.pick_confirmation_id = confirmation.id
    LEFT JOIN public.packing_sessions pack_session
      ON pack_session.tenant_id = pack_snapshot.tenant_id
     AND pack_session.inventory_owner_id = pack_snapshot.inventory_owner_id
     AND pack_session.facility_id = pack_snapshot.facility_id
     AND pack_session.id = pack_snapshot.packing_session_id
     AND pack_session.state = 'abandoned'
    LEFT JOIN public.packing_allocation_positions pack_position
      ON pack_position.tenant_id = pack_snapshot.tenant_id
     AND pack_position.inventory_owner_id = pack_snapshot.inventory_owner_id
     AND pack_position.facility_id = pack_snapshot.facility_id
     AND pack_position.packing_session_id = pack_snapshot.packing_session_id
     AND pack_position.packing_session_allocation_id = pack_snapshot.id
     AND pack_position.state = 'available'
     AND pack_session.id IS NOT NULL
    INNER JOIN public.inventory_allocations staged_allocation
      ON staged_allocation.tenant_id = confirmation.tenant_id
     AND staged_allocation.inventory_owner_id = confirmation.inventory_owner_id
     AND staged_allocation.id = COALESCE(
         pack_position.current_inventory_allocation_id,
         confirmation.destination_inventory_allocation_id
     )
    INNER JOIN public.inventory_balances source_balance
      ON source_balance.tenant_id = confirmation.tenant_id
     AND source_balance.inventory_owner_id = confirmation.inventory_owner_id
     AND source_balance.id = confirmation.source_inventory_balance_id
    INNER JOIN public.inventory_balances staged_balance
      ON staged_balance.tenant_id = confirmation.tenant_id
     AND staged_balance.inventory_owner_id = confirmation.inventory_owner_id
     AND staged_balance.id = staged_allocation.inventory_balance_id
    WHERE confirmation.tenant_id = NEW.tenant_id
      AND confirmation.inventory_owner_id = NEW.inventory_owner_id
      AND confirmation.id = NEW.pick_confirmation_id
    FOR UPDATE OF content, task, order_header, source_allocation,
                  staged_allocation, source_balance, staged_balance;

    IF target.task_id IS NULL THEN
        RAISE EXCEPTION 'pick confirmation does not exist'
            USING ERRCODE = '23503';
    END IF;

    IF target.inventory_owner_id IS DISTINCT FROM NEW.inventory_owner_id
       OR target.facility_id IS DISTINCT FROM NEW.facility_id
       OR target.task_id IS DISTINCT FROM NEW.task_id
       OR target.pick_task_content_id IS DISTINCT FROM NEW.pick_task_content_id
       OR target.order_release_id IS DISTINCT FROM NEW.order_release_id
       OR target.order_id IS DISTINCT FROM NEW.order_id
       OR target.order_item_id IS DISTINCT FROM NEW.order_item_id
       OR target.reservation_id IS DISTINCT FROM NEW.reservation_id
       OR target.source_inventory_allocation_id IS DISTINCT FROM NEW.source_inventory_allocation_id
       OR target.destination_inventory_allocation_id IS DISTINCT FROM NEW.staged_inventory_allocation_id
       OR target.source_inventory_balance_id IS DISTINCT FROM NEW.source_inventory_balance_id
       OR target.destination_inventory_balance_id IS DISTINCT FROM NEW.staged_inventory_balance_id
       OR target.source_location_id IS DISTINCT FROM NEW.source_location_id
       OR target.destination_location_id IS DISTINCT FROM NEW.staged_location_id
       OR target.source_license_plate_id IS DISTINCT FROM NEW.source_license_plate_id
       OR target.destination_license_plate_id IS DISTINCT FROM NEW.staged_license_plate_id
       OR target.item_batch_id IS DISTINCT FROM NEW.item_batch_id
       OR target.item_id IS DISTINCT FROM NEW.item_id
       OR target.uom IS DISTINCT FROM NEW.uom
       OR target.inventory_status IS DISTINCT FROM NEW.inventory_status
       OR target.picked_qty IS DISTINCT FROM NEW.reversed_qty
       OR target.planned_qty IS DISTINCT FROM NEW.reversed_qty
    THEN
        RAISE EXCEPTION 'pick reversal does not match the immutable confirmation'
            USING ERRCODE = '23514';
    END IF;

    IF target.order_status NOT IN ('processing', 'awaiting packing')
       OR target.order_revision IS DISTINCT FROM NEW.expected_order_revision
       OR NEW.resulting_order_revision <> NEW.expected_order_revision + 1
       OR target.content_state <> 'completed'
       OR target.content_completed_at IS DISTINCT FROM target.confirmed_at
       OR target.task_status <> 'completed'
       OR target.task_completed_at IS DISTINCT FROM target.confirmed_at
       OR target.source_allocation_status <> 'fulfilled'
       OR target.source_allocation_deleted IS DISTINCT FROM target.confirmed_at
       OR target.source_execution_stage <> 'pick_source'
       OR target.staged_allocation_status <> 'allocated'
       OR target.staged_allocation_deleted IS NOT NULL
       OR target.staged_execution_stage <> 'staged'
       OR target.staged_on_hand < NEW.reversed_qty
       OR target.staged_reserved < NEW.reversed_qty
       OR NEW.reversed_at < target.confirmed_at
    THEN
        RAISE EXCEPTION 'pick confirmation is not reversible in its current execution state'
            USING ERRCODE = '55000';
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.pick_shortages shortage
        WHERE shortage.tenant_id = NEW.tenant_id
          AND shortage.inventory_owner_id = NEW.inventory_owner_id
          AND (
              shortage.pick_confirmation_id = NEW.pick_confirmation_id
              OR shortage.pick_task_content_id = NEW.pick_task_content_id
          )
    ) THEN
        RAISE EXCEPTION 'shortage-backed picks require shortage recovery'
            USING ERRCODE = '55000';
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.packing_sessions session
        WHERE session.tenant_id = NEW.tenant_id
          AND session.inventory_owner_id = NEW.inventory_owner_id
          AND session.order_id = NEW.order_id
          AND session.state <> 'abandoned'
    ) THEN
        RAISE EXCEPTION 'pick reversal is unavailable after packing begins'
            USING ERRCODE = '55000';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.license_plates plate
        WHERE plate.tenant_id = NEW.tenant_id
          AND plate.inventory_owner_id = NEW.inventory_owner_id
          AND plate.facility_id = NEW.facility_id
          AND plate.id = NEW.staged_license_plate_id
          AND plate.location_id = NEW.staged_location_id
          AND plate.deleted IS NULL
    ) OR (
        NEW.source_license_plate_id IS NOT NULL
        AND NEW.source_license_plate_id IS DISTINCT FROM NEW.staged_license_plate_id
        AND NOT EXISTS (
            SELECT 1 FROM public.license_plates plate
            WHERE plate.tenant_id = NEW.tenant_id
              AND plate.inventory_owner_id = NEW.inventory_owner_id
              AND plate.facility_id = NEW.facility_id
              AND plate.id = NEW.source_license_plate_id
              AND plate.location_id = NEW.source_location_id
              AND plate.deleted IS NULL
        )
    ) THEN
        RAISE EXCEPTION 'pick reversal license plates are not at the recorded locations'
            USING ERRCODE = '55000';
    END IF;

    SELECT transaction.actor_user_id, transaction.transaction_type,
           transaction.reference_type, transaction.reference_id,
           transaction.operation, transaction.created
    INTO transaction_row
    FROM public.inventory_transactions transaction
    WHERE transaction.tenant_id = NEW.tenant_id
      AND transaction.inventory_owner_id = NEW.inventory_owner_id
      AND transaction.id = NEW.inventory_transaction_id;

    IF transaction_row.transaction_type IS NULL
       OR transaction_row.actor_user_id IS DISTINCT FROM NEW.reversed_by_user_id
       OR transaction_row.transaction_type <> 'move'
       OR transaction_row.reference_type <> 'pick_confirmation'
       OR transaction_row.reference_id IS DISTINCT FROM NEW.pick_confirmation_id
       OR transaction_row.operation <> 'picking.confirmation.reverse.v1'
       OR transaction_row.created IS DISTINCT FROM NEW.reversed_at
    THEN
        RAISE EXCEPTION 'pick reversal inventory transaction does not match the command'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: require_pick_reversal_consistency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_pick_reversal_consistency() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    entry_count BIGINT;
    entry_net BIGINT;
    source_entry_count BIGINT;
    staged_entry_count BIGINT;
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.orders order_header
        INNER JOIN public.pick_tasks task
          ON task.tenant_id = order_header.tenant_id
         AND task.inventory_owner_id = order_header.inventory_owner_id
         AND task.order_id = order_header.id
         AND task.id = NEW.task_id
        INNER JOIN public.pick_task_contents content
          ON content.tenant_id = task.tenant_id
         AND content.inventory_owner_id = task.inventory_owner_id
         AND content.facility_id = task.facility_id
         AND content.task_id = task.id
         AND content.id = NEW.pick_task_content_id
        INNER JOIN public.inventory_allocations source_allocation
          ON source_allocation.tenant_id = NEW.tenant_id
         AND source_allocation.inventory_owner_id = NEW.inventory_owner_id
         AND source_allocation.id = NEW.source_inventory_allocation_id
        INNER JOIN public.inventory_allocations staged_allocation
          ON staged_allocation.tenant_id = NEW.tenant_id
         AND staged_allocation.inventory_owner_id = NEW.inventory_owner_id
         AND staged_allocation.id = NEW.staged_inventory_allocation_id
        INNER JOIN public.inventory_balances source_balance
          ON source_balance.tenant_id = NEW.tenant_id
         AND source_balance.inventory_owner_id = NEW.inventory_owner_id
         AND source_balance.id = NEW.source_inventory_balance_id
        INNER JOIN public.inventory_balances staged_balance
          ON staged_balance.tenant_id = NEW.tenant_id
         AND staged_balance.inventory_owner_id = NEW.inventory_owner_id
         AND staged_balance.id = NEW.staged_inventory_balance_id
        WHERE order_header.tenant_id = NEW.tenant_id
          AND order_header.inventory_owner_id = NEW.inventory_owner_id
          AND order_header.id = NEW.order_id
          AND order_header.status = 'processing'
          AND order_header.revision = NEW.resulting_order_revision
          AND task.status = 'open'
          AND task.assigned_user_id IS NULL
          AND task.claimed_at IS NULL
          AND task.lease_expires_at IS NULL
          AND task.completed_at IS NULL
          AND content.state = 'pending'
          AND content.completed_at IS NULL
          AND source_allocation.status = 'allocated'
          AND source_allocation.deleted IS NULL
          AND source_allocation.modified IS NULL
          AND source_allocation.execution_stage = 'pick_source'
          AND source_allocation.inventory_balance_id = NEW.source_inventory_balance_id
          AND source_allocation.qty = NEW.reversed_qty
          AND staged_allocation.status = 'released'
          AND staged_allocation.deleted = NEW.reversed_at
          AND staged_allocation.modified = NEW.reversed_at
          AND staged_allocation.execution_stage = 'staged'
          AND staged_allocation.inventory_balance_id = NEW.staged_inventory_balance_id
          AND staged_allocation.qty = NEW.reversed_qty
          AND source_balance.qty_on_hand >= NEW.reversed_qty
          AND source_balance.qty_reserved >= NEW.reversed_qty
          AND staged_balance.qty_on_hand >= 0
          AND staged_balance.qty_reserved >= 0
          AND (
              NEW.source_license_plate_id IS NULL
              OR EXISTS (
                  SELECT 1 FROM public.license_plates source_plate
                  WHERE source_plate.tenant_id = NEW.tenant_id
                    AND source_plate.inventory_owner_id = NEW.inventory_owner_id
                    AND source_plate.facility_id = NEW.facility_id
                    AND source_plate.id = NEW.source_license_plate_id
                    AND source_plate.location_id = NEW.source_location_id
                    AND source_plate.deleted IS NULL
              )
          )
          AND (
              NEW.source_license_plate_id IS NOT DISTINCT FROM NEW.staged_license_plate_id
              OR EXISTS (
                  SELECT 1 FROM public.license_plates staged_plate
                  WHERE staged_plate.tenant_id = NEW.tenant_id
                    AND staged_plate.inventory_owner_id = NEW.inventory_owner_id
                    AND staged_plate.facility_id = NEW.facility_id
                    AND staged_plate.id = NEW.staged_license_plate_id
                    AND staged_plate.location_id = NEW.staged_location_id
                    AND staged_plate.deleted IS NULL
              )
          )
    ) THEN
        RAISE EXCEPTION 'pick reversal does not reconcile with reopened work or inventory projections'
            USING ERRCODE = '23514';
    END IF;

    SELECT COUNT(*), COALESCE(SUM(entry.quantity_delta), 0)::BIGINT,
           COUNT(*) FILTER (
               WHERE entry.facility_id = NEW.facility_id
                 AND entry.location_id = NEW.source_location_id
                 AND entry.license_plate_id IS NOT DISTINCT FROM NEW.source_license_plate_id
                 AND entry.item_batch_id = NEW.item_batch_id
                 AND entry.item_id = NEW.item_id
                 AND entry.uom = NEW.uom
                 AND entry.status = NEW.inventory_status
                 AND entry.quantity_delta = NEW.reversed_qty
           ),
           COUNT(*) FILTER (
               WHERE entry.facility_id = NEW.facility_id
                 AND entry.location_id = NEW.staged_location_id
                 AND entry.license_plate_id = NEW.staged_license_plate_id
                 AND entry.item_batch_id = NEW.item_batch_id
                 AND entry.item_id = NEW.item_id
                 AND entry.uom = NEW.uom
                 AND entry.status = NEW.inventory_status
                 AND entry.quantity_delta = -NEW.reversed_qty
           )
    INTO entry_count, entry_net, source_entry_count, staged_entry_count
    FROM public.inventory_entries entry
    WHERE entry.tenant_id = NEW.tenant_id
      AND entry.inventory_owner_id = NEW.inventory_owner_id
      AND entry.transaction_id = NEW.inventory_transaction_id;

    IF entry_count <> 2 OR entry_net <> 0
       OR source_entry_count <> 1 OR staged_entry_count <> 1
    THEN
        RAISE EXCEPTION 'pick reversal inventory entries do not conserve reversed quantity'
            USING ERRCODE = '23514';
    END IF;

    RETURN NULL;
END;
$$;


--
-- Name: validate_order_release(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_order_release() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    location_matches BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM public.locations location
        WHERE location.tenant_id = NEW.tenant_id
          AND location.facility_id = NEW.facility_id
          AND location.id = NEW.destination_location_id
          AND location.deleted IS NULL
          AND location.active
          AND NOT location.pickable
          AND location.barcode IS NOT NULL
          AND location.barcode = btrim(location.barcode)
          AND location.barcode <> ''
          AND lower(location.type) IN ('staging', 'packing')
    ) INTO location_matches;

    IF NOT location_matches THEN
        RAISE EXCEPTION 'order release destination must be an active scannable staging or packing location'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_order_release_allocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_order_release_allocation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    release_row RECORD;
    allocation_row RECORD;
    recovery_matches BOOLEAN;
BEGIN
    SELECT release.inventory_owner_id, release.facility_id, release.order_id
    INTO release_row
    FROM public.order_releases release
    WHERE release.tenant_id = NEW.tenant_id
      AND release.id = NEW.order_release_id;

    SELECT allocation.reservation_id, allocation.inventory_balance_id,
           allocation.facility_id, allocation.location_id,
           allocation.license_plate_id, allocation.item_batch_id,
           allocation.item_id, allocation.uom, allocation.inventory_status,
           allocation.qty, allocation.status, allocation.deleted,
           allocation.execution_stage,
           reservation.order_id, reservation.order_item_id,
           (source_location.deleted IS NULL
            AND source_location.active
            AND source_location.pickable
            AND source_location.barcode IS NOT NULL
            AND source_location.barcode = btrim(source_location.barcode)
            AND source_location.barcode <> '') AS source_is_ready
    INTO allocation_row
    FROM public.inventory_allocations allocation
    INNER JOIN public.inventory_reservations reservation
        ON reservation.tenant_id = allocation.tenant_id
       AND reservation.inventory_owner_id = allocation.inventory_owner_id
       AND reservation.id = allocation.reservation_id
    INNER JOIN public.locations source_location
        ON source_location.tenant_id = allocation.tenant_id
       AND source_location.facility_id = allocation.facility_id
       AND source_location.id = allocation.location_id
    WHERE allocation.tenant_id = NEW.tenant_id
      AND allocation.inventory_owner_id = NEW.inventory_owner_id
      AND allocation.id = NEW.allocation_id
    FOR SHARE OF allocation, reservation;

    IF release_row.order_id IS NULL OR allocation_row.order_id IS NULL THEN
        RAISE EXCEPTION 'release allocation dependencies do not exist'
            USING ERRCODE = '23503';
    END IF;

    IF NEW.inventory_owner_id IS DISTINCT FROM release_row.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM release_row.facility_id
       OR NEW.order_id IS DISTINCT FROM release_row.order_id
       OR NEW.order_id IS DISTINCT FROM allocation_row.order_id
       OR NEW.order_item_id IS DISTINCT FROM allocation_row.order_item_id
       OR NEW.reservation_id IS DISTINCT FROM allocation_row.reservation_id
       OR NEW.inventory_balance_id IS DISTINCT FROM allocation_row.inventory_balance_id
       OR NEW.source_location_id IS DISTINCT FROM allocation_row.location_id
       OR NEW.source_license_plate_id IS DISTINCT FROM allocation_row.license_plate_id
       OR NEW.item_batch_id IS DISTINCT FROM allocation_row.item_batch_id
       OR NEW.item_id IS DISTINCT FROM allocation_row.item_id
       OR NEW.uom IS DISTINCT FROM allocation_row.uom
       OR NEW.inventory_status IS DISTINCT FROM allocation_row.inventory_status
       OR NEW.planned_qty IS DISTINCT FROM allocation_row.qty
       OR NEW.facility_id IS DISTINCT FROM allocation_row.facility_id
       OR allocation_row.status <> 'allocated'
       OR allocation_row.deleted IS NOT NULL
       OR allocation_row.execution_stage <> 'pick_source'
       OR allocation_row.inventory_status <> 'available'
       OR NOT allocation_row.source_is_ready
    THEN
        RAISE EXCEPTION 'release snapshot does not match its active allocation'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.source_kind = 'shortage_recovery' THEN
        SELECT EXISTS (
            SELECT 1
            FROM public.pick_shortage_reallocation_runs run
            INNER JOIN public.pick_shortages shortage
              ON shortage.tenant_id = run.tenant_id
             AND shortage.inventory_owner_id = run.inventory_owner_id
             AND shortage.facility_id = run.facility_id
             AND shortage.order_release_id = run.order_release_id
             AND shortage.order_id = run.order_id
             AND shortage.order_item_id = run.order_item_id
             AND shortage.reservation_id = run.reservation_id
             AND shortage.id = run.pick_shortage_id
            WHERE run.tenant_id = NEW.tenant_id
              AND run.inventory_owner_id = NEW.inventory_owner_id
              AND run.facility_id = NEW.facility_id
              AND run.order_release_id = NEW.order_release_id
              AND run.order_id = NEW.order_id
              AND run.order_item_id = NEW.order_item_id
              AND run.reservation_id = NEW.reservation_id
              AND run.pick_shortage_id = NEW.pick_shortage_id
              AND run.id = NEW.pick_shortage_reallocation_run_id
        ) INTO recovery_matches;

        IF NOT recovery_matches THEN
            RAISE EXCEPTION 'shortage recovery snapshot does not match its reallocation run'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: require_order_release_execution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_order_release_execution() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    snapshot_count BIGINT;
    snapshot_qty BIGINT;
    task_count BIGINT;
    content_count BIGINT;
    final_order_matches BOOLEAN;
BEGIN
    SELECT COUNT(*), COALESCE(SUM(snapshot.planned_qty), 0)::BIGINT
    INTO snapshot_count, snapshot_qty
    FROM public.order_release_allocations snapshot
    WHERE snapshot.tenant_id = NEW.tenant_id
      AND snapshot.order_release_id = NEW.id
      AND snapshot.source_kind = 'initial';

    SELECT COUNT(*) INTO task_count
    FROM public.pick_tasks task
    INNER JOIN public.order_release_allocations snapshot
      ON snapshot.tenant_id = task.tenant_id
     AND snapshot.inventory_owner_id = task.inventory_owner_id
     AND snapshot.facility_id = task.facility_id
     AND snapshot.order_release_id = task.order_release_id
     AND snapshot.order_id = task.order_id
     AND snapshot.order_item_id = task.order_item_id
     AND snapshot.reservation_id = task.reservation_id
     AND snapshot.allocation_id = task.source_allocation_id
    WHERE task.tenant_id = NEW.tenant_id
      AND task.order_release_id = NEW.id
      AND snapshot.source_kind = 'initial';

    SELECT COUNT(*) INTO content_count
    FROM public.pick_task_contents content
    INNER JOIN public.order_release_allocations snapshot
      ON snapshot.tenant_id = content.tenant_id
     AND snapshot.inventory_owner_id = content.inventory_owner_id
     AND snapshot.facility_id = content.facility_id
     AND snapshot.order_release_id = content.order_release_id
     AND snapshot.order_id = content.order_id
     AND snapshot.order_item_id = content.order_item_id
     AND snapshot.reservation_id = content.reservation_id
     AND snapshot.allocation_id = content.source_allocation_id
    WHERE content.tenant_id = NEW.tenant_id
      AND content.order_release_id = NEW.id
      AND snapshot.source_kind = 'initial';

    SELECT EXISTS (
        SELECT 1 FROM public.orders customer_order
        WHERE customer_order.tenant_id = NEW.tenant_id
          AND customer_order.inventory_owner_id = NEW.inventory_owner_id
          AND customer_order.id = NEW.order_id
          AND customer_order.deleted IS NULL
          AND customer_order.status = 'processing'
          AND customer_order.revision = NEW.resulting_revision
    ) INTO final_order_matches;

    IF snapshot_count <> NEW.allocation_count
       OR snapshot_qty <> NEW.released_qty
       OR task_count <> NEW.pick_task_count
       OR content_count <> NEW.pick_task_count
       OR NOT final_order_matches
    THEN
        RAISE EXCEPTION 'order release execution snapshot is incomplete'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_pick_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_pick_task() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    task_matches BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM public.order_releases release
        INNER JOIN public.order_release_allocations snapshot
            ON snapshot.tenant_id = release.tenant_id
           AND snapshot.inventory_owner_id = release.inventory_owner_id
           AND snapshot.facility_id = release.facility_id
           AND snapshot.order_release_id = release.id
           AND snapshot.order_id = release.order_id
        WHERE release.tenant_id = NEW.tenant_id
          AND release.inventory_owner_id = NEW.inventory_owner_id
          AND release.facility_id = NEW.facility_id
          AND release.id = NEW.order_release_id
          AND release.order_id = NEW.order_id
          AND release.destination_location_id = NEW.destination_location_id
          AND snapshot.order_item_id = NEW.order_item_id
          AND snapshot.reservation_id = NEW.reservation_id
          AND snapshot.allocation_id = NEW.source_allocation_id
    ) INTO task_matches;

    IF NOT task_matches
       OR NEW.status <> 'open'
       OR NEW.assigned_user_id IS NOT NULL
       OR NEW.claimed_at IS NOT NULL
       OR NEW.lease_expires_at IS NOT NULL
       OR NEW.completed_at IS NOT NULL
    THEN
        RAISE EXCEPTION 'pick task does not match its release allocation'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_pick_task_content(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_pick_task_content() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    content_matches BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM public.pick_tasks task
        INNER JOIN public.order_release_allocations snapshot
            ON snapshot.tenant_id = task.tenant_id
           AND snapshot.inventory_owner_id = task.inventory_owner_id
           AND snapshot.facility_id = task.facility_id
           AND snapshot.order_release_id = task.order_release_id
           AND snapshot.order_id = task.order_id
           AND snapshot.order_item_id = task.order_item_id
           AND snapshot.reservation_id = task.reservation_id
           AND snapshot.allocation_id = task.source_allocation_id
        WHERE task.tenant_id = NEW.tenant_id
          AND task.inventory_owner_id = NEW.inventory_owner_id
          AND task.facility_id = NEW.facility_id
          AND task.id = NEW.task_id
          AND task.order_release_id = NEW.order_release_id
          AND task.order_id = NEW.order_id
          AND task.order_item_id = NEW.order_item_id
          AND task.reservation_id = NEW.reservation_id
          AND task.source_allocation_id = NEW.source_allocation_id
          AND task.status = 'open'
          AND snapshot.inventory_balance_id = NEW.source_inventory_balance_id
          AND snapshot.source_location_id = NEW.source_location_id
          AND snapshot.source_license_plate_id IS NOT DISTINCT FROM NEW.source_license_plate_id
          AND snapshot.item_batch_id = NEW.item_batch_id
          AND snapshot.item_id = NEW.item_id
          AND snapshot.uom = NEW.uom
          AND snapshot.inventory_status = NEW.inventory_status
          AND snapshot.planned_qty = NEW.planned_qty
          AND snapshot.travel_sequence = NEW.travel_sequence
    ) INTO content_matches;

    IF NOT content_matches
       OR NEW.state <> 'pending'
       OR NEW.completed_at IS NOT NULL
    THEN
        RAISE EXCEPTION 'pick content does not match its task and release snapshot'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_pick_confirmation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_pick_confirmation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    content_row RECORD;
    task_row RECORD;
    source_allocation_row RECORD;
    destination_allocation_row RECORD;
    transaction_row RECORD;
    entry_count BIGINT;
    entry_net BIGINT;
    source_entry_count BIGINT;
    destination_entry_count BIGINT;
BEGIN
    IF EXISTS (
        SELECT 1
        FROM public.pick_confirmations earlier
        WHERE earlier.tenant_id = NEW.tenant_id
          AND earlier.inventory_owner_id = NEW.inventory_owner_id
          AND (
              earlier.pick_task_content_id = NEW.pick_task_content_id
              OR earlier.source_inventory_allocation_id =
                 NEW.source_inventory_allocation_id
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.pick_reversals reversal
              WHERE reversal.tenant_id = earlier.tenant_id
                AND reversal.inventory_owner_id = earlier.inventory_owner_id
                AND reversal.pick_confirmation_id = earlier.id
          )
    ) THEN
        RAISE EXCEPTION 'pick content or source allocation already has an active confirmation'
            USING ERRCODE = '55000';
    END IF;

    SELECT content.inventory_owner_id, content.facility_id, content.task_id,
           content.order_release_id, content.order_id, content.order_item_id,
           content.reservation_id, content.source_allocation_id,
           content.source_inventory_balance_id, content.source_location_id,
           content.source_license_plate_id, content.item_batch_id,
           content.item_id, content.uom, content.inventory_status,
           content.planned_qty, content.state
    INTO content_row
    FROM public.pick_task_contents content
    WHERE content.tenant_id = NEW.tenant_id
      AND content.id = NEW.pick_task_content_id
    FOR UPDATE;

    SELECT task.status, task.assigned_user_id, task.claimed_at,
           task.lease_expires_at, task.destination_location_id
    INTO task_row
    FROM public.pick_tasks task
    WHERE task.tenant_id = NEW.tenant_id
      AND task.id = NEW.task_id
    FOR UPDATE;

    IF content_row.task_id IS NULL OR task_row.status IS NULL
       OR content_row.state <> 'pending'
       OR task_row.status <> 'in_progress'
       OR task_row.assigned_user_id IS DISTINCT FROM NEW.confirmed_by_user_id
       OR NEW.confirmed_at < task_row.claimed_at
       OR task_row.lease_expires_at <= NEW.confirmed_at
       OR task_row.destination_location_id IS DISTINCT FROM NEW.destination_location_id
    THEN
        RAISE EXCEPTION 'pick confirmation requires the current active claim'
            USING ERRCODE = '55000';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.locations location
        WHERE location.tenant_id = NEW.tenant_id
          AND location.facility_id = NEW.facility_id
          AND location.id = NEW.destination_location_id
          AND location.deleted IS NULL
          AND location.active
          AND NOT location.pickable
          AND location.barcode IS NOT NULL
          AND location.barcode = btrim(location.barcode)
          AND location.barcode <> ''
          AND lower(location.type) IN ('staging', 'packing')
    ) THEN
        RAISE EXCEPTION 'pick confirmation destination must remain an active scannable staging or packing location'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.inventory_owner_id IS DISTINCT FROM content_row.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM content_row.facility_id
       OR NEW.task_id IS DISTINCT FROM content_row.task_id
       OR NEW.order_release_id IS DISTINCT FROM content_row.order_release_id
       OR NEW.order_id IS DISTINCT FROM content_row.order_id
       OR NEW.order_item_id IS DISTINCT FROM content_row.order_item_id
       OR NEW.reservation_id IS DISTINCT FROM content_row.reservation_id
       OR NEW.source_inventory_allocation_id IS DISTINCT FROM content_row.source_allocation_id
       OR NEW.source_inventory_balance_id IS DISTINCT FROM content_row.source_inventory_balance_id
       OR NEW.source_location_id IS DISTINCT FROM content_row.source_location_id
       OR NEW.source_license_plate_id IS DISTINCT FROM content_row.source_license_plate_id
       OR NEW.item_batch_id IS DISTINCT FROM content_row.item_batch_id
       OR NEW.item_id IS DISTINCT FROM content_row.item_id
       OR NEW.uom IS DISTINCT FROM content_row.uom
       OR NEW.inventory_status IS DISTINCT FROM content_row.inventory_status
       OR NEW.picked_qty > content_row.planned_qty
    THEN
        RAISE EXCEPTION 'pick confirmation does not match its immutable content'
            USING ERRCODE = '23514';
    END IF;

    SELECT allocation.reservation_id, allocation.inventory_balance_id,
           allocation.facility_id, allocation.location_id,
           allocation.license_plate_id, allocation.item_batch_id,
           allocation.item_id, allocation.uom, allocation.inventory_status,
           allocation.qty, allocation.status, allocation.modified,
           allocation.deleted, allocation.execution_stage
    INTO source_allocation_row
    FROM public.inventory_allocations allocation
    WHERE allocation.tenant_id = NEW.tenant_id
      AND allocation.inventory_owner_id = NEW.inventory_owner_id
      AND allocation.id = NEW.source_inventory_allocation_id
    FOR SHARE;

    SELECT allocation.reservation_id, allocation.inventory_balance_id,
           allocation.facility_id, allocation.location_id,
           allocation.license_plate_id, allocation.item_batch_id,
           allocation.item_id, allocation.uom, allocation.inventory_status,
           allocation.qty, allocation.status, allocation.created,
           allocation.modified, allocation.deleted, allocation.created_by,
           allocation.execution_stage
    INTO destination_allocation_row
    FROM public.inventory_allocations allocation
    WHERE allocation.tenant_id = NEW.tenant_id
      AND allocation.inventory_owner_id = NEW.inventory_owner_id
      AND allocation.id = NEW.destination_inventory_allocation_id
    FOR SHARE;

    IF source_allocation_row.reservation_id IS NULL
       OR source_allocation_row.reservation_id IS DISTINCT FROM NEW.reservation_id
       OR source_allocation_row.inventory_balance_id IS DISTINCT FROM NEW.source_inventory_balance_id
       OR source_allocation_row.facility_id IS DISTINCT FROM NEW.facility_id
       OR source_allocation_row.location_id IS DISTINCT FROM NEW.source_location_id
       OR source_allocation_row.license_plate_id IS DISTINCT FROM NEW.source_license_plate_id
       OR source_allocation_row.item_batch_id IS DISTINCT FROM NEW.item_batch_id
       OR source_allocation_row.item_id IS DISTINCT FROM NEW.item_id
       OR source_allocation_row.uom IS DISTINCT FROM NEW.uom
       OR source_allocation_row.inventory_status IS DISTINCT FROM NEW.inventory_status
       OR source_allocation_row.qty IS DISTINCT FROM content_row.planned_qty
       OR source_allocation_row.execution_stage <> 'pick_source'
       OR (
           (NEW.picked_qty = content_row.planned_qty
            AND source_allocation_row.status <> 'fulfilled')
           OR (NEW.picked_qty < content_row.planned_qty
               AND source_allocation_row.status <> 'shorted')
       )
       OR source_allocation_row.modified IS DISTINCT FROM NEW.confirmed_at
       OR source_allocation_row.deleted IS DISTINCT FROM NEW.confirmed_at
    THEN
        RAISE EXCEPTION 'source allocation was not fulfilled by this pick'
            USING ERRCODE = '23514';
    END IF;

    IF destination_allocation_row.reservation_id IS NULL
       OR destination_allocation_row.reservation_id IS DISTINCT FROM NEW.reservation_id
       OR destination_allocation_row.inventory_balance_id IS DISTINCT FROM NEW.destination_inventory_balance_id
       OR destination_allocation_row.facility_id IS DISTINCT FROM NEW.facility_id
       OR destination_allocation_row.location_id IS DISTINCT FROM NEW.destination_location_id
       OR destination_allocation_row.license_plate_id IS DISTINCT FROM NEW.destination_license_plate_id
       OR destination_allocation_row.item_batch_id IS DISTINCT FROM NEW.item_batch_id
       OR destination_allocation_row.item_id IS DISTINCT FROM NEW.item_id
       OR destination_allocation_row.uom IS DISTINCT FROM NEW.uom
       OR destination_allocation_row.inventory_status IS DISTINCT FROM NEW.inventory_status
       OR destination_allocation_row.qty IS DISTINCT FROM NEW.picked_qty
       OR destination_allocation_row.status <> 'allocated'
       OR destination_allocation_row.execution_stage <> 'staged'
       OR destination_allocation_row.created IS DISTINCT FROM NEW.confirmed_at
       OR destination_allocation_row.modified IS NOT NULL
       OR destination_allocation_row.deleted IS NOT NULL
       OR destination_allocation_row.created_by IS DISTINCT FROM NEW.confirmed_by_user_id
    THEN
        RAISE EXCEPTION 'destination allocation does not protect picked inventory'
            USING ERRCODE = '23514';
    END IF;

    SELECT transaction.actor_user_id, transaction.transaction_type,
           transaction.reference_type, transaction.reference_id
    INTO transaction_row
    FROM public.inventory_transactions transaction
    WHERE transaction.tenant_id = NEW.tenant_id
      AND transaction.inventory_owner_id = NEW.inventory_owner_id
      AND transaction.id = NEW.inventory_transaction_id;

    IF transaction_row.transaction_type IS NULL
       OR transaction_row.actor_user_id IS DISTINCT FROM NEW.confirmed_by_user_id
       OR transaction_row.transaction_type <> 'move'
       OR transaction_row.reference_type <> 'pick_task_content'
       OR transaction_row.reference_id IS DISTINCT FROM NEW.pick_task_content_id
    THEN
        RAISE EXCEPTION 'pick inventory transaction does not match confirmation'
            USING ERRCODE = '23514';
    END IF;

    SELECT COUNT(*), COALESCE(SUM(entry.quantity_delta), 0)::BIGINT,
           COUNT(*) FILTER (WHERE entry.facility_id = NEW.facility_id
                              AND entry.item_batch_id = NEW.item_batch_id
                              AND entry.item_id = NEW.item_id
                              AND entry.uom = NEW.uom
                              AND entry.status = NEW.inventory_status
                              AND entry.location_id = NEW.source_location_id
                              AND entry.license_plate_id IS NOT DISTINCT FROM NEW.source_license_plate_id
                              AND entry.quantity_delta = -NEW.picked_qty),
           COUNT(*) FILTER (WHERE entry.facility_id = NEW.facility_id
                              AND entry.item_batch_id = NEW.item_batch_id
                              AND entry.item_id = NEW.item_id
                              AND entry.uom = NEW.uom
                              AND entry.status = NEW.inventory_status
                              AND entry.location_id = NEW.destination_location_id
                              AND entry.license_plate_id = NEW.destination_license_plate_id
                              AND entry.quantity_delta = NEW.picked_qty)
    INTO entry_count, entry_net, source_entry_count, destination_entry_count
    FROM public.inventory_entries entry
    WHERE entry.tenant_id = NEW.tenant_id
      AND entry.inventory_owner_id = NEW.inventory_owner_id
      AND entry.transaction_id = NEW.inventory_transaction_id;

    IF entry_count <> 2 OR entry_net <> 0
       OR source_entry_count <> 1 OR destination_entry_count <> 1
    THEN
        RAISE EXCEPTION 'pick inventory entries do not conserve confirmed quantity'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: require_pick_confirmation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_pick_confirmation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF NEW.state = 'completed'
       AND NOT EXISTS (
           SELECT 1 FROM public.pick_confirmations confirmation
           WHERE confirmation.tenant_id = NEW.tenant_id
             AND confirmation.pick_task_content_id = NEW.id
             AND confirmation.confirmed_at = NEW.completed_at
       )
    THEN
        RAISE EXCEPTION 'completed pick content requires an immutable confirmation'
            USING ERRCODE = '23514';
    ELSIF NEW.state = 'shorted'
       AND NOT EXISTS (
           SELECT 1 FROM public.pick_shortages shortage
           WHERE shortage.tenant_id = NEW.tenant_id
             AND shortage.inventory_owner_id = NEW.inventory_owner_id
             AND shortage.facility_id = NEW.facility_id
             AND shortage.task_id = NEW.task_id
             AND shortage.pick_task_content_id = NEW.id
             AND shortage.reported_at = NEW.completed_at
       )
    THEN
        RAISE EXCEPTION 'shorted pick content requires an immutable shortage report'
            USING ERRCODE = '23514';
    ELSIF NEW.state = 'cancelled'
       AND NOT EXISTS (
           SELECT 1 FROM public.order_cancellations cancellation
           WHERE cancellation.tenant_id = NEW.tenant_id
             AND cancellation.inventory_owner_id = NEW.inventory_owner_id
             AND cancellation.order_id = NEW.order_id
             AND cancellation.previous_status = 'processing'
             AND cancellation.occurred_at = NEW.completed_at
       )
    THEN
        RAISE EXCEPTION 'cancelled pick content requires immutable order cancellation evidence'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: require_completed_pick_content(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_completed_pick_content() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF NEW.status = 'completed'
       AND NOT EXISTS (
           SELECT 1 FROM public.pick_task_contents content
           WHERE content.tenant_id = NEW.tenant_id
             AND content.task_id = NEW.id
             AND content.state = 'completed'
             AND content.completed_at = NEW.completed_at
       )
    THEN
        RAISE EXCEPTION 'completed pick task requires completed content'
            USING ERRCODE = '23514';
    ELSIF NEW.status = 'shorted'
       AND NOT EXISTS (
           SELECT 1 FROM public.pick_task_contents content
           WHERE content.tenant_id = NEW.tenant_id
             AND content.task_id = NEW.id
             AND content.state = 'shorted'
             AND content.completed_at = NEW.completed_at
       )
    THEN
        RAISE EXCEPTION 'shorted pick task requires shorted content'
            USING ERRCODE = '23514';
    ELSIF NEW.status = 'cancelled'
       AND (
           NOT EXISTS (
               SELECT 1 FROM public.pick_task_contents content
               WHERE content.tenant_id = NEW.tenant_id
                 AND content.task_id = NEW.id
                 AND content.state = 'cancelled'
                 AND content.completed_at = NEW.completed_at
           )
           OR NOT EXISTS (
               SELECT 1 FROM public.order_cancellations cancellation
               WHERE cancellation.tenant_id = NEW.tenant_id
                 AND cancellation.inventory_owner_id = NEW.inventory_owner_id
                 AND cancellation.order_id = NEW.order_id
                 AND cancellation.previous_status = 'processing'
                 AND cancellation.occurred_at = NEW.completed_at
           )
       )
    THEN
        RAISE EXCEPTION 'cancelled pick task requires content and order cancellation evidence'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: guard_pick_shortage_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_pick_shortage_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'pick shortages are retained permanently'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM OLD.facility_id
       OR NEW.order_release_id IS DISTINCT FROM OLD.order_release_id
       OR NEW.order_id IS DISTINCT FROM OLD.order_id
       OR NEW.order_item_id IS DISTINCT FROM OLD.order_item_id
       OR NEW.reservation_id IS DISTINCT FROM OLD.reservation_id
       OR NEW.task_id IS DISTINCT FROM OLD.task_id
       OR NEW.pick_task_content_id IS DISTINCT FROM OLD.pick_task_content_id
       OR NEW.source_inventory_allocation_id IS DISTINCT FROM OLD.source_inventory_allocation_id
       OR NEW.source_inventory_balance_id IS DISTINCT FROM OLD.source_inventory_balance_id
       OR NEW.source_location_id IS DISTINCT FROM OLD.source_location_id
       OR NEW.source_license_plate_id IS DISTINCT FROM OLD.source_license_plate_id
       OR NEW.destination_location_id IS DISTINCT FROM OLD.destination_location_id
       OR NEW.item_batch_id IS DISTINCT FROM OLD.item_batch_id
       OR NEW.item_id IS DISTINCT FROM OLD.item_id
       OR NEW.uom IS DISTINCT FROM OLD.uom
       OR NEW.inventory_status IS DISTINCT FROM OLD.inventory_status
       OR NEW.planned_qty IS DISTINCT FROM OLD.planned_qty
       OR NEW.picked_qty IS DISTINCT FROM OLD.picked_qty
       OR NEW.short_qty IS DISTINCT FROM OLD.short_qty
       OR NEW.reason_code IS DISTINCT FROM OLD.reason_code
       OR NEW.note IS DISTINCT FROM OLD.note
       OR NEW.observed_item_barcode IS DISTINCT FROM OLD.observed_item_barcode
       OR NEW.observed_lot IS DISTINCT FROM OLD.observed_lot
       OR NEW.observed_serial IS DISTINCT FROM OLD.observed_serial
       OR NEW.inventory_hold_id IS DISTINCT FROM OLD.inventory_hold_id
       OR NEW.pick_confirmation_id IS DISTINCT FROM OLD.pick_confirmation_id
       OR NEW.inventory_transaction_id IS DISTINCT FROM OLD.inventory_transaction_id
       OR NEW.destination_inventory_allocation_id IS DISTINCT FROM OLD.destination_inventory_allocation_id
       OR NEW.destination_inventory_balance_id IS DISTINCT FROM OLD.destination_inventory_balance_id
       OR NEW.destination_license_plate_id IS DISTINCT FROM OLD.destination_license_plate_id
       OR NEW.reported_by_user_id IS DISTINCT FROM OLD.reported_by_user_id
       OR NEW.reported_at IS DISTINCT FROM OLD.reported_at
       OR NEW.report_previous_order_revision IS DISTINCT FROM OLD.report_previous_order_revision
       OR NEW.report_resulting_order_revision IS DISTINCT FROM OLD.report_resulting_order_revision
    THEN
        RAISE EXCEPTION 'pick shortage report facts are immutable'
            USING ERRCODE = '55000';
    END IF;

    IF OLD.status = 'resolved' THEN
        RAISE EXCEPTION 'resolved pick shortages are immutable'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.status = 'resolved'
       AND NEW.resolution IS NULL
       AND NEW.recovery_terminal_qty = NEW.short_qty
       AND NEW.reallocated_qty = NEW.short_qty
       AND NEW.remaining_to_allocate_qty = 0
       AND NEW.accepted_short_qty = 0
       AND NEW.accepted_substitute_qty = 0
    THEN
        NEW.resolution := 'recovered';
    END IF;

    IF NEW.resolution IS DISTINCT FROM OLD.resolution
       OR NEW.accepted_short_qty IS DISTINCT FROM OLD.accepted_short_qty
       OR NEW.accepted_substitute_qty IS DISTINCT FROM OLD.accepted_substitute_qty
    THEN
        IF NOT (
            OLD.status = 'awaiting_inventory'
            AND OLD.resolution IS NULL
            AND OLD.accepted_short_qty = 0
            AND OLD.accepted_substitute_qty = 0
            AND NEW.status = 'resolved'
            AND NEW.resolution = 'short_ship'
            AND NEW.accepted_short_qty = OLD.remaining_to_allocate_qty
            AND NEW.accepted_substitute_qty = 0
            AND NEW.reallocated_qty = OLD.reallocated_qty
            AND NEW.recovery_terminal_qty = OLD.recovery_terminal_qty
            AND NEW.remaining_to_allocate_qty = OLD.remaining_to_allocate_qty
        ) AND NOT (
            OLD.status = 'awaiting_inventory'
            AND OLD.resolution IS NULL
            AND OLD.accepted_short_qty = 0
            AND OLD.accepted_substitute_qty = 0
            AND NEW.status = 'resolved'
            AND NEW.resolution = 'substituted'
            AND NEW.accepted_short_qty = 0
            AND NEW.accepted_substitute_qty = OLD.remaining_to_allocate_qty
            AND NEW.reallocated_qty = OLD.reallocated_qty
            AND NEW.recovery_terminal_qty = OLD.recovery_terminal_qty
            AND NEW.remaining_to_allocate_qty = OLD.remaining_to_allocate_qty
        ) AND NOT (
            NEW.status = 'resolved'
            AND NEW.resolution = 'recovered'
            AND NEW.accepted_short_qty = 0
            AND NEW.accepted_substitute_qty = 0
            AND NEW.reallocated_qty = NEW.short_qty
            AND NEW.recovery_terminal_qty = NEW.short_qty
            AND NEW.remaining_to_allocate_qty = 0
        )
        THEN
            RAISE EXCEPTION 'invalid pick shortage resolution transition'
                USING ERRCODE = '55000';
        END IF;
    END IF;

    IF NEW.revision <> OLD.revision + 1
       OR NEW.modified_at <= OLD.modified_at
       OR NEW.reallocated_qty < OLD.reallocated_qty
       OR NEW.recovery_terminal_qty < OLD.recovery_terminal_qty
       OR NEW.remaining_to_allocate_qty > OLD.remaining_to_allocate_qty
    THEN
        RAISE EXCEPTION 'invalid pick shortage lifecycle revision'
            USING ERRCODE = '55000';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: reject_pick_short_ship_disposition_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_pick_short_ship_disposition_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'pick short-ship dispositions are immutable'
        USING ERRCODE = '55000';
END;
$$;


--
-- Name: validate_pick_short_ship_disposition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_pick_short_ship_disposition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    shortage_row public.pick_shortages%ROWTYPE;
    order_status TEXT;
    order_revision BIGINT;
    original_order_qty BIGINT;
    original_line_qty BIGINT;
    reservation_qty BIGINT;
    previously_accepted_order_qty BIGINT;
    previously_accepted_line_qty BIGINT;
    previously_accepted_reservation_qty BIGINT;
    backordered_order_qty BIGINT;
    backordered_line_qty BIGINT;
BEGIN
    SELECT order_header.status, order_header.revision
    INTO order_status, order_revision
    FROM public.orders order_header
    WHERE order_header.tenant_id = NEW.tenant_id
      AND order_header.inventory_owner_id = NEW.inventory_owner_id
      AND order_header.id = NEW.order_id
      AND order_header.deleted IS NULL
    FOR UPDATE OF order_header;

    IF order_status IS DISTINCT FROM 'processing'
       OR order_revision NOT IN (
           NEW.expected_order_revision,
           NEW.resulting_order_revision
       )
    THEN
        RAISE EXCEPTION 'short-ship disposition order revision is stale or not processing'
            USING ERRCODE = '23514';
    END IF;

    SELECT * INTO shortage_row
    FROM public.pick_shortages shortage
    WHERE shortage.tenant_id = NEW.tenant_id
      AND shortage.inventory_owner_id = NEW.inventory_owner_id
      AND shortage.facility_id = NEW.facility_id
      AND shortage.order_release_id = NEW.order_release_id
      AND shortage.order_id = NEW.order_id
      AND shortage.order_item_id = NEW.order_item_id
      AND shortage.reservation_id = NEW.reservation_id
      AND shortage.id = NEW.pick_shortage_id
    FOR UPDATE OF shortage;

    IF NOT FOUND
       OR shortage_row.revision NOT IN (
           NEW.expected_shortage_revision,
           NEW.resulting_shortage_revision
       )
       OR shortage_row.reallocated_qty <> shortage_row.recovery_terminal_qty
       OR shortage_row.remaining_to_allocate_qty <= 0
       OR shortage_row.accepted_short_qty NOT IN (0, NEW.accepted_short_qty)
       OR shortage_row.remaining_to_allocate_qty <> NEW.accepted_short_qty
       OR NOT (
           (shortage_row.revision = NEW.expected_shortage_revision
            AND shortage_row.status = 'awaiting_inventory'
            AND shortage_row.resolution IS NULL
            AND shortage_row.accepted_short_qty = 0
            AND shortage_row.resolved_by_user_id IS NULL
            AND shortage_row.resolved_at IS NULL)
           OR
           (shortage_row.revision = NEW.resulting_shortage_revision
            AND shortage_row.status = 'resolved'
            AND shortage_row.resolution = 'short_ship'
            AND shortage_row.accepted_short_qty = NEW.accepted_short_qty
            AND shortage_row.resolved_by_user_id = NEW.disposed_by_user_id
            AND shortage_row.resolved_at = NEW.disposed_at)
       )
       OR NOT EXISTS (
           SELECT 1
           FROM public.inventory_holds discrepancy_hold
           WHERE discrepancy_hold.tenant_id = shortage_row.tenant_id
             AND discrepancy_hold.inventory_owner_id = shortage_row.inventory_owner_id
             AND discrepancy_hold.facility_id = shortage_row.facility_id
             AND discrepancy_hold.id = shortage_row.inventory_hold_id
             AND discrepancy_hold.qty = shortage_row.short_qty
             AND discrepancy_hold.reason_code = 'inventory_discrepancy'
             AND discrepancy_hold.reference_type = 'pick_shortage_source'
             AND discrepancy_hold.reference_id = shortage_row.pick_task_content_id
             AND discrepancy_hold.status = 'active'
             AND discrepancy_hold.deleted IS NULL
       )
    THEN
        RAISE EXCEPTION 'short-ship disposition does not match an unresolved shortage and active discrepancy hold'
            USING ERRCODE = '23514';
    END IF;

    SELECT COALESCE(SUM(order_line.qty), 0)::BIGINT
    INTO original_order_qty
    FROM public.order_items order_line
    WHERE order_line.tenant_id = NEW.tenant_id
      AND order_line.inventory_owner_id = NEW.inventory_owner_id
      AND order_line.order_id = NEW.order_id
      AND order_line.deleted IS NULL;

    SELECT order_line.qty, reservation.qty
    INTO original_line_qty, reservation_qty
    FROM public.order_items order_line
    INNER JOIN public.inventory_reservations reservation
      ON reservation.tenant_id = order_line.tenant_id
     AND reservation.inventory_owner_id = order_line.inventory_owner_id
     AND reservation.order_id = order_line.order_id
     AND reservation.order_item_id = order_line.id
    WHERE order_line.tenant_id = NEW.tenant_id
      AND order_line.inventory_owner_id = NEW.inventory_owner_id
      AND order_line.order_id = NEW.order_id
      AND order_line.id = NEW.order_item_id
      AND order_line.deleted IS NULL
      AND reservation.facility_id = NEW.facility_id
      AND reservation.id = NEW.reservation_id
      AND reservation.status = 'active'
      AND reservation.deleted IS NULL;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'short-ship disposition requires active scoped demand'
            USING ERRCODE = '23514';
    END IF;

    SELECT COALESCE(SUM(disposition.accepted_short_qty), 0)::BIGINT,
           COALESCE(SUM(disposition.accepted_short_qty) FILTER (
               WHERE disposition.order_item_id = NEW.order_item_id
           ), 0)::BIGINT,
           COALESCE(SUM(disposition.accepted_short_qty) FILTER (
               WHERE disposition.reservation_id = NEW.reservation_id
           ), 0)::BIGINT
    INTO previously_accepted_order_qty,
         previously_accepted_line_qty,
         previously_accepted_reservation_qty
    FROM public.pick_short_ship_dispositions disposition
    WHERE disposition.tenant_id = NEW.tenant_id
      AND disposition.inventory_owner_id = NEW.inventory_owner_id
      AND disposition.order_id = NEW.order_id;

    SELECT COALESCE(SUM(split_line.newly_backordered_qty), 0)::BIGINT,
           COALESCE(SUM(split_line.newly_backordered_qty) FILTER (
               WHERE split_line.parent_order_item_id = NEW.order_item_id
           ), 0)::BIGINT
    INTO backordered_order_qty, backordered_line_qty
    FROM public.order_backorder_split_lines split_line
    WHERE split_line.tenant_id = NEW.tenant_id
      AND split_line.inventory_owner_id = NEW.inventory_owner_id
      AND split_line.parent_order_id = NEW.order_id;

    IF original_order_qty - backordered_order_qty
       - previously_accepted_order_qty - NEW.accepted_short_qty <= 0 THEN
        RAISE EXCEPTION 'short-ship disposition cannot reduce order effective demand to zero'
            USING ERRCODE = '55000';
    END IF;

    IF original_line_qty - backordered_line_qty
           - previously_accepted_line_qty - NEW.accepted_short_qty < 0
       OR reservation_qty - previously_accepted_reservation_qty - NEW.accepted_short_qty < 0
    THEN
        RAISE EXCEPTION 'accepted short quantity exceeds original line or reservation demand'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


