--
-- Name: order_allocation_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.order_allocation_runs (
    id bigint NOT NULL,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    order_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    created timestamp with time zone NOT NULL,
    created_by_user_id bigint NOT NULL,
    strategy text NOT NULL,
    policy_source text NOT NULL,
    policy_configuration_id bigint,
    policy_configuration_revision bigint,
    policy_scope_level text,
    policy_inventory_owner_id bigint,
    policy_facility_id bigint,
    policy_definition jsonb NOT NULL,
    policy_hash text NOT NULL,
    outcome text NOT NULL,
    requested_qty bigint NOT NULL,
    allocated_qty bigint NOT NULL,
    short_qty bigint NOT NULL,
    expected_revision bigint NOT NULL,
    resulting_revision bigint NOT NULL,
    CONSTRAINT order_allocation_runs_allocated_qty_check CHECK ((allocated_qty >= 0) AND (allocated_qty <= requested_qty)),
    CONSTRAINT order_allocation_runs_outcome_check CHECK ((outcome = ANY (ARRAY['fully_allocated'::text, 'partially_allocated'::text, 'not_allocated'::text]))),
    CONSTRAINT order_allocation_runs_outcome_totals_check CHECK ((((outcome = 'fully_allocated'::text) AND (allocated_qty = requested_qty) AND (short_qty = 0)) OR ((outcome = 'partially_allocated'::text) AND (allocated_qty > 0) AND (short_qty > 0)) OR ((outcome = 'not_allocated'::text) AND (allocated_qty = 0) AND (short_qty = requested_qty)))),
    CONSTRAINT order_allocation_runs_requested_qty_check CHECK (requested_qty > 0),
    CONSTRAINT order_allocation_runs_revision_check CHECK ((expected_revision > 0) AND (resulting_revision = (expected_revision + 1))),
    CONSTRAINT order_allocation_runs_short_qty_check CHECK ((short_qty >= 0) AND (short_qty = (requested_qty - allocated_qty))),
    CONSTRAINT order_allocation_runs_strategy_check CHECK (strategy IN ('fifo','fefo')),
    CONSTRAINT order_allocation_runs_policy_source_check CHECK (
        policy_source IN ('product_default','configuration')),
    CONSTRAINT order_allocation_runs_policy_hash_check CHECK (
        policy_hash~'^[0-9a-f]{64}$'),
    CONSTRAINT order_allocation_runs_policy_definition_check CHECK (
        jsonb_typeof(policy_definition)='object'
        AND policy_definition->>'kind'='allocation'
        AND policy_definition->>'rotation'=strategy),
    CONSTRAINT order_allocation_runs_policy_identity_check CHECK (
        (policy_source='product_default'
          AND policy_configuration_id IS NULL
          AND policy_configuration_revision IS NULL
          AND policy_scope_level IS NULL
          AND policy_inventory_owner_id IS NULL
          AND policy_facility_id IS NULL)
        OR
        (policy_source='configuration'
          AND policy_configuration_id IS NOT NULL
          AND policy_configuration_revision>0
          AND (
            (policy_scope_level='tenant'
              AND policy_inventory_owner_id IS NULL AND policy_facility_id IS NULL)
            OR (policy_scope_level='inventory_owner'
              AND policy_inventory_owner_id IS NOT NULL AND policy_facility_id IS NULL)
            OR (policy_scope_level='facility'
              AND policy_inventory_owner_id IS NULL AND policy_facility_id IS NOT NULL)
            OR (policy_scope_level='owner_facility'
              AND policy_inventory_owner_id IS NOT NULL AND policy_facility_id IS NOT NULL))))
);

ALTER TABLE ONLY public.order_allocation_runs FORCE ROW LEVEL SECURITY;


--
-- Name: order_allocation_runs_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.order_allocation_runs ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.order_allocation_runs_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: order_allocation_run_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.order_allocation_run_lines (
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    allocation_run_id bigint NOT NULL,
    order_id bigint NOT NULL,
    order_item_id bigint NOT NULL,
    reservation_id bigint NOT NULL,
    requested_qty bigint NOT NULL,
    previously_allocated_qty bigint NOT NULL,
    newly_allocated_qty bigint NOT NULL,
    total_allocated_qty bigint NOT NULL,
    short_qty bigint NOT NULL,
    shortage_reason text,
    CONSTRAINT order_allocation_run_lines_newly_allocated_qty_check CHECK (newly_allocated_qty >= 0),
    CONSTRAINT order_allocation_run_lines_previous_qty_check CHECK (previously_allocated_qty >= 0),
    CONSTRAINT order_allocation_run_lines_requested_qty_check CHECK (requested_qty > 0),
    CONSTRAINT order_allocation_run_lines_short_qty_check CHECK ((short_qty >= 0) AND (short_qty = (requested_qty - total_allocated_qty))),
    CONSTRAINT order_allocation_run_lines_shortage_reason_check CHECK (((short_qty = 0) AND (shortage_reason IS NULL)) OR ((short_qty > 0) AND (shortage_reason = ANY (ARRAY['no_eligible_inventory'::text, 'insufficient_eligible_inventory'::text])))),
    CONSTRAINT order_allocation_run_lines_total_qty_check CHECK ((total_allocated_qty = (previously_allocated_qty + newly_allocated_qty)) AND (total_allocated_qty <= requested_qty))
);

ALTER TABLE ONLY public.order_allocation_run_lines FORCE ROW LEVEL SECURITY;


--
-- Name: order_cancellations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.order_cancellations (
    id bigint NOT NULL,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    order_id bigint NOT NULL,
    actor_user_id bigint NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    reason text NOT NULL,
    note text,
    previous_status text NOT NULL,
    expected_revision bigint NOT NULL,
    resulting_revision bigint NOT NULL,
    affected_facility_ids bigint[] DEFAULT '{}'::bigint[] NOT NULL,
    released_hold_count bigint NOT NULL,
    released_reservation_count bigint NOT NULL,
    released_allocation_count bigint NOT NULL,
    released_quantity bigint NOT NULL,
    cancelled_pick_task_count bigint NOT NULL,
    cancelled_pick_content_count bigint NOT NULL,
    reversed_pick_confirmation_count bigint NOT NULL,
    released_outbound_container_count bigint NOT NULL,
    CONSTRAINT order_cancellations_affected_facilities_check CHECK ((array_position(affected_facility_ids, NULL::bigint) IS NULL) AND (0 < ALL (affected_facility_ids))),
    CONSTRAINT order_cancellations_note_check CHECK (((note IS NULL) OR ((note = btrim(note)) AND (note <> ''::text) AND (char_length(note) <= 1000)))),
    CONSTRAINT order_cancellations_other_note_check CHECK (((reason <> 'other'::text) OR (note IS NOT NULL))),
    CONSTRAINT order_cancellations_previous_status_check CHECK ((previous_status = ANY (ARRAY['open'::text, 'held'::text, 'processing'::text]))),
    CONSTRAINT order_cancellations_reason_check CHECK ((reason = ANY (ARRAY['client_request'::text, 'duplicate_order'::text, 'data_correction'::text, 'inventory_unavailable'::text, 'fulfillment_exception'::text, 'other'::text]))),
    CONSTRAINT order_cancellations_released_allocation_count_check CHECK (released_allocation_count >= 0),
    CONSTRAINT order_cancellations_released_hold_count_check CHECK (released_hold_count >= 0),
    CONSTRAINT order_cancellations_released_quantity_check CHECK (released_quantity >= 0),
    CONSTRAINT order_cancellations_released_reservation_count_check CHECK (released_reservation_count >= 0),
    CONSTRAINT order_cancellations_cancelled_pick_task_count_check CHECK (cancelled_pick_task_count >= 0),
    CONSTRAINT order_cancellations_cancelled_pick_content_count_check CHECK (cancelled_pick_content_count >= 0),
    CONSTRAINT order_cancellations_reversed_pick_confirmation_count_check CHECK (reversed_pick_confirmation_count >= 0),
    CONSTRAINT order_cancellations_released_outbound_container_count_check CHECK (released_outbound_container_count >= 0),
    CONSTRAINT order_cancellations_revision_check CHECK ((expected_revision > 0) AND (resulting_revision = (expected_revision + 1)))
);

