CREATE FUNCTION public.reject_shipment_document_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    RAISE EXCEPTION 'shipment document evidence is immutable' USING ERRCODE = '55000';
END;
$$;

CREATE FUNCTION public.validate_shipment_document() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    shipment_row public.shipments%ROWTYPE;
    manifest_row public.shipment_manifests%ROWTYPE;
    configuration_row record;
    demand_row record;
    actual_carton_count bigint;
    resolved_configuration_id bigint;
    calculated_hash text;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(format(
      'configuration-kind:%s:document',NEW.tenant_id),0));
    calculated_hash:=encode(sha256(convert_to(
      'document-policy-v1|'||(NEW.policy_definition->>'generate_packing_slip')||'|'||
      (NEW.policy_definition->>'generate_carton_label')||'|'||
      (NEW.policy_definition->>'require_tracking_barcode'),'UTF8')),'hex');
    IF NEW.policy_hash<>calculated_hash THEN
        RAISE EXCEPTION 'shipment document policy hash does not match its snapshot'
            USING ERRCODE = '23514';
    END IF;
    SELECT configuration.id INTO resolved_configuration_id
    FROM public.configuration_versions configuration
    WHERE configuration.tenant_id=NEW.tenant_id
      AND configuration.kind='document' AND configuration.status='active'
      AND configuration.effective_from<=NEW.generated_at
      AND (configuration.effective_until IS NULL
           OR configuration.effective_until>NEW.generated_at)
      AND (configuration.inventory_owner_id IS NULL
           OR configuration.inventory_owner_id=NEW.inventory_owner_id)
      AND (configuration.facility_id IS NULL
           OR configuration.facility_id=NEW.facility_id)
    ORDER BY CASE configuration.scope_level
               WHEN 'owner_facility' THEN 2
               WHEN 'inventory_owner' THEN 1
               WHEN 'facility' THEN 1
               ELSE 0 END DESC,
             configuration.effective_from DESC,
             configuration.revision DESC,configuration.id DESC
    LIMIT 1;
    IF NEW.policy_source='product_default' THEN
        IF resolved_configuration_id IS NOT NULL THEN
            RAISE EXCEPTION 'shipment document product default is not effective'
                USING ERRCODE = '23514';
        END IF;
    ELSE
        SELECT * INTO configuration_row
        FROM public.configuration_versions configuration
        WHERE configuration.tenant_id=NEW.tenant_id
          AND configuration.id=NEW.policy_configuration_id;
        IF configuration_row.id IS NULL
           OR configuration_row.kind<>'document'
           OR configuration_row.status<>'active'
           OR configuration_row.revision<>NEW.policy_configuration_revision
           OR configuration_row.scope_level<>NEW.policy_scope_level
           OR configuration_row.inventory_owner_id
                IS DISTINCT FROM NEW.policy_inventory_owner_id
           OR configuration_row.facility_id IS DISTINCT FROM NEW.policy_facility_id
           OR configuration_row.definition<>NEW.policy_definition
           OR configuration_row.effective_from>NEW.generated_at
           OR (configuration_row.effective_until IS NOT NULL
               AND configuration_row.effective_until<=NEW.generated_at)
           OR (configuration_row.inventory_owner_id IS NOT NULL
               AND configuration_row.inventory_owner_id<>NEW.inventory_owner_id)
           OR (configuration_row.facility_id IS NOT NULL
               AND configuration_row.facility_id<>NEW.facility_id)
           OR resolved_configuration_id IS DISTINCT FROM NEW.policy_configuration_id
        THEN
            RAISE EXCEPTION 'shipment document policy is stale or inapplicable'
                USING ERRCODE = '23514';
        END IF;
    END IF;
    SELECT * INTO shipment_row
    FROM public.shipments
    WHERE tenant_id = NEW.tenant_id
      AND inventory_owner_id = NEW.inventory_owner_id
      AND facility_id = NEW.facility_id
      AND id = NEW.shipment_id
    FOR SHARE;
    IF NOT FOUND OR shipment_row.order_id <> NEW.order_id THEN
        RAISE EXCEPTION 'shipment document scope does not match shipment' USING ERRCODE = '23514';
    END IF;
    IF shipment_row.revision <> NEW.shipment_revision_at_generation THEN
        RAISE EXCEPTION 'shipment revision changed before document generation' USING ERRCODE = '55000';
    END IF;
    IF shipment_row.state='cancelled' THEN
        RAISE EXCEPTION 'cancelled shipments cannot generate documents' USING ERRCODE = '55000';
    END IF;
    IF NEW.document_type = 'carton_label_set' THEN
        IF shipment_row.state <> 'manifested' THEN
            RAISE EXCEPTION 'carton labels require a manifested shipment before departure'
                USING ERRCODE = '55000';
        END IF;
    END IF;
    IF NEW.carrier_manifest_id IS NOT NULL THEN
        SELECT * INTO manifest_row
        FROM public.shipment_manifests
        WHERE tenant_id = NEW.tenant_id
          AND inventory_owner_id = NEW.inventory_owner_id
          AND facility_id = NEW.facility_id
          AND shipment_id = NEW.shipment_id
          AND id = NEW.carrier_manifest_id;
        IF NOT FOUND
           OR (NEW.document_type='carton_label_set'
               AND manifest_row.resulting_revision <> NEW.shipment_revision_at_generation)
           OR manifest_row.carrier <> NEW.carrier_code
           OR manifest_row.service IS DISTINCT FROM NEW.service_code
           OR manifest_row.manifest_number <> NEW.manifest_reference
        THEN
            RAISE EXCEPTION 'shipment document manifest does not match shipment'
                USING ERRCODE = '23514';
        END IF;
    END IF;
    SELECT COUNT(*)::bigint INTO actual_carton_count
    FROM public.shipment_cartons carton
    WHERE carton.tenant_id = NEW.tenant_id AND carton.inventory_owner_id = NEW.inventory_owner_id
      AND carton.facility_id = NEW.facility_id AND carton.shipment_id = NEW.shipment_id;
    IF actual_carton_count <> NEW.carton_count OR actual_carton_count <> shipment_row.carton_count THEN
        RAISE EXCEPTION 'shipment document carton count does not match shipment' USING ERRCODE = '23514';
    END IF;
    SELECT COALESCE(SUM(original_qty), 0)::bigint AS ordered_qty,
           COALESCE(SUM(accepted_short_qty), 0)::bigint AS accepted_short_qty,
           COALESCE(SUM(accepted_substitute_qty), 0)::bigint AS accepted_substitute_qty,
           COALESCE(SUM(effective_qty), 0)::bigint AS packed_qty,
           COUNT(*)::bigint AS line_count
    INTO demand_row
    FROM public.outbound_effective_demand demand
    WHERE demand.tenant_id = NEW.tenant_id
      AND demand.inventory_owner_id = NEW.inventory_owner_id
      AND demand.order_id = NEW.order_id;
    IF demand_row.ordered_qty <> NEW.ordered_qty
       OR demand_row.accepted_short_qty <> NEW.accepted_short_qty
       OR demand_row.accepted_substitute_qty <> NEW.accepted_substitute_qty
       OR demand_row.packed_qty <> NEW.packed_qty
       OR demand_row.line_count <> NEW.line_count
       OR shipment_row.shipped_qty <> NEW.packed_qty
    THEN
        RAISE EXCEPTION 'shipment document demand does not match shipment' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.validate_shipment_document_carton() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    document_row public.shipment_documents%ROWTYPE;
    source_row record;
BEGIN
    SELECT * INTO document_row
    FROM public.shipment_documents
    WHERE tenant_id = NEW.tenant_id AND inventory_owner_id = NEW.inventory_owner_id
      AND facility_id = NEW.facility_id AND shipment_id = NEW.shipment_id
      AND id = NEW.shipment_document_id;
    IF NOT FOUND OR document_row.order_id <> NEW.order_id THEN
        RAISE EXCEPTION 'shipment document carton scope does not match document'
            USING ERRCODE = '23514';
    END IF;
    SELECT carton.carton_id, carton.license_plate_id, carton.sequence,
           carton.carton_barcode, carton.packed_qty, carton.weight_g,
           carton.length_mm, carton.width_mm, carton.height_mm,
           package.id AS tracking_assignment_id, package.tracking_number
    INTO source_row
    FROM public.shipment_cartons carton
    LEFT JOIN public.shipment_manifest_packages package
      ON package.tenant_id = carton.tenant_id
     AND package.inventory_owner_id = carton.inventory_owner_id
     AND package.facility_id = carton.facility_id
     AND package.shipment_id = carton.shipment_id
     AND package.shipment_carton_id = carton.id
     AND package.manifest_id = document_row.carrier_manifest_id
    WHERE carton.tenant_id = NEW.tenant_id
      AND carton.inventory_owner_id = NEW.inventory_owner_id
      AND carton.facility_id = NEW.facility_id
      AND carton.shipment_id = NEW.shipment_id
      AND carton.id = NEW.shipment_carton_id;
    IF NOT FOUND
       OR NEW.carton_id <> source_row.carton_id
       OR NEW.license_plate_id <> source_row.license_plate_id
       OR NEW.sequence <> source_row.sequence
       OR NEW.carton_barcode <> source_row.carton_barcode
       OR NEW.packed_qty <> source_row.packed_qty
       OR NEW.weight_g IS DISTINCT FROM source_row.weight_g
       OR NEW.length_mm IS DISTINCT FROM source_row.length_mm
       OR NEW.width_mm IS DISTINCT FROM source_row.width_mm
       OR NEW.height_mm IS DISTINCT FROM source_row.height_mm
       OR (document_row.document_type = 'packing_slip'
           AND NOT (document_row.policy_definition->>'require_tracking_barcode')::boolean
           AND (NEW.tracking_assignment_id IS NOT NULL OR NEW.tracking_number IS NOT NULL))
       OR ((document_row.document_type = 'carton_label_set'
            OR (document_row.policy_definition->>'require_tracking_barcode')::boolean)
           AND (source_row.tracking_assignment_id IS NULL
                OR NEW.tracking_assignment_id IS DISTINCT FROM source_row.tracking_assignment_id
                OR NEW.tracking_number IS DISTINCT FROM source_row.tracking_number))
    THEN
        RAISE EXCEPTION 'shipment document carton does not match shipment evidence'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.validate_shipment_document_line() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    document_row public.shipment_documents%ROWTYPE;
    source_row record;
BEGIN
    SELECT * INTO document_row
    FROM public.shipment_documents
    WHERE tenant_id = NEW.tenant_id AND inventory_owner_id = NEW.inventory_owner_id
      AND facility_id = NEW.facility_id AND shipment_id = NEW.shipment_id
      AND id = NEW.shipment_document_id;
    IF NOT FOUND OR document_row.order_id <> NEW.order_id THEN
        RAISE EXCEPTION 'shipment document line scope does not match document' USING ERRCODE = '23514';
    END IF;
    SELECT demand.original_qty, demand.accepted_short_qty,
           demand.accepted_substitute_qty, demand.effective_qty,
           item.line_key, item.line_number, item.item_id, item.uom,
           COALESCE(NULLIF(btrim(catalog.description), ''), 'Item ' || item.item_id::text)
               AS item_description,
           COALESCE(SUM(content.packed_qty), 0)::bigint AS packed_qty
    INTO source_row
    FROM public.outbound_effective_demand demand
    INNER JOIN public.order_items item
      ON item.tenant_id = demand.tenant_id
     AND item.inventory_owner_id = demand.inventory_owner_id
     AND item.order_id = demand.order_id AND item.id = demand.order_item_id
    INNER JOIN public.items catalog
      ON catalog.tenant_id = item.tenant_id AND catalog.id = item.item_id
    LEFT JOIN public.carton_contents content
      ON content.tenant_id = demand.tenant_id
     AND content.inventory_owner_id = demand.inventory_owner_id
     AND content.order_id = demand.order_id AND content.order_item_id = demand.order_item_id
    WHERE demand.tenant_id = NEW.tenant_id
      AND demand.inventory_owner_id = NEW.inventory_owner_id
      AND demand.order_id = NEW.order_id AND demand.order_item_id = NEW.order_item_id
    GROUP BY demand.original_qty, demand.accepted_short_qty,
             demand.accepted_substitute_qty, demand.effective_qty,
             item.line_key, item.line_number, item.item_id, item.uom, catalog.description;
    IF NOT FOUND
       OR NEW.sequence <> source_row.line_number
       OR NEW.line_key <> source_row.line_key
       OR NEW.item_id <> source_row.item_id
       OR NEW.item_description <> source_row.item_description
       OR NEW.uom <> source_row.uom
       OR NEW.ordered_qty <> source_row.original_qty
       OR NEW.accepted_short_qty <> source_row.accepted_short_qty
       OR NEW.accepted_substitute_qty <> source_row.accepted_substitute_qty
       OR NEW.packed_qty <> source_row.effective_qty
       OR NEW.packed_qty <> source_row.packed_qty
    THEN
        RAISE EXCEPTION 'shipment document line does not match packed order demand' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.require_shipment_document_consistency() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    document_id_value bigint;
    document_row public.shipment_documents%ROWTYPE;
    line_count_value bigint;
    ordered_qty_value bigint;
    accepted_short_qty_value bigint;
    accepted_substitute_qty_value bigint;
    packed_qty_value bigint;
    carton_count_value bigint;
    carton_qty_value bigint;
BEGIN
    IF TG_TABLE_NAME = 'shipment_documents' THEN
        document_id_value := NEW.id;
    ELSE
        document_id_value := NEW.shipment_document_id;
    END IF;
    SELECT * INTO document_row FROM public.shipment_documents
    WHERE tenant_id = NEW.tenant_id AND id = document_id_value;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'shipment document is missing' USING ERRCODE = '23514';
    END IF;
    SELECT COUNT(*)::bigint, COALESCE(SUM(ordered_qty), 0)::bigint,
           COALESCE(SUM(accepted_short_qty), 0)::bigint,
           COALESCE(SUM(accepted_substitute_qty), 0)::bigint,
           COALESCE(SUM(packed_qty), 0)::bigint
    INTO line_count_value, ordered_qty_value, accepted_short_qty_value,
         accepted_substitute_qty_value, packed_qty_value
    FROM public.shipment_document_lines
    WHERE tenant_id = document_row.tenant_id AND shipment_document_id = document_row.id;
    SELECT COUNT(*)::bigint, COALESCE(SUM(packed_qty), 0)::bigint
    INTO carton_count_value, carton_qty_value
    FROM public.shipment_document_cartons
    WHERE tenant_id = document_row.tenant_id AND shipment_document_id = document_row.id;
    IF line_count_value <> document_row.line_count
       OR ordered_qty_value <> document_row.ordered_qty
       OR accepted_short_qty_value <> document_row.accepted_short_qty
       OR accepted_substitute_qty_value <> document_row.accepted_substitute_qty
       OR packed_qty_value <> document_row.packed_qty
       OR carton_count_value <> document_row.carton_count
       OR carton_qty_value <> document_row.packed_qty
       OR EXISTS (
           SELECT 1 FROM public.outbound_effective_demand demand
           WHERE demand.tenant_id = document_row.tenant_id
             AND demand.inventory_owner_id = document_row.inventory_owner_id
             AND demand.order_id = document_row.order_id
             AND NOT EXISTS (
                 SELECT 1 FROM public.shipment_document_lines line
                 WHERE line.tenant_id = document_row.tenant_id
                   AND line.shipment_document_id = document_row.id
                   AND line.order_item_id = demand.order_item_id))
       OR EXISTS (
           SELECT 1 FROM public.shipment_cartons carton
           WHERE carton.tenant_id = document_row.tenant_id
             AND carton.inventory_owner_id = document_row.inventory_owner_id
             AND carton.facility_id = document_row.facility_id
             AND carton.shipment_id = document_row.shipment_id
             AND NOT EXISTS (
                 SELECT 1 FROM public.shipment_document_cartons evidence
                 WHERE evidence.tenant_id = document_row.tenant_id
                   AND evidence.shipment_document_id = document_row.id
                   AND evidence.shipment_carton_id = carton.id))
    THEN
        RAISE EXCEPTION 'shipment document evidence does not reconcile with header'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE TRIGGER shipment_documents_validate BEFORE INSERT ON public.shipment_documents
FOR EACH ROW EXECUTE FUNCTION public.validate_shipment_document();
CREATE TRIGGER shipment_documents_are_immutable BEFORE DELETE OR UPDATE ON public.shipment_documents
FOR EACH ROW EXECUTE FUNCTION public.reject_shipment_document_mutation();
CREATE CONSTRAINT TRIGGER shipment_documents_require_consistency
AFTER INSERT ON public.shipment_documents DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_shipment_document_consistency();
CREATE TRIGGER shipment_document_lines_validate BEFORE INSERT ON public.shipment_document_lines
FOR EACH ROW EXECUTE FUNCTION public.validate_shipment_document_line();
CREATE TRIGGER shipment_document_lines_are_immutable BEFORE DELETE OR UPDATE ON public.shipment_document_lines
FOR EACH ROW EXECUTE FUNCTION public.reject_shipment_document_mutation();
CREATE CONSTRAINT TRIGGER shipment_document_lines_require_consistency
AFTER INSERT ON public.shipment_document_lines DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_shipment_document_consistency();
CREATE TRIGGER shipment_document_cartons_validate BEFORE INSERT ON public.shipment_document_cartons
FOR EACH ROW EXECUTE FUNCTION public.validate_shipment_document_carton();
CREATE TRIGGER shipment_document_cartons_are_immutable BEFORE DELETE OR UPDATE ON public.shipment_document_cartons
FOR EACH ROW EXECUTE FUNCTION public.reject_shipment_document_mutation();
CREATE CONSTRAINT TRIGGER shipment_document_cartons_require_consistency
AFTER INSERT ON public.shipment_document_cartons DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_shipment_document_consistency();

ALTER TABLE public.shipment_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY shipment_documents_tenant_isolation ON public.shipment_documents
USING (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint)
WITH CHECK (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint);
ALTER TABLE public.shipment_document_lines ENABLE ROW LEVEL SECURITY;
CREATE POLICY shipment_document_lines_tenant_isolation ON public.shipment_document_lines
USING (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint)
WITH CHECK (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint);
ALTER TABLE public.shipment_document_cartons ENABLE ROW LEVEL SECURITY;
CREATE POLICY shipment_document_cartons_tenant_isolation ON public.shipment_document_cartons
USING (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint)
WITH CHECK (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint);

GRANT SELECT, INSERT ON public.shipment_documents TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.shipment_documents_id_seq TO wareboxes_app;
GRANT SELECT, INSERT ON public.shipment_document_lines TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.shipment_document_lines_id_seq TO wareboxes_app;
GRANT SELECT, INSERT ON public.shipment_document_cartons TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.shipment_document_cartons_id_seq TO wareboxes_app;
REVOKE ALL ON FUNCTION public.reject_shipment_document_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_shipment_document() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_shipment_document_line() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_shipment_document_carton() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_shipment_document_consistency() FROM PUBLIC;

-- Policy-driven outbound QA is an inventory-neutral verification boundary between
-- completed packing and immutable shipment creation.
CREATE TABLE public.outbound_qa_policies (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    requirement text NOT NULL,
    revision bigint NOT NULL,
    supersedes_policy_id bigint,
    effective_from timestamp with time zone NOT NULL,
    effective_to timestamp with time zone,
    configured_by_user_id bigint NOT NULL,
    configured_at timestamp with time zone NOT NULL,
    CONSTRAINT outbound_qa_policies_requirement_check CHECK (
        requirement IN ('not_required', 'scan_every_carton')),
    CONSTRAINT outbound_qa_policies_revision_check CHECK (revision > 0),
    CONSTRAINT outbound_qa_policies_effective_check CHECK (
        effective_from = configured_at AND
        (effective_to IS NULL OR effective_to >= effective_from)),
    CONSTRAINT outbound_qa_policies_initial_check CHECK (
        (revision = 1 AND supersedes_policy_id IS NULL)
        OR (revision > 1 AND supersedes_policy_id IS NOT NULL))
);
ALTER TABLE public.outbound_qa_policies FORCE ROW LEVEL SECURITY;

CREATE TABLE public.outbound_qa_sessions (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    packing_session_id bigint NOT NULL,
    order_id bigint NOT NULL,
    policy_id bigint NOT NULL,
    policy_revision bigint NOT NULL,
    state text NOT NULL DEFAULT 'open',
    revision bigint NOT NULL DEFAULT 1,
    expected_order_revision bigint NOT NULL,
    expected_carton_count bigint NOT NULL,
    verified_carton_count bigint NOT NULL DEFAULT 0,
    started_by_user_id bigint NOT NULL,
    started_at timestamp with time zone NOT NULL,
    passed_by_user_id bigint,
    passed_at timestamp with time zone,
    CONSTRAINT outbound_qa_sessions_state_check CHECK (state IN ('open', 'passed')),
    CONSTRAINT outbound_qa_sessions_revision_check CHECK (revision > 0),
    CONSTRAINT outbound_qa_sessions_counts_check CHECK (
        expected_carton_count > 0 AND verified_carton_count >= 0
        AND verified_carton_count <= expected_carton_count),
    CONSTRAINT outbound_qa_sessions_state_fields_check CHECK (
        (state = 'open' AND passed_by_user_id IS NULL AND passed_at IS NULL)
        OR (state = 'passed' AND passed_by_user_id IS NOT NULL AND passed_at IS NOT NULL
            AND passed_at >= started_at AND verified_carton_count = expected_carton_count))
);
ALTER TABLE public.outbound_qa_sessions FORCE ROW LEVEL SECURITY;

CREATE TABLE public.outbound_qa_carton_verifications (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    outbound_qa_session_id bigint NOT NULL,
    packing_session_id bigint NOT NULL,
    order_id bigint NOT NULL,
    carton_id bigint NOT NULL,
    license_plate_id bigint NOT NULL,
    sequence bigint NOT NULL,
    carton_barcode text NOT NULL,
    content_count bigint NOT NULL,
    packed_qty bigint NOT NULL,
    expected_session_revision bigint NOT NULL,
    resulting_session_revision bigint NOT NULL,
    verified_by_user_id bigint NOT NULL,
    verified_at timestamp with time zone NOT NULL,
    CONSTRAINT outbound_qa_carton_verifications_sequence_check CHECK (sequence > 0),
    CONSTRAINT outbound_qa_carton_verifications_barcode_check CHECK (
        carton_barcode = btrim(carton_barcode) AND carton_barcode <> ''
        AND char_length(carton_barcode) <= 200),
    CONSTRAINT outbound_qa_carton_verifications_counts_check CHECK (
        content_count > 0 AND packed_qty > 0),
    CONSTRAINT outbound_qa_carton_verifications_revision_check CHECK (
        expected_session_revision > 0
        AND resulting_session_revision = expected_session_revision + 1)
);
ALTER TABLE public.outbound_qa_carton_verifications FORCE ROW LEVEL SECURITY;

CREATE TABLE public.outbound_qa_completions (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    outbound_qa_session_id bigint NOT NULL,
    packing_session_id bigint NOT NULL,
    order_id bigint NOT NULL,
    expected_session_revision bigint NOT NULL,
    resulting_session_revision bigint NOT NULL,
    carton_count bigint NOT NULL,
    completed_by_user_id bigint NOT NULL,
    completed_at timestamp with time zone NOT NULL,
    CONSTRAINT outbound_qa_completions_carton_count_check CHECK (carton_count > 0),
    CONSTRAINT outbound_qa_completions_revision_check CHECK (
        expected_session_revision > 0
        AND resulting_session_revision = expected_session_revision + 1)
);
ALTER TABLE public.outbound_qa_completions FORCE ROW LEVEL SECURITY;

ALTER TABLE public.outbound_qa_policies
    ADD CONSTRAINT outbound_qa_policies_scope_id_key
