              pick_task_count, released_qty, active)
ON public.pick_wave_orders TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.pick_wave_orders_id_seq TO wareboxes_app;
GRANT UPDATE (wave_id) ON public.orders TO wareboxes_app;

REVOKE ALL ON FUNCTION public.validate_pick_wave() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_pick_wave_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_pick_wave_order() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_pick_wave_order_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_order_release_wave_membership() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_pick_wave_consistency() FROM PUBLIC;

-- Exact pre-execution demand-line replacement. Existing line identities are
-- retired, never rewritten; the accepted replacement receives new identities and
-- stale reservations/allocations are released in the same transaction.
ALTER TABLE public.order_items
    DROP CONSTRAINT order_items_tenant_owner_order_line_key_key,
    DROP CONSTRAINT order_items_tenant_owner_order_line_number_key;
CREATE UNIQUE INDEX order_items_active_line_key
ON public.order_items (tenant_id, inventory_owner_id, order_id, line_key)
WHERE deleted IS NULL;
CREATE UNIQUE INDEX order_items_active_line_number
ON public.order_items (tenant_id, inventory_owner_id, order_id, line_number)
WHERE deleted IS NULL;

CREATE TABLE public.order_line_amendments (
    id bigint GENERATED ALWAYS AS IDENTITY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    order_id bigint NOT NULL,
    order_status text NOT NULL,
    expected_order_revision bigint NOT NULL,
    resulting_order_revision bigint NOT NULL,
    previous_line_count bigint NOT NULL,
    previous_qty bigint NOT NULL,
    resulting_line_count bigint NOT NULL,
    resulting_qty bigint NOT NULL,
    released_reservation_count bigint NOT NULL,
    released_allocation_count bigint NOT NULL,
    released_qty bigint NOT NULL,
    amended_by_user_id bigint NOT NULL,
    amended_at timestamptz NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, inventory_owner_id, order_id, id),
    UNIQUE (tenant_id, order_id, expected_order_revision),
    CHECK (order_status IN ('open','held')),
    CHECK (expected_order_revision > 0
           AND resulting_order_revision = expected_order_revision + 1),
    CHECK (previous_line_count > 0 AND previous_qty > 0),
    CHECK (resulting_line_count > 0 AND resulting_qty > 0),
    CHECK (released_reservation_count >= 0
           AND released_allocation_count >= 0 AND released_qty >= 0),
    FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    FOREIGN KEY (tenant_id, inventory_owner_id)
        REFERENCES public.inventory_owners(tenant_id, id),
    FOREIGN KEY (tenant_id, inventory_owner_id, order_id)
        REFERENCES public.orders(tenant_id, inventory_owner_id, id),
    FOREIGN KEY (tenant_id, amended_by_user_id)
        REFERENCES public.tenant_memberships(tenant_id, user_id)
);
ALTER TABLE public.order_line_amendments FORCE ROW LEVEL SECURITY;

CREATE TABLE public.order_line_amendment_lines (
    id bigint GENERATED ALWAYS AS IDENTITY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    order_id bigint NOT NULL,
    order_line_amendment_id bigint NOT NULL,
    snapshot_kind text NOT NULL,
    order_item_id bigint NOT NULL,
    line_key text NOT NULL,
    line_number bigint NOT NULL,
    item_id bigint NOT NULL,
    qty bigint NOT NULL,
    uom text NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, order_line_amendment_id, snapshot_kind, order_item_id),
    UNIQUE (tenant_id, order_line_amendment_id, snapshot_kind, line_key),
    UNIQUE (tenant_id, order_line_amendment_id, snapshot_kind, line_number),
    CHECK (snapshot_kind IN ('previous','resulting')),
    CHECK (line_key = btrim(line_key) AND line_key <> '' AND char_length(line_key) <= 200),
    CHECK (line_number > 0 AND qty > 0),
    CHECK (uom = btrim(uom) AND uom <> '' AND char_length(uom) <= 32),
    FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    FOREIGN KEY (tenant_id, inventory_owner_id)
        REFERENCES public.inventory_owners(tenant_id, id),
    FOREIGN KEY (tenant_id, inventory_owner_id, order_id)
        REFERENCES public.orders(tenant_id, inventory_owner_id, id),
    FOREIGN KEY (tenant_id, inventory_owner_id, order_id, order_line_amendment_id)
        REFERENCES public.order_line_amendments(tenant_id, inventory_owner_id, order_id, id),
    FOREIGN KEY (tenant_id, inventory_owner_id, order_id, order_item_id)
        REFERENCES public.order_items(tenant_id, inventory_owner_id, order_id, id),
    FOREIGN KEY (tenant_id, inventory_owner_id, item_id)
        REFERENCES public.inventory_owner_items(tenant_id, inventory_owner_id, item_id)
);
ALTER TABLE public.order_line_amendment_lines FORCE ROW LEVEL SECURITY;

CREATE FUNCTION public.validate_order_line_amendment() RETURNS trigger
LANGUAGE plpgsql SET search_path TO 'pg_catalog', 'public' AS $$
DECLARE
    current_status text;
    current_revision bigint;
    current_owner bigint;
    current_wave bigint;
BEGIN
    SELECT status, revision, inventory_owner_id, wave_id
      INTO current_status, current_revision, current_owner, current_wave
    FROM public.orders
    WHERE tenant_id = NEW.tenant_id AND id = NEW.order_id AND deleted IS NULL
    FOR UPDATE;
    IF NOT FOUND OR current_owner <> NEW.inventory_owner_id THEN
        RAISE EXCEPTION 'order line amendment order is not current'
            USING ERRCODE = '55000';
    END IF;
    IF current_status <> NEW.order_status
       OR current_status NOT IN ('open','held')
       OR current_revision <> NEW.expected_order_revision
       OR current_wave IS NOT NULL
       OR EXISTS (
           SELECT 1 FROM public.order_releases release
           WHERE release.tenant_id = NEW.tenant_id AND release.order_id = NEW.order_id)
    THEN
        RAISE EXCEPTION 'order line amendment requires an unreleased open or held order'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.guard_order_item_line_replacement() RETURNS trigger
LANGUAGE plpgsql SET search_path TO 'pg_catalog', 'public' AS $$
DECLARE
    amendment_id bigint;
    substitution_id bigint;
    allowed boolean;
    order_revision bigint;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'order demand lines cannot be deleted' USING ERRCODE = '55000';
    END IF;
    amendment_id := NULLIF(
        current_setting('wareboxes.order_line_amendment_id', true), '')::bigint;
    substitution_id := NULLIF(
        current_setting('wareboxes.item_substitution_id', true), '')::bigint;
    IF TG_OP = 'UPDATE' THEN
        IF OLD.deleted IS NOT NULL OR NEW.deleted IS NULL
           OR ROW(OLD.tenant_id, OLD.inventory_owner_id, OLD.created, OLD.line_key,
                  OLD.line_number, OLD.qty, OLD.item_id, OLD.order_id, OLD.uom)
              IS DISTINCT FROM
              ROW(NEW.tenant_id, NEW.inventory_owner_id, NEW.created, NEW.line_key,
                  NEW.line_number, NEW.qty, NEW.item_id, NEW.order_id, NEW.uom)
        THEN
            RAISE EXCEPTION 'order demand line facts are immutable'
                USING ERRCODE = '55000';
        END IF;
        SELECT EXISTS(
            SELECT 1 FROM public.order_line_amendments amendment
            INNER JOIN public.order_line_amendment_lines evidence
              ON evidence.tenant_id = amendment.tenant_id
             AND evidence.order_line_amendment_id = amendment.id
             AND evidence.snapshot_kind = 'previous'
             AND evidence.order_item_id = OLD.id
            WHERE amendment.tenant_id = NEW.tenant_id
              AND amendment.inventory_owner_id = NEW.inventory_owner_id
              AND amendment.order_id = NEW.order_id
              AND amendment.id = amendment_id
              AND amendment.amended_at = NEW.deleted)
          INTO allowed;
        IF NOT COALESCE(allowed, false) THEN
            RAISE EXCEPTION 'order demand lines require typed replacement evidence'
                USING ERRCODE = '55000';
        END IF;
        RETURN NEW;
    END IF;

    IF amendment_id IS NOT NULL THEN
        SELECT EXISTS(
            SELECT 1 FROM public.order_line_amendments amendment
            WHERE amendment.tenant_id = NEW.tenant_id
              AND amendment.inventory_owner_id = NEW.inventory_owner_id
              AND amendment.order_id = NEW.order_id
              AND amendment.id = amendment_id
              AND amendment.amended_at = NEW.created)
          INTO allowed;
        IF NOT COALESCE(allowed, false) THEN
            RAISE EXCEPTION 'replacement demand line does not match typed evidence'
                USING ERRCODE = '55000';
        END IF;
        RETURN NEW;
    END IF;

    IF substitution_id IS NOT NULL THEN
        SELECT EXISTS(
            SELECT 1 FROM public.pick_shortage_substitutions substitution
            WHERE substitution.tenant_id = NEW.tenant_id
              AND substitution.inventory_owner_id = NEW.inventory_owner_id
              AND substitution.order_id = NEW.order_id
              AND substitution.substitute_order_item_id = NEW.id
              AND substitution.substitute_item_id = NEW.item_id
              AND substitution.substitute_uom = NEW.uom
              AND substitution.substitute_qty = NEW.qty
              AND substitution.id = substitution_id
              AND substitution.substituted_at = NEW.created)
          INTO allowed;
        IF NOT COALESCE(allowed, false) THEN
            RAISE EXCEPTION 'substitute demand line does not match typed evidence'
                USING ERRCODE = '55000';
        END IF;
        RETURN NEW;
    END IF;

    SELECT revision INTO order_revision
    FROM public.orders
    WHERE tenant_id = NEW.tenant_id AND id = NEW.order_id;
    IF order_revision <> 1 OR EXISTS (
        SELECT 1 FROM public.order_line_amendments amendment
        WHERE amendment.tenant_id = NEW.tenant_id AND amendment.order_id = NEW.order_id)
    THEN
        RAISE EXCEPTION 'new demand lines require order creation or typed replacement'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.reject_order_line_amendment_evidence_mutation() RETURNS trigger
LANGUAGE plpgsql SET search_path TO 'pg_catalog', 'public' AS $$
BEGIN
    RAISE EXCEPTION 'order line amendment evidence is immutable' USING ERRCODE = '55000';
END;
$$;

CREATE FUNCTION public.require_order_line_amendment_consistency() RETURNS trigger
LANGUAGE plpgsql SET search_path TO 'pg_catalog', 'public' AS $$
DECLARE
    amendment_id_value bigint;
    amendment public.order_line_amendments%ROWTYPE;
    previous_count bigint;
    previous_qty bigint;
    resulting_count bigint;
    resulting_qty bigint;
    reservation_count bigint;
    allocation_count bigint;
    released_qty bigint;
BEGIN
    IF TG_TABLE_NAME = 'order_line_amendments' THEN
        amendment_id_value := NEW.id;
    ELSIF TG_TABLE_NAME = 'order_line_amendment_lines' THEN
        amendment_id_value := NEW.order_line_amendment_id;
    ELSE
        amendment_id_value := NULLIF(
            current_setting('wareboxes.order_line_amendment_id', true), '')::bigint;
        IF amendment_id_value IS NULL THEN
            RETURN NULL;
        END IF;
    END IF;
    SELECT * INTO amendment FROM public.order_line_amendments
    WHERE tenant_id = NEW.tenant_id AND id = amendment_id_value;

    SELECT COUNT(*), COALESCE(SUM(qty), 0)
      INTO previous_count, previous_qty
    FROM public.order_line_amendment_lines
    WHERE tenant_id = amendment.tenant_id
      AND order_line_amendment_id = amendment.id
      AND snapshot_kind = 'previous';
    SELECT COUNT(*), COALESCE(SUM(qty), 0)
      INTO resulting_count, resulting_qty
    FROM public.order_line_amendment_lines
    WHERE tenant_id = amendment.tenant_id
      AND order_line_amendment_id = amendment.id
      AND snapshot_kind = 'resulting';

    SELECT COUNT(*) INTO reservation_count
    FROM public.inventory_reservations reservation
    WHERE reservation.tenant_id = amendment.tenant_id
      AND reservation.order_id = amendment.order_id
      AND reservation.status = 'cancelled'
      AND reservation.deleted = amendment.amended_at
      AND reservation.modified = amendment.amended_at;
    SELECT COUNT(*), COALESCE(SUM(allocation.qty), 0)
      INTO allocation_count, released_qty
    FROM public.inventory_allocations allocation
    INNER JOIN public.inventory_reservations reservation
      ON reservation.tenant_id = allocation.tenant_id
     AND reservation.id = allocation.reservation_id
    WHERE allocation.tenant_id = amendment.tenant_id
      AND reservation.order_id = amendment.order_id
      AND allocation.status = 'released'
      AND allocation.deleted = amendment.amended_at
      AND allocation.modified = amendment.amended_at;

    IF previous_count <> amendment.previous_line_count
       OR previous_qty <> amendment.previous_qty
       OR resulting_count <> amendment.resulting_line_count
       OR resulting_qty <> amendment.resulting_qty
       OR reservation_count <> amendment.released_reservation_count
       OR allocation_count <> amendment.released_allocation_count
       OR released_qty <> amendment.released_qty
       OR EXISTS (
           SELECT 1 FROM public.orders order_header
           WHERE order_header.tenant_id = amendment.tenant_id
             AND order_header.id = amendment.order_id
             AND (order_header.inventory_owner_id <> amendment.inventory_owner_id
                  OR order_header.status <> amendment.order_status
                  OR order_header.revision <> amendment.resulting_order_revision
                  OR order_header.wave_id IS NOT NULL))
       OR NOT EXISTS (
           SELECT 1 FROM public.orders order_header
           WHERE order_header.tenant_id = amendment.tenant_id
             AND order_header.id = amendment.order_id)
       OR EXISTS (
           SELECT 1 FROM public.order_line_amendment_lines snapshot
           INNER JOIN public.order_items item
             ON item.tenant_id = snapshot.tenant_id
            AND item.inventory_owner_id = snapshot.inventory_owner_id
            AND item.order_id = snapshot.order_id
            AND item.id = snapshot.order_item_id
           WHERE snapshot.tenant_id = amendment.tenant_id
             AND snapshot.order_line_amendment_id = amendment.id
             AND (snapshot.line_key <> item.line_key
                  OR snapshot.line_number <> item.line_number
                  OR snapshot.item_id <> item.item_id
                  OR snapshot.qty <> item.qty OR snapshot.uom <> item.uom
                  OR (snapshot.snapshot_kind = 'previous'
                      AND item.deleted IS DISTINCT FROM amendment.amended_at)
                  OR (snapshot.snapshot_kind = 'resulting'
                      AND (item.deleted IS NOT NULL
                           OR item.created <> amendment.amended_at))))
       OR EXISTS (
           SELECT 1 FROM public.order_items item
           WHERE item.tenant_id = amendment.tenant_id
             AND item.inventory_owner_id = amendment.inventory_owner_id
             AND item.order_id = amendment.order_id
             AND item.deleted IS NULL
             AND NOT EXISTS (
                 SELECT 1 FROM public.order_line_amendment_lines snapshot
                 WHERE snapshot.tenant_id = item.tenant_id
                   AND snapshot.order_line_amendment_id = amendment.id
                   AND snapshot.snapshot_kind = 'resulting'
                   AND snapshot.order_item_id = item.id))
       OR EXISTS (
           SELECT 1 FROM public.inventory_reservations reservation
           WHERE reservation.tenant_id = amendment.tenant_id
             AND reservation.order_id = amendment.order_id
             AND reservation.deleted IS NULL AND reservation.status = 'active')
       OR EXISTS (
           SELECT 1 FROM public.inventory_allocations allocation
           INNER JOIN public.inventory_reservations reservation
             ON reservation.tenant_id = allocation.tenant_id
            AND reservation.id = allocation.reservation_id
           WHERE allocation.tenant_id = amendment.tenant_id
             AND reservation.order_id = amendment.order_id
             AND allocation.deleted IS NULL
             AND allocation.status = 'allocated')
    THEN
        RAISE EXCEPTION 'order line replacement does not reconcile'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE TRIGGER order_line_amendments_validate
BEFORE INSERT ON public.order_line_amendments
FOR EACH ROW EXECUTE FUNCTION public.validate_order_line_amendment();
CREATE TRIGGER order_line_amendments_immutable
BEFORE UPDATE OR DELETE ON public.order_line_amendments
FOR EACH ROW EXECUTE FUNCTION public.reject_order_line_amendment_evidence_mutation();
CREATE TRIGGER order_line_amendment_lines_immutable
BEFORE UPDATE OR DELETE ON public.order_line_amendment_lines
FOR EACH ROW EXECUTE FUNCTION public.reject_order_line_amendment_evidence_mutation();
CREATE TRIGGER order_items_guard_line_replacement
BEFORE INSERT OR UPDATE OR DELETE ON public.order_items
FOR EACH ROW EXECUTE FUNCTION public.guard_order_item_line_replacement();
CREATE CONSTRAINT TRIGGER order_line_amendments_reconcile
AFTER INSERT ON public.order_line_amendments DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_order_line_amendment_consistency();
CREATE CONSTRAINT TRIGGER order_line_amendment_lines_reconcile
AFTER INSERT ON public.order_line_amendment_lines DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_order_line_amendment_consistency();
CREATE CONSTRAINT TRIGGER order_items_line_replacement_reconcile
AFTER INSERT OR UPDATE ON public.order_items DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_order_line_amendment_consistency();

ALTER TABLE public.order_line_amendments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.order_line_amendments FORCE ROW LEVEL SECURITY;
CREATE POLICY order_line_amendments_tenant_isolation
ON public.order_line_amendments
USING (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint)
WITH CHECK (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint);
ALTER TABLE public.order_line_amendment_lines ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.order_line_amendment_lines FORCE ROW LEVEL SECURITY;
CREATE POLICY order_line_amendment_lines_tenant_isolation
ON public.order_line_amendment_lines
USING (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint)
WITH CHECK (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint);

GRANT SELECT, INSERT ON public.order_line_amendments TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.order_line_amendments_id_seq TO wareboxes_app;
GRANT SELECT, INSERT ON public.order_line_amendment_lines TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.order_line_amendment_lines_id_seq TO wareboxes_app;
REVOKE DELETE, UPDATE ON public.order_items FROM wareboxes_app;
GRANT UPDATE (deleted) ON public.order_items TO wareboxes_app;

REVOKE ALL ON FUNCTION public.validate_order_line_amendment() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_order_item_line_replacement() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.reject_order_line_amendment_evidence_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_order_line_amendment_consistency() FROM PUBLIC;

-- Versioned, owner/facility-scoped approval for exact item substitutions.
CREATE TABLE public.item_substitution_policies (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    source_item_id bigint NOT NULL,
    source_uom text NOT NULL,
    substitute_item_id bigint NOT NULL,
    substitute_uom text NOT NULL,
    source_qty bigint NOT NULL CHECK (source_qty > 0),
    substitute_qty bigint NOT NULL CHECK (substitute_qty > 0),
    revision bigint NOT NULL CHECK (revision > 0),
    supersedes_policy_id bigint,
    effective_from timestamptz NOT NULL,
    effective_to timestamptz,
    configured_by_user_id bigint NOT NULL,
    configured_at timestamptz NOT NULL,
    retired_by_user_id bigint,
    CHECK (source_uom = btrim(source_uom) AND source_uom <> ''
           AND char_length(source_uom) <= 32),
    CHECK (substitute_uom = btrim(substitute_uom) AND substitute_uom <> ''
           AND char_length(substitute_uom) <= 32),
    CHECK (source_item_id <> substitute_item_id OR source_uom <> substitute_uom),
    CHECK (configured_at = effective_from),
    CHECK ((effective_to IS NULL AND retired_by_user_id IS NULL)
           OR effective_to > effective_from),
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, inventory_owner_id, facility_id, id),
    UNIQUE (tenant_id, inventory_owner_id, facility_id,
            source_item_id, source_uom, substitute_item_id, substitute_uom, revision),
    FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    FOREIGN KEY (tenant_id, inventory_owner_id)
        REFERENCES public.inventory_owners(tenant_id, id),
    FOREIGN KEY (tenant_id, facility_id)
        REFERENCES public.facilities(tenant_id, id),
    FOREIGN KEY (tenant_id, inventory_owner_id, facility_id)
        REFERENCES public.inventory_owner_facilities(tenant_id, inventory_owner_id, facility_id),
    FOREIGN KEY (tenant_id, inventory_owner_id, source_item_id)
        REFERENCES public.inventory_owner_items(tenant_id, inventory_owner_id, item_id),
    FOREIGN KEY (tenant_id, inventory_owner_id, substitute_item_id)
        REFERENCES public.inventory_owner_items(tenant_id, inventory_owner_id, item_id),
    FOREIGN KEY (tenant_id, configured_by_user_id)
        REFERENCES public.tenant_memberships(tenant_id, user_id),
    FOREIGN KEY (tenant_id, retired_by_user_id)
        REFERENCES public.tenant_memberships(tenant_id, user_id),
    FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, supersedes_policy_id)
        REFERENCES public.item_substitution_policies(
            tenant_id, inventory_owner_id, facility_id, id)
);
ALTER TABLE public.item_substitution_policies FORCE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX item_substitution_policies_active_natural_key
ON public.item_substitution_policies (
    tenant_id, inventory_owner_id, facility_id,
    source_item_id, source_uom, substitute_item_id, substitute_uom)
WHERE effective_to IS NULL;
CREATE INDEX item_substitution_policies_source_lookup_idx
ON public.item_substitution_policies (
    tenant_id, inventory_owner_id, facility_id, source_item_id, source_uom,
    substitute_item_id, substitute_uom, revision DESC);

CREATE FUNCTION public.validate_item_substitution_policy() RETURNS trigger
LANGUAGE plpgsql SET search_path TO 'pg_catalog', 'public' AS $$
DECLARE
    predecessor public.item_substitution_policies%ROWTYPE;
    source_catalog_uom text;
    substitute_catalog_uom text;
BEGIN
    SELECT item.packaging_unit INTO source_catalog_uom
    FROM public.inventory_owner_items owner_item
    JOIN public.items item ON item.tenant_id = owner_item.tenant_id
                          AND item.id = owner_item.item_id
    WHERE owner_item.tenant_id = NEW.tenant_id
      AND owner_item.inventory_owner_id = NEW.inventory_owner_id
      AND owner_item.item_id = NEW.source_item_id
      AND owner_item.deleted IS NULL AND item.deleted IS NULL
    FOR SHARE OF owner_item, item;
    SELECT item.packaging_unit INTO substitute_catalog_uom
    FROM public.inventory_owner_items owner_item
    JOIN public.items item ON item.tenant_id = owner_item.tenant_id
                          AND item.id = owner_item.item_id
    WHERE owner_item.tenant_id = NEW.tenant_id
      AND owner_item.inventory_owner_id = NEW.inventory_owner_id
      AND owner_item.item_id = NEW.substitute_item_id
      AND owner_item.deleted IS NULL AND item.deleted IS NULL
    FOR SHARE OF owner_item, item;
    IF source_catalog_uom IS DISTINCT FROM NEW.source_uom
       OR substitute_catalog_uom IS DISTINCT FROM NEW.substitute_uom
       OR NOT EXISTS (
           SELECT 1 FROM public.inventory_owner_facilities assignment
           WHERE assignment.tenant_id = NEW.tenant_id
             AND assignment.inventory_owner_id = NEW.inventory_owner_id
             AND assignment.facility_id = NEW.facility_id
             AND assignment.deleted IS NULL)
    THEN
        RAISE EXCEPTION 'item substitution policy scope, items, or UOM is unavailable'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.supersedes_policy_id IS NULL THEN
        IF NEW.revision <> 1 THEN
            RAISE EXCEPTION 'initial item substitution policy revision must be one'
                USING ERRCODE = '23514';
        END IF;
    ELSE
        SELECT * INTO predecessor FROM public.item_substitution_policies
        WHERE tenant_id = NEW.tenant_id
          AND inventory_owner_id = NEW.inventory_owner_id
          AND facility_id = NEW.facility_id
          AND source_item_id = NEW.source_item_id
          AND source_uom = NEW.source_uom
          AND substitute_item_id = NEW.substitute_item_id
          AND substitute_uom = NEW.substitute_uom
          AND id = NEW.supersedes_policy_id
        FOR SHARE;
        IF NOT FOUND OR predecessor.revision + 1 <> NEW.revision
           OR predecessor.effective_to IS NULL
           OR predecessor.effective_to > NEW.effective_from
           OR (predecessor.retired_by_user_id IS NULL
               AND predecessor.effective_to IS DISTINCT FROM NEW.effective_from) THEN
            RAISE EXCEPTION 'item substitution policy predecessor does not reconcile'
                USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.guard_item_substitution_policy_mutation() RETURNS trigger
LANGUAGE plpgsql SET search_path TO 'pg_catalog', 'public' AS $$
BEGIN
    IF TG_OP = 'DELETE' OR OLD.effective_to IS NOT NULL
       OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM OLD.facility_id
       OR NEW.source_item_id IS DISTINCT FROM OLD.source_item_id
       OR NEW.source_uom IS DISTINCT FROM OLD.source_uom
       OR NEW.substitute_item_id IS DISTINCT FROM OLD.substitute_item_id
       OR NEW.substitute_uom IS DISTINCT FROM OLD.substitute_uom
       OR NEW.source_qty IS DISTINCT FROM OLD.source_qty
       OR NEW.substitute_qty IS DISTINCT FROM OLD.substitute_qty
       OR NEW.revision IS DISTINCT FROM OLD.revision
       OR NEW.supersedes_policy_id IS DISTINCT FROM OLD.supersedes_policy_id
       OR NEW.effective_from IS DISTINCT FROM OLD.effective_from
       OR NEW.configured_by_user_id IS DISTINCT FROM OLD.configured_by_user_id
       OR NEW.configured_at IS DISTINCT FROM OLD.configured_at
       OR NEW.effective_to IS NULL OR NEW.effective_to <= OLD.effective_from
       OR (OLD.retired_by_user_id IS NOT NULL)
    THEN
        RAISE EXCEPTION 'item substitution policy versions are immutable except closure'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.require_item_substitution_policy_closure() RETURNS trigger
LANGUAGE plpgsql SET search_path TO 'pg_catalog', 'public' AS $$
BEGIN
    IF NEW.effective_to IS NULL THEN
        RETURN NULL;
    END IF;
    IF NEW.retired_by_user_id IS NULL AND NOT EXISTS (
        SELECT 1 FROM public.item_substitution_policies successor
        WHERE successor.tenant_id = NEW.tenant_id
          AND successor.inventory_owner_id = NEW.inventory_owner_id
          AND successor.facility_id = NEW.facility_id
          AND successor.source_item_id = NEW.source_item_id
          AND successor.source_uom = NEW.source_uom
          AND successor.substitute_item_id = NEW.substitute_item_id
          AND successor.substitute_uom = NEW.substitute_uom
          AND successor.supersedes_policy_id = NEW.id
          AND successor.revision = NEW.revision + 1
          AND successor.effective_from = NEW.effective_to)
    THEN
        RAISE EXCEPTION 'closed item substitution policy requires retirement or successor'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE TRIGGER item_substitution_policies_validate
BEFORE INSERT ON public.item_substitution_policies
FOR EACH ROW EXECUTE FUNCTION public.validate_item_substitution_policy();
CREATE TRIGGER item_substitution_policies_guard
BEFORE UPDATE OR DELETE ON public.item_substitution_policies
FOR EACH ROW EXECUTE FUNCTION public.guard_item_substitution_policy_mutation();
CREATE CONSTRAINT TRIGGER item_substitution_policies_require_closure
AFTER UPDATE OF effective_to, retired_by_user_id ON public.item_substitution_policies
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_item_substitution_policy_closure();

ALTER TABLE public.item_substitution_policies ENABLE ROW LEVEL SECURITY;
CREATE POLICY item_substitution_policies_tenant_isolation
ON public.item_substitution_policies
USING (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint)
WITH CHECK (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint);

GRANT SELECT, INSERT ON public.item_substitution_policies TO wareboxes_app;
GRANT UPDATE (effective_to, retired_by_user_id)
ON public.item_substitution_policies TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.item_substitution_policies_id_seq TO wareboxes_app;

REVOKE ALL ON FUNCTION public.validate_item_substitution_policy() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_item_substitution_policy_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_item_substitution_policy_closure() FROM PUBLIC;

-- Immutable execution evidence for resolving a pick shortage with approved
-- substitute demand on the same order and release.
CREATE TABLE public.pick_shortage_substitutions (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    order_release_id bigint NOT NULL,
    order_id bigint NOT NULL,
    pick_shortage_id bigint NOT NULL,
    policy_id bigint NOT NULL,
    policy_revision bigint NOT NULL CHECK (policy_revision > 0),
    source_order_item_id bigint NOT NULL,
    source_reservation_id bigint NOT NULL,
    source_item_id bigint NOT NULL,
    source_uom text NOT NULL,
    substitute_order_item_id bigint NOT NULL,
    substitute_reservation_id bigint NOT NULL,
    substitute_item_id bigint NOT NULL,
    substitute_uom text NOT NULL,
    accepted_source_qty bigint NOT NULL CHECK (accepted_source_qty > 0),
    substitute_qty bigint NOT NULL CHECK (substitute_qty > 0),
    expected_shortage_revision bigint NOT NULL CHECK (expected_shortage_revision > 0),
    resulting_shortage_revision bigint NOT NULL,
    expected_order_revision bigint NOT NULL CHECK (expected_order_revision > 0),
    resulting_order_revision bigint NOT NULL,
    allocation_count bigint NOT NULL CHECK (allocation_count > 0),
    reason_code text NOT NULL CHECK (
        reason_code IN ('client_authorized','inventory_unavailable','service_recovery','other')),
    note text,
    substituted_by_user_id bigint NOT NULL,
    substituted_at timestamptz NOT NULL,
    CHECK (resulting_shortage_revision = expected_shortage_revision + 1),
    CHECK (resulting_order_revision = expected_order_revision + 1),
    CHECK (source_item_id <> substitute_item_id OR source_uom <> substitute_uom),
    CHECK (source_uom = btrim(source_uom) AND source_uom <> ''
           AND char_length(source_uom) <= 32),
    CHECK (substitute_uom = btrim(substitute_uom) AND substitute_uom <> ''
           AND char_length(substitute_uom) <= 32),
    CHECK (reason_code <> 'other' OR note IS NOT NULL),
    CHECK (note IS NULL OR (note=btrim(note) AND note<>'' AND char_length(note)<=500)),
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, inventory_owner_id, pick_shortage_id),
    UNIQUE (tenant_id, inventory_owner_id, facility_id, order_release_id, order_id,
            substitute_order_item_id, substitute_reservation_id, id),
    FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    FOREIGN KEY (tenant_id, inventory_owner_id, facility_id)
        REFERENCES public.inventory_owner_facilities(tenant_id, inventory_owner_id, facility_id),
    FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, order_release_id, order_id,
                 source_order_item_id, source_reservation_id, pick_shortage_id)
        REFERENCES public.pick_shortages(tenant_id, inventory_owner_id, facility_id,
                 order_release_id, order_id, order_item_id, reservation_id, id),
    FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, policy_id)
        REFERENCES public.item_substitution_policies(tenant_id, inventory_owner_id, facility_id, id),
    FOREIGN KEY (tenant_id, inventory_owner_id, order_id, source_order_item_id)
        REFERENCES public.order_items(tenant_id, inventory_owner_id, order_id, id),
    FOREIGN KEY (tenant_id, inventory_owner_id, order_id, substitute_order_item_id)
        REFERENCES public.order_items(tenant_id, inventory_owner_id, order_id, id)
        DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, source_reservation_id)
        REFERENCES public.inventory_reservations(tenant_id, inventory_owner_id, facility_id, id),
    FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, substitute_reservation_id)
        REFERENCES public.inventory_reservations(tenant_id, inventory_owner_id, facility_id, id)
        DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (tenant_id, source_item_id) REFERENCES public.items(tenant_id, id),
    FOREIGN KEY (tenant_id, substitute_item_id) REFERENCES public.items(tenant_id, id),
    FOREIGN KEY (tenant_id, substituted_by_user_id)
        REFERENCES public.tenant_memberships(tenant_id, user_id)
);
ALTER TABLE public.pick_shortage_substitutions FORCE ROW LEVEL SECURITY;

ALTER TABLE public.order_release_allocations
    ADD COLUMN item_substitution_id bigint;
ALTER TABLE public.order_release_allocations
    DROP CONSTRAINT order_release_allocations_recovery_check;
ALTER TABLE public.order_release_allocations
    DROP CONSTRAINT order_release_allocations_source_kind_check;
ALTER TABLE public.order_release_allocations
    ADD CONSTRAINT order_release_allocations_recovery_check CHECK (
        (source_kind='initial' AND pick_shortage_id IS NULL
         AND pick_shortage_reallocation_run_id IS NULL AND item_substitution_id IS NULL)
        OR
        (source_kind='shortage_recovery' AND pick_shortage_id IS NOT NULL
         AND pick_shortage_reallocation_run_id IS NOT NULL AND item_substitution_id IS NULL)
        OR
        (source_kind='item_substitution' AND pick_shortage_id IS NULL
         AND pick_shortage_reallocation_run_id IS NULL AND item_substitution_id IS NOT NULL));
ALTER TABLE public.order_release_allocations
    ADD CONSTRAINT order_release_allocations_source_kind_check CHECK (
        source_kind IN ('initial','shortage_recovery','item_substitution'));
ALTER TABLE public.order_release_allocations
    ADD CONSTRAINT order_release_allocations_item_substitution_fkey
    FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, order_release_id, order_id,
                 order_item_id, reservation_id, item_substitution_id)
    REFERENCES public.pick_shortage_substitutions(
        tenant_id, inventory_owner_id, facility_id, order_release_id, order_id,
        substitute_order_item_id, substitute_reservation_id, id)
    DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX order_release_allocations_item_substitution_idx
ON public.order_release_allocations (
    tenant_id,inventory_owner_id,item_substitution_id,allocation_id)
WHERE source_kind='item_substitution';

CREATE FUNCTION public.validate_pick_shortage_substitution() RETURNS trigger
LANGUAGE plpgsql SET search_path TO 'pg_catalog', 'public' AS $$
DECLARE
    shortage public.pick_shortages%ROWTYPE;
    policy public.item_substitution_policies%ROWTYPE;
    order_revision bigint;
BEGIN
    SELECT * INTO shortage FROM public.pick_shortages
    WHERE tenant_id=NEW.tenant_id AND inventory_owner_id=NEW.inventory_owner_id
      AND id=NEW.pick_shortage_id FOR SHARE;
    SELECT * INTO policy FROM public.item_substitution_policies
    WHERE tenant_id=NEW.tenant_id AND inventory_owner_id=NEW.inventory_owner_id
      AND facility_id=NEW.facility_id AND id=NEW.policy_id FOR SHARE;
    SELECT revision INTO order_revision FROM public.orders
    WHERE tenant_id=NEW.tenant_id AND inventory_owner_id=NEW.inventory_owner_id
      AND id=NEW.order_id FOR SHARE;
    IF shortage.id IS NULL OR policy.id IS NULL
       OR shortage.status <> 'awaiting_inventory' OR shortage.resolution IS NOT NULL
       OR shortage.revision <> NEW.expected_shortage_revision
       OR order_revision <> NEW.expected_order_revision
       OR shortage.order_release_id <> NEW.order_release_id
       OR shortage.order_id <> NEW.order_id
       OR shortage.order_item_id <> NEW.source_order_item_id
       OR shortage.reservation_id <> NEW.source_reservation_id
       OR shortage.item_id <> NEW.source_item_id OR shortage.uom <> NEW.source_uom
       OR shortage.reallocated_qty <> shortage.recovery_terminal_qty
       OR shortage.remaining_to_allocate_qty <> NEW.accepted_source_qty
       OR policy.revision <> NEW.policy_revision OR policy.effective_to IS NOT NULL
       OR policy.source_item_id <> NEW.source_item_id OR policy.source_uom <> NEW.source_uom
       OR policy.substitute_item_id <> NEW.substitute_item_id
       OR policy.substitute_uom <> NEW.substitute_uom
       OR NEW.accepted_source_qty * policy.substitute_qty
          <> NEW.substitute_qty * policy.source_qty
    THEN
        RAISE EXCEPTION 'pick shortage substitution preconditions do not reconcile'
            USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.reject_pick_shortage_substitution_mutation() RETURNS trigger
LANGUAGE plpgsql SET search_path TO 'pg_catalog', 'public' AS $$
BEGIN
    RAISE EXCEPTION 'pick shortage substitution evidence is immutable'
        USING ERRCODE='55000';
END;
$$;

CREATE FUNCTION public.validate_item_substitution_release_snapshot() RETURNS trigger
LANGUAGE plpgsql SET search_path TO 'pg_catalog', 'public' AS $$
BEGIN
    IF NEW.source_kind <> 'item_substitution' THEN
        RETURN NEW;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.pick_shortage_substitutions substitution
        WHERE substitution.tenant_id=NEW.tenant_id
          AND substitution.inventory_owner_id=NEW.inventory_owner_id
          AND substitution.facility_id=NEW.facility_id
          AND substitution.order_release_id=NEW.order_release_id
          AND substitution.order_id=NEW.order_id
          AND substitution.substitute_order_item_id=NEW.order_item_id
          AND substitution.substitute_reservation_id=NEW.reservation_id
          AND substitution.substitute_item_id=NEW.item_id
          AND substitution.substitute_uom=NEW.uom
          AND substitution.id=NEW.item_substitution_id)
    THEN
        RAISE EXCEPTION 'substitute release snapshot does not match immutable substitution evidence'
            USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.require_pick_shortage_substitution_consistency() RETURNS trigger
LANGUAGE plpgsql SET search_path TO 'pg_catalog', 'public' AS $$
DECLARE
    substitution_id bigint;
    substitution public.pick_shortage_substitutions%ROWTYPE;
    snapshot_count bigint;
    snapshot_qty bigint;
    task_count bigint;
    content_count bigint;
BEGIN
    IF TG_TABLE_NAME='pick_shortage_substitutions' THEN
        substitution_id:=NEW.id;
    ELSIF TG_TABLE_NAME='order_release_allocations' THEN
        substitution_id:=NEW.item_substitution_id;
    ELSE
        SELECT snapshot.item_substitution_id INTO substitution_id
        FROM public.order_release_allocations snapshot
        WHERE snapshot.tenant_id=NEW.tenant_id
          AND snapshot.inventory_owner_id=NEW.inventory_owner_id
          AND snapshot.facility_id=NEW.facility_id
          AND snapshot.order_release_id=NEW.order_release_id
          AND snapshot.order_id=NEW.order_id
          AND snapshot.order_item_id=NEW.order_item_id
          AND snapshot.reservation_id=NEW.reservation_id
          AND snapshot.allocation_id=NEW.source_allocation_id
          AND snapshot.source_kind='item_substitution';
    END IF;
    IF substitution_id IS NULL THEN RETURN NULL; END IF;
    SELECT * INTO substitution FROM public.pick_shortage_substitutions
    WHERE tenant_id=NEW.tenant_id AND id=substitution_id;

    SELECT COUNT(*),COALESCE(SUM(planned_qty),0) INTO snapshot_count,snapshot_qty
    FROM public.order_release_allocations
    WHERE tenant_id=substitution.tenant_id
      AND item_substitution_id=substitution.id AND source_kind='item_substitution';
    SELECT COUNT(*) INTO task_count FROM public.pick_tasks task
    JOIN public.order_release_allocations snapshot
      ON snapshot.tenant_id=task.tenant_id
     AND snapshot.inventory_owner_id=task.inventory_owner_id
     AND snapshot.facility_id=task.facility_id
     AND snapshot.order_release_id=task.order_release_id
     AND snapshot.order_id=task.order_id AND snapshot.order_item_id=task.order_item_id
     AND snapshot.reservation_id=task.reservation_id
     AND snapshot.allocation_id=task.source_allocation_id
    WHERE snapshot.tenant_id=substitution.tenant_id
      AND snapshot.item_substitution_id=substitution.id;
    SELECT COUNT(*) INTO content_count FROM public.pick_task_contents content
    JOIN public.order_release_allocations snapshot
      ON snapshot.tenant_id=content.tenant_id
     AND snapshot.inventory_owner_id=content.inventory_owner_id
     AND snapshot.facility_id=content.facility_id
     AND snapshot.order_release_id=content.order_release_id
     AND snapshot.order_id=content.order_id AND snapshot.order_item_id=content.order_item_id
     AND snapshot.reservation_id=content.reservation_id
     AND snapshot.allocation_id=content.source_allocation_id
    WHERE snapshot.tenant_id=substitution.tenant_id
      AND snapshot.item_substitution_id=substitution.id;

    IF snapshot_count<>substitution.allocation_count
       OR snapshot_qty<>substitution.substitute_qty
       OR task_count<>snapshot_count OR content_count<>snapshot_count
       OR NOT EXISTS (
           SELECT 1 FROM public.order_items item
           WHERE item.tenant_id=substitution.tenant_id
             AND item.inventory_owner_id=substitution.inventory_owner_id
             AND item.order_id=substitution.order_id
             AND item.id=substitution.substitute_order_item_id
             AND item.item_id=substitution.substitute_item_id
             AND item.uom=substitution.substitute_uom
             AND item.qty=substitution.substitute_qty AND item.deleted IS NULL
             AND item.created=substitution.substituted_at)
       OR NOT EXISTS (
           SELECT 1 FROM public.inventory_reservations reservation
           WHERE reservation.tenant_id=substitution.tenant_id
             AND reservation.inventory_owner_id=substitution.inventory_owner_id
             AND reservation.facility_id=substitution.facility_id
             AND reservation.id=substitution.substitute_reservation_id
             AND reservation.order_id=substitution.order_id
             AND reservation.order_item_id=substitution.substitute_order_item_id
             AND reservation.item_id=substitution.substitute_item_id
             AND reservation.uom=substitution.substitute_uom
             AND reservation.qty=substitution.substitute_qty
             AND reservation.status IN ('active','fulfilled')
             AND reservation.created=substitution.substituted_at)
       OR NOT EXISTS (
           SELECT 1 FROM public.pick_shortages shortage
           WHERE shortage.tenant_id=substitution.tenant_id
             AND shortage.id=substitution.pick_shortage_id
             AND shortage.status='resolved' AND shortage.resolution='substituted'
             AND shortage.accepted_substitute_qty=substitution.accepted_source_qty
             AND shortage.revision=substitution.resulting_shortage_revision
             AND shortage.resolved_by_user_id=substitution.substituted_by_user_id
             AND shortage.resolved_at=substitution.substituted_at)
       OR NOT EXISTS (
           SELECT 1 FROM public.orders order_header
           WHERE order_header.tenant_id=substitution.tenant_id
             AND order_header.id=substitution.order_id
             AND order_header.status IN (
                 'processing','awaiting packing','awaiting shipment','shipped')
             AND order_header.revision>=substitution.resulting_order_revision)
    THEN
        RAISE EXCEPTION 'pick shortage substitution does not reconcile to derived demand and work'
            USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE TRIGGER pick_shortage_substitutions_validate
BEFORE INSERT ON public.pick_shortage_substitutions
FOR EACH ROW EXECUTE FUNCTION public.validate_pick_shortage_substitution();
CREATE TRIGGER pick_shortage_substitutions_immutable
BEFORE UPDATE OR DELETE ON public.pick_shortage_substitutions
FOR EACH ROW EXECUTE FUNCTION public.reject_pick_shortage_substitution_mutation();
CREATE TRIGGER order_release_allocations_validate_substitution
BEFORE INSERT ON public.order_release_allocations
FOR EACH ROW EXECUTE FUNCTION public.validate_item_substitution_release_snapshot();
CREATE CONSTRAINT TRIGGER pick_shortage_substitutions_reconcile
AFTER INSERT ON public.pick_shortage_substitutions DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_pick_shortage_substitution_consistency();
CREATE CONSTRAINT TRIGGER order_release_allocations_substitution_reconcile
AFTER INSERT ON public.order_release_allocations DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_pick_shortage_substitution_consistency();
CREATE CONSTRAINT TRIGGER pick_tasks_substitution_reconcile
AFTER INSERT OR UPDATE ON public.pick_tasks DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_pick_shortage_substitution_consistency();
CREATE CONSTRAINT TRIGGER pick_task_contents_substitution_reconcile
AFTER INSERT OR UPDATE ON public.pick_task_contents DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_pick_shortage_substitution_consistency();
CREATE CONSTRAINT TRIGGER pick_shortage_substitutions_require_shortage_consistency
AFTER INSERT ON public.pick_shortage_substitutions DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_pick_shortage_consistency();

ALTER TABLE public.pick_shortage_substitutions ENABLE ROW LEVEL SECURITY;
CREATE POLICY pick_shortage_substitutions_tenant_isolation
ON public.pick_shortage_substitutions
USING (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint)
WITH CHECK (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint);
GRANT SELECT,INSERT ON public.pick_shortage_substitutions TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.pick_shortage_substitutions_id_seq TO wareboxes_app;
GRANT UPDATE (accepted_substitute_qty) ON public.pick_shortages TO wareboxes_app;
REVOKE ALL ON FUNCTION public.validate_pick_shortage_substitution() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.reject_pick_shortage_substitution_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_item_substitution_release_snapshot() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_pick_shortage_substitution_consistency() FROM PUBLIC;

CREATE OR REPLACE VIEW public.outbound_effective_demand
WITH (security_invoker='true') AS
SELECT order_line.tenant_id,
       order_line.inventory_owner_id,
       order_line.order_id,
       order_line.id AS order_item_id,
       order_line.item_id,
       order_line.uom,
       (order_line.qty - COALESCE(backorder.backordered_qty,0))::bigint AS original_qty,
       COALESCE(short_ship.accepted_short_qty,0)::bigint AS accepted_short_qty,
       (order_line.qty - COALESCE(backorder.backordered_qty,0)
        - COALESCE(short_ship.accepted_short_qty,0)
        - COALESCE(substitution.accepted_substitute_qty,0))::bigint AS effective_qty,
       COALESCE(backorder.backordered_qty,0)::bigint AS backordered_qty,
       COALESCE(substitution.accepted_substitute_qty,0)::bigint AS accepted_substitute_qty
FROM public.order_items order_line
LEFT JOIN (
    SELECT tenant_id,inventory_owner_id,parent_order_id AS order_id,
           parent_order_item_id AS order_item_id,
           SUM(newly_backordered_qty) AS backordered_qty
    FROM public.order_backorder_split_lines
    GROUP BY tenant_id,inventory_owner_id,parent_order_id,parent_order_item_id
) backorder ON backorder.tenant_id=order_line.tenant_id
 AND backorder.inventory_owner_id=order_line.inventory_owner_id
 AND backorder.order_id=order_line.order_id AND backorder.order_item_id=order_line.id
LEFT JOIN (
    SELECT tenant_id,inventory_owner_id,order_id,order_item_id,
           SUM(accepted_short_qty) AS accepted_short_qty
    FROM public.pick_short_ship_dispositions
    GROUP BY tenant_id,inventory_owner_id,order_id,order_item_id
) short_ship ON short_ship.tenant_id=order_line.tenant_id
 AND short_ship.inventory_owner_id=order_line.inventory_owner_id
 AND short_ship.order_id=order_line.order_id AND short_ship.order_item_id=order_line.id
LEFT JOIN (
    SELECT tenant_id,inventory_owner_id,order_id,
           source_order_item_id AS order_item_id,
           SUM(accepted_source_qty) AS accepted_substitute_qty
    FROM public.pick_shortage_substitutions
    GROUP BY tenant_id,inventory_owner_id,order_id,source_order_item_id
) substitution ON substitution.tenant_id=order_line.tenant_id
 AND substitution.inventory_owner_id=order_line.inventory_owner_id
 AND substitution.order_id=order_line.order_id
 AND substitution.order_item_id=order_line.id
WHERE order_line.deleted IS NULL;

-- Reversible open-carton packing with immutable attempt and removal evidence.

ALTER TABLE ONLY public.carton_contents
    DROP CONSTRAINT carton_contents_session_allocation_key;
ALTER TABLE ONLY public.carton_contents
    ADD CONSTRAINT carton_contents_owner_id_key
    UNIQUE (tenant_id, inventory_owner_id, id);
CREATE INDEX carton_contents_session_allocation_history_idx
ON public.carton_contents
    (tenant_id, inventory_owner_id, packing_session_id,
     packing_session_allocation_id, packed_at, id);

CREATE TABLE public.packing_allocation_positions (
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    packing_session_id bigint NOT NULL,
    packing_session_allocation_id bigint NOT NULL,
    order_id bigint NOT NULL,
    order_item_id bigint NOT NULL,
    reservation_id bigint NOT NULL,
    state text DEFAULT 'available' NOT NULL,
    current_carton_content_id bigint,
    current_inventory_allocation_id bigint NOT NULL,
    current_inventory_balance_id bigint NOT NULL,
    current_location_id bigint NOT NULL,
    current_license_plate_id bigint NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    positioned_at timestamp with time zone NOT NULL,
    CONSTRAINT packing_allocation_positions_pkey
        PRIMARY KEY (tenant_id, packing_session_allocation_id),
    CONSTRAINT packing_allocation_positions_scope_key UNIQUE
        (tenant_id, inventory_owner_id, facility_id, packing_session_id,
         packing_session_allocation_id),
    CONSTRAINT packing_allocation_positions_state_check CHECK (
        (state='available' AND current_carton_content_id IS NULL)
        OR (state='packed' AND current_carton_content_id IS NOT NULL)
    ),
    CONSTRAINT packing_allocation_positions_revision_check CHECK (revision > 0),
    CONSTRAINT packing_allocation_positions_snapshot_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, facility_id, packing_session_id,
         packing_session_allocation_id)
        REFERENCES public.packing_session_allocations
        (tenant_id, inventory_owner_id, facility_id, packing_session_id, id),
    CONSTRAINT packing_allocation_positions_order_item_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, order_id, order_item_id)
        REFERENCES public.order_items
        (tenant_id, inventory_owner_id, order_id, id),
    CONSTRAINT packing_allocation_positions_allocation_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, facility_id, current_inventory_allocation_id)
        REFERENCES public.inventory_allocations
        (tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT packing_allocation_positions_balance_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, facility_id, current_inventory_balance_id)
        REFERENCES public.inventory_balances
        (tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT packing_allocation_positions_location_fkey FOREIGN KEY
        (tenant_id, facility_id, current_location_id)
        REFERENCES public.locations(tenant_id, facility_id, id),
    CONSTRAINT packing_allocation_positions_plate_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, facility_id, current_license_plate_id)
        REFERENCES public.license_plates
        (tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT packing_allocation_positions_content_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, current_carton_content_id)
        REFERENCES public.carton_contents
        (tenant_id, inventory_owner_id, id)
        DEFERRABLE INITIALLY DEFERRED
);
ALTER TABLE public.packing_allocation_positions FORCE ROW LEVEL SECURITY;

CREATE TABLE public.carton_content_removals (
    id bigint GENERATED ALWAYS AS IDENTITY
        (SEQUENCE NAME public.carton_content_removals_id_seq) PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    packing_session_id bigint NOT NULL,
    carton_id bigint NOT NULL,
    carton_content_id bigint NOT NULL,
    packing_session_allocation_id bigint NOT NULL,
    order_id bigint NOT NULL,
    order_item_id bigint NOT NULL,
    reservation_id bigint NOT NULL,
    inventory_transaction_id bigint NOT NULL,
    source_inventory_allocation_id bigint NOT NULL,
    destination_inventory_allocation_id bigint NOT NULL,
    source_inventory_balance_id bigint NOT NULL,
    destination_inventory_balance_id bigint NOT NULL,
    source_location_id bigint NOT NULL,
    destination_location_id bigint NOT NULL,
    source_license_plate_id bigint NOT NULL,
    destination_license_plate_id bigint NOT NULL,
    item_batch_id bigint NOT NULL,
    item_id bigint NOT NULL,
    uom text NOT NULL,
    inventory_status text NOT NULL,
    removed_qty bigint NOT NULL,
    reason_code text NOT NULL,
    note text,
    expected_position_revision bigint NOT NULL,
    resulting_position_revision bigint NOT NULL,
    expected_packed_position_revision bigint NOT NULL,
    resulting_packed_position_revision bigint NOT NULL,
    expected_order_revision bigint NOT NULL,
    resulting_order_revision bigint NOT NULL,
    removed_by_user_id bigint NOT NULL,
    removed_at timestamp with time zone NOT NULL,
    CONSTRAINT carton_content_removals_scope_id_key UNIQUE
        (tenant_id, inventory_owner_id, facility_id, packing_session_id, id),
    CONSTRAINT carton_content_removals_carton_id_key UNIQUE
        (tenant_id, inventory_owner_id, facility_id, carton_id, id),
    CONSTRAINT carton_content_removals_content_key UNIQUE
        (tenant_id, inventory_owner_id, carton_content_id),
    CONSTRAINT carton_content_removals_transaction_key UNIQUE
        (tenant_id, inventory_owner_id, inventory_transaction_id),
    CONSTRAINT carton_content_removals_allocations_check CHECK
        (source_inventory_allocation_id<>destination_inventory_allocation_id),
    CONSTRAINT carton_content_removals_balances_check CHECK
        (source_inventory_balance_id<>destination_inventory_balance_id),
    CONSTRAINT carton_content_removals_plates_check CHECK
        (source_license_plate_id<>destination_license_plate_id),
    CONSTRAINT carton_content_removals_qty_check CHECK (removed_qty>0),
    CONSTRAINT carton_content_removals_status_check CHECK
        (inventory_status='available'),
    CONSTRAINT carton_content_removals_uom_check CHECK
        (uom=btrim(uom) AND uom<>''),
    CONSTRAINT carton_content_removals_reason_check CHECK
        (reason_code IN ('wrong_carton','wrong_item','quality_issue','damaged_carton','other')),
    CONSTRAINT carton_content_removals_note_check CHECK
        (note IS NULL OR (note=btrim(note) AND note<>'' AND char_length(note)<=500)),
    CONSTRAINT carton_content_removals_other_note_check CHECK
        (reason_code<>'other' OR note IS NOT NULL),
    CONSTRAINT carton_content_removals_position_revision_check CHECK
        (expected_position_revision>0
         AND resulting_position_revision=expected_position_revision+1),
    CONSTRAINT carton_content_removals_packed_position_revision_check CHECK
        (expected_packed_position_revision>0
         AND resulting_packed_position_revision=expected_packed_position_revision+1),
    CONSTRAINT carton_content_removals_order_revision_check CHECK
        (expected_order_revision>0
         AND resulting_order_revision=expected_order_revision+1),
    CONSTRAINT carton_content_removals_position_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, facility_id, packing_session_id,
         packing_session_allocation_id)
        REFERENCES public.packing_allocation_positions
        (tenant_id, inventory_owner_id, facility_id, packing_session_id,
         packing_session_allocation_id),
    CONSTRAINT carton_content_removals_content_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, facility_id, carton_id, carton_content_id)
        REFERENCES public.carton_contents
        (tenant_id, inventory_owner_id, facility_id, carton_id, id),
    CONSTRAINT carton_content_removals_source_allocation_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, facility_id, source_inventory_allocation_id)
        REFERENCES public.inventory_allocations
        (tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT carton_content_removals_destination_allocation_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, facility_id, destination_inventory_allocation_id)
        REFERENCES public.inventory_allocations
        (tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT carton_content_removals_source_balance_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, facility_id, source_inventory_balance_id)
        REFERENCES public.inventory_balances
        (tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT carton_content_removals_destination_balance_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, facility_id, destination_inventory_balance_id)
        REFERENCES public.inventory_balances
        (tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT carton_content_removals_source_location_fkey FOREIGN KEY
        (tenant_id, facility_id, source_location_id)
        REFERENCES public.locations(tenant_id, facility_id, id),
    CONSTRAINT carton_content_removals_destination_location_fkey FOREIGN KEY
        (tenant_id, facility_id, destination_location_id)
        REFERENCES public.locations(tenant_id, facility_id, id),
    CONSTRAINT carton_content_removals_source_plate_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, facility_id, source_license_plate_id)
        REFERENCES public.license_plates
        (tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT carton_content_removals_destination_plate_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, facility_id, destination_license_plate_id)
        REFERENCES public.license_plates
        (tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT carton_content_removals_item_batch_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, item_batch_id)
        REFERENCES public.item_batches(tenant_id, inventory_owner_id, id),
    CONSTRAINT carton_content_removals_item_fkey FOREIGN KEY
        (tenant_id, item_id) REFERENCES public.items(tenant_id, id),
    CONSTRAINT carton_content_removals_transaction_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, inventory_transaction_id)
        REFERENCES public.inventory_transactions(tenant_id, inventory_owner_id, id),
    CONSTRAINT carton_content_removals_actor_fkey FOREIGN KEY
        (tenant_id, removed_by_user_id)
        REFERENCES public.tenant_memberships(tenant_id, user_id)
);
ALTER TABLE public.carton_content_removals FORCE ROW LEVEL SECURITY;

ALTER TABLE public.packed_inventory_positions
    ADD COLUMN carton_content_removal_id bigint,
    ADD COLUMN unpacked_at timestamp with time zone;
ALTER TABLE public.packed_inventory_positions
    DROP CONSTRAINT packed_inventory_positions_state_check,
    DROP CONSTRAINT packed_inventory_positions_fields_check;
ALTER TABLE public.packed_inventory_positions
    ADD CONSTRAINT packed_inventory_positions_state_check CHECK
        (state IN ('packed','staged','loaded','departed','unpacked')),
    ADD CONSTRAINT packed_inventory_positions_fields_check CHECK (
        (state='packed'
         AND outbound_load_id IS NULL AND outbound_load_carton_id IS NULL
         AND load_sequence IS NULL
         AND current_inventory_allocation_id IS NOT NULL
         AND current_inventory_balance_id IS NOT NULL
         AND current_location_id IS NOT NULL AND current_license_plate_id IS NOT NULL
         AND departure_inventory_transaction_id IS NULL AND departed_at IS NULL
         AND carton_content_removal_id IS NULL AND unpacked_at IS NULL)
        OR (state='staged'
         AND outbound_load_id IS NOT NULL AND outbound_load_carton_id IS NOT NULL
         AND load_sequence IS NOT NULL
         AND current_inventory_allocation_id IS NOT NULL
         AND current_inventory_balance_id IS NOT NULL
         AND current_location_id IS NOT NULL AND current_license_plate_id IS NOT NULL
         AND departure_inventory_transaction_id IS NULL AND departed_at IS NULL
         AND carton_content_removal_id IS NULL AND unpacked_at IS NULL)
        OR (state='loaded'
         AND outbound_load_id IS NOT NULL AND outbound_load_carton_id IS NOT NULL
         AND load_sequence IS NOT NULL
         AND current_inventory_allocation_id IS NOT NULL
         AND current_inventory_balance_id IS NOT NULL
         AND current_location_id IS NOT NULL AND current_license_plate_id IS NOT NULL
         AND departure_inventory_transaction_id IS NULL AND departed_at IS NULL
         AND carton_content_removal_id IS NULL AND unpacked_at IS NULL)
        OR (state='departed'
         AND ((outbound_load_id IS NULL AND outbound_load_carton_id IS NULL AND load_sequence IS NULL)
              OR (outbound_load_id IS NOT NULL AND outbound_load_carton_id IS NOT NULL AND load_sequence IS NOT NULL))
         AND current_inventory_allocation_id IS NULL
         AND current_inventory_balance_id IS NULL
         AND current_location_id IS NULL AND current_license_plate_id IS NULL
         AND departure_inventory_transaction_id IS NOT NULL AND departed_at IS NOT NULL
         AND carton_content_removal_id IS NULL AND unpacked_at IS NULL)
        OR (state='unpacked'
         AND outbound_load_id IS NULL AND outbound_load_carton_id IS NULL
         AND load_sequence IS NULL
         AND current_inventory_allocation_id IS NULL
         AND current_inventory_balance_id IS NULL
         AND current_location_id IS NULL AND current_license_plate_id IS NULL
         AND departure_inventory_transaction_id IS NULL AND departed_at IS NULL
         AND carton_content_removal_id IS NOT NULL AND unpacked_at IS NOT NULL)
    );
ALTER TABLE public.packed_inventory_positions
    ADD CONSTRAINT packed_inventory_positions_removal_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, facility_id,
         carton_id, carton_content_removal_id)
        REFERENCES public.carton_content_removals
        (tenant_id, inventory_owner_id, facility_id, carton_id, id)
        DEFERRABLE INITIALLY DEFERRED;

CREATE INDEX packing_allocation_positions_session_state_idx
ON public.packing_allocation_positions
    (tenant_id, packing_session_id, state, packing_session_allocation_id);
CREATE INDEX carton_content_removals_session_idx
ON public.carton_content_removals
    (tenant_id, packing_session_id, removed_at, id);

CREATE FUNCTION public.initialize_packing_allocation_position() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
BEGIN
    INSERT INTO public.packing_allocation_positions (
        tenant_id,inventory_owner_id,facility_id,packing_session_id,
        packing_session_allocation_id,order_id,order_item_id,reservation_id,
        state,current_inventory_allocation_id,current_inventory_balance_id,
        current_location_id,current_license_plate_id,revision,positioned_at
    ) VALUES (
        NEW.tenant_id,NEW.inventory_owner_id,NEW.facility_id,NEW.packing_session_id,
        NEW.id,NEW.order_id,NEW.order_item_id,NEW.reservation_id,'available',
        NEW.source_inventory_allocation_id,NEW.source_inventory_balance_id,
        NEW.source_location_id,NEW.source_license_plate_id,1,
        (SELECT started_at FROM public.packing_sessions
         WHERE tenant_id=NEW.tenant_id AND id=NEW.packing_session_id)
    );
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.guard_packing_allocation_position_mutation() RETURNS trigger
LANGUAGE plpgsql SET search_path TO 'pg_catalog','public' AS $$
BEGIN
    IF TG_OP='DELETE' THEN
        RAISE EXCEPTION 'packing allocation positions cannot be deleted'
            USING ERRCODE='55000';
    END IF;
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM OLD.facility_id
       OR NEW.packing_session_id IS DISTINCT FROM OLD.packing_session_id
       OR NEW.packing_session_allocation_id IS DISTINCT FROM OLD.packing_session_allocation_id
       OR NEW.order_id IS DISTINCT FROM OLD.order_id
       OR NEW.order_item_id IS DISTINCT FROM OLD.order_item_id
       OR NEW.reservation_id IS DISTINCT FROM OLD.reservation_id
       OR NEW.revision<>OLD.revision+1 OR NEW.positioned_at<OLD.positioned_at
    THEN
        RAISE EXCEPTION 'packing allocation position identity or revision changed'
            USING ERRCODE='55000';
    END IF;
    IF NOT ((OLD.state='available' AND NEW.state='packed')
            OR (OLD.state='packed' AND NEW.state='available'))
    THEN
        RAISE EXCEPTION 'invalid packing allocation position transition'
            USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.require_packing_allocation_position_evidence() RETURNS trigger
LANGUAGE plpgsql SET search_path TO 'pg_catalog','public' AS $$
BEGIN
    IF NEW.state='packed' THEN
        IF NOT EXISTS (
            SELECT 1 FROM public.carton_contents content
            JOIN public.packed_inventory_positions packed
              ON packed.tenant_id=content.tenant_id
             AND packed.inventory_owner_id=content.inventory_owner_id
             AND packed.carton_content_id=content.id
             AND packed.state='packed'
            WHERE content.tenant_id=NEW.tenant_id
              AND content.inventory_owner_id=NEW.inventory_owner_id
              AND content.id=NEW.current_carton_content_id
              AND content.packing_session_allocation_id=NEW.packing_session_allocation_id
              AND content.destination_inventory_allocation_id=NEW.current_inventory_allocation_id
              AND content.destination_inventory_balance_id=NEW.current_inventory_balance_id
              AND content.destination_location_id=NEW.current_location_id
              AND content.destination_license_plate_id=NEW.current_license_plate_id
              AND content.packed_at=NEW.positioned_at)
        THEN
            RAISE EXCEPTION 'packed allocation position lacks exact content evidence'
                USING ERRCODE='23514';
        END IF;
    ELSIF NOT EXISTS (
        SELECT 1 FROM public.carton_content_removals removal
        WHERE removal.tenant_id=NEW.tenant_id
          AND removal.inventory_owner_id=NEW.inventory_owner_id
          AND removal.facility_id=NEW.facility_id
          AND removal.packing_session_id=NEW.packing_session_id
          AND removal.packing_session_allocation_id=NEW.packing_session_allocation_id
          AND removal.carton_content_id=OLD.current_carton_content_id
          AND removal.source_inventory_allocation_id=OLD.current_inventory_allocation_id
          AND removal.source_inventory_balance_id=OLD.current_inventory_balance_id
          AND removal.source_location_id=OLD.current_location_id
          AND removal.source_license_plate_id=OLD.current_license_plate_id
          AND removal.destination_inventory_allocation_id=NEW.current_inventory_allocation_id
          AND removal.destination_inventory_balance_id=NEW.current_inventory_balance_id
          AND removal.destination_location_id=NEW.current_location_id
          AND removal.destination_license_plate_id=NEW.current_license_plate_id
          AND removal.expected_position_revision=OLD.revision
          AND removal.resulting_position_revision=NEW.revision
          AND removal.removed_at=NEW.positioned_at)
    THEN
        RAISE EXCEPTION 'available packing allocation position lacks removal evidence'
            USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION public.reject_carton_content_removal_mutation() RETURNS trigger
LANGUAGE plpgsql SET search_path TO 'pg_catalog','public' AS $$
BEGIN
    RAISE EXCEPTION 'carton content removal evidence is immutable'
        USING ERRCODE='55000';
END;
$$;

CREATE FUNCTION public.validate_carton_content_removal() RETURNS trigger
LANGUAGE plpgsql SET search_path TO 'pg_catalog','public' AS $$
DECLARE valid boolean;
BEGIN
    SELECT session.state='open' AND carton.state='open'
           AND content.packing_session_id=NEW.packing_session_id
           AND content.packing_session_allocation_id=NEW.packing_session_allocation_id
           AND content.order_id=NEW.order_id AND content.order_item_id=NEW.order_item_id
           AND content.reservation_id=NEW.reservation_id
           AND content.item_batch_id=NEW.item_batch_id AND content.item_id=NEW.item_id
           AND content.uom=NEW.uom AND content.inventory_status=NEW.inventory_status
           AND content.packed_qty=NEW.removed_qty
           AND position.state='available' AND position.current_carton_content_id IS NULL
           AND position.current_inventory_allocation_id=NEW.destination_inventory_allocation_id
           AND position.current_inventory_balance_id=NEW.destination_inventory_balance_id
           AND position.current_location_id=NEW.destination_location_id
           AND position.current_license_plate_id=NEW.destination_license_plate_id
           AND position.revision=NEW.resulting_position_revision
           AND position.positioned_at=NEW.removed_at
           AND packed.state='unpacked' AND packed.carton_content_removal_id=NEW.id
           AND packed.revision=NEW.resulting_packed_position_revision
           AND packed.unpacked_at=NEW.removed_at
           AND source_allocation.status='fulfilled'
           AND source_allocation.deleted=NEW.removed_at
           AND source_allocation.execution_stage='packed'
           AND destination_allocation.status='allocated'
           AND destination_allocation.deleted IS NULL
           AND destination_allocation.execution_stage='staged'
           AND destination_allocation.reservation_id=NEW.reservation_id
           AND destination_allocation.inventory_balance_id=NEW.destination_inventory_balance_id
           AND destination_allocation.location_id=NEW.destination_location_id
           AND destination_allocation.license_plate_id=NEW.destination_license_plate_id
           AND destination_allocation.item_batch_id=NEW.item_batch_id
           AND destination_allocation.item_id=NEW.item_id
           AND destination_allocation.uom=NEW.uom
           AND destination_allocation.inventory_status=NEW.inventory_status
           AND destination_allocation.qty=NEW.removed_qty
           AND transaction.transaction_type='move'
           AND transaction.operation='packing.content.remove.v1'
           AND transaction.reference_type='carton_content'
           AND transaction.reference_id=NEW.carton_content_id
           AND transaction.actor_user_id=NEW.removed_by_user_id
    INTO valid
    FROM public.carton_contents content
    JOIN public.packing_sessions session
      ON session.tenant_id=content.tenant_id AND session.id=content.packing_session_id
    JOIN public.cartons carton
      ON carton.tenant_id=content.tenant_id AND carton.id=content.carton_id
    JOIN public.packing_allocation_positions position
      ON position.tenant_id=content.tenant_id
     AND position.packing_session_allocation_id=content.packing_session_allocation_id
    JOIN public.packed_inventory_positions packed
      ON packed.tenant_id=content.tenant_id AND packed.carton_content_id=content.id
    JOIN public.inventory_allocations source_allocation
      ON source_allocation.tenant_id=NEW.tenant_id
     AND source_allocation.id=NEW.source_inventory_allocation_id
    JOIN public.inventory_allocations destination_allocation
      ON destination_allocation.tenant_id=NEW.tenant_id
     AND destination_allocation.id=NEW.destination_inventory_allocation_id
    JOIN public.inventory_transactions transaction
      ON transaction.tenant_id=NEW.tenant_id
     AND transaction.inventory_owner_id=NEW.inventory_owner_id
     AND transaction.id=NEW.inventory_transaction_id
    WHERE content.tenant_id=NEW.tenant_id
      AND content.inventory_owner_id=NEW.inventory_owner_id
      AND content.facility_id=NEW.facility_id
      AND content.carton_id=NEW.carton_id AND content.id=NEW.carton_content_id;
    IF valid IS DISTINCT FROM TRUE
       OR (SELECT COUNT(*) FROM public.inventory_entries entry
           WHERE entry.tenant_id=NEW.tenant_id
             AND entry.inventory_owner_id=NEW.inventory_owner_id
             AND entry.transaction_id=NEW.inventory_transaction_id)<>2
       OR NOT EXISTS (
           SELECT 1 FROM public.inventory_entries entry
           WHERE entry.tenant_id=NEW.tenant_id
             AND entry.inventory_owner_id=NEW.inventory_owner_id
             AND entry.transaction_id=NEW.inventory_transaction_id
             AND entry.facility_id=NEW.facility_id
             AND entry.location_id=NEW.source_location_id
             AND entry.license_plate_id=NEW.source_license_plate_id
             AND entry.item_batch_id=NEW.item_batch_id
             AND entry.status=NEW.inventory_status
             AND entry.quantity_delta=-NEW.removed_qty)
       OR NOT EXISTS (
           SELECT 1 FROM public.inventory_entries entry
           WHERE entry.tenant_id=NEW.tenant_id
             AND entry.inventory_owner_id=NEW.inventory_owner_id
             AND entry.transaction_id=NEW.inventory_transaction_id
             AND entry.facility_id=NEW.facility_id
             AND entry.location_id=NEW.destination_location_id
             AND entry.license_plate_id=NEW.destination_license_plate_id
             AND entry.item_batch_id=NEW.item_batch_id
             AND entry.status=NEW.inventory_status
             AND entry.quantity_delta=NEW.removed_qty)
    THEN
        RAISE EXCEPTION 'carton content removal does not reconcile'
            USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;

