-- Closed-carton recovery is append-only evidence plus a guarded carton projection.
ALTER TABLE public.cartons
    ADD COLUMN reopen_count bigint DEFAULT 0 NOT NULL,
    ADD CONSTRAINT cartons_reopen_count_check CHECK (reopen_count >= 0);

CREATE TABLE public.carton_reopenings (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    packing_session_id bigint NOT NULL,
    order_release_id bigint NOT NULL,
    order_id bigint NOT NULL,
    carton_id bigint NOT NULL,
    previous_order_status text NOT NULL,
    resulting_order_status text NOT NULL,
    previous_session_state text NOT NULL,
    resulting_session_state text NOT NULL,
    expected_revision bigint NOT NULL,
    resulting_revision bigint NOT NULL,
    previous_reopen_count bigint NOT NULL,
    resulting_reopen_count bigint NOT NULL,
    previous_closed_by_user_id bigint NOT NULL,
    previous_closed_at timestamp with time zone NOT NULL,
    previous_weight_g bigint,
    previous_length_mm bigint,
    previous_width_mm bigint,
    previous_height_mm bigint,
    reason_code text NOT NULL,
    note text,
    reopened_by_user_id bigint NOT NULL,
    reopened_at timestamp with time zone NOT NULL,
    CONSTRAINT carton_reopenings_scope_id_key UNIQUE
        (tenant_id, inventory_owner_id, facility_id, packing_session_id, id),
    CONSTRAINT carton_reopenings_cycle_key UNIQUE
        (tenant_id, inventory_owner_id, facility_id, carton_id, resulting_reopen_count),
    CONSTRAINT carton_reopenings_status_check CHECK (
        previous_order_status IN ('packing', 'awaiting shipment')
        AND resulting_order_status = 'packing'
        AND previous_session_state IN ('open', 'ready_to_manifest')
        AND resulting_session_state = 'open'
        AND ((previous_order_status = 'packing' AND previous_session_state = 'open')
          OR (previous_order_status = 'awaiting shipment'
              AND previous_session_state = 'ready_to_manifest'))
    ),
    CONSTRAINT carton_reopenings_revision_check CHECK (
        expected_revision > 0 AND resulting_revision = expected_revision + 1
    ),
    CONSTRAINT carton_reopenings_cycle_check CHECK (
        previous_reopen_count >= 0
        AND resulting_reopen_count = previous_reopen_count + 1
    ),
    CONSTRAINT carton_reopenings_dimensions_check CHECK (
        (previous_length_mm IS NULL AND previous_width_mm IS NULL AND previous_height_mm IS NULL)
        OR (previous_length_mm > 0 AND previous_width_mm > 0 AND previous_height_mm > 0)
    ),
    CONSTRAINT carton_reopenings_weight_check CHECK (
        previous_weight_g IS NULL OR previous_weight_g > 0
    ),
    CONSTRAINT carton_reopenings_reason_check CHECK (
        reason_code IN ('packing_correction', 'quality_issue', 'order_cancellation', 'other')
    ),
    CONSTRAINT carton_reopenings_note_check CHECK (
        note IS NULL OR (note = btrim(note) AND note <> '' AND char_length(note) <= 500)
    ),
    CONSTRAINT carton_reopenings_other_note_check CHECK (
        reason_code <> 'other' OR note IS NOT NULL
    ),
    CONSTRAINT carton_reopenings_session_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, facility_id, order_release_id, order_id, packing_session_id)
        REFERENCES public.packing_sessions
        (tenant_id, inventory_owner_id, facility_id, order_release_id, order_id, id),
    CONSTRAINT carton_reopenings_carton_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, facility_id, packing_session_id, carton_id)
        REFERENCES public.cartons
        (tenant_id, inventory_owner_id, facility_id, packing_session_id, id),
    CONSTRAINT carton_reopenings_order_fkey FOREIGN KEY
        (tenant_id, inventory_owner_id, order_id)
        REFERENCES public.orders (tenant_id, inventory_owner_id, id),
    CONSTRAINT carton_reopenings_previous_actor_fkey FOREIGN KEY
        (tenant_id, previous_closed_by_user_id)
        REFERENCES public.tenant_memberships (tenant_id, user_id),
    CONSTRAINT carton_reopenings_actor_fkey FOREIGN KEY
        (tenant_id, reopened_by_user_id)
        REFERENCES public.tenant_memberships (tenant_id, user_id)
);

ALTER TABLE public.carton_reopenings FORCE ROW LEVEL SECURITY;

CREATE FUNCTION public.validate_carton_reopening() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    content_count bigint;
BEGIN
    SELECT COUNT(*) INTO content_count
    FROM public.carton_contents content
    INNER JOIN public.packing_allocation_positions position
      ON position.tenant_id = content.tenant_id
     AND position.inventory_owner_id = content.inventory_owner_id
     AND position.facility_id = content.facility_id
     AND position.packing_session_id = content.packing_session_id
     AND position.packing_session_allocation_id = content.packing_session_allocation_id
     AND position.current_carton_content_id = content.id
     AND position.state = 'packed'
    WHERE content.tenant_id = NEW.tenant_id
      AND content.inventory_owner_id = NEW.inventory_owner_id
      AND content.facility_id = NEW.facility_id
      AND content.packing_session_id = NEW.packing_session_id
      AND content.carton_id = NEW.carton_id;

    IF content_count <= 0
       OR NOT EXISTS (
            SELECT 1
            FROM public.cartons carton
            INNER JOIN public.packing_sessions session
              ON session.tenant_id = carton.tenant_id
             AND session.inventory_owner_id = carton.inventory_owner_id
             AND session.facility_id = carton.facility_id
             AND session.id = carton.packing_session_id
            INNER JOIN public.orders order_header
              ON order_header.tenant_id = carton.tenant_id
             AND order_header.inventory_owner_id = carton.inventory_owner_id
             AND order_header.id = carton.order_id
             AND order_header.deleted IS NULL
            WHERE carton.tenant_id = NEW.tenant_id
              AND carton.inventory_owner_id = NEW.inventory_owner_id
              AND carton.facility_id = NEW.facility_id
              AND carton.packing_session_id = NEW.packing_session_id
              AND carton.order_release_id = NEW.order_release_id
              AND carton.order_id = NEW.order_id
              AND carton.id = NEW.carton_id
              AND carton.state = 'closed'
              AND carton.reopen_count = NEW.previous_reopen_count
              AND carton.closed_by_user_id = NEW.previous_closed_by_user_id
              AND carton.closed_at = NEW.previous_closed_at
              AND carton.weight_g IS NOT DISTINCT FROM NEW.previous_weight_g
              AND carton.length_mm IS NOT DISTINCT FROM NEW.previous_length_mm
              AND carton.width_mm IS NOT DISTINCT FROM NEW.previous_width_mm
              AND carton.height_mm IS NOT DISTINCT FROM NEW.previous_height_mm
              AND session.order_release_id = NEW.order_release_id
              AND session.order_id = NEW.order_id
              AND session.state = NEW.previous_session_state
              AND session.revision = NEW.expected_revision
              AND session.open_carton_count = 0
              AND session.closed_carton_count > 0
              AND order_header.status = NEW.previous_order_status
              AND order_header.revision = NEW.expected_revision
              AND NEW.resulting_revision = NEW.expected_revision + 1
              AND NEW.resulting_reopen_count = carton.reopen_count + 1
              AND NEW.reopened_at >= carton.closed_at
       )
       OR EXISTS (
            SELECT 1 FROM public.outbound_qa_sessions qa
            WHERE qa.tenant_id = NEW.tenant_id
              AND qa.inventory_owner_id = NEW.inventory_owner_id
              AND qa.facility_id = NEW.facility_id
              AND qa.packing_session_id = NEW.packing_session_id
              AND qa.state <> 'cancelled'
       )
       OR EXISTS (
            SELECT 1 FROM public.shipments shipment
            WHERE shipment.tenant_id = NEW.tenant_id
              AND shipment.inventory_owner_id = NEW.inventory_owner_id
              AND shipment.facility_id = NEW.facility_id
              AND shipment.packing_session_id = NEW.packing_session_id
              AND shipment.state <> 'cancelled'
       )
    THEN
        RAISE EXCEPTION 'carton reopening does not match closed pre-downstream packing state'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.require_carton_reopening_consistency() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.cartons carton
        INNER JOIN public.packing_sessions session
          ON session.tenant_id = carton.tenant_id
         AND session.inventory_owner_id = carton.inventory_owner_id
         AND session.facility_id = carton.facility_id
         AND session.id = carton.packing_session_id
        INNER JOIN public.orders order_header
          ON order_header.tenant_id = carton.tenant_id
         AND order_header.inventory_owner_id = carton.inventory_owner_id
         AND order_header.id = carton.order_id
        WHERE carton.tenant_id = NEW.tenant_id
          AND carton.inventory_owner_id = NEW.inventory_owner_id
          AND carton.facility_id = NEW.facility_id
          AND carton.packing_session_id = NEW.packing_session_id
          AND carton.id = NEW.carton_id
          AND carton.state = 'open'
          AND carton.reopen_count = NEW.resulting_reopen_count
          AND carton.closed_by_user_id IS NULL
          AND carton.closed_at IS NULL
          AND carton.weight_g IS NULL
          AND carton.length_mm IS NULL
          AND carton.width_mm IS NULL
          AND carton.height_mm IS NULL
          AND session.state = 'open'
          AND session.revision = NEW.resulting_revision
          AND session.open_carton_count = 1
          AND order_header.status = 'packing'
          AND order_header.revision = NEW.resulting_revision
    ) THEN
        RAISE EXCEPTION 'carton reopening evidence and final packing state do not reconcile'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION public.require_carton_reopening_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.state = 'closed' AND NEW.state = 'open' AND NOT EXISTS (
        SELECT 1 FROM public.carton_reopenings reopening
        WHERE reopening.tenant_id = NEW.tenant_id
          AND reopening.inventory_owner_id = NEW.inventory_owner_id
          AND reopening.facility_id = NEW.facility_id
          AND reopening.packing_session_id = NEW.packing_session_id
          AND reopening.carton_id = NEW.id
          AND reopening.previous_reopen_count = OLD.reopen_count
          AND reopening.resulting_reopen_count = NEW.reopen_count
          AND reopening.previous_closed_by_user_id = OLD.closed_by_user_id
          AND reopening.previous_closed_at = OLD.closed_at
    ) THEN
        RAISE EXCEPTION 'carton reopening requires immutable evidence'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION public.reject_carton_reopening_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'carton reopenings are immutable'
        USING ERRCODE = '55000';
END;
$$;

CREATE OR REPLACE FUNCTION public.guard_packing_session_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM OLD.facility_id
       OR NEW.order_release_id IS DISTINCT FROM OLD.order_release_id
       OR NEW.order_id IS DISTINCT FROM OLD.order_id
       OR NEW.packing_location_id IS DISTINCT FROM OLD.packing_location_id
       OR NEW.expected_allocation_count IS DISTINCT FROM OLD.expected_allocation_count
       OR NEW.expected_qty IS DISTINCT FROM OLD.expected_qty
       OR NEW.started_by_user_id IS DISTINCT FROM OLD.started_by_user_id
       OR NEW.started_at IS DISTINCT FROM OLD.started_at
    THEN
        RAISE EXCEPTION 'packing session identity and plan are immutable'
            USING ERRCODE = '55000';
    END IF;

    IF OLD.state = 'abandoned' THEN
        RAISE EXCEPTION 'abandoned packing sessions are immutable'
            USING ERRCODE = '55000';
    END IF;

    IF OLD.state = 'ready_to_manifest' AND NEW.state = 'open' THEN
        IF NEW.revision <> OLD.revision + 1
           OR NEW.ready_by_user_id IS NOT NULL
           OR NEW.ready_at IS NOT NULL
           OR NEW.packed_allocation_count <> OLD.packed_allocation_count
           OR NEW.packed_qty <> OLD.packed_qty
           OR NEW.open_carton_count <> 1
           OR NEW.closed_carton_count <> OLD.closed_carton_count - 1
           OR NEW.abandonment_reason IS NOT NULL
           OR NEW.abandonment_note IS NOT NULL
           OR NEW.abandoned_by_user_id IS NOT NULL
           OR NEW.abandoned_at IS NOT NULL
        THEN
            RAISE EXCEPTION 'invalid completed-session carton reopening transition'
                USING ERRCODE = '55000';
        END IF;
    ELSIF NEW.state = 'open' THEN
        IF NEW.revision <> OLD.revision + 1
           OR NEW.ready_by_user_id IS NOT NULL
           OR NEW.ready_at IS NOT NULL
           OR NEW.abandonment_reason IS NOT NULL
           OR NEW.abandonment_note IS NOT NULL
           OR NEW.abandoned_by_user_id IS NOT NULL
           OR NEW.abandoned_at IS NOT NULL
        THEN
            RAISE EXCEPTION 'open packing session updates must advance revision once'
                USING ERRCODE = '55000';
        END IF;
    ELSIF NEW.state = 'ready_to_manifest' THEN
        IF OLD.state <> 'open'
           OR NEW.revision <> OLD.revision + 1
           OR NEW.ready_by_user_id IS NULL
           OR NEW.ready_at IS NULL
           OR NEW.abandonment_reason IS NOT NULL
           OR NEW.abandonment_note IS NOT NULL
           OR NEW.abandoned_by_user_id IS NOT NULL
           OR NEW.abandoned_at IS NOT NULL
        THEN
            RAISE EXCEPTION 'invalid packing session completion transition'
                USING ERRCODE = '55000';
        END IF;
    ELSIF NEW.state = 'abandoned' THEN
        IF OLD.state <> 'open'
           OR NEW.revision <> OLD.revision + 1
           OR NEW.ready_by_user_id IS NOT NULL
           OR NEW.ready_at IS NOT NULL
           OR NEW.abandonment_reason IS NULL
           OR NEW.abandoned_by_user_id IS NULL
           OR NEW.abandoned_at IS NULL
           OR NEW.abandoned_at < NEW.started_at
           OR NEW.packed_allocation_count <> 0
           OR NEW.packed_qty <> 0
           OR NEW.open_carton_count <> 0
           OR NEW.closed_carton_count <> 0
        THEN
            RAISE EXCEPTION 'invalid packing session abandonment transition'
                USING ERRCODE = '55000';
        END IF;
    ELSE
        RAISE EXCEPTION 'invalid packing session state'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.guard_carton_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM OLD.facility_id
       OR NEW.packing_session_id IS DISTINCT FROM OLD.packing_session_id
       OR NEW.order_release_id IS DISTINCT FROM OLD.order_release_id
       OR NEW.order_id IS DISTINCT FROM OLD.order_id
       OR NEW.packing_location_id IS DISTINCT FROM OLD.packing_location_id
       OR NEW.license_plate_id IS DISTINCT FROM OLD.license_plate_id
       OR NEW.created_by_user_id IS DISTINCT FROM OLD.created_by_user_id
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
    THEN
        RAISE EXCEPTION 'carton identity is immutable'
            USING ERRCODE = '55000';
    END IF;

    IF OLD.state = 'open' AND NEW.state IN ('closed', 'voided') THEN
        IF NEW.reopen_count <> OLD.reopen_count
           OR (NEW.state = 'closed' AND (
                NEW.closed_by_user_id IS NULL OR NEW.closed_at IS NULL
                OR NEW.voided_by_user_id IS NOT NULL OR NEW.voided_at IS NOT NULL
           ))
           OR (NEW.state = 'voided' AND (
                NEW.voided_by_user_id IS NULL OR NEW.voided_at IS NULL
                OR NEW.closed_by_user_id IS NOT NULL OR NEW.closed_at IS NOT NULL
           ))
        THEN
            RAISE EXCEPTION 'invalid open-carton terminal transition'
                USING ERRCODE = '55000';
        END IF;
    ELSIF OLD.state = 'closed' AND NEW.state = 'open' THEN
        IF NEW.reopen_count <> OLD.reopen_count + 1
           OR NEW.closed_by_user_id IS NOT NULL OR NEW.closed_at IS NOT NULL
           OR NEW.voided_by_user_id IS NOT NULL OR NEW.voided_at IS NOT NULL
           OR NEW.weight_g IS NOT NULL OR NEW.length_mm IS NOT NULL
           OR NEW.width_mm IS NOT NULL OR NEW.height_mm IS NOT NULL
        THEN
            RAISE EXCEPTION 'invalid closed-carton reopening transition'
                USING ERRCODE = '55000';
        END IF;
    ELSE
        RAISE EXCEPTION 'invalid carton lifecycle transition'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER carton_reopenings_validate
BEFORE INSERT ON public.carton_reopenings
FOR EACH ROW EXECUTE FUNCTION public.validate_carton_reopening();
CREATE CONSTRAINT TRIGGER carton_reopenings_validate_consistency
AFTER INSERT ON public.carton_reopenings DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_carton_reopening_consistency();
CREATE TRIGGER carton_reopenings_immutable
BEFORE UPDATE OR DELETE ON public.carton_reopenings
FOR EACH ROW EXECUTE FUNCTION public.reject_carton_reopening_mutation();
CREATE CONSTRAINT TRIGGER cartons_require_reopening_evidence
AFTER UPDATE ON public.cartons DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_carton_reopening_evidence();

ALTER TABLE public.carton_reopenings ENABLE ROW LEVEL SECURITY;
CREATE POLICY carton_reopenings_tenant_isolation
ON public.carton_reopenings
USING (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint)
WITH CHECK (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint);

GRANT SELECT,INSERT ON public.carton_reopenings TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.carton_reopenings_id_seq TO wareboxes_app;
REVOKE ALL ON FUNCTION public.validate_carton_reopening() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_carton_reopening_consistency() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_carton_reopening_evidence() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.reject_carton_reopening_mutation() FROM PUBLIC;

-- A cancelled outbound QA attempt remains immutable while allowing corrected
-- cartons to return to packing and begin a fresh numbered QA attempt.
ALTER TABLE public.outbound_qa_sessions
    ADD COLUMN attempt bigint NOT NULL DEFAULT 1,
    ADD COLUMN cancelled_by_user_id bigint,
    ADD COLUMN cancelled_at timestamp with time zone;
ALTER TABLE public.outbound_qa_sessions
    DROP CONSTRAINT outbound_qa_sessions_state_check,
    DROP CONSTRAINT outbound_qa_sessions_state_fields_check,
    DROP CONSTRAINT outbound_qa_sessions_policy_key;
ALTER TABLE public.outbound_qa_sessions
    ADD CONSTRAINT outbound_qa_sessions_state_check
        CHECK (state IN ('open', 'passed', 'cancelled')),
    ADD CONSTRAINT outbound_qa_sessions_attempt_check CHECK (attempt > 0),
    ADD CONSTRAINT outbound_qa_sessions_state_fields_check CHECK (
        (state = 'open'
         AND passed_by_user_id IS NULL AND passed_at IS NULL
         AND cancelled_by_user_id IS NULL AND cancelled_at IS NULL)
        OR (state = 'passed'
            AND passed_by_user_id IS NOT NULL AND passed_at IS NOT NULL
            AND passed_at >= started_at
            AND verified_carton_count = expected_carton_count
            AND cancelled_by_user_id IS NULL AND cancelled_at IS NULL)
        OR (state = 'cancelled'
            AND cancelled_by_user_id IS NOT NULL AND cancelled_at IS NOT NULL
            AND cancelled_at >= started_at
            AND ((passed_by_user_id IS NULL AND passed_at IS NULL)
                 OR (passed_by_user_id IS NOT NULL AND passed_at IS NOT NULL
                     AND passed_at >= started_at
                     AND verified_carton_count = expected_carton_count)))),
    ADD CONSTRAINT outbound_qa_sessions_policy_attempt_key
        UNIQUE (tenant_id, inventory_owner_id, facility_id,
                packing_session_id, policy_id, attempt),
    ADD CONSTRAINT outbound_qa_sessions_cancelled_by_fkey
        FOREIGN KEY (tenant_id, cancelled_by_user_id)
        REFERENCES public.tenant_memberships (tenant_id, user_id);
CREATE UNIQUE INDEX outbound_qa_sessions_active_policy_idx
ON public.outbound_qa_sessions
    (tenant_id, inventory_owner_id, facility_id, packing_session_id, policy_id)
WHERE state <> 'cancelled';

CREATE TABLE public.outbound_qa_cancellations (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    outbound_qa_session_id bigint NOT NULL,
    packing_session_id bigint NOT NULL,
    order_id bigint NOT NULL,
    policy_id bigint NOT NULL,
    attempt bigint NOT NULL,
    previous_state text NOT NULL,
    expected_session_revision bigint NOT NULL,
    resulting_session_revision bigint NOT NULL,
    verified_carton_count bigint NOT NULL,
    reason_code text NOT NULL,
    note text,
    cancelled_by_user_id bigint NOT NULL,
    cancelled_at timestamp with time zone NOT NULL,
    CONSTRAINT outbound_qa_cancellations_attempt_check CHECK (attempt > 0),
    CONSTRAINT outbound_qa_cancellations_state_check
        CHECK (previous_state IN ('open', 'passed')),
    CONSTRAINT outbound_qa_cancellations_revision_check CHECK (
        expected_session_revision > 0
        AND resulting_session_revision = expected_session_revision + 1),
    CONSTRAINT outbound_qa_cancellations_count_check CHECK (verified_carton_count >= 0),
    CONSTRAINT outbound_qa_cancellations_reason_check CHECK (
        reason_code IN ('packing_correction', 'quality_issue', 'policy_error',
                        'operator_error', 'other')),
    CONSTRAINT outbound_qa_cancellations_note_check CHECK (
        note IS NULL OR (note = btrim(note) AND note <> ''
                         AND char_length(note) <= 500)),
    CONSTRAINT outbound_qa_cancellations_other_note_check CHECK (
        reason_code <> 'other' OR note IS NOT NULL),
    CONSTRAINT outbound_qa_cancellations_scope_id_key UNIQUE (
        tenant_id, inventory_owner_id, facility_id,
        packing_session_id, outbound_qa_session_id, id),
    CONSTRAINT outbound_qa_cancellations_session_key UNIQUE (
        tenant_id, inventory_owner_id, facility_id,
        packing_session_id, outbound_qa_session_id),
    CONSTRAINT outbound_qa_cancellations_session_fkey FOREIGN KEY (
        tenant_id, inventory_owner_id, facility_id,
        packing_session_id, outbound_qa_session_id)
        REFERENCES public.outbound_qa_sessions (
            tenant_id, inventory_owner_id, facility_id, packing_session_id, id),
    CONSTRAINT outbound_qa_cancellations_policy_fkey FOREIGN KEY (
        tenant_id, inventory_owner_id, facility_id, policy_id)
        REFERENCES public.outbound_qa_policies (
            tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT outbound_qa_cancellations_actor_fkey FOREIGN KEY (
        tenant_id, cancelled_by_user_id)
        REFERENCES public.tenant_memberships (tenant_id, user_id)
);
ALTER TABLE public.outbound_qa_cancellations FORCE ROW LEVEL SECURITY;
CREATE INDEX outbound_qa_cancellations_order_idx
ON public.outbound_qa_cancellations (tenant_id, order_id, id);

CREATE OR REPLACE FUNCTION public.validate_outbound_qa_session() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE valid boolean;
DECLARE expected_attempt bigint;
BEGIN
    SELECT policy.requirement = 'scan_every_carton'
           AND policy.revision = NEW.policy_revision
           AND policy.effective_to IS NULL
           AND packing.state = 'ready_to_manifest'
           AND packing.revision = NEW.expected_order_revision
           AND packing.closed_carton_count = NEW.expected_carton_count
           AND orders.status = 'awaiting shipment'
           AND orders.revision = NEW.expected_order_revision
    INTO valid
    FROM public.outbound_qa_policies policy
    JOIN public.packing_sessions packing
      ON packing.tenant_id = policy.tenant_id
     AND packing.inventory_owner_id = policy.inventory_owner_id
     AND packing.facility_id = policy.facility_id
     AND packing.id = NEW.packing_session_id
     AND packing.order_id = NEW.order_id
    JOIN public.orders orders
      ON orders.tenant_id = packing.tenant_id
     AND orders.inventory_owner_id = packing.inventory_owner_id
     AND orders.id = packing.order_id AND orders.deleted IS NULL
    WHERE policy.tenant_id = NEW.tenant_id
      AND policy.inventory_owner_id = NEW.inventory_owner_id
      AND policy.facility_id = NEW.facility_id
      AND policy.id = NEW.policy_id
    FOR SHARE OF policy, packing, orders;

    SELECT COALESCE(MAX(session.attempt), 0) + 1 INTO expected_attempt
    FROM public.outbound_qa_sessions session
    WHERE session.tenant_id = NEW.tenant_id
      AND session.inventory_owner_id = NEW.inventory_owner_id
      AND session.facility_id = NEW.facility_id
      AND session.packing_session_id = NEW.packing_session_id
      AND session.policy_id = NEW.policy_id;

    IF valid IS DISTINCT FROM TRUE OR NEW.state <> 'open' OR NEW.revision <> 1
       OR NEW.verified_carton_count <> 0 OR NEW.attempt <> expected_attempt
       OR NEW.cancelled_by_user_id IS NOT NULL OR NEW.cancelled_at IS NOT NULL
       OR EXISTS (
           SELECT 1 FROM public.outbound_qa_sessions session
           WHERE session.tenant_id = NEW.tenant_id
             AND session.inventory_owner_id = NEW.inventory_owner_id
             AND session.facility_id = NEW.facility_id
             AND session.packing_session_id = NEW.packing_session_id
             AND session.policy_id = NEW.policy_id
             AND session.state <> 'cancelled')
    THEN
        RAISE EXCEPTION 'outbound QA session is not executable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.validate_outbound_qa_cancellation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE source record;
BEGIN
    SELECT session.state, session.revision, session.attempt,
           session.policy_id, session.verified_carton_count,
           session.started_at, session.passed_at,
           packing.state AS packing_state,
           orders.status AS order_status
    INTO source
    FROM public.outbound_qa_sessions session
    JOIN public.packing_sessions packing
      ON packing.tenant_id = session.tenant_id
     AND packing.inventory_owner_id = session.inventory_owner_id
     AND packing.facility_id = session.facility_id
     AND packing.id = session.packing_session_id
     AND packing.order_id = session.order_id
    JOIN public.orders orders
      ON orders.tenant_id = session.tenant_id
     AND orders.inventory_owner_id = session.inventory_owner_id
     AND orders.id = session.order_id AND orders.deleted IS NULL
    WHERE session.tenant_id = NEW.tenant_id
      AND session.inventory_owner_id = NEW.inventory_owner_id
      AND session.facility_id = NEW.facility_id
      AND session.packing_session_id = NEW.packing_session_id
      AND session.order_id = NEW.order_id
      AND session.id = NEW.outbound_qa_session_id
    FOR SHARE OF session, packing, orders;

    IF NOT FOUND OR source.state NOT IN ('open', 'passed')
       OR source.revision <> NEW.expected_session_revision
       OR NEW.resulting_session_revision <> source.revision + 1
       OR NEW.previous_state <> source.state
       OR NEW.attempt <> source.attempt
       OR NEW.policy_id <> source.policy_id
       OR NEW.verified_carton_count <> source.verified_carton_count
       OR source.packing_state <> 'ready_to_manifest'
       OR source.order_status <> 'awaiting shipment'
       OR NEW.cancelled_at < source.started_at
       OR (source.passed_at IS NOT NULL AND NEW.cancelled_at < source.passed_at)
       OR EXISTS (
           SELECT 1 FROM public.shipments shipment
           WHERE shipment.tenant_id = NEW.tenant_id
             AND shipment.inventory_owner_id = NEW.inventory_owner_id
             AND shipment.facility_id = NEW.facility_id
             AND shipment.packing_session_id = NEW.packing_session_id)
    THEN
        RAISE EXCEPTION 'outbound QA cancellation is not executable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.guard_outbound_qa_session_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    IF TG_OP = 'DELETE' OR OLD.state = 'cancelled'
       OR ROW(NEW.id, NEW.tenant_id, NEW.inventory_owner_id, NEW.facility_id,
              NEW.packing_session_id, NEW.order_id, NEW.policy_id, NEW.policy_revision,
              NEW.attempt, NEW.expected_order_revision, NEW.expected_carton_count,
              NEW.started_by_user_id, NEW.started_at)
          IS DISTINCT FROM
          ROW(OLD.id, OLD.tenant_id, OLD.inventory_owner_id, OLD.facility_id,
              OLD.packing_session_id, OLD.order_id, OLD.policy_id, OLD.policy_revision,
              OLD.attempt, OLD.expected_order_revision, OLD.expected_carton_count,
              OLD.started_by_user_id, OLD.started_at)
       OR NEW.revision <> OLD.revision + 1
    THEN
        RAISE EXCEPTION 'outbound QA session mutation is invalid' USING ERRCODE = '55000';
    END IF;
    IF NEW.state = 'open' AND OLD.state = 'open' THEN
        IF NEW.verified_carton_count <> OLD.verified_carton_count + 1
           OR NEW.cancelled_by_user_id IS NOT NULL OR NEW.cancelled_at IS NOT NULL
           OR NOT EXISTS (
               SELECT 1 FROM public.outbound_qa_carton_verifications verification
               WHERE verification.tenant_id = OLD.tenant_id
                 AND verification.outbound_qa_session_id = OLD.id
                 AND verification.expected_session_revision = OLD.revision
                 AND verification.resulting_session_revision = NEW.revision)
        THEN
            RAISE EXCEPTION 'outbound QA carton progress lacks evidence' USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.state = 'passed' AND OLD.state = 'open' THEN
        IF NEW.verified_carton_count <> OLD.verified_carton_count
           OR NEW.verified_carton_count <> NEW.expected_carton_count
           OR NEW.passed_by_user_id IS NULL OR NEW.passed_at IS NULL
           OR NEW.cancelled_by_user_id IS NOT NULL OR NEW.cancelled_at IS NOT NULL
           OR NOT EXISTS (
               SELECT 1 FROM public.outbound_qa_completions completion
               WHERE completion.tenant_id = OLD.tenant_id
                 AND completion.outbound_qa_session_id = OLD.id
                 AND completion.expected_session_revision = OLD.revision
                 AND completion.resulting_session_revision = NEW.revision
                 AND completion.completed_by_user_id = NEW.passed_by_user_id
                 AND completion.completed_at = NEW.passed_at)
        THEN
            RAISE EXCEPTION 'outbound QA completion lacks evidence' USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.state = 'cancelled' AND OLD.state IN ('open', 'passed') THEN
        IF NEW.verified_carton_count <> OLD.verified_carton_count
           OR NEW.passed_by_user_id IS DISTINCT FROM OLD.passed_by_user_id
           OR NEW.passed_at IS DISTINCT FROM OLD.passed_at
           OR NEW.cancelled_by_user_id IS NULL OR NEW.cancelled_at IS NULL
           OR NOT EXISTS (
               SELECT 1 FROM public.outbound_qa_cancellations cancellation
               WHERE cancellation.tenant_id = OLD.tenant_id
                 AND cancellation.outbound_qa_session_id = OLD.id
                 AND cancellation.previous_state = OLD.state
                 AND cancellation.expected_session_revision = OLD.revision
                 AND cancellation.resulting_session_revision = NEW.revision
                 AND cancellation.cancelled_by_user_id = NEW.cancelled_by_user_id
                 AND cancellation.cancelled_at = NEW.cancelled_at)
        THEN
            RAISE EXCEPTION 'outbound QA cancellation lacks evidence' USING ERRCODE = '23514';
        END IF;
    ELSE
        RAISE EXCEPTION 'outbound QA session transition is invalid' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.require_outbound_qa_session_consistency() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE session_id_value bigint;
DECLARE session_row public.outbound_qa_sessions%ROWTYPE;
DECLARE verification_count bigint;
BEGIN
    IF TG_TABLE_NAME = 'outbound_qa_sessions' THEN
        session_id_value := NEW.id;
    ELSE
        session_id_value := NEW.outbound_qa_session_id;
    END IF;
    SELECT * INTO session_row FROM public.outbound_qa_sessions
    WHERE tenant_id = NEW.tenant_id AND id = session_id_value;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'outbound QA session is missing' USING ERRCODE = '23514';
    END IF;
    SELECT COUNT(*)::bigint INTO verification_count
    FROM public.outbound_qa_carton_verifications
    WHERE tenant_id = session_row.tenant_id
      AND outbound_qa_session_id = session_row.id;
    IF verification_count <> session_row.verified_carton_count
       OR verification_count > session_row.expected_carton_count
       OR (session_row.state = 'passed' AND (
           verification_count <> session_row.expected_carton_count OR NOT EXISTS (
               SELECT 1 FROM public.outbound_qa_completions completion
               WHERE completion.tenant_id = session_row.tenant_id
                 AND completion.outbound_qa_session_id = session_row.id
                 AND completion.resulting_session_revision = session_row.revision
                 AND completion.carton_count = session_row.expected_carton_count)))
       OR (session_row.state = 'cancelled' AND NOT EXISTS (
           SELECT 1 FROM public.outbound_qa_cancellations cancellation
           WHERE cancellation.tenant_id = session_row.tenant_id
             AND cancellation.outbound_qa_session_id = session_row.id
             AND cancellation.resulting_session_revision = session_row.revision
             AND cancellation.attempt = session_row.attempt
             AND cancellation.verified_carton_count = verification_count
             AND cancellation.cancelled_by_user_id = session_row.cancelled_by_user_id
             AND cancellation.cancelled_at = session_row.cancelled_at))
    THEN
        RAISE EXCEPTION 'outbound QA session evidence does not reconcile' USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION public.reject_outbound_qa_cancellation_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    RAISE EXCEPTION 'outbound QA cancellations are immutable' USING ERRCODE = '55000';
END;
$$;

CREATE TRIGGER outbound_qa_cancellations_validate
BEFORE INSERT ON public.outbound_qa_cancellations
FOR EACH ROW EXECUTE FUNCTION public.validate_outbound_qa_cancellation();
CREATE TRIGGER outbound_qa_cancellations_are_immutable
BEFORE UPDATE OR DELETE ON public.outbound_qa_cancellations
FOR EACH ROW EXECUTE FUNCTION public.reject_outbound_qa_cancellation_mutation();
CREATE CONSTRAINT TRIGGER outbound_qa_cancellations_require_consistency
AFTER INSERT ON public.outbound_qa_cancellations DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_outbound_qa_session_consistency();

ALTER TABLE public.outbound_qa_cancellations ENABLE ROW LEVEL SECURITY;
CREATE POLICY outbound_qa_cancellations_tenant_isolation
ON public.outbound_qa_cancellations
USING (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint)
WITH CHECK (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint);

GRANT SELECT, INSERT ON public.outbound_qa_cancellations TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.outbound_qa_cancellations_id_seq TO wareboxes_app;
GRANT UPDATE (state, revision, cancelled_by_user_id, cancelled_at)
ON public.outbound_qa_sessions TO wareboxes_app;
REVOKE ALL ON FUNCTION public.validate_outbound_qa_cancellation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.reject_outbound_qa_cancellation_mutation() FROM PUBLIC;

-- Pre-departure shipment attempts may be cancelled without deleting their
-- immutable address, carton, manifest, tracking, or document snapshots.
-- Cancellation advances the packing-session revision to the order revision
-- established by creation, so packing recovery and later shipment attempts
-- resume from one shared revision.
ALTER TABLE public.shipments
    ADD COLUMN attempt bigint NOT NULL DEFAULT 1,
    ADD COLUMN cancelled_by_user_id bigint,
    ADD COLUMN cancelled_at timestamp with time zone;
ALTER TABLE public.shipments
    DROP CONSTRAINT shipments_state_check,
    DROP CONSTRAINT shipments_state_fields_check,
    DROP CONSTRAINT shipments_order_key;
ALTER TABLE public.shipments
    ADD CONSTRAINT shipments_attempt_check CHECK (attempt > 0),
    ADD CONSTRAINT shipments_state_check CHECK (
        state IN ('awaiting manifest','manifested','partially departed','departed','cancelled')),
    ADD CONSTRAINT shipments_state_fields_check CHECK (
        ((state = 'awaiting manifest') AND revision = 1
            AND carrier IS NULL AND service IS NULL
            AND manifested_at IS NULL AND departed_at IS NULL
            AND departed_carton_count = 0 AND departed_qty = 0
            AND cancelled_by_user_id IS NULL AND cancelled_at IS NULL)
        OR ((state = 'manifested') AND revision = 2
            AND carrier IS NOT NULL AND manifested_at IS NOT NULL
            AND manifested_at >= created_at AND departed_at IS NULL
            AND departed_carton_count = 0 AND departed_qty = 0
            AND cancelled_by_user_id IS NULL AND cancelled_at IS NULL)
        OR ((state = 'partially departed') AND revision >= 3
            AND carrier IS NOT NULL AND manifested_at IS NOT NULL
            AND manifested_at >= created_at AND departed_at IS NULL
            AND departed_carton_count > 0 AND departed_carton_count < carton_count
            AND departed_qty > 0 AND departed_qty < shipped_qty
            AND cancelled_by_user_id IS NULL AND cancelled_at IS NULL)
        OR ((state = 'departed') AND revision >= 3
            AND carrier IS NOT NULL AND manifested_at IS NOT NULL
            AND manifested_at >= created_at AND departed_at IS NOT NULL
            AND departed_at >= manifested_at
            AND departed_carton_count = carton_count AND departed_qty = shipped_qty
            AND cancelled_by_user_id IS NULL AND cancelled_at IS NULL)
        OR ((state = 'cancelled') AND revision IN (2, 3)
            AND ((revision = 2 AND carrier IS NULL AND service IS NULL
                  AND manifested_at IS NULL)
                 OR (revision = 3 AND carrier IS NOT NULL
                     AND manifested_at IS NOT NULL
                     AND manifested_at >= created_at))
            AND departed_at IS NULL
            AND departed_carton_count = 0 AND departed_qty = 0
            AND cancelled_by_user_id IS NOT NULL AND cancelled_at IS NOT NULL
            AND cancelled_at >= COALESCE(manifested_at, created_at))),
    ADD CONSTRAINT shipments_order_attempt_key UNIQUE (
        tenant_id, inventory_owner_id, order_id, attempt),
    ADD CONSTRAINT shipments_cancelled_by_fkey FOREIGN KEY (
        tenant_id, cancelled_by_user_id)
        REFERENCES public.tenant_memberships (tenant_id, user_id);
CREATE UNIQUE INDEX shipments_active_order_idx
ON public.shipments (tenant_id, inventory_owner_id, order_id)
WHERE state <> 'cancelled';

ALTER TABLE public.shipment_cartons
    DROP CONSTRAINT shipment_cartons_carton_key,
    DROP CONSTRAINT shipment_cartons_license_plate_key;
ALTER TABLE public.shipment_cartons
    ADD CONSTRAINT shipment_cartons_attempt_carton_key UNIQUE (
        tenant_id, inventory_owner_id, facility_id, shipment_id, carton_id),
    ADD CONSTRAINT shipment_cartons_attempt_license_plate_key UNIQUE (
        tenant_id, inventory_owner_id, facility_id, shipment_id, license_plate_id);

CREATE TABLE public.shipment_cancellations (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    shipment_id bigint NOT NULL,
    previous_shipment_state text NOT NULL,
    carrier_manifest_id bigint,
    packing_session_id bigint NOT NULL,
    order_release_id bigint NOT NULL,
    order_id bigint NOT NULL,
    attempt bigint NOT NULL,
    expected_shipment_revision bigint NOT NULL,
    resulting_shipment_revision bigint NOT NULL,
    expected_order_revision bigint NOT NULL,
    resulting_order_revision bigint NOT NULL,
    expected_packing_revision bigint NOT NULL,
    resulting_packing_revision bigint NOT NULL,
    carton_count bigint NOT NULL,
    content_count bigint NOT NULL,
    packed_qty bigint NOT NULL,
    reason_code text NOT NULL,
    note text,
    cancelled_by_user_id bigint NOT NULL,
    cancelled_at timestamp with time zone NOT NULL,
    CONSTRAINT shipment_cancellations_attempt_check CHECK (attempt > 0),
    CONSTRAINT shipment_cancellations_previous_state_check CHECK (
        previous_shipment_state IN ('awaiting manifest','manifested')),
    CONSTRAINT shipment_cancellations_manifest_check CHECK (
        (previous_shipment_state = 'awaiting manifest' AND carrier_manifest_id IS NULL)
        OR (previous_shipment_state = 'manifested' AND carrier_manifest_id IS NOT NULL)),
    CONSTRAINT shipment_cancellations_revision_check CHECK (
        ((previous_shipment_state = 'awaiting manifest' AND expected_shipment_revision = 1)
         OR (previous_shipment_state = 'manifested' AND expected_shipment_revision = 2))
        AND resulting_shipment_revision = expected_shipment_revision + 1
        AND expected_order_revision > 0
        AND resulting_order_revision = expected_order_revision
        AND expected_packing_revision > 0
        AND resulting_packing_revision = expected_packing_revision + 1
        AND resulting_packing_revision = expected_order_revision),
    CONSTRAINT shipment_cancellations_quantity_check CHECK (
        carton_count > 0 AND content_count > 0 AND packed_qty > 0),
    CONSTRAINT shipment_cancellations_reason_check CHECK (
        reason_code IN ('packing_correction','shipping_data_correction',
                        'duplicate_shipment','operator_error','other')),
    CONSTRAINT shipment_cancellations_note_check CHECK (
        note IS NULL OR (note = btrim(note) AND note <> ''
                         AND char_length(note) <= 500
                         AND note !~ '[[:cntrl:]]')),
    CONSTRAINT shipment_cancellations_other_note_check CHECK (
        reason_code <> 'other' OR note IS NOT NULL),
    CONSTRAINT shipment_cancellations_scope_id_key UNIQUE (
        tenant_id, inventory_owner_id, facility_id, shipment_id, id),
    CONSTRAINT shipment_cancellations_shipment_key UNIQUE (
        tenant_id, inventory_owner_id, facility_id, shipment_id),
    CONSTRAINT shipment_cancellations_shipment_fkey FOREIGN KEY (
        tenant_id, inventory_owner_id, facility_id,
        packing_session_id, order_release_id, order_id, shipment_id)
        REFERENCES public.shipments (
            tenant_id, inventory_owner_id, facility_id,
            packing_session_id, order_release_id, order_id, id),
    CONSTRAINT shipment_cancellations_manifest_fkey FOREIGN KEY (
        tenant_id, inventory_owner_id, facility_id, shipment_id, carrier_manifest_id)
        REFERENCES public.shipment_manifests (
            tenant_id, inventory_owner_id, facility_id, shipment_id, id),
    CONSTRAINT shipment_cancellations_actor_fkey FOREIGN KEY (
        tenant_id, cancelled_by_user_id)
        REFERENCES public.tenant_memberships (tenant_id, user_id)
);
ALTER TABLE public.shipment_cancellations FORCE ROW LEVEL SECURITY;
CREATE INDEX shipment_cancellations_order_idx
ON public.shipment_cancellations (tenant_id, inventory_owner_id, order_id, id);

CREATE OR REPLACE FUNCTION public.validate_shipment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE expected_attempt bigint;
BEGIN
    SELECT COALESCE(MAX(shipment.attempt),0) + 1 INTO expected_attempt
    FROM public.shipments shipment
    WHERE shipment.tenant_id = NEW.tenant_id
      AND shipment.inventory_owner_id = NEW.inventory_owner_id
      AND shipment.order_id = NEW.order_id;

    IF NEW.state <> 'awaiting manifest'
       OR NEW.revision <> 1 OR NEW.attempt <> expected_attempt
       OR NEW.carrier IS NOT NULL OR NEW.service IS NOT NULL
       OR NEW.manifested_at IS NOT NULL OR NEW.departed_at IS NOT NULL
       OR NEW.departed_carton_count <> 0 OR NEW.departed_qty <> 0
       OR NEW.cancelled_by_user_id IS NOT NULL OR NEW.cancelled_at IS NOT NULL
       OR EXISTS (
            SELECT 1 FROM public.shipments shipment
            WHERE shipment.tenant_id = NEW.tenant_id
              AND shipment.inventory_owner_id = NEW.inventory_owner_id
              AND shipment.order_id = NEW.order_id
              AND shipment.state <> 'cancelled')
       OR NOT EXISTS (
            SELECT 1
            FROM public.packing_sessions session
            INNER JOIN public.orders order_header
              ON order_header.tenant_id = session.tenant_id
             AND order_header.inventory_owner_id = session.inventory_owner_id
             AND order_header.id = session.order_id
             AND order_header.deleted IS NULL
            WHERE session.tenant_id = NEW.tenant_id
              AND session.inventory_owner_id = NEW.inventory_owner_id
              AND session.facility_id = NEW.facility_id
              AND session.id = NEW.packing_session_id
              AND session.order_release_id = NEW.order_release_id
              AND session.order_id = NEW.order_id
              AND session.state = 'ready_to_manifest'
              AND session.closed_carton_count = NEW.carton_count
              AND session.packed_allocation_count = NEW.content_count
              AND session.packed_qty = NEW.shipped_qty
              AND NEW.creation_expected_order_revision = session.revision
              AND order_header.status = 'awaiting shipment'
              AND order_header.revision = session.revision
              AND NEW.creation_resulting_order_revision = session.revision + 1)
    THEN
        RAISE EXCEPTION 'shipment must snapshot one ready full-order packing session'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.guard_shipment_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM OLD.facility_id
       OR NEW.packing_session_id IS DISTINCT FROM OLD.packing_session_id
       OR NEW.order_release_id IS DISTINCT FROM OLD.order_release_id
       OR NEW.order_id IS DISTINCT FROM OLD.order_id
       OR NEW.attempt IS DISTINCT FROM OLD.attempt
       OR NEW.creation_expected_order_revision IS DISTINCT FROM OLD.creation_expected_order_revision
       OR NEW.creation_resulting_order_revision IS DISTINCT FROM OLD.creation_resulting_order_revision
       OR NEW.carton_count IS DISTINCT FROM OLD.carton_count
       OR NEW.content_count IS DISTINCT FROM OLD.content_count
       OR NEW.shipped_qty IS DISTINCT FROM OLD.shipped_qty
       OR NEW.created_by_user_id IS DISTINCT FROM OLD.created_by_user_id
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
    THEN
        RAISE EXCEPTION 'shipment identity and plan are immutable' USING ERRCODE = '55000';
    END IF;

    IF OLD.state IN ('awaiting manifest','manifested') AND NEW.state = 'cancelled'
       AND NEW.revision = OLD.revision + 1
       AND NEW.carrier IS NOT DISTINCT FROM OLD.carrier
       AND NEW.service IS NOT DISTINCT FROM OLD.service
       AND NEW.manifested_at IS NOT DISTINCT FROM OLD.manifested_at
       AND NEW.departed_at IS NULL
       AND NEW.departed_carton_count = 0 AND NEW.departed_qty = 0
       AND NEW.cancelled_by_user_id IS NOT NULL AND NEW.cancelled_at IS NOT NULL
       AND EXISTS (
           SELECT 1 FROM public.shipment_cancellations cancellation
           WHERE cancellation.tenant_id = OLD.tenant_id
             AND cancellation.inventory_owner_id = OLD.inventory_owner_id
             AND cancellation.facility_id = OLD.facility_id
             AND cancellation.shipment_id = OLD.id
             AND cancellation.previous_shipment_state = OLD.state
             AND cancellation.expected_shipment_revision = OLD.revision
             AND cancellation.resulting_shipment_revision = NEW.revision
             AND cancellation.cancelled_by_user_id = NEW.cancelled_by_user_id
             AND cancellation.cancelled_at = NEW.cancelled_at)
    THEN
        RETURN NEW;
    END IF;

    IF NEW.cancelled_by_user_id IS NOT NULL OR NEW.cancelled_at IS NOT NULL THEN
        RAISE EXCEPTION 'active shipment cannot contain cancellation evidence'
            USING ERRCODE = '55000';
    END IF;

    IF OLD.state = 'awaiting manifest'
       AND NEW.state = 'manifested'
       AND NEW.revision = OLD.revision + 1
       AND OLD.manifested_at IS NULL
       AND NEW.manifested_at IS NOT NULL
       AND NEW.manifested_at >= NEW.created_at
       AND NEW.departed_at IS NULL
       AND NEW.departed_carton_count = 0 AND NEW.departed_qty = 0
       AND OLD.carrier IS NULL AND OLD.service IS NULL
       AND NEW.carrier IS NOT NULL
    THEN
        RETURN NEW;
    END IF;

    IF OLD.state IN ('manifested','partially departed')
       AND NEW.state IN ('partially departed','departed')
       AND NEW.revision = OLD.revision + 1
       AND NEW.carrier IS NOT DISTINCT FROM OLD.carrier
       AND NEW.service IS NOT DISTINCT FROM OLD.service
       AND NEW.manifested_at IS NOT DISTINCT FROM OLD.manifested_at
       AND NEW.departed_carton_count > OLD.departed_carton_count
       AND NEW.departed_qty > OLD.departed_qty
       AND ((NEW.state = 'partially departed' AND NEW.departed_at IS NULL
             AND NEW.departed_carton_count < NEW.carton_count
             AND NEW.departed_qty < NEW.shipped_qty)
            OR (NEW.state = 'departed' AND NEW.departed_at IS NOT NULL
                AND NEW.departed_at >= NEW.manifested_at
                AND NEW.departed_carton_count = NEW.carton_count
                AND NEW.departed_qty = NEW.shipped_qty))
    THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'invalid shipment state or revision transition' USING ERRCODE = '55000';
END;
$$;

CREATE FUNCTION public.validate_shipment_cancellation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE source record;
BEGIN
    SELECT shipment.state,shipment.revision,shipment.attempt,
           shipment.creation_expected_order_revision,
           shipment.creation_resulting_order_revision,
           shipment.carton_count,shipment.content_count,shipment.shipped_qty,
           shipment.created_at,shipment.manifested_at,session.state AS packing_state,
           session.revision AS packing_revision,
           order_header.status AS order_status,
           order_header.revision AS order_revision
    INTO source
    FROM public.shipments shipment
    INNER JOIN public.packing_sessions session
      ON session.tenant_id=shipment.tenant_id
     AND session.inventory_owner_id=shipment.inventory_owner_id
     AND session.facility_id=shipment.facility_id
     AND session.id=shipment.packing_session_id
     AND session.order_release_id=shipment.order_release_id
     AND session.order_id=shipment.order_id
    INNER JOIN public.orders order_header
      ON order_header.tenant_id=shipment.tenant_id
     AND order_header.inventory_owner_id=shipment.inventory_owner_id
     AND order_header.id=shipment.order_id AND order_header.deleted IS NULL
    WHERE shipment.tenant_id=NEW.tenant_id
      AND shipment.inventory_owner_id=NEW.inventory_owner_id
      AND shipment.facility_id=NEW.facility_id
      AND shipment.id=NEW.shipment_id
      AND shipment.packing_session_id=NEW.packing_session_id
      AND shipment.order_release_id=NEW.order_release_id
      AND shipment.order_id=NEW.order_id
    FOR SHARE OF shipment,session,order_header;

    IF NOT FOUND OR source.state NOT IN ('awaiting manifest','manifested')
       OR source.state <> NEW.previous_shipment_state
       OR source.revision <> NEW.expected_shipment_revision
       OR NEW.resulting_shipment_revision <> source.revision + 1
       OR source.attempt <> NEW.attempt
       OR source.creation_expected_order_revision <> NEW.expected_packing_revision
       OR source.creation_resulting_order_revision <> NEW.expected_order_revision
       OR source.carton_count <> NEW.carton_count
       OR source.content_count <> NEW.content_count
       OR source.shipped_qty <> NEW.packed_qty
       OR source.packing_state <> 'ready_to_manifest'
       OR source.packing_revision <> NEW.expected_packing_revision
       OR source.order_status <> 'awaiting shipment'
       OR source.order_revision <> NEW.expected_order_revision
       OR NEW.resulting_order_revision <> source.order_revision
       OR NEW.resulting_packing_revision <> source.packing_revision + 1
       OR NEW.resulting_packing_revision <> source.order_revision
       OR NEW.cancelled_at < COALESCE(source.manifested_at, source.created_at)
       OR (source.state = 'awaiting manifest' AND (
           NEW.carrier_manifest_id IS NOT NULL OR EXISTS (
               SELECT 1 FROM public.shipment_manifests manifest
               WHERE manifest.tenant_id=NEW.tenant_id
                 AND manifest.inventory_owner_id=NEW.inventory_owner_id
                 AND manifest.facility_id=NEW.facility_id
                 AND manifest.shipment_id=NEW.shipment_id)))
       OR (source.state = 'manifested' AND NOT EXISTS (
           SELECT 1 FROM public.shipment_manifests manifest
           WHERE manifest.tenant_id=NEW.tenant_id
             AND manifest.inventory_owner_id=NEW.inventory_owner_id
             AND manifest.facility_id=NEW.facility_id
             AND manifest.shipment_id=NEW.shipment_id
             AND manifest.id=NEW.carrier_manifest_id))
       OR EXISTS (
           SELECT 1 FROM public.outbound_load_shipments link
           WHERE link.tenant_id=NEW.tenant_id AND link.shipment_id=NEW.shipment_id
             AND link.closed_at IS NULL)
    THEN
        RAISE EXCEPTION 'shipment cancellation is not executable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.guard_packing_session_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM OLD.facility_id
       OR NEW.order_release_id IS DISTINCT FROM OLD.order_release_id
       OR NEW.order_id IS DISTINCT FROM OLD.order_id
       OR NEW.packing_location_id IS DISTINCT FROM OLD.packing_location_id
       OR NEW.expected_allocation_count IS DISTINCT FROM OLD.expected_allocation_count
       OR NEW.expected_qty IS DISTINCT FROM OLD.expected_qty
       OR NEW.started_by_user_id IS DISTINCT FROM OLD.started_by_user_id
       OR NEW.started_at IS DISTINCT FROM OLD.started_at
    THEN
        RAISE EXCEPTION 'packing session identity and plan are immutable' USING ERRCODE = '55000';
    END IF;
    IF OLD.state = 'abandoned' THEN
        RAISE EXCEPTION 'abandoned packing sessions are immutable' USING ERRCODE = '55000';
    END IF;

    IF OLD.state = 'ready_to_manifest' AND NEW.state = 'ready_to_manifest' THEN
        IF NEW.revision <> OLD.revision + 1
           OR ROW(NEW.packed_allocation_count,NEW.packed_qty,
                  NEW.open_carton_count,NEW.closed_carton_count,
                  NEW.ready_by_user_id,NEW.ready_at)
              IS DISTINCT FROM
              ROW(OLD.packed_allocation_count,OLD.packed_qty,
                  OLD.open_carton_count,OLD.closed_carton_count,
                  OLD.ready_by_user_id,OLD.ready_at)
           OR NOT EXISTS (
               SELECT 1 FROM public.shipment_cancellations cancellation
               WHERE cancellation.tenant_id=OLD.tenant_id
                 AND cancellation.inventory_owner_id=OLD.inventory_owner_id
                 AND cancellation.facility_id=OLD.facility_id
                 AND cancellation.packing_session_id=OLD.id
                 AND cancellation.expected_packing_revision=OLD.revision
                 AND cancellation.resulting_packing_revision=NEW.revision)
        THEN
            RAISE EXCEPTION 'invalid shipment-cancellation packing resynchronization'
                USING ERRCODE = '55000';
        END IF;
    ELSIF OLD.state = 'ready_to_manifest' AND NEW.state = 'open' THEN
        IF NEW.revision <> OLD.revision + 1
           OR NEW.ready_by_user_id IS NOT NULL OR NEW.ready_at IS NOT NULL
           OR NEW.packed_allocation_count <> OLD.packed_allocation_count
           OR NEW.packed_qty <> OLD.packed_qty
           OR NEW.open_carton_count <> 1
           OR NEW.closed_carton_count <> OLD.closed_carton_count - 1
           OR NEW.abandonment_reason IS NOT NULL OR NEW.abandonment_note IS NOT NULL
           OR NEW.abandoned_by_user_id IS NOT NULL OR NEW.abandoned_at IS NOT NULL
        THEN
            RAISE EXCEPTION 'invalid completed-session carton reopening transition'
                USING ERRCODE = '55000';
        END IF;
    ELSIF NEW.state = 'open' THEN
        IF NEW.revision <> OLD.revision + 1
           OR NEW.ready_by_user_id IS NOT NULL OR NEW.ready_at IS NOT NULL
           OR NEW.abandonment_reason IS NOT NULL OR NEW.abandonment_note IS NOT NULL
           OR NEW.abandoned_by_user_id IS NOT NULL OR NEW.abandoned_at IS NOT NULL
        THEN
            RAISE EXCEPTION 'open packing session updates must advance revision once'
                USING ERRCODE = '55000';
        END IF;
    ELSIF NEW.state = 'ready_to_manifest' THEN
        IF OLD.state <> 'open' OR NEW.revision <> OLD.revision + 1
           OR NEW.ready_by_user_id IS NULL OR NEW.ready_at IS NULL
           OR NEW.abandonment_reason IS NOT NULL OR NEW.abandonment_note IS NOT NULL
           OR NEW.abandoned_by_user_id IS NOT NULL OR NEW.abandoned_at IS NOT NULL
        THEN
            RAISE EXCEPTION 'invalid packing session completion transition' USING ERRCODE = '55000';
        END IF;
    ELSIF NEW.state = 'abandoned' THEN
        IF OLD.state <> 'open' OR NEW.revision <> OLD.revision + 1
           OR NEW.ready_by_user_id IS NOT NULL OR NEW.ready_at IS NOT NULL
           OR NEW.abandonment_reason IS NULL OR NEW.abandoned_by_user_id IS NULL
           OR NEW.abandoned_at IS NULL OR NEW.abandoned_at < NEW.started_at
           OR NEW.packed_allocation_count <> 0 OR NEW.packed_qty <> 0
           OR NEW.open_carton_count <> 0 OR NEW.closed_carton_count <> 0
        THEN
            RAISE EXCEPTION 'invalid packing session abandonment transition' USING ERRCODE = '55000';
        END IF;
    ELSE
        RAISE EXCEPTION 'invalid packing session state' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.reject_shipment_cancellation_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    RAISE EXCEPTION 'shipment cancellations are immutable' USING ERRCODE = '55000';
END;
$$;

CREATE TRIGGER shipment_cancellations_validate
BEFORE INSERT ON public.shipment_cancellations
FOR EACH ROW EXECUTE FUNCTION public.validate_shipment_cancellation();
CREATE TRIGGER shipment_cancellations_are_immutable
BEFORE UPDATE OR DELETE ON public.shipment_cancellations
FOR EACH ROW EXECUTE FUNCTION public.reject_shipment_cancellation_mutation();
CREATE CONSTRAINT TRIGGER shipment_cancellations_validate_consistency
AFTER INSERT ON public.shipment_cancellations DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.validate_shipment_consistency();

ALTER TABLE public.shipment_cancellations ENABLE ROW LEVEL SECURITY;
CREATE POLICY shipment_cancellations_tenant_isolation
ON public.shipment_cancellations
USING (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint)
WITH CHECK (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint);

GRANT SELECT,INSERT ON public.shipment_cancellations TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.shipment_cancellations_id_seq TO wareboxes_app;
REVOKE ALL ON FUNCTION public.validate_shipment_cancellation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.reject_shipment_cancellation_mutation() FROM PUBLIC;

-- Unexpected inbound stock is retained as quarantined inventory without changing
-- the immutable expectation carried by load_lines.
CREATE TABLE public.unexpected_receipts (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    load_id bigint NOT NULL,
    item_id bigint NOT NULL,
    uom text NOT NULL,
    quantity bigint NOT NULL CHECK (quantity > 0),
    receiving_location_id bigint NOT NULL,
    observed_item_barcode text NOT NULL,
    observed_receiving_location_barcode text NOT NULL,
    license_plate_id bigint,
    license_plate_barcode text,
    item_batch_id bigint NOT NULL,
    lot text,
    serial text,
    expiration timestamptz,
    reason_code text NOT NULL CHECK (
        reason_code IN ('excess','unexpected_item','blind_receipt','mis_shipped','other')
    ),
    note text,
    inventory_transaction_id bigint NOT NULL,
    inventory_balance_id bigint NOT NULL,
    inventory_hold_id bigint NOT NULL,
    confirmed_by_user_id bigint NOT NULL,
    confirmed_at timestamptz NOT NULL,
    owner_item_mapping_id bigint NOT NULL,
    owner_item_was_preexisting boolean NOT NULL,
    policy_source text NOT NULL,
    policy_configuration_id bigint,
    policy_configuration_revision bigint,
    policy_scope_level text,
    policy_inventory_owner_id bigint,
    policy_facility_id bigint,
    policy_definition jsonb NOT NULL,
    policy_hash text NOT NULL,
    CONSTRAINT unexpected_receipts_uom_check CHECK (uom IN ('each','case')),
    CONSTRAINT unexpected_receipts_item_barcode_check CHECK (
        observed_item_barcode = btrim(observed_item_barcode)
        AND char_length(observed_item_barcode) BETWEEN 1 AND 200
    ),
    CONSTRAINT unexpected_receipts_location_barcode_check CHECK (
        observed_receiving_location_barcode = btrim(observed_receiving_location_barcode)
        AND char_length(observed_receiving_location_barcode) BETWEEN 1 AND 200
    ),
    CONSTRAINT unexpected_receipts_license_plate_shape_check CHECK (
        (license_plate_id IS NULL AND license_plate_barcode IS NULL)
        OR (license_plate_id IS NOT NULL AND license_plate_barcode IS NOT NULL
            AND license_plate_barcode = btrim(license_plate_barcode)
            AND char_length(license_plate_barcode) BETWEEN 1 AND 200)
    ),
    CONSTRAINT unexpected_receipts_note_check CHECK (
        note IS NULL OR (note = btrim(note) AND char_length(note) BETWEEN 1 AND 1000)
    ),
    CONSTRAINT unexpected_receipts_other_note_check CHECK (
        reason_code <> 'other' OR note IS NOT NULL
    ),
    CONSTRAINT unexpected_receipts_policy_source_check CHECK (
        policy_source IN ('product_default','configuration')
    ),
    CONSTRAINT unexpected_receipts_policy_hash_check CHECK (
        policy_hash ~ '^[0-9a-f]{64}$'
    ),
    CONSTRAINT unexpected_receipts_policy_definition_check CHECK (
        policy_definition ?& ARRAY[
          'kind','allow_unexpected','quarantine_unmapped_items',
          'over_receipt_tolerance_basis_points']
        AND policy_definition-ARRAY[
          'kind','allow_unexpected','quarantine_unmapped_items',
          'over_receipt_tolerance_basis_points']='{}'::jsonb
        AND policy_definition->>'kind'='receipt'
        AND jsonb_typeof(policy_definition->'allow_unexpected')='boolean'
        AND jsonb_typeof(policy_definition->'quarantine_unmapped_items')='boolean'
        AND jsonb_typeof(policy_definition->'over_receipt_tolerance_basis_points')='number'
        AND (policy_definition->>'over_receipt_tolerance_basis_points')::bigint
              BETWEEN 0 AND 10000
        AND (policy_definition->>'allow_unexpected')::boolean
    ),
    CONSTRAINT unexpected_receipts_policy_identity_check CHECK (
        (policy_source='product_default'
          AND policy_configuration_id IS NULL
          AND policy_configuration_revision IS NULL
          AND policy_scope_level IS NULL
          AND policy_inventory_owner_id IS NULL AND policy_facility_id IS NULL
          AND policy_definition=jsonb_build_object(
            'kind','receipt','allow_unexpected',true,
            'quarantine_unmapped_items',true,
            'over_receipt_tolerance_basis_points',10000))
        OR
        (policy_source='configuration'
          AND policy_configuration_id IS NOT NULL
          AND policy_configuration_revision>0
          AND ((policy_scope_level='tenant'
                AND policy_inventory_owner_id IS NULL AND policy_facility_id IS NULL)
            OR (policy_scope_level='inventory_owner'
                AND policy_inventory_owner_id IS NOT NULL AND policy_facility_id IS NULL)
            OR (policy_scope_level='facility'
                AND policy_inventory_owner_id IS NULL AND policy_facility_id IS NOT NULL)
            OR (policy_scope_level='owner_facility'
                AND policy_inventory_owner_id IS NOT NULL AND policy_facility_id IS NOT NULL)))
    ),
    CONSTRAINT unexpected_receipts_tenant_id_inventory_owner_id_id_key
        UNIQUE (tenant_id, inventory_owner_id, id),
    CONSTRAINT unexpected_receipts_transaction_unique
        UNIQUE (tenant_id, inventory_transaction_id),
    CONSTRAINT unexpected_receipts_hold_unique
        UNIQUE (tenant_id, inventory_hold_id),
    CONSTRAINT unexpected_receipts_batch_unique
        UNIQUE (tenant_id, item_batch_id),
    CONSTRAINT unexpected_receipts_owner_facility_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, facility_id)
        REFERENCES public.inventory_owner_facilities(tenant_id, inventory_owner_id, facility_id),
    CONSTRAINT unexpected_receipts_load_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, load_id)
        REFERENCES public.loads(tenant_id, inventory_owner_id, id),
    CONSTRAINT unexpected_receipts_item_fkey
        FOREIGN KEY (tenant_id, item_id) REFERENCES public.items(tenant_id, id),
    CONSTRAINT unexpected_receipts_location_fkey
        FOREIGN KEY (tenant_id, facility_id, receiving_location_id)
        REFERENCES public.locations(tenant_id, facility_id, id),
    CONSTRAINT unexpected_receipts_license_plate_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, license_plate_id)
        REFERENCES public.license_plates(tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT unexpected_receipts_batch_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, item_batch_id)
        REFERENCES public.item_batches(tenant_id, inventory_owner_id, id),
    CONSTRAINT unexpected_receipts_transaction_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, inventory_transaction_id)
        REFERENCES public.inventory_transactions(tenant_id, inventory_owner_id, id),
    CONSTRAINT unexpected_receipts_balance_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, inventory_balance_id)
        REFERENCES public.inventory_balances(tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT unexpected_receipts_hold_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, inventory_hold_id)
        REFERENCES public.inventory_holds(tenant_id, inventory_owner_id, id),
    CONSTRAINT unexpected_receipts_actor_fkey
        FOREIGN KEY (tenant_id, confirmed_by_user_id)
        REFERENCES public.tenant_memberships(tenant_id, user_id),
    CONSTRAINT unexpected_receipts_owner_item_mapping_fkey
        FOREIGN KEY (owner_item_mapping_id)
        REFERENCES public.inventory_owner_items(id)
);
ALTER TABLE public.unexpected_receipts FORCE ROW LEVEL SECURITY;
CREATE INDEX unexpected_receipts_load_history_idx
ON public.unexpected_receipts(tenant_id, load_id, confirmed_at, id);
CREATE INDEX unexpected_receipts_policy_idx
ON public.unexpected_receipts(tenant_id, policy_configuration_id, confirmed_at, id)
WHERE policy_configuration_id IS NOT NULL;

CREATE FUNCTION public.validate_unexpected_receipt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    expected_hold_reason text;
    configuration_row record;
    mapping_row public.inventory_owner_items%ROWTYPE;
    resolved_configuration_id bigint;
    expected_quantity bigint;
    prior_excess_quantity bigint;
    calculated_hash text;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(format(
      'configuration-kind:%s:receipt',NEW.tenant_id),0));
    calculated_hash:=encode(sha256(convert_to(
      'receipt-policy-v1|'||(NEW.policy_definition->>'allow_unexpected')||'|'||
      (NEW.policy_definition->>'quarantine_unmapped_items')||'|'||
      (NEW.policy_definition->>'over_receipt_tolerance_basis_points'),'UTF8')),'hex');
    IF NEW.policy_hash<>calculated_hash THEN
        RAISE EXCEPTION 'unexpected receipt policy hash does not match its snapshot'
            USING ERRCODE = '23514';
    END IF;
    SELECT configuration.id INTO resolved_configuration_id
    FROM public.configuration_versions configuration
    WHERE configuration.tenant_id=NEW.tenant_id
      AND configuration.kind='receipt' AND configuration.status='active'
      AND configuration.effective_from<=NEW.confirmed_at
      AND (configuration.effective_until IS NULL
           OR configuration.effective_until>NEW.confirmed_at)
      AND (configuration.inventory_owner_id IS NULL
           OR configuration.inventory_owner_id=NEW.inventory_owner_id)
      AND (configuration.facility_id IS NULL
           OR configuration.facility_id=NEW.facility_id)
    ORDER BY CASE configuration.scope_level
               WHEN 'owner_facility' THEN 2
               WHEN 'inventory_owner' THEN 1
               WHEN 'facility' THEN 1
               ELSE 0 END DESC,
             configuration.effective_from DESC,
             configuration.revision DESC,configuration.id DESC
    LIMIT 1;
    IF NEW.policy_source='product_default' THEN
        IF resolved_configuration_id IS NOT NULL THEN
            RAISE EXCEPTION 'unexpected receipt product default is not effective'
                USING ERRCODE = '23514';
        END IF;
    ELSE
        SELECT * INTO configuration_row
        FROM public.configuration_versions configuration
        WHERE configuration.tenant_id=NEW.tenant_id
          AND configuration.id=NEW.policy_configuration_id;
        IF configuration_row.id IS NULL
           OR configuration_row.kind<>'receipt'
           OR configuration_row.status<>'active'
           OR configuration_row.revision<>NEW.policy_configuration_revision
           OR configuration_row.scope_level<>NEW.policy_scope_level
           OR configuration_row.inventory_owner_id
                IS DISTINCT FROM NEW.policy_inventory_owner_id
           OR configuration_row.facility_id IS DISTINCT FROM NEW.policy_facility_id
           OR configuration_row.definition<>NEW.policy_definition
           OR configuration_row.effective_from>NEW.confirmed_at
           OR (configuration_row.effective_until IS NOT NULL
               AND configuration_row.effective_until<=NEW.confirmed_at)
           OR (configuration_row.inventory_owner_id IS NOT NULL
               AND configuration_row.inventory_owner_id<>NEW.inventory_owner_id)
           OR (configuration_row.facility_id IS NOT NULL
               AND configuration_row.facility_id<>NEW.facility_id)
           OR resolved_configuration_id IS DISTINCT FROM NEW.policy_configuration_id
        THEN
            RAISE EXCEPTION 'unexpected receipt policy is stale or inapplicable'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    expected_hold_reason := CASE
        WHEN NEW.reason_code = 'mis_shipped' THEN 'customer_request'
        ELSE 'inventory_discrepancy'
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM public.loads load
        INNER JOIN public.locations location
          ON location.tenant_id = load.tenant_id
         AND location.facility_id = load.facility_id
         AND location.id = load.dock_door_location_id
        WHERE load.tenant_id = NEW.tenant_id
          AND load.inventory_owner_id = NEW.inventory_owner_id
          AND load.facility_id = NEW.facility_id
          AND load.id = NEW.load_id
          AND load.type = 'inbound'
          AND load.status IN ('arrived','receiving','received')
          AND load.deleted IS NULL
          AND location.id = NEW.receiving_location_id
          AND location.barcode = NEW.observed_receiving_location_barcode
          AND location.deleted IS NULL
          AND location.active
          AND location.receivable
        FOR UPDATE OF load
        FOR SHARE OF location
    ) THEN
        RAISE EXCEPTION 'unexpected receipt load and receiving dock are not executable'
            USING ERRCODE = '55000';
    END IF;

    SELECT * INTO mapping_row FROM public.inventory_owner_items mapping
    WHERE mapping.id=NEW.owner_item_mapping_id
      AND mapping.tenant_id=NEW.tenant_id
      AND mapping.inventory_owner_id=NEW.inventory_owner_id
      AND mapping.item_id=NEW.item_id
      AND mapping.deleted IS NULL
    FOR SHARE;
    IF mapping_row.id IS NULL
       OR (NEW.owner_item_was_preexisting AND mapping_row.created>NEW.confirmed_at)
       OR (NOT NEW.owner_item_was_preexisting
           AND mapping_row.created IS DISTINCT FROM NEW.confirmed_at)
       OR (NOT NEW.owner_item_was_preexisting
           AND NOT (NEW.policy_definition->>'quarantine_unmapped_items')::boolean)
    THEN
        RAISE EXCEPTION 'unexpected receipt owner-item mapping evidence is invalid'
            USING ERRCODE = '23514';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.items item
        INNER JOIN public.barcodes barcode
          ON barcode.tenant_id = item.tenant_id
         AND barcode.item_id = item.id
        WHERE item.tenant_id = NEW.tenant_id
          AND item.id = NEW.item_id
          AND item.packaging_unit = NEW.uom
          AND item.deleted IS NULL
          AND barcode.deleted IS NULL
          AND lower(barcode.name) = lower(NEW.observed_item_barcode)
        FOR SHARE OF item, barcode
    ) THEN
        RAISE EXCEPTION 'unexpected receipt item barcode is not active'
            USING ERRCODE = '55000';
    END IF;

    IF (NEW.reason_code = 'excess' AND NOT EXISTS (
            SELECT 1 FROM public.load_lines line
            WHERE line.tenant_id = NEW.tenant_id
              AND line.load_id = NEW.load_id
              AND line.item_id = NEW.item_id
              AND line.deleted IS NULL
        )) OR (NEW.reason_code = 'unexpected_item' AND EXISTS (
            SELECT 1 FROM public.load_lines line
            WHERE line.tenant_id = NEW.tenant_id
              AND line.load_id = NEW.load_id
              AND line.item_id = NEW.item_id
              AND line.deleted IS NULL
        ))
    THEN
        RAISE EXCEPTION 'unexpected receipt reason does not match the load expectation'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.reason_code='excess' THEN
        SELECT COALESCE(SUM(line.expected_qty),0)::bigint
        INTO expected_quantity FROM public.load_lines line
        WHERE line.tenant_id=NEW.tenant_id AND line.load_id=NEW.load_id
          AND line.item_id=NEW.item_id AND line.deleted IS NULL;
        SELECT COALESCE(SUM(receipt.quantity),0)::bigint
        INTO prior_excess_quantity FROM public.unexpected_receipts receipt
        WHERE receipt.tenant_id=NEW.tenant_id AND receipt.load_id=NEW.load_id
          AND receipt.item_id=NEW.item_id AND receipt.reason_code='excess';
        IF (prior_excess_quantity+NEW.quantity)::numeric >
           expected_quantity::numeric*
             (NEW.policy_definition->>'over_receipt_tolerance_basis_points')::numeric/10000
        THEN
            RAISE EXCEPTION 'unexpected receipt exceeds effective tolerance'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    IF NEW.license_plate_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.license_plates plate
        WHERE plate.tenant_id = NEW.tenant_id
          AND plate.inventory_owner_id = NEW.inventory_owner_id
          AND plate.facility_id = NEW.facility_id
          AND plate.id = NEW.license_plate_id
          AND plate.location_id = NEW.receiving_location_id
          AND plate.barcode = NEW.license_plate_barcode
          AND plate.deleted IS NULL
        FOR SHARE
    ) THEN
        RAISE EXCEPTION 'unexpected receipt license plate evidence does not reconcile'
            USING ERRCODE = '23514';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.item_batches batch
        WHERE batch.tenant_id = NEW.tenant_id
          AND batch.inventory_owner_id = NEW.inventory_owner_id
          AND batch.id = NEW.item_batch_id
          AND batch.item_id = NEW.item_id
          AND batch.uom = NEW.uom
          AND batch.load_id = NEW.load_id
          AND batch.lot IS NOT DISTINCT FROM NEW.lot
          AND batch.serial IS NOT DISTINCT FROM NEW.serial
          AND batch.expiration IS NOT DISTINCT FROM NEW.expiration
        FOR SHARE
    ) OR NOT EXISTS (
        SELECT 1 FROM public.inventory_balances balance
        WHERE balance.tenant_id = NEW.tenant_id
          AND balance.inventory_owner_id = NEW.inventory_owner_id
          AND balance.facility_id = NEW.facility_id
          AND balance.id = NEW.inventory_balance_id
          AND balance.location_id = NEW.receiving_location_id
          AND balance.license_plate_id IS NOT DISTINCT FROM NEW.license_plate_id
          AND balance.item_batch_id = NEW.item_batch_id
          AND balance.item_id = NEW.item_id
          AND balance.uom = NEW.uom
          AND balance.status = 'quarantine'
          AND balance.deleted IS NULL
          AND balance.qty_on_hand >= NEW.quantity
          AND balance.qty_held >= NEW.quantity
        FOR SHARE
    ) OR NOT EXISTS (
        SELECT 1 FROM public.inventory_holds hold
        WHERE hold.tenant_id = NEW.tenant_id
          AND hold.inventory_owner_id = NEW.inventory_owner_id
          AND hold.facility_id = NEW.facility_id
          AND hold.id = NEW.inventory_hold_id
          AND hold.inventory_balance_id = NEW.inventory_balance_id
          AND hold.location_id = NEW.receiving_location_id
          AND hold.license_plate_id IS NOT DISTINCT FROM NEW.license_plate_id
          AND hold.item_batch_id = NEW.item_batch_id
          AND hold.item_id = NEW.item_id
          AND hold.uom = NEW.uom
          AND hold.inventory_status = 'quarantine'
          AND hold.qty = NEW.quantity
          AND hold.reason_code = expected_hold_reason
          AND hold.note IS NOT DISTINCT FROM NEW.note
          AND hold.reference_type = 'unexpected_receipt'
          AND hold.reference_id = NEW.id
          AND hold.status = 'active'
          AND hold.created_by = NEW.confirmed_by_user_id
          AND hold.created = NEW.confirmed_at
        FOR SHARE
    ) THEN
        RAISE EXCEPTION 'unexpected receipt inventory and hold evidence do not reconcile'
            USING ERRCODE = '23514';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.inventory_transactions txn
        WHERE txn.tenant_id = NEW.tenant_id
          AND txn.inventory_owner_id = NEW.inventory_owner_id
          AND txn.id = NEW.inventory_transaction_id
          AND txn.transaction_type = 'receive'
          AND txn.reason = NEW.reason_code
          AND txn.reference_type = 'unexpected_receipt'
          AND txn.reference_id = NEW.id
          AND txn.operation = 'inbound.confirm_unexpected_receipt.v2'
          AND txn.actor_user_id = NEW.confirmed_by_user_id
          AND txn.created = NEW.confirmed_at
    ) OR (SELECT COUNT(*) FROM public.inventory_entries entry
          WHERE entry.tenant_id = NEW.tenant_id
            AND entry.inventory_owner_id = NEW.inventory_owner_id
            AND entry.facility_id = NEW.facility_id
            AND entry.transaction_id = NEW.inventory_transaction_id) <> 1
       OR NOT EXISTS (
        SELECT 1 FROM public.inventory_entries entry
        WHERE entry.tenant_id = NEW.tenant_id
          AND entry.inventory_owner_id = NEW.inventory_owner_id
          AND entry.facility_id = NEW.facility_id
          AND entry.transaction_id = NEW.inventory_transaction_id
          AND entry.location_id = NEW.receiving_location_id
          AND entry.license_plate_id IS NOT DISTINCT FROM NEW.license_plate_id
          AND entry.item_batch_id = NEW.item_batch_id
          AND entry.status = 'quarantine'
          AND entry.quantity_delta = NEW.quantity
    ) THEN
        RAISE EXCEPTION 'unexpected receipt journal evidence does not reconcile'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.reject_unexpected_receipt_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    RAISE EXCEPTION 'unexpected receipts are immutable' USING ERRCODE = '55000';
END;
$$;

CREATE TRIGGER unexpected_receipts_validate
BEFORE INSERT ON public.unexpected_receipts
FOR EACH ROW EXECUTE FUNCTION public.validate_unexpected_receipt();
CREATE TRIGGER unexpected_receipts_are_immutable
BEFORE UPDATE OR DELETE ON public.unexpected_receipts
FOR EACH ROW EXECUTE FUNCTION public.reject_unexpected_receipt_mutation();

ALTER TABLE public.unexpected_receipts ENABLE ROW LEVEL SECURITY;
CREATE POLICY unexpected_receipts_tenant_isolation
ON public.unexpected_receipts
USING (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint)
WITH CHECK (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint);

GRANT SELECT,INSERT ON public.unexpected_receipts TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.unexpected_receipts_id_seq TO wareboxes_app;
REVOKE ALL ON FUNCTION public.validate_unexpected_receipt() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.reject_unexpected_receipt_mutation() FROM PUBLIC;

-- Whole-hold inbound inspection disposition. This composes hold release and a
-- conserved quarantine status change without relying on two independent UI commands.
CREATE TABLE public.inbound_inspection_dispositions (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    inventory_hold_id bigint NOT NULL,
    source_inventory_balance_id bigint NOT NULL,
    target_inventory_balance_id bigint NOT NULL,
    location_id bigint NOT NULL,
    license_plate_id bigint,
    item_batch_id bigint NOT NULL,
    item_id bigint NOT NULL,
    uom text NOT NULL,
    quantity bigint NOT NULL CHECK (quantity > 0),
    outcome text NOT NULL CHECK (outcome IN ('approved','damaged')),
    target_status text NOT NULL CHECK (target_status IN ('available','damaged')),
    note text NOT NULL,
    inventory_transaction_id bigint NOT NULL,
    inventory_status_transition_id bigint NOT NULL,
    source_reference_type text NOT NULL,
    source_reference_id bigint NOT NULL CHECK (source_reference_id > 0),
    inspected_by_user_id bigint NOT NULL,
    inspected_at timestamptz NOT NULL,
    CONSTRAINT inbound_inspection_dispositions_status_check CHECK (
        (outcome = 'approved' AND target_status = 'available')
        OR (outcome = 'damaged' AND target_status = 'damaged')
    ),
    CONSTRAINT inbound_inspection_dispositions_note_check CHECK (
        note = btrim(note) AND char_length(note) BETWEEN 1 AND 500
    ),
    CONSTRAINT inbound_inspection_dispositions_reference_check CHECK (
        source_reference_type IN ('expected_receipt_line','unexpected_receipt')
    ),
    CONSTRAINT inbound_inspection_dispositions_balance_check CHECK (
        source_inventory_balance_id <> target_inventory_balance_id
    ),
    CONSTRAINT inbound_inspection_dispositions_tenant_owner_id_key
        UNIQUE (tenant_id, inventory_owner_id, id),
    CONSTRAINT inbound_inspection_dispositions_hold_unique
        UNIQUE (tenant_id, inventory_hold_id),
    CONSTRAINT inbound_inspection_dispositions_transaction_unique
        UNIQUE (tenant_id, inventory_transaction_id),
    CONSTRAINT inbound_inspection_dispositions_transition_unique
        UNIQUE (tenant_id, inventory_status_transition_id),
    CONSTRAINT inbound_inspection_dispositions_owner_facility_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, facility_id)
        REFERENCES public.inventory_owner_facilities(tenant_id, inventory_owner_id, facility_id),
    CONSTRAINT inbound_inspection_dispositions_hold_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, inventory_hold_id)
        REFERENCES public.inventory_holds(tenant_id, inventory_owner_id, id),
    CONSTRAINT inbound_inspection_dispositions_source_balance_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, source_inventory_balance_id)
        REFERENCES public.inventory_balances(tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT inbound_inspection_dispositions_target_balance_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, target_inventory_balance_id)
        REFERENCES public.inventory_balances(tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT inbound_inspection_dispositions_location_fkey
        FOREIGN KEY (tenant_id, facility_id, location_id)
        REFERENCES public.locations(tenant_id, facility_id, id),
    CONSTRAINT inbound_inspection_dispositions_license_plate_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, license_plate_id)
        REFERENCES public.license_plates(tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT inbound_inspection_dispositions_batch_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, item_batch_id)
        REFERENCES public.item_batches(tenant_id, inventory_owner_id, id),
    CONSTRAINT inbound_inspection_dispositions_transaction_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, inventory_transaction_id)
        REFERENCES public.inventory_transactions(tenant_id, inventory_owner_id, id),
    CONSTRAINT inbound_inspection_dispositions_transition_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, inventory_status_transition_id)
        REFERENCES public.inventory_status_transitions(tenant_id, inventory_owner_id, id),
    CONSTRAINT inbound_inspection_dispositions_actor_fkey
        FOREIGN KEY (tenant_id, inspected_by_user_id)
        REFERENCES public.tenant_memberships(tenant_id, user_id)
);
ALTER TABLE public.inbound_inspection_dispositions FORCE ROW LEVEL SECURITY;
CREATE INDEX inbound_inspection_dispositions_receipt_idx
ON public.inbound_inspection_dispositions(
    tenant_id, inventory_owner_id, source_reference_type, source_reference_id, inspected_at, id
);

CREATE FUNCTION public.validate_inbound_inspection_disposition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    expected_reason text;
    receipt_matches boolean;
BEGIN
    expected_reason := CASE
        WHEN NEW.outcome = 'approved' THEN 'inspection_passed'
        ELSE 'damage_confirmed'
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM public.inventory_holds hold
        WHERE hold.tenant_id = NEW.tenant_id
          AND hold.inventory_owner_id = NEW.inventory_owner_id
          AND hold.facility_id = NEW.facility_id
          AND hold.id = NEW.inventory_hold_id
          AND hold.inventory_balance_id = NEW.source_inventory_balance_id
          AND hold.location_id = NEW.location_id
          AND hold.license_plate_id IS NOT DISTINCT FROM NEW.license_plate_id
          AND hold.item_batch_id = NEW.item_batch_id
          AND hold.item_id = NEW.item_id
          AND hold.uom = NEW.uom
          AND hold.inventory_status = 'quarantine'
          AND hold.qty = NEW.quantity
          AND hold.reference_type = NEW.source_reference_type
          AND hold.reference_id = NEW.source_reference_id
          AND hold.status = 'released'
          AND hold.deleted = NEW.inspected_at
          AND hold.released_by = NEW.inspected_by_user_id
          AND hold.released_at = NEW.inspected_at
        FOR SHARE
    ) THEN
        RAISE EXCEPTION 'inbound inspection disposition does not match its released receipt hold'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.source_reference_type = 'expected_receipt_line' THEN
        SELECT EXISTS (
            SELECT 1
            FROM public.load_lines line
            INNER JOIN public.loads load
              ON load.tenant_id = line.tenant_id
             AND load.id = line.load_id
            WHERE line.tenant_id = NEW.tenant_id
              AND line.id = NEW.source_reference_id
              AND line.item_id = NEW.item_id
              AND line.deleted IS NULL
              AND load.inventory_owner_id = NEW.inventory_owner_id
              AND load.facility_id = NEW.facility_id
              AND load.type = 'inbound'
              AND load.deleted IS NULL
        ) INTO receipt_matches;
    ELSE
        SELECT EXISTS (
            SELECT 1
            FROM public.unexpected_receipts receipt
            WHERE receipt.tenant_id = NEW.tenant_id
              AND receipt.inventory_owner_id = NEW.inventory_owner_id
              AND receipt.facility_id = NEW.facility_id
              AND receipt.id = NEW.source_reference_id
              AND receipt.inventory_hold_id = NEW.inventory_hold_id
              AND receipt.inventory_balance_id = NEW.source_inventory_balance_id
              AND receipt.item_id = NEW.item_id
              AND receipt.quantity = NEW.quantity
        ) INTO receipt_matches;
    END IF;
    IF NOT receipt_matches THEN
        RAISE EXCEPTION 'inbound inspection disposition receipt reference does not exist'
            USING ERRCODE = '23514';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.inventory_balances source
        WHERE source.tenant_id = NEW.tenant_id
          AND source.inventory_owner_id = NEW.inventory_owner_id
          AND source.facility_id = NEW.facility_id
          AND source.id = NEW.source_inventory_balance_id
          AND source.location_id = NEW.location_id
          AND source.license_plate_id IS NOT DISTINCT FROM NEW.license_plate_id
          AND source.item_batch_id = NEW.item_batch_id
          AND source.item_id = NEW.item_id
          AND source.uom = NEW.uom
          AND source.status = 'quarantine'
          AND source.deleted IS NULL
          AND source.qty_held = 0
        FOR SHARE
    ) OR NOT EXISTS (
        SELECT 1 FROM public.inventory_balances target
        WHERE target.tenant_id = NEW.tenant_id
          AND target.inventory_owner_id = NEW.inventory_owner_id
          AND target.facility_id = NEW.facility_id
          AND target.id = NEW.target_inventory_balance_id
          AND target.location_id = NEW.location_id
          AND target.license_plate_id IS NOT DISTINCT FROM NEW.license_plate_id
          AND target.item_batch_id = NEW.item_batch_id
          AND target.item_id = NEW.item_id
          AND target.uom = NEW.uom
          AND target.status = NEW.target_status
          AND target.deleted IS NULL
          AND target.qty_on_hand >= NEW.quantity
        FOR SHARE
    ) THEN
        RAISE EXCEPTION 'inbound inspection disposition balance projection does not reconcile'
            USING ERRCODE = '23514';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.inventory_transactions transaction
        WHERE transaction.tenant_id = NEW.tenant_id
          AND transaction.inventory_owner_id = NEW.inventory_owner_id
          AND transaction.id = NEW.inventory_transaction_id
          AND transaction.transaction_type = 'status_change'
          AND transaction.reason = expected_reason
          AND transaction.reference_type = 'inbound_inspection_hold'
          AND transaction.reference_id = NEW.inventory_hold_id
          AND transaction.operation = 'inbound.inspection.dispose.v1'
          AND transaction.actor_user_id = NEW.inspected_by_user_id
          AND transaction.created = NEW.inspected_at
    ) OR NOT EXISTS (
        SELECT 1
        FROM public.inventory_status_transitions transition
        WHERE transition.tenant_id = NEW.tenant_id
          AND transition.inventory_owner_id = NEW.inventory_owner_id
          AND transition.facility_id = NEW.facility_id
          AND transition.id = NEW.inventory_status_transition_id
          AND transition.transaction_id = NEW.inventory_transaction_id
          AND transition.source_balance_id = NEW.source_inventory_balance_id
          AND transition.destination_balance_id = NEW.target_inventory_balance_id
          AND transition.from_status = 'quarantine'
          AND transition.to_status = NEW.target_status
          AND transition.qty = NEW.quantity
          AND transition.reason_code = expected_reason
          AND transition.reason_note = NEW.note
          AND transition.reference_type = 'inbound_inspection_hold'
          AND transition.reference_id = NEW.inventory_hold_id
          AND transition.created_by = NEW.inspected_by_user_id
          AND transition.created = NEW.inspected_at
    ) THEN
        RAISE EXCEPTION 'inbound inspection disposition journal evidence does not reconcile'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;

CREATE FUNCTION public.reject_inbound_inspection_disposition_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    RAISE EXCEPTION 'inbound inspection dispositions are immutable' USING ERRCODE = '55000';
END;
$$;

CREATE TRIGGER inbound_inspection_dispositions_validate
BEFORE INSERT ON public.inbound_inspection_dispositions
FOR EACH ROW EXECUTE FUNCTION public.validate_inbound_inspection_disposition();
CREATE TRIGGER inbound_inspection_dispositions_are_immutable
BEFORE UPDATE OR DELETE ON public.inbound_inspection_dispositions
FOR EACH ROW EXECUTE FUNCTION public.reject_inbound_inspection_disposition_mutation();

CREATE FUNCTION public.require_inbound_receipt_hold_disposition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    IF OLD.status = 'active'
       AND NEW.status = 'released'
       AND OLD.reference_type IN ('expected_receipt_line','unexpected_receipt')
       AND NOT EXISTS (
           SELECT 1
           FROM public.inbound_inspection_dispositions disposition
           WHERE disposition.tenant_id = NEW.tenant_id
             AND disposition.inventory_owner_id = NEW.inventory_owner_id
             AND disposition.facility_id = NEW.facility_id
             AND disposition.inventory_hold_id = NEW.id
             AND disposition.source_inventory_balance_id = NEW.inventory_balance_id
             AND disposition.quantity = NEW.qty
             AND disposition.inspected_by_user_id = NEW.released_by
             AND disposition.inspected_at = NEW.released_at
       )
    THEN
        RAISE EXCEPTION
            'inbound receipt quarantine hold release requires an inspection disposition'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER inventory_holds_require_inbound_receipt_disposition
AFTER UPDATE ON public.inventory_holds
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_inbound_receipt_hold_disposition();

ALTER TABLE public.inbound_inspection_dispositions ENABLE ROW LEVEL SECURITY;
CREATE POLICY inbound_inspection_dispositions_tenant_isolation
ON public.inbound_inspection_dispositions
USING (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint)
WITH CHECK (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint);

GRANT SELECT,INSERT ON public.inbound_inspection_dispositions TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.inbound_inspection_dispositions_id_seq TO wareboxes_app;
REVOKE ALL ON FUNCTION public.validate_inbound_inspection_disposition() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.reject_inbound_inspection_disposition_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_inbound_receipt_hold_disposition() FROM PUBLIC;

-- Typed cycle-count tolerance, recount, and variance approval control.
CREATE TABLE public.cycle_count_policies (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    absolute_tolerance_qty bigint NOT NULL CHECK (absolute_tolerance_qty >= 0),
    percentage_tolerance_bps integer NOT NULL
        CHECK (percentage_tolerance_bps BETWEEN 0 AND 10000),
    automatic_recount_limit smallint NOT NULL
        CHECK (automatic_recount_limit BETWEEN 0 AND 10),
    revision bigint NOT NULL CHECK (revision > 0),
    supersedes_policy_id bigint,
    effective_from timestamptz NOT NULL,
    effective_to timestamptz,
    configured_by_user_id bigint NOT NULL,
    CONSTRAINT cycle_count_policies_effective_window_check
        CHECK (effective_to IS NULL OR effective_to >= effective_from),
    CONSTRAINT cycle_count_policies_scope_id_key
        UNIQUE (tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT cycle_count_policies_scope_revision_key
        UNIQUE (tenant_id, inventory_owner_id, facility_id, revision),
    CONSTRAINT cycle_count_policies_tenant_owner_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id)
        REFERENCES public.inventory_owners (tenant_id, id),
    CONSTRAINT cycle_count_policies_tenant_facility_fkey
        FOREIGN KEY (tenant_id, facility_id)
        REFERENCES public.facilities (tenant_id, id),
    CONSTRAINT cycle_count_policies_owner_facility_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, facility_id)
        REFERENCES public.inventory_owner_facilities
            (tenant_id, inventory_owner_id, facility_id),
    CONSTRAINT cycle_count_policies_configured_by_fkey
        FOREIGN KEY (tenant_id, configured_by_user_id)
        REFERENCES public.tenant_memberships (tenant_id, user_id),
    CONSTRAINT cycle_count_policies_supersedes_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, supersedes_policy_id)
        REFERENCES public.cycle_count_policies
            (tenant_id, inventory_owner_id, facility_id, id)
);

CREATE UNIQUE INDEX cycle_count_policies_active_key
ON public.cycle_count_policies (tenant_id, inventory_owner_id, facility_id)
WHERE effective_to IS NULL;

CREATE TABLE public.cycle_count_variance_cases (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    inventory_balance_id bigint NOT NULL,
    location_id bigint NOT NULL,
    item_id bigint NOT NULL,
    item_batch_id bigint NOT NULL,
    license_plate_id bigint,
    uom text NOT NULL CHECK (btrim(uom) <> ''),
    lot text,
    expiration timestamptz,
    serial text,
    inventory_status text NOT NULL
        CHECK (inventory_status IN ('available','hold','damaged','quarantine')),
    policy_id bigint NOT NULL,
    policy_revision bigint NOT NULL CHECK (policy_revision > 0),
    absolute_tolerance_qty bigint NOT NULL CHECK (absolute_tolerance_qty >= 0),
    percentage_tolerance_bps integer NOT NULL
        CHECK (percentage_tolerance_bps BETWEEN 0 AND 10000),
    automatic_recount_limit smallint NOT NULL
        CHECK (automatic_recount_limit BETWEEN 0 AND 10),
    latest_task_id bigint NOT NULL,
    latest_attempt_sequence smallint NOT NULL CHECK (latest_attempt_sequence > 0),
    automatic_recounts_used smallint NOT NULL
        CHECK (automatic_recounts_used BETWEEN 0 AND 10),
    system_qty_on_hand bigint NOT NULL CHECK (system_qty_on_hand >= 0),
    system_qty_reserved bigint NOT NULL CHECK (system_qty_reserved >= 0),
    system_qty_held bigint NOT NULL CHECK (system_qty_held >= 0),
    counted_qty bigint NOT NULL CHECK (counted_qty >= 0),
    variance_qty bigint NOT NULL,
    allowed_variance_qty bigint NOT NULL CHECK (allowed_variance_qty >= 0),
    state text NOT NULL CHECK (state IN ('awaiting_recount','awaiting_approval','posted')),
    revision bigint NOT NULL CHECK (revision > 0),
    inventory_transaction_id bigint,
    created_at timestamptz NOT NULL,
    modified_at timestamptz NOT NULL,
    resolved_by_user_id bigint,
    resolved_at timestamptz,
    CONSTRAINT cycle_count_variance_cases_quantity_check
        CHECK (variance_qty = counted_qty - system_qty_on_hand),
    CONSTRAINT cycle_count_variance_cases_commitment_check
        CHECK (counted_qty >= system_qty_reserved + system_qty_held),
    CONSTRAINT cycle_count_variance_cases_resolution_check CHECK (
        (state = 'posted' AND ((variance_qty = 0) = (inventory_transaction_id IS NULL))
            AND resolved_by_user_id IS NOT NULL AND resolved_at IS NOT NULL)
        OR
        (state <> 'posted' AND inventory_transaction_id IS NULL
            AND resolved_by_user_id IS NULL AND resolved_at IS NULL)
    ),
    CONSTRAINT cycle_count_variance_cases_scope_id_key
        UNIQUE (tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT cycle_count_variance_cases_scope_revision_key
        UNIQUE (tenant_id, inventory_owner_id, facility_id, id, revision),
    CONSTRAINT cycle_count_variance_cases_balance_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, inventory_balance_id)
        REFERENCES public.inventory_balances
            (tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT cycle_count_variance_cases_policy_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, policy_id)
        REFERENCES public.cycle_count_policies
            (tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT cycle_count_variance_cases_task_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, latest_task_id)
        REFERENCES public.work_tasks
            (tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT cycle_count_variance_cases_resolved_by_fkey
        FOREIGN KEY (tenant_id, resolved_by_user_id)
        REFERENCES public.tenant_memberships (tenant_id, user_id)
);

CREATE UNIQUE INDEX cycle_count_variance_cases_active_balance_key
ON public.cycle_count_variance_cases
    (tenant_id, inventory_owner_id, facility_id, inventory_balance_id)
WHERE state <> 'posted';

CREATE INDEX cycle_count_variance_cases_queue_idx
ON public.cycle_count_variance_cases
    (tenant_id, state, facility_id, inventory_owner_id, modified_at, id);

CREATE TABLE public.cycle_count_variance_decisions (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    variance_case_id bigint NOT NULL,
    expected_revision bigint NOT NULL CHECK (expected_revision > 0),
    resulting_revision bigint NOT NULL CHECK (resulting_revision = expected_revision + 1),
    decision text NOT NULL CHECK (decision IN ('approve_adjustment','request_recount')),
    reason_code text NOT NULL CHECK (reason_code IN (
        'verified_physical_count','packaging_or_uom_issue',
        'receiving_or_shipping_timing','suspected_miscount','other'
    )),
    note text,
    next_task_id bigint,
    inventory_transaction_id bigint,
    decided_by_user_id bigint NOT NULL,
    decided_at timestamptz NOT NULL,
    CONSTRAINT cycle_count_variance_decisions_note_check CHECK (
        note IS NULL OR (note = btrim(note) AND char_length(note) BETWEEN 1 AND 500)
    ),
    CONSTRAINT cycle_count_variance_decisions_other_note_check
        CHECK (reason_code <> 'other' OR note IS NOT NULL),
    CONSTRAINT cycle_count_variance_decisions_effect_check CHECK (
        (decision = 'approve_adjustment' AND inventory_transaction_id IS NOT NULL
            AND next_task_id IS NULL)
        OR
        (decision = 'request_recount' AND inventory_transaction_id IS NULL
            AND next_task_id IS NOT NULL)
    ),
    CONSTRAINT cycle_count_variance_decisions_scope_id_key
        UNIQUE (tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT cycle_count_variance_decisions_revision_key
        UNIQUE (tenant_id, inventory_owner_id, variance_case_id, expected_revision),
    CONSTRAINT cycle_count_variance_decisions_case_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, variance_case_id)
        REFERENCES public.cycle_count_variance_cases
            (tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT cycle_count_variance_decisions_next_task_fkey
        FOREIGN KEY (tenant_id, next_task_id)
        REFERENCES public.work_tasks (tenant_id, id),
    CONSTRAINT cycle_count_variance_decisions_transaction_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, inventory_transaction_id)
        REFERENCES public.inventory_transactions (tenant_id, inventory_owner_id, id),
    CONSTRAINT cycle_count_variance_decisions_actor_fkey
        FOREIGN KEY (tenant_id, decided_by_user_id)
        REFERENCES public.tenant_memberships (tenant_id, user_id)
);

ALTER TABLE public.cycle_count_item_location_tasks
    ADD COLUMN variance_case_id bigint,
    ADD COLUMN attempt_sequence smallint NOT NULL DEFAULT 1
        CHECK (attempt_sequence > 0),
    ADD CONSTRAINT cycle_count_item_location_tasks_variance_case_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, variance_case_id)
        REFERENCES public.cycle_count_variance_cases
            (tenant_id, inventory_owner_id, facility_id, id);

ALTER TABLE public.cycle_count_item_location_results
    DROP CONSTRAINT cycle_count_item_location_results_check3,
    ADD COLUMN disposition text NOT NULL DEFAULT 'posted'
        CHECK (disposition IN ('posted','recount_required','approval_required')),
    ADD COLUMN variance_case_id bigint,
    ADD COLUMN attempt_sequence smallint NOT NULL DEFAULT 1
        CHECK (attempt_sequence > 0),
    ADD COLUMN policy_id bigint,
    ADD COLUMN policy_revision bigint,
    ADD COLUMN absolute_tolerance_qty bigint,
    ADD COLUMN percentage_tolerance_bps integer,
    ADD COLUMN automatic_recount_limit smallint,
    ADD COLUMN allowed_variance_qty bigint,
    ADD CONSTRAINT cycle_count_item_location_results_posting_check CHECK (
        (disposition = 'posted' AND ((variance_qty = 0) = (inventory_transaction_id IS NULL)))
        OR (disposition <> 'posted' AND inventory_transaction_id IS NULL)
    ),
    ADD CONSTRAINT cycle_count_item_location_results_policy_snapshot_check CHECK (
        (policy_id IS NULL AND policy_revision IS NULL
            AND absolute_tolerance_qty IS NULL
            AND percentage_tolerance_bps IS NULL
            AND automatic_recount_limit IS NULL
            AND allowed_variance_qty IS NULL)
        OR
        (policy_id IS NOT NULL AND policy_revision > 0
            AND absolute_tolerance_qty >= 0
            AND percentage_tolerance_bps BETWEEN 0 AND 10000
            AND automatic_recount_limit BETWEEN 0 AND 10
            AND allowed_variance_qty >= 0)
    ),
    ADD CONSTRAINT cycle_count_item_location_results_case_required_check CHECK (
        disposition = 'posted' OR variance_case_id IS NOT NULL
    ),
    ADD CONSTRAINT cycle_count_item_location_results_variance_case_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, variance_case_id)
        REFERENCES public.cycle_count_variance_cases
            (tenant_id, inventory_owner_id, facility_id, id),
    ADD CONSTRAINT cycle_count_item_location_results_policy_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, policy_id)
        REFERENCES public.cycle_count_policies
            (tenant_id, inventory_owner_id, facility_id, id);

CREATE FUNCTION public.guard_cycle_count_policy_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'cycle count policy versions cannot be deleted' USING ERRCODE = '55000';
    END IF;
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM OLD.facility_id
       OR NEW.absolute_tolerance_qty IS DISTINCT FROM OLD.absolute_tolerance_qty
       OR NEW.percentage_tolerance_bps IS DISTINCT FROM OLD.percentage_tolerance_bps
       OR NEW.automatic_recount_limit IS DISTINCT FROM OLD.automatic_recount_limit
       OR NEW.revision IS DISTINCT FROM OLD.revision
       OR NEW.supersedes_policy_id IS DISTINCT FROM OLD.supersedes_policy_id
       OR NEW.effective_from IS DISTINCT FROM OLD.effective_from
       OR NEW.configured_by_user_id IS DISTINCT FROM OLD.configured_by_user_id
       OR OLD.effective_to IS NOT NULL
       OR NEW.effective_to IS NULL
    THEN
        RAISE EXCEPTION 'cycle count policy facts are immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.guard_cycle_count_variance_case_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'cycle count variance cases cannot be deleted' USING ERRCODE = '55000';
    END IF;
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM OLD.facility_id
       OR NEW.inventory_balance_id IS DISTINCT FROM OLD.inventory_balance_id
       OR NEW.location_id IS DISTINCT FROM OLD.location_id
       OR NEW.item_id IS DISTINCT FROM OLD.item_id
       OR NEW.item_batch_id IS DISTINCT FROM OLD.item_batch_id
       OR NEW.license_plate_id IS DISTINCT FROM OLD.license_plate_id
       OR NEW.uom IS DISTINCT FROM OLD.uom
       OR NEW.lot IS DISTINCT FROM OLD.lot
       OR NEW.expiration IS DISTINCT FROM OLD.expiration
       OR NEW.serial IS DISTINCT FROM OLD.serial
       OR NEW.inventory_status IS DISTINCT FROM OLD.inventory_status
       OR NEW.policy_id IS DISTINCT FROM OLD.policy_id
       OR NEW.policy_revision IS DISTINCT FROM OLD.policy_revision
       OR NEW.absolute_tolerance_qty IS DISTINCT FROM OLD.absolute_tolerance_qty
       OR NEW.percentage_tolerance_bps IS DISTINCT FROM OLD.percentage_tolerance_bps
       OR NEW.automatic_recount_limit IS DISTINCT FROM OLD.automatic_recount_limit
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.revision <> OLD.revision + 1
       OR NEW.modified_at < OLD.modified_at
       OR OLD.state = 'posted'
    THEN
        RAISE EXCEPTION 'cycle count variance case mutation is invalid' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.reject_cycle_count_variance_decision_mutation() RETURNS trigger
    LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'cycle count variance decisions are immutable' USING ERRCODE = '55000';
END;
$$;

CREATE OR REPLACE FUNCTION public.validate_item_location_cycle_count_result() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    task_row RECORD;
    balance_row RECORD;
    transaction_matches BOOLEAN;
    matching_entry_count BIGINT;
    transaction_entry_count BIGINT;
BEGIN
    SELECT task.status, task.assigned_user_id, task.deleted, task.lease_expires_at,
           detail.inventory_owner_id, detail.facility_id, detail.location_id,
           detail.item_id, detail.inventory_balance_id, detail.variance_case_id,
           detail.attempt_sequence
    INTO task_row
    FROM public.work_tasks task
    JOIN public.cycle_count_item_location_tasks detail
      ON detail.tenant_id = task.tenant_id AND detail.task_id = task.id
    WHERE task.tenant_id = NEW.tenant_id AND task.id = NEW.task_id
      AND task.task_type = 'cycle_count_item_location'
    FOR UPDATE OF task, detail;

    IF NOT FOUND OR task_row.deleted IS NOT NULL OR task_row.status <> 'in_progress'
       OR task_row.assigned_user_id IS DISTINCT FROM NEW.confirmed_by
       OR task_row.lease_expires_at IS NULL
       OR task_row.lease_expires_at <= statement_timestamp()
       OR task_row.inventory_owner_id IS DISTINCT FROM NEW.inventory_owner_id
       OR task_row.facility_id IS DISTINCT FROM NEW.facility_id
       OR task_row.location_id IS DISTINCT FROM NEW.location_id
       OR task_row.item_id IS DISTINCT FROM NEW.item_id
       OR task_row.inventory_balance_id IS DISTINCT FROM NEW.inventory_balance_id
       OR task_row.variance_case_id IS DISTINCT FROM NEW.variance_case_id
       OR task_row.attempt_sequence IS DISTINCT FROM NEW.attempt_sequence
    THEN
        RAISE EXCEPTION 'cycle count result does not match an active task claim'
            USING ERRCODE = '55000';
    END IF;

    SELECT balance.item_batch_id, balance.license_plate_id, balance.uom,
           batch.lot, batch.expiration, batch.serial, balance.status,
           balance.qty_on_hand, balance.qty_reserved, balance.qty_held, balance.deleted
    INTO balance_row
    FROM public.inventory_balances balance
    JOIN public.item_batches batch
      ON batch.tenant_id = balance.tenant_id
     AND batch.inventory_owner_id = balance.inventory_owner_id
     AND batch.id = balance.item_batch_id
    WHERE balance.tenant_id = NEW.tenant_id
      AND balance.inventory_owner_id = NEW.inventory_owner_id
      AND balance.facility_id = NEW.facility_id
      AND balance.location_id = NEW.location_id
      AND balance.item_id = NEW.item_id
      AND balance.id = NEW.inventory_balance_id
    FOR UPDATE;

    IF NOT FOUND OR balance_row.deleted IS NOT NULL
       OR balance_row.item_batch_id IS DISTINCT FROM NEW.item_batch_id
       OR balance_row.license_plate_id IS DISTINCT FROM NEW.license_plate_id
       OR balance_row.uom IS DISTINCT FROM NEW.uom
       OR balance_row.lot IS DISTINCT FROM NEW.lot
       OR balance_row.expiration IS DISTINCT FROM NEW.expiration
       OR balance_row.serial IS DISTINCT FROM NEW.serial
       OR balance_row.status IS DISTINCT FROM NEW.status
       OR balance_row.qty_reserved IS DISTINCT FROM NEW.system_qty_reserved
       OR balance_row.qty_held IS DISTINCT FROM NEW.system_qty_held
       OR (NEW.disposition = 'posted' AND balance_row.qty_on_hand IS DISTINCT FROM NEW.counted_qty)
       OR (NEW.disposition <> 'posted' AND balance_row.qty_on_hand IS DISTINCT FROM NEW.system_qty_on_hand)
    THEN
        RAISE EXCEPTION 'cycle count result does not match the current balance'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.disposition = 'posted' AND NEW.variance_qty <> 0 THEN
        SELECT EXISTS (
            SELECT 1 FROM public.inventory_transactions transaction
            WHERE transaction.tenant_id = NEW.tenant_id
              AND transaction.inventory_owner_id = NEW.inventory_owner_id
              AND transaction.id = NEW.inventory_transaction_id
              AND transaction.transaction_type = 'adjust'
              AND transaction.actor_user_id = NEW.confirmed_by
              AND transaction.reference_type = 'cycle_count_item_location_task'
              AND transaction.reference_id = NEW.task_id
              AND transaction.operation = 'task.confirm_item_location_cycle_count.v1'
        ) INTO transaction_matches;

        SELECT COUNT(*), COUNT(*) FILTER (
            WHERE entry.facility_id = NEW.facility_id
              AND entry.location_id = NEW.location_id
              AND entry.item_batch_id = NEW.item_batch_id
              AND entry.item_id = NEW.item_id
              AND entry.license_plate_id IS NOT DISTINCT FROM NEW.license_plate_id
              AND entry.uom = NEW.uom AND entry.status = NEW.status
              AND entry.quantity_delta = NEW.variance_qty
        )
        INTO transaction_entry_count, matching_entry_count
        FROM public.inventory_entries entry
        WHERE entry.tenant_id = NEW.tenant_id
          AND entry.inventory_owner_id = NEW.inventory_owner_id
          AND entry.transaction_id = NEW.inventory_transaction_id;

        IF NOT transaction_matches OR transaction_entry_count <> 1 OR matching_entry_count <> 1 THEN
            RAISE EXCEPTION 'cycle count adjustment does not match its result'
                USING ERRCODE = '55000';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER cycle_count_policies_guard_mutation
BEFORE UPDATE OR DELETE ON public.cycle_count_policies
FOR EACH ROW EXECUTE FUNCTION public.guard_cycle_count_policy_mutation();
CREATE TRIGGER cycle_count_variance_cases_guard_mutation
BEFORE UPDATE OR DELETE ON public.cycle_count_variance_cases
FOR EACH ROW EXECUTE FUNCTION public.guard_cycle_count_variance_case_mutation();
CREATE TRIGGER cycle_count_variance_decisions_are_immutable
BEFORE UPDATE OR DELETE ON public.cycle_count_variance_decisions
FOR EACH ROW EXECUTE FUNCTION public.reject_cycle_count_variance_decision_mutation();

ALTER TABLE public.cycle_count_policies ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cycle_count_policies FORCE ROW LEVEL SECURITY;
CREATE POLICY cycle_count_policies_tenant_isolation ON public.cycle_count_policies
USING (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint)
WITH CHECK (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint);
ALTER TABLE public.cycle_count_variance_cases ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cycle_count_variance_cases FORCE ROW LEVEL SECURITY;
CREATE POLICY cycle_count_variance_cases_tenant_isolation ON public.cycle_count_variance_cases
USING (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint)
WITH CHECK (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint);
ALTER TABLE public.cycle_count_variance_decisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cycle_count_variance_decisions FORCE ROW LEVEL SECURITY;
CREATE POLICY cycle_count_variance_decisions_tenant_isolation ON public.cycle_count_variance_decisions
USING (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint)
WITH CHECK (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint);

GRANT SELECT,INSERT ON public.cycle_count_policies TO wareboxes_app;
GRANT UPDATE (effective_to) ON public.cycle_count_policies TO wareboxes_app;
GRANT SELECT,INSERT ON public.cycle_count_variance_cases TO wareboxes_app;
GRANT UPDATE (
    latest_task_id, latest_attempt_sequence, automatic_recounts_used,
    system_qty_on_hand, system_qty_reserved, system_qty_held, counted_qty,
    variance_qty, allowed_variance_qty, state, revision, inventory_transaction_id,
    modified_at, resolved_by_user_id, resolved_at
) ON public.cycle_count_variance_cases TO wareboxes_app;
GRANT SELECT,INSERT ON public.cycle_count_variance_decisions TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.cycle_count_policies_id_seq TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.cycle_count_variance_cases_id_seq TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.cycle_count_variance_decisions_id_seq TO wareboxes_app;
REVOKE ALL ON FUNCTION public.guard_cycle_count_policy_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_cycle_count_variance_case_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.reject_cycle_count_variance_decision_mutation() FROM PUBLIC;

-- Facility-scoped item-batch recalls and exact hold evidence.
CREATE TABLE public.inventory_recall_cases (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    item_batch_id bigint NOT NULL,
    item_id bigint NOT NULL,
    uom text NOT NULL,
    lot text,
    expiration timestamp with time zone,
    serial text,
    state text NOT NULL DEFAULT 'active',
    revision bigint NOT NULL DEFAULT 1,
    reason_code text NOT NULL,
    note text,
    affected_position_count integer NOT NULL,
    held_qty bigint NOT NULL,
    created_by_user_id bigint NOT NULL,
    created_at timestamp with time zone NOT NULL,
    modified_at timestamp with time zone NOT NULL,
    released_by_user_id bigint,
    released_at timestamp with time zone,
    CONSTRAINT inventory_recall_cases_state_check
        CHECK (state IN ('active', 'released')),
    CONSTRAINT inventory_recall_cases_revision_check CHECK (revision > 0),
    CONSTRAINT inventory_recall_cases_reason_check
        CHECK (reason_code IN ('regulatory', 'supplier_notice', 'customer_request', 'quality_concern', 'other')),
    CONSTRAINT inventory_recall_cases_note_check
        CHECK (note IS NULL OR (btrim(note) = note AND note <> '' AND char_length(note) <= 500)),
    CONSTRAINT inventory_recall_cases_other_note_check
        CHECK (reason_code <> 'other' OR note IS NOT NULL),
    CONSTRAINT inventory_recall_cases_position_count_check CHECK (affected_position_count > 0),
    CONSTRAINT inventory_recall_cases_held_qty_check CHECK (held_qty > 0),
    CONSTRAINT inventory_recall_cases_lifecycle_check CHECK (
        (state = 'active' AND revision = 1 AND released_by_user_id IS NULL AND released_at IS NULL)
        OR
        (state = 'released' AND revision = 2 AND released_by_user_id IS NOT NULL
         AND released_at IS NOT NULL AND modified_at = released_at)
    ),
    CONSTRAINT inventory_recall_cases_scope_unique
        UNIQUE (tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT inventory_recall_cases_tenant_id_id_unique UNIQUE (tenant_id, id),
    CONSTRAINT inventory_recall_cases_owner_facility_fk
        FOREIGN KEY (tenant_id, inventory_owner_id, facility_id)
        REFERENCES public.inventory_owner_facilities (tenant_id, inventory_owner_id, facility_id),
    CONSTRAINT inventory_recall_cases_batch_fk
        FOREIGN KEY (tenant_id, inventory_owner_id, item_batch_id)
        REFERENCES public.item_batches (tenant_id, inventory_owner_id, id),
    CONSTRAINT inventory_recall_cases_item_fk
        FOREIGN KEY (tenant_id, item_id) REFERENCES public.items (tenant_id, id),
    CONSTRAINT inventory_recall_cases_created_by_fk
        FOREIGN KEY (tenant_id, created_by_user_id)
        REFERENCES public.tenant_memberships (tenant_id, user_id),
    CONSTRAINT inventory_recall_cases_released_by_fk
        FOREIGN KEY (tenant_id, released_by_user_id)
        REFERENCES public.tenant_memberships (tenant_id, user_id)
);

CREATE UNIQUE INDEX inventory_recall_cases_active_batch_idx
ON public.inventory_recall_cases (tenant_id, inventory_owner_id, facility_id, item_batch_id)
WHERE state = 'active';
CREATE INDEX inventory_recall_cases_queue_idx
ON public.inventory_recall_cases (tenant_id, state, id DESC);

CREATE TABLE public.inventory_recall_case_holds (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    recall_case_id bigint NOT NULL,
    inventory_hold_id bigint NOT NULL,
    inventory_balance_id bigint NOT NULL,
    held_qty bigint NOT NULL CHECK (held_qty > 0),
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT inventory_recall_case_holds_case_balance_unique
        UNIQUE (tenant_id, recall_case_id, inventory_balance_id),
    CONSTRAINT inventory_recall_case_holds_hold_unique
        UNIQUE (tenant_id, inventory_hold_id),
    CONSTRAINT inventory_recall_case_holds_case_fk
        FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, recall_case_id)
        REFERENCES public.inventory_recall_cases (tenant_id, inventory_owner_id, facility_id, id),
    CONSTRAINT inventory_recall_case_holds_hold_fk
        FOREIGN KEY (tenant_id, inventory_owner_id, inventory_hold_id)
        REFERENCES public.inventory_holds (tenant_id, inventory_owner_id, id),
    CONSTRAINT inventory_recall_case_holds_balance_fk
        FOREIGN KEY (tenant_id, inventory_owner_id, inventory_balance_id)
        REFERENCES public.inventory_balances (tenant_id, inventory_owner_id, id)
);

CREATE FUNCTION public.lock_inventory_recall_natural_key() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    row_tenant bigint;
    row_facility bigint;
    row_batch bigint;
BEGIN
    row_tenant := COALESCE(NEW.tenant_id, OLD.tenant_id);
    row_facility := COALESCE(NEW.facility_id, OLD.facility_id);
    row_batch := COALESCE(NEW.item_batch_id, OLD.item_batch_id);
    PERFORM pg_advisory_xact_lock(hashtextextended(
        row_tenant::text || ':' || row_facility::text || ':' || row_batch::text,
        774211
    ));
    RETURN COALESCE(NEW, OLD);
END;
$$;

CREATE FUNCTION public.validate_inventory_recall_case() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    batch_row RECORD;
BEGIN
    SELECT item_id, uom, lot, expiration, serial, deleted
    INTO batch_row
    FROM public.item_batches
    WHERE tenant_id = NEW.tenant_id
      AND inventory_owner_id = NEW.inventory_owner_id
      AND id = NEW.item_batch_id
    FOR SHARE;
    IF NOT FOUND OR batch_row.deleted IS NOT NULL
       OR batch_row.item_id IS DISTINCT FROM NEW.item_id
       OR batch_row.uom IS DISTINCT FROM NEW.uom
       OR batch_row.lot IS DISTINCT FROM NEW.lot
       OR batch_row.expiration IS DISTINCT FROM NEW.expiration
       OR batch_row.serial IS DISTINCT FROM NEW.serial
    THEN
        RAISE EXCEPTION 'inventory recall does not match the active item batch'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.guard_inventory_recall_case_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'inventory recall cases cannot be deleted' USING ERRCODE = '55000';
    END IF;
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM OLD.facility_id
       OR NEW.item_batch_id IS DISTINCT FROM OLD.item_batch_id
       OR NEW.item_id IS DISTINCT FROM OLD.item_id
       OR NEW.uom IS DISTINCT FROM OLD.uom
       OR NEW.lot IS DISTINCT FROM OLD.lot
       OR NEW.expiration IS DISTINCT FROM OLD.expiration
       OR NEW.serial IS DISTINCT FROM OLD.serial
       OR NEW.reason_code IS DISTINCT FROM OLD.reason_code
       OR NEW.note IS DISTINCT FROM OLD.note
       OR NEW.affected_position_count IS DISTINCT FROM OLD.affected_position_count
       OR NEW.held_qty IS DISTINCT FROM OLD.held_qty
       OR NEW.created_by_user_id IS DISTINCT FROM OLD.created_by_user_id
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR OLD.state <> 'active' OR NEW.state <> 'released'
       OR NEW.revision <> OLD.revision + 1
       OR NEW.released_by_user_id IS NULL OR NEW.released_at IS NULL
       OR NEW.modified_at IS DISTINCT FROM NEW.released_at
    THEN
        RAISE EXCEPTION 'inventory recall case mutation is invalid' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.reject_inventory_recall_case_hold_mutation() RETURNS trigger
    LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'inventory recall hold evidence is immutable' USING ERRCODE = '55000';
END;
$$;

CREATE FUNCTION public.require_inventory_recall_consistency() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    case_row public.inventory_recall_cases%ROWTYPE;
    balance_count bigint;
    balance_qty bigint;
    reserved_qty bigint;
    evidence_count bigint;
    evidence_qty bigint;
    invalid_evidence_count bigint;
BEGIN
    IF TG_TABLE_NAME = 'inventory_recall_cases' THEN
        SELECT * INTO case_row FROM public.inventory_recall_cases
        WHERE tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id)
          AND id = COALESCE(NEW.id, OLD.id);
    ELSIF TG_TABLE_NAME = 'inventory_recall_case_holds' THEN
        SELECT * INTO case_row FROM public.inventory_recall_cases
        WHERE tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id)
          AND id = COALESCE(NEW.recall_case_id, OLD.recall_case_id);
    ELSIF TG_TABLE_NAME = 'inventory_holds' THEN
        SELECT recall.* INTO case_row
        FROM public.inventory_recall_case_holds link
        JOIN public.inventory_recall_cases recall
          ON recall.tenant_id = link.tenant_id AND recall.id = link.recall_case_id
        WHERE link.tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id)
          AND link.inventory_hold_id = COALESCE(NEW.id, OLD.id);
    ELSE
        SELECT recall.* INTO case_row
        FROM public.inventory_recall_cases recall
        WHERE recall.tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id)
          AND recall.inventory_owner_id = COALESCE(NEW.inventory_owner_id, OLD.inventory_owner_id)
          AND recall.facility_id = COALESCE(NEW.facility_id, OLD.facility_id)
          AND recall.item_batch_id = COALESCE(NEW.item_batch_id, OLD.item_batch_id)
          AND recall.state = 'active';
    END IF;
    IF NOT FOUND THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    SELECT COUNT(*), COALESCE(SUM(qty_on_hand), 0), COALESCE(SUM(qty_reserved), 0)
    INTO balance_count, balance_qty, reserved_qty
    FROM public.inventory_balances
    WHERE tenant_id = case_row.tenant_id
      AND inventory_owner_id = case_row.inventory_owner_id
      AND facility_id = case_row.facility_id
      AND item_batch_id = case_row.item_batch_id
      AND deleted IS NULL AND qty_on_hand > 0;

    SELECT COUNT(*), COALESCE(SUM(link.held_qty), 0), COUNT(*) FILTER (
        WHERE hold.id IS NULL
           OR hold.inventory_balance_id <> link.inventory_balance_id
           OR hold.facility_id <> case_row.facility_id
           OR hold.item_batch_id <> case_row.item_batch_id
           OR hold.qty <> link.held_qty
           OR hold.reference_type <> 'inventory_recall'
           OR hold.reference_id <> case_row.id
           OR (case_row.state = 'active' AND (
                balance.id IS NULL
                OR balance.deleted IS NOT NULL
                OR balance.qty_on_hand <> link.held_qty
                OR balance.qty_held <> balance.qty_on_hand
                OR balance.qty_reserved <> 0
                OR hold.status <> 'active'
                OR hold.deleted IS NOT NULL
           ))
           OR (case_row.state = 'released' AND (hold.status <> 'released' OR hold.deleted IS NULL))
    )
    INTO evidence_count, evidence_qty, invalid_evidence_count
    FROM public.inventory_recall_case_holds link
    LEFT JOIN public.inventory_holds hold
      ON hold.tenant_id = link.tenant_id AND hold.id = link.inventory_hold_id
    LEFT JOIN public.inventory_balances balance
      ON balance.tenant_id = link.tenant_id AND balance.id = link.inventory_balance_id
    WHERE link.tenant_id = case_row.tenant_id AND link.recall_case_id = case_row.id;

    IF evidence_count <> case_row.affected_position_count
       OR evidence_qty <> case_row.held_qty
       OR invalid_evidence_count <> 0
       OR (case_row.state = 'active' AND (
            balance_count <> case_row.affected_position_count
            OR balance_qty <> case_row.held_qty
            OR reserved_qty <> 0
       ))
    THEN
        RAISE EXCEPTION 'inventory recall does not exactly cover current batch positions'
            USING ERRCODE = '55000';
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;

CREATE TRIGGER inventory_recall_cases_lock_natural_key
BEFORE INSERT OR UPDATE OR DELETE ON public.inventory_recall_cases
FOR EACH ROW EXECUTE FUNCTION public.lock_inventory_recall_natural_key();
CREATE TRIGGER inventory_balances_lock_recall_natural_key
BEFORE INSERT OR UPDATE OR DELETE ON public.inventory_balances
FOR EACH ROW EXECUTE FUNCTION public.lock_inventory_recall_natural_key();
CREATE TRIGGER inventory_recall_cases_validate
BEFORE INSERT ON public.inventory_recall_cases
FOR EACH ROW EXECUTE FUNCTION public.validate_inventory_recall_case();
CREATE TRIGGER inventory_recall_cases_guard
BEFORE UPDATE OR DELETE ON public.inventory_recall_cases
FOR EACH ROW EXECUTE FUNCTION public.guard_inventory_recall_case_mutation();
CREATE TRIGGER inventory_recall_case_holds_immutable
BEFORE UPDATE OR DELETE ON public.inventory_recall_case_holds
FOR EACH ROW EXECUTE FUNCTION public.reject_inventory_recall_case_hold_mutation();

CREATE CONSTRAINT TRIGGER inventory_recall_cases_consistent
AFTER INSERT OR UPDATE ON public.inventory_recall_cases DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_inventory_recall_consistency();
CREATE CONSTRAINT TRIGGER inventory_recall_case_holds_consistent
AFTER INSERT OR UPDATE OR DELETE ON public.inventory_recall_case_holds DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_inventory_recall_consistency();
CREATE CONSTRAINT TRIGGER inventory_recall_holds_consistent
AFTER INSERT OR UPDATE OR DELETE ON public.inventory_holds DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_inventory_recall_consistency();
CREATE CONSTRAINT TRIGGER inventory_recall_balances_consistent
AFTER INSERT OR UPDATE OR DELETE ON public.inventory_balances DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_inventory_recall_consistency();

ALTER TABLE public.inventory_recall_cases ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.inventory_recall_cases FORCE ROW LEVEL SECURITY;
CREATE POLICY inventory_recall_cases_tenant_isolation ON public.inventory_recall_cases
USING (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint)
WITH CHECK (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint);
ALTER TABLE public.inventory_recall_case_holds ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.inventory_recall_case_holds FORCE ROW LEVEL SECURITY;
CREATE POLICY inventory_recall_case_holds_tenant_isolation ON public.inventory_recall_case_holds
USING (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint)
WITH CHECK (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint);

GRANT SELECT, INSERT ON public.inventory_recall_cases TO wareboxes_app;
GRANT UPDATE (state, revision, modified_at, released_by_user_id, released_at)
ON public.inventory_recall_cases TO wareboxes_app;
GRANT SELECT, INSERT ON public.inventory_recall_case_holds TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.inventory_recall_cases_id_seq TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.inventory_recall_case_holds_id_seq TO wareboxes_app;
REVOKE ALL ON FUNCTION public.lock_inventory_recall_natural_key() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_inventory_recall_case() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_inventory_recall_case_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.reject_inventory_recall_case_hold_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_inventory_recall_consistency() FROM PUBLIC;

-- Versioned facility storage zones and immutable location membership.
CREATE TABLE public.storage_zones (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    purpose text NOT NULL,
    travel_sequence bigint NOT NULL,
    revision bigint NOT NULL,
    supersedes_storage_zone_id bigint,
    location_count bigint NOT NULL,
    effective_from timestamptz NOT NULL,
    effective_to timestamptz,
    configured_by_user_id bigint NOT NULL,
    configured_at timestamptz NOT NULL,
    retired_by_user_id bigint,
    CONSTRAINT storage_zones_scope_id_key UNIQUE (tenant_id, facility_id, id),
    CONSTRAINT storage_zones_revision_key UNIQUE (tenant_id, facility_id, code, revision),
    CONSTRAINT storage_zones_code_check CHECK (
        code = upper(btrim(code)) AND code <> '' AND char_length(code) <= 32
        AND code ~ '^[A-Z0-9_-]+$'
    ),
    CONSTRAINT storage_zones_name_check CHECK (
        name = btrim(name) AND name <> '' AND char_length(name) <= 120
    ),
    CONSTRAINT storage_zones_purpose_check CHECK (
        purpose IN ('receiving', 'reserve', 'pick', 'staging', 'packing', 'shipping', 'quarantine', 'damage')
    ),
    CONSTRAINT storage_zones_travel_sequence_check CHECK (travel_sequence >= 0),
    CONSTRAINT storage_zones_revision_check CHECK (
        revision > 0 AND (
            (revision = 1 AND supersedes_storage_zone_id IS NULL)
            OR (revision > 1 AND supersedes_storage_zone_id IS NOT NULL)
        )
    ),
    CONSTRAINT storage_zones_location_count_check CHECK (location_count > 0),
    CONSTRAINT storage_zones_effective_check CHECK (
        effective_from >= configured_at AND (
            (effective_to IS NULL AND retired_by_user_id IS NULL)
            OR (effective_to > effective_from AND retired_by_user_id IS NOT NULL)
        )
    ),
    CONSTRAINT storage_zones_facility_fkey FOREIGN KEY (tenant_id, facility_id)
        REFERENCES public.facilities (tenant_id, id),
    CONSTRAINT storage_zones_configured_by_fkey FOREIGN KEY (tenant_id, configured_by_user_id)
        REFERENCES public.tenant_memberships (tenant_id, user_id),
    CONSTRAINT storage_zones_retired_by_fkey FOREIGN KEY (tenant_id, retired_by_user_id)
        REFERENCES public.tenant_memberships (tenant_id, user_id),
    CONSTRAINT storage_zones_supersedes_fkey FOREIGN KEY (tenant_id, facility_id, supersedes_storage_zone_id)
        REFERENCES public.storage_zones (tenant_id, facility_id, id)
);

CREATE TABLE public.storage_zone_locations (
    tenant_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    storage_zone_id bigint NOT NULL,
    location_id bigint NOT NULL,
    location_sequence bigint NOT NULL,
    PRIMARY KEY (tenant_id, storage_zone_id, location_id),
    CONSTRAINT storage_zone_locations_sequence_key UNIQUE (tenant_id, storage_zone_id, location_sequence),
    CONSTRAINT storage_zone_locations_sequence_check CHECK (location_sequence > 0),
    CONSTRAINT storage_zone_locations_zone_fkey FOREIGN KEY (tenant_id, facility_id, storage_zone_id)
        REFERENCES public.storage_zones (tenant_id, facility_id, id),
    CONSTRAINT storage_zone_locations_location_fkey FOREIGN KEY (tenant_id, facility_id, location_id)
        REFERENCES public.locations (tenant_id, facility_id, id)
);

CREATE UNIQUE INDEX storage_zones_one_active_code_idx
ON public.storage_zones (tenant_id, facility_id, code)
WHERE effective_to IS NULL;
CREATE INDEX storage_zones_page_idx
ON public.storage_zones (tenant_id, travel_sequence, id);
CREATE INDEX storage_zones_facility_page_idx
ON public.storage_zones (tenant_id, facility_id, travel_sequence, id);
CREATE INDEX storage_zone_locations_location_idx
ON public.storage_zone_locations (tenant_id, facility_id, location_id, storage_zone_id);

CREATE FUNCTION public.validate_storage_zone() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    predecessor public.storage_zones%ROWTYPE;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(
        concat_ws(':', 'storage_zone', NEW.tenant_id, NEW.facility_id, NEW.code), 0
    ));

    IF NOT EXISTS (
        SELECT 1 FROM public.facilities facility
        WHERE facility.tenant_id = NEW.tenant_id
          AND facility.id = NEW.facility_id
          AND facility.deleted IS NULL
    ) OR NOT EXISTS (
        SELECT 1 FROM public.tenant_memberships membership
        WHERE membership.tenant_id = NEW.tenant_id
          AND membership.user_id = NEW.configured_by_user_id
          AND membership.deleted IS NULL
    ) THEN
        RAISE EXCEPTION 'storage zone requires an active facility and configuring membership'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.supersedes_storage_zone_id IS NULL THEN
        IF NEW.revision <> 1 THEN
            RAISE EXCEPTION 'initial storage zone revision must be one'
                USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    SELECT * INTO predecessor
    FROM public.storage_zones zone
    WHERE zone.tenant_id = NEW.tenant_id
      AND zone.facility_id = NEW.facility_id
      AND zone.id = NEW.supersedes_storage_zone_id;

    IF NOT FOUND
       OR predecessor.code <> NEW.code
       OR predecessor.revision + 1 <> NEW.revision
       OR predecessor.effective_to IS NULL
       OR predecessor.retired_by_user_id IS NULL
       OR NEW.effective_from < predecessor.effective_to
       OR EXISTS (
           SELECT 1 FROM public.storage_zones newer
           WHERE newer.tenant_id = NEW.tenant_id
             AND newer.facility_id = NEW.facility_id
             AND newer.code = NEW.code
             AND newer.revision > predecessor.revision
       )
    THEN
        RAISE EXCEPTION 'storage zone successor does not match its closed predecessor'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.guard_storage_zone_mutation() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'storage zones are immutable' USING ERRCODE = '23514';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(
        concat_ws(':', 'storage_zone', OLD.tenant_id, OLD.facility_id, OLD.code), 0
    ));
    IF NEW.id <> OLD.id
       OR NEW.tenant_id <> OLD.tenant_id
       OR NEW.facility_id <> OLD.facility_id
       OR NEW.code <> OLD.code
       OR NEW.name <> OLD.name
       OR NEW.purpose <> OLD.purpose
       OR NEW.travel_sequence <> OLD.travel_sequence
       OR NEW.revision <> OLD.revision
       OR NEW.supersedes_storage_zone_id IS DISTINCT FROM OLD.supersedes_storage_zone_id
       OR NEW.location_count <> OLD.location_count
       OR NEW.effective_from <> OLD.effective_from
       OR NEW.configured_by_user_id <> OLD.configured_by_user_id
       OR NEW.configured_at <> OLD.configured_at
       OR OLD.effective_to IS NOT NULL
       OR NEW.effective_to IS NULL
       OR NEW.retired_by_user_id IS NULL
       OR NEW.effective_to <= OLD.effective_from
    THEN
        RAISE EXCEPTION 'only active storage zone retirement is allowed'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.validate_storage_zone_location() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    zone_purpose text;
    location_pickable boolean;
    location_receivable boolean;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(
        concat_ws(':', 'storage_zone_location', NEW.tenant_id, NEW.facility_id, NEW.location_id), 0
    ));

    SELECT zone.purpose INTO zone_purpose
    FROM public.storage_zones zone
    WHERE zone.tenant_id = NEW.tenant_id
      AND zone.facility_id = NEW.facility_id
      AND zone.id = NEW.storage_zone_id
      AND zone.effective_to IS NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'storage zone location requires an active zone'
            USING ERRCODE = '23514';
    END IF;

    SELECT location.pickable, location.receivable
    INTO location_pickable, location_receivable
    FROM public.locations location
    WHERE location.tenant_id = NEW.tenant_id
      AND location.facility_id = NEW.facility_id
      AND location.id = NEW.location_id
      AND location.deleted IS NULL
      AND location.active
      AND NULLIF(btrim(location.barcode), '') IS NOT NULL
    FOR SHARE;
    IF NOT FOUND
       OR (zone_purpose = 'receiving' AND (NOT location_receivable OR location_pickable))
       OR (zone_purpose = 'pick' AND (NOT location_pickable OR location_receivable))
       OR (zone_purpose NOT IN ('receiving', 'pick') AND (location_pickable OR location_receivable))
    THEN
        RAISE EXCEPTION 'storage zone location flags are incompatible with zone purpose'
            USING ERRCODE = '23514';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.storage_zone_locations other_member
        JOIN public.storage_zones other_zone
          ON other_zone.tenant_id = other_member.tenant_id
         AND other_zone.facility_id = other_member.facility_id
         AND other_zone.id = other_member.storage_zone_id
         AND other_zone.effective_to IS NULL
        WHERE other_member.tenant_id = NEW.tenant_id
          AND other_member.facility_id = NEW.facility_id
          AND other_member.location_id = NEW.location_id
          AND other_member.storage_zone_id <> NEW.storage_zone_id
    ) THEN
        RAISE EXCEPTION 'location already belongs to an active storage zone'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.reject_storage_zone_location_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'storage zone location membership is immutable'
        USING ERRCODE = '23514';
END;
$$;

CREATE FUNCTION public.require_storage_zone_location_count() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    checked_tenant_id bigint;
    checked_zone_id bigint;
BEGIN
    IF TG_TABLE_NAME = 'storage_zones' THEN
        checked_tenant_id := NEW.tenant_id;
        checked_zone_id := NEW.id;
    ELSE
        checked_tenant_id := NEW.tenant_id;
        checked_zone_id := NEW.storage_zone_id;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.storage_zones zone
        WHERE zone.tenant_id = checked_tenant_id
          AND zone.id = checked_zone_id
          AND zone.location_count = (
              SELECT count(*) FROM public.storage_zone_locations member
              WHERE member.tenant_id = checked_tenant_id
                AND member.storage_zone_id = checked_zone_id
          )
          AND zone.location_count = (
              SELECT max(member.location_sequence)
              FROM public.storage_zone_locations member
              WHERE member.tenant_id = checked_tenant_id
                AND member.storage_zone_id = checked_zone_id
          )
    ) THEN
        RAISE EXCEPTION 'storage zone location set is inconsistent'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.require_active_storage_zone_location_eligibility() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM public.storage_zone_locations member
        JOIN public.storage_zones zone
          ON zone.tenant_id = member.tenant_id
         AND zone.facility_id = member.facility_id
         AND zone.id = member.storage_zone_id
         AND zone.effective_to IS NULL
        WHERE member.tenant_id = OLD.tenant_id
          AND member.facility_id = OLD.facility_id
          AND member.location_id = OLD.id
          AND (
              TG_OP = 'DELETE'
              OR NEW.deleted IS NOT NULL
              OR NOT NEW.active
              OR NULLIF(btrim(NEW.barcode), '') IS NULL
              OR (zone.purpose = 'receiving' AND (NOT NEW.receivable OR NEW.pickable))
              OR (zone.purpose = 'pick' AND (NOT NEW.pickable OR NEW.receivable))
              OR (zone.purpose NOT IN ('receiving', 'pick') AND (NEW.pickable OR NEW.receivable))
          )
    ) THEN
        RAISE EXCEPTION 'location is assigned to an active storage zone'
            USING ERRCODE = '55000';
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;

CREATE TRIGGER storage_zones_validate
BEFORE INSERT ON public.storage_zones
FOR EACH ROW EXECUTE FUNCTION public.validate_storage_zone();
CREATE TRIGGER storage_zones_guard
BEFORE UPDATE OR DELETE ON public.storage_zones
FOR EACH ROW EXECUTE FUNCTION public.guard_storage_zone_mutation();
CREATE TRIGGER storage_zone_locations_validate
BEFORE INSERT ON public.storage_zone_locations
FOR EACH ROW EXECUTE FUNCTION public.validate_storage_zone_location();
CREATE TRIGGER storage_zone_locations_immutable
BEFORE UPDATE OR DELETE ON public.storage_zone_locations
FOR EACH ROW EXECUTE FUNCTION public.reject_storage_zone_location_mutation();
CREATE CONSTRAINT TRIGGER storage_zones_location_count_consistent
AFTER INSERT OR UPDATE ON public.storage_zones DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_storage_zone_location_count();
CREATE CONSTRAINT TRIGGER storage_zone_locations_count_consistent
AFTER INSERT ON public.storage_zone_locations DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_storage_zone_location_count();
CREATE CONSTRAINT TRIGGER locations_active_storage_zone_eligible
AFTER UPDATE OR DELETE ON public.locations DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_active_storage_zone_location_eligibility();

ALTER TABLE public.storage_zones ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.storage_zones FORCE ROW LEVEL SECURITY;
CREATE POLICY storage_zones_tenant_isolation ON public.storage_zones
USING (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint)
WITH CHECK (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint);
ALTER TABLE public.storage_zone_locations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.storage_zone_locations FORCE ROW LEVEL SECURITY;
CREATE POLICY storage_zone_locations_tenant_isolation ON public.storage_zone_locations
USING (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint)
WITH CHECK (tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint);

GRANT SELECT, INSERT ON public.storage_zones TO wareboxes_app;
GRANT UPDATE (effective_to, retired_by_user_id) ON public.storage_zones TO wareboxes_app;
GRANT SELECT, INSERT ON public.storage_zone_locations TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.storage_zones_id_seq TO wareboxes_app;
REVOKE ALL ON FUNCTION public.validate_storage_zone() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_storage_zone_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_storage_zone_location() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.reject_storage_zone_location_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_storage_zone_location_count() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_active_storage_zone_location_eligibility() FROM PUBLIC;

-- Versioned owner/facility/item storage compatibility and per-location capacity.
-- Policies apply only to locations in an active storage zone. Transient unzoned
-- execution locations remain governed by their workflow-specific invariants.
CREATE TABLE public.item_storage_policies (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    item_id bigint NOT NULL,
    uom text NOT NULL,
    max_quantity_per_location bigint,
    revision bigint NOT NULL,
    supersedes_item_storage_policy_id bigint,
    allowed_purpose_count bigint NOT NULL,
    effective_from timestamptz NOT NULL,
    effective_to timestamptz,
    configured_by_user_id bigint NOT NULL,
    configured_at timestamptz NOT NULL,
    retired_by_user_id bigint,
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, inventory_owner_id, facility_id, id),
    UNIQUE (tenant_id, inventory_owner_id, facility_id, item_id, uom, revision),
    CHECK (uom = btrim(uom) AND uom <> '' AND char_length(uom) <= 32),
    CHECK (max_quantity_per_location IS NULL OR max_quantity_per_location > 0),
    CHECK (revision > 0 AND allowed_purpose_count > 0),
    CHECK (configured_at = effective_from),
    CHECK ((effective_to IS NULL AND retired_by_user_id IS NULL)
           OR (effective_to > effective_from AND retired_by_user_id IS NOT NULL)),
    FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    FOREIGN KEY (tenant_id, inventory_owner_id)
        REFERENCES public.inventory_owners(tenant_id, id),
    FOREIGN KEY (tenant_id, facility_id)
        REFERENCES public.facilities(tenant_id, id),
    FOREIGN KEY (tenant_id, inventory_owner_id, facility_id)
        REFERENCES public.inventory_owner_facilities(tenant_id, inventory_owner_id, facility_id),
    FOREIGN KEY (tenant_id, inventory_owner_id, item_id)
        REFERENCES public.inventory_owner_items(tenant_id, inventory_owner_id, item_id),
    FOREIGN KEY (tenant_id, configured_by_user_id)
        REFERENCES public.tenant_memberships(tenant_id, user_id),
    FOREIGN KEY (tenant_id, retired_by_user_id)
        REFERENCES public.tenant_memberships(tenant_id, user_id),
    FOREIGN KEY (tenant_id, inventory_owner_id, facility_id,
                 supersedes_item_storage_policy_id)
        REFERENCES public.item_storage_policies(
            tenant_id, inventory_owner_id, facility_id, id)
);

CREATE TABLE public.item_storage_policy_zone_purposes (
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    item_storage_policy_id bigint NOT NULL,
    purpose text NOT NULL,
    purpose_sequence bigint NOT NULL,
    PRIMARY KEY (tenant_id, item_storage_policy_id, purpose),
    UNIQUE (tenant_id, item_storage_policy_id, purpose_sequence),
    CHECK (purpose IN (
        'receiving','reserve','pick','staging','packing','shipping','quarantine','damage')),
    CHECK (purpose_sequence > 0),
    FOREIGN KEY (tenant_id, inventory_owner_id, facility_id, item_storage_policy_id)
        REFERENCES public.item_storage_policies(
            tenant_id, inventory_owner_id, facility_id, id)
);

CREATE UNIQUE INDEX item_storage_policies_one_active_natural_key
ON public.item_storage_policies(
    tenant_id, inventory_owner_id, facility_id, item_id, uom)
WHERE effective_to IS NULL;
CREATE INDEX item_storage_policies_history_idx
ON public.item_storage_policies(
    tenant_id, inventory_owner_id, facility_id, item_id, uom, revision DESC);
CREATE INDEX item_storage_policy_purpose_lookup_idx
ON public.item_storage_policy_zone_purposes(
    tenant_id, inventory_owner_id, facility_id, purpose, item_storage_policy_id);

CREATE FUNCTION public.validate_item_storage_policy() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    predecessor public.item_storage_policies%ROWTYPE;
    item_uom text;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(':',
        'item_storage_policy', NEW.tenant_id, NEW.inventory_owner_id,
        NEW.facility_id, NEW.item_id, NEW.uom), 0));

    SELECT item.packaging_unit INTO item_uom
    FROM public.inventory_owner_items owner_item
    JOIN public.items item
      ON item.tenant_id = owner_item.tenant_id AND item.id = owner_item.item_id
    JOIN public.inventory_owner_facilities assignment
      ON assignment.tenant_id = owner_item.tenant_id
     AND assignment.inventory_owner_id = owner_item.inventory_owner_id
     AND assignment.facility_id = NEW.facility_id
     AND assignment.deleted IS NULL
    WHERE owner_item.tenant_id = NEW.tenant_id
      AND owner_item.inventory_owner_id = NEW.inventory_owner_id
      AND owner_item.item_id = NEW.item_id
      AND owner_item.deleted IS NULL AND item.deleted IS NULL
    FOR SHARE OF owner_item, item, assignment;
    IF item_uom IS DISTINCT FROM NEW.uom THEN
        RAISE EXCEPTION 'item storage policy owner, facility, item, or UOM is unavailable'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.supersedes_item_storage_policy_id IS NULL THEN
        IF NEW.revision <> 1 OR EXISTS (
            SELECT 1 FROM public.item_storage_policies existing
            WHERE existing.tenant_id = NEW.tenant_id
              AND existing.inventory_owner_id = NEW.inventory_owner_id
              AND existing.facility_id = NEW.facility_id
              AND existing.item_id = NEW.item_id AND existing.uom = NEW.uom)
        THEN
            RAISE EXCEPTION 'initial item storage policy revision must be one'
                USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    SELECT * INTO predecessor FROM public.item_storage_policies
    WHERE tenant_id = NEW.tenant_id
      AND inventory_owner_id = NEW.inventory_owner_id
      AND facility_id = NEW.facility_id
      AND item_id = NEW.item_id AND uom = NEW.uom
      AND id = NEW.supersedes_item_storage_policy_id
    FOR SHARE;
    IF NOT FOUND
       OR predecessor.effective_to IS NULL
       OR NEW.revision <> predecessor.revision + 1
       OR NEW.effective_from < predecessor.effective_to
       OR EXISTS (
           SELECT 1 FROM public.item_storage_policies newer
           WHERE newer.tenant_id = NEW.tenant_id
             AND newer.inventory_owner_id = NEW.inventory_owner_id
             AND newer.facility_id = NEW.facility_id
             AND newer.item_id = NEW.item_id AND newer.uom = NEW.uom
             AND newer.revision > predecessor.revision)
    THEN
        RAISE EXCEPTION 'item storage policy successor does not match its closed predecessor'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.guard_item_storage_policy_mutation() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'item storage policies are immutable' USING ERRCODE = '23514';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(':',
        'item_storage_policy', OLD.tenant_id, OLD.inventory_owner_id,
        OLD.facility_id, OLD.item_id, OLD.uom), 0));
    IF NEW.id <> OLD.id
       OR NEW.tenant_id <> OLD.tenant_id
       OR NEW.inventory_owner_id <> OLD.inventory_owner_id
       OR NEW.facility_id <> OLD.facility_id
       OR NEW.item_id <> OLD.item_id OR NEW.uom <> OLD.uom
       OR NEW.max_quantity_per_location IS DISTINCT FROM OLD.max_quantity_per_location
       OR NEW.revision <> OLD.revision
       OR NEW.supersedes_item_storage_policy_id IS DISTINCT FROM OLD.supersedes_item_storage_policy_id
       OR NEW.allowed_purpose_count <> OLD.allowed_purpose_count
       OR NEW.effective_from <> OLD.effective_from
       OR NEW.configured_by_user_id <> OLD.configured_by_user_id
       OR NEW.configured_at <> OLD.configured_at
       OR OLD.effective_to IS NOT NULL
       OR NEW.effective_to IS NULL OR NEW.retired_by_user_id IS NULL
       OR NEW.effective_to <= OLD.effective_from
    THEN
        RAISE EXCEPTION 'only active item storage policy retirement is allowed'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.validate_item_storage_policy_purpose() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.item_storage_policies policy
        WHERE policy.tenant_id = NEW.tenant_id
          AND policy.inventory_owner_id = NEW.inventory_owner_id
          AND policy.facility_id = NEW.facility_id
          AND policy.id = NEW.item_storage_policy_id
          AND policy.effective_to IS NULL)
    THEN
        RAISE EXCEPTION 'item storage policy purpose requires an active policy'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.reject_item_storage_policy_purpose_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'item storage policy purposes are immutable'
        USING ERRCODE = '23514';
END;
$$;

CREATE FUNCTION public.require_item_storage_policy_consistency() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    checked_tenant_id bigint;
    checked_policy_id bigint;
    policy public.item_storage_policies%ROWTYPE;
BEGIN
    IF TG_TABLE_NAME = 'item_storage_policies' THEN
        checked_tenant_id := NEW.tenant_id;
        checked_policy_id := NEW.id;
    ELSE
        checked_tenant_id := NEW.tenant_id;
        checked_policy_id := NEW.item_storage_policy_id;
    END IF;
    SELECT * INTO policy FROM public.item_storage_policies
    WHERE tenant_id = checked_tenant_id AND id = checked_policy_id;

    IF NOT FOUND
       OR policy.allowed_purpose_count <> (
           SELECT count(*) FROM public.item_storage_policy_zone_purposes purpose
           WHERE purpose.tenant_id = policy.tenant_id
             AND purpose.item_storage_policy_id = policy.id)
       OR policy.allowed_purpose_count <> (
           SELECT max(purpose.purpose_sequence)
           FROM public.item_storage_policy_zone_purposes purpose
           WHERE purpose.tenant_id = policy.tenant_id
             AND purpose.item_storage_policy_id = policy.id)
       OR (policy.effective_to IS NULL AND EXISTS (
           SELECT 1
           FROM public.inventory_balances balance
           JOIN public.storage_zone_locations member
             ON member.tenant_id = balance.tenant_id
            AND member.facility_id = balance.facility_id
            AND member.location_id = balance.location_id
           JOIN public.storage_zones zone
             ON zone.tenant_id = member.tenant_id
            AND zone.facility_id = member.facility_id
            AND zone.id = member.storage_zone_id
            AND zone.effective_to IS NULL
           WHERE balance.tenant_id = policy.tenant_id
             AND balance.inventory_owner_id = policy.inventory_owner_id
             AND balance.facility_id = policy.facility_id
             AND balance.item_id = policy.item_id AND balance.uom = policy.uom
             AND balance.deleted IS NULL AND balance.qty_on_hand > 0
             AND NOT EXISTS (
                 SELECT 1 FROM public.item_storage_policy_zone_purposes allowed
                 WHERE allowed.tenant_id = policy.tenant_id
                   AND allowed.item_storage_policy_id = policy.id
                   AND allowed.purpose = zone.purpose)))
       OR (policy.effective_to IS NULL
           AND policy.max_quantity_per_location IS NOT NULL AND EXISTS (
           SELECT 1
           FROM public.inventory_balances balance
           JOIN public.storage_zone_locations member
             ON member.tenant_id = balance.tenant_id
            AND member.facility_id = balance.facility_id
            AND member.location_id = balance.location_id
           JOIN public.storage_zones zone
             ON zone.tenant_id = member.tenant_id
            AND zone.facility_id = member.facility_id
            AND zone.id = member.storage_zone_id
            AND zone.effective_to IS NULL
           WHERE balance.tenant_id = policy.tenant_id
             AND balance.inventory_owner_id = policy.inventory_owner_id
             AND balance.facility_id = policy.facility_id
             AND balance.item_id = policy.item_id AND balance.uom = policy.uom
             AND balance.deleted IS NULL
           GROUP BY balance.location_id
           HAVING sum(balance.qty_on_hand) > policy.max_quantity_per_location))
    THEN
        RAISE EXCEPTION 'item storage policy purposes, current positions, or capacity are inconsistent'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION public.enforce_item_storage_policy_for_balance() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    policy_id bigint;
    capacity bigint;
    zone_purpose text;
    resulting_on_hand bigint;
BEGIN
    IF NEW.deleted IS NOT NULL OR NEW.qty_on_hand <= 0 THEN
        RETURN NEW;
    END IF;

    SELECT policy.id, policy.max_quantity_per_location, zone.purpose
      INTO policy_id, capacity, zone_purpose
    FROM public.item_storage_policies policy
    JOIN public.storage_zone_locations member
      ON member.tenant_id = policy.tenant_id
     AND member.facility_id = policy.facility_id
     AND member.location_id = NEW.location_id
    JOIN public.storage_zones zone
      ON zone.tenant_id = member.tenant_id
     AND zone.facility_id = member.facility_id
     AND zone.id = member.storage_zone_id
     AND zone.effective_to IS NULL
    WHERE policy.tenant_id = NEW.tenant_id
      AND policy.inventory_owner_id = NEW.inventory_owner_id
      AND policy.facility_id = NEW.facility_id
      AND policy.item_id = NEW.item_id AND policy.uom = NEW.uom
      AND policy.effective_to IS NULL;
    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.item_storage_policy_zone_purposes allowed
        WHERE allowed.tenant_id = NEW.tenant_id
          AND allowed.item_storage_policy_id = policy_id
          AND allowed.purpose = zone_purpose)
    THEN
        RAISE EXCEPTION 'item is not compatible with the destination storage zone'
            USING ERRCODE = '55000';
    END IF;

    IF capacity IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(hashtextextended(
            'inventory-location-item:' || NEW.tenant_id::text || ':'
            || NEW.inventory_owner_id::text || ':' || NEW.location_id::text
            || ':' || NEW.item_id::text, 0));
        SELECT COALESCE(sum(balance.qty_on_hand), 0) + NEW.qty_on_hand
          INTO resulting_on_hand
        FROM public.inventory_balances balance
        WHERE balance.tenant_id = NEW.tenant_id
          AND balance.inventory_owner_id = NEW.inventory_owner_id
          AND balance.facility_id = NEW.facility_id
          AND balance.location_id = NEW.location_id
          AND balance.item_id = NEW.item_id AND balance.uom = NEW.uom
          AND balance.id <> COALESCE(NEW.id, -1)
          AND balance.deleted IS NULL;
        IF resulting_on_hand > capacity THEN
            RAISE EXCEPTION 'item storage location capacity would be exceeded'
                USING ERRCODE = '55000';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.require_storage_zone_item_policy_compatibility() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    checked_tenant_id bigint;
    checked_zone_id bigint;
BEGIN
    IF TG_TABLE_NAME = 'storage_zones' THEN
        checked_tenant_id := NEW.tenant_id;
        checked_zone_id := NEW.id;
    ELSE
        checked_tenant_id := NEW.tenant_id;
        checked_zone_id := NEW.storage_zone_id;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM public.storage_zones zone
        JOIN public.storage_zone_locations member
          ON member.tenant_id = zone.tenant_id
         AND member.storage_zone_id = zone.id
        JOIN public.inventory_balances balance
          ON balance.tenant_id = member.tenant_id
         AND balance.facility_id = member.facility_id
         AND balance.location_id = member.location_id
         AND balance.deleted IS NULL AND balance.qty_on_hand > 0
        JOIN public.item_storage_policies policy
          ON policy.tenant_id = balance.tenant_id
         AND policy.inventory_owner_id = balance.inventory_owner_id
         AND policy.facility_id = balance.facility_id
         AND policy.item_id = balance.item_id AND policy.uom = balance.uom
         AND policy.effective_to IS NULL
        WHERE zone.tenant_id = checked_tenant_id AND zone.id = checked_zone_id
          AND zone.effective_to IS NULL
          AND NOT EXISTS (
              SELECT 1 FROM public.item_storage_policy_zone_purposes allowed
              WHERE allowed.tenant_id = policy.tenant_id
                AND allowed.item_storage_policy_id = policy.id
                AND allowed.purpose = zone.purpose))
       OR EXISTS (
        SELECT 1
        FROM public.storage_zones zone
        JOIN public.storage_zone_locations member
          ON member.tenant_id = zone.tenant_id
         AND member.storage_zone_id = zone.id
        JOIN public.inventory_balances balance
          ON balance.tenant_id = member.tenant_id
         AND balance.facility_id = member.facility_id
         AND balance.location_id = member.location_id
         AND balance.deleted IS NULL
        JOIN public.item_storage_policies policy
          ON policy.tenant_id = balance.tenant_id
         AND policy.inventory_owner_id = balance.inventory_owner_id
         AND policy.facility_id = balance.facility_id
         AND policy.item_id = balance.item_id AND policy.uom = balance.uom
         AND policy.effective_to IS NULL
         AND policy.max_quantity_per_location IS NOT NULL
        WHERE zone.tenant_id = checked_tenant_id AND zone.id = checked_zone_id
          AND zone.effective_to IS NULL
        GROUP BY policy.id, member.location_id, policy.max_quantity_per_location
        HAVING sum(balance.qty_on_hand) > policy.max_quantity_per_location)
    THEN
        RAISE EXCEPTION 'storage zone conflicts with an active item storage policy'
            USING ERRCODE = '55000';
    END IF;
    RETURN NULL;
END;
$$;

CREATE TRIGGER item_storage_policies_validate
BEFORE INSERT ON public.item_storage_policies
FOR EACH ROW EXECUTE FUNCTION public.validate_item_storage_policy();
CREATE TRIGGER item_storage_policies_guard
BEFORE UPDATE OR DELETE ON public.item_storage_policies
FOR EACH ROW EXECUTE FUNCTION public.guard_item_storage_policy_mutation();
CREATE TRIGGER item_storage_policy_purposes_validate
BEFORE INSERT ON public.item_storage_policy_zone_purposes
FOR EACH ROW EXECUTE FUNCTION public.validate_item_storage_policy_purpose();
CREATE TRIGGER item_storage_policy_purposes_immutable
BEFORE UPDATE OR DELETE ON public.item_storage_policy_zone_purposes
FOR EACH ROW EXECUTE FUNCTION public.reject_item_storage_policy_purpose_mutation();
CREATE CONSTRAINT TRIGGER item_storage_policies_consistent
AFTER INSERT OR UPDATE ON public.item_storage_policies DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_item_storage_policy_consistency();
CREATE CONSTRAINT TRIGGER item_storage_policy_purposes_consistent
AFTER INSERT ON public.item_storage_policy_zone_purposes DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_item_storage_policy_consistency();
CREATE TRIGGER inventory_balances_enforce_item_storage_policy
BEFORE INSERT OR UPDATE OF tenant_id, inventory_owner_id, facility_id, location_id,
    item_id, uom, qty_on_hand, deleted ON public.inventory_balances
FOR EACH ROW EXECUTE FUNCTION public.enforce_item_storage_policy_for_balance();
CREATE CONSTRAINT TRIGGER storage_zones_item_policy_compatible
AFTER INSERT OR UPDATE ON public.storage_zones DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_storage_zone_item_policy_compatibility();
CREATE CONSTRAINT TRIGGER storage_zone_locations_item_policy_compatible
AFTER INSERT ON public.storage_zone_locations DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_storage_zone_item_policy_compatibility();

