ON public.integration_order_item_mappings
    (tenant_id,inventory_owner_id,source_key,external_item_key,external_uom,revision DESC);

CREATE FUNCTION public.guard_integration_order_item_mapping() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    predecessor public.integration_order_item_mappings%ROWTYPE;
    catalog_uom text;
BEGIN
    IF TG_OP='DELETE' THEN
        RAISE EXCEPTION 'integration order item mapping evidence is immutable'
            USING ERRCODE='55000';
    END IF;
    IF TG_OP='UPDATE' THEN
        IF NEW.tenant_id<>OLD.tenant_id
           OR NEW.inventory_owner_id<>OLD.inventory_owner_id
           OR NEW.source_key<>OLD.source_key
           OR NEW.external_item_key<>OLD.external_item_key
           OR NEW.external_uom<>OLD.external_uom
           OR NEW.item_id<>OLD.item_id
           OR NEW.requested_uom<>OLD.requested_uom
           OR NEW.revision<>OLD.revision
           OR NEW.supersedes_mapping_id IS DISTINCT FROM OLD.supersedes_mapping_id
           OR NEW.effective_from<>OLD.effective_from
           OR NEW.configured_by_user_id<>OLD.configured_by_user_id
           OR NEW.configured_at<>OLD.configured_at
           OR OLD.effective_to IS NOT NULL
           OR NEW.effective_to IS NULL
           OR NEW.effective_to<=OLD.effective_from
           OR NEW.retired_by_user_id IS NULL
        THEN
            RAISE EXCEPTION 'integration order item mapping mutation is invalid'
                USING ERRCODE='55000';
        END IF;
        RETURN NEW;
    END IF;

    PERFORM pg_advisory_xact_lock(hashtextextended(
        'integration-order-item-mapping:' || NEW.tenant_id::text || ':' ||
        NEW.inventory_owner_id::text || ':' || octet_length(NEW.source_key)::text || ':' ||
        NEW.source_key || ':' || octet_length(NEW.external_item_key)::text || ':' ||
        NEW.external_item_key || ':' || octet_length(NEW.external_uom)::text || ':' ||
        NEW.external_uom, 0));
    SELECT item.packaging_unit INTO catalog_uom
    FROM public.inventory_owner_items owner_item
    JOIN public.items item ON item.tenant_id=owner_item.tenant_id
                          AND item.id=owner_item.item_id
    WHERE owner_item.tenant_id=NEW.tenant_id
      AND owner_item.inventory_owner_id=NEW.inventory_owner_id
      AND owner_item.item_id=NEW.item_id
      AND owner_item.deleted IS NULL AND item.deleted IS NULL;
    IF NOT FOUND OR catalog_uom<>NEW.requested_uom THEN
        RAISE EXCEPTION 'integration order item mapping target is not an active owner item and UOM'
            USING ERRCODE='55000';
    END IF;

    IF NEW.supersedes_mapping_id IS NULL THEN
        IF NEW.revision<>1 OR EXISTS (
            SELECT 1 FROM public.integration_order_item_mappings existing
            WHERE existing.tenant_id=NEW.tenant_id
              AND existing.inventory_owner_id=NEW.inventory_owner_id
              AND existing.source_key=NEW.source_key
              AND existing.external_item_key=NEW.external_item_key
              AND existing.external_uom=NEW.external_uom)
        THEN
            RAISE EXCEPTION 'initial integration order item mapping revision is invalid'
                USING ERRCODE='55000';
        END IF;
    ELSE
        SELECT * INTO predecessor FROM public.integration_order_item_mappings
        WHERE tenant_id=NEW.tenant_id
          AND inventory_owner_id=NEW.inventory_owner_id
          AND id=NEW.supersedes_mapping_id
        FOR UPDATE;
        IF NOT FOUND
           OR predecessor.source_key<>NEW.source_key
           OR predecessor.external_item_key<>NEW.external_item_key
           OR predecessor.external_uom<>NEW.external_uom
           OR NEW.revision<>predecessor.revision+1
           OR predecessor.effective_to IS NULL
           OR predecessor.effective_to>NEW.effective_from
        THEN
            RAISE EXCEPTION 'integration order item mapping predecessor is invalid'
                USING ERRCODE='55000';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER integration_order_item_mappings_guard
BEFORE INSERT OR UPDATE OR DELETE ON public.integration_order_item_mappings
FOR EACH ROW EXECUTE FUNCTION public.guard_integration_order_item_mapping();

ALTER TABLE public.integration_order_item_mappings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.integration_order_item_mappings FORCE ROW LEVEL SECURITY;
CREATE POLICY integration_order_item_mappings_tenant_isolation
ON public.integration_order_item_mappings
USING (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint)
WITH CHECK (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint);

GRANT SELECT,INSERT,UPDATE(effective_to,retired_by_user_id)
ON public.integration_order_item_mappings TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.integration_order_item_mappings_id_seq TO wareboxes_app;
REVOKE ALL ON FUNCTION public.guard_integration_order_item_mapping() FROM PUBLIC;

-- Durable execution state and append-only attempt history for standard inbound
-- order processing. Raw inbox receipts remain the immutable source envelope.
CREATE TABLE public.integration_inbox_processings (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    receipt_id bigint NOT NULL,
    source_key text NOT NULL,
    deduplication_key text NOT NULL,
    payload_sha256 bytea NOT NULL,
    last_input_payload_sha256 bytea NOT NULL,
    last_correction_id bigint,
    adapter_key text NOT NULL,
    mapping_version integer NOT NULL,
    status text NOT NULL,
    revision bigint NOT NULL,
    attempt_count integer NOT NULL,
    order_id bigint,
    order_revision bigint,
    error_code text,
    error_message text,
    last_attempted_by_user_id bigint NOT NULL,
    last_attempted_at timestamp with time zone NOT NULL,
    processed_at timestamp with time zone,
    CONSTRAINT integration_inbox_processings_receipt_unique UNIQUE (tenant_id,receipt_id),
    CONSTRAINT integration_inbox_processings_scope_id_unique
        UNIQUE (tenant_id,inventory_owner_id,id),
    CONSTRAINT integration_inbox_processings_source_check
        CHECK (source_key=btrim(source_key) AND source_key<>'' AND char_length(source_key)<=200),
    CONSTRAINT integration_inbox_processings_deduplication_check
        CHECK (deduplication_key=btrim(deduplication_key) AND deduplication_key<>''
            AND char_length(deduplication_key)<=500),
    CONSTRAINT integration_inbox_processings_payload_hash_check
        CHECK (octet_length(payload_sha256)=32),
    CONSTRAINT integration_inbox_processings_input_payload_hash_check
        CHECK (octet_length(last_input_payload_sha256)=32),
    CONSTRAINT integration_inbox_processings_adapter_check
        CHECK (adapter_key=btrim(adapter_key) AND adapter_key<>'' AND char_length(adapter_key)<=200),
    CONSTRAINT integration_inbox_processings_mapping_version_check CHECK (mapping_version>0),
    CONSTRAINT integration_inbox_processings_status_check
        CHECK (status IN ('quarantined','processed')),
    CONSTRAINT integration_inbox_processings_revision_check CHECK (revision>0),
    CONSTRAINT integration_inbox_processings_attempt_count_check CHECK (attempt_count>0),
    CONSTRAINT integration_inbox_processings_error_code_check CHECK (
        error_code IS NULL OR
        (error_code=btrim(error_code) AND error_code<>'' AND char_length(error_code)<=100)),
    CONSTRAINT integration_inbox_processings_error_message_check CHECK (
        error_message IS NULL OR
        (error_message=btrim(error_message) AND error_message<>''
            AND char_length(error_message)<=1000 AND error_message!~'[[:cntrl:]]')),
    CONSTRAINT integration_inbox_processings_result_shape_check CHECK (
        (status='processed' AND order_id IS NOT NULL AND order_revision IS NOT NULL
            AND error_code IS NULL AND error_message IS NULL AND processed_at IS NOT NULL)
        OR
        (status='quarantined' AND order_id IS NULL AND order_revision IS NULL
            AND error_code IS NOT NULL AND error_message IS NOT NULL AND processed_at IS NULL)),
    CONSTRAINT integration_inbox_processings_receipt_fkey
        FOREIGN KEY (tenant_id,receipt_id)
        REFERENCES public.integration_inbox_receipts(tenant_id,id),
    CONSTRAINT integration_inbox_processings_owner_fkey
        FOREIGN KEY (tenant_id,inventory_owner_id)
        REFERENCES public.inventory_owners(tenant_id,id),
    CONSTRAINT integration_inbox_processings_order_fkey
        FOREIGN KEY (tenant_id,inventory_owner_id,order_id)
        REFERENCES public.orders(tenant_id,inventory_owner_id,id),
    CONSTRAINT integration_inbox_processings_actor_fkey
        FOREIGN KEY (tenant_id,last_attempted_by_user_id)
        REFERENCES public.tenant_memberships(tenant_id,user_id)
);

CREATE TABLE public.integration_inbox_processing_attempts (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    processing_id bigint NOT NULL,
    receipt_id bigint NOT NULL,
    attempt_number integer NOT NULL,
    previous_revision bigint,
    resulting_revision bigint NOT NULL,
    input_payload_sha256 bytea NOT NULL,
    correction_id bigint,
    outcome text NOT NULL,
    order_id bigint,
    order_revision bigint,
    error_code text,
    error_message text,
    attempted_by_user_id bigint NOT NULL,
    attempted_at timestamp with time zone NOT NULL,
    applied_mapping_count integer NOT NULL,
    CONSTRAINT integration_inbox_processing_attempts_sequence_unique
        UNIQUE (tenant_id,processing_id,attempt_number),
    CONSTRAINT integration_inbox_processing_attempts_revision_unique
        UNIQUE (tenant_id,processing_id,resulting_revision),
    CONSTRAINT integration_inbox_processing_attempts_scope_id_unique
        UNIQUE (tenant_id,inventory_owner_id,id),
    CONSTRAINT integration_inbox_processing_attempts_number_check CHECK (attempt_number>0),
    CONSTRAINT integration_inbox_processing_attempts_mapping_count_check
        CHECK (applied_mapping_count>=0),
    CONSTRAINT integration_inbox_processing_attempts_revision_check CHECK (
        resulting_revision>0 AND
        ((previous_revision IS NULL AND resulting_revision=1 AND attempt_number=1)
         OR (previous_revision IS NOT NULL AND previous_revision>0
             AND resulting_revision=previous_revision+1))),
    CONSTRAINT integration_inbox_processing_attempts_outcome_check
        CHECK (outcome IN ('quarantined','processed')),
    CONSTRAINT integration_inbox_processing_attempts_payload_hash_check
        CHECK (octet_length(input_payload_sha256)=32),
    CONSTRAINT integration_inbox_processing_attempts_error_code_check CHECK (
        error_code IS NULL OR
        (error_code=btrim(error_code) AND error_code<>'' AND char_length(error_code)<=100)),
    CONSTRAINT integration_inbox_processing_attempts_error_message_check CHECK (
        error_message IS NULL OR
        (error_message=btrim(error_message) AND error_message<>''
            AND char_length(error_message)<=1000 AND error_message!~'[[:cntrl:]]')),
    CONSTRAINT integration_inbox_processing_attempts_result_shape_check CHECK (
        (outcome='processed' AND order_id IS NOT NULL AND order_revision IS NOT NULL
            AND error_code IS NULL AND error_message IS NULL)
        OR
        (outcome='quarantined' AND order_id IS NULL AND order_revision IS NULL
            AND error_code IS NOT NULL AND error_message IS NOT NULL)),
    CONSTRAINT integration_inbox_processing_attempts_processing_fkey
        FOREIGN KEY (tenant_id,inventory_owner_id,processing_id)
        REFERENCES public.integration_inbox_processings(tenant_id,inventory_owner_id,id),
    CONSTRAINT integration_inbox_processing_attempts_receipt_fkey
        FOREIGN KEY (tenant_id,receipt_id)
        REFERENCES public.integration_inbox_receipts(tenant_id,id),
    CONSTRAINT integration_inbox_processing_attempts_order_fkey
        FOREIGN KEY (tenant_id,inventory_owner_id,order_id)
        REFERENCES public.orders(tenant_id,inventory_owner_id,id),
    CONSTRAINT integration_inbox_processing_attempts_actor_fkey
        FOREIGN KEY (tenant_id,attempted_by_user_id)
        REFERENCES public.tenant_memberships(tenant_id,user_id)
);

CREATE TABLE public.integration_inbox_processing_attempt_mappings (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    processing_id bigint NOT NULL,
    processing_attempt_id bigint NOT NULL,
    receipt_id bigint NOT NULL,
    attempt_number integer NOT NULL,
    line_key text NOT NULL,
    mapping_id bigint NOT NULL,
    mapping_revision bigint NOT NULL,
    source_key text NOT NULL,
    external_item_key text NOT NULL,
    external_uom text NOT NULL,
    item_id bigint NOT NULL,
    requested_uom text NOT NULL,
    CONSTRAINT integration_inbox_attempt_mappings_scope_id_unique
        UNIQUE (tenant_id,inventory_owner_id,id),
    CONSTRAINT integration_inbox_attempt_mappings_line_unique
        UNIQUE (tenant_id,processing_attempt_id,line_key),
    CONSTRAINT integration_inbox_attempt_mappings_line_check CHECK (
        line_key=btrim(line_key) AND line_key<>'' AND char_length(line_key)<=200
        AND line_key!~'[[:cntrl:]]'),
    CONSTRAINT integration_inbox_attempt_mappings_revision_check CHECK (mapping_revision>0),
    CONSTRAINT integration_inbox_attempt_mappings_identity_check CHECK (
        source_key=btrim(source_key) AND source_key<>'' AND char_length(source_key)<=200
        AND source_key!~'[[:cntrl:]]'
        AND external_item_key=btrim(external_item_key) AND external_item_key<>''
        AND char_length(external_item_key)<=200 AND external_item_key!~'[[:cntrl:]]'
        AND external_uom=btrim(external_uom) AND external_uom<>''
        AND char_length(external_uom)<=32 AND external_uom!~'[[:cntrl:]]'
        AND requested_uom=btrim(requested_uom) AND requested_uom<>''
        AND char_length(requested_uom)<=32 AND requested_uom!~'[[:cntrl:]]'),
    CONSTRAINT integration_inbox_attempt_mappings_attempt_fkey
        FOREIGN KEY (tenant_id,inventory_owner_id,processing_attempt_id)
        REFERENCES public.integration_inbox_processing_attempts(tenant_id,inventory_owner_id,id),
    CONSTRAINT integration_inbox_attempt_mappings_processing_fkey
        FOREIGN KEY (tenant_id,inventory_owner_id,processing_id)
        REFERENCES public.integration_inbox_processings(tenant_id,inventory_owner_id,id),
    CONSTRAINT integration_inbox_attempt_mappings_receipt_fkey
        FOREIGN KEY (tenant_id,receipt_id)
        REFERENCES public.integration_inbox_receipts(tenant_id,id),
    CONSTRAINT integration_inbox_attempt_mappings_mapping_fkey
        FOREIGN KEY (tenant_id,inventory_owner_id,mapping_id)
        REFERENCES public.integration_order_item_mappings(tenant_id,inventory_owner_id,id),
    CONSTRAINT integration_inbox_attempt_mappings_owner_item_fkey
        FOREIGN KEY (tenant_id,inventory_owner_id,item_id)
        REFERENCES public.inventory_owner_items(tenant_id,inventory_owner_id,item_id)
);

CREATE TABLE public.integration_inbox_processing_corrections (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    processing_id bigint NOT NULL,
    receipt_id bigint NOT NULL,
    expected_revision bigint NOT NULL,
    resulting_revision bigint NOT NULL,
    corrected_payload bytea NOT NULL,
    payload_sha256 bytea NOT NULL,
    reason text NOT NULL,
    corrected_by_user_id bigint NOT NULL,
    corrected_at timestamp with time zone NOT NULL,
    CONSTRAINT integration_inbox_processing_corrections_scope_id_unique
        UNIQUE (tenant_id,inventory_owner_id,id),
    CONSTRAINT integration_inbox_processing_corrections_revision_unique
        UNIQUE (tenant_id,processing_id,resulting_revision),
    CONSTRAINT integration_inbox_processing_corrections_revision_check
        CHECK (expected_revision>0 AND resulting_revision=expected_revision+1),
    CONSTRAINT integration_inbox_processing_corrections_payload_check
        CHECK (octet_length(corrected_payload)>0 AND octet_length(payload_sha256)=32
            AND sha256(corrected_payload)=payload_sha256
            AND convert_from(corrected_payload,'UTF8')::jsonb IS NOT NULL),
    CONSTRAINT integration_inbox_processing_corrections_reason_check
        CHECK (reason=btrim(reason) AND reason<>'' AND char_length(reason)<=500
            AND reason!~'[[:cntrl:]]'),
    CONSTRAINT integration_inbox_processing_corrections_processing_fkey
        FOREIGN KEY (tenant_id,inventory_owner_id,processing_id)
        REFERENCES public.integration_inbox_processings(tenant_id,inventory_owner_id,id),
    CONSTRAINT integration_inbox_processing_corrections_receipt_fkey
        FOREIGN KEY (tenant_id,receipt_id)
        REFERENCES public.integration_inbox_receipts(tenant_id,id),
    CONSTRAINT integration_inbox_processing_corrections_actor_fkey
        FOREIGN KEY (tenant_id,corrected_by_user_id)
        REFERENCES public.tenant_memberships(tenant_id,user_id)
);

ALTER TABLE public.integration_inbox_processings
ADD CONSTRAINT integration_inbox_processings_last_correction_fkey
FOREIGN KEY (tenant_id,inventory_owner_id,last_correction_id)
REFERENCES public.integration_inbox_processing_corrections(tenant_id,inventory_owner_id,id)
DEFERRABLE INITIALLY DEFERRED;

ALTER TABLE public.integration_inbox_processing_attempts
ADD CONSTRAINT integration_inbox_processing_attempts_correction_fkey
FOREIGN KEY (tenant_id,inventory_owner_id,correction_id)
REFERENCES public.integration_inbox_processing_corrections(tenant_id,inventory_owner_id,id);

CREATE INDEX integration_inbox_processings_operational_idx
ON public.integration_inbox_processings
    (tenant_id,status,last_attempted_at DESC,id DESC);

CREATE FUNCTION public.guard_integration_inbox_processing_mutation() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    receipt public.integration_inbox_receipts%ROWTYPE;
BEGIN
    IF TG_OP='DELETE' THEN
        RAISE EXCEPTION 'integration inbox processing state cannot be deleted'
            USING ERRCODE='55000';
    END IF;

    SELECT * INTO receipt FROM public.integration_inbox_receipts
    WHERE tenant_id=NEW.tenant_id AND id=NEW.receipt_id
    FOR SHARE;
    IF NOT FOUND OR receipt.inventory_owner_id IS DISTINCT FROM NEW.inventory_owner_id
       OR receipt.facility_id IS NOT NULL OR receipt.source_key<>NEW.source_key
       OR receipt.deduplication_key<>NEW.deduplication_key
       OR receipt.payload_sha256<>NEW.payload_sha256
    THEN
        RAISE EXCEPTION 'integration inbox processing does not match its immutable receipt'
            USING ERRCODE='23514';
    END IF;

    IF TG_OP='INSERT' THEN
        IF NEW.revision<>1 OR NEW.attempt_count<>1
           OR NEW.last_input_payload_sha256<>NEW.payload_sha256
           OR NEW.last_correction_id IS NOT NULL
        THEN
            RAISE EXCEPTION 'initial integration inbox processing revision is invalid'
                USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.status='processed' THEN
        RAISE EXCEPTION 'processed integration inbox state is terminal'
            USING ERRCODE='55000';
    END IF;
    IF NEW.tenant_id<>OLD.tenant_id
       OR NEW.inventory_owner_id<>OLD.inventory_owner_id
       OR NEW.receipt_id<>OLD.receipt_id
       OR NEW.source_key<>OLD.source_key
       OR NEW.deduplication_key<>OLD.deduplication_key
       OR NEW.payload_sha256<>OLD.payload_sha256
       OR NEW.adapter_key<>OLD.adapter_key
       OR NEW.mapping_version<>OLD.mapping_version
       OR NEW.revision<>OLD.revision+1
       OR NEW.attempt_count<>OLD.attempt_count+1
    THEN
        RAISE EXCEPTION 'integration inbox processing transition is invalid'
            USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.validate_integration_inbox_processing_correction() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    processing public.integration_inbox_processings%ROWTYPE;
BEGIN
    SELECT * INTO processing FROM public.integration_inbox_processings
    WHERE tenant_id=NEW.tenant_id AND inventory_owner_id=NEW.inventory_owner_id
      AND id=NEW.processing_id AND receipt_id=NEW.receipt_id
    FOR UPDATE;
    IF NOT FOUND OR processing.status<>'quarantined'
       OR processing.revision<>NEW.expected_revision
       OR NEW.resulting_revision<>processing.revision+1
    THEN
        RAISE EXCEPTION 'integration inbox correction processing revision is stale'
            USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.reject_integration_inbox_processing_attempt_mutation() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    RAISE EXCEPTION 'integration inbox processing attempts are immutable'
        USING ERRCODE='55000';
END;
$$;

CREATE FUNCTION public.validate_integration_inbox_processing_attempt_mapping() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
DECLARE
    attempt public.integration_inbox_processing_attempts%ROWTYPE;
    processing public.integration_inbox_processings%ROWTYPE;
    mapping public.integration_order_item_mappings%ROWTYPE;
    receipt public.integration_inbox_receipts%ROWTYPE;
    payload jsonb;
    payload_text text;
    segments text[];
    element_separator text;
    segment_terminator text;
BEGIN
    SELECT * INTO attempt FROM public.integration_inbox_processing_attempts
    WHERE tenant_id=NEW.tenant_id AND inventory_owner_id=NEW.inventory_owner_id
      AND id=NEW.processing_attempt_id AND processing_id=NEW.processing_id
      AND receipt_id=NEW.receipt_id AND attempt_number=NEW.attempt_number
    FOR SHARE;
    SELECT * INTO processing FROM public.integration_inbox_processings
    WHERE tenant_id=NEW.tenant_id AND inventory_owner_id=NEW.inventory_owner_id
      AND id=NEW.processing_id AND receipt_id=NEW.receipt_id
    FOR SHARE;
    SELECT * INTO mapping FROM public.integration_order_item_mappings
    WHERE tenant_id=NEW.tenant_id AND inventory_owner_id=NEW.inventory_owner_id
      AND id=NEW.mapping_id
    FOR SHARE;
    SELECT * INTO receipt FROM public.integration_inbox_receipts
    WHERE tenant_id=NEW.tenant_id AND inventory_owner_id=NEW.inventory_owner_id
      AND id=NEW.receipt_id
    FOR SHARE;
    IF attempt.id IS NULL OR processing.id IS NULL OR mapping.id IS NULL OR receipt.id IS NULL
       OR attempt.correction_id IS NOT NULL
       OR receipt.source_key<>NEW.source_key
       OR mapping.revision<>NEW.mapping_revision
       OR mapping.source_key<>NEW.source_key
       OR mapping.external_item_key<>NEW.external_item_key
       OR mapping.external_uom<>NEW.external_uom
       OR mapping.item_id<>NEW.item_id
       OR mapping.requested_uom<>NEW.requested_uom
       OR mapping.effective_from>attempt.attempted_at
       OR (mapping.effective_to IS NOT NULL AND mapping.effective_to<=attempt.attempted_at)
    THEN
        RAISE EXCEPTION 'integration processing attempt mapping snapshot is invalid'
            USING ERRCODE='23514';
    END IF;
    IF processing.adapter_key='wareboxes.fulfillment_order'
       AND processing.mapping_version=2
    THEN
        payload:=convert_from(receipt.raw_payload,'UTF8')::jsonb;
        IF jsonb_typeof(payload->'lines')<>'array'
           OR attempt.applied_mapping_count<>jsonb_array_length(payload->'lines')
           OR NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(payload->'lines') line
            WHERE line->>'line_key'=NEW.line_key
              AND line->>'external_item_key'=NEW.external_item_key
              AND line->>'external_uom'=NEW.external_uom)
        THEN
            RAISE EXCEPTION 'integration processing attempt mapping lacks matching source line'
                USING ERRCODE='23514';
        END IF;
    ELSIF processing.adapter_key='x12.940.warehouse_shipping_order'
          AND processing.mapping_version=1
          AND lower(btrim(split_part(receipt.content_type,';',1)))='application/edi-x12'
    THEN
        payload_text:=convert_from(receipt.raw_payload,'UTF8');
        IF octet_length(receipt.raw_payload)<106 THEN
            RAISE EXCEPTION 'X12 integration source is shorter than its ISA envelope'
                USING ERRCODE='23514';
        END IF;
        element_separator:=substr(payload_text,4,1);
        segment_terminator:=substr(payload_text,106,1);
        segments:=string_to_array(payload_text,segment_terminator);
        IF attempt.applied_mapping_count<>(
              SELECT count(*) FROM unnest(segments) segment
              WHERE split_part(btrim(segment),element_separator,1)='W01')
           OR NOT EXISTS (
              SELECT 1 FROM generate_subscripts(segments,1) position
              WHERE position<array_length(segments,1)
                AND split_part(btrim(segments[position]),element_separator,1)='LX'
                AND split_part(btrim(segments[position]),element_separator,2)=NEW.line_key
                AND split_part(btrim(segments[position+1]),element_separator,1)='W01'
                AND split_part(btrim(segments[position+1]),element_separator,3)=NEW.external_uom
                AND split_part(btrim(segments[position+1]),element_separator,5) IN ('SK','VP')
                AND split_part(btrim(segments[position+1]),element_separator,6)=NEW.external_item_key)
        THEN
            RAISE EXCEPTION 'X12 integration mapping lacks matching LX/W01 source evidence'
                USING ERRCODE='23514';
        END IF;
    ELSE
        RAISE EXCEPTION 'integration mapping uses an unsupported source adapter'
            USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.require_integration_inbox_processing_consistency() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.integration_inbox_processing_attempts attempt
        WHERE attempt.tenant_id=NEW.tenant_id
          AND attempt.inventory_owner_id=NEW.inventory_owner_id
          AND attempt.processing_id=NEW.id
          AND attempt.receipt_id=NEW.receipt_id
          AND attempt.attempt_number=NEW.attempt_count
          AND attempt.resulting_revision=NEW.revision
          AND attempt.input_payload_sha256=NEW.last_input_payload_sha256
          AND attempt.correction_id IS NOT DISTINCT FROM NEW.last_correction_id
          AND attempt.outcome=NEW.status
          AND attempt.order_id IS NOT DISTINCT FROM NEW.order_id
          AND attempt.order_revision IS NOT DISTINCT FROM NEW.order_revision
          AND attempt.error_code IS NOT DISTINCT FROM NEW.error_code
          AND attempt.error_message IS NOT DISTINCT FROM NEW.error_message
          AND attempt.attempted_by_user_id=NEW.last_attempted_by_user_id
          AND attempt.attempted_at=NEW.last_attempted_at
    ) THEN
        RAISE EXCEPTION 'integration inbox processing lacks exact attempt evidence'
            USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION public.require_integration_inbox_processing_attempt_projection() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.integration_inbox_processings processing
        WHERE processing.tenant_id=NEW.tenant_id
          AND processing.inventory_owner_id=NEW.inventory_owner_id
          AND processing.id=NEW.processing_id
          AND processing.receipt_id=NEW.receipt_id
          AND processing.revision=NEW.resulting_revision
          AND processing.attempt_count=NEW.attempt_number
          AND processing.last_input_payload_sha256=NEW.input_payload_sha256
          AND processing.last_correction_id IS NOT DISTINCT FROM NEW.correction_id
          AND NEW.applied_mapping_count=(
              SELECT COUNT(*) FROM public.integration_inbox_processing_attempt_mappings mapping
              WHERE mapping.tenant_id=NEW.tenant_id
                AND mapping.processing_attempt_id=NEW.id)
    ) THEN
        RAISE EXCEPTION 'integration inbox processing attempt lacks exact current projection'
            USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION public.require_integration_inbox_attempt_mapping_count() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.integration_inbox_processing_attempts attempt
        WHERE attempt.tenant_id=NEW.tenant_id
          AND attempt.inventory_owner_id=NEW.inventory_owner_id
          AND attempt.id=NEW.processing_attempt_id
          AND attempt.processing_id=NEW.processing_id
          AND attempt.receipt_id=NEW.receipt_id
          AND attempt.attempt_number=NEW.attempt_number
          AND attempt.applied_mapping_count=(
              SELECT COUNT(*) FROM public.integration_inbox_processing_attempt_mappings mapping
              WHERE mapping.tenant_id=NEW.tenant_id
                AND mapping.processing_attempt_id=NEW.processing_attempt_id)
    ) THEN
        RAISE EXCEPTION 'integration processing attempt mapping count is inconsistent'
            USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION public.require_integration_inbox_processing_correction_consistency() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.integration_inbox_processings processing
        JOIN public.integration_inbox_processing_attempts attempt
          ON attempt.tenant_id=processing.tenant_id
         AND attempt.inventory_owner_id=processing.inventory_owner_id
         AND attempt.processing_id=processing.id
         AND attempt.receipt_id=processing.receipt_id
         AND attempt.resulting_revision=NEW.resulting_revision
        WHERE processing.tenant_id=NEW.tenant_id
          AND processing.inventory_owner_id=NEW.inventory_owner_id
          AND processing.id=NEW.processing_id
          AND processing.receipt_id=NEW.receipt_id
          AND processing.revision=NEW.resulting_revision
          AND processing.last_correction_id=NEW.id
          AND processing.last_input_payload_sha256=NEW.payload_sha256
          AND attempt.correction_id=NEW.id
          AND attempt.input_payload_sha256=NEW.payload_sha256
          AND attempt.attempted_by_user_id=NEW.corrected_by_user_id
          AND attempt.attempted_at=NEW.corrected_at
    ) THEN
        RAISE EXCEPTION 'integration inbox correction lacks exact processing attempt evidence'
            USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE TRIGGER integration_inbox_processings_guard
BEFORE INSERT OR UPDATE OR DELETE ON public.integration_inbox_processings
FOR EACH ROW EXECUTE FUNCTION public.guard_integration_inbox_processing_mutation();
CREATE CONSTRAINT TRIGGER integration_inbox_processings_require_attempt
AFTER INSERT OR UPDATE ON public.integration_inbox_processings
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
