-- M4 advisory slotting: versioned configuration, immutable run evidence, and
-- supervisor decisions that create typed relocation work without moving stock.
CREATE TABLE public.slotting_profiles (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  inventory_owner_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  mode text NOT NULL,
  demand_lookback_days bigint NOT NULL,
  demand_weight bigint NOT NULL,
  travel_weight bigint NOT NULL,
  activity_weight bigint NOT NULL,
  minimum_demand_quantity bigint NOT NULL,
  max_recommendations bigint NOT NULL,
  default_task_priority bigint NOT NULL,
  revision bigint NOT NULL,
  supersedes_slotting_profile_id bigint,
  effective_from timestamptz NOT NULL,
  effective_to timestamptz,
  configured_by_user_id bigint NOT NULL,
  configured_at timestamptz NOT NULL,
  UNIQUE (tenant_id,id),
  UNIQUE (tenant_id,inventory_owner_id,facility_id,id),
  UNIQUE (tenant_id,inventory_owner_id,facility_id,revision),
  CHECK (mode IN ('enabled','disabled')),
  CHECK (demand_lookback_days BETWEEN 1 AND 365),
  CHECK (demand_weight BETWEEN 1 AND 10000),
  CHECK (travel_weight BETWEEN 1 AND 10000),
  CHECK (activity_weight BETWEEN 1 AND 10000),
  CHECK (minimum_demand_quantity>0),
  CHECK (max_recommendations BETWEEN 1 AND 1000),
  CHECK (default_task_priority BETWEEN 0 AND 65535),
  CHECK (revision>0 AND (
    revision=1 AND supersedes_slotting_profile_id IS NULL
    OR revision>1 AND supersedes_slotting_profile_id IS NOT NULL)),
  CHECK (configured_at=effective_from),
  CHECK (effective_to IS NULL OR effective_to>effective_from),
  FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
  FOREIGN KEY (tenant_id,inventory_owner_id)
    REFERENCES public.inventory_owners(tenant_id,id),
  FOREIGN KEY (tenant_id,facility_id)
    REFERENCES public.facilities(tenant_id,id),
  FOREIGN KEY (tenant_id,inventory_owner_id,facility_id)
    REFERENCES public.inventory_owner_facilities(tenant_id,inventory_owner_id,facility_id),
  FOREIGN KEY (tenant_id,configured_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  FOREIGN KEY (tenant_id,inventory_owner_id,facility_id,supersedes_slotting_profile_id)
    REFERENCES public.slotting_profiles(tenant_id,inventory_owner_id,facility_id,id)
);

CREATE UNIQUE INDEX slotting_profiles_one_active_scope_idx
ON public.slotting_profiles(tenant_id,inventory_owner_id,facility_id)
WHERE effective_to IS NULL;
CREATE INDEX slotting_profiles_page_idx
ON public.slotting_profiles(tenant_id,configured_at DESC,id DESC);
CREATE INDEX slotting_profiles_scope_history_idx
ON public.slotting_profiles(
  tenant_id,inventory_owner_id,facility_id,revision DESC,id DESC);

CREATE TABLE public.slotting_runs (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  inventory_owner_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  slotting_profile_id bigint NOT NULL,
  profile_revision bigint NOT NULL,
  demand_window_started_at timestamptz NOT NULL,
  input_snapshot_at timestamptz NOT NULL,
  configuration_snapshot jsonb NOT NULL,
  candidate_count bigint NOT NULL,
  recommendation_count bigint NOT NULL,
  generated_by_user_id bigint NOT NULL,
  generated_at timestamptz NOT NULL,
  UNIQUE (tenant_id,id),
  UNIQUE (tenant_id,inventory_owner_id,facility_id,id),
  CHECK (profile_revision>0),
  CHECK (demand_window_started_at<input_snapshot_at),
  CHECK (input_snapshot_at=generated_at),
  CHECK (jsonb_typeof(configuration_snapshot)='object'),
  CHECK (candidate_count>=0 AND recommendation_count>=0
    AND recommendation_count<=candidate_count AND recommendation_count<=1000),
  FOREIGN KEY (tenant_id,inventory_owner_id,facility_id,slotting_profile_id)
    REFERENCES public.slotting_profiles(tenant_id,inventory_owner_id,facility_id,id),
  FOREIGN KEY (tenant_id,generated_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id)
);

CREATE INDEX slotting_runs_scope_page_idx
ON public.slotting_runs(
  tenant_id,inventory_owner_id,facility_id,generated_at DESC,id DESC);

CREATE TABLE public.slotting_recommendations (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  inventory_owner_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  slotting_run_id bigint NOT NULL,
  source_inventory_balance_id bigint NOT NULL,
  item_id bigint NOT NULL,
  item_description text,
  uom text NOT NULL,
  source_location_id bigint NOT NULL,
  source_location_label text NOT NULL,
  source_zone_code text NOT NULL,
  destination_location_id bigint NOT NULL,
  destination_location_label text NOT NULL,
  destination_zone_code text NOT NULL,
  item_storage_policy_id bigint NOT NULL,
  item_storage_policy_revision bigint NOT NULL,
  recommended_quantity bigint NOT NULL,
  reason text NOT NULL,
  demand_score bigint NOT NULL,
  travel_score bigint NOT NULL,
  activity_score bigint NOT NULL,
  total_score bigint NOT NULL,
  outstanding_demand_quantity bigint NOT NULL,
  historical_pick_quantity bigint NOT NULL,
  historical_pick_count bigint NOT NULL,
  source_travel_sequence bigint NOT NULL,
  destination_travel_sequence bigint NOT NULL,
  source_on_hand bigint NOT NULL,
  source_movable_quantity bigint NOT NULL,
  destination_on_hand bigint NOT NULL,
  destination_inbound_planned_quantity bigint NOT NULL,
  destination_capacity bigint,
  status text NOT NULL,
  revision bigint NOT NULL,
  decided_by_user_id bigint,
  decided_at timestamptz,
  dismissal_reason text,
  dismissal_note text,
  inventory_relocation_task_id bigint,
  created_at timestamptz NOT NULL,
  UNIQUE (tenant_id,id),
  CHECK (source_location_id<>destination_location_id),
  CHECK (uom=btrim(uom) AND uom<>'' AND char_length(uom)<=32),
  CHECK (source_location_label=btrim(source_location_label)
    AND source_location_label<>'' AND char_length(source_location_label)<=200),
  CHECK (destination_location_label=btrim(destination_location_label)
    AND destination_location_label<>'' AND char_length(destination_location_label)<=200),
  CHECK (source_zone_code=upper(btrim(source_zone_code)) AND source_zone_code<>''),
  CHECK (destination_zone_code=upper(btrim(destination_zone_code))
    AND destination_zone_code<>''),
  CHECK (item_storage_policy_revision>0),
  CHECK (recommended_quantity>0),
  CHECK (reason IN ('forward_pick_demand','travel_reduction','capacity_rebalance')),
  CHECK (demand_score>=0 AND travel_score>0 AND activity_score>=0
    AND total_score=demand_score+travel_score+activity_score),
  CHECK (outstanding_demand_quantity>=0 AND historical_pick_quantity>=0
    AND historical_pick_count>=0),
  CHECK (source_travel_sequence>destination_travel_sequence
    AND destination_travel_sequence>=0),
  CHECK (source_on_hand>0 AND source_movable_quantity>0
    AND source_movable_quantity<=source_on_hand
    AND recommended_quantity<=source_movable_quantity),
  CHECK (destination_on_hand>=0 AND destination_inbound_planned_quantity>=0 AND (
    destination_capacity IS NULL OR destination_capacity>0
      AND destination_on_hand+destination_inbound_planned_quantity
        +recommended_quantity<=destination_capacity)),
  CHECK (status IN ('pending','accepted','dismissed')),
  CHECK (revision>0),
  CHECK (dismissal_reason IS NULL OR dismissal_reason IN (
    'capacity_changed','operational_constraint','item_strategy','stale_evidence',
    'duplicate_work','other')),
  CHECK (dismissal_note IS NULL OR dismissal_note=btrim(dismissal_note)
    AND dismissal_note<>'' AND char_length(dismissal_note)<=500),
  CHECK (dismissal_reason<>'other' OR dismissal_note IS NOT NULL),
  CHECK (
    status='pending' AND revision=1 AND decided_by_user_id IS NULL
      AND decided_at IS NULL AND dismissal_reason IS NULL AND dismissal_note IS NULL
      AND inventory_relocation_task_id IS NULL
    OR status='accepted' AND revision=2 AND decided_by_user_id IS NOT NULL
      AND decided_at IS NOT NULL AND dismissal_reason IS NULL AND dismissal_note IS NULL
      AND inventory_relocation_task_id IS NOT NULL
    OR status='dismissed' AND revision=2 AND decided_by_user_id IS NOT NULL
      AND decided_at IS NOT NULL AND dismissal_reason IS NOT NULL
      AND inventory_relocation_task_id IS NULL),
  FOREIGN KEY (tenant_id,inventory_owner_id,facility_id,slotting_run_id)
    REFERENCES public.slotting_runs(tenant_id,inventory_owner_id,facility_id,id),
  FOREIGN KEY (tenant_id,source_inventory_balance_id)
    REFERENCES public.inventory_balances(tenant_id,id),
  FOREIGN KEY (tenant_id,item_id) REFERENCES public.items(tenant_id,id),
  FOREIGN KEY (tenant_id,facility_id,source_location_id)
    REFERENCES public.locations(tenant_id,facility_id,id),
  FOREIGN KEY (tenant_id,facility_id,destination_location_id)
    REFERENCES public.locations(tenant_id,facility_id,id),
  FOREIGN KEY (tenant_id,inventory_owner_id,facility_id,item_storage_policy_id)
    REFERENCES public.item_storage_policies(tenant_id,inventory_owner_id,facility_id,id),
  FOREIGN KEY (tenant_id,decided_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  FOREIGN KEY (tenant_id,inventory_relocation_task_id)
    REFERENCES public.work_tasks(tenant_id,id)
);

CREATE UNIQUE INDEX slotting_recommendations_one_pending_source_idx
ON public.slotting_recommendations(tenant_id,source_inventory_balance_id)
WHERE status='pending';
CREATE INDEX slotting_recommendations_page_idx
ON public.slotting_recommendations(tenant_id,total_score DESC,id DESC);
CREATE INDEX slotting_recommendations_scope_page_idx
ON public.slotting_recommendations(
  tenant_id,inventory_owner_id,facility_id,status,total_score DESC,id DESC);
CREATE INDEX slotting_recommendations_run_idx
ON public.slotting_recommendations(tenant_id,slotting_run_id,total_score DESC,id DESC);

CREATE FUNCTION public.slotting_user_has_supervisor_permission(
  checked_tenant_id bigint,checked_user_id bigint) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
  WITH RECURSIVE granted_roles AS (
    SELECT role.id,role.parent_id
    FROM public.user_roles user_role
    JOIN public.tenant_memberships membership
      ON membership.tenant_id=user_role.tenant_id
      AND membership.user_id=user_role.user_id AND membership.deleted IS NULL
    JOIN public.roles role ON role.tenant_id=user_role.tenant_id
      AND role.id=user_role.role_id AND role.deleted IS NULL
    WHERE user_role.tenant_id=checked_tenant_id AND user_role.user_id=checked_user_id
      AND user_role.deleted IS NULL
    UNION
    SELECT parent.id,parent.parent_id
    FROM granted_roles child
    JOIN public.roles parent ON parent.tenant_id=checked_tenant_id
      AND parent.id=child.parent_id AND parent.deleted IS NULL
  )
  SELECT EXISTS(
    SELECT 1 FROM granted_roles role
    JOIN public.role_permissions role_permission
      ON role_permission.tenant_id=checked_tenant_id
      AND role_permission.role_id=role.id AND role_permission.deleted IS NULL
    JOIN public.permissions permission
      ON permission.tenant_id=role_permission.tenant_id
      AND permission.id=role_permission.permission_id AND permission.deleted IS NULL
    WHERE upper(permission.name) IN('WMS_SUPERVISOR','ADMIN')
  )
$$;

CREATE FUNCTION public.slotting_destination_planned_quantity(
  checked_tenant_id bigint,checked_inventory_owner_id bigint,
  checked_facility_id bigint,checked_location_id bigint,
  checked_item_id bigint,checked_uom text) RETURNS bigint
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
  SELECT COALESCE(sum(inbound.quantity),0)::bigint FROM (
    SELECT putaway.planned_quantity AS quantity
    FROM public.putaway_tasks putaway
    JOIN public.inventory_balances source
      ON source.tenant_id=putaway.tenant_id
      AND source.id=putaway.source_inventory_balance_id
    WHERE putaway.tenant_id=checked_tenant_id
      AND putaway.inventory_owner_id=checked_inventory_owner_id
      AND putaway.facility_id=checked_facility_id
      AND putaway.destination_location_id=checked_location_id
      AND putaway.item_id=checked_item_id AND source.uom=checked_uom
      AND putaway.closed_at IS NULL
    UNION ALL
    SELECT relocation.planned_quantity
    FROM public.inventory_relocation_tasks relocation
    WHERE relocation.tenant_id=checked_tenant_id
      AND relocation.inventory_owner_id=checked_inventory_owner_id
      AND relocation.facility_id=checked_facility_id
      AND relocation.destination_location_id=checked_location_id
      AND relocation.item_id=checked_item_id AND relocation.uom=checked_uom
      AND relocation.workflow='loose_balance' AND relocation.closed_at IS NULL
    UNION ALL
    SELECT replenishment.planned_qty
    FROM public.replenishment_tasks replenishment
    WHERE replenishment.tenant_id=checked_tenant_id
      AND replenishment.inventory_owner_id=checked_inventory_owner_id
      AND replenishment.facility_id=checked_facility_id
      AND replenishment.destination_location_id=checked_location_id
      AND replenishment.item_id=checked_item_id AND replenishment.uom=checked_uom
      AND replenishment.closed_at IS NULL
    UNION ALL
    SELECT cross_dock.planned_quantity
    FROM public.cross_dock_tasks cross_dock
    WHERE cross_dock.tenant_id=checked_tenant_id
      AND cross_dock.inventory_owner_id=checked_inventory_owner_id
      AND cross_dock.facility_id=checked_facility_id
      AND cross_dock.destination_location_id=checked_location_id
      AND cross_dock.item_id=checked_item_id AND cross_dock.uom=checked_uom
      AND cross_dock.closed_at IS NULL
    UNION ALL
    SELECT content.planned_quantity
    FROM public.license_plate_putaway_tasks task
    JOIN public.license_plate_putaway_task_contents content
      ON content.tenant_id=task.tenant_id AND content.task_id=task.task_id
    WHERE task.tenant_id=checked_tenant_id
      AND task.inventory_owner_id=checked_inventory_owner_id
      AND task.facility_id=checked_facility_id
      AND task.destination_location_id=checked_location_id
      AND content.item_id=checked_item_id AND content.uom=checked_uom
      AND task.closed_at IS NULL
  ) inbound
$$;

CREATE FUNCTION public.validate_slotting_profile_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE predecessor public.slotting_profiles%ROWTYPE;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(':','slotting_profile',
    NEW.tenant_id,NEW.inventory_owner_id,NEW.facility_id),0));
  IF NOT EXISTS(SELECT 1 FROM public.inventory_owner_facilities assignment
      JOIN public.inventory_owners owner ON owner.tenant_id=assignment.tenant_id
        AND owner.id=assignment.inventory_owner_id AND owner.deleted IS NULL
      JOIN public.facilities facility ON facility.tenant_id=assignment.tenant_id
        AND facility.id=assignment.facility_id AND facility.deleted IS NULL
      WHERE assignment.tenant_id=NEW.tenant_id
        AND assignment.inventory_owner_id=NEW.inventory_owner_id
        AND assignment.facility_id=NEW.facility_id AND assignment.deleted IS NULL)
    OR NOT EXISTS(SELECT 1 FROM public.tenant_memberships membership
      WHERE membership.tenant_id=NEW.tenant_id
        AND membership.user_id=NEW.configured_by_user_id AND membership.deleted IS NULL)
    OR NEW.configured_by_user_id IS DISTINCT FROM
      NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint
    OR NOT public.slotting_user_has_supervisor_permission(
      NEW.tenant_id,NEW.configured_by_user_id) THEN
    RAISE EXCEPTION 'slotting profile requires active scope and membership'
      USING ERRCODE='23514';
  END IF;
  IF NEW.supersedes_slotting_profile_id IS NULL THEN
    IF NEW.revision<>1 OR EXISTS(SELECT 1 FROM public.slotting_profiles existing
      WHERE existing.tenant_id=NEW.tenant_id
        AND existing.inventory_owner_id=NEW.inventory_owner_id
        AND existing.facility_id=NEW.facility_id) THEN
      RAISE EXCEPTION 'initial slotting profile revision is invalid' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO predecessor FROM public.slotting_profiles profile
  WHERE profile.tenant_id=NEW.tenant_id
    AND profile.inventory_owner_id=NEW.inventory_owner_id
    AND profile.facility_id=NEW.facility_id
    AND profile.id=NEW.supersedes_slotting_profile_id FOR SHARE;
  IF NOT FOUND OR predecessor.revision+1<>NEW.revision
    OR predecessor.effective_to IS NULL
    OR predecessor.effective_to<>NEW.effective_from
    OR EXISTS(SELECT 1 FROM public.slotting_profiles newer
      WHERE newer.tenant_id=NEW.tenant_id
        AND newer.inventory_owner_id=NEW.inventory_owner_id
        AND newer.facility_id=NEW.facility_id AND newer.revision>=NEW.revision) THEN
    RAISE EXCEPTION 'slotting profile successor does not match closed predecessor'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.guard_slotting_profile_mutation() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'slotting profiles are immutable' USING ERRCODE='23514';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(':','slotting_profile',
    OLD.tenant_id,OLD.inventory_owner_id,OLD.facility_id),0));
  IF NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint IS NULL
    OR NOT public.slotting_user_has_supervisor_permission(OLD.tenant_id,
      NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint)
    OR NEW.id<>OLD.id OR NEW.tenant_id<>OLD.tenant_id
    OR NEW.inventory_owner_id<>OLD.inventory_owner_id OR NEW.facility_id<>OLD.facility_id
    OR NEW.mode<>OLD.mode OR NEW.demand_lookback_days<>OLD.demand_lookback_days
    OR NEW.demand_weight<>OLD.demand_weight OR NEW.travel_weight<>OLD.travel_weight
    OR NEW.activity_weight<>OLD.activity_weight
    OR NEW.minimum_demand_quantity<>OLD.minimum_demand_quantity
    OR NEW.max_recommendations<>OLD.max_recommendations
    OR NEW.default_task_priority<>OLD.default_task_priority OR NEW.revision<>OLD.revision
    OR NEW.supersedes_slotting_profile_id IS DISTINCT FROM OLD.supersedes_slotting_profile_id
    OR NEW.effective_from<>OLD.effective_from
    OR NEW.configured_by_user_id<>OLD.configured_by_user_id
    OR NEW.configured_at<>OLD.configured_at OR OLD.effective_to IS NOT NULL
    OR NEW.effective_to IS NULL OR NEW.effective_to<=OLD.effective_from THEN
    RAISE EXCEPTION 'only active slotting profile closure is allowed' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.require_slotting_profile_successor() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
BEGIN
  IF NEW.effective_to IS NOT NULL AND OLD.effective_to IS NULL
    AND NOT EXISTS(SELECT 1 FROM public.slotting_profiles successor
      WHERE successor.tenant_id=NEW.tenant_id
        AND successor.inventory_owner_id=NEW.inventory_owner_id
        AND successor.facility_id=NEW.facility_id
        AND successor.supersedes_slotting_profile_id=NEW.id
        AND successor.revision=NEW.revision+1
        AND successor.effective_from=NEW.effective_to
        AND successor.effective_to IS NULL) THEN
    RAISE EXCEPTION 'slotting profile closure requires an active successor'
      USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;

CREATE FUNCTION public.reject_slotting_run_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$ BEGIN
  RAISE EXCEPTION 'slotting runs are immutable' USING ERRCODE='23514';
END $$;

CREATE FUNCTION public.validate_slotting_run_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE profile public.slotting_profiles%ROWTYPE;
BEGIN
  SELECT * INTO profile FROM public.slotting_profiles configured
  WHERE configured.tenant_id=NEW.tenant_id
    AND configured.inventory_owner_id=NEW.inventory_owner_id
    AND configured.facility_id=NEW.facility_id
    AND configured.id=NEW.slotting_profile_id FOR SHARE;
  IF NOT FOUND OR profile.revision<>NEW.profile_revision OR profile.mode<>'enabled'
    OR profile.effective_to IS NOT NULL
    OR NEW.demand_window_started_at IS DISTINCT FROM NEW.generated_at
      -make_interval(days=>profile.demand_lookback_days::integer)
    OR NEW.recommendation_count>profile.max_recommendations
    OR (SELECT count(*) FROM jsonb_object_keys(NEW.configuration_snapshot))<>8
    OR jsonb_typeof(NEW.configuration_snapshot->'definition')<>'object'
    OR (SELECT count(*) FROM jsonb_object_keys(
      NEW.configuration_snapshot->'definition'))<>11
    OR NEW.configuration_snapshot->>'slotting_profile_id' IS DISTINCT FROM profile.id::text
    OR (NEW.configuration_snapshot->>'revision')::bigint IS DISTINCT FROM profile.revision
    OR (NEW.configuration_snapshot->>'configured_by')::bigint
      IS DISTINCT FROM profile.configured_by_user_id
    OR (NEW.configuration_snapshot->>'configured_at')::timestamptz
      IS DISTINCT FROM profile.configured_at
    OR (NEW.configuration_snapshot->>'effective_from')::timestamptz
      IS DISTINCT FROM profile.effective_from
    OR (NEW.configuration_snapshot->>'supersedes_slotting_profile_id')::bigint
      IS DISTINCT FROM profile.supersedes_slotting_profile_id
    OR (NEW.configuration_snapshot->>'effective_to')::timestamptz
      IS DISTINCT FROM profile.effective_to
    OR (NEW.configuration_snapshot->'definition'->>'tenant_id')::bigint
      IS DISTINCT FROM profile.tenant_id
    OR (NEW.configuration_snapshot->'definition'->>'inventory_owner_id')::bigint
      IS DISTINCT FROM profile.inventory_owner_id
    OR (NEW.configuration_snapshot->'definition'->>'facility_id')::bigint
      IS DISTINCT FROM profile.facility_id
    OR NEW.configuration_snapshot->'definition'->>'mode' IS DISTINCT FROM profile.mode
    OR (NEW.configuration_snapshot->'definition'->>'demand_lookback_days')::bigint
      IS DISTINCT FROM profile.demand_lookback_days
    OR (NEW.configuration_snapshot->'definition'->>'demand_weight')::bigint
      IS DISTINCT FROM profile.demand_weight
    OR (NEW.configuration_snapshot->'definition'->>'travel_weight')::bigint
      IS DISTINCT FROM profile.travel_weight
    OR (NEW.configuration_snapshot->'definition'->>'activity_weight')::bigint
      IS DISTINCT FROM profile.activity_weight
    OR (NEW.configuration_snapshot->'definition'->>'minimum_demand_quantity')::bigint
      IS DISTINCT FROM profile.minimum_demand_quantity
    OR (NEW.configuration_snapshot->'definition'->>'max_recommendations')::bigint
      IS DISTINCT FROM profile.max_recommendations
    OR (NEW.configuration_snapshot->'definition'->>'default_task_priority')::bigint
      IS DISTINCT FROM profile.default_task_priority
    OR NOT EXISTS(SELECT 1 FROM public.tenant_memberships membership
      WHERE membership.tenant_id=NEW.tenant_id
        AND membership.user_id=NEW.generated_by_user_id AND membership.deleted IS NULL)
    OR NEW.generated_by_user_id IS DISTINCT FROM
      NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint
    OR NOT public.slotting_user_has_supervisor_permission(
      NEW.tenant_id,NEW.generated_by_user_id) THEN
    RAISE EXCEPTION 'slotting run configuration snapshot is invalid' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.validate_slotting_recommendation_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE run_row public.slotting_runs%ROWTYPE; demand_weight bigint;
  travel_weight bigint; activity_weight bigint; current_outstanding bigint;
  current_historical_quantity bigint; current_historical_count bigint;
  current_destination_on_hand bigint; current_destination_planned bigint;
  current_destination_capacity bigint; expected_quantity bigint; expected_reason text;
BEGIN
  SELECT * INTO run_row FROM public.slotting_runs run
  WHERE run.tenant_id=NEW.tenant_id AND run.id=NEW.slotting_run_id FOR SHARE;
  IF NOT FOUND OR run_row.inventory_owner_id<>NEW.inventory_owner_id
    OR run_row.facility_id<>NEW.facility_id OR NEW.created_at<>run_row.generated_at
    OR run_row.generated_by_user_id IS DISTINCT FROM
      NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint
    OR NOT public.slotting_user_has_supervisor_permission(
      NEW.tenant_id,run_row.generated_by_user_id) THEN
    RAISE EXCEPTION 'slotting recommendation run scope is invalid' USING ERRCODE='23514';
  END IF;
  demand_weight:=(run_row.configuration_snapshot->'definition'->>'demand_weight')::bigint;
  travel_weight:=(run_row.configuration_snapshot->'definition'->>'travel_weight')::bigint;
  activity_weight:=(run_row.configuration_snapshot->'definition'->>'activity_weight')::bigint;

  SELECT COALESCE(sum(reservation.qty),0)::bigint INTO current_outstanding
  FROM public.inventory_reservations reservation
  WHERE reservation.tenant_id=NEW.tenant_id
    AND reservation.inventory_owner_id=NEW.inventory_owner_id
    AND reservation.facility_id=NEW.facility_id AND reservation.item_id=NEW.item_id
    AND reservation.uom=NEW.uom AND reservation.status='active'
    AND reservation.deleted IS NULL;
  SELECT COALESCE(sum(pick.picked_qty),0)::bigint,count(*)::bigint
    INTO current_historical_quantity,current_historical_count
  FROM public.pick_confirmations pick
  WHERE pick.tenant_id=NEW.tenant_id
    AND pick.inventory_owner_id=NEW.inventory_owner_id
    AND pick.facility_id=NEW.facility_id AND pick.item_id=NEW.item_id
    AND pick.uom=NEW.uom AND pick.confirmed_at>=run_row.demand_window_started_at
    AND pick.confirmed_at<=run_row.input_snapshot_at;
  SELECT COALESCE(sum(balance.qty_on_hand),0)::bigint INTO current_destination_on_hand
  FROM public.inventory_balances balance
  WHERE balance.tenant_id=NEW.tenant_id
    AND balance.inventory_owner_id=NEW.inventory_owner_id
    AND balance.facility_id=NEW.facility_id
    AND balance.location_id=NEW.destination_location_id
    AND balance.item_id=NEW.item_id AND balance.uom=NEW.uom AND balance.deleted IS NULL;
  current_destination_planned:=public.slotting_destination_planned_quantity(
    NEW.tenant_id,NEW.inventory_owner_id,NEW.facility_id,
    NEW.destination_location_id,NEW.item_id,NEW.uom);
  SELECT policy.max_quantity_per_location INTO current_destination_capacity
  FROM public.item_storage_policies policy
  JOIN public.item_storage_policy_zone_purposes allowed
    ON allowed.tenant_id=policy.tenant_id
    AND allowed.item_storage_policy_id=policy.id AND allowed.purpose='pick'
  WHERE policy.tenant_id=NEW.tenant_id AND policy.id=NEW.item_storage_policy_id
    AND policy.inventory_owner_id=NEW.inventory_owner_id
    AND policy.facility_id=NEW.facility_id AND policy.item_id=NEW.item_id
    AND policy.uom=NEW.uom AND policy.revision=NEW.item_storage_policy_revision
    AND policy.effective_to IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'slotting recommendation policy evidence is invalid'
      USING ERRCODE='23514';
  END IF;
  expected_quantity:=LEAST(NEW.source_movable_quantity,
    current_outstanding+current_historical_quantity,
    CASE WHEN current_destination_capacity IS NULL THEN NEW.source_movable_quantity
      ELSE current_destination_capacity-current_destination_on_hand
        -current_destination_planned END);
  expected_reason:=CASE WHEN current_outstanding>0 THEN 'forward_pick_demand'
    WHEN current_destination_capacity IS NOT NULL THEN 'capacity_rebalance'
    ELSE 'travel_reduction' END;

  IF NEW.demand_score<>(NEW.outstanding_demand_quantity+NEW.historical_pick_quantity)*demand_weight
    OR NEW.travel_score<>(NEW.source_travel_sequence-NEW.destination_travel_sequence)
      *NEW.recommended_quantity*travel_weight
    OR NEW.activity_score<>NEW.historical_pick_count*activity_weight
    OR NEW.outstanding_demand_quantity<>current_outstanding
    OR NEW.historical_pick_quantity<>current_historical_quantity
    OR NEW.historical_pick_count<>current_historical_count
    OR NEW.destination_on_hand<>current_destination_on_hand
    OR NEW.destination_inbound_planned_quantity<>current_destination_planned
    OR NEW.destination_capacity IS DISTINCT FROM current_destination_capacity
    OR NEW.recommended_quantity<>expected_quantity OR NEW.reason<>expected_reason
    OR current_outstanding+current_historical_quantity<
      (run_row.configuration_snapshot->'definition'->>'minimum_demand_quantity')::bigint
    OR NOT EXISTS(SELECT 1 FROM public.inventory_balances balance
      JOIN public.items item ON item.tenant_id=balance.tenant_id
        AND item.id=balance.item_id AND item.deleted IS NULL
      WHERE balance.tenant_id=NEW.tenant_id AND balance.id=NEW.source_inventory_balance_id
        AND balance.inventory_owner_id=NEW.inventory_owner_id
        AND balance.facility_id=NEW.facility_id AND balance.item_id=NEW.item_id
        AND balance.uom=NEW.uom AND balance.location_id=NEW.source_location_id
        AND balance.deleted IS NULL AND balance.license_plate_id IS NULL
        AND balance.status='available' AND balance.qty_on_hand=NEW.source_on_hand
        AND balance.qty_on_hand-balance.qty_reserved-balance.qty_held
          =NEW.source_movable_quantity
        AND item.description IS NOT DISTINCT FROM NEW.item_description)
    OR EXISTS(SELECT 1 FROM public.inventory_relocation_tasks movement
      WHERE movement.tenant_id=NEW.tenant_id
        AND movement.source_inventory_balance_id=NEW.source_inventory_balance_id
        AND movement.closed_at IS NULL)
    OR EXISTS(SELECT 1 FROM public.putaway_tasks movement
      WHERE movement.tenant_id=NEW.tenant_id
        AND movement.source_inventory_balance_id=NEW.source_inventory_balance_id
        AND movement.closed_at IS NULL)
    OR EXISTS(SELECT 1 FROM public.inventory_balances source
      JOIN public.item_batches incoming_batch
        ON incoming_batch.tenant_id=source.tenant_id
        AND incoming_batch.id=source.item_batch_id AND incoming_batch.deleted IS NULL
      JOIN public.inventory_balances conflict_balance
        ON conflict_balance.tenant_id=source.tenant_id
        AND conflict_balance.inventory_owner_id=source.inventory_owner_id
        AND conflict_balance.location_id=NEW.destination_location_id
        AND conflict_balance.item_id=source.item_id
        AND conflict_balance.item_batch_id<>source.item_batch_id
        AND conflict_balance.deleted IS NULL AND conflict_balance.qty_on_hand>0
      JOIN public.item_batches existing_batch
        ON existing_batch.tenant_id=conflict_balance.tenant_id
        AND existing_batch.id=conflict_balance.item_batch_id
      WHERE source.tenant_id=NEW.tenant_id
        AND source.id=NEW.source_inventory_balance_id
        AND (existing_batch.lot IS DISTINCT FROM incoming_batch.lot
          OR existing_batch.expiration IS DISTINCT FROM incoming_batch.expiration))
    OR NOT EXISTS(SELECT 1 FROM public.storage_zone_locations member
      JOIN public.storage_zones zone ON zone.tenant_id=member.tenant_id
        AND zone.facility_id=member.facility_id AND zone.id=member.storage_zone_id
        AND zone.effective_to IS NULL
      JOIN public.locations location ON location.tenant_id=member.tenant_id
        AND location.facility_id=member.facility_id AND location.id=member.location_id
        AND location.deleted IS NULL AND location.active
      WHERE member.tenant_id=NEW.tenant_id AND member.facility_id=NEW.facility_id
        AND member.location_id=NEW.source_location_id
        AND zone.code=NEW.source_zone_code
        AND zone.travel_sequence=NEW.source_travel_sequence
        AND COALESCE(NULLIF(location.name,''),location.barcode,
          'Location #'||location.id::text)=NEW.source_location_label)
    OR NOT EXISTS(SELECT 1 FROM public.storage_zone_locations member
      JOIN public.storage_zones zone ON zone.tenant_id=member.tenant_id
        AND zone.facility_id=member.facility_id AND zone.id=member.storage_zone_id
        AND zone.effective_to IS NULL AND zone.purpose='pick'
      JOIN public.locations location ON location.tenant_id=member.tenant_id
        AND location.facility_id=member.facility_id AND location.id=member.location_id
        AND location.deleted IS NULL AND location.active AND location.pickable
        AND NOT location.receivable AND NULLIF(btrim(location.barcode),'') IS NOT NULL
      WHERE member.tenant_id=NEW.tenant_id AND member.facility_id=NEW.facility_id
        AND member.location_id=NEW.destination_location_id
        AND zone.code=NEW.destination_zone_code
        AND zone.travel_sequence=NEW.destination_travel_sequence
        AND COALESCE(NULLIF(location.name,''),location.barcode,
          'Location #'||location.id::text)=NEW.destination_location_label) THEN
    RAISE EXCEPTION 'slotting recommendation evidence is invalid' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.guard_slotting_recommendation_mutation() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'slotting recommendations are immutable' USING ERRCODE='23514';
  END IF;
  IF NEW.id<>OLD.id OR NEW.tenant_id<>OLD.tenant_id
    OR NEW.inventory_owner_id<>OLD.inventory_owner_id OR NEW.facility_id<>OLD.facility_id
    OR NEW.slotting_run_id<>OLD.slotting_run_id
    OR NEW.source_inventory_balance_id<>OLD.source_inventory_balance_id
    OR NEW.item_id<>OLD.item_id OR NEW.item_description IS DISTINCT FROM OLD.item_description
    OR NEW.uom<>OLD.uom OR NEW.source_location_id<>OLD.source_location_id
    OR NEW.source_location_label<>OLD.source_location_label
    OR NEW.source_zone_code<>OLD.source_zone_code
    OR NEW.destination_location_id<>OLD.destination_location_id
    OR NEW.destination_location_label<>OLD.destination_location_label
    OR NEW.destination_zone_code<>OLD.destination_zone_code
    OR NEW.item_storage_policy_id<>OLD.item_storage_policy_id
    OR NEW.item_storage_policy_revision<>OLD.item_storage_policy_revision
    OR NEW.recommended_quantity<>OLD.recommended_quantity OR NEW.reason<>OLD.reason
    OR NEW.demand_score<>OLD.demand_score OR NEW.travel_score<>OLD.travel_score
    OR NEW.activity_score<>OLD.activity_score OR NEW.total_score<>OLD.total_score
    OR NEW.outstanding_demand_quantity<>OLD.outstanding_demand_quantity
    OR NEW.historical_pick_quantity<>OLD.historical_pick_quantity
    OR NEW.historical_pick_count<>OLD.historical_pick_count
    OR NEW.source_travel_sequence<>OLD.source_travel_sequence
    OR NEW.destination_travel_sequence<>OLD.destination_travel_sequence
    OR NEW.source_on_hand<>OLD.source_on_hand
    OR NEW.source_movable_quantity<>OLD.source_movable_quantity
    OR NEW.destination_on_hand<>OLD.destination_on_hand
    OR NEW.destination_inbound_planned_quantity<>OLD.destination_inbound_planned_quantity
    OR NEW.destination_capacity IS DISTINCT FROM OLD.destination_capacity
    OR NEW.created_at<>OLD.created_at OR OLD.status<>'pending' OR OLD.revision<>1
    OR NEW.revision<>2 OR NEW.status NOT IN ('accepted','dismissed')
    OR NEW.decided_at<transaction_timestamp()-INTERVAL '5 minutes'
    OR NEW.decided_at>clock_timestamp()+INTERVAL '1 minute'
    OR NEW.decided_by_user_id IS DISTINCT FROM
      NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint
    OR NOT public.slotting_user_has_supervisor_permission(
      NEW.tenant_id,NEW.decided_by_user_id)
    OR NOT EXISTS(SELECT 1 FROM public.tenant_memberships membership
      WHERE membership.tenant_id=NEW.tenant_id
        AND membership.user_id=NEW.decided_by_user_id AND membership.deleted IS NULL) THEN
    RAISE EXCEPTION 'invalid slotting recommendation decision' USING ERRCODE='23514';
  END IF;
  IF NEW.status='accepted' AND NOT EXISTS(
    SELECT 1 FROM public.work_tasks task
    JOIN public.inventory_relocation_tasks relocation
      ON relocation.tenant_id=task.tenant_id AND relocation.task_id=task.id
    WHERE task.tenant_id=NEW.tenant_id AND task.id=NEW.inventory_relocation_task_id
      AND task.task_type='inventory_relocation' AND task.created_by=NEW.decided_by_user_id
      AND task.inventory_owner_id=NEW.inventory_owner_id
      AND task.facility_id=NEW.facility_id
      AND relocation.workflow='loose_balance'
      AND relocation.source_inventory_balance_id=NEW.source_inventory_balance_id
      AND relocation.destination_location_id=NEW.destination_location_id
      AND relocation.planned_quantity=NEW.recommended_quantity) THEN
    RAISE EXCEPTION 'accepted slotting recommendation requires exact relocation work'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.require_slotting_run_recommendation_count() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE checked_tenant_id bigint; checked_run_id bigint;
BEGIN
  checked_tenant_id:=NEW.tenant_id;
  IF TG_TABLE_NAME='slotting_runs' THEN
    checked_run_id:=NEW.id;
  ELSE
    checked_run_id:=NEW.slotting_run_id;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.slotting_runs run
    WHERE run.tenant_id=checked_tenant_id AND run.id=checked_run_id
      AND run.recommendation_count=(SELECT count(*)
        FROM public.slotting_recommendations recommendation
        WHERE recommendation.tenant_id=checked_tenant_id
          AND recommendation.slotting_run_id=checked_run_id)) THEN
    RAISE EXCEPTION 'slotting run recommendation count does not reconcile'
      USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;

CREATE TRIGGER slotting_profiles_validate BEFORE INSERT ON public.slotting_profiles
FOR EACH ROW EXECUTE FUNCTION public.validate_slotting_profile_insert();
CREATE TRIGGER slotting_profiles_guard BEFORE UPDATE OR DELETE ON public.slotting_profiles
FOR EACH ROW EXECUTE FUNCTION public.guard_slotting_profile_mutation();
CREATE CONSTRAINT TRIGGER slotting_profiles_require_successor
AFTER UPDATE OF effective_to ON public.slotting_profiles DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_slotting_profile_successor();
CREATE TRIGGER slotting_runs_validate BEFORE INSERT ON public.slotting_runs
FOR EACH ROW EXECUTE FUNCTION public.validate_slotting_run_insert();
CREATE TRIGGER slotting_runs_immutable BEFORE UPDATE OR DELETE ON public.slotting_runs
FOR EACH ROW EXECUTE FUNCTION public.reject_slotting_run_mutation();
CREATE TRIGGER slotting_recommendations_validate
BEFORE INSERT ON public.slotting_recommendations
FOR EACH ROW EXECUTE FUNCTION public.validate_slotting_recommendation_insert();
CREATE TRIGGER slotting_recommendations_guard
BEFORE UPDATE OR DELETE ON public.slotting_recommendations
FOR EACH ROW EXECUTE FUNCTION public.guard_slotting_recommendation_mutation();
CREATE CONSTRAINT TRIGGER slotting_runs_recommendation_count
AFTER INSERT ON public.slotting_runs DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_slotting_run_recommendation_count();
CREATE CONSTRAINT TRIGGER slotting_recommendations_run_count
AFTER INSERT ON public.slotting_recommendations DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_slotting_run_recommendation_count();

ALTER TABLE public.slotting_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.slotting_profiles FORCE ROW LEVEL SECURITY;
CREATE POLICY slotting_profiles_tenant_isolation ON public.slotting_profiles
USING (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint)
WITH CHECK (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint);
ALTER TABLE public.slotting_runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.slotting_runs FORCE ROW LEVEL SECURITY;
CREATE POLICY slotting_runs_tenant_isolation ON public.slotting_runs
USING (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint)
WITH CHECK (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint);
ALTER TABLE public.slotting_recommendations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.slotting_recommendations FORCE ROW LEVEL SECURITY;
CREATE POLICY slotting_recommendations_tenant_isolation ON public.slotting_recommendations
USING (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint)
WITH CHECK (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint);

GRANT SELECT,INSERT ON public.slotting_profiles TO wareboxes_app;
GRANT UPDATE(effective_to) ON public.slotting_profiles TO wareboxes_app;
GRANT SELECT,INSERT ON public.slotting_runs TO wareboxes_app;
GRANT SELECT,INSERT ON public.slotting_recommendations TO wareboxes_app;
GRANT UPDATE(status,revision,decided_by_user_id,decided_at,dismissal_reason,
  dismissal_note,inventory_relocation_task_id)
  ON public.slotting_recommendations TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.slotting_profiles_id_seq TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.slotting_runs_id_seq TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.slotting_recommendations_id_seq TO wareboxes_app;
GRANT EXECUTE ON FUNCTION public.slotting_destination_planned_quantity(
  bigint,bigint,bigint,bigint,bigint,text) TO wareboxes_app;
REVOKE ALL ON FUNCTION public.slotting_user_has_supervisor_permission(bigint,bigint)
  FROM PUBLIC;
REVOKE ALL ON FUNCTION public.slotting_destination_planned_quantity(
  bigint,bigint,bigint,bigint,bigint,text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_slotting_profile_insert() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_slotting_profile_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_slotting_profile_successor() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_slotting_run_insert() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.reject_slotting_run_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_slotting_recommendation_insert() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_slotting_recommendation_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_slotting_run_recommendation_count() FROM PUBLIC;

-- Explainable, advisory work orchestration with explicit manual fallback.
CREATE TABLE public.work_orchestration_policies (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  inventory_owner_id bigint,
  mode text NOT NULL,
  priority_weight bigint NOT NULL,
  due_urgency_weight bigint NOT NULL,
  proximity_weight bigint NOT NULL,
  interleaving_weight bigint NOT NULL,
  congestion_penalty_weight bigint NOT NULL,
  bottleneck_penalty_weight bigint NOT NULL,
  due_horizon_minutes bigint NOT NULL,
  max_candidates bigint NOT NULL,
  revision bigint NOT NULL,
  supersedes_policy_id bigint,
  effective_from timestamptz NOT NULL,
  effective_to timestamptz,
  configured_by_user_id bigint NOT NULL,
  configured_at timestamptz NOT NULL,
  UNIQUE (tenant_id,id),
  CHECK (mode IN ('enabled','disabled')),
  CHECK (priority_weight BETWEEN 0 AND 10000
    AND due_urgency_weight BETWEEN 0 AND 10000
    AND proximity_weight BETWEEN 0 AND 10000
    AND interleaving_weight BETWEEN 0 AND 10000
    AND congestion_penalty_weight BETWEEN 0 AND 10000
    AND bottleneck_penalty_weight BETWEEN 0 AND 10000),
  CHECK (mode='disabled' OR priority_weight+due_urgency_weight+proximity_weight
    +interleaving_weight+congestion_penalty_weight+bottleneck_penalty_weight>0),
  CHECK (due_horizon_minutes BETWEEN 1 AND 10080),
  CHECK (max_candidates BETWEEN 1 AND 500),
  CHECK ((revision=1 AND supersedes_policy_id IS NULL)
    OR (revision>1 AND supersedes_policy_id IS NOT NULL)),
  CHECK (effective_from>=configured_at),
  CHECK (effective_to IS NULL OR effective_to>effective_from),
  FOREIGN KEY (tenant_id,facility_id)
    REFERENCES public.facilities(tenant_id,id),
  FOREIGN KEY (tenant_id,inventory_owner_id,facility_id)
    REFERENCES public.inventory_owner_facilities(tenant_id,inventory_owner_id,facility_id),
  FOREIGN KEY (tenant_id,supersedes_policy_id)
    REFERENCES public.work_orchestration_policies(tenant_id,id),
  FOREIGN KEY (tenant_id,configured_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id)
);
CREATE UNIQUE INDEX work_orchestration_facility_default_active_key
ON public.work_orchestration_policies(tenant_id,facility_id)
WHERE inventory_owner_id IS NULL AND effective_to IS NULL;
CREATE UNIQUE INDEX work_orchestration_owner_active_key
ON public.work_orchestration_policies(tenant_id,facility_id,inventory_owner_id)
WHERE inventory_owner_id IS NOT NULL AND effective_to IS NULL;
CREATE UNIQUE INDEX work_orchestration_facility_default_revision_key
ON public.work_orchestration_policies(tenant_id,facility_id,revision)
WHERE inventory_owner_id IS NULL;
CREATE UNIQUE INDEX work_orchestration_owner_revision_key
ON public.work_orchestration_policies(tenant_id,facility_id,inventory_owner_id,revision)
WHERE inventory_owner_id IS NOT NULL;
CREATE INDEX work_orchestration_policies_page_idx
ON public.work_orchestration_policies(tenant_id,configured_at DESC,id DESC);

CREATE TABLE public.work_orchestration_zone_signals (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  storage_zone_id bigint NOT NULL,
  storage_zone_code text NOT NULL,
  congestion_basis_points bigint NOT NULL,
  queue_depth bigint NOT NULL,
  ttl_seconds bigint NOT NULL,
  recorded_by_user_id bigint NOT NULL,
  observed_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL,
  UNIQUE (tenant_id,id),
  CHECK (storage_zone_code=upper(btrim(storage_zone_code))
    AND storage_zone_code<>'' AND char_length(storage_zone_code)<=32),
  CHECK (congestion_basis_points BETWEEN 0 AND 10000),
  CHECK (queue_depth>=0),
  CHECK (ttl_seconds BETWEEN 1 AND 86400),
  CHECK (expires_at=observed_at+make_interval(secs=>ttl_seconds::double precision)),
  FOREIGN KEY (tenant_id,facility_id,storage_zone_id)
    REFERENCES public.storage_zones(tenant_id,facility_id,id),
  FOREIGN KEY (tenant_id,recorded_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id)
);
CREATE INDEX work_orchestration_zone_signals_current_idx
ON public.work_orchestration_zone_signals(
  tenant_id,facility_id,storage_zone_id,observed_at DESC,id DESC);

CREATE TABLE public.work_orchestration_resource_signals (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  resource_kind text NOT NULL,
  available_units bigint NOT NULL,
  demand_units bigint NOT NULL,
  utilization_basis_points bigint NOT NULL,
  ttl_seconds bigint NOT NULL,
  recorded_by_user_id bigint NOT NULL,
  observed_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL,
  UNIQUE (tenant_id,id),
  CHECK (resource_kind IN ('general_labor','inventory_control','material_handling',
    'dock_door','pack_station','automation')),
  CHECK (available_units>=0 AND demand_units>=0),
  CHECK (utilization_basis_points BETWEEN 0 AND 10000),
  CHECK (ttl_seconds BETWEEN 1 AND 86400),
  CHECK (expires_at=observed_at+make_interval(secs=>ttl_seconds::double precision)),
  FOREIGN KEY (tenant_id,facility_id)
    REFERENCES public.facilities(tenant_id,id),
  FOREIGN KEY (tenant_id,recorded_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id)
);
CREATE INDEX work_orchestration_resource_signals_current_idx
ON public.work_orchestration_resource_signals(
  tenant_id,facility_id,resource_kind,observed_at DESC,id DESC);

CREATE TABLE public.work_orchestration_plans (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  requested_inventory_owner_id bigint,
  current_location_id bigint NOT NULL,
  current_location_label text NOT NULL,
  previous_work_kind text,
  generated_for_user_id bigint,
  policy_id bigint NOT NULL,
  policy_revision bigint NOT NULL,
  policy_inventory_owner_id bigint,
  plan_mode text NOT NULL,
  input_snapshot_at timestamptz NOT NULL,
  configuration_snapshot jsonb NOT NULL,
  candidate_count bigint NOT NULL,
  item_count bigint NOT NULL,
  generated_by_user_id bigint NOT NULL,
  generated_at timestamptz NOT NULL,
  UNIQUE (tenant_id,id),
  UNIQUE (tenant_id,facility_id,id),
  CHECK (current_location_label=btrim(current_location_label)
    AND current_location_label<>'' AND char_length(current_location_label)<=200),
  CHECK (previous_work_kind IS NULL OR previous_work_kind IN (
    'cycle_count_item_location','cycle_count_location','putaway',
    'license_plate_putaway','inventory_relocation','replenishment','cross_dock')),
  CHECK (policy_revision>0),
  CHECK (plan_mode IN ('optimized','manual_fifo')),
  CHECK (input_snapshot_at=generated_at),
  CHECK (jsonb_typeof(configuration_snapshot)='object'),
  CHECK (candidate_count>=0 AND item_count>=0
    AND item_count=candidate_count AND item_count<=500),
  FOREIGN KEY (tenant_id,facility_id)
    REFERENCES public.facilities(tenant_id,id),
  FOREIGN KEY (tenant_id,requested_inventory_owner_id,facility_id)
    REFERENCES public.inventory_owner_facilities(tenant_id,inventory_owner_id,facility_id),
  FOREIGN KEY (tenant_id,current_location_id)
    REFERENCES public.locations(tenant_id,id),
  FOREIGN KEY (tenant_id,policy_id)
    REFERENCES public.work_orchestration_policies(tenant_id,id),
  FOREIGN KEY (tenant_id,generated_for_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  FOREIGN KEY (tenant_id,generated_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id)
);
CREATE INDEX work_orchestration_plans_page_idx
ON public.work_orchestration_plans(tenant_id,generated_at DESC,id DESC);
CREATE INDEX work_orchestration_plans_scope_page_idx
ON public.work_orchestration_plans(
  tenant_id,facility_id,requested_inventory_owner_id,generated_at DESC,id DESC);

CREATE TABLE public.work_orchestration_plan_items (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  plan_id bigint NOT NULL,
  sequence bigint NOT NULL,
  work_task_id bigint NOT NULL,
  work_kind text NOT NULL,
  inventory_owner_id bigint,
  title text NOT NULL,
  instructions text,
  task_status text NOT NULL,
  task_created_at timestamptz NOT NULL,
  source_location_id bigint NOT NULL,
  source_location_label text NOT NULL,
  destination_location_id bigint,
  destination_location_label text,
  task_priority bigint NOT NULL,
  due_at timestamptz,
  overdue_seconds bigint NOT NULL,
  due_urgency_basis_points bigint NOT NULL,
  current_location_id bigint NOT NULL,
  current_travel_sequence bigint NOT NULL,
  source_travel_sequence bigint NOT NULL,
  destination_travel_sequence bigint,
  travel_distance bigint NOT NULL,
  proximity_basis_points bigint NOT NULL,
  previous_work_kind text,
  interleaving_compatible boolean NOT NULL,
  source_zone_id bigint,
  source_zone_code text,
  zone_signal_id bigint,
  congestion_basis_points bigint NOT NULL,
  congestion_queue_depth bigint NOT NULL,
  resource_kind text NOT NULL,
  resource_signal_id bigint,
  resource_available_units bigint NOT NULL,
  resource_demand_units bigint NOT NULL,
  resource_utilization_basis_points bigint NOT NULL,
  priority_score bigint NOT NULL,
  due_urgency_score bigint NOT NULL,
  proximity_score bigint NOT NULL,
  interleaving_score bigint NOT NULL,
  congestion_penalty bigint NOT NULL,
  bottleneck_penalty bigint NOT NULL,
  total_score bigint NOT NULL,
  UNIQUE (tenant_id,id),
  UNIQUE (tenant_id,plan_id,sequence),
  UNIQUE (tenant_id,plan_id,work_task_id),
  CHECK (sequence BETWEEN 1 AND 500),
  CHECK (work_kind IN ('cycle_count_item_location','cycle_count_location','putaway',
    'license_plate_putaway','inventory_relocation','replenishment','cross_dock')),
  CHECK (title=btrim(title) AND title<>'' AND char_length(title)<=500),
  CHECK (instructions IS NULL OR char_length(instructions)<=2000),
  CHECK (task_status='open'),
  CHECK (source_location_label=btrim(source_location_label)
    AND source_location_label<>'' AND char_length(source_location_label)<=200),
  CHECK ((destination_location_id IS NULL AND destination_location_label IS NULL)
    OR (destination_location_id IS NOT NULL AND destination_location_id<>source_location_id
      AND destination_location_label=btrim(destination_location_label)
      AND destination_location_label<>'' AND char_length(destination_location_label)<=200)),
  CHECK (task_priority>=0 AND overdue_seconds>=0),
  CHECK (due_urgency_basis_points BETWEEN 0 AND 10000
    AND proximity_basis_points BETWEEN 0 AND 10000
    AND congestion_basis_points BETWEEN 0 AND 10000
    AND resource_utilization_basis_points BETWEEN 0 AND 10000),
  CHECK (travel_distance>=0 AND congestion_queue_depth>=0
    AND resource_available_units>=0 AND resource_demand_units>=0),
  CHECK (previous_work_kind IS NULL OR previous_work_kind IN (
    'cycle_count_item_location','cycle_count_location','putaway',
    'license_plate_putaway','inventory_relocation','replenishment','cross_dock')),
  CHECK (source_zone_code IS NULL OR source_zone_code=upper(btrim(source_zone_code))),
  CHECK (resource_kind IN ('general_labor','inventory_control','material_handling',
    'dock_door','pack_station','automation')),
  CHECK (priority_score>=0 AND due_urgency_score>=0 AND proximity_score>=0
    AND interleaving_score>=0 AND congestion_penalty>=0 AND bottleneck_penalty>=0),
  CHECK (total_score=priority_score+due_urgency_score+proximity_score
    +interleaving_score-congestion_penalty-bottleneck_penalty),
  FOREIGN KEY (tenant_id,facility_id,plan_id)
    REFERENCES public.work_orchestration_plans(tenant_id,facility_id,id),
  FOREIGN KEY (tenant_id,work_task_id)
    REFERENCES public.work_tasks(tenant_id,id),
  FOREIGN KEY (tenant_id,inventory_owner_id,facility_id)
    REFERENCES public.inventory_owner_facilities(tenant_id,inventory_owner_id,facility_id),
  FOREIGN KEY (tenant_id,facility_id,source_location_id)
    REFERENCES public.locations(tenant_id,facility_id,id),
  FOREIGN KEY (tenant_id,facility_id,destination_location_id)
    REFERENCES public.locations(tenant_id,facility_id,id),
  FOREIGN KEY (tenant_id,facility_id,current_location_id)
    REFERENCES public.locations(tenant_id,facility_id,id),
  FOREIGN KEY (tenant_id,facility_id,source_zone_id)
    REFERENCES public.storage_zones(tenant_id,facility_id,id),
  FOREIGN KEY (tenant_id,zone_signal_id)
    REFERENCES public.work_orchestration_zone_signals(tenant_id,id),
  FOREIGN KEY (tenant_id,resource_signal_id)
    REFERENCES public.work_orchestration_resource_signals(tenant_id,id)
);
CREATE INDEX work_orchestration_plan_items_plan_idx
ON public.work_orchestration_plan_items(tenant_id,plan_id,sequence);
CREATE INDEX work_orchestration_plan_items_task_idx
ON public.work_orchestration_plan_items(tenant_id,work_task_id);

CREATE FUNCTION public.validate_work_orchestration_policy_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE predecessor public.work_orchestration_policies%ROWTYPE;
BEGIN
  IF NEW.configured_by_user_id IS DISTINCT FROM
      NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint
    OR NOT public.slotting_user_has_supervisor_permission(
      NEW.tenant_id,NEW.configured_by_user_id)
    OR NEW.configured_at<transaction_timestamp()-INTERVAL '5 minutes'
    OR NEW.configured_at>clock_timestamp()+INTERVAL '1 minute'
    OR NEW.effective_from<>NEW.configured_at THEN
    RAISE EXCEPTION 'invalid work orchestration policy actor or time'
      USING ERRCODE='23514';
  END IF;
  IF NEW.revision=1 THEN
    IF NEW.supersedes_policy_id IS NOT NULL OR EXISTS(
      SELECT 1 FROM public.work_orchestration_policies policy
      WHERE policy.tenant_id=NEW.tenant_id AND policy.facility_id=NEW.facility_id
        AND policy.inventory_owner_id IS NOT DISTINCT FROM NEW.inventory_owner_id) THEN
      RAISE EXCEPTION 'invalid initial work orchestration policy' USING ERRCODE='23514';
    END IF;
  ELSE
    SELECT * INTO predecessor FROM public.work_orchestration_policies policy
    WHERE policy.tenant_id=NEW.tenant_id AND policy.id=NEW.supersedes_policy_id;
    IF NOT FOUND OR predecessor.facility_id<>NEW.facility_id
      OR predecessor.inventory_owner_id IS DISTINCT FROM NEW.inventory_owner_id
      OR predecessor.revision<>NEW.revision-1
      OR predecessor.effective_to IS DISTINCT FROM NEW.effective_from THEN
      RAISE EXCEPTION 'invalid work orchestration policy predecessor' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.guard_work_orchestration_policy_mutation() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
BEGIN
  IF TG_OP='DELETE' OR NEW.id<>OLD.id OR NEW.tenant_id<>OLD.tenant_id
    OR NEW.facility_id<>OLD.facility_id
    OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
    OR NEW.mode<>OLD.mode OR NEW.priority_weight<>OLD.priority_weight
    OR NEW.due_urgency_weight<>OLD.due_urgency_weight
    OR NEW.proximity_weight<>OLD.proximity_weight
    OR NEW.interleaving_weight<>OLD.interleaving_weight
    OR NEW.congestion_penalty_weight<>OLD.congestion_penalty_weight
    OR NEW.bottleneck_penalty_weight<>OLD.bottleneck_penalty_weight
    OR NEW.due_horizon_minutes<>OLD.due_horizon_minutes
    OR NEW.max_candidates<>OLD.max_candidates OR NEW.revision<>OLD.revision
    OR NEW.supersedes_policy_id IS DISTINCT FROM OLD.supersedes_policy_id
    OR NEW.effective_from<>OLD.effective_from
    OR NEW.configured_by_user_id<>OLD.configured_by_user_id
    OR NEW.configured_at<>OLD.configured_at OR OLD.effective_to IS NOT NULL
    OR NEW.effective_to IS NULL OR NEW.effective_to<=OLD.effective_from
    OR NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint IS NULL
    OR NOT public.slotting_user_has_supervisor_permission(
      OLD.tenant_id,NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint) THEN
    RAISE EXCEPTION 'work orchestration policies are immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.require_work_orchestration_policy_successor() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM public.work_orchestration_policies successor
    WHERE successor.tenant_id=NEW.tenant_id
      AND successor.supersedes_policy_id=NEW.id
      AND successor.facility_id=NEW.facility_id
      AND successor.inventory_owner_id IS NOT DISTINCT FROM NEW.inventory_owner_id
      AND successor.revision=NEW.revision+1
      AND successor.effective_from=NEW.effective_to) THEN
    RAISE EXCEPTION 'closed work orchestration policy requires exact successor'
      USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;

CREATE FUNCTION public.validate_work_orchestration_zone_signal() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
BEGIN
  IF NEW.recorded_by_user_id IS DISTINCT FROM
      NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint
    OR NOT public.slotting_user_has_supervisor_permission(
      NEW.tenant_id,NEW.recorded_by_user_id)
    OR NEW.observed_at<transaction_timestamp()-INTERVAL '5 minutes'
    OR NEW.observed_at>clock_timestamp()+INTERVAL '1 minute'
    OR NOT EXISTS(SELECT 1 FROM public.storage_zones zone
      WHERE zone.tenant_id=NEW.tenant_id AND zone.facility_id=NEW.facility_id
        AND zone.id=NEW.storage_zone_id AND zone.effective_to IS NULL
        AND zone.code=NEW.storage_zone_code) THEN
    RAISE EXCEPTION 'invalid work orchestration zone signal' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.validate_work_orchestration_resource_signal() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE expected_utilization bigint;
BEGIN
  expected_utilization:=CASE WHEN NEW.demand_units=0 THEN 0
    WHEN NEW.available_units=0 THEN 10000
    ELSE LEAST(10000,trunc(
      (NEW.demand_units::numeric*10000)/NEW.available_units::numeric)::bigint) END;
  IF NEW.recorded_by_user_id IS DISTINCT FROM
      NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint
    OR NOT public.slotting_user_has_supervisor_permission(
      NEW.tenant_id,NEW.recorded_by_user_id)
    OR NEW.observed_at<transaction_timestamp()-INTERVAL '5 minutes'
    OR NEW.observed_at>clock_timestamp()+INTERVAL '1 minute'
    OR NEW.utilization_basis_points<>expected_utilization THEN
    RAISE EXCEPTION 'invalid work orchestration resource signal' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.work_orchestration_user_has_permission(
  checked_tenant_id bigint,checked_user_id bigint,checked_permission text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
  WITH RECURSIVE granted_roles AS (
    SELECT role.id,role.parent_id
    FROM public.tenant_memberships membership
    JOIN public.user_roles user_role ON user_role.tenant_id=membership.tenant_id
      AND user_role.user_id=membership.user_id AND user_role.deleted IS NULL
    JOIN public.roles role ON role.tenant_id=user_role.tenant_id
      AND role.id=user_role.role_id AND role.deleted IS NULL
    WHERE membership.tenant_id=checked_tenant_id
      AND membership.user_id=checked_user_id AND membership.deleted IS NULL
    UNION
    SELECT parent.id,parent.parent_id
    FROM granted_roles child
    JOIN public.roles parent ON parent.tenant_id=checked_tenant_id
      AND parent.id=child.parent_id AND parent.deleted IS NULL
  )
  SELECT EXISTS(
    SELECT 1 FROM granted_roles role
    JOIN public.role_permissions role_permission
      ON role_permission.tenant_id=checked_tenant_id
      AND role_permission.role_id=role.id AND role_permission.deleted IS NULL
    JOIN public.permissions permission
      ON permission.tenant_id=role_permission.tenant_id
      AND permission.id=role_permission.permission_id AND permission.deleted IS NULL
    WHERE upper(permission.name) IN ('ADMIN',upper(checked_permission))
  )
$$;

CREATE FUNCTION public.reject_work_orchestration_immutable_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$ BEGIN
  RAISE EXCEPTION '% is immutable',TG_TABLE_NAME USING ERRCODE='23514';
END $$;

CREATE FUNCTION public.validate_work_orchestration_plan_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE policy public.work_orchestration_policies%ROWTYPE;
BEGIN
  SELECT * INTO policy FROM public.work_orchestration_policies candidate
  WHERE candidate.tenant_id=NEW.tenant_id AND candidate.id=NEW.policy_id;
  IF NOT FOUND OR policy.facility_id<>NEW.facility_id
    OR policy.inventory_owner_id IS DISTINCT FROM NEW.policy_inventory_owner_id
    OR NOT ((NEW.requested_inventory_owner_id IS NULL
        AND policy.inventory_owner_id IS NULL)
      OR (NEW.requested_inventory_owner_id IS NOT NULL
        AND (policy.inventory_owner_id=NEW.requested_inventory_owner_id
          OR policy.inventory_owner_id IS NULL)))
    OR policy.revision<>NEW.policy_revision OR policy.effective_to IS NOT NULL
    OR NEW.item_count>policy.max_candidates
    OR NEW.configuration_snapshot<>to_jsonb(policy)
    OR NEW.plan_mode<>(CASE WHEN policy.mode='enabled'
      THEN 'optimized' ELSE 'manual_fifo' END)
    OR NEW.generated_by_user_id IS DISTINCT FROM
      NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint
    OR NOT public.slotting_user_has_supervisor_permission(
      NEW.tenant_id,NEW.generated_by_user_id)
    OR (NEW.generated_for_user_id IS NOT NULL AND NOT EXISTS(
      SELECT 1 FROM public.employees employee
      JOIN public.employee_facilities assignment
        ON assignment.tenant_id=employee.tenant_id
        AND assignment.employee_id=employee.id
        AND assignment.facility_id=NEW.facility_id
        AND assignment.deleted IS NULL
      JOIN public.tenant_memberships membership
        ON membership.tenant_id=employee.tenant_id
        AND membership.user_id=employee.user_id AND membership.deleted IS NULL
      WHERE employee.tenant_id=NEW.tenant_id
        AND employee.user_id=NEW.generated_for_user_id
        AND employee.deleted IS NULL AND employee.hired<=NEW.generated_at
        AND (employee.terminated IS NULL OR employee.terminated>NEW.generated_at)
        AND (membership.all_facilities OR EXISTS(
          SELECT 1 FROM public.user_facilities user_facility
          WHERE user_facility.tenant_id=membership.tenant_id
            AND user_facility.user_id=membership.user_id
            AND user_facility.facility_id=NEW.facility_id
            AND user_facility.deleted IS NULL))
        AND (NEW.requested_inventory_owner_id IS NULL
          OR membership.all_inventory_owners OR EXISTS(
            SELECT 1 FROM public.user_inventory_owners user_owner
            WHERE user_owner.tenant_id=membership.tenant_id
              AND user_owner.user_id=membership.user_id
              AND user_owner.inventory_owner_id=NEW.requested_inventory_owner_id
              AND user_owner.deleted IS NULL))
        AND public.work_orchestration_user_has_permission(
          NEW.tenant_id,NEW.generated_for_user_id,'wms')))
    OR NEW.generated_at<transaction_timestamp()-INTERVAL '5 minutes'
    OR NEW.generated_at>clock_timestamp()+INTERVAL '1 minute'
    OR NOT EXISTS(SELECT 1 FROM public.locations location
      WHERE location.tenant_id=NEW.tenant_id AND location.facility_id=NEW.facility_id
        AND location.id=NEW.current_location_id AND location.deleted IS NULL
        AND location.active
        AND COALESCE(NULLIF(location.name,''),location.barcode,
          'Location #'||location.id::text)=NEW.current_location_label) THEN
    RAISE EXCEPTION 'invalid work orchestration plan' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.validate_work_orchestration_plan_item() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE plan public.work_orchestration_plans%ROWTYPE;
DECLARE priority_weight bigint; due_weight bigint; proximity_weight bigint;
DECLARE interleave_weight bigint; congestion_weight bigint; bottleneck_weight bigint;
DECLARE expected_interleave boolean;
DECLARE horizon_seconds bigint; expected_overdue bigint; expected_due_urgency bigint;
DECLARE expected_distance bigint; expected_proximity bigint;
DECLARE plan_found boolean; expected_current_sequence bigint;
DECLARE expected_source_zone_id bigint; expected_source_zone_code text;
DECLARE expected_source_sequence bigint; expected_destination_sequence bigint;
DECLARE expected_zone_signal_id bigint; expected_resource_signal_id bigint;
BEGIN
  SELECT * INTO plan FROM public.work_orchestration_plans candidate
  WHERE candidate.tenant_id=NEW.tenant_id AND candidate.id=NEW.plan_id;
  plan_found:=FOUND;
  priority_weight:=(plan.configuration_snapshot->>'priority_weight')::bigint;
  due_weight:=(plan.configuration_snapshot->>'due_urgency_weight')::bigint;
  proximity_weight:=(plan.configuration_snapshot->>'proximity_weight')::bigint;
  interleave_weight:=(plan.configuration_snapshot->>'interleaving_weight')::bigint;
  congestion_weight:=(plan.configuration_snapshot->>'congestion_penalty_weight')::bigint;
  bottleneck_weight:=(plan.configuration_snapshot->>'bottleneck_penalty_weight')::bigint;
  expected_interleave:=CASE
    WHEN NEW.previous_work_kind IN ('putaway','license_plate_putaway','cross_dock')
      AND NEW.work_kind IN ('inventory_relocation','replenishment') THEN true
    WHEN NEW.previous_work_kind IN ('inventory_relocation','replenishment')
      AND NEW.work_kind IN ('putaway','license_plate_putaway','cross_dock') THEN true
    ELSE false END;
  horizon_seconds:=(plan.configuration_snapshot->>'due_horizon_minutes')::bigint*60;
  expected_overdue:=CASE WHEN NEW.due_at IS NOT NULL
      AND NEW.due_at<=plan.input_snapshot_at
    THEN trunc(EXTRACT(EPOCH FROM plan.input_snapshot_at-NEW.due_at))::bigint
    ELSE 0 END;
  expected_due_urgency:=CASE
    WHEN NEW.due_at IS NULL THEN 0
    WHEN NEW.due_at<=plan.input_snapshot_at THEN 10000
    WHEN trunc(EXTRACT(EPOCH FROM NEW.due_at-plan.input_snapshot_at))::bigint
        >=horizon_seconds THEN 0
    ELSE ((horizon_seconds-
      trunc(EXTRACT(EPOCH FROM NEW.due_at-plan.input_snapshot_at))::bigint)*10000)
      /horizon_seconds END;
  expected_distance:=abs(NEW.current_travel_sequence-NEW.source_travel_sequence);
  expected_proximity:=GREATEST(0,10000-LEAST(expected_distance,10000));
  SELECT COALESCE(path.travel_sequence,0)::bigint
    INTO expected_current_sequence
  FROM public.locations location
  LEFT JOIN LATERAL (
    SELECT zone.travel_sequence*1000000+member.location_sequence AS travel_sequence
    FROM public.storage_zone_locations member
    JOIN public.storage_zones zone ON zone.tenant_id=member.tenant_id
      AND zone.facility_id=member.facility_id AND zone.id=member.storage_zone_id
      AND zone.effective_to IS NULL
    WHERE member.tenant_id=location.tenant_id
      AND member.facility_id=location.facility_id AND member.location_id=location.id
    ORDER BY zone.travel_sequence,member.location_sequence,zone.id LIMIT 1
  ) path ON true
  WHERE location.tenant_id=NEW.tenant_id AND location.facility_id=NEW.facility_id
    AND location.id=NEW.current_location_id AND location.deleted IS NULL AND location.active;
  SELECT path.storage_zone_id,path.storage_zone_code,
      COALESCE(path.travel_sequence,0)::bigint
    INTO expected_source_zone_id,expected_source_zone_code,expected_source_sequence
  FROM public.locations location
  LEFT JOIN LATERAL (
    SELECT zone.id AS storage_zone_id,zone.code AS storage_zone_code,
      zone.travel_sequence*1000000+member.location_sequence AS travel_sequence
    FROM public.storage_zone_locations member
    JOIN public.storage_zones zone ON zone.tenant_id=member.tenant_id
      AND zone.facility_id=member.facility_id AND zone.id=member.storage_zone_id
      AND zone.effective_to IS NULL
    WHERE member.tenant_id=location.tenant_id
      AND member.facility_id=location.facility_id AND member.location_id=location.id
    ORDER BY zone.travel_sequence,member.location_sequence,zone.id LIMIT 1
  ) path ON true
  WHERE location.tenant_id=NEW.tenant_id AND location.facility_id=NEW.facility_id
    AND location.id=NEW.source_location_id AND location.deleted IS NULL AND location.active;
  expected_destination_sequence:=NULL;
  IF NEW.destination_location_id IS NOT NULL THEN
    SELECT path.travel_sequence::bigint INTO expected_destination_sequence
    FROM public.locations location
    LEFT JOIN LATERAL (
      SELECT zone.travel_sequence*1000000+member.location_sequence AS travel_sequence
      FROM public.storage_zone_locations member
      JOIN public.storage_zones zone ON zone.tenant_id=member.tenant_id
        AND zone.facility_id=member.facility_id AND zone.id=member.storage_zone_id
        AND zone.effective_to IS NULL
      WHERE member.tenant_id=location.tenant_id
        AND member.facility_id=location.facility_id AND member.location_id=location.id
      ORDER BY zone.travel_sequence,member.location_sequence,zone.id LIMIT 1
    ) path ON true
    WHERE location.tenant_id=NEW.tenant_id AND location.facility_id=NEW.facility_id
      AND location.id=NEW.destination_location_id
      AND location.deleted IS NULL AND location.active;
  END IF;
  SELECT signal.id INTO expected_zone_signal_id
  FROM public.work_orchestration_zone_signals signal
  WHERE signal.tenant_id=NEW.tenant_id AND signal.facility_id=NEW.facility_id
    AND signal.storage_zone_id=expected_source_zone_id
    AND signal.observed_at<=plan.input_snapshot_at
    AND signal.expires_at>plan.input_snapshot_at
  ORDER BY signal.observed_at DESC,signal.id DESC LIMIT 1;
  SELECT signal.id INTO expected_resource_signal_id
  FROM public.work_orchestration_resource_signals signal
  WHERE signal.tenant_id=NEW.tenant_id AND signal.facility_id=NEW.facility_id
    AND signal.resource_kind=NEW.resource_kind
    AND signal.observed_at<=plan.input_snapshot_at
    AND signal.expires_at>plan.input_snapshot_at
  ORDER BY signal.observed_at DESC,signal.id DESC LIMIT 1;
  IF NOT plan_found OR NEW.facility_id<>plan.facility_id
    OR NEW.inventory_owner_id IS DISTINCT FROM plan.requested_inventory_owner_id
    OR NEW.current_location_id<>plan.current_location_id
    OR NEW.previous_work_kind IS DISTINCT FROM plan.previous_work_kind
    OR NEW.interleaving_compatible<>expected_interleave
    OR NEW.overdue_seconds<>expected_overdue
    OR NEW.due_urgency_basis_points<>expected_due_urgency
    OR NEW.travel_distance<>expected_distance
    OR NEW.proximity_basis_points<>expected_proximity
    OR NEW.current_travel_sequence<>expected_current_sequence
    OR NEW.source_travel_sequence<>expected_source_sequence
    OR NEW.destination_travel_sequence IS DISTINCT FROM expected_destination_sequence
    OR NEW.source_zone_id IS DISTINCT FROM expected_source_zone_id
    OR NEW.source_zone_code IS DISTINCT FROM expected_source_zone_code
    OR NEW.zone_signal_id IS DISTINCT FROM expected_zone_signal_id
    OR NEW.resource_signal_id IS DISTINCT FROM expected_resource_signal_id
    OR NEW.resource_kind<>(CASE WHEN NEW.work_kind IN
      ('cycle_count_item_location','cycle_count_location')
      THEN 'inventory_control' ELSE 'material_handling' END)
    OR (plan.generated_for_user_id IS NOT NULL AND NEW.work_kind='cycle_count_location')
    OR (plan.plan_mode='optimized' AND (
      NEW.priority_score<>LEAST(NEW.task_priority,1000)*10*priority_weight
      OR NEW.due_urgency_score<>NEW.due_urgency_basis_points*due_weight
      OR NEW.proximity_score<>NEW.proximity_basis_points*proximity_weight
      OR NEW.interleaving_score<>(CASE WHEN NEW.interleaving_compatible
        THEN 10000*interleave_weight ELSE 0 END)
      OR NEW.congestion_penalty<>NEW.congestion_basis_points*congestion_weight
      OR NEW.bottleneck_penalty<>
        NEW.resource_utilization_basis_points*bottleneck_weight))
    OR (plan.plan_mode='manual_fifo' AND (
      NEW.priority_score<>0 OR NEW.due_urgency_score<>0 OR NEW.proximity_score<>0
      OR NEW.interleaving_score<>0 OR NEW.congestion_penalty<>0
      OR NEW.bottleneck_penalty<>0 OR NEW.total_score<>0))
    OR NOT EXISTS(SELECT 1 FROM public.work_tasks task
      WHERE task.tenant_id=NEW.tenant_id AND task.id=NEW.work_task_id
        AND task.facility_id=NEW.facility_id
        AND task.inventory_owner_id IS NOT DISTINCT FROM NEW.inventory_owner_id
        AND task.task_type=NEW.work_kind AND task.status='open' AND task.deleted IS NULL
        AND task.priority=NEW.task_priority AND task.due_at IS NOT DISTINCT FROM NEW.due_at
        AND task.created<=plan.input_snapshot_at
        AND (task.scheduled_for IS NULL OR task.scheduled_for<=plan.input_snapshot_at)
        AND task.created=NEW.task_created_at AND task.title=NEW.title
        AND task.instructions IS NOT DISTINCT FROM NEW.instructions
        AND (plan.generated_for_user_id IS NULL
          OR public.work_orchestration_user_has_permission(
            NEW.tenant_id,plan.generated_for_user_id,task.required_permission)))
    OR NOT (
      (NEW.work_kind='cycle_count_item_location' AND EXISTS(
        SELECT 1 FROM public.cycle_count_item_location_tasks typed
        WHERE typed.tenant_id=NEW.tenant_id AND typed.task_id=NEW.work_task_id
          AND typed.location_id=NEW.source_location_id
          AND NEW.destination_location_id IS NULL))
      OR (NEW.work_kind='cycle_count_location' AND EXISTS(
        SELECT 1 FROM public.cycle_count_location_tasks typed
        WHERE typed.tenant_id=NEW.tenant_id AND typed.task_id=NEW.work_task_id
          AND typed.location_id=NEW.source_location_id
          AND NEW.destination_location_id IS NULL))
      OR (NEW.work_kind='putaway' AND EXISTS(
        SELECT 1 FROM public.putaway_tasks typed
        WHERE typed.tenant_id=NEW.tenant_id AND typed.task_id=NEW.work_task_id
          AND typed.source_location_id=NEW.source_location_id
          AND typed.destination_location_id IS NOT DISTINCT FROM NEW.destination_location_id))
      OR (NEW.work_kind='license_plate_putaway' AND EXISTS(
        SELECT 1 FROM public.license_plate_putaway_tasks typed
        WHERE typed.tenant_id=NEW.tenant_id AND typed.task_id=NEW.work_task_id
          AND typed.source_location_id=NEW.source_location_id
          AND typed.destination_location_id IS NOT DISTINCT FROM NEW.destination_location_id))
      OR (NEW.work_kind='inventory_relocation' AND EXISTS(
        SELECT 1 FROM public.inventory_relocation_tasks typed
        WHERE typed.tenant_id=NEW.tenant_id AND typed.task_id=NEW.work_task_id
          AND typed.source_location_id=NEW.source_location_id
          AND typed.destination_location_id IS NOT DISTINCT FROM NEW.destination_location_id))
      OR (NEW.work_kind='replenishment' AND EXISTS(
        SELECT 1 FROM public.replenishment_tasks typed
        WHERE typed.tenant_id=NEW.tenant_id AND typed.task_id=NEW.work_task_id
          AND typed.source_location_id=NEW.source_location_id
          AND typed.destination_location_id IS NOT DISTINCT FROM NEW.destination_location_id))
      OR (NEW.work_kind='cross_dock' AND EXISTS(
        SELECT 1 FROM public.cross_dock_tasks typed
        WHERE typed.tenant_id=NEW.tenant_id AND typed.task_id=NEW.work_task_id
          AND typed.source_location_id=NEW.source_location_id
          AND typed.destination_location_id IS NOT DISTINCT FROM NEW.destination_location_id)))
    OR NOT EXISTS(SELECT 1 FROM public.locations location
      WHERE location.tenant_id=NEW.tenant_id AND location.facility_id=NEW.facility_id
        AND location.id=NEW.source_location_id AND location.deleted IS NULL
        AND location.active AND COALESCE(NULLIF(location.name,''),location.barcode,
          'Location #'||location.id::text)=NEW.source_location_label)
    OR (NEW.destination_location_id IS NOT NULL AND NOT EXISTS(
      SELECT 1 FROM public.locations location
      WHERE location.tenant_id=NEW.tenant_id AND location.facility_id=NEW.facility_id
        AND location.id=NEW.destination_location_id AND location.deleted IS NULL
        AND location.active AND COALESCE(NULLIF(location.name,''),location.barcode,
          'Location #'||location.id::text)=NEW.destination_location_label))
    OR (NEW.zone_signal_id IS NULL AND (
      NEW.congestion_basis_points<>0 OR NEW.congestion_queue_depth<>0))
    OR (NEW.zone_signal_id IS NOT NULL AND NOT EXISTS(
      SELECT 1 FROM public.work_orchestration_zone_signals signal
      WHERE signal.tenant_id=NEW.tenant_id AND signal.id=NEW.zone_signal_id
        AND signal.facility_id=NEW.facility_id
        AND signal.storage_zone_id=NEW.source_zone_id
        AND signal.storage_zone_code=NEW.source_zone_code
        AND signal.congestion_basis_points=NEW.congestion_basis_points
        AND signal.queue_depth=NEW.congestion_queue_depth
        AND signal.observed_at<=plan.input_snapshot_at
        AND signal.expires_at>plan.input_snapshot_at))
    OR (NEW.resource_signal_id IS NULL AND (
      NEW.resource_available_units<>0 OR NEW.resource_demand_units<>0
      OR NEW.resource_utilization_basis_points<>0))
    OR (NEW.resource_signal_id IS NOT NULL AND NOT EXISTS(
      SELECT 1 FROM public.work_orchestration_resource_signals signal
      WHERE signal.tenant_id=NEW.tenant_id AND signal.id=NEW.resource_signal_id
        AND signal.facility_id=NEW.facility_id AND signal.resource_kind=NEW.resource_kind
        AND signal.available_units=NEW.resource_available_units
        AND signal.demand_units=NEW.resource_demand_units
        AND signal.utilization_basis_points=NEW.resource_utilization_basis_points
        AND signal.observed_at<=plan.input_snapshot_at
        AND signal.expires_at>plan.input_snapshot_at)) THEN
    RAISE EXCEPTION 'invalid work orchestration plan item' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.require_work_orchestration_plan_count() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE checked_tenant bigint; checked_plan bigint; expected_count bigint;
DECLARE actual_count bigint; checked_mode text; plan_found boolean;
BEGIN
  checked_tenant:=NEW.tenant_id;
  IF TG_TABLE_NAME='work_orchestration_plans' THEN
    checked_plan:=NEW.id;
  ELSE
    checked_plan:=NEW.plan_id;
  END IF;
  SELECT plan.item_count,plan.plan_mode INTO expected_count,checked_mode
  FROM public.work_orchestration_plans plan
  WHERE plan.tenant_id=checked_tenant AND plan.id=checked_plan;
  plan_found:=FOUND;
  SELECT count(*) INTO actual_count FROM public.work_orchestration_plan_items item
  WHERE item.tenant_id=checked_tenant AND item.plan_id=checked_plan;
  IF NOT plan_found OR expected_count<>actual_count THEN
    RAISE EXCEPTION 'work orchestration plan item count does not reconcile'
      USING ERRCODE='23514';
  END IF;
  IF EXISTS(SELECT 1 FROM (
      SELECT item.sequence,row_number() OVER (ORDER BY item.sequence) AS expected_sequence
      FROM public.work_orchestration_plan_items item
      WHERE item.tenant_id=checked_tenant AND item.plan_id=checked_plan
    ) sequenced WHERE sequenced.sequence<>sequenced.expected_sequence) THEN
    RAISE EXCEPTION 'work orchestration plan item sequence is not dense'
      USING ERRCODE='23514';
  END IF;
  IF checked_mode='manual_fifo' AND EXISTS(SELECT 1 FROM (
      SELECT item.sequence,row_number() OVER (
        ORDER BY item.task_created_at,item.work_task_id) AS expected_sequence
      FROM public.work_orchestration_plan_items item
      WHERE item.tenant_id=checked_tenant AND item.plan_id=checked_plan
    ) ranked WHERE ranked.sequence<>ranked.expected_sequence) THEN
    RAISE EXCEPTION 'manual work orchestration plan is not FIFO ordered'
      USING ERRCODE='23514';
  END IF;
  IF checked_mode='optimized' AND EXISTS(SELECT 1 FROM (
      SELECT item.sequence,row_number() OVER (
        ORDER BY item.total_score DESC,item.task_priority DESC,
          item.due_at ASC NULLS LAST,item.task_created_at,item.work_task_id) AS expected_sequence
      FROM public.work_orchestration_plan_items item
      WHERE item.tenant_id=checked_tenant AND item.plan_id=checked_plan
    ) ranked WHERE ranked.sequence<>ranked.expected_sequence) THEN
    RAISE EXCEPTION 'optimized work orchestration plan is not score ordered'
      USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;

CREATE TRIGGER work_orchestration_policies_validate BEFORE INSERT
ON public.work_orchestration_policies FOR EACH ROW
EXECUTE FUNCTION public.validate_work_orchestration_policy_insert();
CREATE TRIGGER work_orchestration_policies_guard BEFORE UPDATE OR DELETE
ON public.work_orchestration_policies FOR EACH ROW
EXECUTE FUNCTION public.guard_work_orchestration_policy_mutation();
CREATE CONSTRAINT TRIGGER work_orchestration_policies_successor
AFTER UPDATE OF effective_to ON public.work_orchestration_policies
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
EXECUTE FUNCTION public.require_work_orchestration_policy_successor();
CREATE TRIGGER work_orchestration_zone_signals_validate BEFORE INSERT
ON public.work_orchestration_zone_signals FOR EACH ROW
EXECUTE FUNCTION public.validate_work_orchestration_zone_signal();
CREATE TRIGGER work_orchestration_zone_signals_immutable BEFORE UPDATE OR DELETE
ON public.work_orchestration_zone_signals FOR EACH ROW
EXECUTE FUNCTION public.reject_work_orchestration_immutable_mutation();
CREATE TRIGGER work_orchestration_resource_signals_validate BEFORE INSERT
ON public.work_orchestration_resource_signals FOR EACH ROW
EXECUTE FUNCTION public.validate_work_orchestration_resource_signal();
CREATE TRIGGER work_orchestration_resource_signals_immutable BEFORE UPDATE OR DELETE
ON public.work_orchestration_resource_signals FOR EACH ROW
EXECUTE FUNCTION public.reject_work_orchestration_immutable_mutation();
CREATE TRIGGER work_orchestration_plans_validate BEFORE INSERT
ON public.work_orchestration_plans FOR EACH ROW
EXECUTE FUNCTION public.validate_work_orchestration_plan_insert();
CREATE TRIGGER work_orchestration_plans_immutable BEFORE UPDATE OR DELETE
ON public.work_orchestration_plans FOR EACH ROW
EXECUTE FUNCTION public.reject_work_orchestration_immutable_mutation();
CREATE TRIGGER work_orchestration_plan_items_validate BEFORE INSERT
ON public.work_orchestration_plan_items FOR EACH ROW
EXECUTE FUNCTION public.validate_work_orchestration_plan_item();
CREATE TRIGGER work_orchestration_plan_items_immutable BEFORE UPDATE OR DELETE
ON public.work_orchestration_plan_items FOR EACH ROW
EXECUTE FUNCTION public.reject_work_orchestration_immutable_mutation();
CREATE CONSTRAINT TRIGGER work_orchestration_plans_item_count
AFTER INSERT ON public.work_orchestration_plans DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_work_orchestration_plan_count();
CREATE CONSTRAINT TRIGGER work_orchestration_items_plan_count
AFTER INSERT ON public.work_orchestration_plan_items DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_work_orchestration_plan_count();

ALTER TABLE public.work_orchestration_policies ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.work_orchestration_policies FORCE ROW LEVEL SECURITY;
CREATE POLICY work_orchestration_policies_tenant_isolation
ON public.work_orchestration_policies
USING (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint)
WITH CHECK (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint);
ALTER TABLE public.work_orchestration_zone_signals ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.work_orchestration_zone_signals FORCE ROW LEVEL SECURITY;
CREATE POLICY work_orchestration_zone_signals_tenant_isolation
ON public.work_orchestration_zone_signals
USING (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint)
WITH CHECK (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint);
ALTER TABLE public.work_orchestration_resource_signals ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.work_orchestration_resource_signals FORCE ROW LEVEL SECURITY;
CREATE POLICY work_orchestration_resource_signals_tenant_isolation
ON public.work_orchestration_resource_signals
USING (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint)
WITH CHECK (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint);
ALTER TABLE public.work_orchestration_plans ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.work_orchestration_plans FORCE ROW LEVEL SECURITY;
CREATE POLICY work_orchestration_plans_tenant_isolation ON public.work_orchestration_plans
USING (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint)
WITH CHECK (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint);
ALTER TABLE public.work_orchestration_plan_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.work_orchestration_plan_items FORCE ROW LEVEL SECURITY;
CREATE POLICY work_orchestration_plan_items_tenant_isolation
ON public.work_orchestration_plan_items
USING (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint)
WITH CHECK (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint);

GRANT SELECT,INSERT ON public.work_orchestration_policies TO wareboxes_app;
GRANT UPDATE(effective_to) ON public.work_orchestration_policies TO wareboxes_app;
GRANT SELECT,INSERT ON public.work_orchestration_zone_signals TO wareboxes_app;
GRANT SELECT,INSERT ON public.work_orchestration_resource_signals TO wareboxes_app;
GRANT SELECT,INSERT ON public.work_orchestration_plans TO wareboxes_app;
GRANT SELECT,INSERT ON public.work_orchestration_plan_items TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.work_orchestration_policies_id_seq TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.work_orchestration_zone_signals_id_seq TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.work_orchestration_resource_signals_id_seq TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.work_orchestration_plans_id_seq TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.work_orchestration_plan_items_id_seq TO wareboxes_app;
REVOKE ALL ON FUNCTION public.validate_work_orchestration_policy_insert() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_work_orchestration_policy_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_work_orchestration_policy_successor() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_work_orchestration_zone_signal() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_work_orchestration_resource_signal() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.work_orchestration_user_has_permission(bigint,bigint,text)
FROM PUBLIC;
REVOKE ALL ON FUNCTION public.reject_work_orchestration_immutable_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_work_orchestration_plan_insert() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_work_orchestration_plan_item() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_work_orchestration_plan_count() FROM PUBLIC;

-- Distinct integration service accounts, scoped credentials, and immutable lifecycle evidence.

CREATE TABLE public.service_accounts (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  principal_user_id bigint NOT NULL,
  name text NOT NULL,
  description text,
  status text NOT NULL DEFAULT 'active',
  revision bigint NOT NULL DEFAULT 1,
  all_facilities boolean NOT NULL,
  all_inventory_owners boolean NOT NULL,
  created_at timestamptz NOT NULL,
  created_by_user_id bigint NOT NULL,
  updated_at timestamptz NOT NULL,
  updated_by_user_id bigint NOT NULL,
  disabled_at timestamptz,
  disabled_by_user_id bigint,
  disabled_reason text,
  last_used_at timestamptz,
  CONSTRAINT service_accounts_scope_id_unique UNIQUE(tenant_id,id),
  CONSTRAINT service_accounts_subject_unique UNIQUE(principal_user_id),
  CONSTRAINT service_accounts_tenant_fkey FOREIGN KEY(tenant_id)
    REFERENCES public.tenants(id),
  CONSTRAINT service_accounts_subject_fkey FOREIGN KEY(tenant_id,principal_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  CONSTRAINT service_accounts_created_by_fkey FOREIGN KEY(tenant_id,created_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  CONSTRAINT service_accounts_updated_by_fkey FOREIGN KEY(tenant_id,updated_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  CONSTRAINT service_accounts_disabled_by_fkey FOREIGN KEY(tenant_id,disabled_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  CONSTRAINT service_accounts_name_check CHECK (
    name=btrim(name) AND name<>'' AND char_length(name)<=120 AND name!~'[[:cntrl:]]'),
  CONSTRAINT service_accounts_description_check CHECK (description IS NULL OR (
    description=btrim(description) AND description<>'' AND char_length(description)<=500
    AND description!~'[[:cntrl:]]')),
  CONSTRAINT service_accounts_status_check CHECK(status IN ('active','disabled')),
  CONSTRAINT service_accounts_revision_check CHECK(revision>0),
  CONSTRAINT service_accounts_timestamps_check CHECK(updated_at>=created_at),
  CONSTRAINT service_accounts_disabled_check CHECK(
    (status='active' AND disabled_at IS NULL AND disabled_by_user_id IS NULL
      AND disabled_reason IS NULL)
    OR (status='disabled' AND disabled_at IS NOT NULL AND disabled_by_user_id IS NOT NULL
      AND disabled_reason IS NOT NULL)),
  CONSTRAINT service_accounts_disabled_reason_check CHECK(disabled_reason IS NULL OR (
    disabled_reason=btrim(disabled_reason) AND disabled_reason<>''
    AND char_length(disabled_reason)<=500 AND disabled_reason!~'[[:cntrl:]]'))
);
CREATE UNIQUE INDEX service_accounts_tenant_name_unique
ON public.service_accounts(tenant_id,lower(name));

CREATE TABLE public.service_account_facilities (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  service_account_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  granted_at timestamptz NOT NULL,
  granted_by_user_id bigint NOT NULL,
  revoked_at timestamptz,
  revoked_by_user_id bigint,
  CONSTRAINT service_account_facilities_account_fkey
    FOREIGN KEY(tenant_id,service_account_id)
    REFERENCES public.service_accounts(tenant_id,id),
  CONSTRAINT service_account_facilities_facility_fkey FOREIGN KEY(tenant_id,facility_id)
    REFERENCES public.facilities(tenant_id,id),
  CONSTRAINT service_account_facilities_granted_by_fkey
    FOREIGN KEY(tenant_id,granted_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  CONSTRAINT service_account_facilities_revoked_by_fkey
    FOREIGN KEY(tenant_id,revoked_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  CONSTRAINT service_account_facilities_revocation_check CHECK(
    (revoked_at IS NULL)=(revoked_by_user_id IS NULL) AND
    (revoked_at IS NULL OR revoked_at>=granted_at))
);
CREATE UNIQUE INDEX service_account_facilities_active_unique
ON public.service_account_facilities(tenant_id,service_account_id,facility_id)
WHERE revoked_at IS NULL;

CREATE TABLE public.service_account_inventory_owners (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  service_account_id bigint NOT NULL,
  inventory_owner_id bigint NOT NULL,
  granted_at timestamptz NOT NULL,
  granted_by_user_id bigint NOT NULL,
  revoked_at timestamptz,
  revoked_by_user_id bigint,
  CONSTRAINT service_account_owners_account_fkey
    FOREIGN KEY(tenant_id,service_account_id)
    REFERENCES public.service_accounts(tenant_id,id),
  CONSTRAINT service_account_owners_owner_fkey FOREIGN KEY(tenant_id,inventory_owner_id)
    REFERENCES public.inventory_owners(tenant_id,id),
  CONSTRAINT service_account_owners_granted_by_fkey
    FOREIGN KEY(tenant_id,granted_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  CONSTRAINT service_account_owners_revoked_by_fkey
    FOREIGN KEY(tenant_id,revoked_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  CONSTRAINT service_account_owners_revocation_check CHECK(
    (revoked_at IS NULL)=(revoked_by_user_id IS NULL) AND
    (revoked_at IS NULL OR revoked_at>=granted_at))
);
CREATE UNIQUE INDEX service_account_owners_active_unique
ON public.service_account_inventory_owners(tenant_id,service_account_id,inventory_owner_id)
WHERE revoked_at IS NULL;

CREATE TABLE public.service_account_permissions (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  service_account_id bigint NOT NULL,
  permission_id bigint NOT NULL,
  granted_at timestamptz NOT NULL,
  granted_by_user_id bigint NOT NULL,
  revoked_at timestamptz,
  revoked_by_user_id bigint,
  CONSTRAINT service_account_permissions_account_fkey
    FOREIGN KEY(tenant_id,service_account_id)
    REFERENCES public.service_accounts(tenant_id,id),
  CONSTRAINT service_account_permissions_permission_fkey FOREIGN KEY(tenant_id,permission_id)
    REFERENCES public.permissions(tenant_id,id),
  CONSTRAINT service_account_permissions_granted_by_fkey
    FOREIGN KEY(tenant_id,granted_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  CONSTRAINT service_account_permissions_revoked_by_fkey
    FOREIGN KEY(tenant_id,revoked_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  CONSTRAINT service_account_permissions_revocation_check CHECK(
    (revoked_at IS NULL)=(revoked_by_user_id IS NULL) AND
    (revoked_at IS NULL OR revoked_at>=granted_at))
);
CREATE UNIQUE INDEX service_account_permissions_active_unique
ON public.service_account_permissions(tenant_id,service_account_id,permission_id)
WHERE revoked_at IS NULL;

CREATE TABLE public.service_account_credentials (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  service_account_id bigint NOT NULL,
  label text NOT NULL,
  token_prefix text NOT NULL,
  token_hash text NOT NULL UNIQUE,
  created_at timestamptz NOT NULL,
  created_by_user_id bigint NOT NULL,
  expires_at timestamptz,
  revoked_at timestamptz,
  revoked_by_user_id bigint,
  revocation_reason text,
  last_used_at timestamptz,
  CONSTRAINT service_account_credentials_scope_id_unique UNIQUE(tenant_id,id),
  CONSTRAINT service_account_credentials_account_fkey
    FOREIGN KEY(tenant_id,service_account_id)
    REFERENCES public.service_accounts(tenant_id,id),
  CONSTRAINT service_account_credentials_created_by_fkey
    FOREIGN KEY(tenant_id,created_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  CONSTRAINT service_account_credentials_revoked_by_fkey
    FOREIGN KEY(tenant_id,revoked_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  CONSTRAINT service_account_credentials_label_check CHECK(
    label=btrim(label) AND label<>'' AND char_length(label)<=120 AND label!~'[[:cntrl:]]'),
  CONSTRAINT service_account_credentials_prefix_check CHECK(
    token_prefix~'^wbs_sa_[A-Za-z0-9]{8}$'),
  CONSTRAINT service_account_credentials_hash_check CHECK(token_hash~'^[0-9a-f]{64}$'),
  CONSTRAINT service_account_credentials_expiry_check CHECK(
    expires_at IS NULL OR expires_at>created_at),
  CONSTRAINT service_account_credentials_revocation_check CHECK(
    (revoked_at IS NULL AND revoked_by_user_id IS NULL AND revocation_reason IS NULL)
    OR (revoked_at IS NOT NULL AND revoked_by_user_id IS NOT NULL
      AND revocation_reason IS NOT NULL AND revoked_at>=created_at)),
  CONSTRAINT service_account_credentials_reason_check CHECK(revocation_reason IS NULL OR (
    revocation_reason=btrim(revocation_reason) AND revocation_reason<>''
    AND char_length(revocation_reason)<=500 AND revocation_reason!~'[[:cntrl:]]')),
  CONSTRAINT service_account_credentials_last_used_check CHECK(
    last_used_at IS NULL OR last_used_at>=created_at)
);
CREATE INDEX service_account_credentials_account_idx
ON public.service_account_credentials(tenant_id,service_account_id,created_at DESC,id DESC);

CREATE TABLE public.service_account_events (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  service_account_id bigint NOT NULL,
  credential_id bigint,
  action text NOT NULL,
  account_revision bigint NOT NULL,
  actor_user_id bigint NOT NULL,
  occurred_at timestamptz NOT NULL,
  evidence jsonb NOT NULL,
  CONSTRAINT service_account_events_account_fkey FOREIGN KEY(tenant_id,service_account_id)
    REFERENCES public.service_accounts(tenant_id,id),
  CONSTRAINT service_account_events_credential_fkey FOREIGN KEY(tenant_id,credential_id)
    REFERENCES public.service_account_credentials(tenant_id,id),
  CONSTRAINT service_account_events_actor_fkey FOREIGN KEY(tenant_id,actor_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  CONSTRAINT service_account_events_action_check CHECK(action IN (
    'created','access_updated','enabled','disabled','credential_issued','credential_revoked')),
  CONSTRAINT service_account_events_credential_shape_check CHECK(
    (action IN ('credential_issued','credential_revoked'))=(credential_id IS NOT NULL)),
  CONSTRAINT service_account_events_revision_check CHECK(account_revision>0),
  CONSTRAINT service_account_events_evidence_check CHECK(jsonb_typeof(evidence)='object')
);

CREATE FUNCTION public.service_account_actor_is_admin(
  checked_tenant_id bigint, checked_user_id bigint
) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER
SET search_path TO 'pg_catalog','public' AS $$
  SELECT EXISTS(
    SELECT 1 FROM public.tenant_memberships membership
    JOIN public.user_roles assignment ON assignment.tenant_id=membership.tenant_id
      AND assignment.user_id=membership.user_id AND assignment.deleted IS NULL
    JOIN public.roles role ON role.tenant_id=assignment.tenant_id
      AND role.id=assignment.role_id AND role.deleted IS NULL
    JOIN public.role_permissions role_permission ON role_permission.tenant_id=role.tenant_id
      AND role_permission.role_id=role.id AND role_permission.deleted IS NULL
    JOIN public.permissions permission ON permission.tenant_id=role_permission.tenant_id
      AND permission.id=role_permission.permission_id AND permission.deleted IS NULL
    WHERE membership.tenant_id=checked_tenant_id AND membership.user_id=checked_user_id
      AND membership.deleted IS NULL AND permission.name='admin'
  )
$$;

CREATE FUNCTION public.validate_service_account() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE actor_id bigint;
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'service accounts cannot be deleted' USING ERRCODE='55000';
  END IF;
  actor_id:=NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint;
  IF TG_OP='INSERT' THEN
    IF actor_id IS NULL OR actor_id<>NEW.created_by_user_id
      OR actor_id<>NEW.updated_by_user_id
      OR NOT public.service_account_actor_is_admin(NEW.tenant_id,actor_id)
      OR NEW.status<>'active' OR NEW.revision<>1
      OR NEW.created_at<>NEW.updated_at OR NEW.disabled_at IS NOT NULL
      OR NEW.last_used_at IS NOT NULL
      OR NOT EXISTS(SELECT 1 FROM public.users subject
        JOIN public.tenant_memberships membership ON membership.user_id=subject.id
          AND membership.tenant_id=NEW.tenant_id AND membership.deleted IS NULL
        WHERE subject.id=NEW.principal_user_id AND subject.deleted IS NULL
          AND subject.email LIKE 'service-account-%@identity.wareboxes.invalid'
          AND subject.first_name IS NULL AND subject.last_name IS NULL AND subject.phone IS NULL
          AND NOT membership.all_facilities AND NOT membership.all_inventory_owners)
      OR EXISTS(SELECT 1 FROM public.user_credentials credential
        WHERE credential.user_id=NEW.principal_user_id)
      OR EXISTS(SELECT 1 FROM public.sessions session
        WHERE session.user_id=NEW.principal_user_id)
      OR EXISTS(SELECT 1 FROM public.user_roles assignment
        WHERE assignment.tenant_id=NEW.tenant_id AND assignment.user_id=NEW.principal_user_id
          AND assignment.deleted IS NULL)
      OR EXISTS(SELECT 1 FROM public.user_facilities assignment
        WHERE assignment.tenant_id=NEW.tenant_id AND assignment.user_id=NEW.principal_user_id
          AND assignment.deleted IS NULL)
      OR EXISTS(SELECT 1 FROM public.user_inventory_owners assignment
        WHERE assignment.tenant_id=NEW.tenant_id AND assignment.user_id=NEW.principal_user_id
          AND assignment.deleted IS NULL) THEN
      RAISE EXCEPTION 'invalid service account principal or actor' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(NEW.id,NEW.tenant_id,NEW.principal_user_id,NEW.name,NEW.description,
      NEW.status,NEW.revision,NEW.all_facilities,NEW.all_inventory_owners,
      NEW.created_at,NEW.created_by_user_id,NEW.updated_at,NEW.updated_by_user_id,
      NEW.disabled_at,NEW.disabled_by_user_id,NEW.disabled_reason)
    IS NOT DISTINCT FROM
    ROW(OLD.id,OLD.tenant_id,OLD.principal_user_id,OLD.name,OLD.description,
      OLD.status,OLD.revision,OLD.all_facilities,OLD.all_inventory_owners,
      OLD.created_at,OLD.created_by_user_id,OLD.updated_at,OLD.updated_by_user_id,
      OLD.disabled_at,OLD.disabled_by_user_id,OLD.disabled_reason) THEN
    IF NEW.last_used_at IS NULL OR (OLD.last_used_at IS NOT NULL
      AND NEW.last_used_at<OLD.last_used_at) THEN
      RAISE EXCEPTION 'service account last-used evidence cannot regress'
        USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF actor_id IS NULL OR actor_id<>NEW.updated_by_user_id
    OR NOT public.service_account_actor_is_admin(NEW.tenant_id,actor_id)
    OR ROW(NEW.id,NEW.tenant_id,NEW.principal_user_id,NEW.name,NEW.description,
        NEW.created_at,NEW.created_by_user_id,NEW.last_used_at)
      IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.principal_user_id,OLD.name,OLD.description,
        OLD.created_at,OLD.created_by_user_id,OLD.last_used_at)
    OR NEW.revision<>OLD.revision+1 OR NEW.updated_at<OLD.updated_at
    OR (NEW.status=OLD.status AND ROW(NEW.disabled_at,NEW.disabled_by_user_id,NEW.disabled_reason)
      IS DISTINCT FROM ROW(OLD.disabled_at,OLD.disabled_by_user_id,OLD.disabled_reason)) THEN
    RAISE EXCEPTION 'invalid service account mutation' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.validate_service_account_assignment() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE actor_id bigint; checked_account bigint; checked_tenant bigint;
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'service account assignments cannot be deleted' USING ERRCODE='55000';
  END IF;
  actor_id:=NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint;
  checked_tenant:=NEW.tenant_id; checked_account:=NEW.service_account_id;
  IF actor_id IS NULL OR NOT public.service_account_actor_is_admin(checked_tenant,actor_id) THEN
    RAISE EXCEPTION 'service account assignment actor is not authorized' USING ERRCODE='42501';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.granted_by_user_id<>actor_id OR NEW.revoked_at IS NOT NULL
      OR (TG_TABLE_NAME='service_account_facilities' AND NOT EXISTS(
        SELECT 1 FROM public.facilities facility WHERE facility.tenant_id=NEW.tenant_id
          AND facility.id=(to_jsonb(NEW)->>'facility_id')::bigint
          AND facility.deleted IS NULL))
      OR (TG_TABLE_NAME='service_account_inventory_owners' AND NOT EXISTS(
        SELECT 1 FROM public.inventory_owners owner WHERE owner.tenant_id=NEW.tenant_id
          AND owner.id=(to_jsonb(NEW)->>'inventory_owner_id')::bigint
          AND owner.deleted IS NULL))
      OR (TG_TABLE_NAME='service_account_permissions' AND NOT EXISTS(
        SELECT 1 FROM public.permissions permission WHERE permission.tenant_id=NEW.tenant_id
          AND permission.id=(to_jsonb(NEW)->>'permission_id')::bigint
          AND permission.deleted IS NULL
          AND permission.name<>'admin')) THEN
      RAISE EXCEPTION 'invalid service account assignment' USING ERRCODE='23514';
    END IF;
  ELSIF ROW(NEW.id,NEW.tenant_id,NEW.service_account_id,NEW.granted_at,
      NEW.granted_by_user_id) IS DISTINCT FROM
      ROW(OLD.id,OLD.tenant_id,OLD.service_account_id,OLD.granted_at,
      OLD.granted_by_user_id)
    OR OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL
    OR NEW.revoked_by_user_id<>actor_id THEN
    RAISE EXCEPTION 'invalid service account assignment revocation' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.validate_service_account_credential() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE actor_id bigint;
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'service account credentials cannot be deleted' USING ERRCODE='55000';
  END IF;
  actor_id:=NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint;
  IF TG_OP='INSERT' THEN
    IF actor_id IS NULL OR actor_id<>NEW.created_by_user_id
      OR NOT public.service_account_actor_is_admin(NEW.tenant_id,actor_id)
      OR NEW.revoked_at IS NOT NULL OR NEW.last_used_at IS NOT NULL
      OR NOT EXISTS(SELECT 1 FROM public.service_accounts account
        WHERE account.tenant_id=NEW.tenant_id AND account.id=NEW.service_account_id
          AND account.status='active') THEN
      RAISE EXCEPTION 'invalid service account credential' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(NEW.id,NEW.tenant_id,NEW.service_account_id,NEW.label,NEW.token_prefix,
      NEW.token_hash,NEW.created_at,NEW.created_by_user_id,NEW.expires_at,
      NEW.revoked_at,NEW.revoked_by_user_id,NEW.revocation_reason)
    IS NOT DISTINCT FROM
    ROW(OLD.id,OLD.tenant_id,OLD.service_account_id,OLD.label,OLD.token_prefix,
      OLD.token_hash,OLD.created_at,OLD.created_by_user_id,OLD.expires_at,
      OLD.revoked_at,OLD.revoked_by_user_id,OLD.revocation_reason) THEN
    IF NEW.last_used_at IS NULL OR (OLD.last_used_at IS NOT NULL
      AND NEW.last_used_at<OLD.last_used_at) THEN
      RAISE EXCEPTION 'credential last-used evidence cannot regress' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF actor_id IS NULL OR NOT public.service_account_actor_is_admin(NEW.tenant_id,actor_id)
    OR ROW(NEW.id,NEW.tenant_id,NEW.service_account_id,NEW.label,NEW.token_prefix,
        NEW.token_hash,NEW.created_at,NEW.created_by_user_id,NEW.expires_at,NEW.last_used_at)
      IS DISTINCT FROM
      ROW(OLD.id,OLD.tenant_id,OLD.service_account_id,OLD.label,OLD.token_prefix,
        OLD.token_hash,OLD.created_at,OLD.created_by_user_id,OLD.expires_at,OLD.last_used_at)
    OR OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL
    OR NEW.revoked_by_user_id<>actor_id OR NEW.revocation_reason IS NULL THEN
    RAISE EXCEPTION 'invalid service account credential revocation' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.reject_service_account_event_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$ BEGIN
  RAISE EXCEPTION 'service account events are immutable' USING ERRCODE='55000';
END $$;

CREATE FUNCTION public.validate_service_account_event() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE actor_id bigint;
BEGIN
  actor_id:=NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint;
  IF actor_id IS NULL OR NEW.actor_user_id<>actor_id
    OR NOT public.service_account_actor_is_admin(NEW.tenant_id,actor_id)
    OR NOT EXISTS(SELECT 1 FROM public.service_accounts account
      WHERE account.tenant_id=NEW.tenant_id AND account.id=NEW.service_account_id
        AND account.revision=NEW.account_revision)
    OR (NEW.credential_id IS NOT NULL AND NOT EXISTS(
      SELECT 1 FROM public.service_account_credentials credential
      WHERE credential.tenant_id=NEW.tenant_id AND credential.id=NEW.credential_id
        AND credential.service_account_id=NEW.service_account_id)) THEN
    RAISE EXCEPTION 'invalid service account event evidence' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.guard_service_account_subject() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE checked_user bigint;
BEGIN
  checked_user:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END;
  IF EXISTS(SELECT 1 FROM public.service_accounts account
    WHERE account.principal_user_id=checked_user) THEN
    RAISE EXCEPTION 'service account authorization subjects are immutable'
      USING ERRCODE='55000';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.guard_service_account_login_artifact() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE checked_user bigint;
BEGIN
  checked_user:=CASE WHEN TG_OP='DELETE' THEN OLD.user_id ELSE NEW.user_id END;
  IF EXISTS(SELECT 1 FROM public.service_accounts account
    WHERE account.principal_user_id=checked_user) THEN
    RAISE EXCEPTION 'service accounts cannot use user credentials or sessions'
      USING ERRCODE='23514';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.guard_service_account_legacy_access() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE checked_user bigint;
BEGIN
  checked_user:=CASE WHEN TG_OP='DELETE' THEN OLD.user_id ELSE NEW.user_id END;
  IF EXISTS(SELECT 1 FROM public.service_accounts account
    WHERE account.principal_user_id=checked_user) THEN
    RAISE EXCEPTION 'service account access is managed through service account scopes'
      USING ERRCODE='23514';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.guard_service_account_membership() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE checked_user bigint;
BEGIN
  IF TG_OP='INSERT' THEN RETURN NEW; END IF;
  checked_user:=CASE WHEN TG_OP='DELETE' THEN OLD.user_id ELSE NEW.user_id END;
  IF EXISTS(SELECT 1 FROM public.service_accounts account
    WHERE account.principal_user_id=checked_user) THEN
    RAISE EXCEPTION 'service account tenant membership is immutable'
      USING ERRCODE='55000';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.api_service_account_identity(p_token_hash text)
RETURNS TABLE(service_account_id bigint,tenant_id bigint,principal_user_id bigint)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE checked_credential_id bigint; checked_account_id bigint;
DECLARE checked_tenant_id bigint; checked_user_id bigint; used_at timestamptz;
BEGIN
  IF p_token_hash IS NULL OR p_token_hash!~'^[0-9a-f]{64}$' THEN RETURN; END IF;
  SELECT credential.id,account.id,account.tenant_id,account.principal_user_id
  INTO checked_credential_id,checked_account_id,checked_tenant_id,checked_user_id
  FROM public.service_account_credentials credential
  JOIN public.service_accounts account ON account.tenant_id=credential.tenant_id
    AND account.id=credential.service_account_id
  JOIN public.tenants tenant ON tenant.id=account.tenant_id
  JOIN public.users subject ON subject.id=account.principal_user_id
  JOIN public.tenant_memberships membership ON membership.tenant_id=account.tenant_id
    AND membership.user_id=account.principal_user_id
  WHERE credential.token_hash=p_token_hash AND credential.revoked_at IS NULL
    AND (credential.expires_at IS NULL OR credential.expires_at>CURRENT_TIMESTAMP)
    AND account.status='active' AND tenant.status='active' AND tenant.deleted IS NULL
    AND subject.deleted IS NULL AND membership.deleted IS NULL;
  IF NOT FOUND THEN RETURN; END IF;
  used_at:=CURRENT_TIMESTAMP;
  UPDATE public.service_account_credentials SET last_used_at=used_at
  WHERE id=checked_credential_id
    AND (last_used_at IS NULL OR last_used_at<used_at-INTERVAL '5 minutes');
  UPDATE public.service_accounts SET last_used_at=used_at
  WHERE id=checked_account_id
    AND (last_used_at IS NULL OR last_used_at<used_at-INTERVAL '5 minutes');
  RETURN QUERY SELECT checked_account_id,checked_tenant_id,checked_user_id;
END $$;

