-- Nested license-plate/container hierarchy with immutable relationship evidence.

ALTER TABLE public.license_plates
  ADD COLUMN parent_license_plate_id bigint,
  ADD COLUMN hierarchy_revision bigint NOT NULL DEFAULT 0,
  ADD COLUMN hierarchy_updated_at timestamptz,
  ADD COLUMN hierarchy_updated_by_user_id bigint,
  ADD CONSTRAINT license_plates_hierarchy_revision_nonnegative
    CHECK(hierarchy_revision>=0),
  ADD CONSTRAINT license_plates_parent_not_self
    CHECK(parent_license_plate_id IS NULL OR parent_license_plate_id<>id),
  ADD CONSTRAINT license_plates_parent_scope_fkey
    FOREIGN KEY(tenant_id,inventory_owner_id,facility_id,parent_license_plate_id)
    REFERENCES public.license_plates(tenant_id,inventory_owner_id,facility_id,id)
    DEFERRABLE INITIALLY DEFERRED,
  ADD CONSTRAINT license_plates_hierarchy_actor_fkey
    FOREIGN KEY(tenant_id,hierarchy_updated_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id);

CREATE INDEX idx_license_plates_active_parent
ON public.license_plates(tenant_id,inventory_owner_id,facility_id,parent_license_plate_id,id)
WHERE deleted IS NULL AND parent_license_plate_id IS NOT NULL;

CREATE INDEX idx_license_plate_putaway_contents_leaf
ON public.license_plate_putaway_task_contents(
  tenant_id,inventory_owner_id,facility_id,content_license_plate_id,task_id);
CREATE INDEX idx_inventory_relocation_contents_leaf
ON public.inventory_relocation_task_contents(
  tenant_id,inventory_owner_id,facility_id,content_license_plate_id,task_id);

CREATE TABLE public.license_plate_hierarchy_events (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  inventory_owner_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  child_license_plate_id bigint NOT NULL,
  previous_parent_license_plate_id bigint,
  parent_license_plate_id bigint,
  resulting_revision bigint NOT NULL,
  action text NOT NULL,
  actor_user_id bigint NOT NULL,
  occurred_at timestamptz NOT NULL,
  reason text NOT NULL,
  idempotency_key text NOT NULL,
  request_hash text NOT NULL,
  CONSTRAINT license_plate_hierarchy_events_scope_id_unique UNIQUE(tenant_id,id),
  CONSTRAINT license_plate_hierarchy_events_child_revision_unique
    UNIQUE(tenant_id,child_license_plate_id,resulting_revision),
  CONSTRAINT license_plate_hierarchy_events_idempotency_unique
    UNIQUE(tenant_id,idempotency_key),
  CONSTRAINT license_plate_hierarchy_events_action_check
    CHECK(action IN ('attached','detached')),
  CONSTRAINT license_plate_hierarchy_events_parent_shape_check CHECK(
    (action='attached' AND previous_parent_license_plate_id IS NULL
      AND parent_license_plate_id IS NOT NULL)
    OR (action='detached' AND previous_parent_license_plate_id IS NOT NULL
      AND parent_license_plate_id IS NULL)),
  CONSTRAINT license_plate_hierarchy_events_revision_positive
    CHECK(resulting_revision>0),
  CONSTRAINT license_plate_hierarchy_events_reason_check
    CHECK(reason=btrim(reason) AND char_length(reason) BETWEEN 1 AND 1000),
  CONSTRAINT license_plate_hierarchy_events_key_check
    CHECK(idempotency_key=btrim(idempotency_key)
      AND char_length(idempotency_key) BETWEEN 1 AND 200),
  CONSTRAINT license_plate_hierarchy_events_hash_check
    CHECK(request_hash~'^[0-9a-f]{64}$'),
  CONSTRAINT license_plate_hierarchy_events_tenant_fkey
    FOREIGN KEY(tenant_id) REFERENCES public.tenants(id),
  CONSTRAINT license_plate_hierarchy_events_child_fkey
    FOREIGN KEY(tenant_id,inventory_owner_id,facility_id,child_license_plate_id)
    REFERENCES public.license_plates(tenant_id,inventory_owner_id,facility_id,id)
    DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT license_plate_hierarchy_events_previous_parent_fkey
    FOREIGN KEY(tenant_id,inventory_owner_id,facility_id,previous_parent_license_plate_id)
    REFERENCES public.license_plates(tenant_id,inventory_owner_id,facility_id,id)
    DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT license_plate_hierarchy_events_parent_fkey
    FOREIGN KEY(tenant_id,inventory_owner_id,facility_id,parent_license_plate_id)
    REFERENCES public.license_plates(tenant_id,inventory_owner_id,facility_id,id)
    DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT license_plate_hierarchy_events_actor_fkey
    FOREIGN KEY(tenant_id,actor_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id)
);

ALTER TABLE public.license_plate_hierarchy_events FORCE ROW LEVEL SECURITY;

CREATE FUNCTION public.license_plate_actor_has_wms_permission(
  checked_tenant_id bigint,checked_user_id bigint
) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER
SET search_path TO 'pg_catalog','public' AS $$
  WITH RECURSIVE granted_roles AS (
    SELECT role.id,role.parent_id
    FROM public.tenant_memberships membership
    JOIN public.user_roles user_role ON user_role.tenant_id=membership.tenant_id
      AND user_role.user_id=membership.user_id AND user_role.deleted IS NULL
    JOIN public.roles role ON role.tenant_id=user_role.tenant_id
      AND role.id=user_role.role_id AND role.deleted IS NULL
    WHERE membership.tenant_id=checked_tenant_id
      AND membership.user_id=checked_user_id AND membership.deleted IS NULL
    UNION
    SELECT parent.id,parent.parent_id
    FROM granted_roles child
    JOIN public.roles parent ON parent.tenant_id=checked_tenant_id
      AND parent.id=child.parent_id AND parent.deleted IS NULL
  ), role_permission AS (
    SELECT 1
    FROM granted_roles role
    JOIN public.role_permissions grant_record
      ON grant_record.tenant_id=checked_tenant_id
      AND grant_record.role_id=role.id AND grant_record.deleted IS NULL
    JOIN public.permissions permission
      ON permission.tenant_id=grant_record.tenant_id
      AND permission.id=grant_record.permission_id AND permission.deleted IS NULL
    WHERE upper(permission.name) IN ('ADMIN','WMS')
    LIMIT 1
  ), service_permission AS (
    SELECT 1
    FROM public.service_accounts account
    JOIN public.service_account_permissions grant_record
      ON grant_record.tenant_id=account.tenant_id
      AND grant_record.service_account_id=account.id
      AND grant_record.revoked_at IS NULL
    JOIN public.permissions permission
      ON permission.tenant_id=grant_record.tenant_id
      AND permission.id=grant_record.permission_id AND permission.deleted IS NULL
    WHERE account.tenant_id=checked_tenant_id
      AND account.principal_user_id=checked_user_id AND account.status='active'
      AND upper(permission.name) IN ('ADMIN','WMS')
    LIMIT 1
  )
  SELECT EXISTS(SELECT 1 FROM role_permission)
    OR EXISTS(SELECT 1 FROM service_permission)
$$;

CREATE FUNCTION public.validate_license_plate_hierarchy_mutation() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE actor_id bigint;
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'license plates cannot be physically deleted' USING ERRCODE='55000';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.parent_license_plate_id IS NOT NULL OR NEW.hierarchy_revision<>0
      OR NEW.hierarchy_updated_at IS NOT NULL
      OR NEW.hierarchy_updated_by_user_id IS NOT NULL THEN
      RAISE EXCEPTION 'license plate hierarchy must be changed through a command'
        USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.deleted IS NULL AND NEW.deleted IS NOT NULL
    AND (OLD.parent_license_plate_id IS NOT NULL OR EXISTS(
      SELECT 1 FROM public.license_plates child
      WHERE child.tenant_id=OLD.tenant_id
        AND child.parent_license_plate_id=OLD.id AND child.deleted IS NULL)) THEN
    RAISE EXCEPTION 'nested license plates must be detached before deactivation'
      USING ERRCODE='23514';
  END IF;
  IF NEW.parent_license_plate_id IS NOT DISTINCT FROM OLD.parent_license_plate_id THEN
    IF NEW.hierarchy_revision<>OLD.hierarchy_revision
      OR NEW.hierarchy_updated_at IS DISTINCT FROM OLD.hierarchy_updated_at
      OR NEW.hierarchy_updated_by_user_id IS DISTINCT FROM OLD.hierarchy_updated_by_user_id THEN
      RAISE EXCEPTION 'license plate hierarchy evidence cannot change independently'
        USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(':',
    'license-plate-hierarchy',NEW.tenant_id,NEW.inventory_owner_id,NEW.facility_id),0));
  actor_id:=NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint;
  IF actor_id IS NULL OR NEW.hierarchy_updated_by_user_id<>actor_id
    OR NOT public.license_plate_actor_has_wms_permission(NEW.tenant_id,actor_id)
    OR NEW.hierarchy_revision<>OLD.hierarchy_revision+1
    OR NEW.hierarchy_updated_at IS NULL
    OR NEW.hierarchy_updated_at<transaction_timestamp()-INTERVAL '5 minutes'
    OR NEW.hierarchy_updated_at>clock_timestamp()+INTERVAL '1 minute'
    OR OLD.deleted IS NOT NULL OR NEW.deleted IS NOT NULL
    OR (OLD.parent_license_plate_id IS NOT NULL
      AND NEW.parent_license_plate_id IS NOT NULL) THEN
    RAISE EXCEPTION 'invalid license plate hierarchy transition'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.require_license_plate_hierarchy_integrity() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE cursor_id bigint; ancestor_depth integer:=0; child_height integer:=0;
DECLARE tree_size bigint:=0;
DECLARE ancestor record;
BEGIN
  IF NEW.parent_license_plate_id IS NOT NULL THEN
    cursor_id:=NEW.parent_license_plate_id;
    WHILE cursor_id IS NOT NULL LOOP
      ancestor_depth:=ancestor_depth+1;
      IF ancestor_depth>8 THEN
        RAISE EXCEPTION 'license plate hierarchy exceeds 8 levels'
          USING ERRCODE='23514';
      END IF;
      IF cursor_id=NEW.id THEN
        RAISE EXCEPTION 'license plate hierarchy cannot contain a cycle'
          USING ERRCODE='23514';
      END IF;
      SELECT candidate.id,candidate.inventory_owner_id,candidate.facility_id,
             candidate.location_id,candidate.parent_license_plate_id,candidate.deleted
      INTO ancestor
      FROM public.license_plates candidate
      WHERE candidate.tenant_id=NEW.tenant_id AND candidate.id=cursor_id;
      IF NOT FOUND OR ancestor.deleted IS NOT NULL
        OR ancestor.inventory_owner_id<>NEW.inventory_owner_id
        OR ancestor.facility_id<>NEW.facility_id
        OR ancestor.location_id IS DISTINCT FROM NEW.location_id THEN
        RAISE EXCEPTION 'nested license plates must share active owner, facility, and location'
          USING ERRCODE='23514';
      END IF;
      cursor_id:=ancestor.parent_license_plate_id;
    END LOOP;
  END IF;
  WITH RECURSIVE descendants AS (
    SELECT NEW.id AS id,0 AS depth
    UNION ALL
    SELECT child.id,descendants.depth+1
    FROM descendants
    JOIN public.license_plates child ON child.tenant_id=NEW.tenant_id
      AND child.parent_license_plate_id=descendants.id AND child.deleted IS NULL
  ) SELECT COALESCE(MAX(depth),0) INTO child_height FROM descendants;
  IF ancestor_depth+child_height>8 THEN
    RAISE EXCEPTION 'license plate hierarchy exceeds 8 levels'
      USING ERRCODE='23514';
  END IF;
  WITH RECURSIVE ancestors AS (
    SELECT NEW.id AS id,NEW.parent_license_plate_id AS parent_id
    UNION ALL
    SELECT parent.id,parent.parent_license_plate_id
    FROM ancestors
    JOIN public.license_plates parent ON parent.tenant_id=NEW.tenant_id
      AND parent.id=ancestors.parent_id
  ), root AS (
    SELECT id FROM ancestors WHERE parent_id IS NULL LIMIT 1
  ), tree AS (
    SELECT root.id FROM root
    UNION ALL
    SELECT child.id FROM tree
    JOIN public.license_plates child ON child.tenant_id=NEW.tenant_id
      AND child.parent_license_plate_id=tree.id AND child.deleted IS NULL
  ) SELECT COUNT(*) INTO tree_size FROM tree;
  IF tree_size>1000 THEN
    RAISE EXCEPTION 'license plate hierarchy exceeds 1000 containers'
      USING ERRCODE='23514';
  END IF;
  IF EXISTS(
    WITH RECURSIVE descendants AS (
      SELECT child.id
      FROM public.license_plates child
      WHERE child.tenant_id=NEW.tenant_id
        AND child.parent_license_plate_id=NEW.id AND child.deleted IS NULL
      UNION ALL
      SELECT child.id
      FROM descendants
      JOIN public.license_plates child ON child.tenant_id=NEW.tenant_id
        AND child.parent_license_plate_id=descendants.id AND child.deleted IS NULL
    )
    SELECT 1 FROM descendants
    JOIN public.license_plates child ON child.tenant_id=NEW.tenant_id
      AND child.id=descendants.id
    WHERE child.inventory_owner_id<>NEW.inventory_owner_id
      OR child.facility_id<>NEW.facility_id
      OR child.location_id IS DISTINCT FROM NEW.location_id
  ) THEN
    RAISE EXCEPTION 'license plate descendants must share owner, facility, and location'
      USING ERRCODE='23514';
  END IF;
  IF NEW.parent_license_plate_id IS DISTINCT FROM OLD.parent_license_plate_id
    AND EXISTS(
      WITH RECURSIVE child_tree AS (
        SELECT NEW.id AS id
        UNION ALL
        SELECT child.id FROM child_tree
        JOIN public.license_plates child ON child.tenant_id=NEW.tenant_id
          AND child.parent_license_plate_id=child_tree.id AND child.deleted IS NULL
      ), parent_chain AS (
        SELECT plate.id,plate.parent_license_plate_id
        FROM public.license_plates plate
        WHERE plate.tenant_id=NEW.tenant_id
          AND plate.id=COALESCE(NEW.parent_license_plate_id,OLD.parent_license_plate_id)
        UNION ALL
        SELECT parent.id,parent.parent_license_plate_id
        FROM parent_chain
        JOIN public.license_plates parent ON parent.tenant_id=NEW.tenant_id
          AND parent.id=parent_chain.parent_license_plate_id
      ), affected AS (
        SELECT id FROM child_tree UNION SELECT id FROM parent_chain
      )
      SELECT 1 FROM public.license_plate_putaway_tasks task
      WHERE task.tenant_id=NEW.tenant_id
        AND task.license_plate_id IN (SELECT id FROM affected)
        AND task.closed_at IS NULL
      UNION ALL
      SELECT 1 FROM public.inventory_relocation_tasks task
      WHERE task.tenant_id=NEW.tenant_id
        AND task.license_plate_id IN (SELECT id FROM affected)
        AND task.closed_at IS NULL
      UNION ALL
      SELECT 1 FROM public.packed_inventory_positions position
      WHERE position.tenant_id=NEW.tenant_id
        AND position.current_license_plate_id IN (SELECT id FROM affected)
        AND position.state IN ('packed','staged','loaded')
    ) THEN
    RAISE EXCEPTION 'license plate hierarchy cannot change during active movement'
      USING ERRCODE='23514';
  END IF;
  IF NEW.parent_license_plate_id IS DISTINCT FROM OLD.parent_license_plate_id
    AND NOT EXISTS(
      SELECT 1 FROM public.license_plate_hierarchy_events event
      WHERE event.tenant_id=NEW.tenant_id
        AND event.child_license_plate_id=NEW.id
        AND event.resulting_revision=NEW.hierarchy_revision
        AND event.previous_parent_license_plate_id
          IS NOT DISTINCT FROM OLD.parent_license_plate_id
        AND event.parent_license_plate_id
          IS NOT DISTINCT FROM NEW.parent_license_plate_id
        AND event.actor_user_id=NEW.hierarchy_updated_by_user_id
        AND event.occurred_at=NEW.hierarchy_updated_at) THEN
    RAISE EXCEPTION 'license plate hierarchy transition is missing audit evidence'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.validate_license_plate_hierarchy_event() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE actor_id bigint;
BEGIN
  actor_id:=NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint;
  IF actor_id IS NULL OR NEW.actor_user_id<>actor_id
    OR NOT public.license_plate_actor_has_wms_permission(NEW.tenant_id,actor_id)
    OR NOT EXISTS(
      SELECT 1 FROM public.license_plates child
      WHERE child.tenant_id=NEW.tenant_id
        AND child.inventory_owner_id=NEW.inventory_owner_id
        AND child.facility_id=NEW.facility_id
        AND child.id=NEW.child_license_plate_id
        AND child.parent_license_plate_id IS NOT DISTINCT FROM NEW.parent_license_plate_id
        AND child.hierarchy_revision=NEW.resulting_revision
        AND child.hierarchy_updated_at=NEW.occurred_at
        AND child.hierarchy_updated_by_user_id=NEW.actor_user_id) THEN
    RAISE EXCEPTION 'invalid license plate hierarchy event evidence'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.reject_license_plate_hierarchy_event_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$ BEGIN
  RAISE EXCEPTION 'license plate hierarchy events are immutable' USING ERRCODE='55000';
END $$;

CREATE FUNCTION public.guard_packed_position_license_plate_hierarchy() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE plate record;
BEGIN
  IF NEW.current_license_plate_id IS NULL
    OR NEW.state NOT IN ('packed','staged','loaded') THEN
    RETURN NEW;
  END IF;
  SELECT candidate.inventory_owner_id,candidate.facility_id,
         candidate.parent_license_plate_id,candidate.deleted
  INTO plate
  FROM public.license_plates candidate
  WHERE candidate.tenant_id=NEW.tenant_id
    AND candidate.id=NEW.current_license_plate_id;
  IF NOT FOUND OR plate.deleted IS NOT NULL THEN
    RAISE EXCEPTION 'packed inventory requires an active license plate'
      USING ERRCODE='23514';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(':',
    'license-plate-hierarchy',NEW.tenant_id,plate.inventory_owner_id,plate.facility_id),0));
  SELECT candidate.parent_license_plate_id,candidate.deleted
  INTO plate
  FROM public.license_plates candidate
  WHERE candidate.tenant_id=NEW.tenant_id
    AND candidate.id=NEW.current_license_plate_id;
  IF NOT FOUND OR plate.deleted IS NOT NULL
    OR plate.parent_license_plate_id IS NOT NULL
    OR EXISTS(SELECT 1 FROM public.license_plates child
      WHERE child.tenant_id=NEW.tenant_id
        AND child.parent_license_plate_id=NEW.current_license_plate_id
        AND child.deleted IS NULL) THEN
    RAISE EXCEPTION 'packed shipment license plates must be standalone containers'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER license_plates_validate_hierarchy_mutation
BEFORE INSERT OR UPDATE OR DELETE ON public.license_plates FOR EACH ROW
EXECUTE FUNCTION public.validate_license_plate_hierarchy_mutation();
CREATE CONSTRAINT TRIGGER license_plates_require_hierarchy_integrity
AFTER UPDATE OF parent_license_plate_id,location_id,inventory_owner_id,facility_id,deleted
ON public.license_plates
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
EXECUTE FUNCTION public.require_license_plate_hierarchy_integrity();
CREATE TRIGGER license_plate_hierarchy_events_validate
BEFORE INSERT ON public.license_plate_hierarchy_events FOR EACH ROW
EXECUTE FUNCTION public.validate_license_plate_hierarchy_event();
CREATE TRIGGER license_plate_hierarchy_events_immutable
BEFORE UPDATE OR DELETE ON public.license_plate_hierarchy_events FOR EACH ROW
EXECUTE FUNCTION public.reject_license_plate_hierarchy_event_mutation();
CREATE TRIGGER packed_inventory_positions_require_standalone_plate
BEFORE INSERT OR UPDATE OF current_license_plate_id,state
ON public.packed_inventory_positions FOR EACH ROW
EXECUTE FUNCTION public.guard_packed_position_license_plate_hierarchy();

ALTER TABLE public.license_plate_hierarchy_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY license_plate_hierarchy_events_tenant_isolation
ON public.license_plate_hierarchy_events
USING(tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint)
WITH CHECK(tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint);

GRANT SELECT,INSERT ON public.license_plate_hierarchy_events TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.license_plate_hierarchy_events_id_seq TO wareboxes_app;
REVOKE ALL ON FUNCTION public.license_plate_actor_has_wms_permission(bigint,bigint)
FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_license_plate_hierarchy_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_license_plate_hierarchy_integrity() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_license_plate_hierarchy_event() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.reject_license_plate_hierarchy_event_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_packed_position_license_plate_hierarchy() FROM PUBLIC;

-- Continuous inventory reconciliation control loop.
CREATE TABLE public.inventory_reconciliation_runs (
  id bigint GENERATED ALWAYS AS IDENTITY,
  tenant_id bigint NOT NULL,
  scheduled_for timestamp with time zone NOT NULL,
  started_at timestamp with time zone NOT NULL,
  completed_at timestamp with time zone NOT NULL,
  next_due_at timestamp with time zone NOT NULL,
  interval_seconds bigint NOT NULL,
  worker_id text NOT NULL,
  health text NOT NULL,
  previous_health text,
  journal_projection_issue_count bigint NOT NULL,
  commitment_issue_count bigint NOT NULL,
  affected_inventory_owner_count bigint NOT NULL,
  affected_facility_count bigint NOT NULL,
  max_severity_quantity bigint NOT NULL,
  issue_digest text NOT NULL,
  previous_issue_digest text,
  alert_type text,
  state_revision bigint NOT NULL,
  PRIMARY KEY (id),
  UNIQUE (tenant_id,id),
  UNIQUE (tenant_id,scheduled_for),
  FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
  CHECK (scheduled_for=date_trunc('minute',scheduled_for)),
  CHECK (started_at<=completed_at),
  CHECK (completed_at<next_due_at),
  CHECK (interval_seconds BETWEEN 60 AND 86400),
  CHECK (char_length(btrim(worker_id)) BETWEEN 1 AND 200),
  CHECK (health IN ('healthy','issues_detected')),
  CHECK (previous_health IS NULL OR previous_health IN ('healthy','issues_detected')),
  CHECK (journal_projection_issue_count>=0),
  CHECK (commitment_issue_count>=0),
  CHECK (affected_inventory_owner_count>=0),
  CHECK (affected_facility_count>=0),
  CHECK (max_severity_quantity>=0),
  CHECK (issue_digest ~ '^[0-9a-f]{32}$'),
  CHECK (previous_issue_digest IS NULL OR previous_issue_digest ~ '^[0-9a-f]{32}$'),
  CHECK (alert_type IS NULL OR alert_type IN ('issues_detected','issues_changed','restored')),
  CHECK (state_revision>0),
  CHECK ((health='healthy')=(journal_projection_issue_count=0 AND commitment_issue_count=0)),
  CHECK (health='issues_detected' OR max_severity_quantity=0)
);

CREATE TABLE public.inventory_reconciliation_state (
  tenant_id bigint PRIMARY KEY,
  revision bigint NOT NULL,
  health text NOT NULL,
  issue_digest text NOT NULL,
  last_run_id bigint NOT NULL,
  last_scheduled_for timestamp with time zone NOT NULL,
  last_completed_at timestamp with time zone NOT NULL,
  next_due_at timestamp with time zone NOT NULL,
  journal_projection_issue_count bigint NOT NULL,
  commitment_issue_count bigint NOT NULL,
  affected_inventory_owner_count bigint NOT NULL,
  affected_facility_count bigint NOT NULL,
  max_severity_quantity bigint NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
  FOREIGN KEY (tenant_id,last_run_id)
    REFERENCES public.inventory_reconciliation_runs(tenant_id,id),
  CHECK (revision>0),
  CHECK (health IN ('healthy','issues_detected')),
  CHECK (issue_digest ~ '^[0-9a-f]{32}$'),
  CHECK (last_scheduled_for=date_trunc('minute',last_scheduled_for)),
  CHECK (last_completed_at<next_due_at),
  CHECK (journal_projection_issue_count>=0),
  CHECK (commitment_issue_count>=0),
  CHECK (affected_inventory_owner_count>=0),
  CHECK (affected_facility_count>=0),
  CHECK (max_severity_quantity>=0),
  CHECK ((health='healthy')=(journal_projection_issue_count=0 AND commitment_issue_count=0)),
  CHECK (health='issues_detected' OR max_severity_quantity=0)
);

CREATE INDEX inventory_reconciliation_runs_tenant_history_idx
ON public.inventory_reconciliation_runs(tenant_id,scheduled_for DESC,id DESC);

CREATE FUNCTION public.reject_inventory_reconciliation_run_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$ BEGIN
  RAISE EXCEPTION 'inventory reconciliation runs are immutable' USING ERRCODE='55000';
END $$;

CREATE TRIGGER inventory_reconciliation_runs_immutable
BEFORE UPDATE OR DELETE ON public.inventory_reconciliation_runs FOR EACH ROW
EXECUTE FUNCTION public.reject_inventory_reconciliation_run_mutation();

CREATE FUNCTION public.execute_inventory_reconciliation(
  requested_tenant_id bigint,
  requested_worker_id text,
  requested_scheduled_for timestamp with time zone,
  requested_interval_seconds bigint
) RETURNS TABLE(
  run_id bigint,
  tenant_id bigint,
  scheduled_for timestamp with time zone,
  completed_at timestamp with time zone,
  next_due_at timestamp with time zone,
  interval_seconds bigint,
  health text,
  previous_health text,
  journal_projection_issue_count bigint,
  commitment_issue_count bigint,
  affected_inventory_owner_count bigint,
  affected_facility_count bigint,
  max_severity_quantity bigint,
  issue_digest text,
  state_revision bigint,
  created boolean,
  alert_type text
) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE current_tenant_id bigint;
DECLARE prior public.inventory_reconciliation_state%ROWTYPE;
DECLARE existing public.inventory_reconciliation_runs%ROWTYPE;
DECLARE inserted public.inventory_reconciliation_runs%ROWTYPE;
DECLARE journal_count bigint:=0;
DECLARE commitment_count bigint:=0;
DECLARE owner_count bigint:=0;
DECLARE facility_count bigint:=0;
DECLARE maximum_severity bigint:=0;
DECLARE digest text;
DECLARE current_health text;
DECLARE transition text;
DECLARE next_revision bigint;
DECLARE started timestamp with time zone:=clock_timestamp();
DECLARE completed timestamp with time zone;
BEGIN
  current_tenant_id:=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint;
  IF current_tenant_id IS NULL OR current_tenant_id<>requested_tenant_id THEN
    RAISE EXCEPTION 'inventory reconciliation tenant context is required'
      USING ERRCODE='42501';
  END IF;
  IF requested_tenant_id<=0
    OR char_length(btrim(requested_worker_id)) NOT BETWEEN 1 AND 200
    OR requested_scheduled_for<>date_trunc('minute',requested_scheduled_for)
    OR requested_scheduled_for<clock_timestamp()-INTERVAL '24 hours'
    OR requested_scheduled_for>clock_timestamp()+INTERVAL '1 minute'
    OR requested_interval_seconds NOT BETWEEN 60 AND 86400
    OR NOT EXISTS(SELECT 1 FROM public.tenants tenant
      WHERE tenant.id=requested_tenant_id AND tenant.deleted IS NULL
        AND tenant.status='active') THEN
    RAISE EXCEPTION 'invalid inventory reconciliation schedule'
      USING ERRCODE='22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'inventory-reconciliation:'||requested_tenant_id::text,0));
  SELECT run.* INTO existing
  FROM public.inventory_reconciliation_runs run
  WHERE run.tenant_id=requested_tenant_id
    AND run.scheduled_for=requested_scheduled_for;
  IF FOUND THEN
    IF existing.interval_seconds<>requested_interval_seconds THEN
      RAISE EXCEPTION 'inventory reconciliation schedule was reused with a different interval'
        USING ERRCODE='23505';
    END IF;
    RETURN QUERY SELECT existing.id,existing.tenant_id,existing.scheduled_for,
      existing.completed_at,existing.next_due_at,existing.interval_seconds,existing.health,
      existing.previous_health,existing.journal_projection_issue_count,
      existing.commitment_issue_count,existing.affected_inventory_owner_count,
      existing.affected_facility_count,existing.max_severity_quantity,
      existing.issue_digest,existing.state_revision,FALSE,existing.alert_type;
    RETURN;
  END IF;

  SELECT state.* INTO prior
  FROM public.inventory_reconciliation_state state
  WHERE state.tenant_id=requested_tenant_id
  FOR UPDATE;
  IF FOUND AND requested_scheduled_for<=prior.last_scheduled_for THEN
    RAISE EXCEPTION 'inventory reconciliation schedule is older than the current state'
      USING ERRCODE='40001';
  END IF;

  WITH issue AS (
    SELECT 'journal_projection'::text AS kind,reconciliation.inventory_owner_id,
      reconciliation.facility_id,ABS(reconciliation.variance)::bigint AS severity,
      hashtextextended(concat_ws(':','journal',reconciliation.inventory_owner_id,
        reconciliation.facility_id,reconciliation.location_id,
        COALESCE(reconciliation.license_plate_id,0),reconciliation.item_batch_id,
        reconciliation.status,reconciliation.journal_qty,
        reconciliation.projected_qty),0) AS issue_hash
    FROM public.inventory_reconciliation reconciliation
    WHERE reconciliation.tenant_id=requested_tenant_id
    UNION ALL
    SELECT 'commitments'::text,reconciliation.inventory_owner_id,
      reconciliation.facility_id,GREATEST(
        ABS(reconciliation.qty_reserved-reconciliation.allocated_qty),
        ABS(reconciliation.qty_held-reconciliation.held_qty),
        reconciliation.overcommitted_qty)::bigint,
      hashtextextended(concat_ws(':','commitments',reconciliation.inventory_balance_id,
        reconciliation.qty_on_hand,reconciliation.qty_reserved,
        reconciliation.allocated_qty,reconciliation.qty_held,
        reconciliation.held_qty,reconciliation.overcommitted_qty,
        array_to_string(reconciliation.issue_codes,',')),0)
    FROM public.inventory_hold_reconciliation reconciliation
    WHERE reconciliation.tenant_id=requested_tenant_id
  )
  SELECT COUNT(*) FILTER(WHERE kind='journal_projection')::bigint,
    COUNT(*) FILTER(WHERE kind='commitments')::bigint,
    COUNT(DISTINCT inventory_owner_id)::bigint,
    COUNT(DISTINCT facility_id)::bigint,COALESCE(MAX(severity),0)::bigint,
    md5(concat_ws('|',
      COUNT(*) FILTER(WHERE kind='journal_projection')::text,
      COUNT(*) FILTER(WHERE kind='commitments')::text,
      COUNT(DISTINCT inventory_owner_id)::text,
      COUNT(DISTINCT facility_id)::text,
      COALESCE(MAX(severity),0)::text,
      COALESCE(SUM(issue_hash::numeric),0)::text))
  INTO journal_count,commitment_count,owner_count,facility_count,
    maximum_severity,digest
  FROM issue;

  current_health:=CASE WHEN journal_count+commitment_count=0
    THEN 'healthy' ELSE 'issues_detected' END;
  transition:=CASE
    WHEN current_health='issues_detected'
      AND (prior.tenant_id IS NULL OR prior.health='healthy') THEN 'issues_detected'
    WHEN current_health='issues_detected' AND prior.health='issues_detected'
      AND prior.issue_digest<>digest THEN 'issues_changed'
    WHEN current_health='healthy' AND prior.health='issues_detected' THEN 'restored'
    ELSE NULL END;
  next_revision:=COALESCE(prior.revision,0)+1;
  completed:=clock_timestamp();

  INSERT INTO public.inventory_reconciliation_runs(
    tenant_id,scheduled_for,started_at,completed_at,next_due_at,interval_seconds,worker_id,
    health,previous_health,journal_projection_issue_count,commitment_issue_count,
    affected_inventory_owner_count,affected_facility_count,max_severity_quantity,
    issue_digest,previous_issue_digest,alert_type,state_revision)
  VALUES(requested_tenant_id,requested_scheduled_for,started,completed,
    completed+make_interval(secs=>requested_interval_seconds::integer),
    requested_interval_seconds,btrim(requested_worker_id),current_health,prior.health,journal_count,
    commitment_count,owner_count,facility_count,maximum_severity,digest,
    prior.issue_digest,transition,next_revision)
  RETURNING * INTO inserted;

  INSERT INTO public.inventory_reconciliation_state(
    tenant_id,revision,health,issue_digest,last_run_id,last_scheduled_for,
    last_completed_at,next_due_at,journal_projection_issue_count,
    commitment_issue_count,affected_inventory_owner_count,
    affected_facility_count,max_severity_quantity)
  VALUES(requested_tenant_id,next_revision,current_health,digest,inserted.id,
    requested_scheduled_for,completed,inserted.next_due_at,journal_count,
    commitment_count,owner_count,facility_count,maximum_severity)
  ON CONFLICT ON CONSTRAINT inventory_reconciliation_state_pkey
  DO UPDATE SET revision=EXCLUDED.revision,
    health=EXCLUDED.health,issue_digest=EXCLUDED.issue_digest,
    last_run_id=EXCLUDED.last_run_id,last_scheduled_for=EXCLUDED.last_scheduled_for,
    last_completed_at=EXCLUDED.last_completed_at,next_due_at=EXCLUDED.next_due_at,
    journal_projection_issue_count=EXCLUDED.journal_projection_issue_count,
    commitment_issue_count=EXCLUDED.commitment_issue_count,
    affected_inventory_owner_count=EXCLUDED.affected_inventory_owner_count,
    affected_facility_count=EXCLUDED.affected_facility_count,
    max_severity_quantity=EXCLUDED.max_severity_quantity;

  RETURN QUERY SELECT inserted.id,inserted.tenant_id,inserted.scheduled_for,
    inserted.completed_at,inserted.next_due_at,inserted.interval_seconds,inserted.health,
    inserted.previous_health,inserted.journal_projection_issue_count,
    inserted.commitment_issue_count,inserted.affected_inventory_owner_count,
    inserted.affected_facility_count,inserted.max_severity_quantity,
    inserted.issue_digest,inserted.state_revision,TRUE,inserted.alert_type;
END $$;

ALTER TABLE public.inventory_reconciliation_runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.inventory_reconciliation_runs FORCE ROW LEVEL SECURITY;
ALTER TABLE public.inventory_reconciliation_state ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.inventory_reconciliation_state FORCE ROW LEVEL SECURITY;
CREATE POLICY inventory_reconciliation_runs_tenant_isolation
ON public.inventory_reconciliation_runs
USING(tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint)
WITH CHECK(tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint);
CREATE POLICY inventory_reconciliation_state_tenant_isolation
ON public.inventory_reconciliation_state
USING(tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint)
WITH CHECK(tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint);

GRANT SELECT ON public.inventory_reconciliation_runs TO wareboxes_app;
GRANT SELECT ON public.inventory_reconciliation_state TO wareboxes_app;
REVOKE ALL ON FUNCTION public.reject_inventory_reconciliation_run_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.execute_inventory_reconciliation(bigint,text,timestamp with time zone,bigint)
FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.execute_inventory_reconciliation(bigint,text,timestamp with time zone,bigint)
TO wareboxes_app;

-- Executable putaway decision evidence. Every directed task freezes the exact
-- effective policy used to accept its destination; execution reuses that
-- evidence instead of silently adopting a later configuration.
ALTER TABLE public.putaway_tasks
  ADD COLUMN putaway_policy_source text NOT NULL,
  ADD COLUMN putaway_policy_configuration_id bigint,
  ADD COLUMN putaway_policy_configuration_revision bigint,
  ADD COLUMN putaway_policy_scope_level text,
  ADD COLUMN putaway_policy_scope_owner_id bigint,
  ADD COLUMN putaway_policy_scope_facility_id bigint,
  ADD COLUMN putaway_policy_definition jsonb NOT NULL,
  ADD COLUMN putaway_policy_hash text NOT NULL;

ALTER TABLE public.license_plate_putaway_tasks
  ADD COLUMN putaway_policy_source text NOT NULL,
  ADD COLUMN putaway_policy_configuration_id bigint,
  ADD COLUMN putaway_policy_configuration_revision bigint,
  ADD COLUMN putaway_policy_scope_level text,
  ADD COLUMN putaway_policy_scope_owner_id bigint,
  ADD COLUMN putaway_policy_scope_facility_id bigint,
  ADD COLUMN putaway_policy_definition jsonb NOT NULL,
  ADD COLUMN putaway_policy_hash text NOT NULL;

ALTER TABLE public.putaway_tasks
  ADD CONSTRAINT putaway_tasks_policy_configuration_fkey
    FOREIGN KEY (tenant_id,putaway_policy_configuration_id)
    REFERENCES public.configuration_versions(tenant_id,id),
  ADD CONSTRAINT putaway_tasks_policy_shape_check CHECK (
    putaway_policy_hash~'^[0-9a-f]{64}$'
    AND jsonb_typeof(putaway_policy_definition)='object'
    AND putaway_policy_definition ?& ARRAY[
      'require_zone_compatibility','enforce_location_capacity','allow_mixed_lots']
    AND putaway_policy_definition-ARRAY[
      'require_zone_compatibility','enforce_location_capacity','allow_mixed_lots']='{}'::jsonb
    AND jsonb_typeof(putaway_policy_definition->'require_zone_compatibility')='boolean'
    AND jsonb_typeof(putaway_policy_definition->'enforce_location_capacity')='boolean'
    AND jsonb_typeof(putaway_policy_definition->'allow_mixed_lots')='boolean'
    AND ((putaway_policy_source='product_default'
          AND putaway_policy_configuration_id IS NULL
          AND putaway_policy_configuration_revision IS NULL
          AND putaway_policy_scope_level IS NULL
          AND putaway_policy_scope_owner_id IS NULL
          AND putaway_policy_scope_facility_id IS NULL)
      OR (putaway_policy_source='configuration'
          AND putaway_policy_configuration_id IS NOT NULL
          AND putaway_policy_configuration_revision>0
          AND ((putaway_policy_scope_level='tenant'
                AND putaway_policy_scope_owner_id IS NULL
                AND putaway_policy_scope_facility_id IS NULL)
            OR (putaway_policy_scope_level='inventory_owner'
                AND putaway_policy_scope_owner_id IS NOT NULL
                AND putaway_policy_scope_facility_id IS NULL)
            OR (putaway_policy_scope_level='facility'
                AND putaway_policy_scope_owner_id IS NULL
                AND putaway_policy_scope_facility_id IS NOT NULL)
            OR (putaway_policy_scope_level='owner_facility'
                AND putaway_policy_scope_owner_id IS NOT NULL
                AND putaway_policy_scope_facility_id IS NOT NULL)))));

ALTER TABLE public.license_plate_putaway_tasks
  ADD CONSTRAINT license_plate_putaway_tasks_policy_configuration_fkey
    FOREIGN KEY (tenant_id,putaway_policy_configuration_id)
    REFERENCES public.configuration_versions(tenant_id,id),
  ADD CONSTRAINT license_plate_putaway_tasks_policy_shape_check CHECK (
    putaway_policy_hash~'^[0-9a-f]{64}$'
    AND jsonb_typeof(putaway_policy_definition)='object'
    AND putaway_policy_definition ?& ARRAY[
      'require_zone_compatibility','enforce_location_capacity','allow_mixed_lots']
    AND putaway_policy_definition-ARRAY[
      'require_zone_compatibility','enforce_location_capacity','allow_mixed_lots']='{}'::jsonb
    AND jsonb_typeof(putaway_policy_definition->'require_zone_compatibility')='boolean'
    AND jsonb_typeof(putaway_policy_definition->'enforce_location_capacity')='boolean'
    AND jsonb_typeof(putaway_policy_definition->'allow_mixed_lots')='boolean'
    AND ((putaway_policy_source='product_default'
          AND putaway_policy_configuration_id IS NULL
          AND putaway_policy_configuration_revision IS NULL
          AND putaway_policy_scope_level IS NULL
          AND putaway_policy_scope_owner_id IS NULL
          AND putaway_policy_scope_facility_id IS NULL)
      OR (putaway_policy_source='configuration'
          AND putaway_policy_configuration_id IS NOT NULL
          AND putaway_policy_configuration_revision>0
          AND ((putaway_policy_scope_level='tenant'
                AND putaway_policy_scope_owner_id IS NULL
                AND putaway_policy_scope_facility_id IS NULL)
            OR (putaway_policy_scope_level='inventory_owner'
                AND putaway_policy_scope_owner_id IS NOT NULL
                AND putaway_policy_scope_facility_id IS NULL)
            OR (putaway_policy_scope_level='facility'
                AND putaway_policy_scope_owner_id IS NULL
                AND putaway_policy_scope_facility_id IS NOT NULL)
            OR (putaway_policy_scope_level='owner_facility'
                AND putaway_policy_scope_owner_id IS NOT NULL
                AND putaway_policy_scope_facility_id IS NOT NULL)))));

CREATE INDEX putaway_tasks_policy_configuration_idx
ON public.putaway_tasks(tenant_id,putaway_policy_configuration_id)
WHERE putaway_policy_configuration_id IS NOT NULL;
CREATE INDEX license_plate_putaway_tasks_policy_configuration_idx
ON public.license_plate_putaway_tasks(tenant_id,putaway_policy_configuration_id)
WHERE putaway_policy_configuration_id IS NOT NULL;

CREATE FUNCTION public.validate_putaway_policy_snapshot() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE task_created timestamp with time zone;
DECLARE configuration_row public.configuration_versions%ROWTYPE;
DECLARE resolved_configuration_id bigint;
DECLARE calculated_hash text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(format(
    'configuration-kind:%s:putaway',NEW.tenant_id),0));
  SELECT task.created INTO task_created FROM public.work_tasks task
  WHERE task.tenant_id=NEW.tenant_id AND task.id=NEW.task_id;
  IF task_created IS NULL THEN
    RAISE EXCEPTION 'putaway policy requires its work task' USING ERRCODE='23514';
  END IF;

  calculated_hash:=encode(sha256(convert_to(
    'putaway-policy-v1|'||
    (NEW.putaway_policy_definition->>'require_zone_compatibility')||'|'||
    (NEW.putaway_policy_definition->>'enforce_location_capacity')||'|'||
    (NEW.putaway_policy_definition->>'allow_mixed_lots'),'UTF8')),'hex');
  IF calculated_hash IS DISTINCT FROM NEW.putaway_policy_hash THEN
    RAISE EXCEPTION 'putaway policy hash does not match its snapshot'
      USING ERRCODE='23514';
  END IF;

  SELECT configuration.id INTO resolved_configuration_id
  FROM public.configuration_versions configuration
  WHERE configuration.tenant_id=NEW.tenant_id
    AND configuration.kind='putaway' AND configuration.status='active'
    AND configuration.effective_from<=task_created
    AND (configuration.effective_until IS NULL OR configuration.effective_until>task_created)
    AND (configuration.inventory_owner_id IS NULL
         OR configuration.inventory_owner_id=NEW.inventory_owner_id)
    AND (configuration.facility_id IS NULL OR configuration.facility_id=NEW.facility_id)
  ORDER BY CASE configuration.scope_level
             WHEN 'owner_facility' THEN 2
             WHEN 'inventory_owner' THEN 1
             WHEN 'facility' THEN 1 ELSE 0 END DESC,
           configuration.effective_from DESC,configuration.revision DESC,configuration.id DESC
  LIMIT 1;

  IF NEW.putaway_policy_source='product_default' THEN
    IF resolved_configuration_id IS NOT NULL
       OR NEW.putaway_policy_definition<>jsonb_build_object(
         'require_zone_compatibility',false,
         'enforce_location_capacity',false,
         'allow_mixed_lots',false) THEN
      RAISE EXCEPTION 'putaway product default is not effective or exact'
        USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;

  SELECT * INTO configuration_row FROM public.configuration_versions configuration
  WHERE configuration.tenant_id=NEW.tenant_id
    AND configuration.id=NEW.putaway_policy_configuration_id;
  IF NOT FOUND OR resolved_configuration_id IS DISTINCT FROM configuration_row.id
     OR configuration_row.kind<>'putaway'
     OR configuration_row.revision<>NEW.putaway_policy_configuration_revision
     OR configuration_row.scope_level<>NEW.putaway_policy_scope_level
     OR configuration_row.inventory_owner_id IS DISTINCT FROM NEW.putaway_policy_scope_owner_id
     OR configuration_row.facility_id IS DISTINCT FROM NEW.putaway_policy_scope_facility_id
     OR configuration_row.definition-'kind'<>NEW.putaway_policy_definition THEN
    RAISE EXCEPTION 'putaway configuration snapshot is stale or inconsistent'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.guard_putaway_policy_evidence_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.putaway_policy_source IS DISTINCT FROM OLD.putaway_policy_source
     OR NEW.putaway_policy_configuration_id IS DISTINCT FROM OLD.putaway_policy_configuration_id
     OR NEW.putaway_policy_configuration_revision IS DISTINCT FROM OLD.putaway_policy_configuration_revision
     OR NEW.putaway_policy_scope_level IS DISTINCT FROM OLD.putaway_policy_scope_level
     OR NEW.putaway_policy_scope_owner_id IS DISTINCT FROM OLD.putaway_policy_scope_owner_id
     OR NEW.putaway_policy_scope_facility_id IS DISTINCT FROM OLD.putaway_policy_scope_facility_id
     OR NEW.putaway_policy_definition IS DISTINCT FROM OLD.putaway_policy_definition
     OR NEW.putaway_policy_hash IS DISTINCT FROM OLD.putaway_policy_hash THEN
    RAISE EXCEPTION 'putaway policy evidence is immutable' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.require_putaway_policy_destination() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE task_created timestamp with time zone;
DECLARE item_row record;
DECLARE zone_purpose text;
DECLARE require_zone boolean;
DECLARE enforce_capacity boolean;
DECLARE allow_mixed boolean;
BEGIN
  SELECT task.created INTO task_created FROM public.work_tasks task
  WHERE task.tenant_id=NEW.tenant_id AND task.id=NEW.task_id;
  require_zone:=(NEW.putaway_policy_definition->>'require_zone_compatibility')::boolean;
  enforce_capacity:=(NEW.putaway_policy_definition->>'enforce_location_capacity')::boolean;
  allow_mixed:=(NEW.putaway_policy_definition->>'allow_mixed_lots')::boolean;

  SELECT zone.purpose INTO zone_purpose
  FROM public.storage_zone_locations member
  JOIN public.storage_zones zone ON zone.tenant_id=member.tenant_id
    AND zone.facility_id=member.facility_id AND zone.id=member.storage_zone_id
  WHERE member.tenant_id=NEW.tenant_id AND member.facility_id=NEW.facility_id
    AND member.location_id=NEW.destination_location_id
    AND zone.effective_from<=task_created
    AND (zone.effective_to IS NULL OR zone.effective_to>task_created)
  ORDER BY zone.id LIMIT 1;

  IF TG_TABLE_NAME='putaway_tasks' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(format(
      'inventory-location-item:%s:%s:%s:%s',NEW.tenant_id,NEW.inventory_owner_id,
      NEW.destination_location_id,NEW.item_id),0));
    IF require_zone AND (zone_purpose IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.item_storage_policies policy
      JOIN public.item_storage_policy_zone_purposes purpose
        ON purpose.tenant_id=policy.tenant_id
       AND purpose.inventory_owner_id=policy.inventory_owner_id
       AND purpose.facility_id=policy.facility_id
       AND purpose.item_storage_policy_id=policy.id
      JOIN public.inventory_balances source ON source.tenant_id=NEW.tenant_id
       AND source.inventory_owner_id=NEW.inventory_owner_id
       AND source.facility_id=NEW.facility_id
       AND source.id=NEW.source_inventory_balance_id
      WHERE policy.tenant_id=NEW.tenant_id
        AND policy.inventory_owner_id=NEW.inventory_owner_id
        AND policy.facility_id=NEW.facility_id AND policy.item_id=NEW.item_id
        AND policy.uom=source.uom AND purpose.purpose=zone_purpose
        AND policy.effective_from<=task_created
        AND (policy.effective_to IS NULL OR policy.effective_to>task_created))) THEN
      RAISE EXCEPTION 'putaway destination zone violates its frozen policy'
        USING ERRCODE='23514';
    END IF;
    IF enforce_capacity AND EXISTS (
      SELECT 1 FROM public.item_storage_policies policy
      JOIN public.inventory_balances source ON source.tenant_id=NEW.tenant_id
       AND source.inventory_owner_id=NEW.inventory_owner_id
       AND source.facility_id=NEW.facility_id
       AND source.id=NEW.source_inventory_balance_id AND source.uom=policy.uom
      WHERE policy.tenant_id=NEW.tenant_id
        AND policy.inventory_owner_id=NEW.inventory_owner_id
        AND policy.facility_id=NEW.facility_id AND policy.item_id=NEW.item_id
        AND policy.effective_from<=task_created
        AND (policy.effective_to IS NULL OR policy.effective_to>task_created)
        AND policy.max_quantity_per_location IS NOT NULL
        AND COALESCE((SELECT SUM(balance.qty_on_hand) FROM public.inventory_balances balance
          WHERE balance.tenant_id=NEW.tenant_id
            AND balance.inventory_owner_id=NEW.inventory_owner_id
            AND balance.facility_id=NEW.facility_id
            AND balance.location_id=NEW.destination_location_id
            AND balance.item_id=NEW.item_id AND balance.uom=policy.uom
            AND balance.deleted IS NULL),0)+NEW.planned_quantity>
              policy.max_quantity_per_location) THEN
      RAISE EXCEPTION 'putaway destination capacity violates its frozen policy'
        USING ERRCODE='23514';
    END IF;
    IF NOT allow_mixed AND EXISTS (
      SELECT 1 FROM public.inventory_balances balance
      JOIN public.item_batches existing_batch ON existing_batch.tenant_id=balance.tenant_id
       AND existing_batch.inventory_owner_id=balance.inventory_owner_id
       AND existing_batch.id=balance.item_batch_id
      JOIN public.item_batches incoming_batch ON incoming_batch.tenant_id=NEW.tenant_id
       AND incoming_batch.inventory_owner_id=NEW.inventory_owner_id
       AND incoming_batch.id=NEW.item_batch_id
      WHERE balance.tenant_id=NEW.tenant_id
        AND balance.inventory_owner_id=NEW.inventory_owner_id
        AND balance.facility_id=NEW.facility_id
        AND balance.location_id=NEW.destination_location_id
        AND balance.item_id=NEW.item_id AND balance.item_batch_id<>NEW.item_batch_id
        AND balance.deleted IS NULL AND balance.qty_on_hand>0
        AND (existing_batch.lot IS DISTINCT FROM incoming_batch.lot
             OR existing_batch.expiration IS DISTINCT FROM incoming_batch.expiration)) THEN
      RAISE EXCEPTION 'putaway destination lot mix violates its frozen policy'
        USING ERRCODE='23514';
    END IF;
    RETURN NULL;
  END IF;

  IF (SELECT COUNT(*) FROM public.license_plate_putaway_task_contents content
      WHERE content.tenant_id=NEW.tenant_id AND content.task_id=NEW.task_id)
      <>NEW.planned_balance_count THEN
    RAISE EXCEPTION 'license plate putaway policy content snapshot is incomplete'
      USING ERRCODE='23514';
  END IF;
  FOR item_row IN
    SELECT content.item_id,content.uom,SUM(content.planned_quantity)::bigint AS incoming_quantity
    FROM public.license_plate_putaway_task_contents content
    WHERE content.tenant_id=NEW.tenant_id AND content.task_id=NEW.task_id
    GROUP BY content.item_id,content.uom ORDER BY content.item_id,content.uom
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(format(
      'inventory-location-item:%s:%s:%s:%s',NEW.tenant_id,NEW.inventory_owner_id,
      NEW.destination_location_id,item_row.item_id),0));
    IF require_zone AND (zone_purpose IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.item_storage_policies policy
      JOIN public.item_storage_policy_zone_purposes purpose
        ON purpose.tenant_id=policy.tenant_id
       AND purpose.inventory_owner_id=policy.inventory_owner_id
       AND purpose.facility_id=policy.facility_id
       AND purpose.item_storage_policy_id=policy.id
      WHERE policy.tenant_id=NEW.tenant_id
        AND policy.inventory_owner_id=NEW.inventory_owner_id
        AND policy.facility_id=NEW.facility_id AND policy.item_id=item_row.item_id
        AND policy.uom=item_row.uom AND purpose.purpose=zone_purpose
        AND policy.effective_from<=task_created
        AND (policy.effective_to IS NULL OR policy.effective_to>task_created))) THEN
      RAISE EXCEPTION 'license plate putaway destination zone violates its frozen policy'
        USING ERRCODE='23514';
    END IF;
    IF enforce_capacity AND EXISTS (
      SELECT 1 FROM public.item_storage_policies policy
      WHERE policy.tenant_id=NEW.tenant_id
        AND policy.inventory_owner_id=NEW.inventory_owner_id
        AND policy.facility_id=NEW.facility_id AND policy.item_id=item_row.item_id
        AND policy.uom=item_row.uom AND policy.effective_from<=task_created
        AND (policy.effective_to IS NULL OR policy.effective_to>task_created)
        AND policy.max_quantity_per_location IS NOT NULL
        AND COALESCE((SELECT SUM(balance.qty_on_hand) FROM public.inventory_balances balance
          WHERE balance.tenant_id=NEW.tenant_id
            AND balance.inventory_owner_id=NEW.inventory_owner_id
            AND balance.facility_id=NEW.facility_id
            AND balance.location_id=NEW.destination_location_id
            AND balance.item_id=item_row.item_id AND balance.uom=item_row.uom
            AND balance.deleted IS NULL),0)+item_row.incoming_quantity>
              policy.max_quantity_per_location) THEN
      RAISE EXCEPTION 'license plate putaway capacity violates its frozen policy'
        USING ERRCODE='23514';
    END IF;
  END LOOP;
  IF NOT allow_mixed AND (
    EXISTS (
      SELECT 1 FROM public.license_plate_putaway_task_contents left_content
      JOIN public.item_batches left_batch ON left_batch.tenant_id=left_content.tenant_id
       AND left_batch.inventory_owner_id=left_content.inventory_owner_id
       AND left_batch.id=left_content.item_batch_id
      JOIN public.license_plate_putaway_task_contents right_content
        ON right_content.tenant_id=left_content.tenant_id
       AND right_content.task_id=left_content.task_id
       AND right_content.item_id=left_content.item_id
       AND right_content.inventory_balance_id>left_content.inventory_balance_id
      JOIN public.item_batches right_batch ON right_batch.tenant_id=right_content.tenant_id
       AND right_batch.inventory_owner_id=right_content.inventory_owner_id
       AND right_batch.id=right_content.item_batch_id
      WHERE left_content.tenant_id=NEW.tenant_id AND left_content.task_id=NEW.task_id
        AND (left_batch.lot IS DISTINCT FROM right_batch.lot
             OR left_batch.expiration IS DISTINCT FROM right_batch.expiration))
    OR EXISTS (
      SELECT 1 FROM public.license_plate_putaway_task_contents content
      JOIN public.item_batches incoming_batch ON incoming_batch.tenant_id=content.tenant_id
       AND incoming_batch.inventory_owner_id=content.inventory_owner_id
       AND incoming_batch.id=content.item_batch_id
      JOIN public.inventory_balances balance ON balance.tenant_id=content.tenant_id
       AND balance.inventory_owner_id=content.inventory_owner_id
       AND balance.facility_id=content.facility_id
       AND balance.location_id=NEW.destination_location_id
       AND balance.item_id=content.item_id AND balance.deleted IS NULL
       AND balance.qty_on_hand>0 AND balance.item_batch_id<>content.item_batch_id
      JOIN public.item_batches existing_batch ON existing_batch.tenant_id=balance.tenant_id
       AND existing_batch.inventory_owner_id=balance.inventory_owner_id
       AND existing_batch.id=balance.item_batch_id
      WHERE content.tenant_id=NEW.tenant_id AND content.task_id=NEW.task_id
        AND (existing_batch.lot IS DISTINCT FROM incoming_batch.lot
             OR existing_batch.expiration IS DISTINCT FROM incoming_batch.expiration))) THEN
    RAISE EXCEPTION 'license plate putaway lot mix violates its frozen policy'
      USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;

CREATE TRIGGER putaway_tasks_validate_policy_snapshot
BEFORE INSERT ON public.putaway_tasks FOR EACH ROW
EXECUTE FUNCTION public.validate_putaway_policy_snapshot();
CREATE TRIGGER license_plate_putaway_tasks_validate_policy_snapshot
BEFORE INSERT ON public.license_plate_putaway_tasks FOR EACH ROW
EXECUTE FUNCTION public.validate_putaway_policy_snapshot();
CREATE TRIGGER putaway_tasks_guard_policy_evidence
BEFORE UPDATE ON public.putaway_tasks FOR EACH ROW
EXECUTE FUNCTION public.guard_putaway_policy_evidence_mutation();
CREATE TRIGGER license_plate_putaway_tasks_guard_policy_evidence
BEFORE UPDATE ON public.license_plate_putaway_tasks FOR EACH ROW
EXECUTE FUNCTION public.guard_putaway_policy_evidence_mutation();
CREATE CONSTRAINT TRIGGER putaway_tasks_require_policy_destination
AFTER INSERT ON public.putaway_tasks DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
EXECUTE FUNCTION public.require_putaway_policy_destination();
CREATE CONSTRAINT TRIGGER license_plate_putaway_tasks_require_policy_destination
AFTER INSERT ON public.license_plate_putaway_tasks DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
EXECUTE FUNCTION public.require_putaway_policy_destination();

REVOKE ALL ON FUNCTION public.validate_putaway_policy_snapshot() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_putaway_policy_evidence_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_putaway_policy_destination() FROM PUBLIC;

-- Effective wave policy is resolved independently for every client represented
-- in a multi-client wave. Membership freezes exact policy evidence so release,
-- replay, and audit cannot silently adopt a later configuration revision.
ALTER TABLE public.pick_wave_orders
  ADD COLUMN wave_policy_source text NOT NULL,
  ADD COLUMN wave_policy_configuration_id bigint,
  ADD COLUMN wave_policy_configuration_revision bigint,
  ADD COLUMN wave_policy_scope_level text,
  ADD COLUMN wave_policy_scope_owner_id bigint,
  ADD COLUMN wave_policy_scope_facility_id bigint,
  ADD COLUMN wave_policy_definition jsonb NOT NULL,
  ADD COLUMN wave_policy_hash text NOT NULL,
  ADD CONSTRAINT pick_wave_orders_policy_configuration_fkey
    FOREIGN KEY (tenant_id,wave_policy_configuration_id)
    REFERENCES public.configuration_versions(tenant_id,id),
  ADD CONSTRAINT pick_wave_orders_policy_shape_check CHECK (
    wave_policy_hash~'^[0-9a-f]{64}$'
    AND jsonb_typeof(wave_policy_definition)='object'
    AND wave_policy_definition ?& ARRAY['max_orders','require_complete_allocation']
    AND wave_policy_definition-ARRAY['max_orders','require_complete_allocation']='{}'::jsonb
    AND jsonb_typeof(wave_policy_definition->'max_orders')='number'
    AND (wave_policy_definition->>'max_orders')::bigint BETWEEN 1 AND 10000
    AND jsonb_typeof(wave_policy_definition->'require_complete_allocation')='boolean'
    AND ((wave_policy_source='product_default'
          AND wave_policy_configuration_id IS NULL
          AND wave_policy_configuration_revision IS NULL
          AND wave_policy_scope_level IS NULL
          AND wave_policy_scope_owner_id IS NULL
          AND wave_policy_scope_facility_id IS NULL)
      OR (wave_policy_source='configuration'
          AND wave_policy_configuration_id IS NOT NULL
          AND wave_policy_configuration_revision>0
          AND ((wave_policy_scope_level='tenant'
                AND wave_policy_scope_owner_id IS NULL
                AND wave_policy_scope_facility_id IS NULL)
            OR (wave_policy_scope_level='inventory_owner'
                AND wave_policy_scope_owner_id=inventory_owner_id
                AND wave_policy_scope_facility_id IS NULL)
            OR (wave_policy_scope_level='facility'
                AND wave_policy_scope_owner_id IS NULL
                AND wave_policy_scope_facility_id=facility_id)
            OR (wave_policy_scope_level='owner_facility'
                AND wave_policy_scope_owner_id=inventory_owner_id
                AND wave_policy_scope_facility_id=facility_id)))));

CREATE INDEX pick_wave_orders_policy_configuration_idx
ON public.pick_wave_orders(tenant_id,wave_policy_configuration_id)
WHERE wave_policy_configuration_id IS NOT NULL;

CREATE FUNCTION public.validate_wave_policy_snapshot() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE wave_planned_at timestamp with time zone;
DECLARE configuration_row public.configuration_versions%ROWTYPE;
DECLARE resolved_configuration_id bigint;
DECLARE calculated_hash text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(format(
    'configuration-kind:%s:wave',NEW.tenant_id),0));
  SELECT wave.planned_at INTO wave_planned_at FROM public.pick_waves wave
  WHERE wave.tenant_id=NEW.tenant_id AND wave.facility_id=NEW.facility_id
    AND wave.id=NEW.pick_wave_id;
  IF wave_planned_at IS NULL THEN
    RAISE EXCEPTION 'wave policy requires its wave header' USING ERRCODE='23514';
  END IF;
  calculated_hash:=encode(sha256(convert_to(
    'wave-policy-v1|'||(NEW.wave_policy_definition->>'max_orders')||'|'||
    (NEW.wave_policy_definition->>'require_complete_allocation'),'UTF8')),'hex');
  IF calculated_hash IS DISTINCT FROM NEW.wave_policy_hash THEN
    RAISE EXCEPTION 'wave policy hash does not match its snapshot' USING ERRCODE='23514';
  END IF;

  SELECT configuration.id INTO resolved_configuration_id
  FROM public.configuration_versions configuration
  WHERE configuration.tenant_id=NEW.tenant_id
    AND configuration.kind='wave' AND configuration.status='active'
    AND configuration.effective_from<=wave_planned_at
    AND (configuration.effective_until IS NULL OR configuration.effective_until>wave_planned_at)
    AND (configuration.inventory_owner_id IS NULL
         OR configuration.inventory_owner_id=NEW.inventory_owner_id)
    AND (configuration.facility_id IS NULL OR configuration.facility_id=NEW.facility_id)
  ORDER BY CASE configuration.scope_level
             WHEN 'owner_facility' THEN 2
             WHEN 'inventory_owner' THEN 1
             WHEN 'facility' THEN 1 ELSE 0 END DESC,
           configuration.effective_from DESC,configuration.revision DESC,configuration.id DESC
  LIMIT 1;

  IF NEW.wave_policy_source='product_default' THEN
    IF resolved_configuration_id IS NOT NULL
       OR NEW.wave_policy_definition<>jsonb_build_object(
         'max_orders',10000,'require_complete_allocation',false) THEN
      RAISE EXCEPTION 'wave product default is not effective or exact' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;

  SELECT * INTO configuration_row FROM public.configuration_versions configuration
  WHERE configuration.tenant_id=NEW.tenant_id
    AND configuration.id=NEW.wave_policy_configuration_id;
  IF NOT FOUND OR resolved_configuration_id IS DISTINCT FROM configuration_row.id
     OR configuration_row.kind<>'wave'
     OR configuration_row.revision<>NEW.wave_policy_configuration_revision
     OR configuration_row.scope_level<>NEW.wave_policy_scope_level
     OR configuration_row.inventory_owner_id IS DISTINCT FROM NEW.wave_policy_scope_owner_id
     OR configuration_row.facility_id IS DISTINCT FROM NEW.wave_policy_scope_facility_id
     OR configuration_row.definition-'kind'<>NEW.wave_policy_definition THEN
    RAISE EXCEPTION 'wave configuration snapshot is stale or inconsistent'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.guard_wave_policy_evidence_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.wave_policy_source IS DISTINCT FROM OLD.wave_policy_source
     OR NEW.wave_policy_configuration_id IS DISTINCT FROM OLD.wave_policy_configuration_id
     OR NEW.wave_policy_configuration_revision IS DISTINCT FROM OLD.wave_policy_configuration_revision
     OR NEW.wave_policy_scope_level IS DISTINCT FROM OLD.wave_policy_scope_level
     OR NEW.wave_policy_scope_owner_id IS DISTINCT FROM OLD.wave_policy_scope_owner_id
     OR NEW.wave_policy_scope_facility_id IS DISTINCT FROM OLD.wave_policy_scope_facility_id
     OR NEW.wave_policy_definition IS DISTINCT FROM OLD.wave_policy_definition
     OR NEW.wave_policy_hash IS DISTINCT FROM OLD.wave_policy_hash THEN
    RAISE EXCEPTION 'wave policy evidence is immutable' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.require_wave_policy_consistency() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE require_complete boolean;
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.pick_wave_orders member
    WHERE member.tenant_id=NEW.tenant_id AND member.pick_wave_id=NEW.pick_wave_id
      AND member.inventory_owner_id=NEW.inventory_owner_id
      AND (member.wave_policy_hash IS DISTINCT FROM NEW.wave_policy_hash
        OR member.wave_policy_configuration_id IS DISTINCT FROM NEW.wave_policy_configuration_id
        OR member.wave_policy_configuration_revision IS DISTINCT FROM NEW.wave_policy_configuration_revision)
  ) THEN
    RAISE EXCEPTION 'one client resolved multiple policies in a wave' USING ERRCODE='23514';
  END IF;
  IF (SELECT count(*) FROM public.pick_wave_orders member
      WHERE member.tenant_id=NEW.tenant_id AND member.pick_wave_id=NEW.pick_wave_id
        AND member.inventory_owner_id=NEW.inventory_owner_id)>
      (NEW.wave_policy_definition->>'max_orders')::bigint THEN
    RAISE EXCEPTION 'wave client order count exceeds its frozen policy' USING ERRCODE='23514';
  END IF;

  require_complete:=(NEW.wave_policy_definition->>'require_complete_allocation')::boolean;
  IF require_complete THEN
    PERFORM reservation.id FROM public.inventory_reservations reservation
    WHERE reservation.tenant_id=NEW.tenant_id
      AND reservation.inventory_owner_id=NEW.inventory_owner_id
      AND reservation.facility_id=NEW.facility_id
      AND reservation.order_id=NEW.order_id
    ORDER BY reservation.id FOR SHARE;
    PERFORM allocation.id FROM public.inventory_allocations allocation
    JOIN public.inventory_reservations reservation
      ON reservation.tenant_id=allocation.tenant_id
     AND reservation.inventory_owner_id=allocation.inventory_owner_id
     AND reservation.id=allocation.reservation_id
    WHERE allocation.tenant_id=NEW.tenant_id
      AND allocation.inventory_owner_id=NEW.inventory_owner_id
      AND allocation.facility_id=NEW.facility_id
      AND reservation.order_id=NEW.order_id
    ORDER BY allocation.id FOR SHARE OF allocation;
    IF NOT EXISTS (
      SELECT 1 FROM public.order_items line
      WHERE line.tenant_id=NEW.tenant_id
        AND line.inventory_owner_id=NEW.inventory_owner_id
        AND line.order_id=NEW.order_id AND line.deleted IS NULL)
      OR EXISTS (
      SELECT 1 FROM public.order_items line
      JOIN public.outbound_effective_demand demand
        ON demand.tenant_id=line.tenant_id
       AND demand.inventory_owner_id=line.inventory_owner_id
       AND demand.order_id=line.order_id AND demand.order_item_id=line.id
      WHERE line.tenant_id=NEW.tenant_id
        AND line.inventory_owner_id=NEW.inventory_owner_id
        AND line.order_id=NEW.order_id AND line.deleted IS NULL
        AND demand.effective_qty IS DISTINCT FROM COALESCE((
          SELECT SUM(allocation.qty) FROM public.inventory_reservations reservation
          JOIN public.inventory_allocations allocation
            ON allocation.tenant_id=reservation.tenant_id
           AND allocation.inventory_owner_id=reservation.inventory_owner_id
           AND allocation.reservation_id=reservation.id
          WHERE reservation.tenant_id=line.tenant_id
            AND reservation.inventory_owner_id=line.inventory_owner_id
            AND reservation.order_id=line.order_id
            AND reservation.order_item_id=line.id
            AND reservation.facility_id=NEW.facility_id
            AND reservation.status='active' AND reservation.deleted IS NULL
            AND allocation.facility_id=NEW.facility_id
            AND allocation.status='allocated' AND allocation.deleted IS NULL
            AND allocation.execution_stage='pick_source'),0)) THEN
      RAISE EXCEPTION 'wave policy requires complete allocation' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NULL;
END $$;

CREATE TRIGGER pick_wave_orders_validate_policy_snapshot
BEFORE INSERT ON public.pick_wave_orders FOR EACH ROW
EXECUTE FUNCTION public.validate_wave_policy_snapshot();
CREATE TRIGGER pick_wave_orders_guard_policy_evidence
BEFORE UPDATE ON public.pick_wave_orders FOR EACH ROW
EXECUTE FUNCTION public.guard_wave_policy_evidence_mutation();
CREATE CONSTRAINT TRIGGER pick_wave_orders_require_policy_consistency
AFTER INSERT ON public.pick_wave_orders DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
EXECUTE FUNCTION public.require_wave_policy_consistency();

REVOKE ALL ON FUNCTION public.validate_wave_policy_snapshot() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_wave_policy_evidence_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_wave_policy_consistency() FROM PUBLIC;

--
-- Executable work-orchestration dispatches. Plans remain immutable evidence;
-- dispatch items reserve their typed work without bypassing workflow claims.
--

CREATE TABLE public.work_orchestration_dispatches (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  inventory_owner_id bigint,
  plan_id bigint NOT NULL,
  worker_user_id bigint NOT NULL,
  status text NOT NULL DEFAULT 'active',
  revision bigint NOT NULL DEFAULT 1,
  activated_by_user_id bigint NOT NULL,
  activated_at timestamptz NOT NULL,
  ended_by_user_id bigint,
  ended_at timestamptz,
  cancellation_reason text,
  cancellation_note text,
  UNIQUE (tenant_id,id),
  UNIQUE (tenant_id,plan_id),
  CHECK (status IN ('active','completed','cancelled')),
  CHECK (revision>0),
  CHECK (cancellation_reason IS NULL OR cancellation_reason IN (
    'operator_cancelled','worker_unavailable','scope_changed','plan_invalidated','other')),
  CHECK (cancellation_note IS NULL OR (
    cancellation_note=btrim(cancellation_note) AND cancellation_note<>''
    AND char_length(cancellation_note)<=500 AND cancellation_note!~'[[:cntrl:]]')),
  CHECK ((status='active' AND revision=1 AND ended_by_user_id IS NULL
      AND ended_at IS NULL AND cancellation_reason IS NULL AND cancellation_note IS NULL)
    OR (status='completed' AND revision=2 AND ended_by_user_id IS NOT NULL
      AND ended_at IS NOT NULL AND cancellation_reason IS NULL AND cancellation_note IS NULL)
    OR (status='cancelled' AND revision=2 AND ended_by_user_id IS NOT NULL
      AND ended_at IS NOT NULL AND cancellation_reason IS NOT NULL
      AND (cancellation_reason<>'other' OR cancellation_note IS NOT NULL))),
  FOREIGN KEY (tenant_id,facility_id)
    REFERENCES public.facilities(tenant_id,id),
  FOREIGN KEY (tenant_id,inventory_owner_id,facility_id)
    REFERENCES public.inventory_owner_facilities(tenant_id,inventory_owner_id,facility_id),
  FOREIGN KEY (tenant_id,plan_id)
    REFERENCES public.work_orchestration_plans(tenant_id,id),
  FOREIGN KEY (tenant_id,worker_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  FOREIGN KEY (tenant_id,activated_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  FOREIGN KEY (tenant_id,ended_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id)
);
CREATE UNIQUE INDEX work_orchestration_dispatches_active_worker_idx
ON public.work_orchestration_dispatches(tenant_id,worker_user_id)
WHERE status='active';
CREATE INDEX work_orchestration_dispatches_scope_page_idx
ON public.work_orchestration_dispatches(tenant_id,facility_id,inventory_owner_id,activated_at DESC,id DESC);

CREATE TABLE public.work_orchestration_dispatch_items (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  dispatch_id bigint NOT NULL,
  plan_item_id bigint NOT NULL,
  sequence bigint NOT NULL,
  work_task_id bigint NOT NULL,
  state text NOT NULL DEFAULT 'reserved',
  released_at timestamptz,
  UNIQUE (tenant_id,id),
  UNIQUE (tenant_id,dispatch_id,sequence),
  UNIQUE (tenant_id,dispatch_id,plan_item_id),
  CHECK (sequence BETWEEN 1 AND 500),
  CHECK (state IN ('reserved','completed','cancelled')),
  CHECK ((state='reserved' AND released_at IS NULL)
    OR (state IN ('completed','cancelled') AND released_at IS NOT NULL)),
  FOREIGN KEY (tenant_id,dispatch_id)
    REFERENCES public.work_orchestration_dispatches(tenant_id,id),
  FOREIGN KEY (tenant_id,plan_item_id)
    REFERENCES public.work_orchestration_plan_items(tenant_id,id),
  FOREIGN KEY (tenant_id,work_task_id)
    REFERENCES public.work_tasks(tenant_id,id)
);
CREATE UNIQUE INDEX work_orchestration_dispatch_items_reserved_task_idx
ON public.work_orchestration_dispatch_items(tenant_id,work_task_id)
WHERE state='reserved';
CREATE INDEX work_orchestration_dispatch_items_dispatch_idx
ON public.work_orchestration_dispatch_items(tenant_id,dispatch_id,sequence);

CREATE FUNCTION public.work_orchestration_dispatch_worker_eligible(
  checked_tenant_id bigint,checked_user_id bigint,checked_facility_id bigint,
  checked_owner_id bigint,checked_at timestamptz) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
  SELECT EXISTS(
    SELECT 1 FROM public.employees employee
    JOIN public.employee_facilities assignment
      ON assignment.tenant_id=employee.tenant_id AND assignment.employee_id=employee.id
      AND assignment.facility_id=checked_facility_id AND assignment.deleted IS NULL
    JOIN public.tenant_memberships membership
      ON membership.tenant_id=employee.tenant_id AND membership.user_id=employee.user_id
      AND membership.deleted IS NULL
    WHERE employee.tenant_id=checked_tenant_id AND employee.user_id=checked_user_id
      AND employee.deleted IS NULL AND employee.hired<=checked_at
      AND (employee.terminated IS NULL OR employee.terminated>checked_at)
      AND (membership.all_facilities OR EXISTS(
        SELECT 1 FROM public.user_facilities facility_scope
        WHERE facility_scope.tenant_id=membership.tenant_id
          AND facility_scope.user_id=membership.user_id
          AND facility_scope.facility_id=checked_facility_id
          AND facility_scope.deleted IS NULL))
      AND (checked_owner_id IS NULL OR membership.all_inventory_owners OR EXISTS(
        SELECT 1 FROM public.user_inventory_owners owner_scope
        WHERE owner_scope.tenant_id=membership.tenant_id
          AND owner_scope.user_id=membership.user_id
          AND owner_scope.inventory_owner_id=checked_owner_id
          AND owner_scope.deleted IS NULL))
      AND public.work_orchestration_user_has_permission(
        checked_tenant_id,checked_user_id,'wms'))
$$;

CREATE FUNCTION public.validate_work_orchestration_dispatch_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE plan public.work_orchestration_plans%ROWTYPE;
DECLARE plan_found boolean;
BEGIN
  SELECT * INTO plan FROM public.work_orchestration_plans candidate
  WHERE candidate.tenant_id=NEW.tenant_id AND candidate.id=NEW.plan_id;
  plan_found:=FOUND;
  PERFORM task.id FROM public.work_orchestration_plan_items item
  JOIN public.work_tasks task ON task.tenant_id=item.tenant_id AND task.id=item.work_task_id
  WHERE item.tenant_id=NEW.tenant_id AND item.plan_id=NEW.plan_id
  ORDER BY task.id FOR UPDATE OF task;
  IF NOT plan_found OR plan.facility_id<>NEW.facility_id
    OR plan.requested_inventory_owner_id IS DISTINCT FROM NEW.inventory_owner_id
    OR plan.generated_for_user_id IS DISTINCT FROM NEW.worker_user_id
    OR plan.item_count<=0
    OR NEW.activated_by_user_id IS DISTINCT FROM
      NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint
    OR NOT public.slotting_user_has_supervisor_permission(
      NEW.tenant_id,NEW.activated_by_user_id)
    OR NOT public.work_orchestration_dispatch_worker_eligible(
      NEW.tenant_id,NEW.worker_user_id,NEW.facility_id,NEW.inventory_owner_id,NEW.activated_at)
    OR NEW.activated_at<transaction_timestamp()-INTERVAL '5 minutes'
    OR NEW.activated_at>clock_timestamp()+INTERVAL '1 minute'
    OR EXISTS(SELECT 1 FROM public.work_tasks task
      WHERE task.tenant_id=NEW.tenant_id AND task.assigned_user_id=NEW.worker_user_id
        AND task.deleted IS NULL AND task.status IN ('assigned','in_progress'))
    OR EXISTS(SELECT 1 FROM public.pick_tasks task
      WHERE task.tenant_id=NEW.tenant_id AND task.assigned_user_id=NEW.worker_user_id
        AND task.status='in_progress')
    OR EXISTS(SELECT 1 FROM public.work_orchestration_plan_items item
      LEFT JOIN public.work_tasks task ON task.tenant_id=item.tenant_id
        AND task.id=item.work_task_id
      WHERE item.tenant_id=NEW.tenant_id AND item.plan_id=NEW.plan_id
        AND (task.id IS NULL OR task.deleted IS NOT NULL OR task.status<>'open'
          OR task.assigned_user_id IS NOT NULL)) THEN
    RAISE EXCEPTION 'invalid or stale work orchestration dispatch'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.validate_work_orchestration_dispatch_item_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
BEGIN
  IF NOT EXISTS(
    SELECT 1 FROM public.work_orchestration_dispatches dispatch
    JOIN public.work_orchestration_plan_items item
      ON item.tenant_id=dispatch.tenant_id AND item.plan_id=dispatch.plan_id
    JOIN public.work_tasks task
      ON task.tenant_id=item.tenant_id AND task.id=item.work_task_id
    WHERE dispatch.tenant_id=NEW.tenant_id AND dispatch.id=NEW.dispatch_id
      AND dispatch.status='active' AND item.id=NEW.plan_item_id
      AND item.sequence=NEW.sequence AND item.work_task_id=NEW.work_task_id
      AND task.status='open' AND task.assigned_user_id IS NULL AND task.deleted IS NULL) THEN
    RAISE EXCEPTION 'invalid work orchestration dispatch item' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.guard_work_orchestration_dispatch_item_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP='DELETE' OR NEW.id<>OLD.id OR NEW.tenant_id<>OLD.tenant_id
    OR NEW.dispatch_id<>OLD.dispatch_id OR NEW.plan_item_id<>OLD.plan_item_id
    OR NEW.sequence<>OLD.sequence OR NEW.work_task_id<>OLD.work_task_id
    OR OLD.state<>'reserved' OR NEW.state NOT IN ('completed','cancelled')
    OR NEW.released_at IS NULL OR pg_trigger_depth()<=1 THEN
    RAISE EXCEPTION 'work orchestration dispatch items are immutable'
      USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.require_work_orchestration_dispatch_items() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE expected_count bigint; actual_count bigint;
BEGIN
  SELECT plan.item_count INTO expected_count
  FROM public.work_orchestration_dispatches dispatch
  JOIN public.work_orchestration_plans plan
    ON plan.tenant_id=dispatch.tenant_id AND plan.id=dispatch.plan_id
  WHERE dispatch.tenant_id=NEW.tenant_id AND dispatch.id=NEW.id;
  SELECT count(*) INTO actual_count FROM public.work_orchestration_dispatch_items item
  WHERE item.tenant_id=NEW.tenant_id AND item.dispatch_id=NEW.id;
  IF expected_count IS NULL OR expected_count<>actual_count THEN
    RAISE EXCEPTION 'work orchestration dispatch item count does not reconcile'
      USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;

CREATE FUNCTION public.guard_work_orchestration_dispatch_mutation() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE actor_id bigint;
BEGIN
  actor_id:=NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint;
  IF TG_OP='DELETE' OR NEW.id<>OLD.id OR NEW.tenant_id<>OLD.tenant_id
    OR NEW.facility_id<>OLD.facility_id
    OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
    OR NEW.plan_id<>OLD.plan_id OR NEW.worker_user_id<>OLD.worker_user_id
    OR NEW.activated_by_user_id<>OLD.activated_by_user_id
    OR NEW.activated_at<>OLD.activated_at OR OLD.status<>'active'
    OR NEW.revision<>OLD.revision+1
    OR (pg_trigger_depth()<=1 AND NEW.ended_by_user_id IS DISTINCT FROM actor_id)
    OR NEW.ended_at<transaction_timestamp()-INTERVAL '5 minutes'
    OR NEW.ended_at>clock_timestamp()+INTERVAL '1 minute' THEN
    RAISE EXCEPTION 'invalid work orchestration dispatch transition'
      USING ERRCODE='23514';
  END IF;
  IF NEW.status='completed' THEN
    IF pg_trigger_depth()<=1 OR NEW.cancellation_reason IS NOT NULL
      OR NEW.cancellation_note IS NOT NULL OR EXISTS(
        SELECT 1 FROM public.work_orchestration_dispatch_items item
        WHERE item.tenant_id=OLD.tenant_id AND item.dispatch_id=OLD.id
          AND item.state='reserved') THEN
      RAISE EXCEPTION 'dispatch cannot complete with reserved work'
        USING ERRCODE='23514';
    END IF;
  ELSIF NEW.status='cancelled' THEN
    IF NEW.cancellation_reason='scope_changed' AND pg_trigger_depth()>1 THEN
      IF public.work_orchestration_dispatch_worker_eligible(
        OLD.tenant_id,OLD.worker_user_id,OLD.facility_id,
        OLD.inventory_owner_id,NEW.ended_at) THEN
        RAISE EXCEPTION 'dispatch worker scope remains valid' USING ERRCODE='23514';
      END IF;
    ELSIF NEW.cancellation_reason='plan_invalidated' AND pg_trigger_depth()>1 THEN
      IF NOT EXISTS(SELECT 1 FROM public.work_orchestration_dispatch_items item
        WHERE item.tenant_id=OLD.tenant_id AND item.dispatch_id=OLD.id
          AND item.state='cancelled') THEN
        RAISE EXCEPTION 'dispatch plan remains executable' USING ERRCODE='23514';
      END IF;
    ELSIF NOT public.slotting_user_has_supervisor_permission(OLD.tenant_id,actor_id) THEN
      RAISE EXCEPTION 'dispatch cancellation requires supervisor permission'
        USING ERRCODE='23514';
    END IF;
    IF EXISTS(SELECT 1 FROM public.work_orchestration_dispatch_items item
      JOIN public.work_tasks task ON task.tenant_id=item.tenant_id
        AND task.id=item.work_task_id
      WHERE item.tenant_id=OLD.tenant_id AND item.dispatch_id=OLD.id
        AND item.state='reserved' AND task.status='in_progress') THEN
      RAISE EXCEPTION 'release in-progress work before cancelling its dispatch'
        USING ERRCODE='55000';
    END IF;
  ELSE
    RAISE EXCEPTION 'invalid work orchestration dispatch status'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.enforce_work_orchestration_dispatch_claim() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE reserved_dispatch record; worker_dispatch record; expected_task_id bigint;
BEGIN
  IF NEW.deleted IS NOT NULL OR NEW.status NOT IN ('assigned','in_progress')
    OR (NEW.status IS NOT DISTINCT FROM OLD.status
      AND NEW.assigned_user_id IS NOT DISTINCT FROM OLD.assigned_user_id) THEN
    RETURN NEW;
  END IF;
  SELECT dispatch.id,dispatch.worker_user_id INTO reserved_dispatch
  FROM public.work_orchestration_dispatch_items item
  JOIN public.work_orchestration_dispatches dispatch
    ON dispatch.tenant_id=item.tenant_id AND dispatch.id=item.dispatch_id
  WHERE item.tenant_id=NEW.tenant_id AND item.work_task_id=NEW.id
    AND item.state='reserved' AND dispatch.status='active';
  IF FOUND AND NEW.assigned_user_id IS DISTINCT FROM reserved_dispatch.worker_user_id THEN
    RAISE EXCEPTION 'work task is reserved by an active orchestration dispatch'
      USING ERRCODE='23514';
  END IF;
  SELECT dispatch.id INTO worker_dispatch
  FROM public.work_orchestration_dispatches dispatch
  WHERE dispatch.tenant_id=NEW.tenant_id AND dispatch.worker_user_id=NEW.assigned_user_id
    AND dispatch.status='active';
  IF FOUND THEN
    SELECT item.work_task_id INTO expected_task_id
    FROM public.work_orchestration_dispatch_items item
    WHERE item.tenant_id=NEW.tenant_id AND item.dispatch_id=worker_dispatch.id
      AND item.state='reserved' ORDER BY item.sequence LIMIT 1;
    IF expected_task_id IS DISTINCT FROM NEW.id THEN
      RAISE EXCEPTION 'claim the next task in the active orchestration dispatch'
        USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.advance_work_orchestration_dispatch() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE dispatch public.work_orchestration_dispatches%ROWTYPE;
DECLARE next_task record; actor_id bigint; transition_state text;
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status AND NEW.deleted IS NOT DISTINCT FROM OLD.deleted THEN
    RETURN NULL;
  END IF;
  SELECT target.* INTO dispatch
  FROM public.work_orchestration_dispatch_items item
  JOIN public.work_orchestration_dispatches target
    ON target.tenant_id=item.tenant_id AND target.id=item.dispatch_id
  WHERE item.tenant_id=NEW.tenant_id AND item.work_task_id=NEW.id
    AND item.state='reserved' AND target.status='active' FOR UPDATE OF target;
  IF NOT FOUND THEN RETURN NULL; END IF;
  actor_id:=COALESCE(
    NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint,
    NEW.completed_by,OLD.assigned_user_id);
  IF NOT public.work_orchestration_dispatch_worker_eligible(
    dispatch.tenant_id,dispatch.worker_user_id,dispatch.facility_id,
    dispatch.inventory_owner_id,transaction_timestamp()) THEN
    UPDATE public.work_orchestration_dispatches SET status='cancelled',revision=revision+1,
      ended_by_user_id=actor_id,ended_at=transaction_timestamp(),
      cancellation_reason='scope_changed',cancellation_note=NULL
    WHERE tenant_id=dispatch.tenant_id AND id=dispatch.id AND status='active';
    RETURN NULL;
  END IF;
  IF NEW.deleted IS NOT NULL OR NEW.status IN ('completed','cancelled') THEN
    transition_state:=CASE WHEN NEW.status='completed' THEN 'completed' ELSE 'cancelled' END;
    UPDATE public.work_orchestration_dispatch_items
    SET state=transition_state,released_at=transaction_timestamp()
    WHERE tenant_id=dispatch.tenant_id AND dispatch_id=dispatch.id
      AND work_task_id=NEW.id AND state='reserved';
  END IF;
  SELECT item.work_task_id,task.status,task.assigned_user_id INTO next_task
  FROM public.work_orchestration_dispatch_items item
  JOIN public.work_tasks task ON task.tenant_id=item.tenant_id AND task.id=item.work_task_id
  WHERE item.tenant_id=dispatch.tenant_id AND item.dispatch_id=dispatch.id
    AND item.state='reserved' ORDER BY item.sequence LIMIT 1;
  IF NOT FOUND THEN
    UPDATE public.work_orchestration_dispatches SET
      status=CASE WHEN EXISTS(SELECT 1 FROM public.work_orchestration_dispatch_items item
        WHERE item.tenant_id=dispatch.tenant_id AND item.dispatch_id=dispatch.id
          AND item.state='cancelled') THEN 'cancelled' ELSE 'completed' END,
      revision=revision+1,ended_by_user_id=actor_id,ended_at=transaction_timestamp(),
      cancellation_reason=CASE WHEN EXISTS(
        SELECT 1 FROM public.work_orchestration_dispatch_items item
        WHERE item.tenant_id=dispatch.tenant_id AND item.dispatch_id=dispatch.id
          AND item.state='cancelled') THEN 'plan_invalidated' ELSE NULL END
    WHERE tenant_id=dispatch.tenant_id AND id=dispatch.id AND status='active';
  ELSIF next_task.status='open' AND next_task.assigned_user_id IS NULL THEN
    UPDATE public.work_tasks SET status='assigned',assigned_user_id=dispatch.worker_user_id,
      modified=transaction_timestamp()
    WHERE tenant_id=dispatch.tenant_id AND id=next_task.work_task_id
      AND status='open' AND assigned_user_id IS NULL AND deleted IS NULL;
  END IF;
  RETURN NULL;
END $$;

CREATE FUNCTION public.close_work_orchestration_dispatch() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
BEGIN
  IF NEW.status='cancelled' AND OLD.status='active' THEN
    UPDATE public.work_orchestration_dispatch_items SET state='cancelled',released_at=NEW.ended_at
    WHERE tenant_id=NEW.tenant_id AND dispatch_id=NEW.id AND state='reserved';
    UPDATE public.work_tasks task SET status='open',assigned_user_id=NULL,modified=NEW.ended_at
    FROM public.work_orchestration_dispatch_items item
    WHERE item.tenant_id=NEW.tenant_id AND item.dispatch_id=NEW.id
      AND item.work_task_id=task.id AND task.tenant_id=NEW.tenant_id
      AND task.status='assigned' AND task.assigned_user_id=NEW.worker_user_id
      AND task.deleted IS NULL;
  END IF;
  RETURN NULL;
END $$;

CREATE FUNCTION public.emit_work_orchestration_dispatch_event() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE transition_name text; event_actor bigint; event_time timestamptz;
DECLARE ordering_value text; event_key_value text; sequence_value bigint;
BEGIN
  IF TG_OP='INSERT' THEN
    transition_name:='activated'; event_actor:=NEW.activated_by_user_id;
    event_time:=NEW.activated_at;
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    transition_name:=NEW.status; event_actor:=NEW.ended_by_user_id; event_time:=NEW.ended_at;
  ELSE RETURN NULL; END IF;
  ordering_value:='work_orchestration_dispatch:'||NEW.id::text;
  event_key_value:=ordering_value||':'||transition_name;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'outbox-sequence:'||NEW.tenant_id::text||':'||ordering_value,0));
  INSERT INTO public.outbox_event_keys(tenant_id,event_key,created)
  VALUES (NEW.tenant_id,event_key_value,clock_timestamp());
  INSERT INTO public.outbox_aggregate_sequences(tenant_id,ordering_key,last_sequence,updated)
  VALUES (NEW.tenant_id,ordering_value,1,clock_timestamp())
  ON CONFLICT (tenant_id,ordering_key) DO UPDATE
  SET last_sequence=public.outbox_aggregate_sequences.last_sequence+1,
      updated=clock_timestamp()
  RETURNING last_sequence INTO sequence_value;
  INSERT INTO public.outbox_events(
    tenant_id,inventory_owner_id,facility_id,actor_user_id,created,event_key,
    aggregate_type,aggregate_id,ordering_key,aggregate_sequence,event_type,
    schema_version,payload,occurred_at,available_at)
  VALUES (NEW.tenant_id,NEW.inventory_owner_id,NEW.facility_id,event_actor,
    clock_timestamp(),event_key_value,'work_orchestration_dispatch',NEW.id::text,
    ordering_value,sequence_value,
    'optimization.work_orchestration.dispatch.'||transition_name,1,
    jsonb_build_object('dispatch_id',NEW.id,'plan_id',NEW.plan_id,
      'worker_user_id',NEW.worker_user_id,'status',NEW.status,'revision',NEW.revision,
      'facility_id',NEW.facility_id,'inventory_owner_id',NEW.inventory_owner_id,
      'activated_at',NEW.activated_at,'ended_at',NEW.ended_at,
      'cancellation_reason',NEW.cancellation_reason),event_time,clock_timestamp());
  RETURN NULL;
END $$;

CREATE TRIGGER work_orchestration_dispatches_validate BEFORE INSERT
ON public.work_orchestration_dispatches FOR EACH ROW
EXECUTE FUNCTION public.validate_work_orchestration_dispatch_insert();
CREATE TRIGGER work_orchestration_dispatches_guard BEFORE UPDATE OR DELETE
ON public.work_orchestration_dispatches FOR EACH ROW
EXECUTE FUNCTION public.guard_work_orchestration_dispatch_mutation();
CREATE TRIGGER work_orchestration_dispatches_close AFTER UPDATE OF status
ON public.work_orchestration_dispatches FOR EACH ROW
EXECUTE FUNCTION public.close_work_orchestration_dispatch();
CREATE TRIGGER work_orchestration_dispatches_emit AFTER INSERT OR UPDATE OF status
ON public.work_orchestration_dispatches FOR EACH ROW
EXECUTE FUNCTION public.emit_work_orchestration_dispatch_event();
CREATE CONSTRAINT TRIGGER work_orchestration_dispatch_require_items
AFTER INSERT ON public.work_orchestration_dispatches DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
EXECUTE FUNCTION public.require_work_orchestration_dispatch_items();
CREATE TRIGGER work_orchestration_dispatch_items_validate BEFORE INSERT
ON public.work_orchestration_dispatch_items FOR EACH ROW
EXECUTE FUNCTION public.validate_work_orchestration_dispatch_item_insert();
CREATE TRIGGER work_orchestration_dispatch_items_guard BEFORE UPDATE OR DELETE
ON public.work_orchestration_dispatch_items FOR EACH ROW
EXECUTE FUNCTION public.guard_work_orchestration_dispatch_item_mutation();
CREATE TRIGGER work_tasks_enforce_orchestration_dispatch BEFORE UPDATE OF status,assigned_user_id
ON public.work_tasks FOR EACH ROW
EXECUTE FUNCTION public.enforce_work_orchestration_dispatch_claim();
CREATE TRIGGER work_tasks_advance_orchestration_dispatch AFTER UPDATE OF status,deleted
ON public.work_tasks FOR EACH ROW
EXECUTE FUNCTION public.advance_work_orchestration_dispatch();

ALTER TABLE public.work_orchestration_dispatches ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.work_orchestration_dispatches FORCE ROW LEVEL SECURITY;
ALTER TABLE public.work_orchestration_dispatch_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.work_orchestration_dispatch_items FORCE ROW LEVEL SECURITY;
CREATE POLICY work_orchestration_dispatches_tenant_isolation
ON public.work_orchestration_dispatches
USING (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint)
WITH CHECK (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint);
CREATE POLICY work_orchestration_dispatch_items_tenant_isolation
ON public.work_orchestration_dispatch_items
USING (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint)
WITH CHECK (tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint);

GRANT SELECT,INSERT,UPDATE ON public.work_orchestration_dispatches TO wareboxes_app;
GRANT SELECT,INSERT,UPDATE ON public.work_orchestration_dispatch_items TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.work_orchestration_dispatches_id_seq TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.work_orchestration_dispatch_items_id_seq TO wareboxes_app;

REVOKE ALL ON FUNCTION public.work_orchestration_dispatch_worker_eligible(
  bigint,bigint,bigint,bigint,timestamptz) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_work_orchestration_dispatch_insert() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_work_orchestration_dispatch_item_insert() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_work_orchestration_dispatch_item_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_work_orchestration_dispatch_items() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_work_orchestration_dispatch_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.enforce_work_orchestration_dispatch_claim() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.advance_work_orchestration_dispatch() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.close_work_orchestration_dispatch() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.emit_work_orchestration_dispatch_event() FROM PUBLIC;

-- Replenishment planning resolves the active inherited decision table while the
-- item-specific operational policy remains the source/destination and stocking basis.
ALTER TABLE public.replenishment_plan_runs
ADD CONSTRAINT replenishment_plan_runs_decision_configuration_fkey
FOREIGN KEY (tenant_id,decision_configuration_id)
REFERENCES public.configuration_versions(tenant_id,id);
CREATE INDEX replenishment_plan_runs_decision_configuration_idx
ON public.replenishment_plan_runs(tenant_id,decision_configuration_id)
WHERE decision_configuration_id IS NOT NULL;

CREATE FUNCTION public.validate_replenishment_decision_policy_snapshot() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE configuration_row public.configuration_versions%ROWTYPE;
DECLARE resolved_configuration_id bigint;
DECLARE calculated_hash text;
DECLARE scope_component text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(format(
    'configuration-kind:%s:replenishment',NEW.tenant_id),0));
  SELECT configuration.id INTO resolved_configuration_id
  FROM public.configuration_versions configuration
  WHERE configuration.tenant_id=NEW.tenant_id
    AND configuration.kind='replenishment' AND configuration.status='active'
    AND configuration.activated_at<=NEW.planned_at
    AND configuration.effective_from<=NEW.planned_at
    AND (configuration.effective_until IS NULL OR configuration.effective_until>NEW.planned_at)
    AND (configuration.inventory_owner_id IS NULL
      OR configuration.inventory_owner_id=NEW.inventory_owner_id)
    AND (configuration.facility_id IS NULL OR configuration.facility_id=NEW.facility_id)
  ORDER BY CASE configuration.scope_level
    WHEN 'owner_facility' THEN 2
    WHEN 'inventory_owner' THEN 1
    WHEN 'facility' THEN 1
    ELSE 0 END DESC,
    configuration.effective_from DESC,configuration.revision DESC,configuration.id DESC
  LIMIT 1;

  IF NEW.decision_policy_source='product_default' THEN
    IF resolved_configuration_id IS NOT NULL THEN
      RAISE EXCEPTION 'replenishment product default is not effective'
        USING ERRCODE='23514';
    END IF;
    scope_component:='-';
  ELSE
    SELECT * INTO configuration_row FROM public.configuration_versions configuration
    WHERE configuration.tenant_id=NEW.tenant_id
      AND configuration.id=NEW.decision_configuration_id;
    IF configuration_row.id IS NULL
      OR resolved_configuration_id IS DISTINCT FROM configuration_row.id
      OR configuration_row.kind<>'replenishment' OR configuration_row.status<>'active'
      OR configuration_row.activated_at>NEW.planned_at
      OR configuration_row.effective_from>NEW.planned_at
      OR (configuration_row.effective_until IS NOT NULL
        AND configuration_row.effective_until<=NEW.planned_at)
      OR configuration_row.revision<>NEW.decision_configuration_revision
      OR configuration_row.scope_level<>NEW.decision_scope_level
      OR configuration_row.inventory_owner_id IS DISTINCT FROM NEW.decision_inventory_owner_id
      OR configuration_row.facility_id IS DISTINCT FROM NEW.decision_facility_id
      OR configuration_row.definition<>jsonb_build_object(
        'kind','replenishment','minimum_percent',NEW.decision_minimum_percent,
        'target_percent',NEW.decision_target_percent,
        'include_inbound_projection',NEW.include_inbound_projection) THEN
      RAISE EXCEPTION 'replenishment configuration snapshot is stale or inapplicable'
        USING ERRCODE='23514';
    END IF;
    scope_component:=CASE NEW.decision_scope_level
      WHEN 'tenant' THEN 'tenant'
      WHEN 'inventory_owner' THEN 'inventory_owner:'||NEW.decision_inventory_owner_id::text
      WHEN 'facility' THEN 'facility:'||NEW.decision_facility_id::text
      WHEN 'owner_facility' THEN 'owner_facility:'||NEW.decision_inventory_owner_id::text
        ||':'||NEW.decision_facility_id::text
      ELSE NULL END;
  END IF;
  calculated_hash:=encode(sha256(convert_to(
    'replenishment-decision-policy-v1|'||NEW.decision_policy_source||'|'
    ||COALESCE(NEW.decision_configuration_id::text,'-')||'|'
    ||COALESCE(NEW.decision_configuration_revision::text,'-')||'|'
    ||COALESCE(NEW.decision_minimum_percent::text,'-')||'|'
    ||COALESCE(NEW.decision_target_percent::text,'-')||'|'
    ||NEW.operational_minimum_qty::text||'|'||NEW.operational_target_qty::text||'|'
    ||NEW.minimum_qty::text||'|'||NEW.target_qty::text||'|'
    ||NEW.include_inbound_projection::text||'|'||scope_component,'UTF8')),'hex');
  IF calculated_hash IS DISTINCT FROM NEW.decision_policy_hash THEN
    RAISE EXCEPTION 'replenishment decision policy hash does not match its evidence'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
  RAISE EXCEPTION 'replenishment decision policy has an invalid typed value'
    USING ERRCODE='23514';
END $$;

CREATE TRIGGER replenishment_plan_runs_decision_policy_validate
BEFORE INSERT ON public.replenishment_plan_runs FOR EACH ROW
EXECUTE FUNCTION public.validate_replenishment_decision_policy_snapshot();
REVOKE ALL ON FUNCTION public.validate_replenishment_decision_policy_snapshot() FROM PUBLIC;

-- Pick scan policy is resolved once at first claim and remains immutable through
-- release, reclaim, confirmation, and reversal. Product defaults preserve all
-- pre-configuration scan requirements.
ALTER TABLE public.pick_tasks
  ADD COLUMN pick_policy_source text,
  ADD COLUMN pick_configuration_id bigint,
  ADD COLUMN pick_configuration_revision bigint,
  ADD COLUMN pick_scope_level text,
  ADD COLUMN pick_inventory_owner_id bigint,
  ADD COLUMN pick_facility_id bigint,
  ADD COLUMN require_source_location_scan boolean,
  ADD COLUMN require_item_scan boolean,
  ADD COLUMN require_destination_container_scan boolean,
  ADD COLUMN pick_policy_hash text,
  ADD CONSTRAINT pick_tasks_policy_state_check CHECK (
    (pick_policy_source IS NULL
      AND pick_configuration_id IS NULL AND pick_configuration_revision IS NULL
      AND pick_scope_level IS NULL AND pick_inventory_owner_id IS NULL
      AND pick_facility_id IS NULL AND require_source_location_scan IS NULL
      AND require_item_scan IS NULL AND require_destination_container_scan IS NULL
      AND pick_policy_hash IS NULL)
    OR
    (pick_policy_source IN ('product_default','configuration')
      AND require_source_location_scan IS NOT NULL AND require_item_scan IS NOT NULL
      AND require_destination_container_scan IS NOT NULL
      AND pick_policy_hash~'^[0-9a-f]{64}$'
      AND ((pick_policy_source='product_default'
        AND pick_configuration_id IS NULL AND pick_configuration_revision IS NULL
        AND pick_scope_level IS NULL AND pick_inventory_owner_id IS NULL
        AND pick_facility_id IS NULL AND require_source_location_scan
        AND require_item_scan AND require_destination_container_scan)
      OR (pick_policy_source='configuration'
        AND pick_configuration_id IS NOT NULL AND pick_configuration_revision>0
        AND ((pick_scope_level='tenant' AND pick_inventory_owner_id IS NULL
              AND pick_facility_id IS NULL)
          OR (pick_scope_level='inventory_owner' AND pick_inventory_owner_id IS NOT NULL
              AND pick_facility_id IS NULL)
          OR (pick_scope_level='facility' AND pick_inventory_owner_id IS NULL
              AND pick_facility_id IS NOT NULL)
          OR (pick_scope_level='owner_facility' AND pick_inventory_owner_id IS NOT NULL
              AND pick_facility_id IS NOT NULL))))));
ALTER TABLE public.pick_tasks
  ADD CONSTRAINT pick_tasks_policy_configuration_fkey
  FOREIGN KEY (tenant_id,pick_configuration_id)
  REFERENCES public.configuration_versions(tenant_id,id);
CREATE INDEX pick_tasks_policy_configuration_idx
ON public.pick_tasks(tenant_id,pick_configuration_id)
WHERE pick_configuration_id IS NOT NULL;

ALTER TABLE public.pick_confirmations
  ADD COLUMN pick_policy_source text NOT NULL,
  ADD COLUMN pick_configuration_id bigint,
  ADD COLUMN pick_configuration_revision bigint,
  ADD COLUMN pick_scope_level text,
  ADD COLUMN pick_inventory_owner_id bigint,
  ADD COLUMN pick_facility_id bigint,
  ADD COLUMN require_source_location_scan boolean NOT NULL,
  ADD COLUMN require_item_scan boolean NOT NULL,
  ADD COLUMN require_destination_container_scan boolean NOT NULL,
  ADD COLUMN pick_policy_hash text NOT NULL,
  ADD COLUMN source_location_scan_verified boolean NOT NULL,
  ADD COLUMN item_scan_verified boolean NOT NULL,
  ADD COLUMN destination_container_scan_verified boolean NOT NULL,
  ADD CONSTRAINT pick_confirmations_policy_identity_check CHECK (
    pick_policy_source IN ('product_default','configuration')
    AND pick_policy_hash~'^[0-9a-f]{64}$'
    AND ((pick_policy_source='product_default'
      AND pick_configuration_id IS NULL AND pick_configuration_revision IS NULL
      AND pick_scope_level IS NULL AND pick_inventory_owner_id IS NULL
      AND pick_facility_id IS NULL AND require_source_location_scan
      AND require_item_scan AND require_destination_container_scan)
    OR (pick_policy_source='configuration'
      AND pick_configuration_id IS NOT NULL AND pick_configuration_revision>0
      AND ((pick_scope_level='tenant' AND pick_inventory_owner_id IS NULL
            AND pick_facility_id IS NULL)
        OR (pick_scope_level='inventory_owner' AND pick_inventory_owner_id IS NOT NULL
            AND pick_facility_id IS NULL)
        OR (pick_scope_level='facility' AND pick_inventory_owner_id IS NULL
            AND pick_facility_id IS NOT NULL)
        OR (pick_scope_level='owner_facility' AND pick_inventory_owner_id IS NOT NULL
            AND pick_facility_id IS NOT NULL))))),
  ADD CONSTRAINT pick_confirmations_required_scan_evidence_check CHECK (
    (NOT require_source_location_scan OR source_location_scan_verified)
    AND (NOT require_item_scan OR item_scan_verified)
    AND (NOT require_destination_container_scan OR destination_container_scan_verified));
ALTER TABLE public.pick_confirmations
  ADD CONSTRAINT pick_confirmations_policy_configuration_fkey
  FOREIGN KEY (tenant_id,pick_configuration_id)
  REFERENCES public.configuration_versions(tenant_id,id);
CREATE INDEX pick_confirmations_policy_configuration_idx
ON public.pick_confirmations(tenant_id,pick_configuration_id)
WHERE pick_configuration_id IS NOT NULL;

CREATE FUNCTION public.validate_pick_task_policy_snapshot() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE configuration_row public.configuration_versions%ROWTYPE;
DECLARE resolved_configuration_id bigint;
DECLARE scope_component text;
DECLARE calculated_hash text;
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.pick_policy_source IS NOT NULL THEN
      RAISE EXCEPTION 'pick policy is frozen only when work is first claimed'
        USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.pick_policy_source IS NOT NULL THEN
    IF ROW(NEW.pick_policy_source,NEW.pick_configuration_id,
      NEW.pick_configuration_revision,NEW.pick_scope_level,
      NEW.pick_inventory_owner_id,NEW.pick_facility_id,
      NEW.require_source_location_scan,NEW.require_item_scan,
      NEW.require_destination_container_scan,NEW.pick_policy_hash)
      IS DISTINCT FROM
      ROW(OLD.pick_policy_source,OLD.pick_configuration_id,
      OLD.pick_configuration_revision,OLD.pick_scope_level,
      OLD.pick_inventory_owner_id,OLD.pick_facility_id,
      OLD.require_source_location_scan,OLD.require_item_scan,
      OLD.require_destination_container_scan,OLD.pick_policy_hash) THEN
      RAISE EXCEPTION 'frozen Pick policy evidence is immutable' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.status='open' AND NEW.status='cancelled'
    AND NEW.pick_policy_source IS NULL THEN
    RETURN NEW;
  END IF;

  IF OLD.status<>'open' OR NEW.status<>'in_progress' OR NEW.claimed_at IS NULL
    OR NEW.pick_policy_source IS NULL THEN
    RAISE EXCEPTION 'first Pick policy snapshot requires a claim transition'
      USING ERRCODE='55000';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(format(
    'configuration-kind:%s:pick',NEW.tenant_id),0));
  SELECT configuration.id INTO resolved_configuration_id
  FROM public.configuration_versions configuration
  WHERE configuration.tenant_id=NEW.tenant_id AND configuration.kind='pick'
    AND configuration.status='active' AND configuration.activated_at<=NEW.claimed_at
    AND configuration.effective_from<=NEW.claimed_at
    AND (configuration.effective_until IS NULL OR configuration.effective_until>NEW.claimed_at)
    AND (configuration.inventory_owner_id IS NULL
      OR configuration.inventory_owner_id=NEW.inventory_owner_id)
    AND (configuration.facility_id IS NULL OR configuration.facility_id=NEW.facility_id)
  ORDER BY CASE configuration.scope_level
    WHEN 'owner_facility' THEN 2 WHEN 'inventory_owner' THEN 1
    WHEN 'facility' THEN 1 ELSE 0 END DESC,
    configuration.effective_from DESC,configuration.revision DESC,configuration.id DESC
  LIMIT 1;

  IF NEW.pick_policy_source='product_default' THEN
    IF resolved_configuration_id IS NOT NULL OR NOT NEW.require_source_location_scan
      OR NOT NEW.require_item_scan OR NOT NEW.require_destination_container_scan THEN
      RAISE EXCEPTION 'Pick product default is not effective' USING ERRCODE='23514';
    END IF;
    scope_component:='-';
  ELSIF NEW.pick_policy_source='configuration' THEN
    SELECT * INTO configuration_row FROM public.configuration_versions configuration
    WHERE configuration.tenant_id=NEW.tenant_id
      AND configuration.id=NEW.pick_configuration_id;
    IF configuration_row.id IS NULL
      OR resolved_configuration_id IS DISTINCT FROM configuration_row.id
      OR configuration_row.kind<>'pick' OR configuration_row.status<>'active'
      OR configuration_row.revision<>NEW.pick_configuration_revision
      OR configuration_row.scope_level<>NEW.pick_scope_level
      OR configuration_row.inventory_owner_id IS DISTINCT FROM NEW.pick_inventory_owner_id
      OR configuration_row.facility_id IS DISTINCT FROM NEW.pick_facility_id
      OR configuration_row.definition<>jsonb_build_object(
        'kind','pick','require_source_location_scan',NEW.require_source_location_scan,
        'require_item_scan',NEW.require_item_scan,
        'require_destination_container_scan',NEW.require_destination_container_scan) THEN
      RAISE EXCEPTION 'Pick configuration snapshot is stale or inapplicable'
        USING ERRCODE='23514';
    END IF;
    scope_component:=CASE NEW.pick_scope_level
      WHEN 'tenant' THEN 'tenant'
      WHEN 'inventory_owner' THEN 'inventory_owner:'||NEW.pick_inventory_owner_id::text
      WHEN 'facility' THEN 'facility:'||NEW.pick_facility_id::text
      WHEN 'owner_facility' THEN 'owner_facility:'||NEW.pick_inventory_owner_id::text
        ||':'||NEW.pick_facility_id::text ELSE NULL END;
  ELSE
    RAISE EXCEPTION 'Pick policy source is invalid' USING ERRCODE='23514';
  END IF;
  calculated_hash:=encode(sha256(convert_to(
    'pick-decision-policy-v1|'||NEW.pick_policy_source||'|'
    ||COALESCE(NEW.pick_configuration_id::text,'-')||'|'
    ||COALESCE(NEW.pick_configuration_revision::text,'-')||'|'
    ||scope_component||'|'||NEW.require_source_location_scan::text||'|'
    ||NEW.require_item_scan::text||'|'||NEW.require_destination_container_scan::text,
    'UTF8')),'hex');
  IF calculated_hash IS DISTINCT FROM NEW.pick_policy_hash THEN
    RAISE EXCEPTION 'Pick policy hash does not match its evidence' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.validate_pick_confirmation_policy_evidence() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE task_row public.pick_tasks%ROWTYPE;
DECLARE matching_container_count bigint;
BEGIN
  SELECT * INTO task_row FROM public.pick_tasks task
  WHERE task.tenant_id=NEW.tenant_id AND task.id=NEW.task_id FOR SHARE;
  IF task_row.id IS NULL OR task_row.pick_policy_source IS NULL
    OR ROW(NEW.pick_policy_source,NEW.pick_configuration_id,
      NEW.pick_configuration_revision,NEW.pick_scope_level,
      NEW.pick_inventory_owner_id,NEW.pick_facility_id,
      NEW.require_source_location_scan,NEW.require_item_scan,
      NEW.require_destination_container_scan,NEW.pick_policy_hash)
      IS DISTINCT FROM
      ROW(task_row.pick_policy_source,task_row.pick_configuration_id,
      task_row.pick_configuration_revision,task_row.pick_scope_level,
      task_row.pick_inventory_owner_id,task_row.pick_facility_id,
      task_row.require_source_location_scan,task_row.require_item_scan,
      task_row.require_destination_container_scan,task_row.pick_policy_hash) THEN
    RAISE EXCEPTION 'pick confirmation policy does not match the claimed task'
      USING ERRCODE='23514';
  END IF;
  IF NOT NEW.destination_container_scan_verified THEN
    SELECT COUNT(*) INTO matching_container_count
    FROM public.outbound_order_containers container
    WHERE container.tenant_id=NEW.tenant_id
      AND container.inventory_owner_id=NEW.inventory_owner_id
      AND container.facility_id=NEW.facility_id
      AND container.order_release_id=NEW.order_release_id
      AND container.order_id=NEW.order_id
      AND container.destination_location_id=NEW.destination_location_id
      AND container.license_plate_id=NEW.destination_license_plate_id
      AND container.released_at IS NULL;
    IF NEW.require_destination_container_scan OR matching_container_count<>1 THEN
      RAISE EXCEPTION 'unscanned destination requires one existing order container'
        USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER pick_tasks_policy_snapshot_validate
BEFORE INSERT OR UPDATE ON public.pick_tasks FOR EACH ROW
EXECUTE FUNCTION public.validate_pick_task_policy_snapshot();
CREATE TRIGGER pick_confirmations_policy_evidence_validate
BEFORE INSERT ON public.pick_confirmations FOR EACH ROW
EXECUTE FUNCTION public.validate_pick_confirmation_policy_evidence();
REVOKE ALL ON FUNCTION public.validate_pick_task_policy_snapshot() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_pick_confirmation_policy_evidence() FROM PUBLIC;

-- Pack policy is selected once when the order enters a physical station. The
-- snapshot governs station admission and carton measurement for the session's
-- complete lifetime; mixed orders means concurrent order sessions at a station,
-- never mixed ownership inside a carton.
ALTER TABLE public.packing_sessions
  ADD COLUMN pack_policy_source text NOT NULL,
  ADD COLUMN pack_configuration_id bigint,
  ADD COLUMN pack_configuration_revision bigint,
  ADD COLUMN pack_scope_level text,
  ADD COLUMN pack_inventory_owner_id bigint,
  ADD COLUMN pack_facility_id bigint,
  ADD COLUMN require_station_scan boolean NOT NULL,
  ADD COLUMN require_weight boolean NOT NULL,
  ADD COLUMN allow_mixed_orders boolean NOT NULL,
  ADD COLUMN pack_policy_hash text NOT NULL,
  ADD COLUMN station_scan_value text,
  ADD COLUMN station_scan_verified boolean NOT NULL,
  ADD CONSTRAINT packing_sessions_pack_policy_identity_check CHECK (
    pack_policy_source IN ('product_default','configuration')
    AND pack_policy_hash~'^[0-9a-f]{64}$'
    AND ((pack_policy_source='product_default'
      AND pack_configuration_id IS NULL AND pack_configuration_revision IS NULL
      AND pack_scope_level IS NULL AND pack_inventory_owner_id IS NULL
      AND pack_facility_id IS NULL AND NOT require_station_scan
      AND NOT require_weight AND allow_mixed_orders)
    OR (pack_policy_source='configuration'
      AND pack_configuration_id IS NOT NULL AND pack_configuration_revision>0
      AND ((pack_scope_level='tenant' AND pack_inventory_owner_id IS NULL
            AND pack_facility_id IS NULL)
        OR (pack_scope_level='inventory_owner' AND pack_inventory_owner_id IS NOT NULL
            AND pack_facility_id IS NULL)
        OR (pack_scope_level='facility' AND pack_inventory_owner_id IS NULL
            AND pack_facility_id IS NOT NULL)
        OR (pack_scope_level='owner_facility' AND pack_inventory_owner_id IS NOT NULL
            AND pack_facility_id IS NOT NULL))))),
  ADD CONSTRAINT packing_sessions_station_scan_evidence_check CHECK (
    (station_scan_verified AND station_scan_value IS NOT NULL)
    OR (NOT station_scan_verified AND station_scan_value IS NULL)),
  ADD CONSTRAINT packing_sessions_required_station_scan_check CHECK (
    NOT require_station_scan OR station_scan_verified),
  ADD CONSTRAINT packing_sessions_station_scan_value_check CHECK (
    station_scan_value IS NULL OR
    (station_scan_value=btrim(station_scan_value) AND station_scan_value<>''
      AND char_length(station_scan_value)<=200));
ALTER TABLE public.packing_sessions
  ADD CONSTRAINT packing_sessions_pack_configuration_fkey
  FOREIGN KEY (tenant_id,pack_configuration_id)
  REFERENCES public.configuration_versions(tenant_id,id);
CREATE INDEX packing_sessions_pack_configuration_idx
ON public.packing_sessions(tenant_id,pack_configuration_id)
WHERE pack_configuration_id IS NOT NULL;

CREATE FUNCTION public.validate_pack_policy_snapshot() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE configuration_row public.configuration_versions%ROWTYPE;
DECLARE resolved_configuration_id bigint;
DECLARE scope_component text;
DECLARE calculated_hash text;
DECLARE station_barcode text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(format(
    'configuration-kind:%s:pack',NEW.tenant_id),0));
  SELECT configuration.id INTO resolved_configuration_id
  FROM public.configuration_versions configuration
  WHERE configuration.tenant_id=NEW.tenant_id AND configuration.kind='pack'
    AND configuration.status='active' AND configuration.activated_at<=NEW.started_at
    AND configuration.effective_from<=NEW.started_at
    AND (configuration.effective_until IS NULL OR configuration.effective_until>NEW.started_at)
    AND (configuration.inventory_owner_id IS NULL
      OR configuration.inventory_owner_id=NEW.inventory_owner_id)
    AND (configuration.facility_id IS NULL OR configuration.facility_id=NEW.facility_id)
  ORDER BY CASE configuration.scope_level
    WHEN 'owner_facility' THEN 2 WHEN 'inventory_owner' THEN 1
    WHEN 'facility' THEN 1 ELSE 0 END DESC,
    configuration.effective_from DESC,configuration.revision DESC,configuration.id DESC
  LIMIT 1;

  IF NEW.pack_policy_source='product_default' THEN
    IF resolved_configuration_id IS NOT NULL OR NEW.require_station_scan
      OR NEW.require_weight OR NOT NEW.allow_mixed_orders THEN
      RAISE EXCEPTION 'Pack product default is not effective' USING ERRCODE='23514';
    END IF;
    scope_component:='-';
  ELSIF NEW.pack_policy_source='configuration' THEN
    SELECT * INTO configuration_row FROM public.configuration_versions configuration
    WHERE configuration.tenant_id=NEW.tenant_id
      AND configuration.id=NEW.pack_configuration_id;
    IF configuration_row.id IS NULL
      OR resolved_configuration_id IS DISTINCT FROM configuration_row.id
      OR configuration_row.kind<>'pack' OR configuration_row.status<>'active'
      OR configuration_row.revision<>NEW.pack_configuration_revision
      OR configuration_row.scope_level<>NEW.pack_scope_level
      OR configuration_row.inventory_owner_id IS DISTINCT FROM NEW.pack_inventory_owner_id
      OR configuration_row.facility_id IS DISTINCT FROM NEW.pack_facility_id
      OR configuration_row.definition<>jsonb_build_object(
        'kind','pack','require_station_scan',NEW.require_station_scan,
        'require_weight',NEW.require_weight,
        'allow_mixed_orders',NEW.allow_mixed_orders) THEN
      RAISE EXCEPTION 'Pack configuration snapshot is stale or inapplicable'
        USING ERRCODE='23514';
    END IF;
    scope_component:=CASE NEW.pack_scope_level
      WHEN 'tenant' THEN 'tenant'
      WHEN 'inventory_owner' THEN 'inventory_owner:'||NEW.pack_inventory_owner_id::text
      WHEN 'facility' THEN 'facility:'||NEW.pack_facility_id::text
      WHEN 'owner_facility' THEN 'owner_facility:'||NEW.pack_inventory_owner_id::text
        ||':'||NEW.pack_facility_id::text ELSE NULL END;
  ELSE
    RAISE EXCEPTION 'Pack policy source is invalid' USING ERRCODE='23514';
  END IF;
  calculated_hash:=encode(sha256(convert_to(
    'pack-decision-policy-v1|'||NEW.pack_policy_source||'|'
    ||COALESCE(NEW.pack_configuration_id::text,'-')||'|'
    ||COALESCE(NEW.pack_configuration_revision::text,'-')||'|'
    ||scope_component||'|'||NEW.require_station_scan::text||'|'
    ||NEW.require_weight::text||'|'||NEW.allow_mixed_orders::text,
    'UTF8')),'hex');
  IF calculated_hash IS DISTINCT FROM NEW.pack_policy_hash THEN
    RAISE EXCEPTION 'Pack policy hash does not match its evidence' USING ERRCODE='23514';
  END IF;

  SELECT location.barcode INTO station_barcode FROM public.locations location
  WHERE location.tenant_id=NEW.tenant_id AND location.facility_id=NEW.facility_id
    AND location.id=NEW.packing_location_id AND location.deleted IS NULL
    AND location.active AND NOT location.pickable AND lower(location.type)='packing'
    AND location.barcode IS NOT NULL AND btrim(location.barcode)<>''
  FOR SHARE;
  IF NEW.station_scan_verified
    AND NEW.station_scan_value IS DISTINCT FROM station_barcode THEN
    RAISE EXCEPTION 'Pack station scan does not match its location' USING ERRCODE='23514';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(format(
    'packing-station:%s:%s:%s',NEW.tenant_id,NEW.facility_id,NEW.packing_location_id),0));
  IF EXISTS (
    SELECT 1 FROM public.packing_sessions session
    WHERE session.tenant_id=NEW.tenant_id AND session.facility_id=NEW.facility_id
      AND session.packing_location_id=NEW.packing_location_id AND session.state='open'
      AND (NOT NEW.allow_mixed_orders OR NOT session.allow_mixed_orders)
  ) THEN
    RAISE EXCEPTION 'Pack policy reserves this station for one order'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.guard_pack_policy_snapshot() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF ROW(NEW.pack_policy_source,NEW.pack_configuration_id,
    NEW.pack_configuration_revision,NEW.pack_scope_level,
    NEW.pack_inventory_owner_id,NEW.pack_facility_id,
    NEW.require_station_scan,NEW.require_weight,NEW.allow_mixed_orders,
    NEW.pack_policy_hash,NEW.station_scan_value,NEW.station_scan_verified)
    IS DISTINCT FROM
    ROW(OLD.pack_policy_source,OLD.pack_configuration_id,
    OLD.pack_configuration_revision,OLD.pack_scope_level,
    OLD.pack_inventory_owner_id,OLD.pack_facility_id,
    OLD.require_station_scan,OLD.require_weight,OLD.allow_mixed_orders,
    OLD.pack_policy_hash,OLD.station_scan_value,OLD.station_scan_verified) THEN
    RAISE EXCEPTION 'frozen Pack policy evidence is immutable' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.validate_pack_carton_weight() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
BEGIN
  IF NEW.state='closed' AND OLD.state<>'closed' AND EXISTS (
    SELECT 1 FROM public.packing_sessions session
    WHERE session.tenant_id=NEW.tenant_id AND session.id=NEW.packing_session_id
      AND session.require_weight AND NEW.weight_g IS NULL
  ) THEN
    RAISE EXCEPTION 'effective Pack policy requires carton weight' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER packing_sessions_pack_policy_validate
BEFORE INSERT ON public.packing_sessions FOR EACH ROW
EXECUTE FUNCTION public.validate_pack_policy_snapshot();
CREATE TRIGGER packing_sessions_pack_policy_guard
BEFORE UPDATE ON public.packing_sessions FOR EACH ROW
EXECUTE FUNCTION public.guard_pack_policy_snapshot();
CREATE TRIGGER cartons_pack_weight_validate
BEFORE UPDATE ON public.cartons FOR EACH ROW
EXECUTE FUNCTION public.validate_pack_carton_weight();
REVOKE ALL ON FUNCTION public.validate_pack_policy_snapshot() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_pack_policy_snapshot() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_pack_carton_weight() FROM PUBLIC;

-- Cart-routed picking. Existing pick tasks remain the immutable allocation-backed
-- execution unit; these aggregates bind either a general cluster route or a
-- homogeneous same-source item batch to physical order slots.
CREATE TABLE public.pick_carts (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES public.tenants(id),
  facility_id bigint NOT NULL,
  barcode text NOT NULL,
  name text NOT NULL,
  status text NOT NULL DEFAULT 'active' CHECK(status IN('active','out_of_service','retired')),
  revision bigint NOT NULL DEFAULT 1 CHECK(revision>0),
  created_by_user_id bigint NOT NULL,
  created_at timestamptz NOT NULL,
  status_changed_by_user_id bigint,
  status_changed_at timestamptz,
  CHECK(barcode=btrim(barcode) AND barcode<>'' AND char_length(barcode)<=80),
  CHECK(name=btrim(name) AND name<>'' AND char_length(name)<=120),
  CHECK((revision=1 AND status_changed_by_user_id IS NULL AND status_changed_at IS NULL)
    OR (revision>1 AND status_changed_by_user_id IS NOT NULL AND status_changed_at IS NOT NULL)),
  UNIQUE(tenant_id,facility_id,id),
  UNIQUE(tenant_id,facility_id,barcode),
  FOREIGN KEY(tenant_id,facility_id) REFERENCES public.facilities(tenant_id,id),
  FOREIGN KEY(tenant_id,created_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  FOREIGN KEY(tenant_id,status_changed_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id)
);

CREATE TABLE public.pick_cart_slots (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES public.tenants(id),
  facility_id bigint NOT NULL,
  cart_id bigint NOT NULL,
  code text NOT NULL,
  sequence bigint NOT NULL CHECK(sequence>0),
  created_at timestamptz NOT NULL,
  CHECK(code=upper(btrim(code)) AND code<>'' AND char_length(code)<=40),
  UNIQUE(tenant_id,facility_id,cart_id,id),
  UNIQUE(tenant_id,facility_id,cart_id,code),
  UNIQUE(tenant_id,facility_id,cart_id,sequence),
  FOREIGN KEY(tenant_id,facility_id,cart_id)
    REFERENCES public.pick_carts(tenant_id,facility_id,id)
);

CREATE TABLE public.pick_clusters (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES public.tenants(id),
  inventory_owner_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  cart_id bigint NOT NULL,
  mode text NOT NULL CHECK(mode IN('cluster_cart','batch_cart')),
  batch_source_inventory_balance_id bigint,
  batch_source_location_id bigint,
  batch_item_batch_id bigint,
  batch_uom text,
  batch_inventory_status text,
  batch_total_quantity bigint,
  status text NOT NULL DEFAULT 'planned'
    CHECK(status IN('planned','in_progress','completed','cancelled')),
  revision bigint NOT NULL DEFAULT 1 CHECK(revision>0),
  task_count bigint NOT NULL CHECK(task_count BETWEEN 2 AND 200),
  order_count bigint NOT NULL CHECK(order_count BETWEEN 2 AND 48),
  assigned_user_id bigint,
  planned_by_user_id bigint NOT NULL,
  planned_at timestamptz NOT NULL,
  started_at timestamptz,
  completed_at timestamptz,
  cancelled_by_user_id bigint,
  cancelled_at timestamptz,
  cancellation_note text,
  CHECK(
    (mode='cluster_cart' AND batch_source_inventory_balance_id IS NULL
      AND batch_source_location_id IS NULL
      AND batch_item_batch_id IS NULL AND batch_uom IS NULL
      AND batch_inventory_status IS NULL AND batch_total_quantity IS NULL)
    OR (mode='batch_cart' AND batch_source_inventory_balance_id IS NOT NULL
      AND batch_source_location_id IS NOT NULL
      AND batch_item_batch_id IS NOT NULL AND batch_uom=btrim(batch_uom)
      AND batch_uom<>'' AND batch_inventory_status=btrim(batch_inventory_status)
      AND batch_inventory_status<>'' AND batch_total_quantity>0)
  ),
  CHECK(cancellation_note IS NULL OR
    (cancellation_note=btrim(cancellation_note) AND cancellation_note<>''
      AND char_length(cancellation_note)<=500)),
  CHECK(
    (status='planned' AND revision=1 AND assigned_user_id IS NULL
      AND started_at IS NULL AND completed_at IS NULL
      AND cancelled_by_user_id IS NULL AND cancelled_at IS NULL
      AND cancellation_note IS NULL)
    OR (status='in_progress' AND revision=2 AND assigned_user_id IS NOT NULL
      AND started_at IS NOT NULL AND completed_at IS NULL
      AND cancelled_by_user_id IS NULL AND cancelled_at IS NULL
      AND cancellation_note IS NULL)
    OR (status='completed' AND revision=3 AND assigned_user_id IS NOT NULL
      AND started_at IS NOT NULL AND completed_at IS NOT NULL
      AND completed_at>=started_at AND cancelled_by_user_id IS NULL
      AND cancelled_at IS NULL AND cancellation_note IS NULL)
    OR (status='cancelled' AND revision IN(2,3) AND completed_at IS NULL
      AND cancelled_at IS NOT NULL AND cancellation_note IS NOT NULL
      AND ((revision=2 AND assigned_user_id IS NULL AND started_at IS NULL)
        OR (revision=3 AND assigned_user_id IS NOT NULL AND started_at IS NOT NULL)))
  ),
  UNIQUE(tenant_id,inventory_owner_id,facility_id,id),
  UNIQUE(tenant_id,inventory_owner_id,facility_id,cart_id,id),
  FOREIGN KEY(tenant_id,inventory_owner_id)
    REFERENCES public.inventory_owners(tenant_id,id),
  FOREIGN KEY(tenant_id,inventory_owner_id,facility_id)
    REFERENCES public.inventory_owner_facilities(tenant_id,inventory_owner_id,facility_id),
  FOREIGN KEY(tenant_id,facility_id,cart_id)
    REFERENCES public.pick_carts(tenant_id,facility_id,id),
  FOREIGN KEY(tenant_id,inventory_owner_id,facility_id,batch_source_inventory_balance_id)
    REFERENCES public.inventory_balances(tenant_id,inventory_owner_id,facility_id,id),
  FOREIGN KEY(tenant_id,facility_id,batch_source_location_id)
    REFERENCES public.locations(tenant_id,facility_id,id),
  FOREIGN KEY(tenant_id,inventory_owner_id,batch_item_batch_id)
    REFERENCES public.item_batches(tenant_id,inventory_owner_id,id),
  FOREIGN KEY(tenant_id,assigned_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  FOREIGN KEY(tenant_id,planned_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  FOREIGN KEY(tenant_id,cancelled_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id)
);

CREATE UNIQUE INDEX pick_clusters_one_active_cart_idx
ON public.pick_clusters(tenant_id,facility_id,cart_id)
WHERE status IN('planned','in_progress');
CREATE INDEX pick_clusters_scope_status_idx
ON public.pick_clusters(tenant_id,facility_id,inventory_owner_id,status,planned_at DESC,id DESC);

CREATE TABLE public.pick_cluster_orders (
  tenant_id bigint NOT NULL REFERENCES public.tenants(id),
  inventory_owner_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  cluster_id bigint NOT NULL,
  cart_id bigint NOT NULL,
  order_id bigint NOT NULL,
  slot_id bigint NOT NULL,
  PRIMARY KEY(tenant_id,inventory_owner_id,facility_id,cluster_id,order_id),
  UNIQUE(tenant_id,inventory_owner_id,facility_id,cluster_id,slot_id),
  UNIQUE(tenant_id,inventory_owner_id,facility_id,cluster_id,order_id,slot_id),
  FOREIGN KEY(tenant_id,inventory_owner_id,facility_id,cart_id,cluster_id)
    REFERENCES public.pick_clusters(tenant_id,inventory_owner_id,facility_id,cart_id,id),
  FOREIGN KEY(tenant_id,facility_id,cart_id,slot_id)
    REFERENCES public.pick_cart_slots(tenant_id,facility_id,cart_id,id),
  FOREIGN KEY(tenant_id,inventory_owner_id,order_id)
    REFERENCES public.orders(tenant_id,inventory_owner_id,id)
);

CREATE TABLE public.pick_cluster_members (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES public.tenants(id),
  inventory_owner_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  cluster_id bigint NOT NULL,
  cart_id bigint NOT NULL,
  order_id bigint NOT NULL,
  slot_id bigint NOT NULL,
  task_id bigint NOT NULL,
  sequence bigint NOT NULL CHECK(sequence>0),
  created_at timestamptz NOT NULL,
  UNIQUE(tenant_id,inventory_owner_id,facility_id,cluster_id,id),
  UNIQUE(tenant_id,inventory_owner_id,facility_id,cluster_id,sequence),
  UNIQUE(tenant_id,cluster_id,task_id),
  FOREIGN KEY(tenant_id,inventory_owner_id,facility_id,cluster_id,order_id,slot_id)
    REFERENCES public.pick_cluster_orders(
      tenant_id,inventory_owner_id,facility_id,cluster_id,order_id,slot_id),
  FOREIGN KEY(tenant_id,inventory_owner_id,facility_id,task_id)
    REFERENCES public.pick_tasks(tenant_id,inventory_owner_id,facility_id,id)
);

CREATE INDEX pick_cluster_members_route_idx
ON public.pick_cluster_members(tenant_id,cluster_id,sequence);
CREATE INDEX pick_cluster_members_task_idx
ON public.pick_cluster_members(tenant_id,task_id);

-- Each zone-directed claim freezes the exact active pick-zone version and source
-- evidence that admitted the task. A released task may be claimed again, but the
-- prior attempt remains immutable for handoff and audit reconstruction.
CREATE TABLE public.pick_zone_claims (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES public.tenants(id),
  inventory_owner_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  task_id bigint NOT NULL,
  claimed_by_user_id bigint NOT NULL,
  claimed_at timestamptz NOT NULL,
  storage_zone_id bigint NOT NULL,
  storage_zone_code text NOT NULL,
  storage_zone_revision bigint NOT NULL CHECK(storage_zone_revision>0),
  storage_zone_travel_sequence bigint NOT NULL CHECK(storage_zone_travel_sequence>=0),
  source_location_id bigint NOT NULL,
  source_inventory_balance_id bigint NOT NULL,
  CHECK(storage_zone_code=upper(btrim(storage_zone_code))
    AND storage_zone_code<>'' AND char_length(storage_zone_code)<=32
    AND storage_zone_code~'^[A-Z0-9_-]+$'),
  UNIQUE(tenant_id,inventory_owner_id,facility_id,id),
  UNIQUE(tenant_id,task_id,claimed_at),
  FOREIGN KEY(tenant_id,inventory_owner_id,facility_id,task_id)
    REFERENCES public.pick_tasks(tenant_id,inventory_owner_id,facility_id,id),
  FOREIGN KEY(tenant_id,claimed_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  FOREIGN KEY(tenant_id,facility_id,storage_zone_id)
    REFERENCES public.storage_zones(tenant_id,facility_id,id),
  FOREIGN KEY(tenant_id,facility_id,source_location_id)
    REFERENCES public.locations(tenant_id,facility_id,id),
  FOREIGN KEY(tenant_id,inventory_owner_id,facility_id,source_inventory_balance_id)
    REFERENCES public.inventory_balances(tenant_id,inventory_owner_id,facility_id,id)
);

CREATE INDEX pick_zone_claims_task_history_idx
ON public.pick_zone_claims(tenant_id,task_id,claimed_at DESC,id DESC);
CREATE INDEX pick_zone_claims_zone_history_idx
ON public.pick_zone_claims(tenant_id,storage_zone_id,claimed_at DESC,id DESC);

CREATE FUNCTION public.guard_pick_cart_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'pick carts cannot be deleted' USING ERRCODE='55000';
  END IF;
  IF ROW(NEW.tenant_id,NEW.facility_id,NEW.barcode,NEW.name,
      NEW.created_by_user_id,NEW.created_at)
    IS DISTINCT FROM ROW(OLD.tenant_id,OLD.facility_id,OLD.barcode,OLD.name,
      OLD.created_by_user_id,OLD.created_at)
    OR NEW.revision<>OLD.revision+1
    OR ROW(NEW.status_changed_by_user_id,NEW.status_changed_at)
      IS NOT DISTINCT FROM ROW(OLD.status_changed_by_user_id,OLD.status_changed_at)
    OR NOT ((OLD.status='active' AND NEW.status IN('out_of_service','retired'))
      OR (OLD.status='out_of_service' AND NEW.status IN('active','retired'))) THEN
    RAISE EXCEPTION 'invalid pick cart mutation' USING ERRCODE='55000';
  END IF;
  IF EXISTS(SELECT 1 FROM public.pick_clusters cluster
    WHERE cluster.tenant_id=OLD.tenant_id AND cluster.facility_id=OLD.facility_id
      AND cluster.cart_id=OLD.id AND cluster.status IN('planned','in_progress')) THEN
    RAISE EXCEPTION 'pick cart has an active cluster' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.guard_pick_cart_slot_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'pick cart slots are immutable' USING ERRCODE='55000';
END $$;

CREATE FUNCTION public.guard_pick_cluster_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'pick clusters cannot be deleted' USING ERRCODE='55000';
  END IF;
  IF ROW(NEW.tenant_id,NEW.inventory_owner_id,NEW.facility_id,NEW.cart_id,
      NEW.mode,NEW.batch_source_inventory_balance_id,NEW.batch_source_location_id,
      NEW.batch_item_batch_id,NEW.batch_uom,
      NEW.batch_inventory_status,NEW.batch_total_quantity,
      NEW.task_count,NEW.order_count,NEW.planned_by_user_id,NEW.planned_at)
    IS DISTINCT FROM ROW(OLD.tenant_id,OLD.inventory_owner_id,OLD.facility_id,OLD.cart_id,
      OLD.mode,OLD.batch_source_inventory_balance_id,OLD.batch_source_location_id,
      OLD.batch_item_batch_id,OLD.batch_uom,
      OLD.batch_inventory_status,OLD.batch_total_quantity,
      OLD.task_count,OLD.order_count,OLD.planned_by_user_id,OLD.planned_at)
    OR NOT (
      (OLD.status='planned' AND NEW.status='in_progress' AND NEW.revision=2
        AND NEW.assigned_user_id IS NOT NULL AND NEW.started_at IS NOT NULL)
      OR (OLD.status='planned' AND NEW.status='cancelled' AND NEW.revision=2
        AND NEW.assigned_user_id IS NULL AND NEW.started_at IS NULL
        AND NEW.cancelled_at IS NOT NULL AND NEW.cancellation_note IS NOT NULL)
      OR (OLD.status='in_progress' AND NEW.status='completed' AND NEW.revision=3
        AND NEW.assigned_user_id=OLD.assigned_user_id
        AND NEW.started_at=OLD.started_at AND NEW.completed_at IS NOT NULL)
      OR (OLD.status='in_progress' AND NEW.status='cancelled' AND NEW.revision=3
        AND NEW.assigned_user_id=OLD.assigned_user_id
        AND NEW.started_at=OLD.started_at AND NEW.cancelled_at IS NOT NULL
        AND NEW.cancellation_note IS NOT NULL)
    ) THEN
    RAISE EXCEPTION 'invalid pick cluster mutation' USING ERRCODE='55000';
  END IF;
  IF OLD.status='planned' AND NEW.status='in_progress' AND NOT EXISTS(
    SELECT 1 FROM public.pick_carts cart
    WHERE cart.tenant_id=NEW.tenant_id AND cart.facility_id=NEW.facility_id
      AND cart.id=NEW.cart_id AND cart.status='active'
  ) THEN
    RAISE EXCEPTION 'pick cluster cart is not active' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.guard_pick_cluster_child_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'pick cluster plan evidence is immutable' USING ERRCODE='55000';
END $$;

CREATE FUNCTION public.guard_pick_zone_claim_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'pick zone claim evidence is immutable' USING ERRCODE='55000';
END $$;

CREATE FUNCTION public.protect_active_pick_zone_claims() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
BEGIN
  IF OLD.effective_to IS NULL AND NEW.effective_to IS NOT NULL AND EXISTS(
    SELECT 1 FROM public.pick_zone_claims evidence
    JOIN public.pick_tasks task ON task.tenant_id=evidence.tenant_id
      AND task.id=evidence.task_id
      AND task.assigned_user_id=evidence.claimed_by_user_id
      AND task.claimed_at=evidence.claimed_at
    WHERE evidence.tenant_id=OLD.tenant_id
      AND evidence.storage_zone_id=OLD.id AND task.status='in_progress'
      AND task.lease_expires_at>statement_timestamp()
  ) THEN
    RAISE EXCEPTION 'active zone picks must be completed or released before reconfiguration'
      USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.validate_pick_zone_claim() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE task_row public.pick_tasks%ROWTYPE;
DECLARE zone_row public.storage_zones%ROWTYPE;
DECLARE actor_id bigint;
BEGIN
  actor_id:=NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint;
  SELECT * INTO task_row FROM public.pick_tasks task
  WHERE task.tenant_id=NEW.tenant_id
    AND task.inventory_owner_id=NEW.inventory_owner_id
    AND task.facility_id=NEW.facility_id AND task.id=NEW.task_id
  FOR SHARE;
  IF task_row.id IS NULL OR task_row.status<>'in_progress'
    OR task_row.assigned_user_id IS DISTINCT FROM NEW.claimed_by_user_id
    OR task_row.claimed_at IS DISTINCT FROM NEW.claimed_at
    OR actor_id IS DISTINCT FROM NEW.claimed_by_user_id
    OR NOT public.work_orchestration_user_has_permission(
      NEW.tenant_id,NEW.claimed_by_user_id,'wms') THEN
    RAISE EXCEPTION 'pick zone claim does not match active authorized work'
      USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS(
    SELECT 1 FROM public.tenant_memberships membership
    WHERE membership.tenant_id=NEW.tenant_id
      AND membership.user_id=NEW.claimed_by_user_id
      AND membership.deleted IS NULL
      AND (membership.all_facilities OR EXISTS(
        SELECT 1 FROM public.user_facilities assignment
        WHERE assignment.tenant_id=membership.tenant_id
          AND assignment.user_id=membership.user_id
          AND assignment.facility_id=NEW.facility_id
          AND assignment.deleted IS NULL))
      AND (membership.all_inventory_owners OR EXISTS(
        SELECT 1 FROM public.user_inventory_owners assignment
        WHERE assignment.tenant_id=membership.tenant_id
          AND assignment.user_id=membership.user_id
          AND assignment.inventory_owner_id=NEW.inventory_owner_id
          AND assignment.deleted IS NULL))
  ) THEN
    RAISE EXCEPTION 'pick zone claim is outside operator scope' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS(
    SELECT 1 FROM public.inventory_owner_facilities assignment
    JOIN public.inventory_owners owner ON owner.tenant_id=assignment.tenant_id
      AND owner.id=assignment.inventory_owner_id AND owner.deleted IS NULL
    JOIN public.facilities facility ON facility.tenant_id=assignment.tenant_id
      AND facility.id=assignment.facility_id AND facility.deleted IS NULL
    WHERE assignment.tenant_id=NEW.tenant_id
      AND assignment.inventory_owner_id=NEW.inventory_owner_id
      AND assignment.facility_id=NEW.facility_id AND assignment.deleted IS NULL
  ) THEN
    RAISE EXCEPTION 'pick zone claim requires an active owner-facility scope'
      USING ERRCODE='23514';
  END IF;
  SELECT * INTO zone_row FROM public.storage_zones zone
  WHERE zone.tenant_id=NEW.tenant_id AND zone.facility_id=NEW.facility_id
    AND zone.id=NEW.storage_zone_id FOR SHARE;
  IF zone_row.id IS NULL OR zone_row.purpose<>'pick'
    OR zone_row.effective_to IS NOT NULL
    OR zone_row.code IS DISTINCT FROM NEW.storage_zone_code
    OR zone_row.revision IS DISTINCT FROM NEW.storage_zone_revision
    OR zone_row.travel_sequence IS DISTINCT FROM NEW.storage_zone_travel_sequence
    OR NOT EXISTS(
      SELECT 1 FROM public.pick_task_contents content
      WHERE content.tenant_id=NEW.tenant_id AND content.task_id=NEW.task_id
        AND content.state='pending'
        AND content.source_location_id=NEW.source_location_id
        AND content.source_inventory_balance_id=NEW.source_inventory_balance_id)
    OR NOT EXISTS(
      SELECT 1 FROM public.storage_zone_locations member
      WHERE member.tenant_id=NEW.tenant_id AND member.facility_id=NEW.facility_id
        AND member.storage_zone_id=NEW.storage_zone_id
        AND member.location_id=NEW.source_location_id)
    OR EXISTS(
      SELECT 1 FROM public.pick_cluster_members member
      JOIN public.pick_clusters cluster ON cluster.tenant_id=member.tenant_id
        AND cluster.id=member.cluster_id
      WHERE member.tenant_id=NEW.tenant_id AND member.task_id=NEW.task_id
        AND cluster.status IN('planned','in_progress')) THEN
    RAISE EXCEPTION 'pick zone claim evidence is stale or inapplicable'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.require_zone_route_on_pick_claim() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
BEGIN
  IF OLD.status='open' AND NEW.status='in_progress'
    AND NOT EXISTS(
      SELECT 1 FROM public.pick_cluster_members member
      JOIN public.pick_clusters cluster ON cluster.tenant_id=member.tenant_id
        AND cluster.id=member.cluster_id
      WHERE member.tenant_id=NEW.tenant_id AND member.task_id=NEW.id
        AND cluster.status IN('planned','in_progress'))
    AND EXISTS(
      SELECT 1 FROM public.pick_task_contents content
      JOIN public.storage_zone_locations member
        ON member.tenant_id=content.tenant_id
        AND member.facility_id=content.facility_id
        AND member.location_id=content.source_location_id
      JOIN public.storage_zones zone ON zone.tenant_id=member.tenant_id
        AND zone.facility_id=member.facility_id
        AND zone.id=member.storage_zone_id
      WHERE content.tenant_id=NEW.tenant_id AND content.task_id=NEW.id
        AND content.state='pending' AND zone.purpose='pick'
        AND zone.effective_to IS NULL)
    AND NOT EXISTS(
      SELECT 1 FROM public.pick_zone_claims evidence
      WHERE evidence.tenant_id=NEW.tenant_id AND evidence.task_id=NEW.id
        AND evidence.claimed_by_user_id=NEW.assigned_user_id
        AND evidence.claimed_at=NEW.claimed_at) THEN
    RAISE EXCEPTION 'zoned pick task must be claimed through its zone queue'
      USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;

CREATE FUNCTION public.validate_pick_cluster_member() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE task_row public.pick_tasks%ROWTYPE;
DECLARE cluster_row public.pick_clusters%ROWTYPE;
DECLARE source_barcode text;
BEGIN
  SELECT * INTO task_row FROM public.pick_tasks task
  WHERE task.tenant_id=NEW.tenant_id AND task.inventory_owner_id=NEW.inventory_owner_id
    AND task.facility_id=NEW.facility_id AND task.id=NEW.task_id FOR SHARE;
  IF task_row.id IS NULL OR task_row.order_id<>NEW.order_id OR task_row.status<>'open'
    OR task_row.assigned_user_id IS NOT NULL THEN
    RAISE EXCEPTION 'pick cluster member task is not open in the requested scope'
      USING ERRCODE='23514';
  END IF;
  IF EXISTS(
    SELECT 1 FROM public.pick_cluster_members member
    JOIN public.pick_clusters cluster ON cluster.tenant_id=member.tenant_id
      AND cluster.id=member.cluster_id
    WHERE member.tenant_id=NEW.tenant_id AND member.task_id=NEW.task_id
      AND cluster.status IN('planned','in_progress')
  ) THEN
    RAISE EXCEPTION 'pick task already belongs to an active cluster'
      USING ERRCODE='23514';
  END IF;
  SELECT location.barcode INTO source_barcode
  FROM public.pick_task_contents content
  JOIN public.locations location ON location.tenant_id=content.tenant_id
    AND location.facility_id=content.facility_id AND location.id=content.source_location_id
  WHERE content.tenant_id=NEW.tenant_id AND content.task_id=NEW.task_id
    AND content.state='pending' AND location.deleted IS NULL AND location.active
    AND location.pickable;
  IF source_barcode IS NULL OR btrim(source_barcode)='' THEN
    RAISE EXCEPTION 'pick cluster member source is not executable' USING ERRCODE='23514';
  END IF;
  SELECT * INTO cluster_row FROM public.pick_clusters cluster
  WHERE cluster.tenant_id=NEW.tenant_id AND cluster.id=NEW.cluster_id;
  IF cluster_row.id IS NULL THEN
    RAISE EXCEPTION 'pick cluster member has no route' USING ERRCODE='23514';
  END IF;
  IF cluster_row.mode='batch_cart' AND NOT EXISTS(
    SELECT 1 FROM public.pick_task_contents content
    WHERE content.tenant_id=NEW.tenant_id AND content.task_id=NEW.task_id
      AND content.state='pending'
      AND content.source_inventory_balance_id=cluster_row.batch_source_inventory_balance_id
      AND content.source_location_id=cluster_row.batch_source_location_id
      AND content.item_batch_id=cluster_row.batch_item_batch_id
      AND content.uom=cluster_row.batch_uom
      AND content.inventory_status=cluster_row.batch_inventory_status
      AND content.planned_qty>0
  ) THEN
    RAISE EXCEPTION 'batch-cart member does not match frozen batch evidence'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.require_pick_cluster_complete_plan() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE cluster_row public.pick_clusters%ROWTYPE;
DECLARE cluster_id_value bigint;
DECLARE actual_task_count bigint;
DECLARE actual_order_count bigint;
DECLARE invalid_sequence boolean;
DECLARE actual_batch_quantity bigint;
DECLARE invalid_batch_member boolean;
DECLARE batch_identity_count bigint;
BEGIN
  IF TG_TABLE_NAME='pick_clusters' THEN
    cluster_id_value:=NEW.id;
  ELSE
    cluster_id_value:=NEW.cluster_id;
  END IF;
  SELECT * INTO cluster_row FROM public.pick_clusters cluster
  WHERE cluster.tenant_id=NEW.tenant_id AND cluster.id=cluster_id_value;
  SELECT COUNT(*),COUNT(DISTINCT member.order_id) INTO actual_task_count,actual_order_count
  FROM public.pick_cluster_members member
  WHERE member.tenant_id=NEW.tenant_id AND member.cluster_id=cluster_id_value;
  SELECT EXISTS(
    SELECT 1 FROM (
      SELECT member.sequence,
        row_number() OVER(ORDER BY lower(location.barcode),member.task_id) expected_sequence
      FROM public.pick_cluster_members member
      JOIN public.pick_task_contents content ON content.tenant_id=member.tenant_id
        AND content.task_id=member.task_id
      JOIN public.locations location ON location.tenant_id=content.tenant_id
        AND location.facility_id=content.facility_id AND location.id=content.source_location_id
      WHERE member.tenant_id=NEW.tenant_id AND member.cluster_id=cluster_id_value
    ) ordered WHERE ordered.sequence<>ordered.expected_sequence
  ) INTO invalid_sequence;
  SELECT COALESCE(SUM(content.planned_qty),0),COALESCE(bool_or(
      content.source_inventory_balance_id
        IS DISTINCT FROM cluster_row.batch_source_inventory_balance_id
      OR content.source_location_id IS DISTINCT FROM cluster_row.batch_source_location_id
      OR content.item_batch_id IS DISTINCT FROM cluster_row.batch_item_batch_id
      OR content.uom IS DISTINCT FROM cluster_row.batch_uom
      OR content.inventory_status IS DISTINCT FROM cluster_row.batch_inventory_status),false),
      COUNT(DISTINCT ROW(content.source_inventory_balance_id,content.source_location_id,
        content.item_batch_id,content.uom,content.inventory_status))
    INTO actual_batch_quantity,invalid_batch_member,batch_identity_count
  FROM public.pick_cluster_members member
  JOIN public.pick_task_contents content ON content.tenant_id=member.tenant_id
    AND content.task_id=member.task_id
  WHERE member.tenant_id=NEW.tenant_id AND member.cluster_id=cluster_id_value;
  IF cluster_row.id IS NULL OR actual_task_count<>cluster_row.task_count
    OR actual_order_count<>cluster_row.order_count OR actual_order_count<2
    OR invalid_sequence OR (cluster_row.mode='batch_cart' AND
      (invalid_batch_member OR actual_batch_quantity<>cluster_row.batch_total_quantity))
    OR (cluster_row.mode='cluster_cart' AND batch_identity_count=1) THEN
    RAISE EXCEPTION 'pick cluster plan is incomplete or not in canonical route order'
      USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;

CREATE FUNCTION public.require_pick_cart_slot_set() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE cart_id_value bigint;
DECLARE slot_count bigint;
BEGIN
  IF TG_TABLE_NAME='pick_carts' THEN cart_id_value:=NEW.id;
  ELSE cart_id_value:=NEW.cart_id; END IF;
  SELECT COUNT(*) INTO slot_count FROM public.pick_cart_slots slot
  WHERE slot.tenant_id=NEW.tenant_id AND slot.cart_id=cart_id_value;
  IF slot_count<2 OR slot_count>48 THEN
    RAISE EXCEPTION 'pick cart must contain between 2 and 48 immutable slots'
      USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;

CREATE FUNCTION public.require_cluster_reservation_on_pick_claim() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
BEGIN
  IF OLD.status='open' AND NEW.status='cancelled' AND EXISTS(
    SELECT 1 FROM public.pick_cluster_members member
    JOIN public.pick_clusters cluster ON cluster.tenant_id=member.tenant_id
      AND cluster.id=member.cluster_id
    WHERE member.tenant_id=NEW.tenant_id AND member.task_id=NEW.id
      AND cluster.status IN('planned','in_progress')
  ) THEN
    RAISE EXCEPTION 'active pick cluster route must be cancelled before its task'
      USING ERRCODE='23514';
  END IF;
  IF OLD.status='open' AND NEW.status='in_progress' AND EXISTS(
    SELECT 1 FROM public.pick_cluster_members member
    JOIN public.pick_clusters cluster ON cluster.tenant_id=member.tenant_id
      AND cluster.id=member.cluster_id
    WHERE member.tenant_id=NEW.tenant_id AND member.task_id=NEW.id
      AND cluster.status IN('planned','in_progress')
      AND NOT (cluster.status='in_progress'
        AND cluster.assigned_user_id=NEW.assigned_user_id)
  ) THEN
    RAISE EXCEPTION 'cluster-reserved pick task must be claimed through its route'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.reconcile_pick_cluster_task() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE cluster_id_value bigint;
BEGIN
  IF NEW.status NOT IN('completed','shorted','cancelled')
    OR OLD.status IN('completed','shorted','cancelled') THEN RETURN NEW; END IF;
  SELECT member.cluster_id INTO cluster_id_value
  FROM public.pick_cluster_members member
  WHERE member.tenant_id=NEW.tenant_id AND member.task_id=NEW.id;
  IF cluster_id_value IS NULL OR EXISTS(
    SELECT 1 FROM public.pick_cluster_members member
    JOIN public.pick_tasks task ON task.tenant_id=member.tenant_id AND task.id=member.task_id
    WHERE member.tenant_id=NEW.tenant_id AND member.cluster_id=cluster_id_value
      AND task.status IN('open','in_progress')) THEN RETURN NEW; END IF;
  UPDATE public.pick_clusters SET status='completed',revision=3,
    completed_at=NEW.completed_at
  WHERE tenant_id=NEW.tenant_id AND id=cluster_id_value
    AND status='in_progress';
  RETURN NEW;
END $$;

