-- Execute inherited Count decision rules while retaining the operational
-- cycle-count policy as the source of the bounded automatic recount limit.
ALTER TABLE public.cycle_count_item_location_results
  ADD COLUMN count_policy_source text,
  ADD COLUMN count_configuration_id bigint,
  ADD COLUMN count_configuration_revision bigint,
  ADD COLUMN count_scope_level text,
  ADD COLUMN count_inventory_owner_id bigint,
  ADD COLUMN count_facility_id bigint,
  ADD COLUMN count_absolute_tolerance_qty bigint,
  ADD COLUMN count_percentage_tolerance_bps integer,
  ADD COLUMN count_approval_threshold_qty bigint,
  ADD COLUMN count_policy_hash text,
  ADD CONSTRAINT cycle_count_results_count_policy_shape CHECK (
    (policy_id IS NULL AND count_policy_source IS NULL
      AND count_configuration_id IS NULL AND count_configuration_revision IS NULL
      AND count_scope_level IS NULL AND count_inventory_owner_id IS NULL
      AND count_facility_id IS NULL AND count_absolute_tolerance_qty IS NULL
      AND count_percentage_tolerance_bps IS NULL
      AND count_approval_threshold_qty IS NULL AND count_policy_hash IS NULL)
    OR
    (policy_id IS NOT NULL AND count_policy_source IN ('product_default','configuration')
      AND count_absolute_tolerance_qty=absolute_tolerance_qty
      AND count_percentage_tolerance_bps=percentage_tolerance_bps
      AND count_absolute_tolerance_qty>=0
      AND count_percentage_tolerance_bps BETWEEN 0 AND 10000
      AND count_policy_hash~'^[0-9a-f]{64}$'
      AND ((count_policy_source='product_default'
        AND count_configuration_id IS NULL AND count_configuration_revision IS NULL
        AND count_scope_level IS NULL AND count_inventory_owner_id IS NULL
        AND count_facility_id IS NULL AND count_approval_threshold_qty IS NULL)
      OR (count_policy_source='configuration'
        AND count_configuration_id IS NOT NULL AND count_configuration_revision>0
        AND count_approval_threshold_qty>=count_absolute_tolerance_qty
        AND ((count_scope_level='tenant' AND count_inventory_owner_id IS NULL
              AND count_facility_id IS NULL)
          OR (count_scope_level='inventory_owner' AND count_inventory_owner_id IS NOT NULL
              AND count_facility_id IS NULL)
          OR (count_scope_level='facility' AND count_inventory_owner_id IS NULL
              AND count_facility_id IS NOT NULL)
          OR (count_scope_level='owner_facility' AND count_inventory_owner_id IS NOT NULL
              AND count_facility_id IS NOT NULL)))))),
  ADD CONSTRAINT cycle_count_results_count_configuration_fkey
    FOREIGN KEY(tenant_id,count_configuration_id)
    REFERENCES public.configuration_versions(tenant_id,id);

ALTER TABLE public.cycle_count_variance_cases
  ADD COLUMN count_policy_source text NOT NULL,
  ADD COLUMN count_configuration_id bigint,
  ADD COLUMN count_configuration_revision bigint,
  ADD COLUMN count_scope_level text,
  ADD COLUMN count_inventory_owner_id bigint,
  ADD COLUMN count_facility_id bigint,
  ADD COLUMN count_absolute_tolerance_qty bigint NOT NULL,
  ADD COLUMN count_percentage_tolerance_bps integer NOT NULL,
  ADD COLUMN count_approval_threshold_qty bigint,
  ADD COLUMN count_policy_hash text NOT NULL,
  ADD CONSTRAINT cycle_count_variances_count_policy_shape CHECK (
    count_policy_source IN ('product_default','configuration')
    AND count_absolute_tolerance_qty=absolute_tolerance_qty
    AND count_percentage_tolerance_bps=percentage_tolerance_bps
    AND count_absolute_tolerance_qty>=0
    AND count_percentage_tolerance_bps BETWEEN 0 AND 10000
    AND count_policy_hash~'^[0-9a-f]{64}$'
    AND ((count_policy_source='product_default'
      AND count_configuration_id IS NULL AND count_configuration_revision IS NULL
      AND count_scope_level IS NULL AND count_inventory_owner_id IS NULL
      AND count_facility_id IS NULL AND count_approval_threshold_qty IS NULL)
    OR (count_policy_source='configuration'
      AND count_configuration_id IS NOT NULL AND count_configuration_revision>0
      AND count_approval_threshold_qty>=count_absolute_tolerance_qty
      AND ((count_scope_level='tenant' AND count_inventory_owner_id IS NULL
            AND count_facility_id IS NULL)
        OR (count_scope_level='inventory_owner' AND count_inventory_owner_id IS NOT NULL
            AND count_facility_id IS NULL)
        OR (count_scope_level='facility' AND count_inventory_owner_id IS NULL
            AND count_facility_id IS NOT NULL)
        OR (count_scope_level='owner_facility' AND count_inventory_owner_id IS NOT NULL
            AND count_facility_id IS NOT NULL))))),
  ADD CONSTRAINT cycle_count_variances_count_configuration_fkey
    FOREIGN KEY(tenant_id,count_configuration_id)
    REFERENCES public.configuration_versions(tenant_id,id);

CREATE INDEX cycle_count_results_count_configuration_idx
ON public.cycle_count_item_location_results(tenant_id,count_configuration_id)
WHERE count_configuration_id IS NOT NULL;
CREATE INDEX cycle_count_variances_count_configuration_idx
ON public.cycle_count_variance_cases(tenant_id,count_configuration_id)
WHERE count_configuration_id IS NOT NULL;

CREATE FUNCTION public.validate_count_decision_snapshot() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE effective_at timestamptz;
DECLARE resolved public.configuration_versions%ROWTYPE;
DECLARE scope_component text;
DECLARE calculated_hash text;
BEGIN
  IF TG_TABLE_NAME='cycle_count_variance_cases' THEN
    effective_at:=NEW.created_at;
  ELSE
    effective_at:=NEW.confirmed_at;
  END IF;
  IF NEW.policy_id IS NULL THEN
    IF NEW.count_policy_source IS NOT NULL THEN
      RAISE EXCEPTION 'uncontrolled cycle count cannot carry Count policy evidence'
        USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;

  SELECT configuration.* INTO resolved
  FROM public.configuration_versions configuration
  WHERE configuration.tenant_id=NEW.tenant_id AND configuration.kind='count'
    AND configuration.status='active' AND configuration.activated_at<=effective_at
    AND configuration.effective_from<=effective_at
    AND (configuration.effective_until IS NULL OR configuration.effective_until>effective_at)
    AND (configuration.inventory_owner_id IS NULL
      OR configuration.inventory_owner_id=NEW.inventory_owner_id)
    AND (configuration.facility_id IS NULL OR configuration.facility_id=NEW.facility_id)
  ORDER BY CASE configuration.scope_level WHEN 'owner_facility' THEN 2
    WHEN 'inventory_owner' THEN 1 WHEN 'facility' THEN 1 ELSE 0 END DESC,
    configuration.effective_from DESC,configuration.revision DESC,configuration.id DESC
  LIMIT 1;

  IF NEW.count_policy_source='product_default' THEN
    IF resolved.id IS NOT NULL OR NEW.count_configuration_id IS NOT NULL
      OR NEW.count_configuration_revision IS NOT NULL OR NEW.count_scope_level IS NOT NULL
      OR NEW.count_inventory_owner_id IS NOT NULL OR NEW.count_facility_id IS NOT NULL
      OR NEW.count_approval_threshold_qty IS NOT NULL THEN
      RAISE EXCEPTION 'product-default Count evidence does not match effective configuration'
        USING ERRCODE='23514';
    END IF;
    scope_component:='-';
  ELSE
    IF resolved.id IS NULL OR NEW.count_configuration_id IS DISTINCT FROM resolved.id
      OR NEW.count_configuration_revision IS DISTINCT FROM resolved.revision
      OR NEW.count_scope_level IS DISTINCT FROM resolved.scope_level
      OR NEW.count_inventory_owner_id IS DISTINCT FROM resolved.inventory_owner_id
      OR NEW.count_facility_id IS DISTINCT FROM resolved.facility_id
      OR NEW.count_absolute_tolerance_qty
        IS DISTINCT FROM (resolved.definition->>'absolute_tolerance')::bigint
      OR NEW.count_percentage_tolerance_bps
        IS DISTINCT FROM (resolved.definition->>'percentage_tolerance_basis_points')::integer
      OR NEW.count_approval_threshold_qty
        IS DISTINCT FROM (resolved.definition->>'approval_threshold')::bigint THEN
      RAISE EXCEPTION 'configured Count evidence does not match effective configuration'
        USING ERRCODE='23514';
    END IF;
    scope_component:=CASE NEW.count_scope_level
      WHEN 'tenant' THEN 'tenant'
      WHEN 'inventory_owner' THEN 'inventory_owner:'||NEW.count_inventory_owner_id::text
      WHEN 'facility' THEN 'facility:'||NEW.count_facility_id::text
      WHEN 'owner_facility' THEN 'owner_facility:'||NEW.count_inventory_owner_id::text
        ||':'||NEW.count_facility_id::text END;
  END IF;

  calculated_hash:=encode(sha256(convert_to(
    'count-decision-policy-v1|'||NEW.count_policy_source||'|'
    ||COALESCE(NEW.count_configuration_id::text,'-')||'|'
    ||COALESCE(NEW.count_configuration_revision::text,'-')||'|'
    ||scope_component||'|'||NEW.count_absolute_tolerance_qty::text||'|'
    ||NEW.count_percentage_tolerance_bps::text||'|'
    ||COALESCE(NEW.count_approval_threshold_qty::text,'-'),'UTF8')),'hex');
  IF NEW.count_policy_hash IS DISTINCT FROM calculated_hash THEN
    RAISE EXCEPTION 'Count policy hash is inconsistent' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.guard_count_decision_snapshot() RETURNS trigger
LANGUAGE plpgsql SET search_path TO 'pg_catalog','public' AS $$
BEGIN
  IF ROW(NEW.count_policy_source,NEW.count_configuration_id,
      NEW.count_configuration_revision,NEW.count_scope_level,
      NEW.count_inventory_owner_id,NEW.count_facility_id,
      NEW.count_absolute_tolerance_qty,NEW.count_percentage_tolerance_bps,
      NEW.count_approval_threshold_qty,NEW.count_policy_hash)
    IS DISTINCT FROM ROW(OLD.count_policy_source,OLD.count_configuration_id,
      OLD.count_configuration_revision,OLD.count_scope_level,
      OLD.count_inventory_owner_id,OLD.count_facility_id,
      OLD.count_absolute_tolerance_qty,OLD.count_percentage_tolerance_bps,
      OLD.count_approval_threshold_qty,OLD.count_policy_hash) THEN
    RAISE EXCEPTION 'Count decision evidence is immutable' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER cycle_count_results_validate_count_policy
BEFORE INSERT ON public.cycle_count_item_location_results
FOR EACH ROW EXECUTE FUNCTION public.validate_count_decision_snapshot();
CREATE TRIGGER cycle_count_variances_validate_count_policy
BEFORE INSERT ON public.cycle_count_variance_cases
FOR EACH ROW EXECUTE FUNCTION public.validate_count_decision_snapshot();
CREATE TRIGGER cycle_count_variances_guard_count_policy
BEFORE UPDATE ON public.cycle_count_variance_cases
FOR EACH ROW EXECUTE FUNCTION public.guard_count_decision_snapshot();

REVOKE ALL ON FUNCTION public.validate_count_decision_snapshot() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_count_decision_snapshot() FROM PUBLIC;

-- Execute inherited Billing decisions per billable event. Contract rate cards
-- remain the governed fallback and every immutable charge freezes its exact
-- decision source and terms.
ALTER TABLE public.billing_charges
  ALTER COLUMN rate_version_id DROP NOT NULL,
  ADD COLUMN contract_rate_revision bigint,
  ADD COLUMN decision_policy_source text NOT NULL,
  ADD COLUMN decision_configuration_id bigint,
  ADD COLUMN decision_configuration_revision bigint,
  ADD COLUMN decision_scope_level text,
  ADD COLUMN decision_inventory_owner_id bigint,
  ADD COLUMN decision_facility_id bigint,
  ADD COLUMN decision_policy_hash text NOT NULL,
  ADD CONSTRAINT billing_charges_decision_policy_shape CHECK (
    decision_policy_source IN ('contract_rate','configuration')
    AND decision_policy_hash~'^[0-9a-f]{64}$'
    AND ((decision_policy_source='contract_rate'
      AND rate_version_id IS NOT NULL AND contract_rate_revision>0
      AND decision_configuration_id IS NULL
      AND decision_configuration_revision IS NULL
      AND decision_scope_level IS NULL AND decision_inventory_owner_id IS NULL
      AND decision_facility_id IS NULL)
    OR (decision_policy_source='configuration'
      AND rate_version_id IS NULL AND contract_rate_revision IS NULL
      AND decision_configuration_id IS NOT NULL
      AND decision_configuration_revision>0
      AND ((decision_scope_level='tenant' AND decision_inventory_owner_id IS NULL
            AND decision_facility_id IS NULL)
        OR (decision_scope_level='inventory_owner'
            AND decision_inventory_owner_id IS NOT NULL AND decision_facility_id IS NULL)
        OR (decision_scope_level='facility' AND decision_inventory_owner_id IS NULL
            AND decision_facility_id IS NOT NULL)
        OR (decision_scope_level='owner_facility'
            AND decision_inventory_owner_id IS NOT NULL
            AND decision_facility_id IS NOT NULL))))),
  ADD CONSTRAINT billing_charges_decision_configuration_fkey
    FOREIGN KEY(tenant_id,decision_configuration_id)
    REFERENCES public.configuration_versions(tenant_id,id);

CREATE INDEX billing_charges_decision_configuration_idx
ON public.billing_charges(tenant_id,decision_configuration_id)
WHERE decision_configuration_id IS NOT NULL;

CREATE FUNCTION public.billing_decision_policy_hash(
  policy_source text,contract_rate_id bigint,contract_rate_revision bigint,
  configuration_id bigint,configuration_revision bigint,scope_level text,
  scope_owner_id bigint,scope_facility_id bigint,event_name text,unit_name text,
  currency_code text,rate_value bigint,minimum_value bigint
) RETURNS text LANGUAGE sql IMMUTABLE SET search_path TO 'pg_catalog','public' AS $$
  SELECT encode(sha256(convert_to(
    'billing-decision-policy-v1|'||policy_source||'|'
    ||COALESCE(contract_rate_id::text,'-')||'|'
    ||COALESCE(contract_rate_revision::text,'-')||'|'
    ||COALESCE(configuration_id::text,'-')||'|'
    ||COALESCE(configuration_revision::text,'-')||'|'
    ||CASE scope_level
        WHEN 'tenant' THEN 'tenant'
        WHEN 'inventory_owner' THEN 'inventory_owner:'||scope_owner_id::text
        WHEN 'facility' THEN 'facility:'||scope_facility_id::text
        WHEN 'owner_facility' THEN 'owner_facility:'||scope_owner_id::text
          ||':'||scope_facility_id::text
        ELSE '-' END||'|'||event_name||'|'||unit_name||'|'||currency_code||'|'
    ||rate_value::text||'|'||minimum_value::text,'UTF8')),'hex')
$$;

CREATE OR REPLACE FUNCTION public.validate_billing_charge_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE run_row public.billing_reconciliation_runs%ROWTYPE;
DECLARE event_row public.billable_events%ROWTYPE;
DECLARE rate_row public.billing_rate_versions%ROWTYPE;
DECLARE configuration_row public.configuration_versions%ROWTYPE;
DECLARE gross numeric; DECLARE amount numeric; DECLARE calculated_hash text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(format(
    'configuration-kind:%s:billing',NEW.tenant_id),0));
  SELECT * INTO run_row FROM public.billing_reconciliation_runs run
  WHERE run.tenant_id=NEW.tenant_id AND run.id=NEW.reconciliation_run_id FOR SHARE;
  SELECT * INTO event_row FROM public.billable_events event
  WHERE event.tenant_id=NEW.tenant_id AND event.id=NEW.billable_event_id;
  IF event_row.id IS NOT NULL THEN
    SELECT configuration.* INTO configuration_row
    FROM public.configuration_versions configuration
    WHERE configuration.tenant_id=event_row.tenant_id AND configuration.kind='billing'
      AND configuration.status IN ('active','retired')
      AND configuration.activated_at<=event_row.occurred_at
      AND (configuration.retired_at IS NULL
        OR configuration.retired_at>event_row.occurred_at)
      AND configuration.effective_from<=event_row.occurred_at
      AND (configuration.effective_until IS NULL
        OR configuration.effective_until>event_row.occurred_at)
      AND (configuration.inventory_owner_id IS NULL
        OR configuration.inventory_owner_id=event_row.inventory_owner_id)
      AND (configuration.facility_id IS NULL
        OR configuration.facility_id=event_row.facility_id)
      AND configuration.definition->>'event_type'=event_row.event_type
      AND configuration.definition->>'unit'=event_row.unit
      AND configuration.definition->>'currency'=NEW.currency
    ORDER BY CASE configuration.scope_level WHEN 'owner_facility' THEN 2
      WHEN 'inventory_owner' THEN 1 WHEN 'facility' THEN 1 ELSE 0 END DESC,
      configuration.effective_from DESC,configuration.revision DESC,configuration.id DESC
    LIMIT 1 FOR SHARE;
  END IF;

  IF NEW.decision_policy_source='configuration' THEN
    IF configuration_row.id IS NULL
      OR NEW.rate_version_id IS NOT NULL OR NEW.contract_rate_revision IS NOT NULL
      OR NEW.decision_configuration_id IS DISTINCT FROM configuration_row.id
      OR NEW.decision_configuration_revision IS DISTINCT FROM
        (CASE configuration_row.status WHEN 'retired' THEN configuration_row.revision-1
              ELSE configuration_row.revision END)
      OR NEW.decision_scope_level IS DISTINCT FROM configuration_row.scope_level
      OR NEW.decision_inventory_owner_id IS DISTINCT FROM configuration_row.inventory_owner_id
      OR NEW.decision_facility_id IS DISTINCT FROM configuration_row.facility_id
      OR NEW.event_type IS DISTINCT FROM configuration_row.definition->>'event_type'
      OR NEW.unit IS DISTINCT FROM configuration_row.definition->>'unit'
      OR NEW.currency IS DISTINCT FROM configuration_row.definition->>'currency'
      OR NEW.rate_minor IS DISTINCT FROM
        (configuration_row.definition->>'rate_minor')::bigint
      OR NEW.minimum_charge_minor IS DISTINCT FROM
        (configuration_row.definition->>'minimum_charge_minor')::bigint THEN
      RAISE EXCEPTION 'Billing charge does not match its effective configuration'
        USING ERRCODE='55000';
    END IF;
  ELSE
    IF configuration_row.id IS NOT NULL OR NEW.decision_configuration_id IS NOT NULL
      OR NEW.decision_configuration_revision IS NOT NULL
      OR NEW.decision_scope_level IS NOT NULL
      OR NEW.decision_inventory_owner_id IS NOT NULL OR NEW.decision_facility_id IS NOT NULL THEN
      RAISE EXCEPTION 'contract Billing rate cannot bypass an effective configuration'
        USING ERRCODE='55000';
    END IF;
    SELECT rate.* INTO rate_row FROM public.billing_rate_versions rate
    WHERE rate.tenant_id=event_row.tenant_id AND rate.contract_id=event_row.contract_id
      AND rate.event_type=event_row.event_type AND rate.unit=event_row.unit
      AND rate.currency=NEW.currency AND rate.effective_from<=event_row.occurred_at
      AND (rate.effective_until IS NULL OR rate.effective_until>event_row.occurred_at)
    ORDER BY rate.revision DESC,rate.id DESC LIMIT 1 FOR SHARE;
    IF rate_row.id IS NULL OR NEW.rate_version_id IS DISTINCT FROM rate_row.id
      OR NEW.contract_rate_revision IS DISTINCT FROM rate_row.revision
      OR NEW.rate_minor IS DISTINCT FROM rate_row.rate_minor
      OR NEW.minimum_charge_minor IS DISTINCT FROM rate_row.minimum_charge_minor THEN
      RAISE EXCEPTION 'Billing charge does not match its effective contract rate'
        USING ERRCODE='55000';
    END IF;
  END IF;

  calculated_hash:=public.billing_decision_policy_hash(
    NEW.decision_policy_source,NEW.rate_version_id,NEW.contract_rate_revision,
    NEW.decision_configuration_id,NEW.decision_configuration_revision,
    NEW.decision_scope_level,NEW.decision_inventory_owner_id,NEW.decision_facility_id,
    NEW.event_type,NEW.unit,NEW.currency,NEW.rate_minor,NEW.minimum_charge_minor);
  gross:=NEW.rate_minor::numeric*NEW.quantity;
  amount:=GREATEST(gross,NEW.minimum_charge_minor::numeric);
  IF run_row.id IS NULL OR run_row.status<>'pending_review'
     OR event_row.id IS NULL
     OR NEW.inventory_owner_id IS DISTINCT FROM run_row.inventory_owner_id
     OR NEW.contract_id IS DISTINCT FROM run_row.contract_id
     OR NEW.inventory_owner_id IS DISTINCT FROM event_row.inventory_owner_id
     OR NEW.facility_id IS DISTINCT FROM event_row.facility_id
     OR (run_row.facility_id IS NOT NULL
       AND NEW.facility_id IS DISTINCT FROM run_row.facility_id)
     OR event_row.occurred_at<run_row.period_from OR event_row.occurred_at>=run_row.period_until
     OR NEW.contract_id IS DISTINCT FROM event_row.contract_id
     OR NEW.event_type IS DISTINCT FROM event_row.event_type
     OR NEW.unit IS DISTINCT FROM event_row.unit
     OR NEW.quantity IS DISTINCT FROM event_row.quantity
     OR NEW.currency IS DISTINCT FROM run_row.currency
     OR gross>9223372036854775807 OR NEW.gross_minor IS DISTINCT FROM gross
     OR amount>9223372036854775807 OR NEW.amount_minor IS DISTINCT FROM amount
     OR NEW.source_type IS DISTINCT FROM event_row.source_type
     OR NEW.source_reference IS DISTINCT FROM event_row.source_reference
     OR NEW.occurred_at IS DISTINCT FROM event_row.occurred_at
     OR NEW.decision_policy_hash IS DISTINCT FROM calculated_hash
     OR EXISTS(
       SELECT 1 FROM public.billing_charges prior_charge
       JOIN public.billing_reconciliation_runs prior_run
         ON prior_run.tenant_id=prior_charge.tenant_id
        AND prior_run.id=prior_charge.reconciliation_run_id
       WHERE prior_charge.tenant_id=NEW.tenant_id
         AND prior_charge.billable_event_id=NEW.billable_event_id
         AND prior_run.status<>'rejected') THEN
    RAISE EXCEPTION 'billing charge does not reconcile its run, event, and policy'
      USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $$;

GRANT EXECUTE ON FUNCTION public.billing_decision_policy_hash(
  text,bigint,bigint,bigint,bigint,text,bigint,bigint,text,text,text,bigint,bigint
) TO wareboxes_app;
REVOKE ALL ON FUNCTION public.billing_decision_policy_hash(
  text,bigint,bigint,bigint,bigint,text,bigint,bigint,text,text,text,bigint,bigint
) FROM PUBLIC;

-- Governed platform support access. Support principals are never ordinary tenant
-- members: the membership row exists only so immutable operational evidence can
-- retain actor foreign keys after a grant expires or is revoked.
ALTER TABLE public.tenant_memberships
  ADD COLUMN support_managed boolean NOT NULL DEFAULT false,
  ADD CONSTRAINT tenant_memberships_support_default_check
    CHECK(NOT support_managed OR NOT is_default);

CREATE TABLE public.support_access_grants (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES public.tenants(id),
  revision bigint NOT NULL DEFAULT 1,
  status text NOT NULL DEFAULT 'pending',
  reason text NOT NULL,
  requested_at timestamptz NOT NULL,
  requested_by_user_id bigint NOT NULL REFERENCES public.users(id),
  expires_at timestamptz NOT NULL,
  all_facilities boolean NOT NULL DEFAULT false,
  all_inventory_owners boolean NOT NULL DEFAULT false,
  approved_at timestamptz,
  approved_by_user_id bigint REFERENCES public.users(id),
  rejected_at timestamptz,
  rejected_by_user_id bigint REFERENCES public.users(id),
  rejection_reason text,
  revoked_at timestamptz,
  revoked_by_user_id bigint REFERENCES public.users(id),
  revocation_reason text,
  CONSTRAINT support_access_grants_tenant_id_id_unique UNIQUE(tenant_id,id),
  CONSTRAINT support_access_grants_revision_check CHECK(revision>0),
  CONSTRAINT support_access_grants_status_check
    CHECK(status IN ('pending','active','rejected','revoked')),
  CONSTRAINT support_access_grants_reason_check CHECK(
    reason=btrim(reason) AND reason<>'' AND char_length(reason)<=500
      AND reason!~'[[:cntrl:]]'),
  CONSTRAINT support_access_grants_window_check CHECK(
    expires_at>requested_at AND expires_at<=requested_at+interval '8 hours'),
  CONSTRAINT support_access_grants_rejection_reason_check CHECK(
    rejection_reason IS NULL OR (rejection_reason=btrim(rejection_reason)
      AND rejection_reason<>'' AND char_length(rejection_reason)<=500
      AND rejection_reason!~'[[:cntrl:]]')),
  CONSTRAINT support_access_grants_revocation_reason_check CHECK(
    revocation_reason IS NULL OR (revocation_reason=btrim(revocation_reason)
      AND revocation_reason<>'' AND char_length(revocation_reason)<=500
      AND revocation_reason!~'[[:cntrl:]]')),
  CONSTRAINT support_access_grants_lifecycle_check CHECK(
    (status='pending' AND revision=1 AND approved_at IS NULL
      AND approved_by_user_id IS NULL AND rejected_at IS NULL
      AND rejected_by_user_id IS NULL AND rejection_reason IS NULL
      AND revoked_at IS NULL AND revoked_by_user_id IS NULL
      AND revocation_reason IS NULL)
    OR (status='active' AND revision=2 AND approved_at IS NOT NULL
      AND approved_by_user_id IS NOT NULL
      AND approved_by_user_id<>requested_by_user_id
      AND approved_at>=requested_at AND approved_at<expires_at
      AND rejected_at IS NULL AND rejected_by_user_id IS NULL
      AND rejection_reason IS NULL AND revoked_at IS NULL
      AND revoked_by_user_id IS NULL AND revocation_reason IS NULL)
    OR (status='rejected' AND revision=2 AND approved_at IS NULL
      AND approved_by_user_id IS NULL AND rejected_at IS NOT NULL
      AND rejected_by_user_id IS NOT NULL AND rejection_reason IS NOT NULL
      AND revoked_at IS NULL AND revoked_by_user_id IS NULL
      AND revocation_reason IS NULL)
    OR (status='revoked' AND revision=3 AND approved_at IS NOT NULL
      AND approved_by_user_id IS NOT NULL
      AND approved_by_user_id<>requested_by_user_id
      AND rejected_at IS NULL AND rejected_by_user_id IS NULL
      AND rejection_reason IS NULL AND revoked_at IS NOT NULL
      AND revoked_by_user_id IS NOT NULL AND revocation_reason IS NOT NULL
      AND revoked_at>=approved_at))
);
CREATE INDEX support_access_grants_platform_history_idx
ON public.support_access_grants(requested_at DESC,id DESC);
CREATE INDEX support_access_grants_principal_lookup_idx
ON public.support_access_grants(tenant_id,requested_by_user_id,status,expires_at DESC,id DESC);

CREATE TABLE public.support_access_facilities (
  support_access_grant_id bigint NOT NULL,
  tenant_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  PRIMARY KEY(support_access_grant_id,facility_id),
  FOREIGN KEY(tenant_id,support_access_grant_id)
    REFERENCES public.support_access_grants(tenant_id,id),
  FOREIGN KEY(tenant_id,facility_id) REFERENCES public.facilities(tenant_id,id)
);

CREATE TABLE public.support_access_inventory_owners (
  support_access_grant_id bigint NOT NULL,
  tenant_id bigint NOT NULL,
  inventory_owner_id bigint NOT NULL,
  PRIMARY KEY(support_access_grant_id,inventory_owner_id),
  FOREIGN KEY(tenant_id,support_access_grant_id)
    REFERENCES public.support_access_grants(tenant_id,id),
  FOREIGN KEY(tenant_id,inventory_owner_id)
    REFERENCES public.inventory_owners(tenant_id,id)
);

CREATE TABLE public.support_access_permissions (
  support_access_grant_id bigint NOT NULL,
  tenant_id bigint NOT NULL,
  permission_name text NOT NULL,
  PRIMARY KEY(support_access_grant_id,permission_name),
  FOREIGN KEY(tenant_id,support_access_grant_id)
    REFERENCES public.support_access_grants(tenant_id,id),
  CONSTRAINT support_access_permissions_name_check CHECK(
    permission_name<>'admin' AND permission_name=lower(permission_name)
      AND permission_name~'^[a-z0-9_]+$' AND char_length(permission_name)<=64)
);

CREATE TABLE public.support_access_events (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  support_access_grant_id bigint NOT NULL,
  tenant_id bigint NOT NULL,
  action text NOT NULL,
  grant_revision bigint NOT NULL,
  actor_user_id bigint NOT NULL REFERENCES public.users(id),
  occurred_at timestamptz NOT NULL,
  reason text,
  request_id text,
  evidence jsonb NOT NULL,
  FOREIGN KEY(tenant_id,support_access_grant_id)
    REFERENCES public.support_access_grants(tenant_id,id),
  CONSTRAINT support_access_events_grant_revision_unique
    UNIQUE(support_access_grant_id,grant_revision),
  CONSTRAINT support_access_events_action_check
    CHECK(action IN ('requested','approved','rejected','revoked')),
  CONSTRAINT support_access_events_revision_check CHECK(grant_revision>0),
  CONSTRAINT support_access_events_reason_check CHECK(reason IS NULL OR (
    reason=btrim(reason) AND reason<>'' AND char_length(reason)<=500
      AND reason!~'[[:cntrl:]]')),
  CONSTRAINT support_access_events_request_id_check CHECK(request_id IS NULL OR (
    request_id=btrim(request_id) AND request_id<>'' AND char_length(request_id)<=128)),
  CONSTRAINT support_access_events_evidence_check CHECK(jsonb_typeof(evidence)='object')
);
CREATE INDEX support_access_events_history_idx
ON public.support_access_events(support_access_grant_id,occurred_at DESC,id DESC);

ALTER TABLE public.support_access_grants ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.support_access_grants FORCE ROW LEVEL SECURITY;
ALTER TABLE public.support_access_facilities ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.support_access_facilities FORCE ROW LEVEL SECURITY;
ALTER TABLE public.support_access_inventory_owners ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.support_access_inventory_owners FORCE ROW LEVEL SECURITY;
ALTER TABLE public.support_access_permissions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.support_access_permissions FORCE ROW LEVEL SECURITY;
ALTER TABLE public.support_access_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.support_access_events FORCE ROW LEVEL SECURITY;

CREATE POLICY support_access_grants_platform_isolation
ON public.support_access_grants
USING(public.platform_actor_is_administrator(
  NULLIF(current_setting('wareboxes.platform_actor_user_id',true),'')::bigint))
WITH CHECK(public.platform_actor_is_administrator(
  NULLIF(current_setting('wareboxes.platform_actor_user_id',true),'')::bigint));
CREATE POLICY support_access_facilities_platform_isolation
ON public.support_access_facilities
USING(public.platform_actor_is_administrator(
  NULLIF(current_setting('wareboxes.platform_actor_user_id',true),'')::bigint))
WITH CHECK(public.platform_actor_is_administrator(
  NULLIF(current_setting('wareboxes.platform_actor_user_id',true),'')::bigint));
CREATE POLICY support_access_inventory_owners_platform_isolation
ON public.support_access_inventory_owners
USING(public.platform_actor_is_administrator(
  NULLIF(current_setting('wareboxes.platform_actor_user_id',true),'')::bigint))
WITH CHECK(public.platform_actor_is_administrator(
  NULLIF(current_setting('wareboxes.platform_actor_user_id',true),'')::bigint));
CREATE POLICY support_access_permissions_platform_isolation
ON public.support_access_permissions
USING(public.platform_actor_is_administrator(
  NULLIF(current_setting('wareboxes.platform_actor_user_id',true),'')::bigint))
WITH CHECK(public.platform_actor_is_administrator(
  NULLIF(current_setting('wareboxes.platform_actor_user_id',true),'')::bigint));
CREATE POLICY support_access_events_platform_isolation
ON public.support_access_events
USING(public.platform_actor_is_administrator(
  NULLIF(current_setting('wareboxes.platform_actor_user_id',true),'')::bigint))
WITH CHECK(public.platform_actor_is_administrator(
  NULLIF(current_setting('wareboxes.platform_actor_user_id',true),'')::bigint));

CREATE FUNCTION public.active_support_access_scope(
  checked_tenant_id bigint, checked_user_id bigint
) RETURNS TABLE(
  support_access_grant_id bigint,
  all_facilities boolean,
  facility_ids bigint[],
  all_inventory_owners boolean,
  inventory_owner_ids bigint[]
) LANGUAGE sql STABLE SECURITY DEFINER
SET search_path TO 'pg_catalog','public' AS $$
  SELECT grant_record.id,grant_record.all_facilities,
    ARRAY(SELECT scope.facility_id FROM public.support_access_facilities scope
      JOIN public.facilities facility ON facility.tenant_id=scope.tenant_id
        AND facility.id=scope.facility_id AND facility.deleted IS NULL
      WHERE scope.support_access_grant_id=grant_record.id
      ORDER BY scope.facility_id),
    grant_record.all_inventory_owners,
    ARRAY(SELECT scope.inventory_owner_id
      FROM public.support_access_inventory_owners scope
      JOIN public.inventory_owners owner ON owner.tenant_id=scope.tenant_id
        AND owner.id=scope.inventory_owner_id AND owner.deleted IS NULL
      WHERE scope.support_access_grant_id=grant_record.id
      ORDER BY scope.inventory_owner_id)
  FROM public.support_access_grants grant_record
  JOIN public.tenant_memberships membership
    ON membership.tenant_id=grant_record.tenant_id
   AND membership.user_id=grant_record.requested_by_user_id
   AND membership.deleted IS NULL AND membership.support_managed
  JOIN public.tenants tenant ON tenant.id=grant_record.tenant_id
    AND tenant.deleted IS NULL AND tenant.status='active'
  WHERE grant_record.tenant_id=checked_tenant_id
    AND grant_record.requested_by_user_id=checked_user_id
    AND grant_record.status='active' AND grant_record.expires_at>CURRENT_TIMESTAMP
    AND public.platform_actor_is_administrator(checked_user_id)
  ORDER BY grant_record.approved_at DESC,grant_record.id DESC LIMIT 1
$$;

CREATE FUNCTION public.active_support_access_permissions(
  checked_tenant_id bigint, checked_user_id bigint
) RETURNS TABLE(
  id bigint, name text, description text, created timestamptz, deleted timestamptz
) LANGUAGE sql STABLE SECURITY DEFINER
SET search_path TO 'pg_catalog','public' AS $$
  SELECT permission.id,upper(permission.name),permission.description,
    permission.created,permission.deleted
  FROM public.active_support_access_scope(checked_tenant_id,checked_user_id) active_scope
  JOIN public.support_access_permissions support_permission
    ON support_permission.support_access_grant_id=active_scope.support_access_grant_id
   AND support_permission.tenant_id=checked_tenant_id
  JOIN public.permissions permission ON permission.tenant_id=support_permission.tenant_id
   AND permission.name=support_permission.permission_name AND permission.deleted IS NULL
  ORDER BY permission.id
$$;

CREATE FUNCTION public.support_access_permission_granted(
  checked_tenant_id bigint, checked_user_id bigint, checked_permission text
) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER
SET search_path TO 'pg_catalog','public' AS $$
  SELECT checked_permission IS NOT NULL AND EXISTS(
    SELECT 1 FROM public.active_support_access_permissions(
      checked_tenant_id,checked_user_id) permission
    WHERE permission.name=upper(checked_permission))
$$;

CREATE FUNCTION public.lock_support_access_permission(
  checked_tenant_id bigint,checked_user_id bigint,checked_permissions text[]
) RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path TO 'pg_catalog','public' AS $$
DECLARE grant_id bigint;
BEGIN
  SELECT grant_record.id INTO grant_id
  FROM public.support_access_grants grant_record
  JOIN public.tenant_memberships membership
    ON membership.tenant_id=grant_record.tenant_id
   AND membership.user_id=grant_record.requested_by_user_id
   AND membership.deleted IS NULL AND membership.support_managed
  JOIN public.tenants tenant ON tenant.id=grant_record.tenant_id
    AND tenant.deleted IS NULL AND tenant.status='active'
  WHERE grant_record.tenant_id=checked_tenant_id
    AND grant_record.requested_by_user_id=checked_user_id
    AND grant_record.status='active' AND grant_record.expires_at>CURRENT_TIMESTAMP
    AND public.platform_actor_is_administrator(checked_user_id)
  ORDER BY grant_record.approved_at DESC,grant_record.id DESC LIMIT 1
  FOR SHARE OF grant_record,membership,tenant;
  IF grant_id IS NULL THEN RETURN false; END IF;
  RETURN EXISTS(
    SELECT 1 FROM public.support_access_permissions support_permission
    JOIN public.permissions permission
      ON permission.tenant_id=support_permission.tenant_id
     AND permission.name=support_permission.permission_name
     AND permission.deleted IS NULL
    WHERE support_permission.support_access_grant_id=grant_id
      AND upper(permission.name)=ANY(checked_permissions)
    FOR SHARE OF support_permission,permission);
END $$;

CREATE FUNCTION public.validate_support_access_grant() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE actor_id bigint;
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'support access grants cannot be deleted' USING ERRCODE='55000';
  END IF;
  actor_id:=NULLIF(current_setting('wareboxes.platform_actor_user_id',true),'')::bigint;
  IF actor_id IS NULL OR NOT public.platform_actor_is_administrator(actor_id) THEN
    RAISE EXCEPTION 'support access mutation is not authorized' USING ERRCODE='42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'support-access:'||NEW.tenant_id::text||':'||NEW.requested_by_user_id::text,0));
  IF TG_OP='INSERT' THEN
    IF NEW.status<>'pending' OR NEW.revision<>1
      OR NEW.requested_by_user_id<>actor_id
      OR NOT EXISTS(SELECT 1 FROM public.tenants tenant
        WHERE tenant.id=NEW.tenant_id AND tenant.deleted IS NULL AND tenant.status='active')
      OR EXISTS(SELECT 1 FROM public.tenant_memberships membership
        WHERE membership.tenant_id=NEW.tenant_id AND membership.user_id=actor_id
          AND membership.deleted IS NULL AND NOT membership.support_managed)
      OR EXISTS(SELECT 1 FROM public.support_access_grants existing
        WHERE existing.tenant_id=NEW.tenant_id
          AND existing.requested_by_user_id=actor_id
          AND (existing.status='pending' OR (existing.status='active'
            AND existing.expires_at>CURRENT_TIMESTAMP))) THEN
      RAISE EXCEPTION 'invalid support access request' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(NEW.id,NEW.tenant_id,NEW.reason,NEW.requested_at,
      NEW.requested_by_user_id,NEW.expires_at,NEW.all_facilities,
      NEW.all_inventory_owners)
    IS DISTINCT FROM
    ROW(OLD.id,OLD.tenant_id,OLD.reason,OLD.requested_at,
      OLD.requested_by_user_id,OLD.expires_at,OLD.all_facilities,
      OLD.all_inventory_owners)
    OR NEW.revision<>OLD.revision+1 THEN
    RAISE EXCEPTION 'support access request evidence is immutable' USING ERRCODE='55000';
  END IF;
  IF OLD.status='pending' AND NEW.status='active' THEN
    IF actor_id=OLD.requested_by_user_id OR NEW.approved_by_user_id<>actor_id
      OR NEW.approved_at IS NULL OR NEW.approved_at>=NEW.expires_at
      OR NEW.rejected_at IS NOT NULL OR NEW.rejected_by_user_id IS NOT NULL
      OR NEW.rejection_reason IS NOT NULL OR NEW.revoked_at IS NOT NULL
      OR NEW.revoked_by_user_id IS NOT NULL OR NEW.revocation_reason IS NOT NULL
      OR EXISTS(SELECT 1 FROM public.support_access_grants existing
        WHERE existing.id<>NEW.id AND existing.tenant_id=NEW.tenant_id
          AND existing.requested_by_user_id=NEW.requested_by_user_id
          AND existing.status='active' AND existing.expires_at>CURRENT_TIMESTAMP) THEN
      RAISE EXCEPTION 'invalid support access approval' USING ERRCODE='23514';
    END IF;
  ELSIF OLD.status='pending' AND NEW.status='rejected' THEN
    IF NEW.rejected_by_user_id<>actor_id OR NEW.rejected_at IS NULL
      OR NEW.rejection_reason IS NULL OR NEW.approved_at IS NOT NULL
      OR NEW.approved_by_user_id IS NOT NULL OR NEW.revoked_at IS NOT NULL
      OR NEW.revoked_by_user_id IS NOT NULL OR NEW.revocation_reason IS NOT NULL THEN
      RAISE EXCEPTION 'invalid support access rejection' USING ERRCODE='23514';
    END IF;
  ELSIF OLD.status='active' AND NEW.status='revoked' THEN
    IF ROW(NEW.approved_at,NEW.approved_by_user_id)
        IS DISTINCT FROM ROW(OLD.approved_at,OLD.approved_by_user_id)
      OR NEW.revoked_by_user_id<>actor_id OR NEW.revoked_at IS NULL
      OR NEW.revocation_reason IS NULL THEN
      RAISE EXCEPTION 'invalid support access revocation' USING ERRCODE='23514';
    END IF;
  ELSE
    RAISE EXCEPTION 'invalid support access transition' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.guard_support_access_scope() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE actor_id bigint; grant_id bigint; grant_row public.support_access_grants%ROWTYPE;
BEGIN
  IF TG_OP<>'INSERT' THEN
    RAISE EXCEPTION 'support access scope evidence is immutable' USING ERRCODE='55000';
  END IF;
  actor_id:=NULLIF(current_setting('wareboxes.platform_actor_user_id',true),'')::bigint;
  grant_id:=NEW.support_access_grant_id;
  SELECT * INTO grant_row FROM public.support_access_grants grant_record
    WHERE grant_record.id=grant_id FOR SHARE;
  IF grant_row.id IS NULL OR grant_row.status<>'pending'
    OR grant_row.requested_by_user_id<>actor_id
    OR NOT public.platform_actor_is_administrator(actor_id) THEN
    RAISE EXCEPTION 'support access scope mutation is not authorized' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.require_support_access_integrity() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE grant_id bigint; grant_row public.support_access_grants%ROWTYPE;
BEGIN
  IF TG_TABLE_NAME='support_access_grants' THEN
    grant_id:=NEW.id;
  ELSE
    grant_id:=NEW.support_access_grant_id;
  END IF;
  SELECT * INTO grant_row FROM public.support_access_grants grant_record
    WHERE grant_record.id=grant_id;
  IF grant_row.id IS NULL THEN RETURN NULL; END IF;
  IF (grant_row.all_facilities AND EXISTS(SELECT 1
      FROM public.support_access_facilities scope
      WHERE scope.support_access_grant_id=grant_id))
    OR (NOT grant_row.all_facilities AND NOT EXISTS(SELECT 1
      FROM public.support_access_facilities scope
      JOIN public.facilities facility ON facility.tenant_id=scope.tenant_id
        AND facility.id=scope.facility_id AND facility.deleted IS NULL
      WHERE scope.support_access_grant_id=grant_id))
    OR (grant_row.all_inventory_owners AND EXISTS(SELECT 1
      FROM public.support_access_inventory_owners scope
      WHERE scope.support_access_grant_id=grant_id))
    OR (NOT grant_row.all_inventory_owners AND NOT EXISTS(SELECT 1
      FROM public.support_access_inventory_owners scope
      JOIN public.inventory_owners owner ON owner.tenant_id=scope.tenant_id
        AND owner.id=scope.inventory_owner_id AND owner.deleted IS NULL
      WHERE scope.support_access_grant_id=grant_id))
    OR NOT EXISTS(SELECT 1 FROM public.support_access_permissions scope
      JOIN public.permissions permission ON permission.tenant_id=scope.tenant_id
        AND permission.name=scope.permission_name AND permission.deleted IS NULL
      WHERE scope.support_access_grant_id=grant_id
        AND permission.name<>'admin')
    OR EXISTS(SELECT 1 FROM public.support_access_permissions scope
      LEFT JOIN public.permissions permission ON permission.tenant_id=scope.tenant_id
        AND permission.name=scope.permission_name AND permission.deleted IS NULL
      WHERE scope.support_access_grant_id=grant_id AND permission.id IS NULL)
    OR (grant_row.status='active' AND NOT EXISTS(
      SELECT 1 FROM public.tenant_memberships membership
      WHERE membership.tenant_id=grant_row.tenant_id
        AND membership.user_id=grant_row.requested_by_user_id
        AND membership.deleted IS NULL AND membership.support_managed)) THEN
    RAISE EXCEPTION 'support access scope is incomplete or unavailable' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;

CREATE FUNCTION public.guard_support_managed_membership() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE actor_id bigint;
BEGIN
  IF NOT COALESCE(NEW.support_managed,false)
    AND NOT COALESCE(OLD.support_managed,false) THEN RETURN NEW; END IF;
  actor_id:=NULLIF(current_setting('wareboxes.platform_actor_user_id',true),'')::bigint;
  IF actor_id IS NULL OR NOT public.platform_actor_is_administrator(actor_id) THEN
    RAISE EXCEPTION 'support-managed memberships require platform authority'
      USING ERRCODE='42501';
  END IF;
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'support-managed memberships cannot be deleted' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.validate_support_access_event() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE actor_id bigint; grant_row public.support_access_grants%ROWTYPE;
BEGIN
  actor_id:=NULLIF(current_setting('wareboxes.platform_actor_user_id',true),'')::bigint;
  SELECT * INTO grant_row FROM public.support_access_grants grant_record
    WHERE grant_record.id=NEW.support_access_grant_id;
  IF actor_id IS NULL OR NEW.actor_user_id<>actor_id
    OR NOT public.platform_actor_is_administrator(actor_id)
    OR grant_row.id IS NULL OR NEW.tenant_id<>grant_row.tenant_id
    OR NEW.grant_revision<>grant_row.revision
    OR NOT ((NEW.action='requested' AND grant_row.status='pending'
          AND grant_row.requested_by_user_id=actor_id)
      OR (NEW.action='approved' AND grant_row.status='active'
          AND grant_row.approved_by_user_id=actor_id)
      OR (NEW.action='rejected' AND grant_row.status='rejected'
          AND grant_row.rejected_by_user_id=actor_id)
      OR (NEW.action='revoked' AND grant_row.status='revoked'
          AND grant_row.revoked_by_user_id=actor_id)) THEN
    RAISE EXCEPTION 'invalid support access event evidence' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.reject_support_access_event_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$ BEGIN
  RAISE EXCEPTION 'support access events are immutable' USING ERRCODE='55000';
END $$;

CREATE TRIGGER support_access_grants_validate BEFORE INSERT OR UPDATE OR DELETE
ON public.support_access_grants FOR EACH ROW
EXECUTE FUNCTION public.validate_support_access_grant();
CREATE TRIGGER support_access_facilities_guard BEFORE INSERT OR UPDATE OR DELETE
ON public.support_access_facilities FOR EACH ROW
EXECUTE FUNCTION public.guard_support_access_scope();
CREATE TRIGGER support_access_inventory_owners_guard BEFORE INSERT OR UPDATE OR DELETE
ON public.support_access_inventory_owners FOR EACH ROW
EXECUTE FUNCTION public.guard_support_access_scope();
CREATE TRIGGER support_access_permissions_guard BEFORE INSERT OR UPDATE OR DELETE
ON public.support_access_permissions FOR EACH ROW
EXECUTE FUNCTION public.guard_support_access_scope();
CREATE CONSTRAINT TRIGGER support_access_grants_require_integrity
AFTER INSERT OR UPDATE ON public.support_access_grants DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_support_access_integrity();
CREATE CONSTRAINT TRIGGER support_access_facilities_require_integrity
AFTER INSERT ON public.support_access_facilities DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_support_access_integrity();
CREATE CONSTRAINT TRIGGER support_access_inventory_owners_require_integrity
AFTER INSERT ON public.support_access_inventory_owners DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_support_access_integrity();
CREATE CONSTRAINT TRIGGER support_access_permissions_require_integrity
AFTER INSERT ON public.support_access_permissions DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_support_access_integrity();
CREATE TRIGGER tenant_memberships_guard_support BEFORE INSERT OR UPDATE OR DELETE
ON public.tenant_memberships FOR EACH ROW
EXECUTE FUNCTION public.guard_support_managed_membership();
CREATE TRIGGER support_access_events_validate BEFORE INSERT
ON public.support_access_events FOR EACH ROW
EXECUTE FUNCTION public.validate_support_access_event();
CREATE TRIGGER support_access_events_immutable BEFORE UPDATE OR DELETE
ON public.support_access_events FOR EACH ROW
EXECUTE FUNCTION public.reject_support_access_event_mutation();

CREATE OR REPLACE FUNCTION public.select_web_session_tenant(
  p_token_hash text,p_selected_tenant_id bigint
) RETURNS boolean LANGUAGE sql SECURITY DEFINER
SET search_path TO 'pg_catalog','public' AS $$
  WITH selected AS (
    UPDATE public.sessions session
    SET active_tenant_id=p_selected_tenant_id,last_seen_at=CURRENT_TIMESTAMP
    WHERE session.token=p_token_hash AND session.purpose='web'
      AND session.expires>CURRENT_TIMESTAMP
      AND EXISTS(SELECT 1 FROM public.tenant_memberships membership
        JOIN public.tenants tenant ON tenant.id=membership.tenant_id
        WHERE membership.tenant_id=p_selected_tenant_id
          AND membership.user_id=session.user_id AND membership.deleted IS NULL
          AND tenant.deleted IS NULL AND tenant.status='active'
          AND (NOT membership.support_managed OR EXISTS(
            SELECT 1 FROM public.active_support_access_scope(
              membership.tenant_id,membership.user_id))))
    RETURNING 1
  ) SELECT EXISTS(SELECT 1 FROM selected)
$$;

CREATE OR REPLACE FUNCTION public.web_session_identity(
  p_token_hash text,p_idle_ttl_seconds integer
) RETURNS TABLE(user_id bigint,tenant_id bigint)
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
BEGIN
  IF p_idle_ttl_seconds<60 OR p_idle_ttl_seconds>86400 THEN
    RAISE EXCEPTION 'web session idle TTL must be between 60 and 86400 seconds'
      USING ERRCODE='22023';
  END IF;
  RETURN QUERY UPDATE public.sessions session
  SET last_seen_at=CURRENT_TIMESTAMP
  FROM public.tenant_memberships membership,public.tenants tenant
  WHERE session.token=p_token_hash AND session.purpose='web'
    AND session.expires>CURRENT_TIMESTAMP
    AND session.last_seen_at>CURRENT_TIMESTAMP-p_idle_ttl_seconds*interval '1 second'
    AND session.active_tenant_id IS NOT NULL
    AND membership.tenant_id=session.active_tenant_id
    AND membership.user_id=session.user_id AND membership.deleted IS NULL
    AND tenant.id=membership.tenant_id AND tenant.deleted IS NULL AND tenant.status='active'
    AND (NOT membership.support_managed OR EXISTS(
      SELECT 1 FROM public.active_support_access_scope(
        membership.tenant_id,membership.user_id)))
  RETURNING session.user_id,session.active_tenant_id;
END $$;

GRANT SELECT,INSERT,UPDATE ON public.support_access_grants TO wareboxes_app;
GRANT SELECT,INSERT ON public.support_access_facilities TO wareboxes_app;
GRANT SELECT,INSERT ON public.support_access_inventory_owners TO wareboxes_app;
GRANT SELECT,INSERT ON public.support_access_permissions TO wareboxes_app;
GRANT SELECT,INSERT ON public.support_access_events TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.support_access_grants_id_seq TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.support_access_events_id_seq TO wareboxes_app;
GRANT EXECUTE ON FUNCTION public.active_support_access_scope(bigint,bigint)
TO wareboxes_app;
GRANT EXECUTE ON FUNCTION public.active_support_access_permissions(bigint,bigint)
TO wareboxes_app;
GRANT EXECUTE ON FUNCTION public.support_access_permission_granted(bigint,bigint,text)
TO wareboxes_app;
GRANT EXECUTE ON FUNCTION public.lock_support_access_permission(bigint,bigint,text[])
TO wareboxes_app;
REVOKE ALL ON FUNCTION public.active_support_access_scope(bigint,bigint) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.active_support_access_permissions(bigint,bigint) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.support_access_permission_granted(bigint,bigint,text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.lock_support_access_permission(bigint,bigint,text[]) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_support_access_grant() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_support_access_scope() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_support_access_integrity() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_support_managed_membership() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_support_access_event() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.reject_support_access_event_mutation() FROM PUBLIC;

-- Dynamic release snapshots the allocation-ready priority queue, freezes the
-- effective wave policy, and atomically releases the selected prefix. Manual
-- wave planning remains the safe fallback when no eligible work is selected.
CREATE TABLE public.dynamic_release_runs (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  inventory_owner_id bigint NOT NULL,
  destination_location_id bigint NOT NULL,
  pick_wave_id bigint,
  status text NOT NULL DEFAULT 'building',
  input_snapshot_at timestamptz NOT NULL,
  policy_source text NOT NULL,
  policy_configuration_id bigint,
  policy_configuration_revision bigint,
  policy_scope_level text,
  policy_scope_owner_id bigint,
  policy_scope_facility_id bigint,
  policy_definition jsonb NOT NULL,
  policy_hash text NOT NULL,
  eligible_order_count bigint NOT NULL,
  selected_order_count bigint NOT NULL,
  deferred_order_count bigint NOT NULL,
  released_by_user_id bigint NOT NULL,
  released_at timestamptz NOT NULL,
  UNIQUE(tenant_id,id),
  UNIQUE(tenant_id,pick_wave_id),
  CHECK(status IN ('building','sealed')),
  CHECK(policy_hash~'^[0-9a-f]{64}$'),
  CHECK(jsonb_typeof(policy_definition)='object'
    AND policy_definition ?& ARRAY['max_orders','require_complete_allocation']
    AND policy_definition-ARRAY['max_orders','require_complete_allocation']='{}'::jsonb
    AND jsonb_typeof(policy_definition->'max_orders')='number'
    AND (policy_definition->>'max_orders')::bigint BETWEEN 1 AND 10000
    AND jsonb_typeof(policy_definition->'require_complete_allocation')='boolean'),
  CHECK((policy_source='product_default'
      AND policy_configuration_id IS NULL
      AND policy_configuration_revision IS NULL
      AND policy_scope_level IS NULL
      AND policy_scope_owner_id IS NULL
      AND policy_scope_facility_id IS NULL)
    OR (policy_source='configuration'
      AND policy_configuration_id IS NOT NULL
      AND policy_configuration_revision>0
      AND ((policy_scope_level='tenant'
          AND policy_scope_owner_id IS NULL AND policy_scope_facility_id IS NULL)
        OR (policy_scope_level='inventory_owner'
          AND policy_scope_owner_id=inventory_owner_id AND policy_scope_facility_id IS NULL)
        OR (policy_scope_level='facility'
          AND policy_scope_owner_id IS NULL AND policy_scope_facility_id=facility_id)
        OR (policy_scope_level='owner_facility'
          AND policy_scope_owner_id=inventory_owner_id
          AND policy_scope_facility_id=facility_id)))),
  CHECK(eligible_order_count>=0 AND selected_order_count>=0
    AND deferred_order_count>=0
    AND eligible_order_count=selected_order_count+deferred_order_count
    AND selected_order_count<=(policy_definition->>'max_orders')::bigint),
  CHECK((selected_order_count=0 AND pick_wave_id IS NULL)
    OR (selected_order_count>0 AND pick_wave_id IS NOT NULL)),
  CHECK(released_at=input_snapshot_at),
  FOREIGN KEY(tenant_id) REFERENCES public.tenants(id),
  FOREIGN KEY(tenant_id,inventory_owner_id)
    REFERENCES public.inventory_owners(tenant_id,id),
  FOREIGN KEY(tenant_id,facility_id)
    REFERENCES public.facilities(tenant_id,id),
  FOREIGN KEY(tenant_id,inventory_owner_id,facility_id)
    REFERENCES public.inventory_owner_facilities(tenant_id,inventory_owner_id,facility_id),
  FOREIGN KEY(tenant_id,facility_id,destination_location_id)
    REFERENCES public.locations(tenant_id,facility_id,id),
  FOREIGN KEY(tenant_id,facility_id,pick_wave_id)
    REFERENCES public.pick_waves(tenant_id,facility_id,id),
  FOREIGN KEY(tenant_id,policy_configuration_id)
    REFERENCES public.configuration_versions(tenant_id,id),
  FOREIGN KEY(tenant_id,released_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id)
);

CREATE TABLE public.dynamic_release_candidates (
  tenant_id bigint NOT NULL,
  dynamic_release_run_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  inventory_owner_id bigint NOT NULL,
  pick_wave_id bigint NOT NULL,
  order_id bigint NOT NULL,
  order_key text NOT NULL,
  order_revision bigint NOT NULL,
  selection_rank bigint NOT NULL,
  rush boolean NOT NULL,
  ship_by timestamptz,
  order_created_at timestamptz NOT NULL,
  demand_qty bigint NOT NULL,
  allocated_qty bigint NOT NULL,
  PRIMARY KEY(tenant_id,dynamic_release_run_id,selection_rank),
  UNIQUE(tenant_id,dynamic_release_run_id,order_id),
  CHECK(order_key=btrim(order_key) AND order_key<>'' AND char_length(order_key)<=200),
  CHECK(order_revision>0 AND selection_rank>0),
  CHECK(demand_qty>0 AND allocated_qty=demand_qty),
  FOREIGN KEY(tenant_id,dynamic_release_run_id)
    REFERENCES public.dynamic_release_runs(tenant_id,id),
  FOREIGN KEY(tenant_id,inventory_owner_id,facility_id)
    REFERENCES public.inventory_owner_facilities(tenant_id,inventory_owner_id,facility_id),
  FOREIGN KEY(tenant_id,inventory_owner_id,order_id)
    REFERENCES public.orders(tenant_id,inventory_owner_id,id),
  FOREIGN KEY(tenant_id,pick_wave_id,order_id)
    REFERENCES public.pick_wave_orders(tenant_id,pick_wave_id,order_id)
);

CREATE INDEX dynamic_release_runs_scope_idx
ON public.dynamic_release_runs(tenant_id,facility_id,inventory_owner_id,released_at DESC,id DESC);

CREATE FUNCTION public.validate_dynamic_release_run() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE configuration_row public.configuration_versions%ROWTYPE;
DECLARE resolved_configuration_id bigint;
DECLARE calculated_hash text;
DECLARE wave_row public.pick_waves%ROWTYPE;
DECLARE destination_row public.locations%ROWTYPE;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(format(
    'configuration-kind:%s:wave',NEW.tenant_id),0));
  IF NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint
      IS DISTINCT FROM NEW.released_by_user_id
    OR NOT public.work_orchestration_user_has_permission(
      NEW.tenant_id,NEW.released_by_user_id,'wms_supervisor')
    OR NOT EXISTS(SELECT 1 FROM public.tenant_memberships membership
      WHERE membership.tenant_id=NEW.tenant_id
        AND membership.user_id=NEW.released_by_user_id
        AND membership.deleted IS NULL
        AND (membership.all_facilities OR EXISTS(
          SELECT 1 FROM public.user_facilities assignment
          WHERE assignment.tenant_id=membership.tenant_id
            AND assignment.user_id=membership.user_id
            AND assignment.facility_id=NEW.facility_id
            AND assignment.deleted IS NULL))
        AND (membership.all_inventory_owners OR EXISTS(
          SELECT 1 FROM public.user_inventory_owners assignment
          WHERE assignment.tenant_id=membership.tenant_id
            AND assignment.user_id=membership.user_id
            AND assignment.inventory_owner_id=NEW.inventory_owner_id
            AND assignment.deleted IS NULL))) THEN
    RAISE EXCEPTION 'dynamic release actor is not authorized for its exact scope'
      USING ERRCODE='23514';
  END IF;
  calculated_hash:=encode(sha256(convert_to(
    'wave-policy-v1|'||(NEW.policy_definition->>'max_orders')||'|'||
    (NEW.policy_definition->>'require_complete_allocation'),'UTF8')),'hex');
  IF calculated_hash IS DISTINCT FROM NEW.policy_hash THEN
    RAISE EXCEPTION 'dynamic release policy hash does not match its snapshot'
      USING ERRCODE='23514';
  END IF;
  SELECT * INTO destination_row FROM public.locations location
  WHERE location.tenant_id=NEW.tenant_id AND location.facility_id=NEW.facility_id
    AND location.id=NEW.destination_location_id AND location.deleted IS NULL
  FOR SHARE;
  IF NOT FOUND OR NOT destination_row.active OR destination_row.pickable
    OR destination_row.receivable OR destination_row.barcode IS NULL
    OR btrim(destination_row.barcode)='' THEN
    RAISE EXCEPTION 'dynamic release destination is not scanner-ready staging inventory'
      USING ERRCODE='55000';
  END IF;
  SELECT configuration.id INTO resolved_configuration_id
  FROM public.configuration_versions configuration
  WHERE configuration.tenant_id=NEW.tenant_id
    AND configuration.kind='wave' AND configuration.status='active'
    AND configuration.effective_from<=NEW.input_snapshot_at
    AND (configuration.effective_until IS NULL
      OR configuration.effective_until>NEW.input_snapshot_at)
    AND (configuration.inventory_owner_id IS NULL
      OR configuration.inventory_owner_id=NEW.inventory_owner_id)
    AND (configuration.facility_id IS NULL
      OR configuration.facility_id=NEW.facility_id)
  ORDER BY CASE configuration.scope_level
      WHEN 'owner_facility' THEN 2 WHEN 'inventory_owner' THEN 1
      WHEN 'facility' THEN 1 ELSE 0 END DESC,
    configuration.effective_from DESC,configuration.revision DESC,configuration.id DESC
  LIMIT 1;
  IF NEW.policy_source='product_default' THEN
    IF resolved_configuration_id IS NOT NULL
      OR NEW.policy_definition<>jsonb_build_object(
        'max_orders',10000,'require_complete_allocation',false) THEN
      RAISE EXCEPTION 'dynamic release product default is not effective or exact'
        USING ERRCODE='23514';
    END IF;
  ELSE
    SELECT * INTO configuration_row FROM public.configuration_versions configuration
    WHERE configuration.tenant_id=NEW.tenant_id
      AND configuration.id=NEW.policy_configuration_id;
    IF NOT FOUND OR resolved_configuration_id IS DISTINCT FROM configuration_row.id
      OR configuration_row.kind<>'wave'
      OR configuration_row.revision<>NEW.policy_configuration_revision
      OR configuration_row.scope_level<>NEW.policy_scope_level
      OR configuration_row.inventory_owner_id IS DISTINCT FROM NEW.policy_scope_owner_id
      OR configuration_row.facility_id IS DISTINCT FROM NEW.policy_scope_facility_id
      OR configuration_row.definition-'kind'<>NEW.policy_definition THEN
      RAISE EXCEPTION 'dynamic release configuration snapshot is stale or inconsistent'
        USING ERRCODE='23514';
    END IF;
  END IF;
  IF NEW.pick_wave_id IS NOT NULL THEN
    SELECT * INTO wave_row FROM public.pick_waves wave
    WHERE wave.tenant_id=NEW.tenant_id AND wave.facility_id=NEW.facility_id
      AND wave.id=NEW.pick_wave_id FOR SHARE;
    IF NOT FOUND OR wave_row.status<>'planned'
      OR wave_row.destination_location_id<>NEW.destination_location_id
      OR wave_row.order_count<>NEW.selected_order_count
      OR wave_row.planned_by_user_id<>NEW.released_by_user_id
      OR wave_row.planned_at<>NEW.input_snapshot_at
      OR EXISTS(SELECT 1 FROM public.pick_wave_orders member
        WHERE member.tenant_id=NEW.tenant_id AND member.pick_wave_id=NEW.pick_wave_id
          AND (member.inventory_owner_id<>NEW.inventory_owner_id
            OR member.wave_policy_hash<>NEW.policy_hash)) THEN
      RAISE EXCEPTION 'dynamic release wave does not match its frozen scope and policy'
        USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.validate_dynamic_release_candidate() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE run_row public.dynamic_release_runs%ROWTYPE;
DECLARE order_row public.orders%ROWTYPE;
DECLARE actual_demand bigint;
DECLARE actual_allocated bigint;
BEGIN
  SELECT * INTO run_row FROM public.dynamic_release_runs run
  WHERE run.tenant_id=NEW.tenant_id AND run.id=NEW.dynamic_release_run_id FOR SHARE;
  SELECT * INTO order_row FROM public.orders order_header
  WHERE order_header.tenant_id=NEW.tenant_id
    AND order_header.inventory_owner_id=NEW.inventory_owner_id
    AND order_header.id=NEW.order_id AND order_header.deleted IS NULL FOR SHARE;
  SELECT COALESCE(SUM(demand.effective_qty),0)::bigint,
    COALESCE(SUM((SELECT COALESCE(SUM(allocation.qty),0)::bigint
      FROM public.inventory_reservations reservation
      JOIN public.inventory_allocations allocation
        ON allocation.tenant_id=reservation.tenant_id
       AND allocation.inventory_owner_id=reservation.inventory_owner_id
       AND allocation.reservation_id=reservation.id
      WHERE reservation.tenant_id=demand.tenant_id
        AND reservation.inventory_owner_id=demand.inventory_owner_id
        AND reservation.order_id=demand.order_id
        AND reservation.order_item_id=demand.order_item_id
        AND reservation.facility_id=NEW.facility_id
        AND reservation.status='active' AND reservation.deleted IS NULL
        AND allocation.facility_id=NEW.facility_id
        AND allocation.status='allocated' AND allocation.deleted IS NULL
        AND allocation.execution_stage='pick_source')),0)::bigint
  INTO actual_demand,actual_allocated
  FROM public.outbound_effective_demand demand
  WHERE demand.tenant_id=NEW.tenant_id
    AND demand.inventory_owner_id=NEW.inventory_owner_id
    AND demand.order_id=NEW.order_id;
  IF run_row.id IS NULL OR run_row.status<>'building'
    OR run_row.facility_id<>NEW.facility_id
    OR run_row.inventory_owner_id<>NEW.inventory_owner_id
    OR run_row.pick_wave_id<>NEW.pick_wave_id
    OR order_row.id IS NULL OR order_row.status<>'open'
    OR order_row.order_key<>NEW.order_key OR order_row.revision<>NEW.order_revision
    OR order_row.rush<>NEW.rush OR order_row.ship_by IS DISTINCT FROM NEW.ship_by
    OR order_row.created<>NEW.order_created_at
    OR order_row.created>run_row.input_snapshot_at
    OR actual_demand<>NEW.demand_qty OR actual_allocated<>NEW.allocated_qty
    OR actual_demand<=0 OR actual_demand<>actual_allocated
    OR NOT EXISTS(SELECT 1 FROM public.pick_wave_orders member
      WHERE member.tenant_id=NEW.tenant_id AND member.pick_wave_id=NEW.pick_wave_id
        AND member.inventory_owner_id=NEW.inventory_owner_id
        AND member.order_id=NEW.order_id AND member.wave_sequence=NEW.selection_rank
        AND member.expected_order_revision=NEW.order_revision AND member.active)
  THEN
    RAISE EXCEPTION 'dynamic release candidate is stale, unallocated, or outside its wave'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.guard_dynamic_release_run() RETURNS trigger
LANGUAGE plpgsql SET search_path TO 'pg_catalog','public' AS $$
BEGIN
  IF TG_OP='DELETE' OR OLD.status<>'building' OR NEW.status<>'sealed'
    OR NEW.id<>OLD.id OR NEW.tenant_id<>OLD.tenant_id
    OR NEW.facility_id<>OLD.facility_id
    OR NEW.inventory_owner_id<>OLD.inventory_owner_id
    OR NEW.destination_location_id<>OLD.destination_location_id
    OR NEW.pick_wave_id IS DISTINCT FROM OLD.pick_wave_id
    OR NEW.input_snapshot_at<>OLD.input_snapshot_at
    OR NEW.policy_source<>OLD.policy_source
    OR NEW.policy_configuration_id IS DISTINCT FROM OLD.policy_configuration_id
    OR NEW.policy_configuration_revision IS DISTINCT FROM OLD.policy_configuration_revision
    OR NEW.policy_scope_level IS DISTINCT FROM OLD.policy_scope_level
    OR NEW.policy_scope_owner_id IS DISTINCT FROM OLD.policy_scope_owner_id
    OR NEW.policy_scope_facility_id IS DISTINCT FROM OLD.policy_scope_facility_id
    OR NEW.policy_definition<>OLD.policy_definition OR NEW.policy_hash<>OLD.policy_hash
    OR NEW.eligible_order_count<>OLD.eligible_order_count
    OR NEW.selected_order_count<>OLD.selected_order_count
    OR NEW.deferred_order_count<>OLD.deferred_order_count
    OR NEW.released_by_user_id<>OLD.released_by_user_id
    OR NEW.released_at<>OLD.released_at THEN
    RAISE EXCEPTION 'dynamic release evidence is immutable after its one-way seal'
      USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.reject_dynamic_release_candidate_mutation() RETURNS trigger
LANGUAGE plpgsql SET search_path TO 'pg_catalog','public' AS $$
BEGIN
  RAISE EXCEPTION 'dynamic release candidate evidence is immutable' USING ERRCODE='55000';
END $$;


CREATE FUNCTION public.dynamic_release_eligible_orders(
  p_tenant_id bigint,p_inventory_owner_id bigint,p_facility_id bigint,
  p_input_snapshot_at timestamptz,p_pick_wave_id bigint
) RETURNS TABLE(order_id bigint,selection_rank bigint)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
  SELECT order_header.id,
    row_number() OVER(ORDER BY order_header.rush DESC,
      order_header.ship_by ASC NULLS LAST,order_header.created,order_header.id)::bigint
  FROM public.orders order_header
  JOIN public.inventory_owner_facilities assignment
    ON assignment.tenant_id=order_header.tenant_id
   AND assignment.inventory_owner_id=order_header.inventory_owner_id
   AND assignment.facility_id=p_facility_id AND assignment.deleted IS NULL
  JOIN LATERAL (
    SELECT SUM(demand.effective_qty)::bigint AS demand_qty,
      SUM(COALESCE(allocated.qty,0))::bigint AS allocated_qty
    FROM public.outbound_effective_demand demand
    LEFT JOIN LATERAL (
      SELECT SUM(allocation.qty)::bigint AS qty
      FROM public.inventory_reservations reservation
      JOIN public.inventory_allocations allocation
        ON allocation.tenant_id=reservation.tenant_id
       AND allocation.inventory_owner_id=reservation.inventory_owner_id
       AND allocation.reservation_id=reservation.id
      WHERE reservation.tenant_id=demand.tenant_id
        AND reservation.inventory_owner_id=demand.inventory_owner_id
        AND reservation.order_id=demand.order_id
        AND reservation.order_item_id=demand.order_item_id
        AND reservation.facility_id=p_facility_id
        AND reservation.status='active' AND reservation.deleted IS NULL
        AND allocation.facility_id=p_facility_id
        AND allocation.status='allocated' AND allocation.deleted IS NULL
        AND allocation.execution_stage='pick_source'
    ) allocated ON true
    WHERE demand.tenant_id=order_header.tenant_id
      AND demand.inventory_owner_id=order_header.inventory_owner_id
      AND demand.order_id=order_header.id
  ) totals ON totals.demand_qty>0 AND totals.demand_qty=totals.allocated_qty
  WHERE order_header.tenant_id=p_tenant_id
    AND order_header.inventory_owner_id=p_inventory_owner_id
    AND order_header.status='open' AND order_header.deleted IS NULL
    AND order_header.created<=p_input_snapshot_at
    AND NOT EXISTS(SELECT 1 FROM public.order_holds hold
      WHERE hold.tenant_id=order_header.tenant_id
        AND hold.inventory_owner_id=order_header.inventory_owner_id
        AND hold.order_id=order_header.id AND hold.released_at IS NULL)
    AND NOT EXISTS(SELECT 1 FROM public.cross_dock_tasks detail
      JOIN public.work_tasks work
        ON work.tenant_id=detail.tenant_id AND work.id=detail.task_id
      WHERE detail.tenant_id=order_header.tenant_id
        AND detail.inventory_owner_id=order_header.inventory_owner_id
        AND detail.order_id=order_header.id AND detail.closed_at IS NULL
        AND work.status IN ('open','assigned','in_progress'))
    AND NOT EXISTS(SELECT 1 FROM public.pick_wave_orders member
      WHERE member.tenant_id=order_header.tenant_id
        AND member.order_id=order_header.id AND member.active
        AND member.pick_wave_id IS DISTINCT FROM p_pick_wave_id)
$$;

CREATE FUNCTION public.seal_dynamic_release_selection() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE actual_eligible bigint;
DECLARE actual_selected bigint;
BEGIN
  IF NEW.status<>'sealed' THEN RETURN NEW; END IF;
  SELECT count(*)::bigint,
    count(*) FILTER(WHERE selection_rank<=(NEW.policy_definition->>'max_orders')::bigint)::bigint
  INTO actual_eligible,actual_selected
  FROM public.dynamic_release_eligible_orders(
    NEW.tenant_id,NEW.inventory_owner_id,NEW.facility_id,
    NEW.input_snapshot_at,NEW.pick_wave_id);
  IF actual_eligible<>NEW.eligible_order_count
    OR actual_selected<>NEW.selected_order_count
    OR (SELECT count(*) FROM public.dynamic_release_candidates candidate
      WHERE candidate.tenant_id=NEW.tenant_id
        AND candidate.dynamic_release_run_id=NEW.id)<>NEW.selected_order_count
    OR EXISTS(SELECT 1
      FROM public.dynamic_release_eligible_orders(
        NEW.tenant_id,NEW.inventory_owner_id,NEW.facility_id,
        NEW.input_snapshot_at,NEW.pick_wave_id) eligible
      LEFT JOIN public.dynamic_release_candidates candidate
        ON candidate.tenant_id=NEW.tenant_id
       AND candidate.dynamic_release_run_id=NEW.id
       AND candidate.order_id=eligible.order_id
       AND candidate.selection_rank=eligible.selection_rank
      WHERE eligible.selection_rank<=(NEW.policy_definition->>'max_orders')::bigint
        AND candidate.order_id IS NULL)
  THEN
    RAISE EXCEPTION 'dynamic release selection is incomplete or not the canonical priority prefix'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.require_dynamic_release_integrity() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE run_row public.dynamic_release_runs%ROWTYPE;
BEGIN
  IF TG_TABLE_NAME='dynamic_release_runs' THEN
    SELECT * INTO run_row FROM public.dynamic_release_runs run
    WHERE run.tenant_id=NEW.tenant_id AND run.id=NEW.id;
  ELSE
    SELECT * INTO run_row FROM public.dynamic_release_runs run
    WHERE run.tenant_id=NEW.tenant_id AND run.id=NEW.dynamic_release_run_id;
  END IF;
  IF run_row.id IS NULL OR run_row.status<>'sealed'
    OR (run_row.selected_order_count=0 AND run_row.pick_wave_id IS NOT NULL)
    OR (run_row.selected_order_count>0 AND NOT EXISTS(
      SELECT 1 FROM public.pick_waves wave
      WHERE wave.tenant_id=run_row.tenant_id AND wave.id=run_row.pick_wave_id
        AND wave.status='released' AND wave.order_count=run_row.selected_order_count
        AND wave.released_by_user_id=run_row.released_by_user_id
        AND wave.released_at=run_row.released_at))
    OR EXISTS(SELECT 1 FROM public.dynamic_release_candidates candidate
      LEFT JOIN public.pick_wave_orders member
        ON member.tenant_id=candidate.tenant_id
       AND member.pick_wave_id=candidate.pick_wave_id
       AND member.order_id=candidate.order_id
      WHERE candidate.tenant_id=run_row.tenant_id
        AND candidate.dynamic_release_run_id=run_row.id
        AND (member.order_id IS NULL OR member.active OR member.order_release_id IS NULL
          OR member.wave_sequence<>candidate.selection_rank)) THEN
    RAISE EXCEPTION 'dynamic release run, selection, wave, and releases do not reconcile'
      USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;

CREATE TRIGGER dynamic_release_runs_validate BEFORE INSERT
ON public.dynamic_release_runs FOR EACH ROW
EXECUTE FUNCTION public.validate_dynamic_release_run();
CREATE TRIGGER dynamic_release_runs_guard BEFORE UPDATE OR DELETE
ON public.dynamic_release_runs FOR EACH ROW
EXECUTE FUNCTION public.guard_dynamic_release_run();
CREATE TRIGGER dynamic_release_runs_seal BEFORE UPDATE OF status
ON public.dynamic_release_runs FOR EACH ROW
EXECUTE FUNCTION public.seal_dynamic_release_selection();
CREATE CONSTRAINT TRIGGER dynamic_release_runs_reconcile
AFTER INSERT OR UPDATE ON public.dynamic_release_runs DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_dynamic_release_integrity();
CREATE TRIGGER dynamic_release_candidates_validate BEFORE INSERT
ON public.dynamic_release_candidates FOR EACH ROW
EXECUTE FUNCTION public.validate_dynamic_release_candidate();
CREATE TRIGGER dynamic_release_candidates_immutable BEFORE UPDATE OR DELETE
ON public.dynamic_release_candidates FOR EACH ROW
EXECUTE FUNCTION public.reject_dynamic_release_candidate_mutation();
CREATE CONSTRAINT TRIGGER dynamic_release_candidates_reconcile
AFTER INSERT ON public.dynamic_release_candidates DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_dynamic_release_integrity();

ALTER TABLE public.dynamic_release_runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.dynamic_release_runs FORCE ROW LEVEL SECURITY;
CREATE POLICY dynamic_release_runs_tenant_isolation ON public.dynamic_release_runs
USING(tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint)
WITH CHECK(tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint);
ALTER TABLE public.dynamic_release_candidates ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.dynamic_release_candidates FORCE ROW LEVEL SECURITY;
CREATE POLICY dynamic_release_candidates_tenant_isolation ON public.dynamic_release_candidates
USING(tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint)
WITH CHECK(tenant_id=NULLIF(current_setting('wareboxes.tenant_id',true),'')::bigint);

GRANT SELECT,INSERT ON public.dynamic_release_runs TO wareboxes_app;
GRANT UPDATE(status) ON public.dynamic_release_runs TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.dynamic_release_runs_id_seq TO wareboxes_app;
GRANT SELECT,INSERT ON public.dynamic_release_candidates TO wareboxes_app;
REVOKE ALL ON FUNCTION public.validate_dynamic_release_run() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.validate_dynamic_release_candidate() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_dynamic_release_run() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.reject_dynamic_release_candidate_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.seal_dynamic_release_selection() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.dynamic_release_eligible_orders(
  bigint,bigint,bigint,timestamptz,bigint) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_dynamic_release_integrity() FROM PUBLIC;

-- Cloud automation registry, replay-safe edge delivery, and immutable evidence.
CREATE TABLE public.automation_devices (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  device_key text NOT NULL,
  device_class text NOT NULL,
  display_name text NOT NULL,
  control_mode text NOT NULL,
  control_reason text NOT NULL,
  control_changed_by_user_id bigint NOT NULL,
  control_changed_at timestamptz NOT NULL,
  revision integer NOT NULL,
  health text NOT NULL,
  health_message text,
  last_heartbeat_at timestamptz,
  registered_by_user_id bigint NOT NULL,
  registered_at timestamptz NOT NULL,
  UNIQUE(tenant_id,id),
  UNIQUE(tenant_id,facility_id,id),
  CHECK(device_key=btrim(device_key) AND device_key<>''
    AND char_length(device_key)<=128 AND device_key~'^[A-Za-z0-9_.:/@-]+$'),
  CHECK(display_name=btrim(display_name) AND display_name<>''
    AND char_length(display_name)<=200 AND display_name!~'[[:cntrl:]]'),
  CHECK(device_class IN ('plc','conveyor','robotics','sortation','printer','scale')),
  CHECK(control_mode IN ('disabled','automatic','manual_fallback')),
  CHECK(control_reason=btrim(control_reason) AND control_reason<>''
    AND char_length(control_reason)<=1000 AND control_reason!~'[[:cntrl:]]'),
  CHECK(revision>0),
  CHECK(health IN ('unknown','healthy','degraded','offline','faulted')),
  CHECK(health_message IS NULL OR (health_message=btrim(health_message)
    AND health_message<>'' AND char_length(health_message)<=1000
    AND health_message!~'[[:cntrl:]]')),
  CHECK((health='unknown' AND last_heartbeat_at IS NULL)
    OR (health<>'unknown' AND last_heartbeat_at IS NOT NULL)),
  CHECK(control_changed_at>=registered_at),
  FOREIGN KEY(tenant_id) REFERENCES public.tenants(id),
  FOREIGN KEY(tenant_id,facility_id) REFERENCES public.facilities(tenant_id,id),
  FOREIGN KEY(tenant_id,control_changed_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  FOREIGN KEY(tenant_id,registered_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id)
);
CREATE UNIQUE INDEX automation_devices_key_unique
ON public.automation_devices(tenant_id,lower(device_key));
CREATE INDEX automation_devices_facility_idx
ON public.automation_devices(tenant_id,facility_id,lower(display_name),id);

CREATE FUNCTION public.automation_json_text_valid(
  document jsonb,field_name text,maximum integer) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT COALESCE(jsonb_typeof(document->field_name)='string'
    AND document->>field_name=btrim(document->>field_name)
    AND document->>field_name<>''
    AND char_length(document->>field_name)<=maximum
    AND document->>field_name!~'[[:cntrl:]]',false)
$$;

CREATE FUNCTION public.automation_json_object_size(document jsonb) RETURNS integer
LANGUAGE sql IMMUTABLE AS $$
  SELECT count(*)::integer FROM jsonb_object_keys(document)
$$;

CREATE FUNCTION public.automation_command_payload_is_valid(
  expected_class text,payload jsonb) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE command jsonb;
DECLARE operation text;
BEGIN
  IF jsonb_typeof(payload)<>'object' OR public.automation_json_object_size(payload)<>2
    OR payload->>'device_class'<>expected_class
    OR jsonb_typeof(payload->'command')<>'object' THEN
    RETURN false;
  END IF;
  command:=payload->'command';
  operation:=command->>'operation';
  RETURN CASE expected_class
    WHEN 'plc' THEN CASE operation
      WHEN 'set_discrete_output' THEN public.automation_json_object_size(command)=3
        AND public.automation_json_text_valid(command,'point',128)
        AND jsonb_typeof(command->'value')='boolean'
      WHEN 'pulse_discrete_output' THEN public.automation_json_object_size(command)=3
        AND public.automation_json_text_valid(command,'point',128)
        AND jsonb_typeof(command->'duration_ms')='number'
        AND (command->>'duration_ms')::numeric BETWEEN 1 AND 60000
        AND (command->>'duration_ms')::numeric=trunc((command->>'duration_ms')::numeric)
      WHEN 'reset_fault' THEN public.automation_json_object_size(command)=2
        AND public.automation_json_text_valid(command,'fault_code',128)
      ELSE false END
    WHEN 'conveyor' THEN CASE operation
      WHEN 'route_carrier' THEN public.automation_json_object_size(command)=3
        AND public.automation_json_text_valid(command,'carrier_id',128)
        AND public.automation_json_text_valid(command,'destination',128)
      WHEN 'start_zone' THEN public.automation_json_object_size(command)=2
        AND public.automation_json_text_valid(command,'zone',128)
      WHEN 'stop_zone' THEN public.automation_json_object_size(command)=2
        AND public.automation_json_text_valid(command,'zone',128)
      ELSE false END
    WHEN 'robotics' THEN CASE operation
      WHEN 'dispatch_mission' THEN public.automation_json_object_size(command)=6
        AND public.automation_json_text_valid(command,'mission_id',128)
        AND command->>'mission_kind' IN ('pick','place','transport','charge')
        AND public.automation_json_text_valid(command,'source',128)
        AND public.automation_json_text_valid(command,'destination',128)
        AND (command->'payload_id'='null'::jsonb
          OR public.automation_json_text_valid(command,'payload_id',128))
      WHEN 'cancel_mission' THEN public.automation_json_object_size(command)=2
        AND public.automation_json_text_valid(command,'mission_id',128)
      ELSE false END
    WHEN 'sortation' THEN CASE operation
      WHEN 'divert' THEN public.automation_json_object_size(command)=3
        AND public.automation_json_text_valid(command,'tracking_id',128)
        AND public.automation_json_text_valid(command,'chute',128)
      WHEN 'reject' THEN public.automation_json_object_size(command)=4
        AND public.automation_json_text_valid(command,'tracking_id',128)
        AND public.automation_json_text_valid(command,'lane',128)
        AND public.automation_json_text_valid(command,'reason_code',128)
      ELSE false END
    WHEN 'printer' THEN CASE operation
      WHEN 'print_document' THEN public.automation_json_object_size(command)=5
        AND public.automation_json_text_valid(command,'document_id',128)
        AND command->>'format' IN ('zpl','pdf','png')
        AND jsonb_typeof(command->'content')='string'
        AND octet_length(command->>'content') BETWEEN 1 AND 10485760
        AND jsonb_typeof(command->'copies')='number'
        AND (command->>'copies')::numeric BETWEEN 1 AND 65535
        AND (command->>'copies')::numeric=trunc((command->>'copies')::numeric)
      WHEN 'cancel_print_job' THEN public.automation_json_object_size(command)=2
        AND public.automation_json_text_valid(command,'spool_job_id',128)
      ELSE false END
    WHEN 'scale' THEN CASE operation
      WHEN 'read_stable_weight' THEN public.automation_json_object_size(command)=3
        AND command->>'requested_unit' IN ('gram','kilogram','pound')
        AND jsonb_typeof(command->'timeout_ms')='number'
        AND (command->>'timeout_ms')::numeric BETWEEN 1 AND 120000
        AND (command->>'timeout_ms')::numeric=trunc((command->>'timeout_ms')::numeric)
      WHEN 'tare' THEN public.automation_json_object_size(command)=1
      ELSE false END
    ELSE false END;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
  RETURN false;
END $$;

CREATE FUNCTION public.automation_result_payload_is_valid(
  expected_class text,payload jsonb) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE result jsonb;
BEGIN
  IF jsonb_typeof(payload)<>'object' OR public.automation_json_object_size(payload)<>2
    OR payload->>'device_class'<>expected_class
    OR jsonb_typeof(payload->'result')<>'object' THEN
    RETURN false;
  END IF;
  result:=payload->'result';
  RETURN CASE expected_class
    WHEN 'plc' THEN public.automation_json_object_size(result)=2
      AND (result->'controller_reference'='null'::jsonb
        OR public.automation_json_text_valid(result,'controller_reference',128))
      AND (result->'output_state'='null'::jsonb
        OR jsonb_typeof(result->'output_state')='boolean')
    WHEN 'conveyor' THEN public.automation_json_object_size(result)=2
      AND (result->'controller_reference'='null'::jsonb
        OR public.automation_json_text_valid(result,'controller_reference',128))
      AND (result->'observed_zone'='null'::jsonb
        OR public.automation_json_text_valid(result,'observed_zone',128))
    WHEN 'robotics' THEN public.automation_json_object_size(result)=2
      AND public.automation_json_text_valid(result,'controller_reference',128)
      AND public.automation_json_text_valid(result,'mission_state',128)
    WHEN 'sortation' THEN public.automation_json_object_size(result)=2
      AND (result->'controller_reference'='null'::jsonb
        OR public.automation_json_text_valid(result,'controller_reference',128))
      AND public.automation_json_text_valid(result,'observed_lane',128)
    WHEN 'printer' THEN public.automation_json_object_size(result)=1
      AND public.automation_json_text_valid(result,'spool_job_id',128)
    WHEN 'scale' THEN public.automation_json_object_size(result)=2
      AND jsonb_typeof(result->'mass_milligrams')='number'
      AND (result->>'mass_milligrams')::numeric BETWEEN -9223372036854775808
        AND 9223372036854775807
      AND (result->>'mass_milligrams')::numeric=
        trunc((result->>'mass_milligrams')::numeric)
      AND jsonb_typeof(result->'stable')='boolean'
    ELSE false END;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
  RETURN false;
END $$;

CREATE TABLE public.automation_commands (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  device_id bigint NOT NULL,
  device_class text NOT NULL,
  correlation_id text NOT NULL,
  recovery_policy text NOT NULL,
  command_payload jsonb NOT NULL,
  packing_inventory_owner_id bigint,
  packing_session_id bigint,
  packing_carton_id bigint,
  packing_carton_reopen_count bigint,
  status text NOT NULL,
  revision integer NOT NULL,
  delivery_attempts integer NOT NULL,
  assigned_service_account_id bigint,
  agent_instance text,
  delivery_token text,
  delivered_at timestamptz,
  delivery_expires_at timestamptz,
  accepted_at timestamptz,
  completed_at timestamptz,
  result_payload jsonb,
  error_code text,
  error_message text,
  resolved_by_user_id bigint,
  resolution_outcome text,
  resolution_reason text,
  resolved_at timestamptz,
  requested_by_user_id bigint NOT NULL,
  requested_at timestamptz NOT NULL,
  UNIQUE(tenant_id,id),
  UNIQUE(tenant_id,facility_id,id),
  UNIQUE(tenant_id,correlation_id),
  CHECK(device_class IN ('plc','conveyor','robotics','sortation','printer','scale')),
  CHECK(correlation_id=btrim(correlation_id) AND correlation_id<>''
    AND char_length(correlation_id)<=1000 AND correlation_id!~'[[:cntrl:]]'),
  CHECK(recovery_policy IN
    ('device_deduplicated_replay','probe_then_retry','manual_review')),
  CHECK(public.automation_command_payload_is_valid(device_class,command_payload)),
  CHECK((packing_inventory_owner_id IS NULL AND packing_session_id IS NULL
      AND packing_carton_id IS NULL AND packing_carton_reopen_count IS NULL)
    OR (packing_inventory_owner_id IS NOT NULL AND packing_session_id IS NOT NULL
      AND packing_carton_id IS NOT NULL AND packing_carton_reopen_count>=0
      AND device_class='scale'
      AND command_payload->'command'->>'operation'='read_stable_weight')),
  CHECK(status IN
    ('queued','delivered','accepted','succeeded','failed','manual_review',
      'resolved_manually','cancelled')),
  CHECK(revision>0 AND delivery_attempts>=0),
  CHECK(agent_instance IS NULL OR (agent_instance=btrim(agent_instance)
    AND agent_instance<>'' AND char_length(agent_instance)<=1000
    AND agent_instance!~'[[:cntrl:]]')),
  CHECK(delivery_token IS NULL OR (delivery_token=btrim(delivery_token)
    AND char_length(delivery_token) BETWEEN 32 AND 200)),
  CHECK(error_code IS NULL OR (error_code=btrim(error_code) AND error_code<>''
    AND char_length(error_code)<=1000 AND error_code!~'[[:cntrl:]]')),
  CHECK(error_message IS NULL OR (error_message=btrim(error_message) AND error_message<>''
    AND char_length(error_message)<=1000 AND error_message!~'[[:cntrl:]]')),
  CHECK(resolution_reason IS NULL OR (resolution_reason=btrim(resolution_reason)
    AND resolution_reason<>'' AND char_length(resolution_reason)<=1000
    AND resolution_reason!~'[[:cntrl:]]')),
  CHECK((status='resolved_manually' AND resolved_by_user_id IS NOT NULL
      AND resolution_outcome IN ('confirmed_executed','confirmed_not_executed')
      AND resolution_reason IS NOT NULL AND resolved_at IS NOT NULL)
    OR (status<>'resolved_manually' AND resolved_by_user_id IS NULL
      AND resolution_outcome IS NULL AND resolution_reason IS NULL
      AND resolved_at IS NULL)),
  CHECK(result_payload IS NULL
    OR public.automation_result_payload_is_valid(device_class,result_payload)),
  CHECK(
    (status='queued' AND revision=1 AND delivery_attempts=0
      AND assigned_service_account_id IS NULL AND agent_instance IS NULL
      AND delivery_token IS NULL AND delivered_at IS NULL
      AND delivery_expires_at IS NULL AND accepted_at IS NULL
      AND completed_at IS NULL AND result_payload IS NULL
      AND error_code IS NULL AND error_message IS NULL)
    OR (status='delivered' AND delivery_attempts>0
      AND assigned_service_account_id IS NOT NULL AND agent_instance IS NOT NULL
      AND delivery_token IS NOT NULL AND delivered_at IS NOT NULL
      AND delivery_expires_at>delivered_at AND accepted_at IS NULL
      AND completed_at IS NULL AND result_payload IS NULL
      AND error_code IS NULL AND error_message IS NULL)
    OR (status='accepted' AND delivery_attempts>0
      AND assigned_service_account_id IS NOT NULL AND agent_instance IS NOT NULL
      AND delivery_token IS NOT NULL AND delivered_at IS NOT NULL
      AND delivery_expires_at IS NULL AND accepted_at>=delivered_at
      AND completed_at IS NULL AND result_payload IS NULL
      AND error_code IS NULL AND error_message IS NULL)
    OR (status='succeeded' AND assigned_service_account_id IS NOT NULL
      AND accepted_at IS NOT NULL AND completed_at>=accepted_at
      AND result_payload IS NOT NULL AND error_code IS NULL AND error_message IS NULL)
    OR (status IN ('failed','manual_review')
      AND assigned_service_account_id IS NOT NULL AND accepted_at IS NOT NULL
      AND completed_at>=accepted_at AND result_payload IS NULL
      AND error_message IS NOT NULL)
    OR (status='resolved_manually'
      AND assigned_service_account_id IS NOT NULL AND accepted_at IS NOT NULL
      AND completed_at>=accepted_at AND result_payload IS NULL
      AND error_message IS NOT NULL AND resolved_at>=completed_at)
    OR (status='cancelled' AND completed_at IS NOT NULL
      AND result_payload IS NULL)),
  FOREIGN KEY(tenant_id,facility_id,device_id)
    REFERENCES public.automation_devices(tenant_id,facility_id,id),
  FOREIGN KEY(tenant_id,packing_inventory_owner_id,facility_id,
      packing_session_id,packing_carton_id)
    REFERENCES public.cartons(
      tenant_id,inventory_owner_id,facility_id,packing_session_id,id),
  FOREIGN KEY(tenant_id,assigned_service_account_id)
    REFERENCES public.service_accounts(tenant_id,id),
  FOREIGN KEY(tenant_id,requested_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  FOREIGN KEY(tenant_id,resolved_by_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id)
);
CREATE INDEX automation_commands_delivery_idx
ON public.automation_commands(tenant_id,facility_id,status,requested_at,id);
CREATE INDEX automation_commands_device_history_idx
ON public.automation_commands(tenant_id,device_id,requested_at DESC,id DESC);

CREATE TABLE public.automation_command_events (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  command_id bigint NOT NULL,
  transition text NOT NULL,
  actor_user_id bigint NOT NULL,
  service_account_id bigint,
  occurred_at timestamptz NOT NULL,
  evidence jsonb NOT NULL,
  UNIQUE(tenant_id,id),
  CHECK(transition IN
    ('delivered','accepted','succeeded','failed','manual_review',
      'resolved_manually','cancelled')),
  CHECK(jsonb_typeof(evidence)='object'),
  FOREIGN KEY(tenant_id,command_id)
    REFERENCES public.automation_commands(tenant_id,id),
  FOREIGN KEY(tenant_id,actor_user_id)
    REFERENCES public.tenant_memberships(tenant_id,user_id),
  FOREIGN KEY(tenant_id,service_account_id)
    REFERENCES public.service_accounts(tenant_id,id)
);
CREATE INDEX automation_command_events_history_idx
ON public.automation_command_events(tenant_id,command_id,occurred_at,id);

CREATE TABLE public.automation_heartbeats (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  device_id bigint NOT NULL,
  service_account_id bigint NOT NULL,
  agent_instance text NOT NULL,
  health text NOT NULL,
  control_mode text NOT NULL,
  message text,
  queued_commands integer NOT NULL,
  manual_review_commands integer NOT NULL,
  observed_at timestamptz NOT NULL,
  received_at timestamptz NOT NULL,
  UNIQUE(tenant_id,id),
  CHECK(agent_instance=btrim(agent_instance) AND agent_instance<>''
    AND char_length(agent_instance)<=1000 AND agent_instance!~'[[:cntrl:]]'),
  CHECK(health IN ('unknown','healthy','degraded','offline','faulted')),
  CHECK(control_mode IN ('disabled','automatic','manual_fallback')),
  CHECK(message IS NULL OR (message=btrim(message) AND message<>''
    AND char_length(message)<=1000 AND message!~'[[:cntrl:]]')),
  CHECK(queued_commands>=0 AND manual_review_commands>=0),
  CHECK(observed_at BETWEEN received_at-INTERVAL '5 minutes'
    AND received_at+INTERVAL '1 minute'),
  FOREIGN KEY(tenant_id,facility_id,device_id)
    REFERENCES public.automation_devices(tenant_id,facility_id,id),
  FOREIGN KEY(tenant_id,service_account_id)
    REFERENCES public.service_accounts(tenant_id,id)
);
CREATE INDEX automation_heartbeats_device_history_idx
ON public.automation_heartbeats(tenant_id,device_id,observed_at DESC,id DESC);

CREATE FUNCTION public.automation_user_has_permission(
  checked_tenant_id bigint,checked_user_id bigint,checked_permission text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
  WITH RECURSIVE granted_roles AS (
    SELECT role.id,role.parent_id
    FROM public.tenant_memberships membership
    JOIN public.user_roles user_role ON user_role.tenant_id=membership.tenant_id
      AND user_role.user_id=membership.user_id AND user_role.deleted IS NULL
    JOIN public.roles role ON role.tenant_id=user_role.tenant_id
      AND role.id=user_role.role_id AND role.deleted IS NULL
    WHERE membership.tenant_id=checked_tenant_id
      AND membership.user_id=checked_user_id AND membership.deleted IS NULL
    UNION
    SELECT parent.id,parent.parent_id FROM granted_roles child
    JOIN public.roles parent ON parent.tenant_id=checked_tenant_id
      AND parent.id=child.parent_id AND parent.deleted IS NULL
  ), role_grant AS (
    SELECT 1 FROM granted_roles role
    JOIN public.role_permissions role_permission
      ON role_permission.tenant_id=checked_tenant_id
      AND role_permission.role_id=role.id AND role_permission.deleted IS NULL
    JOIN public.permissions permission ON permission.tenant_id=role_permission.tenant_id
      AND permission.id=role_permission.permission_id AND permission.deleted IS NULL
    WHERE upper(permission.name) IN ('ADMIN',upper(checked_permission)) LIMIT 1
  ), service_grant AS (
    SELECT 1 FROM public.service_accounts account
    JOIN public.service_account_permissions grant_record
      ON grant_record.tenant_id=account.tenant_id
      AND grant_record.service_account_id=account.id AND grant_record.revoked_at IS NULL
    JOIN public.permissions permission ON permission.tenant_id=grant_record.tenant_id
      AND permission.id=grant_record.permission_id AND permission.deleted IS NULL
    WHERE account.tenant_id=checked_tenant_id
      AND account.principal_user_id=checked_user_id AND account.status='active'
      AND upper(permission.name) IN ('ADMIN',upper(checked_permission)) LIMIT 1
  )
  SELECT EXISTS(SELECT 1 FROM role_grant) OR EXISTS(SELECT 1 FROM service_grant)
$$;

CREATE FUNCTION public.automation_interactive_user_scoped(
  checked_tenant_id bigint,checked_user_id bigint,checked_facility_id bigint) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
  SELECT EXISTS(SELECT 1 FROM public.tenant_memberships membership
    WHERE membership.tenant_id=checked_tenant_id AND membership.user_id=checked_user_id
      AND membership.deleted IS NULL
      AND NOT EXISTS(SELECT 1 FROM public.service_accounts account
        WHERE account.tenant_id=membership.tenant_id
          AND account.principal_user_id=membership.user_id)
      AND (membership.all_facilities OR EXISTS(
        SELECT 1 FROM public.user_facilities assignment
        WHERE assignment.tenant_id=membership.tenant_id
          AND assignment.user_id=membership.user_id
          AND assignment.facility_id=checked_facility_id
          AND assignment.deleted IS NULL)))
$$;

CREATE FUNCTION public.automation_edge_service_account(
  checked_tenant_id bigint,checked_user_id bigint,checked_facility_id bigint) RETURNS bigint
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
  SELECT account.id FROM public.service_accounts account
  JOIN public.tenant_memberships membership ON membership.tenant_id=account.tenant_id
    AND membership.user_id=account.principal_user_id AND membership.deleted IS NULL
  WHERE account.tenant_id=checked_tenant_id
    AND account.principal_user_id=checked_user_id AND account.status='active'
    AND public.automation_user_has_permission(
      checked_tenant_id,checked_user_id,'automation_edge')
    AND (account.all_facilities OR EXISTS(
      SELECT 1 FROM public.service_account_facilities assignment
      WHERE assignment.tenant_id=account.tenant_id
        AND assignment.service_account_id=account.id
        AND assignment.facility_id=checked_facility_id
        AND assignment.revoked_at IS NULL))
  LIMIT 1
$$;

CREATE FUNCTION public.validate_automation_device() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE actor_id bigint:=NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint;
DECLARE latest_heartbeat public.automation_heartbeats%ROWTYPE;
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'automation devices cannot be deleted' USING ERRCODE='55000';
  END IF;
  IF TG_OP='INSERT' THEN
    IF actor_id IS DISTINCT FROM NEW.registered_by_user_id
      OR NEW.control_changed_by_user_id<>NEW.registered_by_user_id
      OR NEW.registered_at<>NEW.control_changed_at
      OR NEW.control_mode<>'disabled' OR NEW.revision<>1 OR NEW.health<>'unknown'
      OR NOT public.automation_user_has_permission(
        NEW.tenant_id,actor_id,'wms_supervisor')
      OR NOT public.automation_interactive_user_scoped(
        NEW.tenant_id,actor_id,NEW.facility_id) THEN
      RAISE EXCEPTION 'invalid automation device registration' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(NEW.id,NEW.tenant_id,NEW.facility_id,NEW.device_key,NEW.device_class,
      NEW.display_name,NEW.registered_by_user_id,NEW.registered_at) IS DISTINCT FROM
    ROW(OLD.id,OLD.tenant_id,OLD.facility_id,OLD.device_key,OLD.device_class,
      OLD.display_name,OLD.registered_by_user_id,OLD.registered_at) THEN
    RAISE EXCEPTION 'automation device identity is immutable' USING ERRCODE='55000';
  END IF;
  IF ROW(NEW.control_mode,NEW.control_reason,NEW.control_changed_by_user_id,
      NEW.control_changed_at,NEW.revision) IS DISTINCT FROM
    ROW(OLD.control_mode,OLD.control_reason,OLD.control_changed_by_user_id,
      OLD.control_changed_at,OLD.revision) THEN
    IF (NEW.control_mode='automatic' AND (
        NEW.health NOT IN ('healthy','degraded')
        OR NEW.last_heartbeat_at<CURRENT_TIMESTAMP-INTERVAL '2 minutes'
        OR EXISTS(SELECT 1 FROM public.automation_commands command
          WHERE command.tenant_id=NEW.tenant_id AND command.device_id=NEW.id
            AND command.status='manual_review')))
      OR ROW(NEW.health,NEW.health_message,NEW.last_heartbeat_at) IS DISTINCT FROM
      ROW(OLD.health,OLD.health_message,OLD.last_heartbeat_at)
      OR actor_id IS DISTINCT FROM NEW.control_changed_by_user_id
      OR NEW.revision<>OLD.revision+1 OR NEW.control_changed_at<OLD.control_changed_at
      OR NOT public.automation_user_has_permission(
        NEW.tenant_id,actor_id,'wms_supervisor')
      OR NOT public.automation_interactive_user_scoped(
        NEW.tenant_id,actor_id,NEW.facility_id) THEN
      RAISE EXCEPTION 'invalid automation control transition' USING ERRCODE='23514';
    END IF;
  ELSE
    SELECT * INTO latest_heartbeat FROM public.automation_heartbeats heartbeat
    WHERE heartbeat.tenant_id=NEW.tenant_id AND heartbeat.device_id=NEW.id
    ORDER BY heartbeat.id DESC LIMIT 1;
    IF ROW(NEW.health,NEW.health_message,NEW.last_heartbeat_at) IS NOT DISTINCT FROM
      ROW(OLD.health,OLD.health_message,OLD.last_heartbeat_at)
      OR latest_heartbeat.id IS NULL
      OR latest_heartbeat.health<>NEW.health
      OR latest_heartbeat.message IS DISTINCT FROM NEW.health_message
      OR latest_heartbeat.observed_at<>NEW.last_heartbeat_at
      OR public.automation_edge_service_account(
        NEW.tenant_id,actor_id,NEW.facility_id) IS DISTINCT FROM
        latest_heartbeat.service_account_id THEN
      RAISE EXCEPTION 'invalid automation health projection update' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.validate_automation_command() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE actor_id bigint:=NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint;
DECLARE device public.automation_devices%ROWTYPE;
DECLARE edge_account_id bigint;
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'automation commands cannot be deleted' USING ERRCODE='55000';
  END IF;
  SELECT * INTO device FROM public.automation_devices candidate
  WHERE candidate.tenant_id=NEW.tenant_id AND candidate.id=NEW.device_id FOR SHARE;
  IF device.id IS NULL OR device.facility_id<>NEW.facility_id
    OR device.device_class<>NEW.device_class THEN
    RAISE EXCEPTION 'automation command device snapshot is invalid' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' THEN
    IF actor_id IS DISTINCT FROM NEW.requested_by_user_id
      OR NOT (
        public.automation_user_has_permission(NEW.tenant_id,actor_id,'wms_supervisor')
        OR (NEW.device_class='scale'
          AND NEW.command_payload->'command'->>'operation'='read_stable_weight'
          AND NEW.packing_session_id IS NOT NULL
          AND public.automation_user_has_permission(NEW.tenant_id,actor_id,'wms')))
      OR NOT public.automation_interactive_user_scoped(
        NEW.tenant_id,actor_id,NEW.facility_id)
      OR device.control_mode<>'automatic' OR device.health NOT IN ('healthy','degraded')
      OR device.last_heartbeat_at<CURRENT_TIMESTAMP-INTERVAL '2 minutes'
      OR NOT EXISTS(SELECT 1 FROM public.automation_heartbeats heartbeat
        WHERE heartbeat.tenant_id=NEW.tenant_id
          AND heartbeat.device_id=NEW.device_id
          AND heartbeat.observed_at=device.last_heartbeat_at
          AND heartbeat.control_mode='automatic')
      OR EXISTS(SELECT 1 FROM public.automation_commands held
        WHERE held.tenant_id=NEW.tenant_id AND held.device_id=NEW.device_id
          AND held.status='manual_review')
      OR (NEW.packing_session_id IS NOT NULL AND NOT EXISTS(
        SELECT 1 FROM public.cartons carton
        JOIN public.packing_sessions session
          ON session.tenant_id=carton.tenant_id
         AND session.inventory_owner_id=carton.inventory_owner_id
         AND session.facility_id=carton.facility_id
         AND session.id=carton.packing_session_id
        WHERE carton.tenant_id=NEW.tenant_id
          AND carton.inventory_owner_id=NEW.packing_inventory_owner_id
          AND carton.facility_id=NEW.facility_id
          AND carton.packing_session_id=NEW.packing_session_id
          AND carton.id=NEW.packing_carton_id
          AND carton.reopen_count=NEW.packing_carton_reopen_count
          AND carton.state='open' AND session.state='open')) THEN
      RAISE EXCEPTION 'invalid automation command enqueue' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(NEW.id,NEW.tenant_id,NEW.facility_id,NEW.device_id,NEW.device_class,
      NEW.correlation_id,NEW.recovery_policy,NEW.command_payload,
      NEW.packing_inventory_owner_id,NEW.packing_session_id,
      NEW.packing_carton_id,NEW.packing_carton_reopen_count,
      NEW.requested_by_user_id,NEW.requested_at) IS DISTINCT FROM
    ROW(OLD.id,OLD.tenant_id,OLD.facility_id,OLD.device_id,OLD.device_class,
      OLD.correlation_id,OLD.recovery_policy,OLD.command_payload,
      OLD.packing_inventory_owner_id,OLD.packing_session_id,
      OLD.packing_carton_id,OLD.packing_carton_reopen_count,
      OLD.requested_by_user_id,OLD.requested_at) THEN
    RAISE EXCEPTION 'automation command envelope is immutable' USING ERRCODE='55000';
  END IF;
  IF OLD.status='manual_review' AND NEW.status='resolved_manually' THEN
    IF NEW.revision<>OLD.revision+1
      OR actor_id IS DISTINCT FROM NEW.resolved_by_user_id
      OR NEW.resolved_at NOT BETWEEN CURRENT_TIMESTAMP-INTERVAL '1 minute'
        AND CURRENT_TIMESTAMP+INTERVAL '1 minute'
      OR ROW(NEW.delivery_attempts,NEW.assigned_service_account_id,
          NEW.agent_instance,NEW.delivery_token,NEW.delivered_at,
          NEW.delivery_expires_at,NEW.accepted_at,NEW.completed_at,
          NEW.result_payload,NEW.error_code,NEW.error_message) IS DISTINCT FROM
        ROW(OLD.delivery_attempts,OLD.assigned_service_account_id,
          OLD.agent_instance,OLD.delivery_token,OLD.delivered_at,
          OLD.delivery_expires_at,OLD.accepted_at,OLD.completed_at,
          OLD.result_payload,OLD.error_code,OLD.error_message)
      OR NOT public.automation_user_has_permission(
        NEW.tenant_id,actor_id,'wms_supervisor')
      OR NOT public.automation_interactive_user_scoped(
        NEW.tenant_id,actor_id,NEW.facility_id) THEN
      RAISE EXCEPTION 'invalid automation manual resolution' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  edge_account_id:=public.automation_edge_service_account(
    NEW.tenant_id,actor_id,NEW.facility_id);
  IF edge_account_id IS NULL OR NEW.revision<>OLD.revision+1
    OR NEW.assigned_service_account_id IS DISTINCT FROM edge_account_id
    OR NOT (
      (OLD.status IN ('queued','delivered') AND NEW.status='delivered'
        AND NEW.delivery_attempts=OLD.delivery_attempts+1
        AND EXISTS(SELECT 1 FROM public.automation_heartbeats heartbeat
          WHERE heartbeat.tenant_id=NEW.tenant_id
            AND heartbeat.device_id=NEW.device_id
            AND heartbeat.service_account_id=edge_account_id
            AND heartbeat.agent_instance=NEW.agent_instance
            AND heartbeat.control_mode='automatic'
            AND heartbeat.id=(SELECT max(latest.id)
              FROM public.automation_heartbeats latest
              WHERE latest.tenant_id=heartbeat.tenant_id
                AND latest.device_id=heartbeat.device_id))
        AND NOT EXISTS(SELECT 1 FROM public.automation_commands held
          WHERE held.tenant_id=NEW.tenant_id AND held.device_id=NEW.device_id
            AND held.status='manual_review')
        AND (OLD.assigned_service_account_id IS NULL
          OR OLD.assigned_service_account_id=NEW.assigned_service_account_id)
        AND NEW.accepted_at IS NULL AND NEW.completed_at IS NULL)
      OR (OLD.status='delivered' AND NEW.status='accepted'
        AND NEW.delivery_attempts=OLD.delivery_attempts
        AND NOT EXISTS(SELECT 1 FROM public.automation_commands held
          WHERE held.tenant_id=NEW.tenant_id AND held.device_id=NEW.device_id
            AND held.status='manual_review')
        AND NEW.assigned_service_account_id=OLD.assigned_service_account_id
        AND NEW.agent_instance=OLD.agent_instance
        AND NEW.delivery_token=OLD.delivery_token
        AND NEW.delivered_at=OLD.delivered_at AND NEW.accepted_at IS NOT NULL)
      OR (OLD.status='accepted' AND NEW.status IN ('succeeded','failed','manual_review')
        AND NEW.delivery_attempts=OLD.delivery_attempts
        AND NEW.assigned_service_account_id=OLD.assigned_service_account_id
        AND NEW.agent_instance=OLD.agent_instance
        AND NEW.delivery_token=OLD.delivery_token
        AND NEW.delivered_at=OLD.delivered_at AND NEW.accepted_at=OLD.accepted_at
        AND NEW.completed_at IS NOT NULL)) THEN
    RAISE EXCEPTION 'invalid automation command transition' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.validate_automation_command_event() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE actor_id bigint:=NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint;
DECLARE command public.automation_commands%ROWTYPE;
BEGIN
  IF TG_OP<>'INSERT' THEN
    RAISE EXCEPTION 'automation command events are immutable' USING ERRCODE='55000';
  END IF;
  SELECT * INTO command FROM public.automation_commands candidate
  WHERE candidate.tenant_id=NEW.tenant_id AND candidate.id=NEW.command_id;
  IF command.id IS NULL OR actor_id IS DISTINCT FROM NEW.actor_user_id
    OR command.status<>NEW.transition THEN
    RAISE EXCEPTION 'invalid automation command event' USING ERRCODE='23514';
  END IF;
  IF NEW.transition='resolved_manually' THEN
    IF NEW.service_account_id IS NOT NULL
      OR command.resolved_by_user_id IS DISTINCT FROM actor_id
      OR NOT public.automation_user_has_permission(
        NEW.tenant_id,actor_id,'wms_supervisor')
      OR NOT public.automation_interactive_user_scoped(
        NEW.tenant_id,actor_id,command.facility_id) THEN
      RAISE EXCEPTION 'invalid automation command resolution event' USING ERRCODE='23514';
    END IF;
  ELSIF command.assigned_service_account_id IS DISTINCT FROM NEW.service_account_id
    OR public.automation_edge_service_account(
      NEW.tenant_id,actor_id,command.facility_id) IS DISTINCT FROM NEW.service_account_id THEN
    RAISE EXCEPTION 'invalid automation edge command event' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.validate_automation_heartbeat() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $$
DECLARE actor_id bigint:=NULLIF(current_setting('wareboxes.actor_user_id',true),'')::bigint;
DECLARE device public.automation_devices%ROWTYPE;
BEGIN
  IF TG_OP<>'INSERT' THEN
    RAISE EXCEPTION 'automation heartbeats are immutable' USING ERRCODE='55000';
  END IF;
  SELECT * INTO device FROM public.automation_devices candidate
  WHERE candidate.tenant_id=NEW.tenant_id AND candidate.id=NEW.device_id FOR SHARE;
  IF device.id IS NULL OR device.facility_id<>NEW.facility_id
    OR (device.last_heartbeat_at IS NOT NULL
      AND NEW.observed_at<=device.last_heartbeat_at)
    OR public.automation_edge_service_account(
      NEW.tenant_id,actor_id,NEW.facility_id) IS DISTINCT FROM NEW.service_account_id
    OR NEW.received_at<>transaction_timestamp() THEN
    RAISE EXCEPTION 'invalid automation heartbeat' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER automation_devices_guard BEFORE INSERT OR UPDATE OR DELETE
ON public.automation_devices FOR EACH ROW EXECUTE FUNCTION public.validate_automation_device();
CREATE TRIGGER automation_commands_guard BEFORE INSERT OR UPDATE OR DELETE
ON public.automation_commands FOR EACH ROW EXECUTE FUNCTION public.validate_automation_command();
CREATE TRIGGER automation_command_events_guard BEFORE INSERT OR UPDATE OR DELETE
ON public.automation_command_events FOR EACH ROW
EXECUTE FUNCTION public.validate_automation_command_event();
CREATE TRIGGER automation_heartbeats_guard BEFORE INSERT OR UPDATE OR DELETE
ON public.automation_heartbeats FOR EACH ROW
EXECUTE FUNCTION public.validate_automation_heartbeat();

